def get_connection(db_path: str | Path | None = None) -> sqlite3.Connection:
    path = str(db_path or DB_PATH)
    # Ensure parent directory exists (Railway persistent volume may need creation)
    Path(path).parent.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    conn.execute("PRAGMA journal_mode=WAL")
    return conn


@contextmanager
def managed_connection(db_path: str | Path | None = None):
    """Context manager that guarantees connection is closed even on exceptions."""
    conn = get_connection(db_path)
    try:
        yield conn
    finally:
        conn.close()


# Alias so both names work (feature code uses _connect, audit code uses managed_connection)
_connect = managed_connection


def _migrate_eliminate_tgf_golfers(conn: sqlite3.Connection) -> None:
    """Migrate tgf_payouts.golfer_id → tgf_payouts.customer_id, then drop tgf_golfers.

    Runs inside init_db(). Idempotent — skips if tgf_golfers is already dropped.

    For each existing payout:
      1. Resolve the golfer's name to a customer_id via _lookup_customer_id.
      2. If no match, create a new customer from the golfer record (first+last name,
         carrying venmo_username and chapter).
      3. Backfill tgf_payouts.customer_id.

    Then rebuilds tgf_payouts without the golfer_id column and drops tgf_golfers.
    """
    golfers_exists = conn.execute(
        "SELECT name FROM sqlite_master WHERE type='table' AND name='tgf_golfers'"
    ).fetchone()
    if not golfers_exists:
        return  # Already migrated

    logger.info("Starting tgf_golfers elimination migration")

    # Step 1: Add customer_id column to tgf_payouts if not present
    cols = [r[1] for r in conn.execute("PRAGMA table_info(tgf_payouts)").fetchall()]
    if "customer_id" not in cols:
        conn.execute("ALTER TABLE tgf_payouts ADD COLUMN customer_id INTEGER")
        logger.info("Added customer_id column to tgf_payouts")

    # Step 2: Backfill customer_id by resolving each distinct golfer name
    # Build a golfer_id → customer_id map
    golfer_rows = conn.execute(
        "SELECT id, name, venmo_username, chapter FROM tgf_golfers"
    ).fetchall()

    golfer_to_customer: dict[int, int] = {}
    for g in golfer_rows:
        name = (g["name"] or "").strip()
        if not name:
            continue

        # Try to resolve to existing customer (by name + alias cascade)
        cid = _lookup_customer_id(conn, name, None)

        if cid is None:
            # No existing customer — create one from the golfer record
            parts = name.split()
            if len(parts) >= 2:
                first = parts[0]
                last = " ".join(parts[1:])
            else:
                first = name
                last = "(Unknown)"
            try:
                cur = conn.execute(
                    """INSERT INTO customers
                           (first_name, last_name, chapter, venmo_username,
                            account_status, acquisition_source)
                       VALUES (?, ?, ?, ?, 'active', 'tgf_payout_migration')""",
                    (first, last, g["chapter"] or None, g["venmo_username"] or None),
                )
                cid = cur.lastrowid
                logger.info("Created customer %d for former golfer '%s'", cid, name)
            except Exception as exc:
                logger.warning("Failed to create customer for golfer '%s': %s", name, exc)
                continue
        else:
            # Backfill venmo_username/chapter onto existing customer if missing
            if g["venmo_username"]:
                conn.execute(
                    """UPDATE customers SET venmo_username = ?
                       WHERE customer_id = ?
                         AND (venmo_username IS NULL OR venmo_username = '')""",
                    (g["venmo_username"], cid),
                )
            if g["chapter"]:
                conn.execute(
                    """UPDATE customers SET chapter = ?
                       WHERE customer_id = ?
                         AND (chapter IS NULL OR chapter = '')""",
                    (g["chapter"], cid),
                )

        golfer_to_customer[g["id"]] = cid

    # Apply the mapping to payouts
    for golfer_id, customer_id in golfer_to_customer.items():
        conn.execute(
            "UPDATE tgf_payouts SET customer_id = ? WHERE golfer_id = ? AND customer_id IS NULL",
            (customer_id, golfer_id),
        )

    # Step 3: Verify all payouts have customer_id set before dropping golfer linkage
    unmapped = conn.execute(
        "SELECT COUNT(*) as cnt FROM tgf_payouts WHERE customer_id IS NULL"
    ).fetchone()["cnt"]
    if unmapped > 0:
        logger.warning(
            "Aborting tgf_golfers drop — %d payouts still have NULL customer_id",
            unmapped,
        )
        conn.commit()
        return

    # Step 4: Rebuild tgf_payouts with clean schema (remove golfer_id column).
    # SQLite can't drop a column directly in older versions, so use table rebuild.
    conn.execute("PRAGMA foreign_keys = OFF")
    conn.execute(
        """
        CREATE TABLE tgf_payouts_new (
            id              INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id        INTEGER NOT NULL REFERENCES tgf_events(id) ON DELETE CASCADE,
            customer_id     INTEGER NOT NULL REFERENCES customers(customer_id),
            category        TEXT NOT NULL,
            amount          REAL NOT NULL,
            description     TEXT,
            created_at      TEXT DEFAULT (datetime('now'))
        )
        """
    )
    conn.execute(
        """INSERT INTO tgf_payouts_new
               (id, event_id, customer_id, category, amount, description, created_at)
           SELECT id, event_id, customer_id, category, amount, description, created_at
           FROM tgf_payouts"""
    )
    conn.execute("DROP TABLE tgf_payouts")
    conn.execute("ALTER TABLE tgf_payouts_new RENAME TO tgf_payouts")
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_tgf_payouts_event ON tgf_payouts(event_id)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_tgf_payouts_customer ON tgf_payouts(customer_id)"
    )

    # Step 5: Drop tgf_golfers
    conn.execute("DROP TABLE tgf_golfers")
    conn.execute("PRAGMA foreign_keys = ON")
    conn.commit()

    logger.info(
        "tgf_golfers eliminated — migrated %d golfers to customers, dropped tgf_golfers table",
        len(golfer_to_customer),
    )


def _migrate_dedupe_payout_customers(conn: sqlite3.Connection) -> None:
    """One-time cleanup: merge duplicate customers created by tgf_golfers migration.

    The migration stored "LAST, First" names from payout screenshots as
    separate customers instead of matching them to existing "First Last"
    records.  This function merges the confirmed duplicates.

    Idempotent — skips if no acquisition_source='tgf_payout_migration'
    customers remain.
    """
    remaining = conn.execute(
        "SELECT COUNT(*) as c FROM customers WHERE acquisition_source = 'tgf_payout_migration'"
    ).fetchone()["c"]
    if remaining == 0:
        return  # Already cleaned up

    logger.info("Starting payout customer dedup — %d migration customers to process", remaining)

    # Approved merge map: migrated_customer_id → target_customer_id
    # User-confirmed matches from the dedup audit
    MERGE_MAP = {
        363: 296,   # Roland Campos → Rolando Campos
        364: 14,    # MARQUES, Mike → Mike Marques
        365: 15,    # REED, Paul → Paul Reed
        366: 31,    # STRATON, Robert → Robert Straiton (typo)
        367: 29,    # MOORE, Dion → Dion Moore
        368: 37,    # HOGUE, Jay → Jay Hogue
        369: 302,   # Moore, Hunter → Hunter Moore
        370: 39,    # BARNA, Kelly → Kelly Barna
        371: 312,   # GAGE, Erica → Erica Gage
        372: 294,   # JENKINS, Mike → Mike Jenkins
        373: 239,   # COTTRILL, Matt → Matt Cottrill
        374: 299,   # FREUND, Mark → Mark Freund
        375: 236,   # CEDILLO, David → David Cedillo
        376: 296,   # CAMPOS, Roland → Rolando Campos (same target as 363)
        377: 136,   # YOUNGS, Pat → Pat Youngs
        378: 46,    # McCRARY, Justin → Justin McCrary (canonical)
        379: 3,     # WOLIN, Allen → Allen Wolin
        380: 320,   # AGUILERA, Hector → Hector Aguilera
        381: 38,    # SHARITZ, Don → Don Sharitz
        382: 24,    # SOUTH, Daniel → Daniel South
        383: 219,   # ATKINSON, Bob → Bob Atkinson
        384: 325,   # CHALFANT, Tanner → Tanner Chalfant
        385: 31,    # STRAITON, Robert → Robert Straiton (same target as 366)
        386: 61,    # MELCHOR, Eduardo → Eduardo Melchor
        387: 30,    # SHARP, Matt → Matt Sharp
        388: 116,   # COLASANTO, Adam → Adam Colasanto
        389: 109,   # CLOER, Neal → Neal Cloer
        390: 16,    # SARRIA, Al → Al Sarria
        391: 22,    # GARTZ, Joshua → Joshua Bartz (typo in screenshot)
    }

    # Pre-existing duplicates to also clean up
    PRE_EXISTING_MERGES = {
        11: 312,    # Erica Cage (typo) → Erica Gage
        317: 46,    # Justin McCrary (wrong Venmo) → canonical Justin McCrary
        324: 46,    # Justin McCrary (third dup) → canonical Justin McCrary
    }

    merged = 0
    for source_cid, target_cid in {**MERGE_MAP, **PRE_EXISTING_MERGES}.items():
        # Verify source still exists (idempotent)
        source = conn.execute(
            "SELECT customer_id FROM customers WHERE customer_id = ?", (source_cid,)
        ).fetchone()
        if not source:
            continue  # Already merged in a previous run

        target = conn.execute(
            "SELECT customer_id FROM customers WHERE customer_id = ?", (target_cid,)
        ).fetchone()
        if not target:
            logger.warning("Merge target customer_id=%d not found — skipping source %d",
                           target_cid, source_cid)
            continue

        # Reassign tgf_payouts
        conn.execute(
            "UPDATE tgf_payouts SET customer_id = ? WHERE customer_id = ?",
            (target_cid, source_cid),
        )

        # Reassign items (if any)
        conn.execute(
            "UPDATE items SET customer_id = ? WHERE customer_id = ?",
            (target_cid, source_cid),
        )

        # Move emails (skip dupes)
        src_emails = conn.execute(
            "SELECT email FROM customer_emails WHERE customer_id = ?", (source_cid,)
        ).fetchall()
        for e in src_emails:
            try:
                conn.execute(
                    "INSERT OR IGNORE INTO customer_emails (customer_id, email, label) VALUES (?, ?, 'merged')",
                    (target_cid, e["email"]),
                )
            except Exception:
                pass
        conn.execute("DELETE FROM customer_emails WHERE customer_id = ?", (source_cid,))

        # Delete the orphaned source customer
        conn.execute("DELETE FROM customers WHERE customer_id = ?", (source_cid,))
        merged += 1

    # Fix wrong Venmo on customer 317 target → customer 46 should NOT inherit tchalfant
    conn.execute(
        """UPDATE customers SET venmo_username = NULL
           WHERE customer_id = 46
             AND venmo_username = 'tchalfant'""",
    )

    conn.commit()
    logger.info("Payout customer dedup complete — merged %d duplicate customers", merged)


def _repair_chalfant_attribution(conn: sqlite3.Connection) -> None:
    """Re-attribute Tanner Chalfant's orders that were corrupted by a bad customer merge.

    Customer 317 (a duplicate Justin McCrary record) had Chalfant's email/Venmo.
    When merged into customer 46 (canonical McCrary), those values contaminated
    McCrary's customer_emails. The identity-drift guard in save_items() then
    assigned all new Chalfant orders to customer_id=46 (McCrary) and overwrote
    their email/phone with McCrary's canonical values.

    This function is called directly from init_db() every boot and is fully
    idempotent — all UPDATEs are no-ops once items.customer_id is already 325.
    """
    _CHALFANT_EMAIL = 'tchalfant@sconservices.com'
    _CHALFANT_PHONE = '(432) 661-9022'
    _CHALFANT_CID = 325
    _MCCRARY_CID = 46
    _MCCRARY_EMAIL = 'justinmccrary@elliottelectric.com'
    _MCCRARY_PHONE = '(210) 882-2755'

    # 1. Remove Chalfant's email from McCrary's customer_emails (bad merge artifact)
    removed_email = conn.execute(
        "DELETE FROM customer_emails WHERE customer_id = ? AND LOWER(email) = LOWER(?)",
        (_MCCRARY_CID, _CHALFANT_EMAIL),
    ).rowcount
    if removed_email:
        logger.info("Chalfant repair: removed %s from McCrary customer_emails", _CHALFANT_EMAIL)

    # 2. Ensure Chalfant's email is on his own record as the primary.
    #    INSERT with is_primary=0 first to avoid the unique partial-index violation
    #    when another primary already exists, then explicitly promote it.
    conn.execute(
        """INSERT OR IGNORE INTO customer_emails (customer_id, email, is_primary, label)
           SELECT ?, ?, 0, 'repaired'
           WHERE EXISTS (SELECT 1 FROM customers WHERE customer_id = ?)""",
        (_CHALFANT_CID, _CHALFANT_EMAIL, _CHALFANT_CID),
    )
    conn.execute(
        """UPDATE customer_emails SET is_primary = 0
           WHERE customer_id = ? AND LOWER(email) != LOWER(?) AND is_primary = 1""",
        (_CHALFANT_CID, _CHALFANT_EMAIL),
    )
    conn.execute(
        "UPDATE customer_emails SET is_primary = 1 WHERE customer_id = ? AND LOWER(email) = LOWER(?)",
        (_CHALFANT_CID, _CHALFANT_EMAIL),
    )

    # 3. Fix Chalfant's phone on the customers record so heal_items_from_customers
    #    applies the correct value after we set customer_id=325 on items below.
    conn.execute(
        """UPDATE customers SET phone = ?
           WHERE customer_id = ?
             AND (phone IS NULL OR TRIM(phone) = '' OR phone = ?)""",
        (_CHALFANT_PHONE, _CHALFANT_CID, _MCCRARY_PHONE),
    )

    # 4. Fix corrupted items rows.  Four overlapping cases ensure full coverage
    #    regardless of which fields were overwritten by the drift guard or heal.

    # (a) Known order R222413986 (confirmed from Audit Log raw email body).
    #     Skip rows that are already fully correct — without the guard this
    #     matched (and "re-attributed") the same healthy row on every boot,
    #     making the log claim work that never happened.
    fixed_a = conn.execute(
        """UPDATE items
           SET customer = 'Tanner Chalfant', customer_id = ?, customer_email = ?,
               customer_phone = CASE WHEN customer_phone = ? THEN ? ELSE customer_phone END
           WHERE order_id IN ('R222413986', '#R222413986', 'R-222413986', '222413986')
             AND (customer_id IS NOT ?
                  OR customer != 'Tanner Chalfant'
                  OR LOWER(COALESCE(customer_email, '')) != LOWER(?))""",
        (_CHALFANT_CID, _CHALFANT_EMAIL, _MCCRARY_PHONE, _CHALFANT_PHONE,
         _CHALFANT_CID, _CHALFANT_EMAIL),
    ).rowcount

    # (b) Items with Chalfant's email still under McCrary's customer_id
    fixed_b = conn.execute(
        """UPDATE items
           SET customer = 'Tanner Chalfant', customer_id = ?,
               customer_phone = CASE WHEN customer_phone = ? THEN ? ELSE customer_phone END
           WHERE customer_id = ? AND LOWER(customer_email) = LOWER(?)""",
        (_CHALFANT_CID, _MCCRARY_PHONE, _CHALFANT_PHONE, _MCCRARY_CID, _CHALFANT_EMAIL),
    ).rowcount

    # (c) Items named 'Tanner Chalfant' but carrying McCrary's email
    fixed_c = conn.execute(
        """UPDATE items
           SET customer_email = ?, customer_id = ?,
               customer_phone = CASE WHEN customer_phone = ? THEN ? ELSE customer_phone END
           WHERE customer = 'Tanner Chalfant' AND LOWER(customer_email) = LOWER(?)""",
        (_CHALFANT_EMAIL, _CHALFANT_CID, _MCCRARY_PHONE, _CHALFANT_PHONE, _MCCRARY_EMAIL),
    ).rowcount

    # (d) Bridge via parse_warnings: EMAIL_DRIFT/PHONE_DRIFT rows store the pre-override
    #     customer name ('Tanner Chalfant') and order_id/email_uid that link back to items
    #     even after items.customer/email were fully overwritten to McCrary's canonical values.
    fixed_d = conn.execute(
        """UPDATE items
           SET customer = 'Tanner Chalfant', customer_id = ?, customer_email = ?,
               customer_phone = CASE WHEN customer_phone = ? THEN ? ELSE customer_phone END
           WHERE customer_id = ?
             AND (
                 (order_id IS NOT NULL AND order_id IN (
                     SELECT DISTINCT order_id FROM parse_warnings
                     WHERE LOWER(customer) = 'tanner chalfant'
                       AND warning_code IN ('EMAIL_DRIFT', 'PHONE_DRIFT')
                       AND order_id IS NOT NULL
                 ))
                 OR
                 (email_uid IS NOT NULL AND email_uid IN (
                     SELECT DISTINCT email_uid FROM parse_warnings
                     WHERE LOWER(customer) = 'tanner chalfant'
                       AND warning_code IN ('EMAIL_DRIFT', 'PHONE_DRIFT')
                       AND email_uid IS NOT NULL
                 ))
             )""",
        (_CHALFANT_CID, _CHALFANT_EMAIL, _MCCRARY_PHONE, _CHALFANT_PHONE, _MCCRARY_CID),
    ).rowcount

    # (e) Items under McCrary with Chalfant's Midland TX zip (79707).
    #     city/state/zip are captured from the order email and NOT overwritten by
    #     the identity-drift guard or heal_items_from_customers, so they survive
    #     even when customer/email/phone have been fully replaced by canonical values.
    #     zip 79707 is specific to Midland TX — McCrary has no legitimate orders there.
    fixed_e = conn.execute(
        """UPDATE items
           SET customer = 'Tanner Chalfant', customer_id = ?, customer_email = ?,
               customer_phone = CASE WHEN customer_phone = ? THEN ? ELSE customer_phone END
           WHERE customer_id = ? AND COALESCE(TRIM(zip), '') = '79707'""",
        (_CHALFANT_CID, _CHALFANT_EMAIL, _MCCRARY_PHONE, _CHALFANT_PHONE, _MCCRARY_CID),
    ).rowcount

    # (f) Guest-swapped items: _do_guest_swap sets customer='Tanner Chalfant' but also
    #     clears email/phone/zip, so cases b/c/e can't match. If customer_id is still
    #     McCrary's (e.g. name lookup fell back to the buyer's cid), fix it here.
    #     Don't overwrite customer_email — it was intentionally cleared (guest slot);
    #     heal_items_from_customers will populate Chalfant's canonical email afterward.
    # (f) Guest items: McCrary bought for Chalfant — find via partner_request on McCrary's
    #     companion rows; companion guest items have notes='Purchased by Justin McCrary'
    #     but customer may not be 'Tanner Chalfant', so we bridge via order_id.
    fixed_f = conn.execute(
        """UPDATE items
           SET customer = 'Tanner Chalfant', customer_id = ?, customer_email = ?
           WHERE customer_id = ?
             AND order_id IN (
                 SELECT DISTINCT order_id FROM items
                 WHERE customer_id = ?
                   AND LOWER(COALESCE(partner_request, '')) LIKE '%chalfant%'
             )
             AND LOWER(COALESCE(notes, '')) LIKE '%purchased by justin mccrary%'""",
        (_CHALFANT_CID, _CHALFANT_EMAIL, _MCCRARY_CID, _MCCRARY_CID),
    ).rowcount

    total_fixed = fixed_a + fixed_b + fixed_c + fixed_d + fixed_e + fixed_f

    # Fix saved pairings: rename 18-hole 'Justin McCrary' → 'Tanner Chalfant'
    # in events where Chalfant has an 18-hole registration but McCrary does not.
    fixed_pairings = conn.execute("""
        UPDATE event_pairings
        SET player_name = 'Tanner Chalfant'
        WHERE player_name = 'Justin McCrary'
          AND holes = '18'
          AND event_id IN (
              SELECT DISTINCT e.id FROM events e
              JOIN items i ON (i.item_name = e.item_name COLLATE NOCASE OR i.event_id = e.id)
              WHERE i.customer_id = ?
                AND i.holes = '18'
                AND COALESCE(i.transaction_status,'active') = 'active'
          )
          AND event_id NOT IN (
              SELECT DISTINCT e.id FROM events e
              JOIN items i ON (i.item_name = e.item_name COLLATE NOCASE OR i.event_id = e.id)
              WHERE i.customer_id = ?
                AND i.holes = '18'
                AND COALESCE(i.transaction_status,'active') = 'active'
          )
    """, (_CHALFANT_CID, _MCCRARY_CID)).rowcount
    if fixed_pairings:
        logger.info("Chalfant repair: renamed %d saved pairing row(s) from McCrary to Chalfant",
                    fixed_pairings)

    if total_fixed:
        logger.info(
            "Chalfant repair: re-attributed %d item(s) to customer %d "
            "(a=%d b=%d c=%d d=%d e=%d f=%d)",
            total_fixed, _CHALFANT_CID, fixed_a, fixed_b, fixed_c, fixed_d, fixed_e, fixed_f,
        )
        conn.execute(
            """UPDATE parse_warnings SET status = 'resolved'
               WHERE LOWER(customer) = 'tanner chalfant'
                 AND warning_code IN ('EMAIL_DRIFT', 'PHONE_DRIFT') AND status = 'open'""",
        )
        conn.execute(
            """UPDATE action_items
               SET status = 'dismissed',
                   resolution_notes = 'Auto-fixed: re-attributed to Tanner Chalfant (cid 325)'
               WHERE LOWER(from_name) = 'tanner chalfant' AND status IN ('open', 'in_progress')""",
        )
    conn.commit()


def _repair_crystal_falls_twin_event(conn: sqlite3.Connection) -> None:
    """Kerry (2026-07-14): events 3267 ('a18.2 CRYSTAL FALLS') and 3263
    ('a18.3 CRYSTAL FALLS') are the SAME May 30 Austin event — the code/
    name changed mid-registration and both rows kept collecting rows.
    GG's coding wins (a18.2 = AUSTIN KICKOFF | ShadowGlen, a18.3 =
    CRYSTAL FALLS). Idempotent: no-ops once 3267 is gone.

    Stale pairing rows on the twin are DELETED (the keeper already has
    the tee-sheet-sourced truth); every other event_id reference moves
    to the keeper; the old product name becomes an event alias so
    name-joined items/RSVPs keep resolving."""
    dup = conn.execute(
        "SELECT id FROM events WHERE id = 3267 "
        "AND item_name = 'a18.2 CRYSTAL FALLS'").fetchone()
    keep = conn.execute(
        "SELECT id FROM events WHERE id = 3263 "
        "AND item_name = 'a18.3 CRYSTAL FALLS'").fetchone()
    if not dup or not keep:
        return
    conn.execute("DELETE FROM pairing_history WHERE event_id = 3267")
    conn.execute("DELETE FROM event_pairings WHERE event_id = 3267")
    moved = {}
    tables = [r[0] for r in conn.execute(
        "SELECT name FROM sqlite_master WHERE type = 'table' "
        "AND name NOT IN ('events', 'pairing_history', 'event_pairings')")]
    for t in tables:
        try:
            cols = [c[1] for c in conn.execute(f"PRAGMA table_info({t})")]
            if "event_id" not in cols:
                continue
            cur = conn.execute(
                f"UPDATE {t} SET event_id = 3263 WHERE event_id = 3267")
            if cur.rowcount:
                moved[t] = cur.rowcount
        except sqlite3.Error as e:
            logger.warning("Crystal Falls merge: %s not moved: %s", t, e)
    conn.execute(
        "INSERT OR IGNORE INTO event_aliases (alias_name, canonical_event_name) "
        "VALUES ('a18.2 CRYSTAL FALLS', 'a18.3 CRYSTAL FALLS')")
    conn.execute("DELETE FROM events WHERE id = 3267")
    conn.commit()
    logger.info("Crystal Falls twin-event merge: 3267 -> 3263, moved %s", moved)


# Pace-of-play ratings, Kerry-ratified 2026-07-14 (scale: 1 slowest → 3
# fastest). Derived from SA shotgun/sequential staging history, then
# adjusted by Kerry: Parch/Miller/Dealy stay unrated (= default 2),
# Ellis flipped to 3, Dyal/Newman promoted to 3, DelCarmen 1. Austin
# members stay at the default 2 except Hogue/Cloer/Straiton (Robert
# will adjust his chapter later). Both Victor Ariases ride together and
# stage together, so both carry the 1. Anyone not listed reads as 2.
_PACE_RATING_SEED = {
    3: ["Jeff Young", "John White", "Chuck Fehlis", "Fred Wicker",
        "Steve Kulawik", "Pat Youngs", "Gus Vasquez", "Rob Callaway",
        "Gilbert Ellis", "Mark Dyal", "Tom Newman", "Kerry Niester",
        "Jay Hogue", "Neal Cloer", "Robert Straiton"],
    1: ["Richard Palacios", "Larry Anthis", "Allen Wolin",
        # Both Victor Ariases store first+last as plain 'Victor Arias'
        # (III/Jr live outside first_name/last_name) — one entry
        # matches BOTH rows, which is intended: they ride/stage
        # together, so both carry the 1.
        "Victor Arias", "Roberto Moreno",
        "Michael Murphy", "Michelle Delcarmen"],
}


def _seed_pace_ratings(conn: sqlite3.Connection) -> None:
    """Seed customers.pace_rating with Kerry's ratified initial values.

    Fill-only-if-NULL: a manager edit (any non-NULL value) always wins,
    so re-running on every boot never stomps a later adjustment — even
    an adjustment back to a value that differs from this seed. NULL is
    read as 2 everywhere (Kerry: "Anyone else that isn't marked/
    discussed, gets a 2 in the system until further notice"), so only
    the 1s and 3s need rows here. pace_rating_source records provenance
    ('manager' for ratified/manual values; 'derived'/'gps' reserved for
    future automated sources). Pace NEVER affects pairing composition —
    staging only."""
    for ddl in (
        "ALTER TABLE customers ADD COLUMN pace_rating INTEGER",
        "ALTER TABLE customers ADD COLUMN pace_rating_source TEXT",
    ):
        try:
            conn.execute(ddl)
        except sqlite3.OperationalError:
            pass  # column already exists
    seeded = 0
    for rating, names in _PACE_RATING_SEED.items():
        for name in names:
            cur = conn.execute(
                """UPDATE customers
                   SET pace_rating = ?, pace_rating_source = 'manager'
                   WHERE LOWER(TRIM(first_name || ' ' || last_name))
                         = LOWER(?)
                     AND pace_rating IS NULL""",
                (rating, name))
            seeded += cur.rowcount
    conn.commit()
    if seeded:
        logger.info("Pace ratings seed: applied %d rating(s)", seeded)


def _repair_massey_attribution(conn: sqlite3.Connection) -> None:
    """Re-attribute William Massey's orders corrupted by a bad customer merge.

    Massey's email (wncmassey@outlook.com) ended up on a duplicate Colby Johnson
    record which was merged into canonical Johnson, pulling Massey's orders in
    under Johnson's customer_id.

    Known Massey orders now showing under Johnson:
      R545206118 — TGF Membership + a9.3 Avery Ranch (Massey's own order)
      R112804515 — a9.5 Star Ranch (Massey's own order)
      R278736131 — Austin Kickoff companion item (Johnson bought 2 spots; one is Massey's)

    Fully idempotent — all UPDATEs are no-ops once customer_id is already Massey's.
    """
    _MASSEY_EMAIL = 'wncmassey@outlook.com'
    _MASSEY_NAME = 'William Massey'
    _MASSEY_PHONE = '(678) 314-8527'
    _JOHNSON_EMAIL = 'colbygjohnson8@gmail.com'

    # Find canonical Johnson customer_id via customer_emails table
    johnson_row = conn.execute(
        """SELECT customer_id FROM customer_emails
           WHERE LOWER(email) = LOWER(?)
           LIMIT 1""",
        (_JOHNSON_EMAIL,),
    ).fetchone()
    if not johnson_row:
        logger.warning("Massey repair: could not find Colby Johnson customer record — skipping")
        return
    johnson_cid = johnson_row["customer_id"]

    # 1. Remove Massey's email from Johnson's customer_emails (bad merge artifact)
    removed = conn.execute(
        "DELETE FROM customer_emails WHERE customer_id = ? AND LOWER(email) = LOWER(?)",
        (johnson_cid, _MASSEY_EMAIL),
    ).rowcount
    if removed:
        logger.info("Massey repair: removed %s from Johnson customer_emails", _MASSEY_EMAIL)

    # 2. Find or create Massey's own customer record
    massey_row = conn.execute(
        """SELECT customer_id FROM customer_emails
           WHERE LOWER(email) = LOWER(?)
           LIMIT 1""",
        (_MASSEY_EMAIL,),
    ).fetchone()
    if massey_row:
        massey_cid = massey_row["customer_id"]
    else:
        cur = conn.execute(
            """INSERT INTO customers
                   (first_name, last_name, phone, chapter, account_status,
                    acquisition_source)
               VALUES (?, ?, ?, 'Austin', 'active', 'repair')""",
            ('William', 'Massey', _MASSEY_PHONE),
        )
        massey_cid = cur.lastrowid
        logger.info("Massey repair: created customer record cid=%d", massey_cid)

    # 3. Ensure Massey's email is on his own record as primary
    conn.execute(
        """INSERT OR IGNORE INTO customer_emails (customer_id, email, is_primary)
           VALUES (?, ?, 0)""",
        (massey_cid, _MASSEY_EMAIL),
    )
    conn.execute(
        """UPDATE customer_emails SET is_primary = 1
           WHERE customer_id = ? AND LOWER(email) = LOWER(?)""",
        (massey_cid, _MASSEY_EMAIL),
    )

    # 4. Re-attribute ALL items with Massey's email, regardless of which customer_id
    #    they're currently under (catches orders placed before the bad merge).
    r4 = conn.execute(
        """UPDATE items
           SET customer = ?, customer_id = ?, customer_email = ?
           WHERE LOWER(customer_email) = LOWER(?) AND (customer_id != ? OR customer_id IS NULL)""",
        (_MASSEY_NAME, massey_cid, _MASSEY_EMAIL, _MASSEY_EMAIL, massey_cid),
    ).rowcount

    # 5. Re-attribute ALL items named William/Will Massey not already on his record.
    r5 = conn.execute(
        """UPDATE items
           SET customer = ?, customer_id = ?, customer_email = ?
           WHERE LOWER(customer) IN ('william massey', 'will massey')
             AND (customer_id != ? OR customer_id IS NULL)""",
        (_MASSEY_NAME, massey_cid, _MASSEY_EMAIL, massey_cid),
    ).rowcount

    # 6. Companion item from R278736131: Johnson bought 2 spots, one for Massey.
    r6 = conn.execute(
        """UPDATE items
           SET customer = ?, customer_id = ?, customer_email = ?
           WHERE order_id = 'R278736131'
             AND (customer_id != ? OR customer_id IS NULL)
             AND (LOWER(COALESCE(partner_request, '')) LIKE '%massey%'
                  OR LOWER(COALESCE(notes, '')) LIKE '%massey%')""",
        (_MASSEY_NAME, massey_cid, _MASSEY_EMAIL, massey_cid),
    ).rowcount

    # 7. Explicit order-id fix for Will's own orders whose customer_email may have been
    #    overwritten by the identity-heal to Johnson's canonical email.
    r7 = conn.execute(
        """UPDATE items
           SET customer = ?, customer_id = ?, customer_email = ?
           WHERE order_id IN ('R545206118', 'R112804515')
             AND (customer_id != ? OR customer_id IS NULL)""",
        (_MASSEY_NAME, massey_cid, _MASSEY_EMAIL, massey_cid),
    ).rowcount

    total = r4 + r5 + r6 + r7
    logger.info(
        "Massey repair: re-attributed %d item(s) to cid=%d "
        "(by-email=%d, by-name=%d, companion=%d, by-order=%d)",
        total, massey_cid, r4, r5, r6, r7,
    )

    # 8. Fix open action_items referencing Massey (action_items has no customer column)
    conn.execute(
        """UPDATE action_items
           SET customer_id = ?
           WHERE LOWER(from_name) IN ('william massey', 'will massey')
             AND (customer_id != ? OR customer_id IS NULL)
             AND status IN ('open', 'in_progress')""",
        (massey_cid, massey_cid),
    )

    conn.commit()


def _repair_lourigan_attribution(conn: sqlite3.Connection) -> None:
    """Merge a duplicate Joseph Lourigan customer record into his canonical one.

    Order R436033588 (a guest-slot purchase for "Jack Semler") had a blank
    customer_email, so the create-customer path's name matching missed his
    existing record and it landed on a fresh customer_id=406 instead of his
    canonical customer_id=83 (TGF Membership + 3 other registrations, real
    email/phone on file). Confirmed via live-data audit — customer_id 406
    has exactly the one stray order and nothing else.

    Delegates to merge_customers(), which already handles moving
    customer_emails/tgf_payouts/acct_transactions and deleting the orphaned
    source row. Fully idempotent: skips entirely once customer_id 406 no
    longer exists (already merged).
    """
    _NAME = "Joseph Lourigan"
    _SOURCE_CID = 406
    _TARGET_CID = 83

    exists = conn.execute(
        "SELECT 1 FROM customers WHERE customer_id = ?", (_SOURCE_CID,)
    ).fetchone()
    if not exists:
        return

    try:
        merge_customers(
            _NAME, _NAME, db_path=None,
            source_customer_id=_SOURCE_CID, target_customer_id=_TARGET_CID,
        )
        logger.info(
            "Lourigan repair: merged customer_id %d -> %d",
            _SOURCE_CID, _TARGET_CID,
        )
    except ValueError as e:
        logger.warning("Lourigan repair failed: %s", e)


