def _repair_lead_email_separations(conn: sqlite3.Connection) -> None:
    """Quarantine lead emails from the whole identity system.

    A lead's email must not appear on ANY profile: removes it from
    customer_emails and customer_aliases regardless of owner, unlinks any
    RSVP attached through it, and clears the items.customer_email snapshot
    that carries it. That last step is what kills the resurrection loop
    seen live on 2026-07-02: separation deleted the alias, then
    capture_email_aliases_from_items re-created it from the member's item
    snapshot, the rsvps backfill re-linked the decline, and the next boot
    separated it all again. The lead emails live in
    _RSVP_KNOWN_NON_CUSTOMERS, so their decline RSVPs stay unlinked by
    design. Runs AFTER _repair_confirmed_profile_details. Idempotent.
    """
    for cid, email, who in _LEAD_EMAIL_SEPARATIONS:
        e = email.lower()
        n1 = conn.execute(
            "DELETE FROM customer_emails WHERE LOWER(TRIM(email)) = ?", (e,)
        ).rowcount
        n2 = conn.execute(
            "DELETE FROM customer_aliases WHERE alias_type = 'email' "
            "AND LOWER(TRIM(COALESCE(alias_value,''))) = ?", (e,)
        ).rowcount
        n3 = conn.execute(
            "UPDATE rsvps SET customer_id = NULL WHERE customer_id IS NOT NULL "
            "AND LOWER(TRIM(COALESCE(player_email,''))) = ?", (e,)
        ).rowcount
        n4 = conn.execute(
            "UPDATE items SET customer_email = NULL "
            "WHERE LOWER(TRIM(COALESCE(customer_email,''))) = ?", (e,)
        ).rowcount
        if n1 or n2 or n3 or n4:
            logger.info(
                "Lead-email separation: removed %d email(s), %d alias(es), "
                "unlinked %d RSVP(s), cleared %d item snapshot(s) — %s is %s "
                "(was attached near cid %d)",
                n1, n2, n3, n4, email, who, cid,
            )


def _apply_roster_contact_backfill(conn: sqlite3.Connection) -> None:
    """ONE-SHOT backfill of missing email/Venmo from an extracted roster file.

    Reads data/member_roster_backfill.json when present; without the file
    this is a silent no-op. The 2026-07-02 run (471 rows extracted from the
    25TGF_Members Player Database sheet) matched 234 existing profiles and
    filled 164 Venmo handles + 9 emails, after which the file was REMOVED
    from the repo: the admin maintains that spreadsheet externally and it
    isn't a master source, so a stale snapshot must not keep enriching
    future profiles. To re-run with fresh data, extract name/email/venmo
    rows to that path again and deploy — it applies once, blank-only.

    Per row: resolve via _lookup_customer_id (email evidence first, then
    exact name incl. alternate first-name spellings, ambiguity-guarded);
    fill venmo when blank; fill email only when the profile has none AND
    the address isn't on any other profile. Never creates profiles;
    lead-registry emails are never applied.
    """
    import json as _json
    path = Path(__file__).resolve().parent.parent / "data" / "member_roster_backfill.json"
    if not path.exists():
        return
    try:
        rows = _json.loads(path.read_text())
    except Exception:
        logger.exception("Roster backfill: could not read %s", path)
        return
    matched = filled_email = filled_venmo = 0
    for r in rows:
        email = (r.get("email") or "").strip().lower() or None
        if email and email in _RSVP_KNOWN_NON_CUSTOMERS:
            email = None
        venmo = (r.get("venmo") or "").lstrip("@").strip() or None
        names = [f"{r['first']} {r['last']}"] + \
                [f"{a} {r['last']}" for a in (r.get("alts") or [])]
        cid = None
        for nm in names:
            cid = _lookup_customer_id(conn, nm, email)
            if cid:
                break
        if not cid:
            continue
        matched += 1
        if venmo:
            cur = conn.execute(
                "UPDATE customers SET venmo_username = ? WHERE customer_id = ? "
                "AND (venmo_username IS NULL OR TRIM(venmo_username) = '')",
                (venmo, cid),
            )
            if cur.rowcount:
                filled_venmo += 1
                logger.info("Roster backfill: venmo %r → %s (cid %d)",
                            venmo, names[0], cid)
        if email:
            has_any = conn.execute(
                "SELECT 1 FROM customer_emails WHERE customer_id = ?", (cid,)
            ).fetchone()
            taken = conn.execute(
                "SELECT 1 FROM customer_emails WHERE LOWER(TRIM(email)) = ?",
                (email,),
            ).fetchone()
            if not has_any and not taken:
                conn.execute(
                    "INSERT OR IGNORE INTO customer_emails "
                    "(customer_id, email, is_primary, label) VALUES (?, ?, 1, 'roster-2025')",
                    (cid, email),
                )
                conn.execute(
                    "INSERT OR IGNORE INTO customer_aliases "
                    "(customer_name, alias_type, alias_value, customer_id) "
                    "VALUES (?, 'email', ?, ?)",
                    (names[0], email, cid),
                )
                filled_email += 1
                logger.info("Roster backfill: email %s → %s (cid %d)",
                            email, names[0], cid)
    conn.commit()
    logger.info(
        "Roster contact backfill: %d/%d roster rows matched existing profiles — "
        "%d email(s) filled, %d Venmo handle(s) filled",
        matched, len(rows), filled_email, filled_venmo,
    )


def _normalize_venmo_usernames(conn: sqlite3.Connection) -> None:
    """Store Venmo handles BARE (no leading @).

    The Customer Info update path already lstrips '@' and every
    payout/matching read strips it from both sides, but direct writes
    (imports, seeds) could slip an @-prefixed value in — the UI then
    rendered '@@handle'. Idempotent.
    """
    n = conn.execute(
        "UPDATE customers SET venmo_username = LTRIM(venmo_username, '@') "
        "WHERE venmo_username LIKE '@%'"
    ).rowcount
    if n:
        logger.info("Venmo handle normalization: stripped leading '@' from %d profile(s)", n)


def _repair_venmo_payer_aliases(conn: sqlite3.Connection) -> None:
    """Register admin-confirmed Venmo payer identities (2026-07-02).

    These Venmo display names belong to existing members under different
    first names. A cid-linked name alias makes the memo-ledger repair (and
    all future name resolution) link their payments to the right profile:
      - 'Leonel Vasquez'    → Lee Vasquez (Austin)
      - 'Christopher Lieck' → Wade Lieck (San Antonio)
      - 'Dan Lehan'         → Daniel Lehan (San Antonio)
    Idempotent; warns and skips a pair when the member can't be uniquely
    resolved by name (so a wrong guess is impossible).
    """
    PAIRS = (
        ("Leonel Vasquez", "Lee Vasquez"),
        ("Christopher Lieck", "Wade Lieck"),
        ("Dan Lehan", "Daniel Lehan"),
    )
    for alias_value, canonical in PAIRS:
        if conn.execute(
            """SELECT id FROM customer_aliases
               WHERE alias_type = 'name' AND LOWER(alias_value) = LOWER(?)""",
            (alias_value,),
        ).fetchone():
            continue
        cid = _lookup_customer_id(conn, canonical, None)
        if cid is None:
            logger.warning(
                "Venmo payer alias: member %r not uniquely resolvable — "
                "skipping alias %r", canonical, alias_value,
            )
            continue
        conn.execute(
            """INSERT OR IGNORE INTO customer_aliases (customer_name, alias_value, alias_type, customer_id)
               VALUES (?, ?, 'name', ?)""",
            (canonical, alias_value, cid),
        )
        logger.info(
            "Venmo payer alias: added %r → %r (cid %d)",
            alias_value, canonical, cid,
        )
    conn.commit()


def _repair_venmo_memo_ledger_customers(conn: sqlite3.Connection) -> None:
    """Fix Venmo ledger rows whose customer field holds the payment MEMO.

    The Venmo CSV importer's customer fallback stored the note text
    ('Skins', 'Putting Contest', 'Luke+Youngs+...+Balance+Due') as the
    customer name for incoming payments — rows that can never link to a
    customer_id. The real payer is recoverable: the description was built
    as '<payer>: <memo>'. For unlinked venmo rows with that shape, resolve
    the payer via _lookup_customer_id and set customer_id + rewrite
    customer to the payer's canonical name (the memo stays intact in
    description). Unresolvable payers (no profile, or ambiguous name) are
    left alone and logged. Idempotent — repaired rows gain a cid and drop
    out of the scan; the v2.16.23 importer fix stops new ones forming.
    """
    rows = conn.execute(
        """SELECT id, customer, description FROM acct_transactions
           WHERE customer_id IS NULL
             AND source = 'venmo'
             AND customer IS NOT NULL AND customer != ''
             AND description LIKE '%:%'"""
    ).fetchall()
    fixed = unresolved = renamed = external = 0
    for r in rows:
        payer = " ".join((r["description"] or "").split(":", 1)[0].split())
        if len(payer) < 3 or " " not in payer:
            unresolved += 1
            continue  # single-token / emoji payer — not name-resolvable
        if payer.lower() in _VENMO_KNOWN_NON_CUSTOMERS:
            # Confirmed non-customer (Two Man Tour / personal) — keep the
            # payer display for readability, never resolve, never nag.
            if (r["customer"] or "").strip().lower() != payer.lower():
                conn.execute(
                    "UPDATE acct_transactions SET customer = ? WHERE id = ?",
                    (payer, r["id"]),
                )
                renamed += 1
            external += 1
            continue
        cid = _lookup_customer_id(conn, payer, None)
        if cid is None:
            # No profile for this payer (or the name is ambiguous). Still set
            # the display to the payer so the ledger reads correctly and the
            # boot backfill auto-links the row the moment a profile for this
            # payer is created. Log per-row only on the first rewrite so the
            # remaining unresolved set doesn't spam every boot.
            if (r["customer"] or "").strip().lower() != payer.lower():
                conn.execute(
                    "UPDATE acct_transactions SET customer = ? WHERE id = ?",
                    (payer, r["id"]),
                )
                renamed += 1
                logger.info(
                    "Venmo memo-ledger repair: payer %r has no profile — row %s "
                    "display set to payer (memo %r stays in description)",
                    payer, r["id"], (r["customer"] or "")[:40],
                )
            unresolved += 1
            continue
        canon = conn.execute(
            """SELECT TRIM(COALESCE(NULLIF(company_name, ''),
                       NULLIF(TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')), ''))) AS n
               FROM customers WHERE customer_id = ?""",
            (cid,),
        ).fetchone()
        display = (canon["n"] if canon and canon["n"] else payer)
        conn.execute(
            "UPDATE acct_transactions SET customer_id = ?, customer = ? WHERE id = ?",
            (cid, display, r["id"]),
        )
        fixed += 1
        logger.info(
            "Venmo memo-ledger repair: row %s memo %r → %s (cid %d)",
            r["id"], (r["customer"] or "")[:40], display, cid,
        )
    if fixed or renamed:
        conn.commit()
    if fixed or unresolved or external:
        logger.info(
            "Venmo memo-ledger repair: %d row(s) linked to their payer, "
            "%d unresolved (no profile), %d known non-customer (2MT/personal), "
            "%d renamed to payer this run",
            fixed, unresolved, external, renamed,
        )


# Title-cased roman numerals that are unambiguous name suffixes ('Iii' is
# never a real name token). 'Vi'/'V'/'X' are deliberately excluded — they
# collide with real names/initials.
_ROMAN_TITLECASE = re.compile(r"\b(Ii|Iii|Iv|Vii|Viii|Ix)\b")


def _repair_roman_numeral_name_case(conn: sqlite3.Connection) -> None:
    """Fix 'Iii'-style title-cased roman numerals in name display columns
    (e.g. the Golf Genius import stored 'Victor Iii Arias'). items/customers
    are already covered by _migrate_normalize_customer_name_case, whose
    _proper_case_word upper-cases roman tokens — this handles the
    name-bearing columns that migration doesn't touch. Idempotent.
    """
    TARGETS = (
        ("handicap_player_links", ("player_name", "customer_name")),
        ("handicap_rounds", ("player_name",)),
        ("rsvps", ("player_name",)),
        ("season_contests", ("customer_name",)),
        ("cmp_pool_members", ("customer_name",)),
        ("customer_aliases", ("customer_name", "alias_value")),
        ("acct_transactions", ("customer",)),
    )
    fixed = 0
    for table, cols in TARGETS:
        for col in cols:
            try:
                rows = conn.execute(
                    f"SELECT rowid AS rid, {col} AS v FROM {table} "
                    f"WHERE {col} IS NOT NULL AND {col} != ''"
                ).fetchall()
            except sqlite3.OperationalError:
                continue
            for r in rows:
                new = _ROMAN_TITLECASE.sub(lambda m: m.group(1).upper(), r["v"])
                if new != r["v"]:
                    conn.execute(
                        f"UPDATE {table} SET {col} = ? WHERE rowid = ?",
                        (new, r["rid"]),
                    )
                    fixed += 1
                    logger.info(
                        "Roman-numeral case repair: %s.%s %r → %r",
                        table, col, r["v"], new,
                    )
    if fixed:
        conn.commit()


def _repair_player_link_identities(conn: sqlite3.Connection) -> None:
    """Re-point handicap_player_links rows whose customer_id contradicts
    their own customer_name.

    Links were historically auto-matched by EMAIL, which attaches a player
    to whoever's email is on their purchases — for guest/family purchases
    that's the BUYER (Will Massey's link pointed at Colby Johnson's profile;
    Isabella Luna's at her guardian's). The v2.16.26 canonical-first GG
    email resolution made link.customer_id authoritative, surfacing these.
    The link's customer_name records who the link is FOR — when it resolves
    uniquely to a different profile than customer_id, the link (and its
    player's handicap_rounds) is re-pointed; ambiguous or unresolvable
    names are logged and left alone. Idempotent.
    """
    _ensure_scoring_tables(conn)   # repairs reset handicap_rounds.scoring_round_id
    rows = conn.execute(
        """SELECT l.rowid AS rid, l.player_name, l.customer_name, l.customer_id,
                  TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')) AS linked_name
           FROM handicap_player_links l
           JOIN customers c ON c.customer_id = l.customer_id
           WHERE l.customer_id IS NOT NULL
             AND l.customer_name IS NOT NULL AND TRIM(l.customer_name) != ''"""
    ).fetchall()
    for r in rows:
        stored = " ".join((r["customer_name"] or "").split()).lower()
        linked = " ".join((r["linked_name"] or "").split()).lower()
        if not stored or stored == linked:
            continue
        want = _lookup_customer_id(conn, r["customer_name"], None)
        if want is None:
            logger.warning(
                "Player link identity: %r (link for %r) points at cid %s (%r) "
                "but the name doesn't resolve uniquely — leaving as-is",
                r["player_name"], r["customer_name"], r["customer_id"], r["linked_name"],
            )
            continue
        if want == r["customer_id"]:
            continue  # name is an alias of the linked customer — correct
        conn.execute(
            "UPDATE handicap_player_links SET customer_id = ? WHERE rowid = ?",
            (want, r["rid"]),
        )
        moved_rounds = conn.execute(
            "UPDATE handicap_rounds SET customer_id = ?, scoring_round_id = NULL "
            "WHERE customer_id = ? AND player_name = ?",
            (want, r["customer_id"], r["player_name"]),
        ).rowcount
        logger.info(
            "Player link identity: %r re-pointed cid %s (%r) → cid %s "
            "(%d round(s) followed)",
            r["customer_name"], r["customer_id"], r["linked_name"], want,
            moved_rounds,
        )

    # Pass 2: links created with NO customer_name — nothing recorded about
    # who the link is FOR, so the GG player_name itself is the only signal.
    # When that name IS a customer's exact canonical name (not merely an
    # alias — alias-mediated resolution is too weak to auto-repair) and the
    # link points at a different profile, it's the same buyer-email
    # misattribution class: Kailey Lopez's nameless link pointed at Steve
    # Kulawik, silently feeding her rounds into his handicap record and
    # blocking her scorecard import as a "duplicate" of his.
    rows = conn.execute(
        """SELECT l.rowid AS rid, l.player_name, l.customer_id,
                  TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')) AS linked_name
           FROM handicap_player_links l
           JOIN customers c ON c.customer_id = l.customer_id
           WHERE l.customer_id IS NOT NULL
             AND (l.customer_name IS NULL OR TRIM(l.customer_name) = '')
             AND l.player_name IS NOT NULL AND TRIM(l.player_name) != ''"""
    ).fetchall()
    for r in rows:
        pname = " ".join((r["player_name"] or "").split())
        linked = " ".join((r["linked_name"] or "").split()).lower()
        if not pname or pname.lower() == linked:
            continue
        want = _lookup_customer_id(conn, pname, None)
        if want is None or want == r["customer_id"]:
            continue
        target = conn.execute(
            """SELECT TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS nm
               FROM customers WHERE customer_id = ?""", (want,)).fetchone()
        if not target or " ".join((target["nm"] or "").split()).lower() != pname.lower():
            continue
        conn.execute(
            "UPDATE handicap_player_links SET customer_id = ? WHERE rowid = ?",
            (want, r["rid"]),
        )
        moved_rounds = conn.execute(
            "UPDATE handicap_rounds SET customer_id = ?, scoring_round_id = NULL "
            "WHERE customer_id = ? AND player_name = ?",
            (want, r["customer_id"], r["player_name"]),
        ).rowcount
        logger.info(
            "Player link identity (nameless link): %r re-pointed cid %s (%r) "
            "→ cid %s (%d round(s) followed; scorecard bridge reset)",
            pname, r["customer_id"], r["linked_name"], want, moved_rounds,
        )

    # Pass 3: the email auto-matcher sometimes filled BOTH customer_name and
    # customer_id with the BUYER (Kailey Lopez's link recorded
    # customer_name='Steve Kulawik' because her guest spots were bought on
    # his email) — pass 1 sees a self-consistent link, pass 2 requires an
    # empty customer_name. Repair only under two hard guards: the GG
    # player_name is EXACTLY one other customer's canonical name (no alias
    # inference, ambiguity refusal), AND the linked customer separately
    # holds a link under their OWN name — proof this second player row
    # can't just be their GG display-name variant. The wrong customer_name
    # is corrected along with the id.
    rows = conn.execute(
        """SELECT l.rowid AS rid, l.player_name, l.customer_name, l.customer_id,
                  TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')) AS linked_name
           FROM handicap_player_links l
           JOIN customers c ON c.customer_id = l.customer_id
           WHERE l.customer_id IS NOT NULL
             AND l.customer_name IS NOT NULL AND TRIM(l.customer_name) != ''
             AND l.player_name IS NOT NULL AND TRIM(l.player_name) != ''"""
    ).fetchall()
    for r in rows:
        pname = " ".join((r["player_name"] or "").split())
        stored = " ".join((r["customer_name"] or "").split()).lower()
        linked = " ".join((r["linked_name"] or "").split()).lower()
        if not pname or pname.lower() == linked or stored != linked:
            continue   # own-name link, or pass-1 territory
        others = conn.execute(
            """SELECT customer_id,
                      TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS nm
               FROM customers
               WHERE LOWER(TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,''))) = LOWER(?)""",
            (pname,)).fetchall()
        if len(others) != 1 or others[0]["customer_id"] == r["customer_id"]:
            continue
        own = conn.execute(
            """SELECT 1 FROM handicap_player_links
               WHERE customer_id = ? AND rowid != ?
                 AND LOWER(TRIM(player_name)) = ? LIMIT 1""",
            (r["customer_id"], r["rid"], linked)).fetchone()
        if not own:
            continue
        want, want_name = others[0]["customer_id"], others[0]["nm"]
        conn.execute(
            """UPDATE handicap_player_links
               SET customer_id = ?, customer_name = ? WHERE rowid = ?""",
            (want, want_name, r["rid"]),
        )
        moved_rounds = conn.execute(
            "UPDATE handicap_rounds SET customer_id = ?, scoring_round_id = NULL "
            "WHERE customer_id = ? AND player_name = ?",
            (want, r["customer_id"], r["player_name"]),
        ).rowcount
        logger.info(
            "Player link identity (buyer-filled link): %r re-pointed cid %s "
            "(%r) → cid %s (%d round(s) followed; scorecard bridge reset)",
            pname, r["customer_id"], r["linked_name"], want, moved_rounds,
        )
    conn.commit()


