def _flight_range_text(lo, hi) -> str:
    if lo is None:
        return f"HCP < {hi:g}"
    if hi is None:
        return f"HCP {lo:g}+"
    return f"HCP {lo:g}–{hi - 0.1:g}"


def _assign_flight(index: float | None, flights) -> str | None:
    if index is None:
        return None
    for label, lo, hi in flights:
        if (lo is None or index >= lo) and (hi is None or index < hi):
            return label
    return None


def _gg_name_candidates(raw_name: str) -> list:
    """Build customer-lookup candidates from a Golf Genius display name.

    Portal names are usually 'LAST, First' (optionally with a suffix inside
    the first part, e.g. 'ARIAS, Victor Jr'); guests sometimes appear as
    plain 'First Last'. Returns ordered 'First Last' candidate strings.
    """
    name = " ".join((raw_name or "").split())
    if not name:
        return []
    cands = []
    if "," in name:
        last, first = [p.strip() for p in name.split(",", 1)]
        if first and last:
            cands.append(f"{first} {last}")
            parts = first.split()
            if len(parts) > 1 and parts[-1].rstrip(".").lower() in (
                    "jr", "sr", "ii", "iii", "iv", "v"):
                cands.append(f"{' '.join(parts[:-1])} {last} {parts[-1]}")
    else:
        cands.append(name)
    # GG duplicate-name artifact: a digit appended to the given name
    # ("REED, Paul1") when a same-named member registers. Try the
    # digit-stripped form after the exact one.
    for c in list(cands):
        stripped = " ".join(w.rstrip("0123456789") for w in c.split())
        stripped = " ".join(stripped.split())
        if stripped and stripped != c and stripped not in cands:
            cands.append(stripped)
    return cands


_GG_EVENT_CODE_RE = re.compile(r"^([a-z]+\d+(?:\.\d+)?)\b", re.I)

# Compound codes with a trailing letter suffix ("hcmR1nm POINTS Net …") —
# GG tournament renames grow suffixes onto the base code, which the plain
# code regex can't parse (no word boundary between "1" and "nm")
_GG_EVENT_CODE_COMPOUND_RE = re.compile(r"^([a-z]+\d+(?:\.\d+)?[a-z]*)\b", re.I)

# Admin-provided labels for GG event codes with no tracker event
# (2026-07-03). A tracker event with the same code would win — live data
# over static — since these only fill gaps left by the events table.
_GG_CODE_NAME_OVERRIDES: dict = {
    # No code prefix on these (admin preference) — the round name carries it
    # ALL CAPS league name per admin (desktop verbatim; the phone-side
    # prettifier title-cases it automatically)
    "hcmr1": "HILL COUNTRY MATCHES - R1 Valley",
    "hcmr2": "HILL COUNTRY MATCHES - R2 Hills",
    "hcmr3": "HILL COUNTRY MATCHES - R3 Creeks",
    # Austin's kickoff points lines are labeled just "Kickoff" in GG —
    # admin confirmed 2026-07-04 it IS a18.2 (keyed by first word)
    "kickoff": "a18.2 AUSTIN KICKOFF | ShadowGlen",
}


def substitute_gg_tournament_names(tables: list,
                                   db_path: str | Path = DB_PATH) -> list:
    """Swap GG tournament labels for tracker event names by event code.

    'a9.13 POINTS Gross - THE PLAYERS CUP' -> 'a9.13 Star Ranch' (admin
    request): the leading code token is the TGF event code both systems
    share, so it keys into events.item_name. Front/Back qualifiers from
    18-hole splits are preserved; unmatched labels pass through unchanged.
    """
    with _connect(db_path) as conn:
        code_map: dict = {}
        for r in conn.execute("SELECT item_name FROM events").fetchall():
            name = (r["item_name"] or "").strip()
            m = _GG_EVENT_CODE_RE.match(name)
            if m:
                code_map.setdefault(m.group(1).lower(), name)
    for code, label in _GG_CODE_NAME_OVERRIDES.items():
        code_map.setdefault(code, label)

    out = []
    for table in tables or []:
        if not table:
            out.append(table)
            continue
        header = [(c or "").strip().lower() for c in table[0]]
        if "tournament" not in header:
            out.append(table)
            continue
        t_idx = header.index("tournament")
        new_table = [table[0]]
        for row in table[1:]:
            row = list(row)
            if t_idx < len(row):
                cell = (row[t_idx] or "").strip()
                # Try the compound form first ("hcmR1nm" -> hcmr1nm), then
                # fall back to its base with the letter suffix stripped
                # ("hcmr1") so the admin overrides keep working after GG
                # tournament renames grow suffixes onto the code
                repl = None
                m = _GG_EVENT_CODE_COMPOUND_RE.match(cell)
                if m:
                    code = m.group(1).lower()
                    repl = (code_map.get(code)
                            # letter-suffix renames: hcmR1nm -> hcmr1
                            or code_map.get(re.sub(r"[a-z]+$", "", code))
                            # series-only event names: GG "a18.3" vs a
                            # tracker event named "a18 CRYSTAL FALLS"
                            or code_map.get(re.sub(r"\.\d+$", "", code)))
                elif cell:
                    # Code-less labels ("Kickoff POINTS Net - …") — the first
                    # word can still key an admin override
                    repl = code_map.get(cell.split(" ", 1)[0].lower())
                if repl:
                    low = cell.lower()
                    # plain hyphen per admin — long/short dashes varied
                    if "front" in low:
                        repl += " - Front"
                    elif "back" in low:
                        repl += " - Back"
                    row[t_idx] = repl
            new_table.append(row)
        out.append(new_table)
    return out


def _ensure_gg_points_table(conn: sqlite3.Connection) -> None:
    """Lazy-create the persisted GG standings snapshot (pairings pattern)."""
    conn.execute(
        """CREATE TABLE IF NOT EXISTS gg_points_standings (
            id            INTEGER PRIMARY KEY AUTOINCREMENT,
            race_key      TEXT NOT NULL,
            rank          TEXT,
            prev_rank     TEXT,
            player_name   TEXT NOT NULL,
            customer_id   INTEGER REFERENCES customers(customer_id),
            affiliation   TEXT,
            tournaments   INTEGER,
            wins          INTEGER,
            total_points  REAL,
            points_behind REAL,
            member_card_id TEXT,
            fetched_at    TEXT DEFAULT (datetime('now'))
        )"""
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_gg_points_race "
        "ON gg_points_standings(race_key)"
    )
    try:  # table may predate the member_card_id column (v2.19.1)
        conn.execute(
            "ALTER TABLE gg_points_standings ADD COLUMN member_card_id TEXT")
    except sqlite3.OperationalError:
        pass


def _resolve_gg_person(conn: sqlite3.Connection, raw_name: str,
                       capture_alias: bool = True) -> tuple:
    """(customer_id, how) for a Golf Genius display name, or (None, None).

    GG spells people its own way — "MORENO, Robert" for our Roberto
    Moreno, "MURPHY, Mike" for our Michael Murphy (Kerry 2026-07-31).
    Those rows carried real points and simply never resolved to a
    profile, so the player showed a dash on the pairing sheet and counted
    as unranked in the standings order.

    Ladder:
      1. the existing candidate lookup (`_gg_name_candidates` →
         `_lookup_customer_id`, which already consults customer_aliases);
      2. the nickname-robust person key (surname + first initial) —
         the same rule match play and partner requests use. Robert/
         Roberto and Mike/Michael collapse; Dick/Richard deliberately
         does not, because that changes the initial.

    A rung-2 hit is CAPTURED AS AN ALIAS so the match is permanent,
    visible in the customer profile, and reusable by every other GG path
    — "aliases should be used to capture anyone in GG that can't be
    matched" (Kerry). Ambiguity never resolves: if two customers share a
    person key, we refuse rather than guess.
    """
    cands = _gg_name_candidates(raw_name)
    for cand in cands:
        cid = _lookup_customer_id(conn, cand, None)
        if cid:
            return cid, "lookup"

    key = _cmp_person_key(raw_name)
    if not (key[0] and key[1]):
        return None, None
    try:
        rows = conn.execute(
            """SELECT customer_id, first_name, last_name FROM customers
               WHERE LOWER(TRIM(last_name)) = ?
                 AND SUBSTR(LOWER(TRIM(first_name)), 1, 1) = ?
                 AND COALESCE(account_status, 'active') != 'banned'
               LIMIT 3""",
            (key[0], key[1])).fetchall()
    except sqlite3.OperationalError:
        return None, None
    if len(rows) != 1:
        if len(rows) > 1:
            logger.info("GG name %r matches %d customers on person key %s "
                        "— refusing to guess", raw_name, len(rows), key)
        return None, None

    cid = rows[0]["customer_id"]
    canonical = f"{(rows[0]['first_name'] or '').strip()} " \
                f"{(rows[0]['last_name'] or '').strip()}".strip()
    if capture_alias:
        for cand in cands:
            if _pair_key_name(cand) == _pair_key_name(canonical):
                continue           # not an alias, just the same name
            # GG shouts the surname ("Robert MORENO"); store it the way a
            # human would read it in the profile. Lookups are already
            # case-insensitive, so this is presentation only.
            pretty = " ".join(w[:1].upper() + w[1:].lower() if w.isalpha() else w
                              for w in cand.split())
            try:
                conn.execute(
                    """INSERT OR IGNORE INTO customer_aliases
                           (customer_id, customer_name, alias_type, alias_value)
                       VALUES (?, ?, 'name', ?)""",
                    (cid, canonical, pretty))
                logger.info("GG alias captured: %r -> %s (cid %s)",
                            pretty, canonical, cid)
            except Exception:
                logger.exception("Non-fatal: could not capture GG alias %r", cand)
    return cid, "person_key"


def audit_gg_points_identities(db_path=None) -> dict:
    """Which stored standings rows never resolved to a customer_id.

    Kerry 2026-07-31: "Check rest of points to see if we're missing
    anyone else in our own points list extractions due to the same
    reasons." An unresolved row still shows on the Contests board (it has
    a name and a points total) but is invisible to anything that joins on
    identity — pairings order, the points column, flighting, payouts.

    Re-runs the resolver over the stored rows, so it both REPORTS and
    REPAIRS: anything the nickname rung can now match is linked and its
    alias captured. Returns per-race counts plus the names still
    unmatched, which are the ones a human has to look at.
    """
    out = {"races": [], "repaired": 0, "still_unmatched": 0}
    with _connect(db_path) as conn:
        _ensure_gg_points_table(conn)
        races = [r["race_key"] for r in conn.execute(
            "SELECT DISTINCT race_key FROM gg_points_standings").fetchall()]
        for rk in races:
            rows = conn.execute(
                """SELECT id, player_name, total_points FROM gg_points_standings
                   WHERE race_key = ? AND customer_id IS NULL""", (rk,)).fetchall()
            fixed, unmatched = [], []
            for r in rows:
                cid, how = _resolve_gg_person(conn, r["player_name"])
                if cid:
                    conn.execute(
                        "UPDATE gg_points_standings SET customer_id = ? WHERE id = ?",
                        (cid, r["id"]))
                    fixed.append({"player_name": r["player_name"],
                                  "customer_id": cid, "via": how})
                else:
                    unmatched.append({"player_name": r["player_name"],
                                      "total_points": r["total_points"]})
            total = conn.execute(
                "SELECT COUNT(*) AS n FROM gg_points_standings WHERE race_key = ?",
                (rk,)).fetchone()["n"]
            out["races"].append({
                "race_key": rk, "rows": total,
                "was_unlinked": len(rows), "repaired": len(fixed),
                "still_unmatched": len(unmatched),
                "repaired_names": fixed, "unmatched_names": unmatched,
            })
            out["repaired"] += len(fixed)
            out["still_unmatched"] += len(unmatched)
        conn.commit()
    return out


def refresh_points_race_standings(race_key: str,
                                  db_path: str | Path = DB_PATH) -> int:
    """Fetch a GG points race and replace its persisted snapshot.

    Names resolve to customer_id at write time (identity-key principle);
    enrollment status is NOT stored — it's joined live at read time so a
    buy-in recorded after the fetch shows immediately. Returns row count.
    """
    race = _GG_POINTS_RACES.get(race_key)
    if not race:
        raise ValueError(
            f"Unknown race {race_key!r} — known: {sorted(_GG_POINTS_RACES)}")

    from golf_genius_sync import fetch_season_points_race
    standings = fetch_season_points_race(
        page_id=race["page_id"], league_id=race["league_id"], host=race["host"])

    with _connect(db_path) as conn:
        _ensure_gg_points_table(conn)
        unmatched = []
        for row in standings:
            cid, how = _resolve_gg_person(conn, row["player_name"])
            row["customer_id"] = cid
            if not cid:
                unmatched.append(row["player_name"])
        if unmatched:
            logger.warning("GG points race %r: %d name(s) did not resolve to a "
                           "customer: %s", race_key, len(unmatched),
                           ", ".join(unmatched[:12]))
        conn.execute("DELETE FROM gg_points_standings WHERE race_key = ?",
                     (race_key,))
        conn.executemany(
            """INSERT INTO gg_points_standings
                   (race_key, rank, prev_rank, player_name, customer_id,
                    affiliation, tournaments, wins, total_points,
                    points_behind, member_card_id)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            [(race_key, r["rank"], r["prev_rank"], r["player_name"],
              r["customer_id"], r["affiliation"], r["tournaments"], r["wins"],
              r["total_points"], r["points_behind"],
              r.get("member_card_id")) for r in standings],
        )
        conn.commit()
    logger.info("GG points race %r: persisted %d standings rows",
                race_key, len(standings))
    return len(standings)


def _points_race_eligible_count(conn: sqlite3.Connection, race_key: str) -> int:
    """Reset-eligible headcount for a race's snapshot (admin methodology):
    active members who have played at least one event this season,
    regardless of point totals. Unresolved names count when GG's own
    affiliation shows a current TGF chapter."""
    rows = conn.execute(
        """SELECT s.affiliation, s.tournaments, s.customer_id,
                  c.current_player_status AS st
           FROM gg_points_standings s
           LEFT JOIN customers c ON c.customer_id = s.customer_id
           WHERE s.race_key = ?""",
        (race_key,),
    ).fetchall()
    n = 0
    for r in rows:
        if (r["tournaments"] or 0) < 1:
            continue
        if r["customer_id"]:
            if r["st"] in _MEMBER_PLAYER_STATUSES:
                n += 1
        elif "tgf" in (r["affiliation"] or "").lower():
            n += 1
    return n


# ── LIVE championship points overlay (Kerry 2026-07-31) ──────────────────
# "The Championship is in addition to the regular season total, so
# everything earned tomorrow adds on like we have setup in the top 10
# totals + championship value."
#
# The season standings are a stored snapshot (gg_points_standings, the
# best-10 totals). The championship is a SEPARATE GG game whose Stableford
# points are added on top, live, while the round is being played. Boards:
#   SA     "sChampionship POINTS Net"  v2tournaments/4779202
#   Austin "aChamp POINTS"             v2tournaments/4779168
# Held as a DIAL (app_settings 'gg_champ_points_boards', JSON keyed by race)
# so next season's tournament ids are a settings change, not a deploy.
_GG_CHAMP_BOARDS_DEFAULT: dict = {
    "san_antonio_net": {
        "label": "sChampionship POINTS Net",
        "url": ("https://tgf-sa.golfgenius.com/v2tournaments/4779202"
                "?player_stats_for_portal=true&round_index=35"),
    },
    "austin_net": {
        "label": "aChamp POINTS",
        "url": ("https://tgf-austin.golfgenius.com/v2tournaments/4779168"
                "?player_stats_for_portal=true&round_index=31"),
    },
}

# GG appends the player's affiliation to the name cell ("FIEBER, Wade TGF
# San Antonio", "Villa, Mark Guest"). Stripped before identity resolution.
_GG_AFFILIATIONS_DEFAULT = ("TGF San Antonio", "TGF Austin",
                            "TGF Dallas-Fort Worth", "TGF Houston",
                            "TGF Dallas", "Guest")

_CHAMP_POINTS_CACHE: dict = {}      # race_key -> (epoch, payload)


def champ_points_boards(db_path: str | Path = DB_PATH) -> dict:
    """The configured championship boards, dial overriding the default."""
    try:
        raw = get_app_setting("gg_champ_points_boards", db_path=db_path)
    except sqlite3.OperationalError:
        raw = None          # app_settings not created yet — use the defaults
    if raw:
        try:
            got = json.loads(raw)
            if isinstance(got, dict) and got:
                return got
        except (ValueError, TypeError):
            logger.warning("gg_champ_points_boards is not valid JSON — "
                           "using the built-in board list")
    return dict(_GG_CHAMP_BOARDS_DEFAULT)


def _strip_gg_affiliation(cell: str, affiliations=None) -> str:
    """'FIEBER, Wade TGF San Antonio' -> 'FIEBER, Wade'."""
    nm = re.sub(r"\s+", " ", (cell or "")).strip()
    for aff in (affiliations or _GG_AFFILIATIONS_DEFAULT):
        if nm.lower().endswith(" " + aff.lower()):
            return nm[: -len(aff) - 1].strip()
    # Unknown affiliation: keep 'SURNAME, First' and drop any trailing tail.
    m = re.match(r"^([^,]+,\s*\S+)(?:\s+.*)?$", nm)
    return m.group(1).strip() if m else nm


def _parse_champ_points_tables(tables: list, affiliations=None) -> list:
    """Rows from a GG championship POINTS board.

    Board shape: Pos. | Player | Stableford Points | Thru. Points read '-'
    until a player starts, and GG interleaves blank single-cell spacer
    rows. Returns [{name, points, thru}] with points None when not yet
    scoring, so 'hasn't started' is never confused with a genuine zero.
    """
    out = []
    for t in tables or []:
        rows = t if isinstance(t, list) else (t.get("rows") or [])
        hdr = None
        for row in rows:
            cells = [re.sub(r"\s+", " ", (c or "")).strip() for c in row]
            if len(cells) < 3:
                continue
            low = [c.lower() for c in cells]
            if "player" in low and any("point" in c for c in low):
                hdr = {"player": low.index("player")}
                hdr["points"] = next(i for i, c in enumerate(low) if "point" in c)
                hdr["thru"] = low.index("thru") if "thru" in low else None
                continue
            if hdr is None:
                continue
            raw_name = cells[hdr["player"]] if hdr["player"] < len(cells) else ""
            name = _strip_gg_affiliation(raw_name, affiliations)
            if not name:
                continue
            if "," not in name:
                # Guests can render FIRST LAST with no comma ("Matt Larson
                # Guest" -> "Matt Larson", seen live on the Austin champ
                # board 2026-08-01). Accept a plain multi-word name; any
                # other comma-less cell (section labels, totals) still
                # skips.
                if not re.match(r"^[A-Za-z'.\-]+(?: [A-Za-z'.\-]+)+$", name):
                    continue
            praw = cells[hdr["points"]] if hdr["points"] < len(cells) else ""
            # A SCORING player's cell reads "3 (3/0)" — total (front/back) —
            # seen on the live board 2026-08-01 during Kerry's pre-round
            # test; float() on the whole cell read every scoring player as
            # not-started and the overlay stayed silently inert. Parse the
            # LEADING number; a bare "-" still yields None (not started),
            # never zero.
            m_pts = re.match(r"-?\d+(?:\.\d+)?",
                             str(praw).replace(",", "").strip())
            pts = float(m_pts.group(0)) if m_pts else None
            thru = (cells[hdr["thru"]] if hdr["thru"] is not None
                    and hdr["thru"] < len(cells) else "")
            out.append({"name": name, "points": pts, "thru": thru})
    return out


def _parse_champ_plus_column(tables: list, affiliations=None) -> dict:
    """name -> PLUS playing handicap (as positive points to deduct), read
    off the championship SCORECARD board's PlayingHandicap™ column.

    Kerry's championship rule (2026-08-01, from the course): a plus
    player's playing handicap comes OFF their championship points total —
    GG's points game never takes their give-back strokes, so the board
    total is inflated by exactly the plus value. Only cells that render
    with a leading '+' ("+4") are returned; ordinary handicaps ("4",
    "22") deduct nothing. Verified live: SA board 4779120 carries
    YOUNGS +4 / HORTON +4 / GRIFFIN +3 and no other plus in the field.
    """
    out = {}
    for t in tables or []:
        rows = t if isinstance(t, list) else (t.get("rows") or [])
        hdr = None
        for row in rows:
            cells = [re.sub(r"\s+", " ", (c or "")).strip() for c in row]
            if len(cells) < 3:
                continue
            low = [c.lower() for c in cells]
            if "player" in low and any("handicap" in c for c in low):
                hdr = {"player": low.index("player"),
                       "ph": next(i for i, c in enumerate(low)
                                  if "handicap" in c)}
                continue
            if hdr is None:
                continue
            name = (_strip_gg_affiliation(cells[hdr["player"]], affiliations)
                    if hdr["player"] < len(cells) else "")
            ph = cells[hdr["ph"]] if hdr["ph"] < len(cells) else ""
            m = re.match(r"\+(\d+(?:\.\d+)?)$", ph)
            if name and m:
                out[name] = float(m.group(1))
    return out


def _champ_plus_adjustments(race_key: str,
                            db_path: str | Path = DB_PATH) -> dict:
    """{'by_cid', 'by_key'} plus-handicap deductions for one race.

    Sourced from the scorecard-board roster walk (cached 120s there). A
    roster failure falls back to the last cached roster — the points
    fetch must never die, and an adjustment must never silently vanish,
    because the scorecard board hiccuped once.

    GROSS races get NO deduction: Kerry's plus-handicap rule (championship
    day 2026-08-01) takes the playing handicap off NET championship
    points; gross points have no handicap component and the GG gross
    boards were recorded into the Players Cup reset as posted. Without
    this guard, configuring a scorecard board for players_cup_gross (for
    the hole-by-hole card) would silently start re-scoring the gross race."""
    if race_key.endswith("_gross"):
        return {"by_cid": {}, "by_key": {}}
    try:
        roster = _champ_card_roster(race_key, db_path=db_path)
    except Exception:
        hit = _CHAMP_ROSTER_CACHE.get(race_key)
        roster = hit[1] if hit else {}
    return {"by_cid": roster.get("plus_by_cid") or {},
            "by_key": roster.get("plus_by_key") or {}}


def _champ_final_board(race_key: str,
                       db_path: str | Path = DB_PATH) -> "list | None":
    """The persisted FINAL championship board for a race, if one exists
    AND the race is still declared final (the gg_points_race_final dial).
    The dial requirement bounds the fallback window: once next season's
    reset clears the dial, a stale snapshot can never resurrect last
    year's championship onto a fresh board."""
    if not _points_race_final(race_key, db_path=db_path):
        return None
    try:
        raw = get_app_setting(f"gg_champ_final_board_{race_key}",
                              db_path=db_path)
        if not raw:
            return None
        players = (json.loads(raw) or {}).get("players")
        return players or None
    except Exception:
        return None


_CHAMP_DISCOVER_ATTEMPTS: dict = {}


def _champ_autodiscover_boards(race_key: str, entries: list,
                               db_path: str | Path = DB_PATH) -> None:
    """Resolve PENDING board entries by themselves (Kerry 2026-08-13:
    "shouldn't it automatically update?"). An entry with no url but a
    "discover" widget URL (the GG round's tournament_results listing)
    plus a "match" name substring looks its own board up the moment GG
    releases the round: the matching link's href becomes the entry's
    url, persisted into gg_champ_points_boards AND mirrored into
    gg_champ_scorecard_boards so the round's card toggle appears too —
    no manual Sunday-morning step. Attempts are throttled to one per
    300s per entry; a failed lookup leaves the entry pending exactly as
    before. not_before still gates ACTIVATION independently, so a
    round discovered early stays a blank column until its date."""
    import time as _t
    from golf_genius_sync import fetch_public_page, parse_page_structure
    for b in entries:
        if b.get("url") or not (b.get("discover") and b.get("match")):
            continue
        label = b.get("label") or "Pending"
        ak = (race_key, label, b["discover"], b["match"])
        last = _CHAMP_DISCOVER_ATTEMPTS.get(ak, 0.0)
        if (_t.time() - last) < 300:
            continue
        _CHAMP_DISCOVER_ATTEMPTS[ak] = _t.time()
        try:
            page = fetch_public_page(b["discover"], xhr=False)
            if page["status_code"] != 200:
                continue
            parsed = parse_page_structure(page["html"],
                                          page.get("final_url") or b["discover"])
            want = str(b["match"]).strip().lower()
            hit = next((l for l in (parsed.get("links") or [])
                        if want in (l.get("text") or "").strip().lower()
                        and "/v2tournaments/" in (l.get("href") or "")), None)
            if not hit:
                continue        # round not released yet — stays pending
            b["url"] = hit["href"]
            logger.info("champ board auto-discovered: %s / %s -> %s",
                        race_key, label, hit["href"])
            _champ_persist_discovered(race_key, label, hit["href"],
                                      db_path=db_path)
        except Exception:
            continue


def _champ_persist_discovered(race_key: str, label: str, url: str,
                              db_path: str | Path = DB_PATH) -> None:
    """Write an auto-discovered board url into BOTH dials so it
    survives restarts: the points entry gains its url (discover/match
    kept for the audit trail), and the scorecard dial gains a matching
    round entry if that label isn't there yet. Cup races hold LISTS in
    both dials; a race whose scorecard config is a plain dict (the city
    shape) is left alone."""
    try:
        raw = get_app_setting("gg_champ_points_boards", db_path=db_path)
        cfg = json.loads(raw) if raw else {}
        lst = cfg.get(race_key)
        if isinstance(lst, list):
            hitb = False
            for e in lst:
                if (isinstance(e, dict) and not e.get("url")
                        and (e.get("label") or "Pending") == label):
                    e["url"] = url
                    hitb = True
            if hitb:
                set_app_setting("gg_champ_points_boards", json.dumps(cfg),
                                db_path=db_path)
    except Exception:
        logger.exception("persisting discovered board url (points dial)")
    try:
        raw = get_app_setting("gg_champ_scorecard_boards", db_path=db_path)
        cfg = json.loads(raw) if raw else {}
        cur = cfg.get(race_key)
        if cur is None:
            cfg[race_key] = [{"label": label, "url": url}]
        elif isinstance(cur, list):
            if any(isinstance(e, dict) and (e.get("label") or "") == label
                   for e in cur):
                return
            cur.append({"label": label, "url": url})
        else:
            return              # city-shape dict — not this race's concern
        set_app_setting("gg_champ_scorecard_boards", json.dumps(cfg),
                        db_path=db_path)
    except Exception:
        logger.exception("persisting discovered board url (scorecard dial)")


def _champ_fill_source(race_key: str,
                       db_path: str | Path = DB_PATH) -> "str | None":
    """The race whose scorecard roster backfills players missing from
    this race's points board — the 'fill_missing_from' flag on any of
    the race's gg_champ_points_boards entries (rules-as-data)."""
    try:
        board = champ_points_boards(db_path=db_path).get(race_key)
        for b in (board if isinstance(board, list)
                  else ([board] if board else [])):
            if isinstance(b, dict) and b.get("fill_missing_from"):
                return str(b["fill_missing_from"])
    except Exception:
        pass
    return None


def _champ_fill_thru_map(fill_race: str, label: str,
                         db_path: str | Path = DB_PATH) -> dict:
    """person-key -> raw Thru cell off the fill race's own board page.

    Pre-round that cell is the TEE TIME + hole assignment (Kerry
    2026-08-15 evening: non-Cup players' RD 2 cells sat blank while cup
    entrants showed '8:30 AM, Hole 18B'). The fill board (ALL Net) has
    no points column so _parse_champ_points_tables skips it entirely —
    this lighter parse wants only Player + Thru."""
    from golf_genius_sync import fetch_public_page, parse_page_structure
    board = champ_card_boards(db_path=db_path).get(fill_race)
    blist = board if isinstance(board, list) else ([board] if board else [])
    blist = [b for b in blist if isinstance(b, dict) and b.get("url")]
    if label:
        blist = [b for b in blist if (b.get("label") or "") == label]
    out: dict = {}
    for b in blist:
        try:
            page = fetch_public_page(b["url"], xhr=False)
            if page["status_code"] != 200:
                continue
            struct = parse_page_structure(page["html"], b["url"])
            for t in struct.get("tables") or []:
                rows = t if isinstance(t, list) else (t.get("rows") or [])
                hdr = None
                for row in rows:
                    cells = [re.sub(r"\s+", " ", (c or "")).strip()
                             for c in row]
                    low = [c.lower() for c in cells]
                    if "player" in low and "thru" in low:
                        hdr = {"player": low.index("player"),
                               "thru": low.index("thru")}
                        continue
                    if hdr is None or len(cells) <= max(hdr.values()):
                        continue
                    nm, th = cells[hdr["player"]], cells[hdr["thru"]]
                    if nm and th:
                        k = _cmp_person_key(_strip_gg_affiliation(nm))
                        if k[0] and k[1]:
                            out.setdefault(k, th)
        except Exception:
            logger.warning("fill thru-map parse failed for %r/%r",
                           fill_race, label, exc_info=True)
    return out


def _champ_points_fill_rows(race_key: str, fill_race: str, label: str,
                            have_keys: set,
                            db_path: str | Path = DB_PATH) -> list:
    """COMPUTED board rows for field players missing from the points
    board (Kerry, R1 live 2026-08-15: 'I know he's not in the Cup but I
    want everyone's totals to calculate' — Option B). GG's FELLOWSHIP
    CUP points game rosters only cup entrants, so everyone else's net
    championship Stableford is computed from the fill race's scorecard
    partials (THE PLAYERS CUP board carries the whole field, all 18
    strokes + handicap dots) with _champ_stableford — the same scale
    verified exact against GG's own cup-board totals. Any per-player
    failure skips that player; the fill never fails the board."""
    rows: list = []
    try:
        roster = _champ_card_roster(fill_race, db_path=db_path,
                                    board_label=label)
    except Exception:
        return rows
    if not roster.get("configured"):
        return rows
    missing = []
    for cid, entry in (roster.get("by_cid") or {}).items():
        nm = (entry or {}).get("name") or ""
        if nm and _cmp_person_key(nm) not in have_keys:
            missing.append((int(cid), nm))
    if not missing:
        return rows

    def _one(cid: int, nm: str):
        try:
            card = fetch_champ_player_card(race_key, cid,
                                           db_path=db_path,
                                           board_label=label,
                                           roster_race=fill_race)
            if not card.get("configured") or card.get("error"):
                return None
            played = sum(1 for h in (card.get("holes") or [])
                         if h.get("gross") is not None)
            pts = card.get("computed_points")
            thru = ("F" if played >= 18 else str(played)) if played else None
            return {"name": nm,
                    "points": (float(pts) if pts is not None else None),
                    "thru": thru,
                    "computed": True}
        except Exception:
            return None

    # ~15 missing players × several GG fetches each is too slow serially
    # for a live-poll endpoint — walk them concurrently.
    from concurrent.futures import ThreadPoolExecutor
    with ThreadPoolExecutor(max_workers=min(6, len(missing))) as pool:
        for row in pool.map(lambda a: _one(*a), missing):
            if row:
                rows.append(row)
    # Pre-round, a fill player's card has no holes so thru comes back
    # empty — borrow the fill board's own Thru cell, which carries the
    # TEE TIME + hole assignment until scoring starts (Kerry 2026-08-15
    # evening: non-Cup rows must show Sunday tee times like everyone
    # else). Card-derived thru always wins once they post a score.
    if any(r.get("thru") is None for r in rows):
        try:
            tee_map = _champ_fill_thru_map(fill_race, label, db_path=db_path)
            for r in rows:
                if r.get("thru") is None:
                    r["thru"] = tee_map.get(_cmp_person_key(r["name"]))
        except Exception:
            logger.warning("fill tee-time borrow failed", exc_info=True)
    return rows


def fetch_champ_points(race_key: str, max_age: float = 45.0,
                       db_path: str | Path = DB_PATH) -> dict:
    """LIVE championship points for one race, straight off the GG board.

    In-memory cached `max_age` seconds so a minute-polling scoreboard with
    many viewers collapses to one GG walk. Never writes; a GG failure
    returns the last good payload (marked stale) rather than nothing, so
    the leaderboard does not blank out mid-round."""
    import time as _t
    from golf_genius_sync import fetch_public_page, parse_page_structure

    boards = champ_points_boards(db_path=db_path)
    board = boards.get(race_key)
    # A race's dial entry may be a LIST of boards (Kerry 2026-08-02: "We
    # didn't wire up gross points from the championships to be added to
    # the players cup" — THE PLAYERS CUP is one cross-chapter race fed by
    # BOTH cities' championship gross boards). A single dict stays the
    # common case; any board failing fails the whole read so a half-cup
    # overlay never renders.
    #
    # MULTI-DAY (Kerry 2026-08-13, the TGF Championship: "track Day 1 AND
    # Day 2 totals to produce the winners"): a board may carry
    # "not_before": "YYYY-MM-DD" — it is IGNORED until that Central date,
    # so Day 2 can be staged in the dial on Wednesday without Saturday's
    # read failing on a board GG hasn't turned on yet. From its date
    # onward it participates fully, and a failure then IS a failure.
    entries = [b for b in (board if isinstance(board, list)
                           else ([board] if board else []))
               if isinstance(b, dict)]
    # Pending entries with a "discover" widget URL resolve themselves
    # the moment GG releases their round (Kerry 2026-08-13: "shouldn't
    # it automatically update?") — throttled, persisted, failure-safe.
    try:
        _champ_autodiscover_boards(race_key, entries, db_path=db_path)
    except Exception:
        pass
    from .timezone_utils import today_central_str
    _today = today_central_str()
    # A board with no url yet, or one date-gated by not_before, is
    # PENDING: it is not fetched, but its label still renders as a blank
    # column so the members see Round 2 coming (Kerry 2026-08-13: "I'd
    # like to see R2 show up now, even though it's blank").
    blist = [b for b in entries if b.get("url")
             and (not b.get("not_before") or str(b["not_before"]) <= _today)]
    pending_labels = [(b.get("label") or "Pending")
                      for b in entries if b not in blist]
    if not blist:
        return {"race": race_key, "configured": False, "players": [],
                "boards_pending": pending_labels}

    hit = _CHAMP_POINTS_CACHE.get(race_key)
    if hit and (_t.time() - hit[0]) < max_age:
        return hit[1]

    out = {"race": race_key, "configured": True,
           "label": " + ".join((b.get("label") or "Championship Points")
                               for b in blist),
           "url": blist[0]["url"], "players": [], "stale": False,
           "boards_pending": pending_labels}
    try:
        board_rows = []
        for b in blist:
            page = fetch_public_page(b["url"], xhr=False)
            if page["status_code"] != 200:
                raise RuntimeError(f"GG returned HTTP {page['status_code']}")
            struct = parse_page_structure(page["html"], b["url"])
            blabel = b.get("label") or "Championship Points"
            brows = _parse_champ_points_tables(struct.get("tables") or [])
            # COMPUTE-FILL (Kerry, R1 live 2026-08-15): field players
            # missing from this board get their points computed from the
            # fill race's scorecards — see _champ_points_fill_rows.
            if b.get("fill_missing_from"):
                try:
                    have = {_cmp_person_key(r["name"]) for r in brows}
                    brows = brows + _champ_points_fill_rows(
                        race_key, str(b["fill_missing_from"]), blabel,
                        have, db_path=db_path)
                except Exception:
                    logger.warning("champ compute-fill failed for %s/%s",
                                   race_key, blabel, exc_info=True)
            board_rows.append((blabel, brows))
        rows = [r for _, br in board_rows for r in br]
    except Exception as e:
        if hit:
            stale = dict(hit[1])
            stale["stale"] = True
            stale["error"] = str(e)
            return stale
        # No cache to re-serve — before giving up, a DECLARED-FINAL race
        # can serve its persisted final board (see the durability block
        # below): GG being down must not un-happen a finished championship.
        snap = _champ_final_board(race_key, db_path=db_path)
        if snap:
            out["players"] = snap
            out["source"] = "final_snapshot"
            out["error"] = str(e)
            out["scoring"] = sum(1 for p in snap
                                 if p.get("points") is not None)
            out["field"] = len(snap)
            _CHAMP_POINTS_CACHE[race_key] = (_t.time(), out)
            return out
        out["error"] = str(e)
        _CHAMP_POINTS_CACHE[race_key] = (_t.time(), out)
        return out

    if not rows:
        # GG answered but the board parsed to NOTHING — archived, emptied,
        # or repointed. For a declared-final race the persisted board
        # takes over (Kerry, close-out evening 2026-08-01: "Like the
        # event never happened. That shouldn't occur in any situation").
        # A non-final race keeps the empty read: cleared test scores must
        # still clear the overlay (same morning, same board).
        snap = _champ_final_board(race_key, db_path=db_path)
        if snap:
            out["players"] = snap
            out["source"] = "final_snapshot"
            out["scoring"] = sum(1 for p in snap
                                 if p.get("points") is not None)
            out["field"] = len(snap)
            _CHAMP_POINTS_CACHE[race_key] = (_t.time(), out)
            return out

    # MERGE PER PLAYER across boards (the two-day fix, Kerry 2026-08-13).
    # The old extend-only path was safe when a player appeared on exactly
    # ONE board (the two-city Players Cup case) but the downstream maps
    # keyed by customer_id OVERWROTE — a Day 2 row would have silently
    # replaced Day 1 instead of adding to it. Points now SUM across the
    # boards a player appears on (None + 3 = 3; all-None stays None so
    # "hasn't started" survives), each day rides along in `days`, and
    # `thru` follows the LAST configured board the player appears on —
    # which during Day 1 is Day 1, and on Day 2 is Day 2, so the
    # final-board detection upstream keeps meaning "today's round is
    # done". Single-board races reduce to the old behaviour exactly.
    with _connect(db_path) as conn:
        merged: dict = {}
        order: list = []
        for blabel, brows in board_rows:
            for r in brows:
                cid = None
                try:
                    cid, _how = _resolve_gg_person(conn, r["name"])
                except Exception:
                    cid = None
                mkey = (("cid", cid) if cid
                        else ("name", _cmp_person_key(r["name"])))
                if mkey not in merged:
                    merged[mkey] = {"name": r["name"], "customer_id": cid,
                                    "points": None, "thru": r.get("thru"),
                                    "days": []}
                    order.append(mkey)
                p = merged[mkey]
                if cid and not p.get("customer_id"):
                    p["customer_id"] = cid
                p["days"].append({"board": blabel,
                                  "points": r.get("points"),
                                  "thru": r.get("thru")})
                if r.get("points") is not None:
                    p["points"] = (p["points"] or 0.0) + r["points"]
                p["thru"] = r.get("thru")
        out["players"] = [merged[k] for k in order]
        out["boards"] = [bl for bl, _ in board_rows]

    # PLUS-HANDICAP DEDUCTION (Kerry, championship day 2026-08-01): the
    # plus values come off the companion scorecard board's
    # PlayingHandicap™ column, so no player is named in code and Austin
    # inherits the rule the moment a plus player appears there. The raw
    # board figure rides along so a diagnostic can always show both.
    # Not-started players (points None) are untouched — the deduction
    # lands with their first posted hole.
    try:
        adj = _champ_plus_adjustments(race_key, db_path=db_path)
    except Exception:
        adj = {"by_cid": {}, "by_key": {}}
    if adj["by_cid"] or adj["by_key"]:
        for p in out["players"]:
            plus = None
            if p.get("customer_id") and p["customer_id"] in adj["by_cid"]:
                plus = adj["by_cid"][p["customer_id"]]
            else:
                plus = adj["by_key"].get(_cmp_person_key(p["name"]))
            if plus and p.get("points") is not None:
                # Multi-day: the give-back applies PER ROUND — a plus
                # player's playing handicap comes off each day's points
                # (Kerry's championship rule, generalized 2026-08-13), so
                # the deduction is plus × the days they have posted on.
                _sdays = max(1, sum(1 for d in p.get("days") or []
                                    if d.get("points") is not None))
                p["points_raw"] = p["points"]
                p["plus_adjustment"] = plus * _sdays
                p["points"] = p["points"] - plus * _sdays
    out["scoring"] = sum(1 for p in out["players"] if p["points"] is not None)
    out["field"] = len(out["players"])

    # FINAL-RESULT DURABILITY (Kerry, close-out evening 2026-08-01): once
    # the race is DECLARED final (gg_points_race_final dial) and every
    # player on the board has posted, persist the finished board —
    # adjusted points, resolved customer_ids — to app_settings. From then
    # on the overlay survives GG archiving, emptying, or repointing the
    # champ board: the result is OURS, served by the fallbacks above
    # until the double-count guard sees GG's season totals absorb it.
    # Written once per race (the first final read after the declaration).
    try:
        # A fully-posted board persists once the race is DECLARED final —
        # or once the season reset is OFFICIAL (the city championships are
        # certainly over then), which covers races that continue past the
        # reset and are never themselves "final" (THE PLAYERS CUP runs on
        # to the TGF Championship, so its race_final never flips).
        if (out["players"] and out["scoring"] == out["field"]
                and (_points_race_final(race_key, db_path=db_path)
                     or _points_reset_official(db_path=db_path))):
            skey = f"gg_champ_final_board_{race_key}"
            if not get_app_setting(skey, db_path=db_path):
                from .timezone_utils import today_central_str
                set_app_setting(skey, json.dumps(
                    {"date": today_central_str(),
                     "players": out["players"]}), db_path=db_path)
    except Exception:
        logger.warning("final champ board persist failed for %r",
                       race_key, exc_info=True)

    _CHAMP_POINTS_CACHE[race_key] = (_t.time(), out)
    return out


def _split_down_ladder(rows: list, amounts: list) -> list:
    """Walk ENROLLED finishers down a payout ladder — the server-side
    mirror of the page's prSplitDown (ratified universal rule 2, Kerry
    2026-07-10): tied rank labels split the combined money of the places
    they jointly occupy, exact cents by largest remainder. rows must
    already be enrolled-only and in final order; money flows past
    non-enrolled players upstream of this call."""
    out = []
    place, i = 0, 0
    while i < len(rows) and place < len(amounts):
        j = i + 1
        while (j < len(rows)
               and str(rows[j].get("rank")) == str(rows[i].get("rank"))):
            j += 1
        k = j - i
        combined = sum(amounts[place:place + k])
        base, rem = divmod(combined, k)
        for g in range(k):
            out.append({**rows[i + g],
                        "amount_cents": base + (1 if g < rem else 0)})
        place += k
        i = j
    return out


def season_race_payout_rows(race_key: str,
                            db_path: str | Path = DB_PATH) -> dict:
    """FINAL City NET place money, assigned to the live final standings
    (Kerry, championship evening 2026-08-01: "need payouts for the Points
    Net for both Chapters"). Enrolled-only — the money flows past
    non-enrolled rows to the next bought-in player down — ties split
    combined places; ladder + pot from the ratified season_payouts rules
    on the SAME entrant count the page's projection uses."""
    from . import season_payouts as _sp
    d = get_points_race_live(race_key, db_path=db_path)
    enrolled = [
        {"customer_id": r.get("customer_id"),
         "golferName": r.get("player_name"),
         "rank": r.get("rank"),
         "total_points": r.get("total_points")}
        for r in (d.get("standings") or []) if r.get("enrolled")]
    n_pot = len(enrolled) + len(d.get("enrolled_not_ranked") or [])
    pp = _sp.city_net_payouts(n_pot)
    if not pp:
        return {"error": f"no pot for {race_key} (n={n_pot})"}
    return {"race": race_key, "label": d.get("label"),
            "chapter": d.get("chapter"),
            "race_final": bool(d.get("race_final")),
            "n_pot": n_pot, "pot_cents": pp["pot_cents"],
            "n_places": len(pp["amounts_cents"]),
            "amounts_cents": pp["amounts_cents"],
            "rows": _split_down_ladder(enrolled, pp["amounts_cents"])}


def matchplay_final_payout_rows(chapter: str, placements: list,
                                season: str = "2026",
                                db_path: str | Path = DB_PATH) -> dict:
    """City Match Play podium money (Kerry: "payouts for Austin match
    play 1st thru 3rd"). placements = ordered names from 1st down, one
    per paid place — a 3rd-place playoff means no ties here. N and the
    ladder come from the same sources the bracket runs on: the season's
    PINNED config + the live enrollment count (principle 4). Pool-winner
    bonuses are deliberately excluded — they belong to the pool stage."""
    from email_parser.match_play import structure_for_n
    active = sct_get_active_config("match_play", season, chapter,
                                   db_path=db_path)
    if not active:
        return {"error": "no Match Play config template"}
    n = len(cmp_enrolled_entrants(season, chapter, db_path=db_path))
    structure = structure_for_n(active["config"], n)
    amounts = structure["ladder_amounts_cents"]
    if len(placements) != len(amounts):
        return {"error": f"the N={n} ladder pays {len(amounts)} places; "
                         f"got {len(placements)} placements"}
    _ord = ("1st", "2nd", "3rd", "4th", "5th", "6th", "7th")
    rows = []
    with _connect(db_path) as conn:
        for i, name in enumerate(placements):
            try:
                cid, _how = _resolve_gg_person(conn, name)
            except Exception:
                cid = None
            canon = None
            if cid:
                c = conn.execute(
                    "SELECT first_name || ' ' || last_name AS n "
                    "FROM customers WHERE customer_id = ?", (cid,)).fetchone()
                canon = (c["n"] or "").strip() if c else None
            rows.append({"customer_id": cid, "golferName": canon or name,
                         "rank": _ord[i], "amount_cents": amounts[i]})
    return {"chapter": chapter, "season": season, "n": n,
            "pot_cents": structure["pot_cents"],
            "adjusted_pot_cents": structure["adjusted_pot_cents"],
            "pool_bonus_note": (f"{structure['pools']} pool-winner bonuses of "
                                f"${structure['pool_winner_bonus_each']:.0f}"
                                " excluded — pool-stage money, not podium"),
            "rows": rows}


def matchplay_pool_bonus_rows(chapter: str, season: str = "2026",
                              db_path: str | Path = DB_PATH) -> dict:
    """Pool-winner bonuses (Kerry, championship evening 2026-08-01: "I
    think pool stage money still needs to be paid"). The $/pool taken off
    the top of the Match Play pot before the podium ladder — one bonus
    per pool, to its rank-1 finisher under the season's PINNED ranking
    rule (D-MP-09 where configured). Withdrawn players never win a pool."""
    from email_parser.match_play import structure_for_n
    active = sct_get_active_config("match_play", season, chapter,
                                   db_path=db_path)
    if not active:
        return {"error": "no Match Play config template"}
    n = len(cmp_enrolled_entrants(season, chapter, db_path=db_path))
    structure = structure_for_n(active["config"], n)
    bonus = structure.get("bonus_each_cents") or 0
    if not bonus:
        return {"error": f"no pool-winner bonus configured for N={n}"}
    standings = cmp_get_standings(season, chapter, db_path=db_path)
    winners = [s for s in standings
               if s.get("rank") == 1 and not s.get("withdrawn")]
    rows = []
    with _connect(db_path) as conn:
        for w in winners:
            try:
                cid, _how = _resolve_gg_person(conn, w["player_name"])
            except Exception:
                cid = None
            rows.append({"customer_id": cid,
                         "golferName": w["player_name"],
                         "rank": f"{w['pool_name']} winner",
                         "amount_cents": bonus})
    return {"chapter": chapter, "season": season, "n": n,
            "pools": structure.get("pools"),
            "bonus_each_cents": bonus, "rows": rows}


def record_season_contest_payouts(code: str, chapter: str, payouts: list,
                                  append_category: str | None = None,
                                  db_path: str | Path = DB_PATH) -> dict:
    """Record season-contest final winnings as TGF PAYOUTS rows.

    Unlike record_event_game_payouts there is no calendar `events` row
    behind a season race, so the tgf_events row is found-or-created
    directly by code (the race label + ' FINAL'). Refuses to
    double-record: ANY existing payout rows on that code stop the write
    (delete them on the TGF Payouts page first). append_category relaxes
    that to CATEGORY scope — a later wave (e.g. pool-winner bonuses) may
    join an event that already carries podium rows, but never a second
    copy of its own category. Inserting delegates to import_tgf_payouts
    so customer resolution, the prize_payout ledger entry, and Venmo
    reconciliation reuse the proven path."""
    from .timezone_utils import today_central_str
    if not payouts:
        return {"error": "no payout rows"}
    with _connect(db_path) as conn:
        trow = conn.execute(
            "SELECT id FROM tgf_events WHERE LOWER(code) = ?",
            (code.lower(),)).fetchone()
        if trow:
            tgf_event_id = trow["id"]
        else:
            cur = conn.execute(
                "INSERT INTO tgf_events (code, name, event_date, course, "
                "chapter) VALUES (?, ?, ?, ?, ?)",
                (code, code, today_central_str(), "", chapter or ""))
            tgf_event_id = cur.lastrowid
        if append_category:
            existing = conn.execute(
                "SELECT COUNT(*) FROM tgf_payouts WHERE event_id = ? "
                "AND category = ?",
                (tgf_event_id, append_category)).fetchone()[0]
        else:
            existing = conn.execute(
                "SELECT COUNT(*) FROM tgf_payouts WHERE event_id = ?",
                (tgf_event_id,)).fetchone()[0]
        if existing:
            what = (f"{append_category!r} " if append_category else "")
            return {"error": f"{existing} {what}payout row(s) already "
                             f"recorded on {code!r} — manage them on the "
                             "TGF Payouts page instead"}
        conn.commit()
    got = import_tgf_payouts(tgf_event_id, payouts, db_path=db_path)
    return {"code": code, "tgf_event_id": tgf_event_id, **got}


def _race_champions(rows: list) -> list:
    """The FINAL champion(s) of a points race: the best-ranked ENROLLED
    row, plus any enrolled rows sharing that rank label. Kerry-ratified
    2026-08-01: a T1 finish makes CO-CHAMPIONS, who become Lone Star Cup
    CO-CAPTAINS occupying two of the chapter's seven NET-path seats (the
    captain seat plus one Fellowship Cup seat). Non-enrolled rows can
    top the table but never hold the title — same eligibility as the
    money."""
    enrolled = [r for r in rows or [] if r.get("enrolled")]
    if not enrolled:
        return []
    top = str(enrolled[0].get("rank"))
    return [{"customer_id": r.get("customer_id"),
             "player_name": r.get("player_name")}
            for r in enrolled if str(r.get("rank")) == top]


def rename_tgf_event(old_code: str, new_code: str,
                     db_path: str | Path = DB_PATH) -> dict:
    """Rename a tgf_events row's code + name (Kerry 2026-08-02: "I don't
    think 'FINAL' is necessary in the event name"). Refuses when the new
    code already belongs to a different event — payouts/matching key on
    the code, so a silent merge would cross-wire two events' money."""
    old_code = (old_code or "").strip()
    new_code = (new_code or "").strip()
    if not old_code or not new_code:
        return {"error": "need old and new codes"}
    with _connect(db_path) as conn:
        src = conn.execute(
            "SELECT id FROM tgf_events WHERE LOWER(code) = ?",
            (old_code.lower(),)).fetchone()
        if not src:
            return {"error": f"no tgf_event with code {old_code!r}"}
        clash = conn.execute(
            "SELECT id FROM tgf_events WHERE LOWER(code) = ? AND id != ?",
            (new_code.lower(), src["id"])).fetchone()
        if clash:
            return {"error": f"code {new_code!r} already exists "
                             f"(event {clash['id']}) — refusing to merge"}
        conn.execute("UPDATE tgf_events SET code = ?, name = ? WHERE id = ?",
                     (new_code, new_code, src["id"]))
        conn.commit()
    return {"renamed": True, "event_id": src["id"],
            "from": old_code, "to": new_code}


def _points_race_final(race_key: str, db_path: str | Path = DB_PATH) -> bool:
    """Is this points race DECLARED final? (Kerry, championship evening
    2026-08-01: "Can you now show winnings for the finishers. City Net is
    final.") A dial, not a derivation — 'final' is a business call the
    admin makes once the scores stand, not something the board's display
    state can prove. app_settings 'gg_points_race_final' holds JSON
    {race_key: truthy (date string by convention)}; the UI flips the
    winnings badges from PROJECTED to WON when set. Cleared/absent =
    still projecting."""
    try:
        raw = get_app_setting("gg_points_race_final", db_path=db_path)
        if not raw:
            return False
        fin = json.loads(raw)
        return bool(isinstance(fin, dict) and fin.get(race_key))
    except Exception:
        return False


def _points_reset_official(db_path: str | Path = DB_PATH) -> bool:
    """Has GG actually PERFORMED the season points reset? (Kerry,
    2026-08-02: "Points Resets have occurred so they don't need to show
    Projected".) A dial like race_final — 'gg_points_reset_official'
    truthy means the reset columns stop reading '(Projected)' and the
    Players Cup leads with the reset number. Clear the dial next season
    while the new races are projecting again."""
    v = (get_app_setting("gg_points_reset_official", db_path=db_path)
         or "").strip().lower()
    return v not in ("", "0", "false", "no", "off")


def _champ_absorbed_check(race_key: str, base: dict, live: dict,
                          db_path: str | Path = DB_PATH) -> bool:
    """Has GG folded the (final) championship board into the season
    snapshot yet? CONTENT-based (v2.185.1, Kerry: "SA is not persisting
    now the round is over").

    The old guard treated ANY same-day snapshot as proof of absorption,
    so the overlay stood down the moment the last group finished — the
    morning's pre-round snapshot was "fetched today" — and the whole
    championship vanished from the standings hours before close-out. GG
    only moves season totals at CLOSE-OUT, so the test is now what the
    data says, not what the clock says: the first time the board reads
    final, capture each champ scorer's snapshot total as a baseline
    (app_settings, per race, dated today); ABSORBED = a majority of
    those totals have since MOVED. A pre-close-out refresh changes
    nothing (there is no other event today) and keeps the overlay live;
    the close-out refresh moves everyone at once and stands it down.
    Any failure returns False — showing live points twice-removed is
    worse than showing them until the next read."""
    from .timezone_utils import today_central_str
    key = f"gg_champ_absorb_baseline_{race_key}"
    champ_cids = {p["customer_id"] for p in live.get("players", [])
                  if p.get("customer_id") and p.get("points") is not None}
    if not champ_cids:
        return False
    totals = {r["customer_id"]: r.get("total_points")
              for r in base.get("standings", []) or []
              if r.get("customer_id") in champ_cids}
    if not totals:
        return False
    try:
        today = today_central_str()
        raw = get_app_setting(key, db_path=db_path)
        state = json.loads(raw) if raw else None
        # Once absorbed, absorbed FOREVER — GG never un-absorbs a
        # closed-out event, and re-baselining would restart the double
        # count (v2.201.1).
        if isinstance(state, dict) and state.get("absorbed"):
            return True
        if not isinstance(state, dict) or not state.get("baseline"):
            # First final read -> capture the pre-close-out baseline ONCE.
            # NOT date-scoped (v2.201.1, Kerry emergency 2026-08-06): GG's
            # close-out can land DAYS after the board goes final — the 2026
            # city championships closed out ~Aug 5, and the old date-scoped
            # baseline re-captured every morning from already-absorbed
            # totals, so "moved" never tripped and the overlay double-added
            # championship points onto GG totals that already contained
            # them, both chapters.
            set_app_setting(key, json.dumps(
                {"date": today,
                 "baseline": {str(c): t for c, t in totals.items()}}),
                db_path=db_path)
            return False
        baseline = state.get("baseline") or {}
        tracked = [c for c in totals if str(c) in baseline]
        moved = sum(
            1 for c in tracked
            if totals[c] is not None and baseline[str(c)] is not None
            and abs(float(totals[c]) - float(baseline[str(c)])) > 1e-6)
        absorbed = bool(tracked) and moved * 2 > len(tracked)
        if absorbed:
            state["absorbed"] = True
            state["absorbed_at"] = today
            set_app_setting(key, json.dumps(state), db_path=db_path)
        return absorbed
    except Exception:
        logger.warning("champ absorption check failed for %r — keeping the "
                       "live overlay up", race_key, exc_info=True)
        return False


def _reproject_points_reset(rows: list, reset_info: dict | None) -> None:
    """Recompute the reset-ladder projection over rows in their CURRENT
    order — the live re-ranked order (Kerry, championship day 2026-08-01:
    "I'm currently 3rd for SA City Net, but I'm projecting at 97.5 and I
    should be 99 with 3rd" — the season pass projected the ladder off the
    SEASON order and the live merge carried it through unchanged, so every
    mover kept their pre-round reset all day).

    Eligibility is EXACTLY the season pass's: the rows it gave a reset
    value (membership/played-once doesn't change mid-round). Same master
    ladder, same coefficient — rebuilt exact from reset_info's counts
    (the stored `coefficient` is rounded to 4dp for display); only the
    positions are live. Mutates rows in place."""
    ri = reset_info or {}
    if ri.get("anchor_count") and ri.get("eligible_count"):
        coef = ri["anchor_count"] / ri["eligible_count"]
    else:
        coef = ri.get("coefficient")
    if not coef:
        return
    elig = [r for r in rows if r.get("points_reset") is not None]
    prev_pts, prev_pos = object(), 0
    for i, r in enumerate(elig):
        cur = r.get("live_total", r.get("total_points"))
        pos = prev_pos if cur == prev_pts else i + 1
        prev_pts, prev_pos = cur, pos
        # int(x + 0.5) == Excel ROUND for positive x (half up) — must stay
        # identical to the season pass or the two projections drift
        master = int(1 + coef * (pos - 1) + 0.5)
        r["points_reset"] = 100 - 0.5 * (master - 1)


def get_points_race_live(race_key: str, force_refresh: bool = False,
                         db_path: str | Path = DB_PATH) -> dict:
    """Season standings PLUS today's championship points, added together.

    Kerry's rule: the championship is IN ADDITION to the season total, so
    a player's live figure is their stored best-10 season total plus
    whatever they have earned on the championship board so far. Matching
    is by customer_id first and name only as a fallback (principle 6) —
    Golf Genius spells people its own way, which is exactly how points
    went missing before.
    """
    base = get_points_race_standings(race_key, force_refresh=force_refresh,
                                     db_path=db_path)
    live = fetch_champ_points(race_key, db_path=db_path)

    # DOUBLE-COUNT GUARD (Kerry 2026-07-31; rebuilt 2026-08-01 after the
    # first version dropped SA the moment the round ended). Golf Genius
    # does not award season points until the manager closes the event out
    # — so while the round runs, and for the hours between the last putt
    # and close-out, the stored snapshot has no championship in it and
    # adding the live board is exactly right. Once close-out lands and
    # the snapshot refreshes, GG's own totals already contain the
    # championship, and adding the board again would inflate everyone by
    # their championship score. Whether that has happened is decided by
    # CONTENT (_champ_absorbed_check: did the snapshot totals move off
    # the board-went-final baseline?), never by the snapshot's date — the
    # morning's pre-round snapshot is also "fetched today".
    # "Final" includes a BLANK thru: once the round completes GG clears
    # the Thru cells entirely (seen live ~4 PM 2026-08-01 — every SA row
    # read points + empty thru, not "F"). A scoring player mid-round
    # always carries a hole count, so blank-with-points only happens on a
    # completed board; and even a false positive here is harmless because
    # the absorption check still requires the snapshot totals to have
    # actually moved before anything stands down.
    _final = bool(live.get("players")) and all(
        (str(p.get("thru") or "").strip().upper() in ("F", "18", "")
         or p.get("points") is None)
        for p in live.get("players", []))
    if _final and _champ_absorbed_check(race_key, base, live,
                                        db_path=db_path):
        out = dict(base)
        out["champ"] = {k: v for k, v in live.items() if k != "players"}
        out["champ_scoring"] = 0
        out["champ_absorbed"] = True
        return out

    # EVERY board player goes in the maps — including the not-yet-started,
    # whose Thru cell carries their TEE TIME (Kerry 2026-08-01: the live
    # table reads like a PGA leaderboard — today's points, thru, or the
    # tee time if they haven't started). Points stay None until they post.
    by_cid, by_name = {}, {}
    for p in live.get("players", []):
        if p.get("customer_id"):
            by_cid[p["customer_id"]] = p
        for cand in _gg_name_candidates(p["name"]):
            by_name.setdefault(cand.strip().lower(), p)

    # Post-reset CUP RESOLUTION (Kerry 2026-08-13: the championship rounds
    # "add to the Points Reset for an overall total"). Once the season
    # reset is OFFICIAL, a race with LIVE championship boards resolves on
    # reset + championship — the season total was the CITY currency and
    # already crowned its champions. Gating on configured boards leaves
    # every final city board exactly as it stands (their champ boards
    # were emergency-unconfigured 2026-08-06).
    _cup_mode = (live.get("configured") is True
                 and _points_reset_official(db_path=db_path))

    rows = []
    for r in base.get("standings", []) or []:
        row = dict(r)
        season = row.get("total_points")
        season = float(season) if season is not None else 0.0
        hit = None
        if row.get("customer_id") and row["customer_id"] in by_cid:
            hit = by_cid[row["customer_id"]]
        elif (row.get("player_name") or "").strip().lower() in by_name:
            hit = by_name[(row["player_name"] or "").strip().lower()]
        champ = (float(hit["points"])
                 if hit and hit.get("points") is not None else None)
        row["season_points"] = round(season, 2)
        row["season_rank"] = row.get("rank")
        row["champ_points"] = champ
        # thru carries for anyone ON today's board: a hole count / "F" once
        # scoring, the tee time before that. Absent entirely for players
        # not entered in the championship — the column can tell the three
        # states apart.
        row["champ_thru"] = hit.get("thru") if hit else None
        # Plus-handicap deduction already applied to champ_points in
        # fetch_champ_points; the size rides along so the drill-down can
        # say so instead of leaving the smaller figure unexplained.
        row["champ_plus"] = hit.get("plus_adjustment") if hit else None
        # Per-round split (Round 1 / Round 2) for the cup columns
        row["champ_days"] = hit.get("days") if hit else None
        row["live_total"] = round(season + (champ or 0.0), 2)
        if _cup_mode:
            row["cup_total"] = round(float(row.get("points_reset") or 0.0)
                                     + (champ or 0.0), 2)
            row["live_total"] = row["cup_total"]
        rows.append(row)

    # Championship POSITION for the drill-down's CITY CHAMPIONSHIP row
    # (Kerry 2026-08-03: "POSITION should populate"): rank on the champ
    # board among scorers, ties T-labelled.
    _scorers = sorted((r for r in rows if r.get("champ_points") is not None),
                      key=lambda r: -r["champ_points"])
    _i = 0
    while _i < len(_scorers):
        _j = _i
        while (_j < len(_scorers)
               and _scorers[_j]["champ_points"] == _scorers[_i]["champ_points"]):
            _j += 1
        _lbl = ("T" if _j - _i > 1 else "") + str(_i + 1)
        for _k in range(_i, _j):
            _scorers[_k]["champ_rank"] = _lbl
        _i = _j

    # Re-rank on the live total; ties keep the season order behind them.
    rows.sort(key=lambda r: (-r["live_total"], -(r.get("season_points") or 0),
                             (r.get("player_name") or "").lower()))
    for i, r in enumerate(rows, start=1):
        r["live_rank"] = i
        # Overwrite the field the standings table already renders, so the
        # combined figure shows everywhere with no display surgery — and the
        # season-only numbers stay available beside them.
        r["total_points"] = r["live_total"]

    # COMPETITION RANKING on the live total (Kerry 2026-08-01, from the
    # course: "Rankings aren't accounting for ties"). Three players on 94
    # are T2/T2/T2 with the next man 5th — a plain enumerate mislabels
    # every tie. DAY movement compares COMPETITION ranks too (Kerry again,
    # minutes later: "Shouldn't Mary show movement if she's now in a tie
    # for 2nd?") — a player climbing from 4th into a T2 is UP 2 even
    # though her ROW position, ordered by season points inside the tie,
    # never moved.
    i = 0
    while i < len(rows):
        j = i + 1
        while j < len(rows) and rows[j]["live_total"] == rows[i]["live_total"]:
            j += 1
        label = ("T" if j - i > 1 else "") + str(i + 1)
        for g in range(i, j):
            rows[g]["rank"] = label
            try:
                _was = int(re.sub(r"[^0-9]", "",
                                  str(rows[g].get("season_rank") or "")))
                rows[g]["move"] = _was - (i + 1) if _was else None
            except (TypeError, ValueError):
                rows[g]["move"] = None
        i = j

    # The reset projection follows the LIVE order (Kerry, championship
    # day) — see _reproject_points_reset. Only fires when something is
    # actually on the board; a quiet day leaves the season figures alone.
    # NOT in cup mode: once the reset is OFFICIAL the ladder is settled
    # history — the TGF Championship ADDS to each player's reset, it does
    # not reshuffle it (re-projecting off the live order fed the champ
    # points back into the reset and cup_total disagreed with the reset
    # column, seen on the 08-13 test scores).
    if (any(r.get("champ_points") is not None for r in rows)
            and not _cup_mode):
        _reproject_points_reset(rows, base.get("reset_info"))

    # Championship date for the drill-down's DATE column (Kerry 2026-08-03)
    # — the final dial stores {race_key: date} by convention.
    champ_date = None
    try:
        _raw = get_app_setting("gg_points_race_final", db_path=db_path)
        _v = (json.loads(_raw) if _raw else {}).get(race_key)
        if isinstance(_v, str) and re.match(r"\d{4}-\d{2}-\d{2}", _v):
            champ_date = _v
    except Exception:
        pass

    # Championship course per chapter (Kerry 2026-08-03: the course name
    # rides a second line under the CITY CHAMPIONSHIP row) — off the
    # championship-day events, never guessed. Cross-chapter races (the
    # cups) carry both chapters' courses; the row picks by player chapter.
    champ_courses: dict = {}
    if champ_date:
        try:
            with _connect(db_path) as _c:
                for _e in _c.execute(
                        """SELECT chapter, course FROM events
                           WHERE UPPER(item_name) LIKE '%CHAMPIONSHIP%'
                             AND event_date = ? AND COALESCE(course,'') != ''""",
                        (champ_date,)).fetchall():
                    if _e["chapter"]:
                        champ_courses[_e["chapter"]] = _e["course"]
        except Exception:
            pass

    return {**{k: v for k, v in base.items() if k != "standings"},
            "standings": rows,
            # champions follow the LIVE final order, not the season order
            "champions": (_race_champions(rows)
                          if base.get("race_final") else None),
            "champ": {k: v for k, v in live.items() if k != "players"},
            "champ_date": champ_date,
            "champ_courses": champ_courses,
            "champ_scoring": live.get("scoring", 0),
            "champ_field": live.get("field", 0),
            # TEST PHASE dial (Kerry 2026-08-13) — see the fellowship
            # payload's twin field; same setting drives both boards.
            "champ_test_phase": (get_app_setting("gg_champ_test_phase",
                                                 db_path=db_path) or "")
                == "1"}


# ── LIVE championship hole-by-hole card (Kerry's ask, built 2026-08-01) ──
# The champ POINTS board carries totals only; per-hole detail lives on the
# companion scorecard board ("ALL Net 18" — every championship player has a
# row). Player-name links on that page point straight at the player's own
# tournaments2/details partial, so one board fetch + one partial fetch
# serves a card — no full-roster walk. Held as a DIAL
# (app_settings 'gg_champ_scorecard_boards') like the points boards.
_GG_CHAMP_CARD_BOARDS_DEFAULT: dict = {
    "san_antonio_net": {
        "label": "ALL Net 18",
        "url": ("https://tgf-sa.golfgenius.com/v2tournaments/4779120"
                "?player_stats_for_portal=true&round_index=35"),
    },
    "austin_net": {
        "label": "ALL Net 18",
        "url": ("https://tgf-austin.golfgenius.com/v2tournaments/4779165"
                "?player_stats_for_portal=true&round_index=31"),
    },
    # THE PLAYERS CUP is one cross-chapter race — its hole-by-hole cards
    # live on BOTH cities' championship scorecard boards (same boards as
    # the net races; the per-hole gross + pars are shared facts). A LIST
    # entry merges the rosters, mirroring the points-boards dial shape
    # (Kerry 2026-08-03: "No scorecard showing for city champ").
    "players_cup_gross": [
        {
            "label": "ALL Net 18",
            "url": ("https://tgf-sa.golfgenius.com/v2tournaments/4779120"
                    "?player_stats_for_portal=true&round_index=35"),
        },
        {
            "label": "ALL Net 18",
            "url": ("https://tgf-austin.golfgenius.com/v2tournaments/4779165"
                    "?player_stats_for_portal=true&round_index=31"),
        },
    ],
}

_CHAMP_ROSTER_CACHE: dict = {}   # race_key -> (epoch, roster dict)
_CHAMP_CARD_CACHE: dict = {}     # (race_key, customer_id) -> (epoch, payload)
_CHAMP_TEE_CACHE: dict = {}      # nets URL -> tee block (pars don't change mid-round)


def champ_card_boards(db_path: str | Path = DB_PATH) -> dict:
    """The configured championship scorecard boards, dial over default."""
    try:
        raw = get_app_setting("gg_champ_scorecard_boards", db_path=db_path)
    except sqlite3.OperationalError:
        raw = None          # app_settings not created yet — use the defaults
    if raw:
        try:
            got = json.loads(raw)
            if isinstance(got, dict) and got:
                return got
        except (ValueError, TypeError):
            logger.warning("gg_champ_scorecard_boards is not valid JSON — "
                           "using the built-in board list")
    return dict(_GG_CHAMP_CARD_BOARDS_DEFAULT)


def _champ_card_roster(race_key: str, max_age: float = 120.0,
                       db_path: str | Path = DB_PATH,
                       board_label: "str | None" = None) -> dict:
    """cid/person-key -> details-partial URL, off the scorecard board page.

    The board lists every player as a link to their own
    tournaments2/details partial (verified live 2026-08-01: link text is
    the bare 'SURNAME, First', no affiliation). Names resolve to
    customer_id up front (principle 6) so the card lookup never
    string-compares."""
    import time as _t
    from golf_genius_sync import fetch_public_page, parse_page_structure

    _rk = (race_key, board_label)
    hit = _CHAMP_ROSTER_CACHE.get(_rk)
    if hit and (_t.time() - hit[0]) < max_age:
        return hit[1]

    board = champ_card_boards(db_path=db_path).get(race_key)
    # A race entry may be a LIST of boards (players_cup_gross spans both
    # cities' scorecard boards) — same shape as the points-boards dial.
    blist = board if isinstance(board, list) else ([board] if board else [])
    blist = [b for b in blist if isinstance(b, dict) and b.get("url")]
    # Per-round cards (Kerry 2026-08-13: "scorecards for both rounds with
    # toggles for Round 1 v Round 2") — a board_label narrows the walk to
    # that round's scorecard board.
    if board_label:
        blist = [b for b in blist if (b.get("label") or "") == board_label]
    if not blist:
        roster = {"configured": False, "by_cid": {}, "by_key": {}}
        _CHAMP_ROSTER_CACHE[_rk] = (_t.time(), roster)
        return roster
    roster = {"configured": True, "url": blist[0]["url"],
              "by_cid": {}, "by_key": {}, "plus_by_cid": {}, "plus_by_key": {}}
    with _connect(db_path) as conn:
        for b in blist:
            page = fetch_public_page(b["url"], xhr=False)
            if page["status_code"] != 200:
                raise RuntimeError(f"GG returned HTTP {page['status_code']}")
            struct = parse_page_structure(page["html"], b["url"])
            plus_names = _parse_champ_plus_column(struct.get("tables") or [])
            for l in struct.get("links") or []:
                href = l.get("href") or ""
                name = re.sub(r"\s+", " ", (l.get("text") or "")).strip()
                if not re.search(r"/tournaments2/details/\d+", href) or not name:
                    continue
                entry = {"name": name, "url": href}
                try:
                    cid, _how = _resolve_gg_person(conn, name)
                except Exception:
                    cid = None
                if cid and cid not in roster["by_cid"]:
                    roster["by_cid"][cid] = entry
                k = _cmp_person_key(name)
                if k[0] and k[1]:
                    roster["by_key"].setdefault(k, entry)
            # Plus-handicap deductions ride the same board walk (Kerry's
            # championship rule — see _parse_champ_plus_column).
            for name, plus in plus_names.items():
                try:
                    cid, _how = _resolve_gg_person(conn, name)
                except Exception:
                    cid = None
                if cid:
                    roster["plus_by_cid"].setdefault(cid, plus)
                k = _cmp_person_key(name)
                if k[0] and k[1]:
                    roster["plus_by_key"].setdefault(k, plus)
    _CHAMP_ROSTER_CACHE[_rk] = (_t.time(), roster)
    return roster


def _champ_stableford(net_vs_par, gross) -> "int | None":
    """Championship-scale Stableford for one hole (the ratified chart:
    triple/double 0, bogey 1, par 2, birdie 3, eagle 4, double eagle 5 —
    one above the regular scale in every category; a GROSS ace pays 9
    regardless of net). The chart ENDS at 5 — KERRY-RATIFIED 2026-08-14:
    "We need to max out at 5 for Net scoring which would be for double
    eagle. Triple eagle net would be 5 too." Matches GG's own bucket
    (caught 2026-08-13 on a net 4-under test hole — we paid 6, GG's own
    per-hole row and board both paid 5, and the board is official)."""
    if net_vs_par is None:
        return None
    if gross == 1:
        return 9
    return min(5, max(0, 2 - int(net_vs_par)))


def fetch_champ_player_card(race_key: str, customer_id: int,
                            max_age: float = 45.0,
                            db_path: str | Path = DB_PATH,
                            board_label: "str | None" = None,
                            roster_race: "str | None" = None) -> dict:
    """One player's LIVE championship hole-by-hole card, off GG.

    Per-hole gross + handicap dots come from the player's scorecard
    partial; pars from the tee (nets) partial; NET and championship-scale
    Stableford are computed HERE from those facts rather than trusted, and
    the payload carries the champ board's own total beside ours so a
    disagreement is visible, never silently absorbed. Cached `max_age`
    seconds per (race, player); a GG failure re-serves the last good card
    marked stale, exactly like fetch_champ_points."""
    import time as _t
    from urllib.parse import urlparse
    from golf_genius_sync import (fetch_public_page, parse_scorecard_details,
                                  parse_tee_block, _unwrap_js_string,
                                  _unwrap_js_strings)

    ck = (race_key, int(customer_id), board_label, roster_race)
    hit = _CHAMP_CARD_CACHE.get(ck)
    if hit and (_t.time() - hit[0]) < max_age:
        return hit[1]

    try:
        roster = _champ_card_roster(roster_race or race_key,
                                    db_path=db_path,
                                    board_label=board_label)
        if not roster.get("configured"):
            return {"race": race_key, "configured": False, "holes": []}
        entry = roster["by_cid"].get(int(customer_id))
        if not entry and not roster_race:
            # COMPUTE-FILL players (Kerry, R1 live 2026-08-15) aren't on
            # this race's own scorecard board — their card comes off the
            # fill race's roster, so row expansions work for everyone.
            _fs = _champ_fill_source(race_key, db_path=db_path)
            if _fs:
                try:
                    _r2 = _champ_card_roster(_fs, db_path=db_path,
                                             board_label=board_label)
                    entry = (_r2.get("by_cid") or {}).get(int(customer_id))
                except Exception:
                    entry = None
        if not entry:
            out = {"race": race_key, "configured": True, "holes": [],
                   "error": "player not on the championship scorecard board"}
            _CHAMP_CARD_CACHE[ck] = (_t.time(), out)
            return out

        resp = fetch_public_page(entry["url"], xhr=True)
        if resp["status_code"] != 200:
            raise RuntimeError(f"GG returned HTTP {resp['status_code']}")
        frag = _unwrap_js_strings(resp["html"]) or resp["html"]
        parsed = parse_scorecard_details(frag)
        want = _cmp_person_key(entry["name"])
        player = next((p for p in parsed["players"]
                       if _cmp_person_key(p.get("player_name") or "") == want),
                      parsed["players"][0] if parsed["players"] else None)
        if not player:
            raise RuntimeError("scorecard partial held no player rows")

        pars, sis, ydss = {}, {}, {}
        card_course = card_tee = None
        if player.get("net_id"):
            base = "https://" + urlparse(entry["url"]).netloc
            nurl = (f"{base}/tournaments2/nets/{player['net_id']}"
                    f"?event_id={player.get('gg_event_id') or ''}")
            tee = _CHAMP_TEE_CACHE.get(nurl)
            if tee is None:
                try:
                    nresp = fetch_public_page(nurl, xhr=True)
                    nfrag = _unwrap_js_strings(nresp["html"]) or ""
                    tee = parse_tee_block(nfrag) if nfrag else None
                except Exception:
                    tee = None      # pars are additive — the card still renders
                # only a SUCCESSFUL parse is cached: a one-off GG hiccup at
                # 9 AM must not cost the card its pars for the whole round
                if tee:
                    _CHAMP_TEE_CACHE[nurl] = tee
            # The course name rides the card (Kerry 2026-08-15: "Where
            # can we put the course name...") — straight off GG's own
            # tee header, so it is always the round's actual venue.
            if tee and tee.get("course"):
                card_course = str(tee["course"]).strip()
            # Tees played ride the card too (Kerry 2026-08-15: "Add in
            # tees played to the right of the course name") — GG's tee
            # header minus its "1 - " ordering prefix, pluralized
            # (Kerry: "TEE should be TEES").
            if tee and tee.get("tee_name"):
                card_tee = re.sub(r"^\s*\d+\s*-\s*", "",
                                  str(tee["tee_name"]).strip()) or None
                if card_tee:
                    card_tee = re.sub(r"([Tt][Ee][Ee])\s*$", r"\1s", card_tee)
            pars = (tee or {}).get("par") or {}
            # GG's own tee block carries YARDS + HCP (stroke index) rows —
            # the live source of truth (Kerry 2026-08-03: "HCP row isn't
            # showing"); the imported round's course-DB tee is the fallback
            sis = (tee or {}).get("stroke_index") or {}
            ydss = (tee or {}).get("yardage") or {}

        # GROSS races (players_cup_gross): points come off the raw gross
        # score vs par — no handicap dots, no NET line, no plus deduction.
        # The scale is the SEASON GROSS table through the championship
        # formulas (get_championship_formulas keeps the gross vs-par table
        # unchanged, only the ace bonus goes +1 -> 9) — verified against
        # every total on the GG championship gross boards (Youngs 50,
        # Rideout 6, Anthis 11, Thompson -1, Murphy -2, Bricco -4). The
        # champion +1 scale (_champ_stableford) is the NET rule only.
        gross_mode = race_key.endswith("_gross")
        gross_formulas = (get_championship_formulas(db_path=db_path)
                          if gross_mode else None)
        holes = []
        computed = None
        for n in range(1, 19):
            h = (player.get("holes") or {}).get(n) or {}
            gross = h.get("strokes")
            dots = 0 if gross_mode else (h.get("dots") or 0)
            par = pars.get(n)
            net = None if gross_mode else (
                (gross - dots) if gross is not None else None)
            if gross_mode:
                pts = compute_hole_derivations(
                    par, gross, 0, gross_formulas)["stableford_gross"]
            else:
                nvp = (net - par) if (net is not None
                                      and par is not None) else None
                pts = _champ_stableford(nvp, gross)
            if pts is not None:
                computed = (computed or 0) + pts
            holes.append({"hole": n, "par": par, "gross": gross,
                          "dots": dots, "net": net, "pts": pts,
                          "yardage": ydss.get(n),
                          "stroke_index": sis.get(n)})

        # The champ board's own figure rides along so the card can say
        # when the two disagree (the board stays official).
        # SKIPPED for compute-fill cards (roster_race set): those cards are
        # requested FROM INSIDE fetch_champ_points' fill step, before its
        # cache is written — calling back into fetch_champ_points here is a
        # re-entrant recursion that hung the live board (2026-08-15, R1).
        # A filled player has no board figure to compare against anyway.
        board_points = board_thru = None
        if roster_race is None:
            try:
                live = fetch_champ_points(race_key, db_path=db_path)
                bp = next((p for p in live.get("players", [])
                           if p.get("customer_id") == int(customer_id)), None)
                if bp:
                    board_points, board_thru = bp.get("points"), bp.get("thru")
                    # A per-round card compares against THAT round's board
                    # figure, not the multi-day sum (caught on the Round 2
                    # test card, 2026-08-13: board said 103 = R1 + R2).
                    if board_label:
                        day = next((x for x in (bp.get("days") or [])
                                    if x.get("board") == board_label), None)
                        if day:
                            board_points = day.get("points")
                            board_thru = day.get("thru") or board_thru
            except Exception:
                pass

        # PLUS-HANDICAP DEDUCTION (Kerry 2026-08-01): the flat deduction
        # the board applies must show on the card too, or the card and the
        # (already-adjusted) board figure would read as a disagreement.
        # Primary source is the roster's PlayingHandicap™ column — the
        # same map fetch_champ_points deducts from; the details partial's
        # own "(+4)" (parsed NEGATIVE by parse_scorecard_details) is the
        # fallback so a roster-parse miss can't hide the adjustment.
        plus_adj = (roster.get("plus_by_cid") or {}).get(int(customer_id))
        ph = player.get("playing_handicap")
        if plus_adj is None and ph is not None and ph < 0:
            plus_adj = -ph
        if gross_mode:
            plus_adj = None     # net-points rule only — see _champ_plus_adjustments
        computed_adj = (computed - plus_adj
                        if computed is not None and plus_adj else computed)

        # Nines render in PLAY order (Kerry 2026-08-03: SA teed off on the
        # back) — the player's latest 18-hole event checks the
        # event_first_nine dial.
        card_first_hole = 1
        nines = []
        try:
            with _connect(db_path) as _c:
                _fh = _c.execute(
                    """SELECT e.item_name, sr.tee_id, sr.round_date,
                              sr.player_name, ct.tee_name
                       FROM scoring_rounds sr
                       JOIN events e ON e.id = sr.event_id
                       LEFT JOIN course_tees ct ON ct.tee_id = sr.tee_id
                       WHERE sr.customer_id = ? AND sr.holes_played > 9
                       ORDER BY sr.round_date DESC, sr.id DESC LIMIT 1""",
                    (int(customer_id),)).fetchone()
                # Course facts (Kerry 2026-08-03: "Show YARDS and HCP rows
                # for the City Championship too") fill from the imported
                # round's course-DB tee only where the GG tee block above
                # didn't supply them — never guessed.
                if _fh and _fh["tee_id"]:
                    for th in _c.execute(
                            """SELECT hole_number, yardage, stroke_index
                               FROM course_tee_holes WHERE tee_id = ?""",
                            (_fh["tee_id"],)).fetchall():
                        hn = th["hole_number"]
                        if 1 <= hn <= 18:
                            h = holes[hn - 1]
                            if h.get("yardage") is None:
                                h["yardage"] = th["yardage"]
                            if h.get("stroke_index") is None:
                                h["stroke_index"] = th["stroke_index"]
                # Per-nine handicap adjusted gross + differentials for the
                # championship card too (Kerry 2026-08-03: "you added the
                # handicap diffs for each 18 hole regular season event,
                # but not the City championships") — the POSTED two-nine
                # handicap rows, same source as get_scorecard.
                # Same TODAY gate as first_hole (Kerry's 08-14 screenshot:
                # an Aug-1 round's adjusted gross + differential rendered
                # under an empty championship card) — a PAST round's
                # posted nines never belong on the LIVE champ card.
                if _fh and _fh["tee_name"] \
                        and _fh["round_date"] == today_central_str():
                    _names = {_normalize_player_name(_fh["player_name"] or "")}
                    for lk in _c.execute(
                            "SELECT player_name FROM handicap_player_links "
                            "WHERE customer_id = ?",
                            (int(customer_id),)).fetchall():
                        _names.add(lk["player_name"])
                    _qm = ",".join("?" * len(_names))
                    for hr in _c.execute(
                            f"""SELECT tee_name, adjusted_score, rating,
                                       slope, differential
                                FROM handicap_rounds
                                WHERE player_name IN ({_qm})
                                  AND round_date = ? AND tee_name IN (?, ?)
                                ORDER BY id""",
                            (*_names, _fh["round_date"],
                             f"{_fh['tee_name']} — Front 9",
                             f"{_fh['tee_name']} — Back 9")).fetchall():
                        nines.append({
                            "nine": ("front" if "Front" in (hr["tee_name"] or "")
                                     else "back"),
                            "adjusted_gross": hr["adjusted_score"],
                            "rating": hr["rating"], "slope": hr["slope"],
                            "differential": hr["differential"]})
            # The dial only applies to TODAY's imported round — a stale
            # back-first flag from a prior shotgun event must not flip a
            # championship card whose scores start on hole 1.
            if (_fh and _fh["round_date"] == today_central_str()
                    and _event_first_nine(_fh["item_name"],
                                          db_path=db_path) == "back"):
                card_first_hole = 10
        except Exception:
            pass

        out = {"race": race_key, "configured": True,
               "scoring": "gross" if gross_mode else "net",
               "first_hole": card_first_hole,
               "course": card_course,
               "tee": card_tee,
               "nines": nines or None,
               "player_name": entry["name"], "customer_id": int(customer_id),
               "playing_handicap": player.get("playing_handicap"),
               "plus_adjustment": plus_adj,
               "holes": holes, "computed_points": computed,
               "computed_points_adj": computed_adj,
               "gross_total": player.get("gross"),
               "board_points": board_points, "board_thru": board_thru,
               "stale": False}
        _CHAMP_CARD_CACHE[ck] = (_t.time(), out)
        return out
    except Exception as e:
        if hit:
            stale = dict(hit[1])
            stale["stale"] = True
            stale["error"] = str(e)
            return stale
        out = {"race": race_key, "configured": True, "holes": [],
               "error": str(e)}
        _CHAMP_CARD_CACHE[ck] = (_t.time(), out)
        return out


def get_points_race_standings(race_key: str,
                              auto_refresh_hours: float = 12,
                              force_refresh: bool = False,
                              db_path: str | Path = DB_PATH) -> dict:
    """Persisted GG points race standings joined with live buy-in status.

    Renders from the gg_points_standings snapshot (instant, survives
    restarts). Refreshes from the GG portal only when the snapshot is
    empty, older than auto_refresh_hours, or force_refresh is set — and
    falls back to the stale snapshot (with gg_error set) if GG is down.
    """
    race = _GG_POINTS_RACES.get(race_key)
    if not race:
        raise ValueError(
            f"Unknown race {race_key!r} — known: {sorted(_GG_POINTS_RACES)}")

    gg_error = None
    with _connect(db_path) as conn:
        _ensure_gg_points_table(conn)
        stat = conn.execute(
            """SELECT COUNT(*) AS n, MAX(fetched_at) AS fetched_at
               FROM gg_points_standings WHERE race_key = ?""",
            (race_key,),
        ).fetchone()
        stale = (
            stat["n"] == 0
            or stat["fetched_at"] is None
            or conn.execute(
                "SELECT datetime(?) < datetime('now', ?)",
                (stat["fetched_at"], f"-{auto_refresh_hours} hours"),
            ).fetchone()[0] == 1
        )
        # Standings only change after events (Kerry, 2026-07-08): a stale
        # snapshot with NO event since it was taken is still current — skip
        # the GG round-trip. Manual Refresh (force_refresh) is unaffected.
        if stale and stat["n"] and stat["fetched_at"]:
            event_since = conn.execute(
                "SELECT 1 FROM events WHERE event_date IS NOT NULL "
                "AND event_date >= date(?) LIMIT 1",
                (stat["fetched_at"],)).fetchone()
            if not event_since:
                stale = False

    if force_refresh or stale:
        try:
            refresh_points_race_standings(race_key, db_path=db_path)
        except Exception as exc:
            gg_error = str(exc)
            logger.warning("GG points race %r refresh failed (serving "
                           "persisted snapshot): %s", race_key, exc)

    with _connect(db_path) as conn:
        _ensure_gg_points_table(conn)
        rows = conn.execute(
            """SELECT rank, prev_rank, player_name, customer_id, affiliation,
                      tournaments, wins, total_points, points_behind,
                      member_card_id, fetched_at
               FROM gg_points_standings WHERE race_key = ? ORDER BY id""",
            (race_key,),
        ).fetchall()

        clauses = ["contest_type = ?"]
        params: list = [race["contest_type"]]
        # Main-season boards only (Kerry 2026-08-06, "Still showing in on
        # Austin Net 2026"): every configured race is a main-season board,
        # and a '<year> Fall' enrollment must not light its pill or count
        # in its pot — John Wade's Austin Fall NET buy-in did exactly that
        # because this query had no season scoping. Fall boards get their
        # own configs (and their own season filter) when they exist.
        clauses.append("COALESCE(season, '') NOT LIKE '%Fall'")
        if race.get("enroll_chapter"):
            clauses.append("(chapter = ? OR chapter IS NULL OR chapter = '')")
            params.append(race["enroll_chapter"])
        enr_rows = conn.execute(
            f"""SELECT customer_id, customer_name,
                       COALESCE(cup_only, 0) AS cup_only
                FROM season_contests
                WHERE {' AND '.join(clauses)}""",
            params,
        ).fetchall()
        # cup_only rows (Kerry 2026-08-06): a NET buy-in made after the
        # city race was declared final — a Fellowship Cup entry only.
        # They never count as city-enrolled (pill stays NOT IN, city pot
        # excludes them) but the Cup includes them fully.
        cup_only_ids = {r["customer_id"] for r in enr_rows
                        if r["customer_id"] and r["cup_only"]}
        n_cup_only = sum(1 for r in enr_rows if r["cup_only"])
        city_rows = [r for r in enr_rows if not r["cup_only"]]
        enrolled_ids = {r["customer_id"] for r in city_rows if r["customer_id"]}
        enrolled_names = {
            (r["customer_name"] or "").strip().lower(): r["customer_id"]
            for r in city_rows
        }

        # Current handicap per customer (every race, admin request): 18-hole
        # index via handicap_player_links — computed at read time so a
        # handicap change updates the column automatically. FLIGHTS are
        # the exception — see the flight lock below.
        flights = race.get("flights")
        # ── FLIGHT LOCK (Kerry 2026-08-06: "The Players Cup flights
        # need to be locked now... We will have handicap updates after
        # Day 1 of the TGF Championship, but I don't want anyone to
        # move flights in The Players Cup because of it.") ──
        # First read stamps each customer's current flight into the
        # flight_lock_<race> app setting; every later read serves the
        # locked flight, so index changes move the HCP column but never
        # the flight. New faces lock at first sight. Deleting the dial
        # re-locks from then-current handicaps on the next read.
        flight_lock, lock_dirty = None, False
        if flights:
            try:
                _raw = get_app_setting(f"flight_lock_{race_key}",
                                       db_path=db_path)
                flight_lock = json.loads(_raw) if _raw else None
            except Exception:
                flight_lock = None
            if (not isinstance(flight_lock, dict)
                    or not isinstance(flight_lock.get("assignments"),
                                      dict)):
                from .timezone_utils import now_central
                flight_lock = {"locked_at": now_central()
                               .strftime("%Y-%m-%d %H:%M"),
                               "assignments": {}}
                lock_dirty = True
        idx_by_cid: dict = {}
        if True:
            idx_by_name = {
                p["player_name"]: p["handicap_index_18"]
                for p in get_all_handicap_players(db_path)
                if p.get("handicap_index_18") is not None
            }
            for lr in conn.execute(
                    """SELECT player_name, customer_id FROM handicap_player_links
                       WHERE customer_id IS NOT NULL""").fetchall():
                v = idx_by_name.get(lr["player_name"])
                if v is not None and lr["customer_id"] not in idx_by_cid:
                    idx_by_cid[lr["customer_id"]] = v

        ranked_ids: set = set()
        out_rows = []
        fetched_at = None
        for r in rows:
            r = dict(r)
            fetched_at = r.pop("fetched_at") or fetched_at
            cid = r["customer_id"]
            if not cid:
                # Snapshot row didn't resolve at write time — the enrollment
                # name snapshot may still identify them
                for cand in _gg_name_candidates(r["player_name"]):
                    if cand.lower() in enrolled_names:
                        cid = enrolled_names[cand.lower()]
                        r["customer_id"] = cid
                        break
            if cid:
                ranked_ids.add(cid)
            r["enrolled"] = bool(cid and cid in enrolled_ids)
            # Cup-side enrollment: city entrants AND cup-only buy-ins —
            # the Fellowship Cup projection reads this instead of the
            # city 'enrolled' flag.
            r["cup_enrolled"] = bool(
                cid and (cid in enrolled_ids or cid in cup_only_ids))
            hcp = idx_by_cid.get(cid) if cid else None
            r["handicap_index"] = hcp
            if flights:
                locked = (flight_lock["assignments"].get(str(cid))
                          if cid else None)
                if locked is None:
                    locked = _assign_flight(hcp, flights)
                    if cid and locked:
                        flight_lock["assignments"][str(cid)] = locked
                        lock_dirty = True
                r["flight"] = locked
            out_rows.append(r)

        # persist the flight lock the first time it forms (and whenever
        # a new face gets locked at first sight)
        if flights and lock_dirty:
            try:
                set_app_setting(f"flight_lock_{race_key}",
                                json.dumps(flight_lock), db_path=db_path)
                logger.info("flight lock stamped for %s: %d players",
                            race_key, len(flight_lock["assignments"]))
            except Exception:
                logger.warning("flight lock save failed for %s",
                               race_key, exc_info=True)

        # R4 (Kerry-ratified #149/#151): SHOW non-members, don't hide them.
        # The old "members only" admin rule dropped non-enrolled non-members
        # from the visible board; ratified reversal — guests/alumni stay
        # RANKED on active boards (preserves LSC alternates percentile math;
        # "ranked next to a pot is the best join pitch"), each row carries
        # member_status (D1 financial truth) so the UI can chip them with a
        # join/renew path. Bought-in players always remain. LADDER
        # eligibility below is UNCHANGED — visible ≠ eligible; ineligible
        # rows still consume no ladder spot and earn no reset points.
        status_by_cid: dict = {}
        chapter_by_cid: dict = {}
        cids = list({r["customer_id"] for r in out_rows if r["customer_id"]})
        if cids:
            qmarks = ",".join("?" * len(cids))
            for sr in conn.execute(
                    f"""SELECT customer_id, current_player_status, chapter
                        FROM customers WHERE customer_id IN ({qmarks})""",
                    cids).fetchall():
                status_by_cid[sr["customer_id"]] = sr["current_player_status"]
                chapter_by_cid[sr["customer_id"]] = sr["chapter"]
        fin_by_cid = derive_member_financial_status_bulk(conn, cids)
        hidden_nonmembers = []   # kept for payload compat — always [] now
        for r in out_rows:
            cid = r["customer_id"]
            if cid:
                r["member_status"] = fin_by_cid.get(cid, "guest")
            else:
                r["member_status"] = ("member" if "tgf" in
                                      (r.get("affiliation") or "").lower()
                                      else "guest")
            r["is_member"] = r["member_status"] == "member"

        # CUP boards hide guests/alumni (Kerry 2026-08-15, R1 live: "Hide
        # guests and alumni from both cups"). Race-flagged so the CITY
        # boards keep the ratified R4 behavior (non-members stay visible,
        # chipped with a join/renew path). A bought-in row is NEVER hidden
        # whatever its status — money always shows. Hidden rows were all
        # 0-total, non-enrolled, non-scoring, so pot counts, the reset
        # ladder (already members-only), and payouts are untouched.
        if race.get("cup_members_only"):
            out_rows = [r for r in out_rows
                        if r["member_status"] == "member"
                        or r.get("enrolled") or r.get("cup_enrolled")]

        # Re-rank over the visible list — now EVERYONE (R4). GG's original
        # rank is kept as gg_rank for reference.
        for r in out_rows:
            cid = r["customer_id"]
            aff = (r.get("affiliation") or "").strip()
            r["player_chapter"] = (
                (chapter_by_cid.get(cid) if cid else None)
                or (aff[4:] if aff.lower().startswith("tgf ") else aff)
            )
        for i, r in enumerate(out_rows):
            r["gg_rank"] = r["rank"]
            if i and out_rows[i - 1]["total_points"] == r["total_points"]:
                r["_rank_num"] = out_rows[i - 1]["_rank_num"]
            else:
                r["_rank_num"] = i + 1
        rank_tally: dict = {}
        for r in out_rows:
            rank_tally[r["_rank_num"]] = rank_tally.get(r["_rank_num"], 0) + 1
        for r in out_rows:
            n = r.pop("_rank_num")
            r["rank"] = f"T{n}" if rank_tally[n] > 1 else str(n)

        # POINTS RESET projection (methodology per the 2025 workbook,
        # admin-confirmed 2026-07-03): one master ladder, position p ->
        # 100 - 0.5*(p-1); a race rank r maps to master position
        # ROUND(1 + coef*(r-1)). NET races share the ladder with
        # coef = anchor_count / this_count (anchor = largest chapter's
        # eligible headcount); the Players Cup restacks its combined
        # list at coef 1. Eligible: active members with >= 1 event played,
        # any point total. Projection only — the actual reset happens
        # after the City Championships.
        reset_info = None
        reset_mode = race.get("reset_mode")
        if reset_mode:
            if reset_mode == "prorated":
                group = race.get("reset_group")
                counts = {
                    k: _points_race_eligible_count(conn, k)
                    for k, v in _GG_POINTS_RACES.items()
                    if v.get("reset_group") == group
                }
                anchor_n = max(counts.values()) if counts else 0
                mine_n = counts.get(race_key, 0)
                coef = (anchor_n / mine_n) if mine_n else None
            else:
                counts, anchor_n, mine_n, coef = None, None, None, 1.0
            # Ladder positions count ELIGIBLE players only — a visible but
            # ineligible row (e.g. an expired member kept visible by their
            # buy-in) consumes no ladder spot
            elig_rows = []
            for r in out_rows:
                r["points_reset"] = None
                if not coef or (r.get("tournaments") or 0) < 1:
                    continue
                cid = r["customer_id"]
                if (status_by_cid.get(cid) in _MEMBER_PLAYER_STATUSES
                        if cid else
                        "tgf" in (r.get("affiliation") or "").lower()):
                    elig_rows.append(r)
            prev_pts, prev_rank = object(), 0
            for i, r in enumerate(elig_rows):
                pos = prev_rank if r["total_points"] == prev_pts else i + 1
                prev_pts, prev_rank = r["total_points"], pos
                # int(x + 0.5) == Excel ROUND for positive x (half up)
                master = int(1 + coef * (pos - 1) + 0.5)
                r["points_reset"] = 100 - 0.5 * (master - 1)
            reset_info = {
                "mode": reset_mode,
                "coefficient": round(coef, 4) if coef else None,
                "eligible_count": mine_n,
                "anchor_count": anchor_n,
                "counts": counts,
            }

        enrolled_not_ranked = [
            {"customer_id": e["customer_id"], "customer_name": e["customer_name"]}
            for e in city_rows
            if e["customer_id"] and e["customer_id"] not in ranked_ids
        ]

    # Projected payouts from the LIVE buy-in count (season_payouts.py —
    # the ratified TGF_Season_Contest_Payouts_v1_0 rules). Pot counts
    # every paid entry, ranked or not.
    from . import season_payouts as _sp
    _n_pot = (sum(1 for r in out_rows if r["enrolled"])
              + len(enrolled_not_ranked))
    projected_payouts = (
        _sp.players_cup_payouts(_n_pot) if race.get("flights")
        else _sp.city_net_payouts(_n_pot))

    _final_flag = _points_race_final(race_key, db_path=db_path)
    return {
        "race_key": race_key,
        "label": race["label"],
        "contest_type": race["contest_type"],
        "chapter": race["chapter"],
        "race_final": _final_flag,
        "reset_official": _points_reset_official(db_path=db_path),
        # Champion(s) once declared final — the live merge recomputes
        # this over the live order; post-absorption this IS final order
        "champions": _race_champions(out_rows) if _final_flag else None,
        "standings": out_rows,
        "cross_chapter": race.get("enroll_chapter") is None,
        "n_players": len(out_rows),
        "n_enrolled": sum(1 for r in out_rows if r["enrolled"]),
        # Fellowship-Cup-only buy-ins attached to this city race (paid
        # $40 Cup entries; NOT in the city pot/pill counts above)
        "n_cup_only": n_cup_only,
        "n_unresolved": sum(1 for r in out_rows if not r["customer_id"]),
        "enrolled_not_ranked": enrolled_not_ranked,
        "hidden_nonmembers": hidden_nonmembers,
        "reset_info": reset_info,
        "projected_payouts": projected_payouts,
        "fetched_at": fetched_at,
        "gg_error": gg_error,
        "flights": (
            [{"label": lbl, "range": _flight_range_text(lo, hi)}
             for lbl, lo, hi in race["flights"]]
            if race.get("flights") else None
        ),
    }


def _apply_rank_movement_history(standings: list, list_key: str,
                                 db_path: str | Path = DB_PATH,
                                 keep: int = 12,
                                 freeze: bool = False) -> None:
    """GG-style Previous Rank for OUR OWN computed standings (v2.43.0,
    Kerry: "I know you don't have a GG reference for The Fellowship Cup
    because that's on our side, but could you create the same movement
    symbols?").

    Persists an ordered rank snapshot per list_key and rotates it ONLY
    when the ordering actually changes, then stamps each row's
    prev_rank from the superseded snapshot. Chips therefore appear when
    a standings change lands (new event data) and persist until the
    next change — the same between-events semantics as GG's arrows.
    Rows are keyed by customer_id (name fallback for unresolved rows).
    Generic: any tracker-computed list can adopt it with its own
    list_key (the monthly races are the obvious next candidate).
    """
    import hashlib

    def key_of(r):
        return (str(r["customer_id"]) if r.get("customer_id")
                else (r.get("player_name") or "").strip().lower())

    # FREEZE (championship day, v2.185.0): a live round reshuffles the
    # order every poll — rotating a snapshot per tick would burn the
    # `keep`-deep history on intra-round noise and leave the post-round
    # chips meaningless. Frozen mode records nothing and stamps movement
    # against the LATEST stored snapshot (the last pre-live rotation), so
    # chips read "vs where the day started" all round.
    if freeze:
        prev_map = {}
        with _connect(db_path) as conn:
            try:
                latest = conn.execute(
                    "SELECT id FROM rank_history_snapshots "
                    "WHERE list_key = ? ORDER BY id DESC LIMIT 1",
                    (list_key,)).fetchone()
                if latest:
                    prev_map = {r["member_key"]: r["rank"] for r in conn.execute(
                        "SELECT member_key, rank FROM rank_history_rows "
                        "WHERE snapshot_id = ?", (latest["id"],)).fetchall()}
            except sqlite3.OperationalError:
                pass    # tables not created yet — no history, no chips
        for r in standings:
            r["prev_rank"] = prev_map.get(key_of(r), "-")
        return

    cur = [(key_of(r), str(r.get("rank") or "")) for r in standings]
    order_hash = hashlib.sha1(
        "|".join(f"{k}:{rk}" for k, rk in cur).encode()).hexdigest()
    with _connect(db_path) as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS rank_history_snapshots (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            list_key   TEXT NOT NULL,
            order_hash TEXT NOT NULL,
            taken_at   TEXT DEFAULT (datetime('now')))""")
        conn.execute("""CREATE TABLE IF NOT EXISTS rank_history_rows (
            snapshot_id INTEGER NOT NULL REFERENCES rank_history_snapshots(id),
            member_key  TEXT NOT NULL,
            rank        TEXT,
            PRIMARY KEY (snapshot_id, member_key))""")
        snaps = conn.execute(
            "SELECT id, order_hash FROM rank_history_snapshots "
            "WHERE list_key = ? ORDER BY id DESC LIMIT 2",
            (list_key,)).fetchall()
        latest = snaps[0] if snaps else None
        if latest and latest["order_hash"] == order_hash:
            # unchanged since last rotation — movement stays vs the
            # snapshot that rotation superseded
            prev_id = snaps[1]["id"] if len(snaps) > 1 else None
        else:
            prev_id = latest["id"] if latest else None
            cur_id = conn.execute(
                "INSERT INTO rank_history_snapshots (list_key, order_hash) "
                "VALUES (?, ?)", (list_key, order_hash)).lastrowid
            conn.executemany(
                "INSERT OR REPLACE INTO rank_history_rows "
                "(snapshot_id, member_key, rank) VALUES (?, ?, ?)",
                [(cur_id, k, rk) for k, rk in cur])
            old = conn.execute(
                "SELECT id FROM rank_history_snapshots WHERE list_key = ? "
                "ORDER BY id DESC LIMIT -1 OFFSET ?",
                (list_key, keep)).fetchall()
            if old:
                ids = [r["id"] for r in old]
                q = ",".join("?" * len(ids))
                conn.execute(
                    f"DELETE FROM rank_history_rows WHERE snapshot_id IN ({q})", ids)
                conn.execute(
                    f"DELETE FROM rank_history_snapshots WHERE id IN ({q})", ids)
        prev_map = {}
        if prev_id is not None:
            prev_map = {r["member_key"]: r["rank"] for r in conn.execute(
                "SELECT member_key, rank FROM rank_history_rows "
                "WHERE snapshot_id = ?", (prev_id,)).fetchall()}
        conn.commit()
    for r in standings:
        r["prev_rank"] = prev_map.get(key_of(r), "-")


def seed_fellowship_cup_history(db_path: str | Path = DB_PATH) -> dict:
    """One-time backfill (v2.43.1, Kerry: 'Any way to reverse engineer
    the change in The Fellowship Cup by reviewing the history of last
    GG event and yesterday's?'): reconstruct the Cup ordering as it
    stood BEFORE the most recent GG event and seed it as the prior
    rank-history snapshot, so movement chips show the last event's
    effect immediately instead of waiting for the next one.

    The Cup's reset value is a pure function of a player's POSITION in
    their NET race (master ladder + coefficient), and GG's race
    snapshots carry each player's Previous Rank from before the last
    event — so yesterday's Cup is: previous race positions → previous
    reset values → previous combined ordering. Players whose first
    imported round IS the latest round date are treated as new
    entrants (absent from yesterday's list → no chip). Existing
    fellowship_cup history is replaced by the seed; the live
    projection then rotates the current order on top of it.
    """
    import hashlib
    races = [k for k, v in _GG_POINTS_RACES.items()
             if v.get("reset_mode") == "prorated"]
    with _connect(db_path) as conn:
        latest_date = (conn.execute(
            "SELECT MAX(round_date) FROM scoring_rounds").fetchone()[0]
            or "")

    def _num(s):
        m = re.search(r"(\d+)", str(s or ""))
        return int(m.group(1)) if m else None

    per_race_prev: dict = {}
    new_entrants: list = []
    for k in races:
        d = get_points_race_standings(k, db_path=db_path)
        kept = []
        for r in d["standings"]:
            if r.get("points_reset") is None:
                continue        # not reset-eligible today
            prevn = _num(r.get("prev_rank"))
            curn = _num(r.get("rank"))
            if prevn is None and r.get("customer_id") and latest_date:
                with _connect(db_path) as conn:
                    played_before = conn.execute(
                        "SELECT 1 FROM scoring_rounds WHERE customer_id = ? "
                        "AND round_date < ? LIMIT 1",
                        (r["customer_id"], latest_date)).fetchone()
                    played_latest = conn.execute(
                        "SELECT 1 FROM scoring_rounds WHERE customer_id = ? "
                        "AND round_date = ? LIMIT 1",
                        (r["customer_id"], latest_date)).fetchone()
                if played_latest and not played_before:
                    new_entrants.append(r["player_name"])
                    continue    # joined the list with the latest event
            kept.append({
                "player_name": r["player_name"],
                "customer_id": r["customer_id"],
                "pos": prevn or curn or 10 ** 6,
            })
        kept.sort(key=lambda x: x["pos"])
        per_race_prev[k] = kept

    # yesterday's coefficients from yesterday's eligible headcounts
    counts = {k: len(v) for k, v in per_race_prev.items()}
    anchor_n = max(counts.values()) if counts else 0
    combined: list = []
    for k, kept in per_race_prev.items():
        coef = (anchor_n / counts[k]) if counts[k] else None
        if not coef:
            continue
        for r in kept:
            master = int(1 + coef * (r["pos"] - 1) + 0.5)
            combined.append({**r, "reset": 100 - 0.5 * (master - 1)})
    combined.sort(key=lambda r: -r["reset"])
    for i, r in enumerate(combined):
        j = i
        while j > 0 and combined[j - 1]["reset"] == r["reset"]:
            j -= 1
        r["_n"] = j + 1
    tally: dict = {}
    for r in combined:
        tally[r["_n"]] = tally.get(r["_n"], 0) + 1
    for r in combined:
        n = r.pop("_n")
        r["rank"] = f"T{n}" if tally[n] > 1 else str(n)

    def key_of(r):
        return (str(r["customer_id"]) if r.get("customer_id")
                else (r.get("player_name") or "").strip().lower())

    rows = [(key_of(r), r["rank"]) for r in combined]
    order_hash = hashlib.sha1(
        "|".join(f"{k}:{rk}" for k, rk in rows).encode()).hexdigest()
    with _connect(db_path) as conn:
        conn.execute("""CREATE TABLE IF NOT EXISTS rank_history_snapshots (
            id         INTEGER PRIMARY KEY AUTOINCREMENT,
            list_key   TEXT NOT NULL,
            order_hash TEXT NOT NULL,
            taken_at   TEXT DEFAULT (datetime('now')))""")
        conn.execute("""CREATE TABLE IF NOT EXISTS rank_history_rows (
            snapshot_id INTEGER NOT NULL REFERENCES rank_history_snapshots(id),
            member_key  TEXT NOT NULL,
            rank        TEXT,
            PRIMARY KEY (snapshot_id, member_key))""")
        conn.execute(
            "DELETE FROM rank_history_rows WHERE snapshot_id IN "
            "(SELECT id FROM rank_history_snapshots WHERE list_key = 'fellowship_cup')")
        conn.execute(
            "DELETE FROM rank_history_snapshots WHERE list_key = 'fellowship_cup'")
        sid = conn.execute(
            "INSERT INTO rank_history_snapshots (list_key, order_hash) "
            "VALUES ('fellowship_cup', ?)", (order_hash,)).lastrowid
        conn.executemany(
            "INSERT OR REPLACE INTO rank_history_rows "
            "(snapshot_id, member_key, rank) VALUES (?, ?, ?)",
            [(sid, k, rk) for k, rk in rows])
        conn.commit()

    # rotate the CURRENT order on top of the seed → chips live now
    cur = get_fellowship_cup_projection(db_path=db_path)
    moved = [{"player": r["player_name"], "rank": r["rank"],
              "prev_rank": r.get("prev_rank")}
             for r in cur["standings"]
             if _num(r.get("prev_rank")) and _num(r.get("rank"))
             and _num(r["prev_rank"]) != _num(r["rank"])]
    return {"latest_event_date": latest_date,
            "seeded_rows": len(rows),
            "new_entrants_excluded": new_entrants,
            "movers_now": moved}


def get_fellowship_cup_projection(force_refresh: bool = False,
                                  db_path: str | Path = DB_PATH) -> dict:
    """THE FELLOWSHIP CUP — combined projected reset standings.

    The City NET competitions convert to the Fellowship Cup race at the
    TGF Championship: both chapters' eligible members enter one list,
    ordered by their projected reset value from the shared master ladder
    (see the reset block in get_points_race_standings). Mirrors the 2025
    workbook's 'TFC Projected' tab.
    """
    races = [k for k, v in _GG_POINTS_RACES.items()
             if v.get("reset_mode") == "prorated"]
    combined: list = []
    per_race: dict = {}
    fetched: list = []
    errors: list = []
    cup_n = 0  # every NET-bundle buy-in funds the Cup pot ($40 each)
    champ_scoring = champ_field = 0
    for k in races:
        # LIVE path (Kerry, championship day 2026-08-01: "start updating
        # The Fellowship Cup with projected points reset"): during the
        # City Championships each NET race re-ranks live and re-projects
        # its reset ladder, and the Cup — a pure function of those
        # projections — must follow. On any other day the live merge is a
        # no-op passthrough of the season standings, so this costs one
        # cached champ-board read per race.
        d = get_points_race_live(k, force_refresh=force_refresh,
                                 db_path=db_path)
        champ_scoring += d.get("champ_scoring") or 0
        champ_field += d.get("champ_field") or 0
        # City entries + cup-only buy-ins (post-final Fellowship Cup
        # entries, Kerry 2026-08-06) — every one is a $40 Cup pot head
        cup_n += ((d.get("n_enrolled") or 0)
                  + len(d.get("enrolled_not_ranked") or [])
                  + (d.get("n_cup_only") or 0))
        info = d.get("reset_info") or {}
        per_race[k] = {
            "label": d["label"],
            "chapter": d["chapter"],
            "eligible_count": info.get("eligible_count"),
            "coefficient": info.get("coefficient"),
            "champ_scoring": d.get("champ_scoring") or 0,
        }
        if d.get("fetched_at"):
            fetched.append(d["fetched_at"])
        if d.get("gg_error"):
            errors.append(f'{d["label"]}: {d["gg_error"]}')
        for r in d["standings"]:
            if r.get("points_reset") is None:
                continue  # not reset-eligible -> not in the cup projection
            # Guests/alumni never ride into the Cup (Kerry 2026-08-15:
            # "Hide guests and alumni from both cups"). Reset eligibility
            # already excludes them today — this guard makes the rule
            # explicit and holds if eligibility ever loosens. A bought-in
            # row always stays.
            if (r.get("member_status") in ("guest", "alumni")
                    and not r.get("cup_enrolled", r.get("enrolled"))):
                continue
            combined.append({
                "player_name": r["player_name"],
                "customer_id": r["customer_id"],
                "chapter": d["chapter"],
                "net_rank": r["rank"],
                "handicap_index": r.get("handicap_index"),
                # Cup enrollment includes cup-only buy-ins; falls back to
                # the city flag for snapshots predating cup_enrolled
                "enrolled": r.get("cup_enrolled", r["enrolled"]),
                "points_reset": r["points_reset"],
                # The player's CITY-race drill-down card + which race it
                # belongs to — the Cup expansion's Season History reads
                # the city board's member card (Kerry 2026-08-13:
                # "Season History isn't populating" — Cup rows carried
                # no card id at all, so the fetch was silently skipped)
                "member_card_id": r.get("member_card_id"),
                "hist_race": k,
            })

    # TGF CHAMPIONSHIP overlay (Kerry 2026-08-13: "the points races will
    # resolve like the City Championship... track Day 1 AND Day 2 totals
    # to produce the winners"). The Cup's championship NET points come off
    # the GG boards configured under the 'fellowship_cup' key of the
    # gg_champ_points_boards dial — a two-board list (Day 1 + Day 2)
    # summed per player by fetch_champ_points. While boards are live the
    # standings order becomes reset + championship; without boards this
    # whole block is a no-op and the pure reset projection stands.
    cup_live = {}
    cup_champ_scoring = cup_champ_field = 0
    try:
        cup_live = fetch_champ_points("fellowship_cup", db_path=db_path)
    except Exception:
        logger.warning("fellowship cup champ fetch failed", exc_info=True)
        cup_live = {}
    cup_overlay = bool(cup_live.get("configured") and cup_live.get("players"))
    cup_boards_pending = cup_live.get("boards_pending") or []
    if cup_overlay:
        by_cid = {p["customer_id"]: p for p in cup_live["players"]
                  if p.get("customer_id")}
        by_name: dict = {}
        for p in cup_live["players"]:
            for cand in _gg_name_candidates(p["name"]):
                by_name.setdefault(cand.strip().lower(), p)
        for r in combined:
            hit = None
            if r.get("customer_id") and r["customer_id"] in by_cid:
                hit = by_cid[r["customer_id"]]
            elif (r.get("player_name") or "").strip().lower() in by_name:
                hit = by_name[(r["player_name"] or "").strip().lower()]
            champ = (float(hit["points"])
                     if hit and hit.get("points") is not None else None)
            r["champ_points"] = champ
            r["champ_thru"] = hit.get("thru") if hit else None
            r["champ_days"] = hit.get("days") if hit else None
            r["champ_plus"] = hit.get("plus_adjustment") if hit else None
            r["cup_total"] = round((r["points_reset"] or 0.0) + (champ or 0.0), 2)
        cup_champ_scoring = cup_live.get("scoring") or 0
        cup_champ_field = cup_live.get("field") or 0

    def _cup_key(r):
        return (r.get("cup_total") if cup_overlay
                else r["points_reset"]) or 0.0

    combined.sort(key=lambda r: (-_cup_key(r), -(r["points_reset"] or 0.0),
                                 (r.get("player_name") or "").lower()))
    for i, r in enumerate(combined):
        j = i
        while j > 0 and _cup_key(combined[j - 1]) == _cup_key(r):
            j -= 1
        r["_rank_num"] = j + 1
    tally: dict = {}
    for r in combined:
        tally[r["_rank_num"]] = tally.get(r["_rank_num"], 0) + 1
    for r in combined:
        n = r.pop("_rank_num")
        r["rank"] = f"T{n}" if tally[n] > 1 else str(n)
    # Movement chips vs our own recorded history (no GG reference here).
    # During a live championship the history FREEZES: chips read against
    # the last pre-round order instead of rotating on every intra-round
    # reshuffle (see _apply_rank_movement_history). Once EVERY feeding
    # race is DECLARED final the Cup is no longer live (Kerry: "It also
    # shouldn't show LIVE anymore") — the badge stands down, and the
    # history thaws so the final order rotates in once and the chips
    # show the day's movement, exactly like after any other event.
    all_final = races and all(
        _points_race_final(k, db_path=db_path) for k in races)
    live = (champ_scoring > 0 or champ_field > 0) and not all_final
    if all_final:
        champ_scoring = champ_field = 0
    # The TGF Championship boards make the Cup live in their own right —
    # the city races being final no longer ends the Cup's live life
    # (Kerry 2026-08-13: the Cup is DECIDED at the TGF Championship).
    if cup_champ_scoring or cup_champ_field:
        live = True
        champ_scoring += cup_champ_scoring
        champ_field += cup_champ_field
    try:
        _apply_rank_movement_history(combined, "fellowship_cup",
                                     db_path=db_path, freeze=live)
    except Exception:
        logger.warning("fellowship cup rank history failed", exc_info=True)

    from . import season_payouts as _sp
    # FINAL + champions (Kerry, championship Sunday 2026-08-16: "Event is
    # over and champions are crowned") — same dial as the races
    # (gg_points_race_final['fellowship_cup']); champions are the
    # top-ranked ENROLLED row(s), same eligibility as the money.
    _cup_final = _points_race_final("fellowship_cup", db_path=db_path)
    return {
        "label": "THE FELLOWSHIP CUP",
        "reset_official": _points_reset_official(db_path=db_path),
        "race_final": _cup_final,
        "champions": _race_champions(combined) if _cup_final else None,
        "standings": combined,
        "n_players": len(combined),
        "n_enrolled": cup_n,
        "per_race": per_race,
        "projected_payouts": _sp.fellowship_cup_payouts(cup_n),
        "fetched_at": max(fetched) if fetched else None,
        "gg_error": "; ".join(errors) or None,
        # Live-championship signal for the Cup tab's badge + 60s poll —
        # the same fields the race payloads carry, summed across races
        "champ_scoring": champ_scoring,
        "champ_field": champ_field,
        "champ": ({"label": (cup_live.get("label")
                             or "TGF Championship")
                   if (cup_champ_scoring or cup_champ_field)
                   else "City Championships"} if live else None),
        # TGF Championship overlay state (Kerry 2026-08-13): rows carry
        # champ_points / champ_thru / champ_days / cup_total when active
        "champ_overlay": cup_overlay,
        "champ_error": cup_live.get("error"),
        "champ_boards": cup_live.get("boards"),
        "champ_boards_pending": cup_boards_pending,
        # TEST PHASE dial (Kerry 2026-08-13: "Show leaderboard as in
        # TEST PHASE while we look at all of this") — members see a
        # loud banner while setup/test scores are on the boards; clear
        # the gg_champ_test_phase setting to drop it, no deploy needed.
        "champ_test_phase": (get_app_setting("gg_champ_test_phase",
                                             db_path=db_path) or "") == "1",
    }


def _lsc_standard_name(nm: str) -> str:
    """'Luke Youngs' -> 'YOUNGS, Luke' — the Lone Star Cup page renders
    every seat in the GG standings style (SURNAME, First), but the match
    play bracket stores plain display names (Kerry 2026-08-02: "Luke
    Youngs name doesn't show as standard"). Already-standard or
    single-word names pass through unchanged."""
    nm = (nm or "").strip()
    if "," in nm or " " not in nm:
        return nm
    parts = nm.split()
    return f"{parts[-1].upper()}, {' '.join(parts[:-1])}"


def _lsc_ordinal(n: int) -> str:
    if 10 <= n % 100 <= 20:
        return f"{n}th"
    return f"{n}{ {1: 'st', 2: 'nd', 3: 'rd'}.get(n % 10, 'th') }"


def get_lone_star_cup_projection(db_path: str | Path = DB_PATH,
                                 alternates_cap: int = 8) -> dict:
    """LONE STAR CUP projected rosters per chapter (spec: mailbox #85–#88,
    Kerry-RATIFIED 2026-07-10).

    12 earned seats per chapter: 1 CAPTAIN (City NET Champion), 6 from the
    final Fellowship Cup standings (top 6 FROM THAT CHAPTER on the TGF-wide
    list), 1 City Match Play Champion, 4 from the final Players Cup
    standings (top 4 from the chapter, overall list — flights don't gate
    LSC seats). CO-CHAMPION amendment (Kerry-ratified 2026-08-01): a T1
    City NET finish makes co-champions who share the captaincy as
    CO-CAPTAINS, occupying two of the chapter's seven NET-path seats —
    the Fellowship Cup allocation drops to 5 so the roster stays 12.
    Once a NET race is DECLARED final (gg_points_race_final dial) the
    champion's seat reads status='secured' instead of 'projected'.
    Rules applied:

    - Only bought-in (enrolled) players hold seats — same eligibility
      spirit as projected payouts.
    - Double-qualifiers take the slot where they placed HIGHER by absolute
      place (#86 interim rule — Kerry's "proportional valuation" tweak is
      NOT ratified; revisit before selection day). Cross-contest place
      ties break by seat order: Captain, Fellowship, Match Play, Players.
    - Vacated or unfillable seats fill from the Tier-2 UNIFIED ALTERNATES
      POOL (#87): one per-chapter list merging all contests, ranked by
      percentile finish (place ÷ field size), tiebreaker events played.
      The MP winner→runner-up→pool cascade (#88) governs real declines
      only, so a standings projection never exercises it.
    - The Match Play seat shows the bracket champion once the final has a
      winner; until then it is TO BE DECIDED (Kerry, 2026-07-10 — no
      speculative projection from seeding).

    PROJECTION ONLY. Actual rosters are picked after the Championships,
    with Kerry's manual fills/overrides (#87 hard requirement) — that
    admin surface is a separate, later feature.
    """
    season = str(today_central().year)

    def pnum(rank) -> int | None:
        try:
            return int(str(rank).lstrip("T"))
        except (TypeError, ValueError):
            return None

    # LIVE view for the Players Cup too (Kerry 2026-08-02: "We didn't wire
    # up gross points from the championships") — quiet-day passthrough,
    # championship-inclusive order once the champ gross boards are dialed in
    gross = get_points_race_live("players_cup_gross", db_path=db_path)
    cup = get_fellowship_cup_projection(db_path=db_path)
    errors = [e for e in (gross.get("gg_error"), cup.get("gg_error")) if e]

    # Invitation responses (Kerry 2026-08-17): two JSON-list-of-
    # customer_id dials, set via scoring-setting-set:<key>|[…].
    # lsc_accepted — holders have ACCEPTED their roster invitation; any
    #   seat they hold reads SECURED (same lock as a declared champion).
    # lsc_declined — holders have DECLINED ("Dow Floyd has declined.
    #   Remove him."): they are excluded from every seat stream AND the
    #   alternates pool, so their seat vacates and refills from the pool.
    #   The declined names surface only in the admin-gated `declined`
    #   list (the route strips it for non-admin sessions).
    def _dial_ids(key: str) -> set:
        try:
            return {int(x) for x in json.loads(
                get_app_setting(key, db_path=db_path) or "[]")}
        except Exception:
            return set()
    lsc_accepted = _dial_ids("lsc_accepted")
    lsc_declined = _dial_ids("lsc_declined")

    chapters_out = []
    for chapter, race_key in (("Austin", "austin_net"),
                              ("San Antonio", "san_antonio_net")):
        # LIVE view: identical passthrough on quiet days, and on/after
        # championship day the captain stream reads the FINAL order
        # instead of the stale pre-championship snapshot
        net = get_points_race_live(race_key, db_path=db_path)
        if net.get("gg_error"):
            errors.append(net["gg_error"])
        # Declared-final champions SECURE the captaincy (Kerry-ratified
        # 2026-08-01): a T1 makes CO-CHAMPIONS = CO-CAPTAINS, occupying
        # two of the chapter's seven NET-path seats — the captain seat
        # plus one Fellowship Cup seat (Cup seats drop to 5).
        champs = (net.get("champions") or []) if net.get("race_final") else []
        n_cap = max(1, len(champs))
        n_fc = 6 - (n_cap - 1)

        def stream(rows, chapter_field=None):
            out = []
            for r in rows:
                if not r.get("enrolled") or not r.get("customer_id"):
                    continue
                if r["customer_id"] in lsc_declined:
                    continue
                if chapter_field and (r.get(chapter_field) or "") != chapter:
                    continue
                place = pnum(r.get("rank"))
                if place is None:
                    continue
                out.append({"name": r["player_name"],
                            "cid": r["customer_id"], "place": place})
            return out

        streams = {
            "captain": stream(net["standings"]),
            "fellowship": stream(cup["standings"], "chapter"),
            "players": stream(gross["standings"], "player_chapter"),
        }
        field_sizes = {
            "captain": len(net["standings"]),
            "fellowship": len(cup["standings"]),
            "players": len(gross["standings"]),
        }
        contest_names = {
            "captain": f"{chapter} NET",
            "fellowship": "The Fellowship Cup",
            "players": "The Players Cup",
        }
        events_by_cid = {r["customer_id"]: (r.get("tournaments") or 0)
                         for r in net["standings"] if r.get("customer_id")}

        mp_champ = None
        try:
            finals = [b for b in cmp_get_bracket(season, chapter,
                                                 db_path=db_path)
                      if b["round"] == "final" and b.get("winner_name")]
            if finals:
                _wcid = finals[0].get("winner_id")
                if not _wcid:
                    # Rows saved before ids were written at save time
                    # (the 2026-08-01 'LSC seat stayed TBD after the
                    # Austin final was recorded' defect) — resolve the
                    # name at read time; the seat must never sit empty
                    # because a backfill hasn't run yet.
                    try:
                        with _connect(db_path) as _c:
                            _wcid, _how = _resolve_gg_person(
                                _c, finals[0]["winner_name"])
                    except Exception:
                        _wcid = None
                mp_champ = {"name": _lsc_standard_name(finals[0]["winner_name"]),
                            "cid": _wcid, "place": 1}
        except Exception:
            logger.warning("LSC: match play bracket read failed for %s",
                           chapter, exc_info=True)
        if mp_champ and mp_champ.get("cid") in lsc_declined:
            mp_champ = None

        # The earned 12, in seat order. Each seat draws the next unclaimed
        # player from its contest stream; a player already holding a
        # better-placed seat is skipped there and their would-be seat
        # becomes a vacancy (filled from the pool below). Seat-order
        # iteration with claim-by-better-place implements #86's
        # "higher-placed slot" rule without a full assignment solver:
        # first assign every contest's natural holders, then resolve.
        seat_defs = (
            [("captain",
              "CAPTAIN" if n_cap == 1 else "CO-CAPTAIN",
              (f"{chapter} NET Champion" if n_cap == 1 else
               f"{chapter} NET Co-Champion (T1) — shares the captaincy"))] * n_cap
            + [("fellowship", f"FELLOWSHIP CUP · {i + 1}",
                f"Final standings, top {n_fc} from the chapter")
               for i in range(n_fc)]
            + [("matchplay", f"{chapter.upper()} MATCH PLAY", "Knockout champion")]
            + [("players", f"PLAYERS CUP · {i + 1}",
                "Final standings, top 4 from the chapter") for i in range(4)]
        )

        # Pass 1 — natural holders per contest (captain: n_cap, cup: n_fc,
        # pc: 4 — always 12 seats total: n_cap + (6-(n_cap-1)) + 1 + 4)
        take = {"captain": n_cap, "fellowship": n_fc, "players": 4}
        quals: dict = {}          # cid -> list of (place, seat_order_idx, contest, name)
        order_idx = 0
        for contest, n_seats in take.items():
            for cand in streams[contest][:n_seats]:
                quals.setdefault(cand["cid"], []).append(
                    (cand["place"], order_idx, contest, cand["name"]))
            order_idx += 1
        if mp_champ and mp_champ.get("cid"):
            quals.setdefault(mp_champ["cid"], []).append(
                (1, 1.5, "matchplay", mp_champ["name"]))

        # Pass 2 — each double-qualifier keeps their best (lowest place;
        # seat order breaks cross-contest ties)
        kept: dict = {}           # cid -> (contest, place, name)
        for cid, qlist in quals.items():
            qlist.sort()
            place, _, contest, name = qlist[0]
            kept[cid] = (contest, place, name)

        roster_ids = set(kept)

        # Pass 3 — alternates pool: enrolled chapter players NOT on the
        # roster, ranked by best percentile finish, then events played
        pool_by_cid: dict = {}
        for contest in ("captain", "fellowship", "players"):
            field = field_sizes[contest] or 1
            for cand in streams[contest]:
                if cand["cid"] in roster_ids:
                    continue
                pct = cand["place"] / field
                cur = pool_by_cid.get(cand["cid"])
                if cur is None or pct < cur["pct"]:
                    pool_by_cid[cand["cid"]] = {
                        "cid": cand["cid"], "name": cand["name"],
                        "pct": pct, "place": cand["place"],
                        "field": field, "contest": contest_names[contest],
                    }
        # OPEN alternates for EVERY chapter (Kerry 2026-08-17: "add in
        # Austin alternates based on fellowship/players cup standings
        # regardless of if they bought in", widened to San Antonio the
        # same day when Pat Youngs — SA, unenrolled, T23 Players Cup —
        # had no bench rank): each bench also draws from the final
        # Fellowship Cup / Players Cup standings WITHOUT the buy-in
        # gate, ranked by the same percentile rule, so declined/vacated
        # seats always have a next man up. Earned seats stay
        # enrolled-only; only the pool opens, and enrolled pool players
        # still outrank open ones.
        open_rows = ([("fellowship", r) for r in cup["standings"]
                      if (r.get("chapter") or "") == chapter]
                     + [("players", r) for r in gross["standings"]
                        if (r.get("player_chapter") or "") == chapter])
        for contest, r in open_rows:
            cid = r.get("customer_id")
            place = pnum(r.get("rank"))
            if not cid or place is None or cid in roster_ids \
                    or cid in lsc_declined:
                continue
            field = field_sizes[contest] or 1
            pct = place / field
            cur = pool_by_cid.get(cid)
            if cur is None or (cur.get("open") and pct < cur["pct"]):
                pool_by_cid[cid] = {
                    "cid": cid, "name": r["player_name"], "pct": pct,
                    "place": place, "field": field,
                    "contest": contest_names[contest], "open": True,
                }
        # ENROLLED pool players outrank OPEN (non-bought-in) ones for
        # seats regardless of percentile — the open bench extends the
        # pool, it must never RESHUFFLE seats already held by bought-in
        # players (first live run displaced Franz/McConahy — wrong).
        pool = sorted(pool_by_cid.values(),
                      key=lambda c: (bool(c.get("open")), c["pct"],
                                     -events_by_cid.get(c["cid"], 0)))

        # Pass 4 — fill the 12 seats: contest keepers in standings order,
        # vacancies from the pool
        keepers: dict = {}
        for contest in ("captain", "fellowship", "players"):
            keepers[contest] = [
                cand for cand in streams[contest]
                if kept.get(cand["cid"], (None,))[0] == contest]
        seats = []
        pool_iter = iter(pool)
        pool_used: set = set()
        for contest, seat_label, seat_note in seat_defs:
            row = {"seat": seat_label, "note": seat_note,
                   "player_name": None, "customer_id": None,
                   "earned_as": None, "via_pool": False, "status": "tbd"}
            if contest == "matchplay":
                if mp_champ and kept.get(mp_champ.get("cid"),
                                         (None,))[0] == "matchplay":
                    # A recorded final is a FACT, not a projection — the
                    # seat is secured the same way a declared-final City
                    # NET captaincy is (Kerry 2026-08-01)
                    row.update(player_name=mp_champ["name"],
                               customer_id=mp_champ["cid"],
                               earned_as=(f"{season} {chapter} Match Play "
                                          "Champion"),
                               status="secured")
                else:
                    row["note"] = "Decided by the knockout bracket"
            elif keepers[contest]:
                cand = keepers[contest].pop(0)
                row.update(
                    player_name=cand["name"], customer_id=cand["cid"],
                    earned_as=(f"{_lsc_ordinal(cand['place'])} in "
                               f"{contest_names[contest]}"),
                    status="projected")
            else:
                nxt = next((c for c in pool_iter
                            if c["cid"] not in pool_used), None)
                if nxt:
                    pool_used.add(nxt["cid"])
                    row.update(
                        player_name=nxt["name"], customer_id=nxt["cid"],
                        earned_as=(f"Alternates pool — "
                                   f"{_lsc_ordinal(nxt['place'])} of "
                                   f"{nxt['field']} in {nxt['contest']}"),
                        via_pool=True, status="projected")
            seats.append(row)

        # Declared-final champions hold their seat as SECURED, not
        # projected — the one seat the standings can no longer move
        if champs:
            champ_ids = {c.get("customer_id") for c in champs
                         if c.get("customer_id")}
            for s in seats:
                if (s["seat"] in ("CAPTAIN", "CO-CAPTAIN")
                        and s.get("customer_id") in champ_ids):
                    s["status"] = "secured"
                    s["earned_as"] = (f"{season} {chapter} NET "
                                      f"{'Co-' if n_cap > 1 else ''}Champion")

        # Accepted invitations LOCK the held seat (Kerry 2026-08-17) —
        # only a projected seat flips; champion/MP-final secured seats
        # keep their stronger context, and TBD seats can't be accepted.
        for s in seats:
            if s.get("customer_id") in lsc_accepted \
                    and s["status"] == "projected":
                s["status"] = "secured"
                if s.get("earned_as"):
                    s["earned_as"] += " — invitation accepted"

        alternates = [
            {"player_name": c["name"], "customer_id": c["cid"],
             "percentile": round(c["pct"] * 100, 1),
             "context": (f"{_lsc_ordinal(c['place'])} of {c['field']} in "
                         f"{c['contest']}"),
             "events": events_by_cid.get(c["cid"], 0)}
            for c in pool if c["cid"] not in pool_used
        ][:alternates_cap]

        # Declined invitations (ADMIN-ONLY payload — the API route strips
        # this key for non-admin sessions): who declined + their best
        # standing in this chapter's streams, so the admin sees exactly
        # what seat claim was given up.
        declined_rows = []
        if lsc_declined:
            _dsrc = ([("captain", r) for r in net["standings"]]
                     + [("fellowship", r) for r in cup["standings"]
                        if (r.get("chapter") or "") == chapter]
                     + [("players", r) for r in gross["standings"]
                        if (r.get("player_chapter") or "") == chapter])
            _dbest: dict = {}
            for contest, r in _dsrc:
                cid = r.get("customer_id")
                if cid not in lsc_declined:
                    continue
                place = pnum(r.get("rank"))
                if place is None:
                    continue
                pct = place / (field_sizes[contest] or 1)
                if cid not in _dbest or pct < _dbest[cid]["pct"]:
                    _dbest[cid] = {"player_name": r["player_name"],
                                   "customer_id": cid, "pct": pct,
                                   "context": (f"{_lsc_ordinal(place)} in "
                                               f"{contest_names[contest]}")}
            declined_rows = [{k: v for k, v in d.items() if k != "pct"}
                             for d in _dbest.values()]

        chapters_out.append({
            "chapter": chapter,
            "seats": seats,
            "n_projected": sum(1 for r in seats
                               if r["status"] in ("projected", "secured")),
            "n_secured": sum(1 for r in seats if r["status"] == "secured"),
            "alternates": alternates,
            "declined": declined_rows,
        })

    return {
        "season": season,
        "chapters": chapters_out,
        "rules_note": ("Projected from today's standings. Double-qualifiers "
                       "take the seat where they placed higher; open seats "
                       "fill from the alternates pool."),
        "gg_error": "; ".join(dict.fromkeys(errors)) or None,
    }


def derive_member_financial_status(conn: sqlite3.Connection,
                                   customer_id: int) -> str:
    """'member' | 'alumni' | 'guest' — from TRACKER FINANCIAL TRUTH.

    D1, Kerry-ratified (mailbox #150, 2026-07-13): "Our side needs to
    dictate whether he's a member or not. We have access to the financial
    side. GG does not." The mutable customers.current_player_status column
    can be stale (it was historically nudged by GG-roster syncs — the
    Decareaux/Beam defect), so member-facing surfaces derive status at
    READ time from what was actually PAID:
      member — a customer_memberships term covering today, OR (backfill
               gap defense) an active membership purchase in the last
               366 days, OR the curated Tracker status column vouches
               member (legacy/cash joins predate the Tracker's order
               history — Mary Wade class; the column may vouch a member
               IN but can never hide one, which was the Decareaux bug);
      alumni — had a term / bought a membership at some point, not
               current ("ALUMNI" is the adopted Tracker-side term per D2
               #151; GG tag: ALUMNI going forward as memberships
               expire, legacy FORMER rows remain — Kerry 2026-07-13);
      guest  — tracked, never bought a membership.
    """
    from .timezone_utils import today_central_str
    today = today_central_str()
    current = terms = 0
    try:
        row = conn.execute(
            """SELECT MAX(CASE WHEN started_at <= ?
                               AND (expires_at IS NULL OR expires_at >= ?)
                          THEN 1 ELSE 0 END) AS cur,
                      COUNT(*) AS n
               FROM customer_memberships WHERE customer_id = ?""",
            (today, today, customer_id)).fetchone()
        current, terms = (row["cur"] or 0), (row["n"] or 0)
    except sqlite3.OperationalError:
        pass  # table not created yet on this DB — purchases decide
    if current:
        return "member"
    ps = conn.execute(
        "SELECT current_player_status AS s FROM customers WHERE customer_id = ?",
        (customer_id,)).fetchone()
    ps = ps["s"] if ps else None
    if ps in _MEMBER_PLAYER_STATUSES:
        return "member"
    buy = conn.execute(
        """SELECT MAX(order_date) AS last FROM items
           WHERE customer_id = ?
             AND LOWER(item_name) LIKE '%membership%'
             AND COALESCE(transaction_status, 'active') = 'active'""",
        (customer_id,)).fetchone()
    last = (buy["last"] or "")[:10] if buy and buy["last"] else None
    if last:
        try:
            import datetime as _dt
            if (_dt.date.fromisoformat(today)
                    - _dt.date.fromisoformat(last)).days <= 366:
                return "member"
        except ValueError:
            pass
        return "alumni"
    if terms or ps == "expired_member":
        return "alumni"
    return "guest"


def gg_roster_drift_report(urls: list[str],
                           db_path: str | Path = DB_PATH) -> dict:
    """GG Master Roster vs Tracker financial truth — the D1 drift report
    (Kerry-ratified #150): "everyone whose GG roster status ≠ Tracker
    customer status — so Kerry updates GG from a checklist, not from
    catching wrong-looking members." GG tags: Member/Guest, plus ALUMNI
    going forward for newly-lapsed (legacy FORMER rows remain — Kerry
    2026-07-13); FORMER and ALUMNI both map to alumni for comparison.

    Two sources:
    - urls=[] (DEFAULT): compare against the GG AFFILIATION tag already
      ingested with every points-race standings snapshot — that's the
      roster-derived value GG prints on its boards (the CH=G column), it
      covers every ranked player, and it needs no scraping. The GG member
      directory itself is login-gated, so this is the reliable source.
    - urls=[...]: scrape public roster-style pages (kept for when Kerry
      shares a public page that carries status tags). Parse is defensive —
      diagnostics come back when nothing parses.
    """
    from golf_genius_sync import fetch_public_page, parse_page_structure

    if not urls:
        drift, checked = [], 0
        with _connect(db_path) as conn:
            rows = conn.execute(
                """SELECT DISTINCT s.customer_id, s.affiliation,
                          TRIM(c.first_name || ' ' || c.last_name) AS name
                   FROM gg_points_standings s
                   JOIN customers c ON c.customer_id = s.customer_id
                   WHERE s.customer_id IS NOT NULL
                     AND COALESCE(s.affiliation, '') != ''""").fetchall()
            cids = list({r["customer_id"] for r in rows})
            fin = derive_member_financial_status_bulk(conn, cids)
            seen_cids = set()
            for r in rows:
                cid = r["customer_id"]
                if cid in seen_cids:
                    continue
                seen_cids.add(cid)
                aff = (r["affiliation"] or "").lower()
                # alumni/former checked BEFORE tgf — GG may render the tag
                # alongside the chapter ("TGF San Antonio Alumni"), and a
                # lapsed player must never read as member. Kerry ruling
                # 2026-07-13: GG tag going forward is ALUMNI (newly-lapsed,
                # applied as memberships expire); legacy FORMER rows remain.
                gg = ("alumni" if "former" in aff or "alumni" in aff
                      else "member" if "tgf" in aff
                      else "guest")
                checked += 1
                ours = fin.get(cid, "guest")
                if ours != gg:
                    drift.append({
                        "customer_id": cid, "name": r["name"],
                        "gg_tag": r["affiliation"],
                        "tracker_status": ours,
                        "action": f"set GG roster to "
                                  f"{'ALUMNI' if ours == 'alumni' else ours.upper()}",
                    })
        return {"drift": drift, "unresolved": [],
                "players_checked": checked,
                "source": "gg_points_standings.affiliation (ingested boards)"}

    _TAG_MAP = {"member": "member", "member+": "member",
                "former": "alumni", "alumni": "alumni",
                "guest": "guest", "1st timer": "guest",
                "first timer": "guest"}
    drift, unresolved, diagnostics = [], [], []
    checked = 0
    with _connect(db_path) as conn:
        status_cache: dict = {}

        def derived(cid):
            if cid not in status_cache:
                status_cache[cid] = derive_member_financial_status(conn, cid)
            return status_cache[cid]

        for url in urls:
            try:
                page = fetch_public_page(url)
            except Exception as e:
                diagnostics.append({"url": url, "error": str(e)})
                continue
            html = page.get("html") or ""
            parsed = parse_page_structure(html, url)
            tables = parsed.get("tables") or []
            if not tables:
                # GG pages render content via widget iframes (the proven
                # widget-route recipe) — follow them and harvest their tables
                # one capture group → findall returns the URL strings directly
                widget_urls = re.findall(
                    r"<iframe[^>]+src=[\"']([^\"']*/widgets/[a-z_0-9]+[^\"']*)[\"']",
                    html, re.I)
                import html as _html
                for wu in widget_urls[:6]:
                    wu = _html.unescape(wu)  # src attrs entity-encode &
                    if wu.startswith("/"):
                        from urllib.parse import urljoin
                        wu = urljoin(url, wu)
                    try:
                        # plain GET (no xhr): widgets serve a full HTML page
                        # with tables; xhr returns a JS partial (the proven
                        # gg_history recipe)
                        wpage = fetch_public_page(wu)
                        wparsed = parse_page_structure(wpage.get("html") or "", wu)
                        tables.extend(wparsed.get("tables") or [])
                    except Exception as e:
                        diagnostics.append({"url": wu, "error": str(e)})
                if widget_urls and not tables:
                    diagnostics.append({"url": url,
                                        "widgets_followed": widget_urls[:6],
                                        "note": "widgets returned no tables"})
            hits = 0
            for tbl in tables:
                if not tbl or len(tbl) < 2:
                    continue
                head = [(c or "").strip().lower() for c in tbl[0]]
                name_i = next((i for i, h in enumerate(head)
                               if "name" in h or "player" in h), None)
                tag_i = next((i for i, h in enumerate(head)
                              if "status" in h or "type" in h
                              or "member" in h), None)
                rows = tbl[1:] if name_i is not None else tbl
                for r in rows:
                    cells = [(c or "").strip() for c in r]
                    if name_i is not None and tag_i is not None:
                        nm = cells[name_i] if name_i < len(cells) else ""
                        tag = (cells[tag_i] if tag_i < len(cells) else "").lower()
                    else:
                        # headerless fallback: a status-looking cell + the
                        # longest other cell as the name
                        tag = next((c.lower() for c in cells
                                    if c.lower() in _TAG_MAP), "")
                        others = [c for c in cells if c.lower() != tag and c]
                        nm = max(others, key=len) if others else ""
                    if not nm or tag not in _TAG_MAP:
                        continue
                    hits += 1
                    checked += 1
                    cid = _resolve_scoring_player(conn, nm)
                    if not cid:
                        unresolved.append({"gg_name": nm, "gg_tag": tag})
                        continue
                    ours = derived(cid)
                    if ours != _TAG_MAP[tag]:
                        crow = conn.execute(
                            "SELECT TRIM(first_name || ' ' || last_name) AS n"
                            " FROM customers WHERE customer_id = ?",
                            (cid,)).fetchone()
                        drift.append({
                            "customer_id": cid,
                            "name": crow["n"] if crow else nm,
                            "gg_tag": tag,
                            "tracker_status": ours,
                            "action": f"set GG roster to "
                                      f"{'ALUMNI' if ours == 'alumni' else ours.upper()}",
                        })
            if not hits:
                diagnostics.append({
                    "url": url, "tables_seen": len(tables),
                    "first_headers": tables[0][0] if tables and tables[0] else None,
                    "note": "no roster rows recognized — adjust parser to this page",
                })
    return {"drift": drift, "unresolved": unresolved,
            "players_checked": checked, "diagnostics": diagnostics}


def derive_member_financial_status_bulk(conn: sqlite3.Connection,
                                        cids: list[int]) -> dict:
    """{customer_id: 'member'|'alumni'|'guest'} for many players in three
    queries — the boards path (R4) can't afford per-row derivation."""
    from .timezone_utils import today_central_str
    import datetime as _dt
    today = today_central_str()
    out = {cid: "guest" for cid in cids}
    if not cids:
        return out
    qmarks = ",".join("?" * len(cids))
    try:
        for r in conn.execute(
                f"""SELECT customer_id,
                           MAX(CASE WHEN started_at <= ?
                                    AND (expires_at IS NULL OR expires_at >= ?)
                               THEN 1 ELSE 0 END) AS cur
                    FROM customer_memberships
                    WHERE customer_id IN ({qmarks})
                    GROUP BY customer_id""",
                (today, today, *cids)).fetchall():
            out[r["customer_id"]] = "member" if r["cur"] else "alumni"
    except sqlite3.OperationalError:
        pass
    for r in conn.execute(
            f"""SELECT customer_id, MAX(order_date) AS last FROM items
                WHERE customer_id IN ({qmarks})
                  AND LOWER(item_name) LIKE '%membership%'
                  AND COALESCE(transaction_status, 'active') = 'active'
                GROUP BY customer_id""",
            cids).fetchall():
        if out.get(r["customer_id"]) == "member":
            continue
        last = (r["last"] or "")[:10]
        try:
            fresh = (last and (_dt.date.fromisoformat(today)
                               - _dt.date.fromisoformat(last)).days <= 366)
        except ValueError:
            fresh = False
        out[r["customer_id"]] = "member" if fresh else "alumni"
    # curated status column vouches members IN (legacy/cash joins predate
    # the order history); expired_member marks alumni. It never demotes.
    for r in conn.execute(
            f"""SELECT customer_id, current_player_status AS s FROM customers
                WHERE customer_id IN ({qmarks})""", cids).fetchall():
        if r["s"] in _MEMBER_PLAYER_STATUSES:
            out[r["customer_id"]] = "member"
        elif r["s"] == "expired_member" and out.get(r["customer_id"]) == "guest":
            out[r["customer_id"]] = "alumni"
    return out


def search_spotlight_players(q: str, limit: int = 12,
                             db_path: str | Path = DB_PATH) -> list[dict]:
    """Name typeahead for the Player Spotlight (admin preview v1).

    PII-FREE BY DESIGN: returns customer_id, display name, and chapter
    only — this endpoint is destined for the pinless member tier once
    Kerry opens the page up, so nothing else may ever be added here.
    R3 (Kerry-ratified #149/#151): index EVERYONE tracked — members,
    guests, alumni, historical — "if we track it, they have a presence."
    The old members-only status filter made current members invisible
    whenever the status column went stale (the Decareaux defect).
    """
    q = (q or "").strip()
    if len(q) < 2:
        return []
    like = f"%{q}%"
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT customer_id,
                      TRIM(first_name || ' ' || last_name) AS name, chapter
               FROM customers
               WHERE (first_name || ' ' || last_name) LIKE ? COLLATE NOCASE
                 AND TRIM(COALESCE(first_name, '') || COALESCE(last_name, '')) != ''
                 AND COALESCE(account_status, 'active') NOT IN
                     ('merged', 'archived', 'deleted')
               ORDER BY last_name COLLATE NOCASE, first_name COLLATE NOCASE
               LIMIT ?""",
            (like, limit),
        ).fetchall()
    return [dict(r) for r in rows]


def _spotlight_scoring(conn, customer_id: int) -> dict | None:
    """Per-hole scoring aggregate for the Spotlight SCORING card
    (mailbox #103/#104 — design-claude's density pass; Kerry asked for
    "simple, not big" individual scoring stats).

    Window = ALL of the CURRENT SEASON's tracked rounds (Kerry,
    2026-07-12: averages + the birdies/pars distribution show the whole
    year; the calendar-year filter also keeps archive-era imports out
    by construction). Trend = recent FORM off the last 10 rounds only:
    latest 5 vs the 5 before, earned at 10+ tracked rounds. Negative
    trend = improving (fewer strokes). Par comes from course_tee_holes
    via the round's tee; holes with no strokes or no par are skipped.
    Returns None when the player has no tracked rounds.
    """
    from .timezone_utils import today_central
    season_start = f"{today_central().year}-01-01"
    rounds = conn.execute(
        """SELECT id, holes_played, gross FROM scoring_rounds
           WHERE customer_id = ? AND gross IS NOT NULL
             AND round_date >= ?
           ORDER BY round_date DESC, id DESC""",
        (customer_id, season_start),
    ).fetchall()
    if not rounds:
        return None
    ids = [r["id"] for r in rounds]
    recent_ids = set(ids[:5])    # trend halves: last 10 rounds, 5 vs 5
    prior_ids = set(ids[5:10])
    qmarks = ",".join("?" * len(ids))
    holes = conn.execute(
        f"""SELECT sh.scoring_round_id AS rid, sh.strokes, cth.par
            FROM scoring_holes sh
            JOIN scoring_rounds sr ON sr.id = sh.scoring_round_id
            LEFT JOIN course_tee_holes cth
                   ON cth.tee_id = sr.tee_id
                  AND cth.hole_number = sh.hole_number
            WHERE sh.scoring_round_id IN ({qmarks})
              AND sh.strokes IS NOT NULL""",
        ids,
    ).fetchall()

    par_sums: dict = {3: [0, 0], 4: [0, 0], 5: [0, 0]}   # strokes, holes
    par_half: dict = {3: [[0, 0], [0, 0]], 4: [[0, 0], [0, 0]],
                      5: [[0, 0], [0, 0]]}               # [recent, prior]
    dist = {"eagle_plus": 0, "birdie": 0, "par": 0, "bogey": 0, "other": 0}
    for h in holes:
        par, strokes = h["par"], h["strokes"]
        if par not in (3, 4, 5):
            continue
        par_sums[par][0] += strokes
        par_sums[par][1] += 1
        if h["rid"] in recent_ids:
            par_half[par][0][0] += strokes
            par_half[par][0][1] += 1
        elif h["rid"] in prior_ids:
            par_half[par][1][0] += strokes
            par_half[par][1][1] += 1
        diff = strokes - par
        if diff <= -2:
            dist["eagle_plus"] += 1
        elif diff == -1:
            dist["birdie"] += 1
        elif diff == 0:
            dist["par"] += 1
        elif diff == 1:
            dist["bogey"] += 1
        else:
            dist["other"] += 1

    # trend needs a real prior half — at least 5 prior rounds
    trend_ok = len(prior_ids) >= 5
    par_avgs = {}
    for p in (3, 4, 5):
        tot, n = par_sums[p]
        (rs, rn), (ps, pn) = par_half[p]
        trend = (round(rs / rn - ps / pn, 2)
                 if trend_ok and rn and pn else None)
        par_avgs[str(p)] = {
            "avg": round(tot / n, 2) if n else None,
            "trend": trend, "holes": n,
        }

    def gross_line(hp):
        rows = [r for r in rounds if r["holes_played"] == hp]
        if not rows:
            return None
        rec = [r["gross"] for r in rows if r["id"] in recent_ids]
        pri = [r["gross"] for r in rows if r["id"] in prior_ids]
        trend = (round(sum(rec) / len(rec) - sum(pri) / len(pri), 1)
                 if trend_ok and len(rec) >= 2 and len(pri) >= 2 else None)
        return {"avg": round(sum(r["gross"] for r in rows) / len(rows), 1),
                "trend": trend, "n": len(rows)}

    return {
        "window_rounds": len(rounds),
        "par_avgs": par_avgs,
        "distribution": dist,
        "avg_gross_9": gross_line(9),
        "avg_gross_18": gross_line(18),
    }


def _spotlight_assign_payouts(standings: list, pp: dict | None,
                              tie_key: str) -> dict:
    """customer_id -> projected payout cents if the season ended today.

    Server-side mirror of the CONTESTS page's prAssignProjectedPayouts:
    money walks the ENROLLED players in standings order (it visibly
    skips non-enrolled rows), tie groups split their combined places
    cent-exact. Flights races pay the champion bonus to the overall
    enrolled leader(s) and [1st, 2nd] within each flight; awards stack.
    """
    if not pp:
        return {}
    out: dict = {}
    enrolled = [r for r in standings
                if r.get("enrolled") and r.get("customer_id")]

    def split(rows, amounts):
        total = sum(amounts)
        if not rows or total <= 0:
            return
        base, rem = divmod(total, len(rows))
        for i, r in enumerate(rows):
            out[r["customer_id"]] = (out.get(r["customer_id"], 0)
                                     + base + (1 if i < rem else 0))

    def walk(players, amounts):
        i = 0
        while i < len(players) and i < len(amounts):
            j = i
            while (j + 1 < len(players)
                   and players[j + 1].get(tie_key) == players[i].get(tie_key)):
                j += 1
            split(players[i:j + 1], amounts[i:j + 1])
            i = j + 1

    if pp.get("kind") == "ladder":
        walk(enrolled, pp.get("amounts_cents") or [])
    elif pp.get("kind") == "flights":
        if enrolled:
            lead = [enrolled[0]]
            k = 1
            while (k < len(enrolled)
                   and enrolled[k].get(tie_key) == enrolled[0].get(tie_key)):
                lead.append(enrolled[k])
                k += 1
            split(lead, [pp.get("champion_cents") or 0])
        flights: dict = {}
        for r in enrolled:
            if r.get("flight"):
                flights.setdefault(r["flight"], []).append(r)
        for rows in flights.values():
            walk(rows, [pp.get("flight_first_cents") or 0,
                        pp.get("flight_second_cents") or 0])
    return out


# Payout category display names (server-side mirror of the tgf.html /
# events.html maps) — used by member-facing winnings labels.
_PAYOUT_CAT_LABELS = {
    "team_net": "Team Net", "individual_net": "Individual Net",
    "individual_gross": "Individual Gross", "skins": "Skins",
    "closest_to_pin": "Closest to Pin", "ctp": "Closest to Pin",
    "hole_in_one": "Hole in One",
    "mvp": "City MVP", "tgf_mvp": "TGF MVP",
    "monthly_points": "Monthly Points", "other": "Other",
    # season-standings payouts store their category as a display string
    "City Net": "City Points Race", "City Gross": "City Points Race",
}


def get_player_spotlight(customer_id: int,
                         db_path: str | Path = DB_PATH) -> dict:
    """PLAYER SPOTLIGHT payload (v1, admin preview — Kerry directed
    2026-07-10; opens to members after CA/CD iteration).

    One player's overview: profile, current handicap index, headline
    stats, where they stand in every points race / cup / match play,
    fall buy-ins, projected Lone Star Cup seat, and recent winnings.

    PII-FREE BY DESIGN: name, chapter, and competitive data only — no
    emails/phones/addresses/DOB — so flipping the routes to the member
    tier later is a role-string change, not a data audit. Standings come
    from the same persisted snapshots the CONTESTS page serves.
    """
    with _connect(db_path) as conn:
        cust = conn.execute(
            """SELECT customer_id, first_name, last_name, suffix, chapter,
                      current_player_status
               FROM customers WHERE customer_id = ?""",
            (customer_id,),
        ).fetchone()
        if not cust:
            return {"error": "player not found"}
        name = " ".join(x for x in (cust["first_name"], cust["last_name"],
                                    cust["suffix"]) if x)
        # D1 (Kerry #150): status from Tracker financial truth, not the
        # mutable status column (which GG-roster syncs can leave stale).
        member_status = derive_member_financial_status(conn, customer_id)
        is_member = member_status == "member"

        # F18 (Kerry #150/#151 + screenshots 2026-07-13): EVENTS = ALL
        # events actually played this season, regardless of status
        # (member/guest/1st-timer/alumni) — distinct events among the
        # season's tracked rounds. The old derivation read the points-race
        # standings' "tournaments" column, so guests/non-enrolled players
        # showed 0-1 (Beam 0 vs 2 rounds; Decareaux 1 vs 5).
        from .timezone_utils import today_central
        _season_start = f"{today_central().year}-01-01"
        _ev = conn.execute(
            """SELECT COUNT(DISTINCT COALESCE(event_id, 'd:' || COALESCE(round_date, '?'))) AS n
               FROM scoring_rounds
               WHERE customer_id = ? AND round_date >= ?
                 AND COALESCE(source, 'gg') NOT LIKE 'gg_history%'""",
            (customer_id, _season_start)).fetchone()
        events_played_rounds = (_ev["n"] or 0) if _ev else 0

        # current handicap index via handicap_player_links (canonical path)
        idx18 = None
        handicap_player_name = None      # deep-link target on /handicaps
        idx_by_name = {
            hp["player_name"]: hp["handicap_index_18"]
            for hp in get_all_handicap_players(db_path)
            if hp.get("handicap_index_18") is not None
        }
        for lr in conn.execute(
                "SELECT player_name FROM handicap_player_links "
                "WHERE customer_id = ?", (customer_id,)).fetchall():
            v = idx_by_name.get(lr["player_name"])
            if v is not None:
                idx18 = v
                handicap_player_name = lr["player_name"]
                break

        enrollments = [dict(r) for r in conn.execute(
            """SELECT contest_type, chapter, season FROM season_contests
               WHERE customer_id = ? ORDER BY season, contest_type""",
            (customer_id,)).fetchall()]

        try:
            scoring = _spotlight_scoring(conn, customer_id)
        except Exception:
            logger.warning("spotlight scoring aggregate failed",
                           exc_info=True)
            scoring = None

    # ── points races (persisted snapshots — same source as CONTESTS) ──
    # in_reach (mailbox #99 item 1, Kerry-RATIFIED): points to the place
    # above, what they'd cash today, the next rung up, and the live pot.
    # race_pots covers EVERY race (entered or not) so the "doorway" and
    # invitation empty-states (#99 items 3-4) can quote live money.
    def in_reach_for(row, standings, pp, tie_key):
        pay_map = _spotlight_assign_payouts(standings, pp, tie_key)
        mine = row.get(tie_key)
        gap = None
        for r in standings:
            v = r.get(tie_key)
            if v is not None and mine is not None and v > mine:
                gap = v  # standings are ordered; last one seen above wins
        gap = (round(gap - mine, 2) if gap is not None and mine is not None
               else None)
        my_pay = pay_map.get(row.get("customer_id"), 0)
        rungs = sorted({v for v in pay_map.values() if v > my_pay})
        if not rungs and pp:
            rungs = sorted(a for a in (pp.get("amounts_cents")
                                       or [pp.get("flight_first_cents") or 0])
                           if a > my_pay)
        return {
            "points_to_next": gap,
            "projected_payout_cents": my_pay,
            "next_payout_cents": rungs[0] if rungs else None,
            "pot_cents": (pp or {}).get("pot_cents"),
        }

    # Canonical SERVER-SIDE drama lines (#99 items 1/3, CA GO #120 bind
    # conditions: templates live here, every number from the live
    # payload). kind drives the UI color: leader/in_money/chase/invite.
    def _drama_money(c):
        d = c / 100
        return "$" + (f"{d:,.2f}" if c % 100 else f"{d:,.0f}")

    def drama_for(rank, enrolled, reach, pot_cents):
        if not enrolled:
            return ({"kind": "invite",
                     "text": f"{_drama_money(pot_cents)} pot and growing — not entered yet"}
                    if pot_cents else None)
        if not reach:
            return None
        my = reach.get("projected_payout_cents") or 0
        nxt, gap = reach.get("next_payout_cents"), reach.get("points_to_next")
        if my and str(rank) in ("1", "T1"):
            return {"kind": "leader",
                    "text": f"Leading the race — {_drama_money(my)} projected today"}
        if my:
            t = f"In the money — {_drama_money(my)} projected"
            if nxt and gap is not None:
                t += f" · {gap:g} pts to the {_drama_money(nxt)} rung"
            return {"kind": "in_money", "text": t}
        if nxt and gap is not None:
            return {"kind": "chase",
                    "text": f"Only {gap:g} pts from the money ({_drama_money(nxt)})"}
        if nxt:
            return {"kind": "chase",
                    "text": f"First money rung: {_drama_money(nxt)}"}
        return None

    # Reset-aware field position (Kerry 2026-08-03: the Points Reset is
    # TGF's Tour Championship — it puts ~30 players within range of
    # winning it all): points back from the leader plus how many players
    # sit within 15 points of the lead, computed on the reset seeds when
    # they exist, else on live points. Rides every race entry so the
    # Spotlight and the snapshot email tell the same story.
    def _field_extras(standings, row):
        def val(r):
            return (r.get("points_reset") if r.get("points_reset") is not None
                    else r.get("total_points"))
        pool = [r for r in standings if val(r) is not None]
        if any(r.get("enrolled") for r in pool):
            # the player belongs in their own comparison field even when
            # not bought in — otherwise a non-enrolled player who out-
            # scores every enrolled player reads as NEGATIVE points back
            pool = [r for r in pool if r.get("enrolled")
                    or r.get("customer_id") == customer_id]
        if not pool:
            return {}
        lead = max(val(r) for r in pool)
        mine = val(row)
        return {
            "leader_points": lead,
            "points_back": (round(lead - mine, 2) if mine is not None else None),
            "n_within_15": sum(1 for r in pool if lead - val(r) <= 15),
        }

    races, errors, events_played = [], [], 0
    race_pots: dict = {}
    member_card = None
    gross_d = None          # kept for the LONE STAR CUP line below
    cup_d = None
    # Free-text status badges per race (Kerry 2026-08-06) — a DIAL
    # (race_status_notes app setting, JSON {race_key: text}) so wording
    # like "Ends Aug 15-16" is editable without a deploy. COMPLETED is
    # derived from the race_final flag, never from this dial.
    try:
        _race_status_notes = json.loads(
            get_app_setting("race_status_notes", db_path=db_path) or "{}")
        if not isinstance(_race_status_notes, dict):
            _race_status_notes = {}
    except Exception:
        _race_status_notes = {}
    # City MVP count per chapter for the net-race cards (Kerry 2026-08-06:
    # "change wins to count MVPs... Only count MVPs per event, not per 9").
    # event_mvp_computed is keyed per EVENT by construction — the per-nine
    # drill-down rows only DISPLAY the badge twice; our engine's
    # determination (determine_tgf_mvp) is the authority.
    mvps_by_chapter: dict = {}
    try:
        with _connect(db_path) as conn:
            for r in conn.execute(
                    """SELECT COALESCE(e.chapter, '') AS ch,
                              COUNT(DISTINCT m.event_id) AS n
                         FROM event_mvp_computed m
                         JOIN events e ON e.id = m.event_id
                        WHERE m.customer_id = ? AND m.kind = 'mvp'
                        GROUP BY COALESCE(e.chapter, '')""",
                    (customer_id,)).fetchall():
                mvps_by_chapter[(r["ch"] or "").strip()] = r["n"]
    except Exception:
        logger.warning("spotlight MVP count failed", exc_info=True)
    for key in _GG_POINTS_RACES:
        try:
            # LIVE path, same as the CONTESTS page (Kerry 2026-08-03:
            # "WHERE PLAYER STANDS is not all updated") — the base
            # snapshots lag championship points and the reset
            # re-projection; the live read carries both.
            d = get_points_race_live(key, db_path=db_path)
            if key == "players_cup_gross":
                gross_d = d
        except Exception as e:
            errors.append(f"{key}: {e}")
            continue
        if d.get("gg_error"):
            errors.append(d["gg_error"])
        pp = d.get("projected_payouts")
        race_pots[key] = {
            "label": d["label"], "chapter": d["chapter"],
            "pot_cents": (pp or {}).get("pot_cents"),
            "n_enrolled": d.get("n_enrolled"),
        }
        row = next((r for r in d["standings"]
                    if r.get("customer_id") == customer_id), None)
        if not row:
            continue
        events_played = max(events_played, row.get("tournaments") or 0)
        if row.get("member_card_id"):
            member_card = member_card or {
                "race": key, "card": row["member_card_id"]}
        # Flighted races (Players Cup) rank WITHIN the flight (Kerry,
        # 2026-07-12) — "16 of 119" is meaningless when the money and the
        # race are per-flight; show "4 of 32 · 2ND FLIGHT" instead.
        rank, n_players = row["rank"], d["n_players"]
        if row.get("flight"):
            mates = [r for r in d["standings"]
                     if r.get("flight") == row["flight"]]
            mine = row.get("total_points") or 0
            better = sum(1 for r in mates
                         if (r.get("total_points") or 0) > mine)
            tied = sum(1 for r in mates
                       if (r.get("total_points") or 0) == mine)
            rank = ("T" if tied > 1 else "") + str(better + 1)
            n_players = len(mates)
        races.append({
            "key": key, "label": d["label"],
            "rank": rank, "n_players": n_players,
            "total_points": row.get("total_points"),
            "tournaments": row.get("tournaments"),
            "wins": row.get("wins"),
            "mvps": (mvps_by_chapter.get("Austin") if key == "austin_net"
                     else mvps_by_chapter.get("San Antonio")
                     if key == "san_antonio_net" else None),
            "enrolled": bool(row.get("enrolled")),
            # Status badge feed (Kerry 2026-08-06: "some type of badge
            # ... that gives status of the contest"): final -> COMPLETED;
            # status_note (race_status_notes dial, {race_key: text}) ->
            # free-text badge like "Ends Aug 15-16" for races whose
            # race_final never flips (THE PLAYERS CUP).
            "final": bool(d.get("race_final")),
            "status_note": _race_status_notes.get(key),
            "flight": row.get("flight"),
            "points_reset": row.get("points_reset"),
            "in_reach": in_reach_for(row, d["standings"], pp,
                                     "total_points"),
        })
        races[-1].update(_field_extras(d["standings"], row))
        races[-1]["drama"] = drama_for(
            row["rank"], bool(row.get("enrolled")), races[-1]["in_reach"],
            (pp or {}).get("pot_cents"))
    try:
        cup = get_fellowship_cup_projection(db_path=db_path)
        cup_d = cup
        pp = cup.get("projected_payouts")
        race_pots["fellowship_cup"] = {
            "label": "THE FELLOWSHIP CUP", "chapter": None,
            "pot_cents": (pp or {}).get("pot_cents"),
            "n_enrolled": cup.get("n_enrolled"),
        }
        crow = next((r for r in cup["standings"]
                     if r.get("customer_id") == customer_id), None)
        if crow:
            races.append({
                "key": "fellowship_cup", "label": "THE FELLOWSHIP CUP",
                "rank": crow["rank"], "n_players": cup["n_players"],
                "total_points": crow.get("points_reset"),
                "tournaments": None, "wins": None,
                "enrolled": bool(crow.get("enrolled")),
                "final": False,
                "status_note": _race_status_notes.get("fellowship_cup"),
                "flight": None, "points_reset": crow.get("points_reset"),
                "in_reach": in_reach_for(crow, cup["standings"], pp,
                                         "points_reset"),
            })
            races[-1].update(_field_extras(cup["standings"], crow))
            races[-1]["drama"] = drama_for(
                crow["rank"], bool(crow.get("enrolled")),
                races[-1]["in_reach"], (pp or {}).get("pot_cents"))
    except Exception as e:
        errors.append(f"fellowship cup: {e}")

    # fall buy-ins (standings light up when the GG races exist)
    fall = [e for e in enrollments
            if e["contest_type"] == "NET Points Race"
            and (e["season"] or "").endswith("Fall")]

    # ── match play ──
    match_play = None
    mp_enr = next((e for e in enrollments
                   if e["contest_type"] == "City Match Play"), None)
    if mp_enr:
        season = str(today_central().year)
        try:
            rows = cmp_get_standings(season, mp_enr["chapter"],
                                     db_path=db_path)
            mrow = next(
                (r for r in rows
                 if (r.get("customer_name") or r.get("player_name") or "")
                 .strip().lower() == name.strip().lower()), None)
            match_play = {
                "chapter": mp_enr["chapter"], "enrolled": True,
                "pool": (mrow or {}).get("pool_name"),
                "wins": (mrow or {}).get("wins"),
                "losses": (mrow or {}).get("losses"),
                "draws": (mrow or {}).get("draws"),
                "stableford": (mrow or {}).get("pts"),
            }
        except Exception as e:
            errors.append(f"match play: {e}")
            match_play = {"chapter": mp_enr["chapter"], "enrolled": True}

    # ── LONE STAR CUP line (Kerry 2026-08-03): every player sees it until
    #    the selection deadline (dial lsc_selection_deadline, default
    #    2026-08-14); after that only players bought into either cup keep
    #    it. Non-enrolled players get their HYPOTHETICAL landing spot —
    #    the best projection of either cup path if the season ended today
    #    and they bought in — as the conversion nudge. ──
    lsc = None
    try:
        _deadline = (get_app_setting("lsc_selection_deadline",
                                     db_path=db_path) or "2026-08-14")
        from .timezone_utils import today_central_str as _tcs
        _pre_deadline = _tcs() < _deadline

        my_ch = (cust["chapter"] or "").strip()
        crow_ = next((r for r in (cup_d or {}).get("standings", [])
                      if r.get("customer_id") == customer_id), None)
        grow_ = next((r for r in (gross_d or {}).get("standings", [])
                      if r.get("customer_id") == customer_id), None)
        enrolled_any = bool((crow_ and crow_.get("enrolled"))
                            or (grow_ and grow_.get("enrolled")))

        proj = get_lone_star_cup_projection(db_path=db_path)
        for ch in proj["chapters"]:
            seat = next((r for r in ch["seats"]
                         if r.get("customer_id") == customer_id), None)
            if seat:
                lsc = {"mode": "seat", "chapter": ch["chapter"],
                       "seat": seat["seat"], "earned_as": seat["earned_as"],
                       "via_pool": seat["via_pool"],
                       # secured (declared-final champion / recorded MP
                       # final) vs projected (standings can still move) —
                       # Kerry 2026-08-03: "How do we differentiate?"
                       "status": seat.get("status") or "projected"}
                break
            alt = next((i for i, a in enumerate(ch["alternates"])
                        if a.get("customer_id") == customer_id), None)
            if alt is not None:
                lsc = {"mode": "alternate", "chapter": ch["chapter"],
                       "alternate_rank": alt + 1}
                break

        if lsc is None and (enrolled_any or _pre_deadline):
            # Place on each cup path among the players who'd actually
            # compete for the chapter's seats — currently-enrolled chapter
            # players (plus this player). Fellowship seat count comes off
            # the REAL projection (a co-captain year shaves it 6 -> 5,
            # Kerry-confirmed 2026-08-03); Players Cup is always 4.
            fc_seats = 6
            _chp = next((c for c in proj.get("chapters", [])
                         if c.get("chapter") == my_ch), None)
            if _chp:
                fc_seats = sum(
                    1 for s in _chp.get("seats", [])
                    if str(s.get("seat", "")).startswith("THE FELLOWSHIP CUP")
                ) or 6
            def _path_stats(rows, ch_field, seats):
                # Place among the enrolled chapter field, PLUS the seat-
                # line measurement (Kerry 2026-08-03: "making your city's
                # Lone Star Cup team is an even lower bar. Measuring from
                # that on either the Fellowship or Players Cup would be
                # really good"): the points the LAST seat currently holds
                # and this player's gap to it (positive = inside).
                def _val(r):
                    return (r.get("points_reset")
                            if r.get("points_reset") is not None
                            else r.get("total_points"))
                place, vals, mine, seen = 0, [], None, False
                for r in rows or []:
                    if (r.get(ch_field) or "").strip() != my_ch:
                        continue
                    if r.get("customer_id") == customer_id:
                        mine, seen = _val(r), True
                        continue
                    if r.get("enrolled"):
                        vals.append(_val(r))
                        if not seen:
                            place += 1
                if not seen:
                    return None
                cut = (vals[seats - 1] if len(vals) >= seats
                       and vals[seats - 1] is not None else None)
                return {"place": place + 1, "seats": seats,
                        "seat_cut_points": cut, "my_points": mine,
                        "gap_to_seat": (round(mine - cut, 2)
                                        if mine is not None and cut is not None
                                        else None)}

            paths = []
            if cup_d:
                p = _path_stats(cup_d.get("standings"), "chapter", fc_seats)
                if p:
                    paths.append({"path": "THE FELLOWSHIP CUP", **p})
            if gross_d:
                p = _path_stats(gross_d.get("standings"), "player_chapter", 4)
                if p:
                    paths.append({"path": "THE PLAYERS CUP", **p})
            if paths:
                best = min(paths, key=lambda x: (x["place"] > x["seats"],
                                                 x["place"] / x["seats"]))
                lsc = {"mode": "in_hunt" if enrolled_any else "hypothetical",
                       "chapter": my_ch, "path": best["path"],
                       "place": best["place"], "seats": best["seats"],
                       "seat_cut_points": best.get("seat_cut_points"),
                       "my_points": best.get("my_points"),
                       "gap_to_seat": best.get("gap_to_seat"),
                       "paths": paths}

        # Post-deadline the line narrows to players in the running
        if lsc and not _pre_deadline and not enrolled_any \
                and lsc.get("mode") in ("hypothetical",):
            lsc = None
    except Exception as e:
        errors.append(f"lone star cup: {e}")

    # ── winnings ──
    # recent_events groups the rows per EVENT (Kerry 2026-08-03: "recent
    # winnings to show event totals... expand to see which games and
    # amounts"); recent_payouts stays for backward compatibility. Each
    # game carries a FRIENDLY label ("Individual Net — 1st Place | Low
    # Flight") — the raw category/description read like gobbledygook
    # (Kerry, same day).
    total_winnings, recent_payouts, recent_events = 0, [], []
    try:
        w = get_customer_winnings(name, db_path=db_path,
                                  customer_id=customer_id)
        total_winnings = w.get("total_winnings") or 0
        recent_payouts = (w.get("payouts") or [])[:5]

        def _team_partners(event_name):
            """Teammates' last names via scoring_rounds.team_num — event
            matched by its code prefix ('s18.8 …')."""
            code = (event_name or "").split(" ")[0].strip()
            if not code:
                return []
            try:
                with _connect(db_path) as _c:
                    rows_ = _c.execute(
                        """SELECT DISTINCT sr2.player_name
                           FROM scoring_rounds sr
                           JOIN events e ON e.id = sr.event_id
                           JOIN scoring_rounds sr2
                             ON sr2.event_id = sr.event_id
                            AND sr2.team_num = sr.team_num
                            AND sr2.customer_id IS NOT sr.customer_id
                           WHERE sr.customer_id = ? AND sr.team_num IS NOT NULL
                             AND e.item_name LIKE ?""",
                        (customer_id, f"{code}%")).fetchall()
                out_, seen_ = [], set()
                for r_ in rows_:
                    nm_ = (r_["player_name"] or "").strip()
                    last = (nm_.split(",")[0].strip().title() if "," in nm_
                            else (nm_.split()[-1].title() if nm_ else ""))
                    if last and last.lower() not in seen_:
                        seen_.add(last.lower())
                        out_.append(last)
                return out_
            except Exception:
                return []

        def _friendly_game(p, partners):
            cat = p.get("category") or ""
            desc = p.get("description") or ""
            label = _PAYOUT_CAT_LABELS.get(cat) or (
                cat.replace("_", " ").title() if cat else "Payout")
            bits = []
            # "SAN ANTONIO Net 2026 final standings — 2 place" (season
            # payout rows) → "2nd Place | Season Standings"
            fs_ = re.search(r"final standings\s*[—\-]\s*(\d+)\s*place",
                            desc, re.I)
            if fs_:
                n_ = int(fs_.group(1))
                suf_ = ("th" if 10 <= n_ % 100 <= 13
                        else {1: "st", 2: "nd", 3: "rd"}.get(n_ % 10, "th"))
                bits.append(f"{n_}{suf_} Place | Season Standings")
            m = re.search(r"\b(\d+)(st|nd|rd|th)\b", desc)
            tied = "(T)" in desc
            if m and cat != "skins" and not fs_:
                bits.append(f"{'T' if tied else ''}{m.group(1)}{m.group(2)} Place")
            if cat == "skins":
                hm = re.search(r"holes?\s+([\d,\s&]+)", desc, re.I)
                cm = re.search(r"×\s*(\d+)", desc)
                if hm:
                    _hl = [h for h in re.split(r"[\s,&]+", hm.group(1)) if h]
                    bits.append(("Hole " if len(_hl) == 1 else "Holes ")
                                + (" & ".join(_hl) if len(_hl) <= 2
                                   else ", ".join(_hl[:-1]) + " & " + _hl[-1]))
                elif cm:
                    n_ = int(cm.group(1))
                    bits.append(f"{n_} skin{'s' if n_ != 1 else ''}")
            if cat in ("closest_to_pin", "ctp"):
                pm = re.search(r"#\s*(\d+)", desc)
                if pm:
                    bits.append(f"Hole {pm.group(1)}")
            fm = re.search(r"\b(LOW|MID|HIGH)\b[\s-]*Flight", desc, re.I)
            fn = re.search(r"Flight\s*(\d+)", desc, re.I)
            if fm:
                bits.append(f"{fm.group(1).title()} Flight")
            elif fn:
                bits.append(f"Flight {fn.group(1)}")
            if cat == "team_net" and partners:
                _w = "w/ " + " & ".join(partners)
                if bits:
                    bits[-1] += f" {_w}"     # "T1st Place w/ Smith & Jones"
                else:
                    bits.append(_w)
            if bits:
                return f"{label} — {' | '.join(bits)}"
            # desc that merely restates the label collapses ("TGF MVP
            # (combined same-day pot)" → "TGF MVP — combined same-day pot")
            if desc and desc.lower().startswith(label.lower()):
                rest = desc[len(label):].strip(" -—()")
                return label + (f" — {rest}" if rest else "")
            return label + (f" — {desc}" if desc
                            and desc.lower() != label.lower() else "")

        by_event: dict = {}
        ev_order: list = []
        partners_cache: dict = {}
        for p in (w.get("payouts") or []):     # already event_date DESC
            k = (p.get("event_name"), p.get("event_date"))
            if k not in by_event:
                if len(ev_order) >= 6:
                    continue
                by_event[k] = {"event_name": p.get("event_name"),
                               "event_date": p.get("event_date"),
                               "total": 0.0, "games": []}
                ev_order.append(k)
            partners = []
            if (p.get("category") or "") == "team_net":
                if k not in partners_cache:
                    partners_cache[k] = _team_partners(p.get("event_name"))
                partners = partners_cache[k]
            by_event[k]["total"] = round(
                by_event[k]["total"] + (p.get("amount") or 0), 2)
            by_event[k]["games"].append({
                "category": p.get("category"),
                "description": p.get("description"),
                "label": _friendly_game(p, partners),
                "amount": p.get("amount")})
        recent_events = [by_event[k] for k in ev_order]
    except Exception as e:
        errors.append(f"winnings: {e}")

    return {
        "customer_id": customer_id,
        "name": name,
        "chapter": cust["chapter"],
        "is_member": is_member,
        "member_status": member_status,  # 'member' | 'alumni' | 'guest' (D1)
        "handicap_index_18": idx18,
        "handicap_index_9": round(idx18 / 2, 1) if idx18 is not None else None,
        "handicap_player_name": handicap_player_name,
        "stats": {
            # F18: rounds-derived count is the truth (all statuses); the
            # race-standings "tournaments" column stays as a floor in case
            # a round import lagged.
            "events_played": max(events_played_rounds, events_played),
            "races_entered": len({(e["contest_type"], e["season"])
                                  for e in enrollments}),
            "total_winnings": total_winnings,
        },
        "scoring": scoring,
        "races": races,
        "race_pots": race_pots,
        "fall_buyins": fall,
        "match_play": match_play,
        "lone_star_cup": lsc,
        "recent_payouts": recent_payouts,
        "recent_events": recent_events,
        "member_card": member_card,
        "gg_error": "; ".join(dict.fromkeys(errors)) or None,
    }


# ═══════════════════════════════════════════════════════════════════════
#  SCORING RECORDS (Phase 1) — tracker-owned scorecards + course database
#
#  Design (admin-established 2026-07-04):
#  - scoring_holes -> scoring_rounds is the FACT layer (what was shot,
#    where, which tee, strokes received per hole). Everything else —
#    adjusted gross (WHS net double bogey is PER-PLAYER: par + 2 + strokes
#    received), stableford points (model-dependent), differentials — is
#    DERIVED, computed on read through admin-controllable formula settings
#    so TGF can customize or toggle to USGA standards later.
#  - handicap_rounds is the legacy derived layer; scoring_round_id bridges
#    it until differential parity is proven, then it collapses to a view.
#  - courses/course_tees/course_tee_holes accrete passively from every
#    scorecard import: own-the-data, GG is an input never the record.
#  - gg_raw_archive keeps gzipped source responses so anything can be
#    re-parsed even if GG severs access.
# ═══════════════════════════════════════════════════════════════════════

def _ensure_scoring_tables(conn: sqlite3.Connection) -> None:
    # NB: courses / course_aliases / events.course_id already exist as the
    # canonical course registry (Events tab datalist reads it) — the scoring
    # layer ENRICHES that table with tees, never duplicates it.
    conn.execute("""CREATE TABLE IF NOT EXISTS course_tees (
        tee_id        INTEGER PRIMARY KEY AUTOINCREMENT,
        course_id     INTEGER NOT NULL REFERENCES courses(course_id),
        tee_name      TEXT,
        slope         INTEGER,
        rating        REAL,
        yardage_total INTEGER,
        created_at    TEXT DEFAULT (datetime('now')),
        UNIQUE(course_id, tee_name, slope, rating))""")
    conn.execute("""CREATE TABLE IF NOT EXISTS course_tee_holes (
        tee_id       INTEGER NOT NULL REFERENCES course_tees(tee_id),
        hole_number  INTEGER NOT NULL,
        par          INTEGER,
        yardage      INTEGER,
        stroke_index INTEGER,
        PRIMARY KEY (tee_id, hole_number))""")
    conn.execute("""CREATE TABLE IF NOT EXISTS scoring_rounds (
        id               INTEGER PRIMARY KEY AUTOINCREMENT,
        customer_id      INTEGER REFERENCES customers(customer_id),
        player_name      TEXT NOT NULL,
        event_id         INTEGER REFERENCES events(id),
        gg_event_id      TEXT,
        gg_round_id      TEXT,
        gg_aggregate_id  TEXT,
        gg_profile_id    TEXT,
        round_date       TEXT,
        course_id        INTEGER REFERENCES courses(course_id),
        tee_id           INTEGER REFERENCES course_tees(tee_id),
        holes_played     INTEGER,
        playing_handicap REAL,
        gross            REAL,
        net              REAL,
        flight           TEXT,
        source           TEXT DEFAULT 'gg',
        imported_at      TEXT DEFAULT (datetime('now')),
        UNIQUE(gg_aggregate_id, player_name))""")
    conn.execute("""CREATE TABLE IF NOT EXISTS scoring_holes (
        id               INTEGER PRIMARY KEY AUTOINCREMENT,
        scoring_round_id INTEGER NOT NULL REFERENCES scoring_rounds(id),
        hole_number      INTEGER NOT NULL,
        strokes          INTEGER,
        strokes_received INTEGER DEFAULT 0,
        gg_result        TEXT,
        UNIQUE(scoring_round_id, hole_number))""")
    conn.execute("""CREATE TABLE IF NOT EXISTS gg_raw_archive (
        id         INTEGER PRIMARY KEY AUTOINCREMENT,
        url        TEXT NOT NULL,
        fetched_at TEXT DEFAULT (datetime('now')),
        body_gz    BLOB)""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_scoring_rounds_cid ON scoring_rounds(customer_id)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_scoring_rounds_event ON scoring_rounds(event_id)")
    try:
        conn.execute("ALTER TABLE handicap_rounds ADD COLUMN scoring_round_id "
                     "INTEGER REFERENCES scoring_rounds(id)")
    except sqlite3.OperationalError:
        pass
    # Persisted played side (Kerry 2026-07-19): 'front' | 'back' | NULL. The
    # nine a 9-hole handicap posting represents is RECORDED here at import
    # time (from the scorecard: holes 1-9 = front, 10-18 = back) instead of
    # being re-derived live on every page load — a round with no clean card
    # bridge otherwise shows a blank side. NULL for named-nine courses
    # (Comanche/Hyatt), whose nine is carried in course_name.
    try:
        conn.execute("ALTER TABLE handicap_rounds ADD COLUMN nine TEXT")
    except sqlite3.OperationalError:
        pass
    # Multi-round days (Hill Country Matches: six GG rounds all dated the
    # same Saturday): the cross-tournament dedupe scopes to the GG league
    # round when the importer passes one — NULL for ordinary one-round
    # events keeps prior behavior.
    try:
        conn.execute("ALTER TABLE scoring_rounds ADD COLUMN gg_league_round_id TEXT")
    except sqlite3.OperationalError:
        pass
    # Member portal: bumping a customer's token version revokes every
    # outstanding magic link for them.
    try:
        conn.execute("ALTER TABLE customers ADD COLUMN portal_token_version "
                     "INTEGER NOT NULL DEFAULT 1")
    except sqlite3.OperationalError:
        pass
    # STARTING (placeholder) handicap — Kerry 2026-07-30. A guest or first
    # timer has no TGF rounds, so no index, so they cannot be flighted and
    # show "—" on every roster. A manager can stamp a starting handicap that
    # stands in until real rounds establish the player's own index.
    #
    # Scale is in the COLUMN NAME on purpose: TGF quotes 18-hole handicaps
    # (= 2 x the 9-hole index) and the roster displays them, but the
    # canonical stored index is the 9-hole one. Naming the scale is the
    # cheapest possible guard against the factor-of-two class of error.
    #
    # This is NEVER a handicap round: it creates no differential, it never
    # feeds compute_handicap_index, and a real computed index always wins
    # over it. It is a display/flighting stand-in with an audit stamp.
    for col, ddl in (
            ("starting_handicap_18", "REAL"),
            ("starting_handicap_set_at", "TEXT"),
            ("starting_handicap_set_by", "TEXT"),
            ("starting_handicap_note", "TEXT"),
            # WHO BROUGHT THIS PLAYER (Kerry 2026-07-30). A guest assigned
            # off a member's purchase was referred by that member, and the
            # buyer is already known at that moment — so derive it, never
            # ask (Principle 1). Stored as the referrer's customer_id per
            # Principle 6; the display name resolves on read.
            #
            # NOT a referral FEE. Fees live in referral_fees and, per the
            # ratified rules, arise only from a redeemed coupon (comped) or
            # a payout receipt (paid). Recording a relationship must never
            # mint a liability.
            ("referred_by_customer_id",
             "INTEGER REFERENCES customers(customer_id)"),
            ("referred_at", "TEXT")):
        try:
            conn.execute(f"ALTER TABLE customers ADD COLUMN {col} {ddl}")
        except sqlite3.OperationalError:
            pass


# Admin-controllable scoring formulas (defaults = current TGF models; the
# stableford tables mirror the matrices on the Contests page). Stored
# overrides live in handicap_settings under these keys as JSON.
_SCORING_FORMULA_DEFAULTS: dict = {
    # Points by (net- or gross-)vs-par per hole (admin-ratified 2026-07-06).
    # NET table (keyed by net-vs-par): triple-eagle-or-better 4, double
    # eagle 4, eagle 3, birdie 2, par 1, bogey 0, double/triple bogey -1.
    "stableford_net_table": {"-4": 4, "-3": 4, "-2": 3, "-1": 2, "0": 1,
                             "1": 0, "2": -1, "3": -1},
    # GROSS table (keyed by gross-vs-par): double-eagle-or-better 16,
    # eagle 8, birdie 4, par 2, bogey 1, double bogey 0, triple -1
    # (doubling ladder up the birdie/eagle/albatross line).
    "stableford_gross_table": {"-4": 16, "-3": 16, "-2": 8, "-1": 4,
                               "0": 2, "1": 1, "2": 0, "3": -1},
    # RAW HOLE-IN-ONE bonus (admin, 2026-07-06): an actual ace (gross
    # strokes == 1) is ALSO a hole result (an eagle on a par 3, a double
    # eagle on a par 4...), so it awards the HIGHER of this HIO bonus and
    # the vs-par table value — never both. So a par-3 ace = 8 (eagle =
    # HIO), a par-4 ace = 16 gross (double eagle beats the HIO bonus). A
    # "net hole-in-one" (net 1 reached via handicap strokes, gross > 1)
    # is NOT a raw ace and is scored by the tables above. Championship:
    # net gets +1 on EVERY category incl. this bonus (->9); gross keeps
    # its vs-par table and only the HIO bonus goes +1 (->9). See
    # get_championship_formulas(). null disables the bonus.
    "stableford_net_hio": 8,
    "stableford_gross_hio": 8,
    # 'whs_net_double_bogey' (par + 2 + strokes received, per WHS) | 'none'
    "adjusted_gross_method": "whs_net_double_bogey",
}


def get_scoring_formulas(db_path: str | Path | None = None) -> dict:
    cfg = dict(_SCORING_FORMULA_DEFAULTS)
    try:
        stored = get_handicap_settings(db_path)
        for key in _SCORING_FORMULA_DEFAULTS:
            if stored.get(key):
                val = stored[key]
                cfg[key] = json.loads(val) if isinstance(val, str) and val.strip().startswith("{") else val
    except Exception:
        pass
    return cfg


def get_championship_formulas(base: dict | None = None,
                              db_path: str | Path | None = None) -> dict:
    """City/TGF Championship schedule (admin-ratified 2026-07-06). NET
    gets +1 on EVERY category (incl. the raw-HIO bonus). GROSS keeps its
    regular vs-par table and only the raw-HIO bonus goes +1. The
    live-standings engine passes this for championship events; regular
    events use get_scoring_formulas()."""
    f = dict(base if base is not None else get_scoring_formulas(db_path))
    f["stableford_net_table"] = {k: v + 1 for k, v in f["stableford_net_table"].items()}
    if f.get("stableford_net_hio") is not None:
        f["stableford_net_hio"] = f["stableford_net_hio"] + 1
    if f.get("stableford_gross_hio") is not None:
        f["stableford_gross_hio"] = f["stableford_gross_hio"] + 1
    # GROSS vs-par table intentionally unchanged for championships.
    return f


def compute_hole_derivations(par: int | None, strokes: int | None,
                             strokes_received: int, formulas: dict) -> dict:
    """Derived per-hole values — never stored, always computed through the
    formula settings so the admin can retune without touching facts."""
    out = {"vs_par": None, "net_vs_par": None, "adjusted_strokes": strokes,
           "stableford_net": None, "stableford_gross": None}
    if par is None or strokes is None:
        return out
    out["vs_par"] = strokes - par
    net = strokes - (strokes_received or 0)
    out["net_vs_par"] = net - par
    if formulas.get("adjusted_gross_method") == "whs_net_double_bogey":
        out["adjusted_strokes"] = min(strokes, par + 2 + (strokes_received or 0))
    def _tbl(table, diff):
        keys = sorted(int(k) for k in table)
        d = max(keys[0], min(keys[-1], diff))
        return table.get(str(d), 0)
    net_tbl = _tbl(formulas["stableford_net_table"], out["net_vs_par"])
    gross_tbl = _tbl(formulas["stableford_gross_table"], out["vs_par"])
    # Raw hole-in-one (gross strokes == 1): an ace IS a hole result, so
    # award the HIGHER of the HIO bonus and the vs-par value, never both
    # (admin, 2026-07-06) — par-3 ace = 8 (= eagle), par-4 ace = 16
    # (double eagle beats HIO). A "net hole-in-one" (net 1 via handicap
    # strokes, gross > 1) is NOT a raw ace.
    if strokes == 1:
        net_hio = formulas.get("stableford_net_hio")
        gross_hio = formulas.get("stableford_gross_hio")
        out["stableford_net"] = max(net_tbl, net_hio) if net_hio is not None else net_tbl
        out["stableford_gross"] = max(gross_tbl, gross_hio) if gross_hio is not None else gross_tbl
    else:
        out["stableford_net"] = net_tbl
        out["stableford_gross"] = gross_tbl
    return out


def _upsert_course_tee(conn: sqlite3.Connection, tee: dict) -> tuple:
    """Course DB accretes passively from tee blocks. Returns (course_id, tee_id)."""
    course_name = (tee.get("course") or "").strip()
    if not course_name:
        return None, None
    row = conn.execute("SELECT course_id FROM courses WHERE LOWER(name) = LOWER(?)",
                       (course_name,)).fetchone()
    if not row:
        row = conn.execute(
            """SELECT course_id FROM course_aliases
               WHERE LOWER(alias_name) = LOWER(?)""", (course_name,)).fetchone()
    if row:
        course_id = row["course_id"]
    else:
        course_id = conn.execute("INSERT INTO courses (name) VALUES (?)",
                                 (course_name,)).lastrowid
    yd = tee.get("yardage") or {}
    conn.execute(
        """INSERT OR IGNORE INTO course_tees (course_id, tee_name, slope, rating, yardage_total)
           VALUES (?, ?, ?, ?, ?)""",
        (course_id, tee.get("tee_name"), tee.get("slope"), tee.get("rating"),
         sum(v for v in yd.values() if v) or None))
    tee_id = conn.execute(
        """SELECT tee_id FROM course_tees WHERE course_id = ? AND tee_name IS ?
           AND slope IS ? AND rating IS ?""",
        (course_id, tee.get("tee_name"), tee.get("slope"), tee.get("rating")),
    ).fetchone()["tee_id"]
    par, si = tee.get("par") or {}, tee.get("stroke_index") or {}
    for hole in sorted(set(list(yd) + list(par) + list(si))):
        conn.execute(
            """INSERT OR REPLACE INTO course_tee_holes
                   (tee_id, hole_number, par, yardage, stroke_index)
               VALUES (?, ?, ?, ?, ?)""",
            (tee_id, hole, par.get(hole), yd.get(hole), si.get(hole)))
    return course_id, tee_id


def _resolve_scoring_player(conn: sqlite3.Connection, gg_name: str) -> int | None:
    """handicap_player_links first (curated GG-name map), then the alias
    machinery — same identity spine as everything else."""
    for cand in _gg_name_candidates(gg_name):
        row = conn.execute(
            """SELECT customer_id FROM handicap_player_links
               WHERE customer_id IS NOT NULL AND LOWER(player_name) = LOWER(?)
               LIMIT 1""", (cand,)).fetchone()
        if row:
            return row["customer_id"]
    for cand in _gg_name_candidates(gg_name):
        cid = _lookup_customer_id(conn, cand, None)
        if cid:
            return cid
    return None


# ── Event MVP / TGF MVP winners (v2.29.0) ──────────────────────────────
# Retroactivity boundary (Kerry, 2026-07-16). Authority hierarchy for
# RESULTS: (1) actual Venmo payouts — IMMUTABLE, nothing already paid ever
# changes; (2) GG results — bible for every event BEFORE a9.18/s9.18; (3) our
# self-computed determination — authoritative from a9.18 Forest Creek /
# s9.18 Cedar Creek (2026-07-14) FORWARD. a9.18 is the FIRST event the WHS cap
# affects (and is unpaid), so it is on the "ours" side (>= boundary). The
# handicap RECORD layer DOES update retroactively with the cap, but that must
# have altered ZERO results before a9.18 — enforced here by deferring to GG
# on any event with event_date < the boundary.
_MVP_RETRO_BOUNDARY = "2026-07-14"
# GG runs an "<code> MVP $" game (one winner per city per event — ties are
# settled by a tiebreaker and only the actual MVP is paid) and a
# "TGF MVP $" game (can be shared). Winners are the purse>0 rows; when an
# MVP table carries no purse at all we fall back to the outright Pos 1 row.

def _ensure_mvp_tables(conn: sqlite3.Connection) -> None:
    conn.execute("""CREATE TABLE IF NOT EXISTS event_mvps (
        id                INTEGER PRIMARY KEY AUTOINCREMENT,
        event_id          INTEGER REFERENCES events(id),
        event_code        TEXT,
        gg_round_id       TEXT,
        gg_tournament_id  TEXT,
        customer_id       INTEGER REFERENCES customers(customer_id),
        player_name       TEXT NOT NULL,
        kind              TEXT NOT NULL CHECK (kind IN ('mvp','tgf_mvp')),
        chapter           TEXT,
        purse             REAL,
        imported_at       TEXT DEFAULT (datetime('now')),
        UNIQUE (gg_tournament_id, player_name, kind))""")
    # Rounds already walked (incl. rounds with no MVP games) so repeated
    # import calls converge instead of re-fetching the whole season
    conn.execute("""CREATE TABLE IF NOT EXISTS mvp_import_rounds (
        gg_round_id  TEXT NOT NULL,
        host         TEXT NOT NULL,
        imported_at  TEXT DEFAULT (datetime('now')),
        PRIMARY KEY (gg_round_id, host))""")
    # Self-computed City MVP / TGF MVP (Kerry-ratified rule 2026-07-16): the
    # winner is whoever scored the most points in the event's MVP side game
    # (net Stableford among the game's players); ties break Net score then
    # Gross score; a still-tied result splits -> `split=1` (Co-MVP /
    # Co-TGF MVP). This frees the badge from the lagging GG import: we own the
    # determination from our scorecards + formula layer (determine_tgf_mvp).
    conn.execute("""CREATE TABLE IF NOT EXISTS event_mvp_computed (
        event_id     INTEGER NOT NULL REFERENCES events(id),
        customer_id  INTEGER NOT NULL REFERENCES customers(customer_id),
        kind         TEXT NOT NULL CHECK (kind IN ('mvp','tgf_mvp')),
        split        INTEGER NOT NULL DEFAULT 0,
        player_name  TEXT,
        points       REAL,
        computed_at  TEXT DEFAULT (datetime('now')),
        PRIMARY KEY (event_id, customer_id, kind))""")
    # Which events our engine has authoritatively determined (winner or not).
    # Lets the badge treat our computation as the sole authority for a
    # computed event — the GG event_mvps fallback applies ONLY to events we
    # have never computed, never per-player within a computed event.
    conn.execute("""CREATE TABLE IF NOT EXISTS mvp_computed_events (
        event_id     INTEGER PRIMARY KEY REFERENCES events(id),
        computed_at  TEXT DEFAULT (datetime('now')))""")


def _parse_money(v) -> float:
    m = re.search(r"([\d,]+(?:\.\d+)?)", str(v or ""))
    return float(m.group(1).replace(",", "")) if m else 0.0


def _mvp_winners_from_table(table: list, kind: str) -> list:
    """[(player_name, chapter, purse)] winners from a GG MVP results table."""
    if not table or not table[0]:
        return []
    head = [(c or "").strip().lower() for c in table[0]]
    def col(*names):
        for n in names:
            for i, h in enumerate(head):
                if n in h:
                    return i
        return -1
    pos_i, player_i, purse_i = col("pos"), col("player"), col("purse")
    if player_i < 0:
        return []
    rows = []
    for r in table[1:]:
        if len(r) != len(head):
            continue        # blank separators / "Total Purse Allocated"
        raw = (r[player_i] or "").strip()
        if not raw:
            continue
        m = re.search(r"\s+TGF\s+([A-Za-z .'-]+)$", raw)
        chapter = m.group(1).strip() if m else None
        name = raw[:m.start()].strip() if m else raw
        purse = _parse_money(r[purse_i]) if purse_i > -1 else 0.0
        pos = (r[pos_i] or "").strip().lower() if pos_i > -1 else ""
        rows.append((name, chapter, purse, pos))
    winners = [(n, c, p) for n, c, p, _ in rows if p > 0]
    if not winners and kind == "mvp":
        # No purse posted — take the outright leader only (a T1 tie with no
        # purse is unresolved; the tiebreaker note lives in GG comments)
        winners = [(n, c, p) for n, c, p, pos in rows if pos == "1"]
    return winners


def import_gg_event_mvps(widget_url: str, db_path: str | Path = DB_PATH,
                         time_budget: float = 42.0) -> dict:
    """Walk a portal's Event Results rounds and record MVP / TGF MVP winners.

    widget_url: .../leagues/<id>/widgets/tournament_results?shared=false
    (a &round=<id> in the URL restricts the walk to that round). Rounds
    already recorded in mvp_import_rounds are skipped, and the walk stops
    at time_budget seconds — call repeatedly until rounds_left == 0.
    """
    from time import monotonic
    from urllib.parse import urlparse, parse_qs, urlencode, urlunparse
    from golf_genius_sync import fetch_public_page, parse_page_structure

    started = monotonic()
    parts = urlparse(widget_url)
    host = parts.netloc
    qs = parse_qs(parts.query)
    only_round = (qs.pop("round", [None]) or [None])[0]
    base_url = urlunparse(parts._replace(query=urlencode(qs, doseq=True)))

    def fetch(url):
        page = fetch_public_page(url, xhr=False)
        if page["status_code"] != 200:
            raise RuntimeError(f"GG returned HTTP {page['status_code']} for {url}")
        return page["html"]

    # Round inventory from the widget's round selector
    html = fetch(base_url)
    sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>', html, re.S)
    options = re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                         sel.group(1) if sel else "", re.S)
    if only_round:
        options = [(rid, lbl) for rid, lbl in options if rid == only_round] \
            or [(only_round, "")]

    result = {"rounds_done": 0, "rounds_skipped": 0, "winners_recorded": 0,
              "rounds_left": 0, "unresolved_names": [], "notes": []}
    with _connect(db_path) as conn:
        _ensure_mvp_tables(conn)
        done = {r["gg_round_id"] for r in conn.execute(
            "SELECT gg_round_id FROM mvp_import_rounds WHERE host = ?",
            (host,)).fetchall()}
        code_map = {}
        for r in conn.execute("SELECT id, item_name FROM events").fetchall():
            m = _GG_EVENT_CODE_COMPOUND_RE.match((r["item_name"] or "").strip())
            if m:
                code_map.setdefault(m.group(1).lower(), (r["id"], r["item_name"]))

        pending = [(rid, lbl) for rid, lbl in options if rid not in done]
        for rid, _lbl in pending:
            if monotonic() - started > time_budget:
                break
            round_url = f"{base_url}&round={rid}"
            struct = parse_page_structure(fetch(round_url), round_url)
            links = struct.get("links") or []
            names_blob = " ".join(l.get("text") or "" for l in links)
            # Event linkage: any coded tournament name in the round; the
            # Austin Kickoff round has no code anywhere -> a18.2 by keyword
            ev_id, ev_code = None, None
            m = re.search(r"\b([sa]\d+(?:\.\d+)?)\b", names_blob)
            if m and m.group(1).lower() in code_map:
                ev_code = m.group(1).lower()
                ev_id = code_map[ev_code][0]
            elif "kickoff" in names_blob.lower() and "austin" in host:
                ev_code = "a18.2"
                ev_id = code_map.get("a18.2", (None,))[0]
            for l in links:
                text = (l.get("text") or "").strip()
                if not re.search(r"\bMVP\b", text, re.I) or "POINTS" in text.upper():
                    continue
                kind = "tgf_mvp" if re.search(r"\bTGF\s+MVP\b", text, re.I) else "mvp"
                href = l.get("href") or ""
                tid_m = re.search(r"/v2tournaments/(\d+)", href)
                if not tid_m:
                    continue
                if href.startswith("/"):
                    href = f"https://{host}{href}"
                tstruct = parse_page_structure(fetch(href), href)
                for table in tstruct.get("tables") or []:
                    for name, chapter, purse in _mvp_winners_from_table(table, kind):
                        cid = _resolve_scoring_player(conn, name)
                        if cid is None and name not in result["unresolved_names"]:
                            result["unresolved_names"].append(name)
                        conn.execute(
                            """INSERT INTO event_mvps
                                   (event_id, event_code, gg_round_id,
                                    gg_tournament_id, customer_id, player_name,
                                    kind, chapter, purse)
                               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
                               ON CONFLICT (gg_tournament_id, player_name, kind)
                               DO UPDATE SET purse = excluded.purse,
                                             customer_id = COALESCE(excluded.customer_id, event_mvps.customer_id),
                                             event_id = COALESCE(excluded.event_id, event_mvps.event_id)""",
                            (ev_id, ev_code, rid, tid_m.group(1), cid, name,
                             kind, chapter, purse))
                        result["winners_recorded"] += 1
            conn.execute(
                "INSERT OR IGNORE INTO mvp_import_rounds (gg_round_id, host) VALUES (?, ?)",
                (rid, host))
            conn.commit()
            result["rounds_done"] += 1
        result["rounds_skipped"] = len(options) - len(pending)
        result["rounds_left"] = len(pending) - result["rounds_done"]
    return result


# ── TGF MVP determination (v2.33.0) ────────────────────────────────────
# Automates the manual step GG cannot do (admin, 2026-07-05): compare
# the linked same-day events' City MVPs and name the TGF MVP. City MVP
# = highest NET STABLEFORD POINTS among that event's NET-bundle buyers
# (ratified: points, not the best net stroke score); tiebreakers
# 1) Individual Net stroke score, 2) Gross, 3) split. TGF MVP = the
# City MVP with the higher points across the day's linked events; tie
# splits with no further tiebreaker. Same-day linkage mirrors the
# Events Games tab: event_date equality, minus event_mvp_unlinks,
# 9-hole/combo nines only.

def _classify_side_games_type(side_games) -> str:
    s = (side_games or "").upper().strip()
    if not s or s == "NONE":
        return "NO GAMES"
    if s == "BOTH" or ("NET" in s and "GROSS" in s):
        return "BOTH"
    if "NET" in s:
        return "NET"
    if "GROSS" in s:
        return "GROSS"
    return "NO GAMES"


def _event_holes_type(item_name: str, fmt: str) -> int:
    f = (fmt or "").lower()
    if "combo" in f:
        m = re.match(r"^[a-z](\d+)\.", (item_name or "").strip(), re.I)
        return 18 if (m and m.group(1) == "18") else 9
    if "18" in f or "27" in f:
        return 18
    return 9


# 36 and 54 are DELIBERATE multi-day entries — a two- or three-day
# championship package (Kerry 2026-08-07, on the 2026 TGF CHAMPIONSHIP
# roster). `_event_holes_type` can only ever return 9 or 18, so the holes
# heal below would "correct" every 36/54 straight back to 18 on the next
# boot and silently delete the manager's choice. Honoured only on
# 18-style events: on a 9-hole event a 36 IS the sequence-number misread
# this heal exists to fix ("a9.36 Some Course" parsed as holes='36').
_MULTI_DAY_HOLES = {"36", "54"}


def _is_multi_day_holes(current, item_name: str, fmt: str) -> bool:
    return (str(current or "").strip() in _MULTI_DAY_HOLES
            and _event_holes_type(item_name, fmt) == 18)


def _canon_holes_for_item(conn: sqlite3.Connection,
                          item_name: str,
                          current=None) -> str | None:
    """Authoritative holes value ('9'/'18') for an item on a single-format
    EVENT, alias-aware. None when no event matches, when the event is a
    9/18 Combo (holes is the player's choice there), or when the event
    declares no format (pseudo-events like SEASON CONTESTS). Kerry
    2026-07-21: blank holes undercounts the side-games player buckets,
    so event rows must never sit blank waiting for the boot heal.
    Also None when `current` is a multi-day 36/54 on an 18-style event —
    that value outranks the event's per-day count."""
    name = (item_name or "").strip()
    if not name:
        return None
    row = conn.execute(
        """SELECT e.item_name AS ev_name, e.format AS fmt
           FROM events e
           LEFT JOIN event_aliases ea ON ea.canonical_event_name = e.item_name
           WHERE e.item_name = ? COLLATE NOCASE
              OR ea.alias_name = ? COLLATE NOCASE
           LIMIT 1""", (name, name)).fetchone()
    if not row:
        return None
    fmt = (row["fmt"] or "").strip()
    if not fmt or "combo" in fmt.lower():
        return None
    if _is_multi_day_holes(current, row["ev_name"], fmt):
        return None
    return str(_event_holes_type(row["ev_name"], fmt))


def heal_item_holes_from_event(db_path=None, conn=None) -> dict:
    """Force items.holes to the EVENT's hole count on single-format events.

    The AI order parser occasionally mis-reads the hole count — most often
    it grabs the SEQUENCE number out of an event code like "a9.18 Forest
    Creek" (a 9-hole event, #18 of the season) and stores holes='18'
    (Kerry 2026-07-14). The event code prefix is authoritative: "a9.x" = 9
    holes, "s18.x" = 18. This aligns items.holes to `_event_holes_type`
    for every NON-combo event (combo events keep their real per-player 9/18
    choice). Money is never affected — side-game pots derive their matrix
    from the event via _event_holes_type, not from items.holes; this only
    corrects the roster hole badge, the 9|18 filter, and the hole-aware HCP
    column. Idempotent; runs at boot and on demand.
    """
    def _run(c):
        fixed = 0
        examples: list = []
        rows = c.execute("""
            SELECT i.id, i.item_name, i.holes, e.format AS fmt
            FROM items i
            JOIN events e
              ON (e.id = i.event_id
                  OR e.item_name = i.item_name COLLATE NOCASE
                  OR EXISTS (SELECT 1 FROM event_aliases ea
                             WHERE ea.canonical_event_name = e.item_name
                               AND ea.alias_name = i.item_name COLLATE NOCASE))
            WHERE COALESCE(i.transaction_status, 'active') = 'active'
              AND COALESCE(LOWER(e.format), '') NOT LIKE '%combo%'
        """).fetchall()
        seen = set()
        for r in rows:
            if r["id"] in seen:
                continue
            seen.add(r["id"])
            canon = str(_event_holes_type(r["item_name"], r["fmt"]))
            cur = (r["holes"] or "").strip()
            if cur == canon:
                continue
            if _is_multi_day_holes(cur, r["item_name"], r["fmt"]):
                continue
            c.execute("UPDATE items SET holes = ? WHERE id = ?", (canon, r["id"]))
            fixed += 1
            if len(examples) < 25:
                examples.append({"id": r["id"], "event": r["item_name"],
                                 "from": cur or None, "to": canon})
        return {"fixed": fixed, "examples": examples}

    if conn is not None:
        return _run(conn)  # caller owns the transaction/commit
    with _connect(db_path) as c:
        res = _run(c)
        c.commit()
        return res


def _event_game_buyers(conn, event_name: str, kind: str = "NET") -> dict:
    """Bundle buyers for an event (parents with the effective game type
    after merging child add-on payments), alias-aware, using the
    Games-tab eligibility rules: credited/refunded/transferred and
    rsvp_only rows are out; wd rows stay only if the bundle was NOT
    credited back. kind is 'NET' or 'GROSS'. Returns
    {"buyers": {customer_id: name}, "no_customer_id": [names]}."""
    wd_key = "net_games" if kind == "NET" else "gross_games"
    names = [event_name]
    names += [r["alias_name"] for r in conn.execute(
        "SELECT alias_name FROM event_aliases WHERE canonical_event_name = ? COLLATE NOCASE",
        (event_name,)).fetchall() if r["alias_name"]]
    ph = ",".join("?" for _ in names)
    rows = [dict(r) for r in conn.execute(
        f"SELECT id, parent_item_id, customer_id, customer, side_games, "
        f"       COALESCE(transaction_status,'active') AS ts, wd_credits "
        f"FROM items WHERE LOWER(item_name) IN ({ph})",
        [n.lower() for n in names]).fetchall()]
    kids = {}
    for r in rows:
        if r["parent_item_id"]:
            kids.setdefault(str(r["parent_item_id"]), []).append(r)
    buyers, no_cid = {}, []
    for r in rows:
        if r["parent_item_id"]:
            continue
        if r["ts"] in ("credited", "refunded", "transferred", "rsvp_only"):
            continue
        t = _classify_side_games_type(r["side_games"])
        has_kind = t in (kind, "BOTH")
        for c in kids.get(str(r["id"]), []):
            ct = _classify_side_games_type(c["side_games"])
            if ct in (kind, "BOTH"):
                has_kind = True
        if r["ts"] == "wd":
            try:
                wd = json.loads(r["wd_credits"] or "{}")
            except (TypeError, ValueError):
                wd = {}
            if wd_key in wd:
                has_kind = False
        if not has_kind:
            continue
        if r["customer_id"]:
            buyers[int(r["customer_id"])] = r["customer"] or ""
        else:
            no_cid.append(r["customer"] or "(unnamed)")
    return {"buyers": buyers, "no_customer_id": no_cid}


def _event_net_buyers(conn, event_name: str) -> dict:
    """Back-compat wrapper — NET-bundle buyers (see _event_game_buyers)."""
    return _event_game_buyers(conn, event_name, "NET")


def determine_tgf_mvp(event_name: str, db_path: str | Path = DB_PATH) -> dict:
    """Compute City MVP for each linked same-day event from OUR imported
    scorecards + the formula layer, then determine the TGF MVP."""
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        _ensure_mvp_tables(conn)
        ev = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        ev = dict(ev)
        try:
            unlinked = {u.lower() for u in get_mvp_unlinked_events(db_path=db_path)}
        except sqlite3.OperationalError:
            unlinked = set()  # table is created by init_db; absent on fresh DBs
        # SAME FORMAT ONLY (Kerry 2026-07-31: "No mixed format TGF MVPs it's
        # either nine or 18"). This used to drop every 18-hole event from the
        # day pool outright, so two 18-hole events on one day could not share
        # a TGF MVP at all; the day now pools by the anchor event's format, so
        # a 9-hole and an 18-hole event on the same date are two separate
        # contests rather than one combined or one suppressed.
        ev_holes = _event_holes_type(ev["item_name"], ev.get("format"))
        day = []
        if ev["event_date"]:
            for r in conn.execute(
                    "SELECT * FROM events WHERE event_date = ? ORDER BY item_name",
                    (ev["event_date"],)).fetchall():
                r = dict(r)
                if r["item_name"].lower() in unlinked:
                    continue
                if _event_holes_type(r["item_name"], r.get("format")) != ev_holes:
                    continue
                day.append(r)
        if not any(d["item_name"].lower() == ev["item_name"].lower() for d in day):
            day.insert(0, ev)  # this event even if unlinked — still gets City MVP

        # per-player rounds for the whole day, keyed (event_id, customer_id)
        event_ids = [d["id"] for d in day]
        ph = ",".join("?" for _ in event_ids)
        round_map = {}
        for r in conn.execute(
                f"SELECT id, event_id, customer_id, player_name, gross, net, "
                f"       playing_handicap, holes_played FROM scoring_rounds "
                f"WHERE event_id IN ({ph}) AND customer_id IS NOT NULL "
                f"ORDER BY id", event_ids).fetchall():
            round_map[(r["event_id"], r["customer_id"])] = dict(r)  # latest wins

        buyers_by_event = {d["item_name"]: _event_net_buyers(conn, d["item_name"])
                           for d in day}

    def _round_points(rd: dict) -> dict:
        card = get_scorecard(rd["id"], db_path=db_path)
        pts = card["derived_totals"]["stableford_net"] if card else None
        gross = rd["gross"]
        if gross is None and card:
            gross = sum(h["strokes"] for h in card["holes"]
                        if h["strokes"] is not None)
        net = rd["net"]
        if net is None and gross is not None and rd["playing_handicap"] is not None:
            net = gross - rd["playing_handicap"]
        return {"points": pts, "net": net, "gross": gross}

    per_event, all_city_mvps = [], []
    for d in day:
        binfo = buyers_by_event[d["item_name"]]
        entrants = []
        for cid, name in binfo["buyers"].items():
            rd = round_map.get((d["id"], cid))
            if not rd:
                continue
            sc = _round_points(rd)
            if sc["points"] is None:
                continue
            entrants.append({"customer_id": cid,
                             "player": rd["player_name"] or name,
                             "holes_played": rd.get("holes_played"), **sc})
        entry = {"event_name": d["item_name"], "course": d.get("course"),
                 "net_buyers": len(binfo["buyers"]),
                 "buyers_without_customer_id": binfo["no_customer_id"],
                 "rounds_matched": len(entrants)}
        if not binfo["buyers"]:
            entry["city_mvp"] = {"status": "no_net_buyers", "winners": []}
        elif not entrants:
            entry["city_mvp"] = {"status": "awaiting_results", "winners": []}
        else:
            entrants.sort(key=lambda e: (
                -e["points"],
                e["net"] if e["net"] is not None else float("inf"),
                e["gross"] if e["gross"] is not None else float("inf")))
            top = entrants[0]
            # Incomplete-card guard (Kerry's s9.20 catch, 2026-07-28): a
            # mid-live-scoring import left ANTHIS with 8 of 9 holes, so his
            # Stableford summed one hole short and KULAWIK was crowned City
            # MVP without the tie ever firing. A card that isn't a full 9
            # or 18 makes the result provisional whenever its player could
            # still catch the leader (max 9 pts/hole — adjusted-scale ace).
            _MAX_PTS_PER_HOLE = 9
            unsettled = []
            for e in entrants:
                hp = e.get("holes_played") or 0
                expected = 18 if hp > 9 else 9
                missing = expected - hp
                if missing > 0 and (top["points"] - e["points"]
                                    <= missing * _MAX_PTS_PER_HOLE):
                    unsettled.append({"player": e["player"],
                                      "holes_played": hp,
                                      "points_so_far": e["points"]})
            if unsettled:
                entry["city_mvp"] = {
                    "status": "incomplete_cards", "winners": [],
                    "incomplete": unsettled,
                    "note": "cards missing holes could still change the "
                            "winner — re-import the event and recompute"}
            else:
                winners = [e for e in entrants if
                           e["points"] == top["points"] and e["net"] == top["net"]
                           and e["gross"] == top["gross"]]
                entry["city_mvp"] = {"status": "determined", "winners": winners,
                                     "split": len(winners) > 1,
                                     "field": entrants[:5]}
                for w in winners:
                    all_city_mvps.append({**w, "event_name": d["item_name"]})
        with _connect(db_path) as conn2:
            entry["gg_recorded_mvp"] = [
                r["player_name"] for r in conn2.execute(
                    "SELECT player_name FROM event_mvps WHERE event_id = ? "
                    "AND kind = 'mvp'", (d["id"],)).fetchall()]
        per_event.append(entry)

    out = {"event": ev["item_name"], "event_date": ev["event_date"],
           "linked_events": [d["item_name"] for d in day],
           "per_event": per_event}
    if len(day) < 2:
        out["tgf_mvp"] = {"status": "single_event_day",
                          "note": "all MVP money to City MVP — no TGF MVP"}
        return out
    waiting = [e["event_name"] for e in per_event
               if e["city_mvp"]["status"] in ("awaiting_results",
                                              "incomplete_cards")]
    if waiting:
        out["tgf_mvp"] = {"status": "awaiting_results", "waiting_on": waiting}
        return out
    if not all_city_mvps:
        out["tgf_mvp"] = {"status": "no_city_mvps"}
        return out
    # TGF MVP is a CROSS-CHAPTER honor (Kerry ruling B, 2026-07-16): it only
    # exists when two or more chapters actually FIELDED the game that day. If
    # only one event produced a determined City MVP (the other chapter had no
    # players / rained out), there is no TGF MVP — the lone City MVP is not
    # elevated. This matches GG, which never ran the TGF MVP game on a
    # single-chapter day.
    mvp_event_names = {w["event_name"] for w in all_city_mvps}
    if len(mvp_event_names) < 2:
        out["tgf_mvp"] = {"status": "single_event_day",
                          "note": "only one chapter fielded the game — no TGF MVP"}
        return out
    # day points per City MVP = their net Stableford summed across the
    # day's linked events (usually just their own nine)
    for w in all_city_mvps:
        total = 0
        for d in day:
            rd = round_map.get((d["id"], w["customer_id"]))
            if rd:
                sc = _round_points(rd)
                if sc["points"] is not None:
                    total += sc["points"]
        w["day_points"] = total
    best = max(w["day_points"] for w in all_city_mvps)
    winners = [w for w in all_city_mvps if w["day_points"] == best]
    out["tgf_mvp"] = {"status": "determined", "split": len(winners) > 1,
                      "winners": [{"player": w["player"],
                                   "customer_id": w["customer_id"],
                                   "event_name": w["event_name"],
                                   "day_points": w["day_points"]}
                                  for w in winners]}
    return out


def recompute_computed_mvps(scope_event: str | None = None,
                            db_path: str | Path = DB_PATH) -> dict:
    """Materialize the self-computed City MVP / TGF MVP into
    ``event_mvp_computed`` so the scorecard badges read our own
    determination (``determine_tgf_mvp``) instead of the lagging GG import.

    Kerry-ratified rule (2026-07-16): MVP = most points in the event's MVP
    side game; ties break Net score then Gross score; a still-tied result
    splits (``split=1`` -> Co-MVP / Co-TGF MVP). ``scope_event`` recomputes
    just that event's same-day group; ``None`` recomputes every date that
    has linked scorecards. Idempotent: a day's rows are cleared and rewritten
    each run, so a corrected/late score reshuffles the badges cleanly."""
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        _ensure_mvp_tables(conn)
        name_to_id = {r["item_name"].lower(): r["id"]
                      for r in conn.execute(
                          "SELECT id, item_name FROM events").fetchall()}
        # Targets = every event that has scorecards (scoped to one day when
        # scope_event is given). We iterate EVENTS, not dates, so two 18-hole
        # events sharing a date each get their own determination (an 18h event
        # is its own day-group — determine_tgf_mvp excludes other 18h events).
        if scope_event:
            row = conn.execute(
                "SELECT event_date FROM events WHERE item_name = ? COLLATE NOCASE",
                (scope_event,)).fetchone()
            date = row["event_date"] if row else None
            if not date:
                return {"days": 0, "mvp_rows": 0, "tgf_mvp_rows": 0,
                        "events_computed": 0, "scope": scope_event}
            targets = [r["name"] for r in conn.execute(
                """SELECT DISTINCT e.item_name AS name
                     FROM scoring_rounds sr JOIN events e ON e.id = sr.event_id
                    WHERE e.event_date = ?""", (date,)).fetchall()]
            clear_ids = [r["id"] for r in conn.execute(
                "SELECT id FROM events WHERE event_date = ?", (date,)).fetchall()]
        else:
            targets = [r["name"] for r in conn.execute(
                """SELECT DISTINCT e.item_name AS name
                     FROM scoring_rounds sr JOIN events e ON e.id = sr.event_id
                    WHERE e.event_date IS NOT NULL""").fetchall()]
            clear_ids = None  # whole-table clear below

        # Clear up-front (once) so per-event inserts never wipe a sibling's
        # freshly-written rows mid-loop.
        if clear_ids is not None:
            ph = ",".join("?" for _ in clear_ids) or "NULL"
            conn.execute(f"DELETE FROM event_mvp_computed WHERE event_id IN ({ph})",
                         clear_ids)
            conn.execute(f"DELETE FROM mvp_computed_events WHERE event_id IN ({ph})",
                         clear_ids)
        else:
            conn.execute("DELETE FROM event_mvp_computed")
            conn.execute("DELETE FROM mvp_computed_events")
        conn.commit()

    processed: set[int] = set()
    mvp_rows = tgf_rows = 0
    for tname in targets:
        tid = name_to_id.get(tname.lower())
        if tid in processed:
            continue
        det = determine_tgf_mvp(tname, db_path=db_path)
        if det.get("error"):
            continue
        linked_ids = [name_to_id[n.lower()] for n in det.get("linked_events", [])
                      if n.lower() in name_to_id]
        with _connect(db_path) as conn:
            for lid in (linked_ids or [tid]):
                if lid:
                    conn.execute(
                        "INSERT OR REPLACE INTO mvp_computed_events (event_id) VALUES (?)",
                        (lid,))
            for pe in det.get("per_event", []):
                cm = pe.get("city_mvp") or {}
                if cm.get("status") != "determined":
                    continue
                eid = name_to_id.get((pe.get("event_name") or "").lower())
                if not eid:
                    continue
                split = 1 if cm.get("split") else 0
                for w in cm.get("winners", []):
                    if not w.get("customer_id"):
                        continue
                    conn.execute(
                        """INSERT OR REPLACE INTO event_mvp_computed
                               (event_id, customer_id, kind, split, player_name, points)
                           VALUES (?, ?, 'mvp', ?, ?, ?)""",
                        (eid, w["customer_id"], split, w.get("player"),
                         w.get("points")))
                    mvp_rows += 1
            tm = det.get("tgf_mvp") or {}
            if tm.get("status") == "determined":
                tsplit = 1 if tm.get("split") else 0
                for w in tm.get("winners", []):
                    eid = name_to_id.get((w.get("event_name") or "").lower())
                    if not eid or not w.get("customer_id"):
                        continue
                    conn.execute(
                        """INSERT OR REPLACE INTO event_mvp_computed
                               (event_id, customer_id, kind, split, player_name, points)
                           VALUES (?, ?, 'tgf_mvp', ?, ?, ?)""",
                        (eid, w["customer_id"], tsplit, w.get("player"),
                         w.get("day_points")))
                    tgf_rows += 1
            conn.commit()
        processed.update(l for l in (linked_ids or [tid]) if l)
    return {"days": len(processed), "mvp_rows": mvp_rows, "tgf_mvp_rows": tgf_rows,
            "events_computed": len(processed), "scope": scope_event or "all"}


def _norm_player(name: str) -> str:
    """Normalize a player name for cross-source comparison. GG names are
    'LAST, First'; strip a trailing ' TGF <chapter>' tag, uppercase, collapse
    whitespace so 'YOUNG, Jeff' == 'young,  jeff'."""
    s = re.sub(r"\s+TGF\s+[A-Za-z .'-]+$", "", (name or "").strip())
    return re.sub(r"\s+", " ", s).strip().upper()


def audit_pre_boundary_mvp(before_date: str = "2026-07-14",
                           db_path: str | Path = DB_PATH) -> dict:
    """RESULTS-HARDENING (H-1, Kerry): for every event BEFORE the retroactivity
    boundary, compare OUR self-computed City MVP (net-points winner, our
    handicaps) against GG's RECORDED MVP (event_mvps, purse winners). This is
    the top of the net-points ranking — the first place a cap-driven points
    change surfaces. Read-only; changes nothing. Returns the full mismatch
    list so pre-boundary divergences can be resolved (GG stays bible)."""
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        _ensure_mvp_tables(conn)
        events = [dict(r) for r in conn.execute(
            """SELECT DISTINCT e.id, e.item_name, e.event_date
                 FROM scoring_rounds sr JOIN events e ON e.id = sr.event_id
                WHERE e.event_date IS NOT NULL AND e.event_date < ?
                ORDER BY e.event_date, e.item_name""", (before_date,)).fetchall()]

    checked, matches, mismatches, skipped = 0, 0, [], []
    for ev in events:
        det = determine_tgf_mvp(ev["item_name"], db_path=db_path)
        if det.get("error"):
            skipped.append({"event": ev["item_name"], "reason": det["error"]})
            continue
        pe = next((p for p in det.get("per_event", [])
                   if (p.get("event_name") or "").lower() == ev["item_name"].lower()),
                  None)
        if not pe:
            continue
        cm = pe.get("city_mvp") or {}
        gg = {_norm_player(n) for n in (pe.get("gg_recorded_mvp") or [])}
        if cm.get("status") != "determined":
            # We can't compute a winner (no net buyers / awaiting) — only a
            # gap if GG DID record one.
            if gg:
                mismatches.append({
                    "event": ev["item_name"], "date": ev["event_date"],
                    "kind": "we_have_no_winner",
                    "our_mvp": [], "gg_mvp": sorted(gg),
                    "our_status": cm.get("status")})
            continue
        ours = {_norm_player(w.get("player")) for w in cm.get("winners", [])}
        checked += 1
        if not gg:
            # GG never recorded this one (import lag) — cannot verify against
            # GG; note it but don't call it a mismatch.
            skipped.append({"event": ev["item_name"], "date": ev["event_date"],
                            "reason": "no GG MVP on record to compare",
                            "our_mvp": sorted(ours)})
            continue
        if ours == gg:
            matches += 1
        else:
            mismatches.append({
                "event": ev["item_name"], "date": ev["event_date"],
                "kind": "winner_set_differs",
                "our_mvp": sorted(ours), "gg_mvp": sorted(gg),
                "our_split": cm.get("split"),
                "field": [{"p": w.get("player"), "pts": w.get("points"),
                           "net": w.get("net"), "gross": w.get("gross")}
                          for w in (cm.get("field") or [])[:5]]})
    return {"before_date": before_date, "events_with_scores": len(events),
            "compared_vs_gg": checked, "matches": matches,
            "mismatch_count": len(mismatches), "mismatches": mismatches,
            "uncomparable": skipped}


# ── Event game results (v2.35.0; flight rule per Kerry 2026-07-07) ─────
# Shadow-computes the scorecard-derivable side-game winners for one
# event from OUR imported scorecards + formula layer, mirroring
# determine_tgf_mvp: Individual Net (stroke, flighted), Individual
# Gross (raw gross, flighted), and gross Skins (outright low gross per
# hole within flight). Buyer eligibility mirrors the Games tab via
# _event_game_buyers. FLIGHTS COME FROM GG ONLY (Kerry ruling): the
# cut lines are configured per game in GG, so we group by the imported
# scoring_rounds.flight labels and never derive flights from handicap.
# Multi-flight games whose scored entrants lack labels report
# status='flights_unknown' — importing the game's own GG leaderboard
# (e.g. "INDIVIDUAL Net $"), not just ALL Net/ALL Gross, is what
# carries the labels. Display-only (GG stays official — Stage 1
# shadow discipline); the Games tab hydrates 🏆 rows from
# /api/events/game-results. CTP / Longest Putt / Hole-in-One and TEAM
# Net winners are GG-RECORDED truth pulled by import_gg_game_results
# (below) — GG cannot compute them from scorecards and neither can we.

_GAME_RESULT_KINDS = {"individual_net": "NET", "individual_gross": "GROSS",
                      "skins": "GROSS"}


def _rank_with_ties(entrants: list[dict], key: str) -> list[dict]:
    """Rank ascending on `key` (stroke play: lower is better) with
    golf-style tied positions (1, 2, 2, 4). Entrants with a NULL key
    are excluded by the caller."""
    ordered = sorted(entrants, key=lambda e: (e[key], e["player"]))
    out, pos = [], 0
    for i, e in enumerate(ordered):
        if i and e[key] == ordered[i - 1][key]:
            rank = out[-1]["position"]
        else:
            rank = i + 1
        row = dict(e)
        row["position"] = rank
        out.append(row)
    for row in out:
        row["tied"] = sum(1 for r in out if r["position"] == row["position"]) > 1
    return out


def determine_event_game_results(event_name: str, game: str,
                                 flights: int = 1,
                                 db_path: str | Path = DB_PATH) -> dict:
    """Compute one side game's results for an event from imported
    scorecards. game ∈ individual_net | individual_gross | skins.
    `flights` comes from the prize matrix (the caller/Games tab knows
    the matrix row for this buyer count)."""
    if game not in _GAME_RESULT_KINDS:
        return {"error": f"unknown game '{game}'"}
    kind = _GAME_RESULT_KINDS[game]
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        ev = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        ev = dict(ev)
        binfo = _event_game_buyers(conn, ev["item_name"], kind)
        out = {"event_name": ev["item_name"], "game": game, "kind": kind,
               "buyers": len(binfo["buyers"]),
               "buyers_without_customer_id": binfo["no_customer_id"]}
        if not binfo["buyers"]:
            out["status"] = "no_buyers"
            return out

        # One merged round per buyer for this event. A buyer can have
        # SEVERAL scoring_rounds rows for the same physical round — one
        # per imported GG board (the ALL Net row carries net +
        # playing_handicap; the ALL Gross row has them NULL). Last-row-
        # wins used to pick whichever board imported last and reported
        # awaiting_results on a fully-scored event (the 2026-08-01
        # championships), so later rows now only fill fields the merged
        # row is still missing — never overwrite a value with NULL.
        rounds = {}
        for r in conn.execute(
                "SELECT id, customer_id, player_name, gross, net, "
                "       playing_handicap, flight FROM scoring_rounds "
                "WHERE event_id = ? AND customer_id IS NOT NULL ORDER BY id",
                (ev["id"],)).fetchall():
            if r["customer_id"] not in binfo["buyers"]:
                continue
            cur = rounds.get(r["customer_id"])
            if cur is None:
                rounds[r["customer_id"]] = dict(r)
                continue
            for k in ("gross", "net", "playing_handicap", "flight"):
                if cur[k] is None and r[k] is not None:
                    cur[k] = r[k]
        if not rounds:
            out["status"] = "awaiting_results"
            return out

        entrants = []
        for cid, rd in rounds.items():
            gross = rd["gross"]
            if gross is None:
                gross = conn.execute(
                    "SELECT SUM(strokes) FROM scoring_holes "
                    "WHERE scoring_round_id = ? AND strokes IS NOT NULL",
                    (rd["id"],)).fetchone()[0]
            net = rd["net"]
            if net is None and gross is not None and rd["playing_handicap"] is not None:
                net = gross - rd["playing_handicap"]
            entrants.append({
                "customer_id": cid,
                "player": rd["player_name"] or binfo["buyers"][cid],
                "round_id": rd["id"],
                "gross": gross, "net": net,
                "playing_handicap": rd["playing_handicap"],
                "gg_flight": rd["flight"],
            })
        metric = "net" if game == "individual_net" else "gross"
        scored = [e for e in entrants if e[metric] is not None]
        if not scored:
            out["status"] = "awaiting_results"
            return out
        out["rounds_matched"] = len(scored)
        out["awaiting"] = sorted(
            binfo["buyers"][cid] for cid in binfo["buyers"]
            if cid not in {e["customer_id"] for e in scored})

        # GG flight labels ONLY (Kerry, 2026-07-07). Preferred source:
        # gg_game_flights — THIS game's own cut lines, captured from the
        # game's GG leaderboard (flights differ per game, so the single
        # scoring_rounds.flight label is only a legacy fallback).
        # Single-flight games need no labels; multi-flight games without
        # a label on every scored entrant can't be grouped.
        _ensure_gg_game_flights_tables(conn)
        game_flights = {}
        for r in conn.execute(
                "SELECT customer_id, player_name, flight_label "
                "FROM gg_game_flights WHERE event_id = ? AND game = ?",
                (ev["id"], game)).fetchall():
            if r["customer_id"]:
                game_flights[("cid", r["customer_id"])] = r["flight_label"]
            game_flights[("name", (r["player_name"] or "").lower())] = \
                r["flight_label"]
        for e in entrants:
            label = (game_flights.get(("cid", e["customer_id"]))
                     or game_flights.get(("name", e["player"].lower())))
            if label:
                e["game_flight"] = label
        out["flight_source"] = ("gg_game_flights" if game_flights
                                else "scoring_rounds")

        def _label(e):
            # Never mix sources within one game: if per-game flights exist,
            # an entrant absent from them is genuinely unplaced (different
            # games cut differently — the legacy label would be wrong).
            if game_flights:
                return (e.get("game_flight") or "").strip()
            return (e["gg_flight"] or "").strip()

        if flights <= 1:
            flight_groups = [("Field", scored)]
        else:
            missing = sorted(e["player"] for e in scored if not _label(e))
            if missing:
                out["status"] = "flights_unknown"
                out["missing_flight_labels"] = missing
                return out
            by_label: dict = {}
            for e in scored:
                by_label.setdefault(_label(e), []).append(e)

            def _avg_hcp(group):
                vals = [e["playing_handicap"] for e in group
                        if e["playing_handicap"] is not None]
                return sum(vals) / len(vals) if vals else float("inf")

            # Low flight first (lowest average handicap) so the UI's
            # matrix-named rows (Low/High/Mid/4th) align by index.
            flight_groups = sorted(by_label.items(),
                                   key=lambda kv: _avg_hcp(kv[1]))
            if len(flight_groups) != flights:
                out["warnings"] = [
                    f"GG shows {len(flight_groups)} flight(s); the prize "
                    f"matrix expects {flights}."]
        result_flights = []
        for label, group in flight_groups:
            hcps = [e["playing_handicap"] for e in group
                    if e["playing_handicap"] is not None]
            fl = {"flight": label, "players": len(group),
                  "hcp_range": [min(hcps), max(hcps)] if hcps else None}
            if game == "skins":
                fl.update(_flight_skins(conn, group))
            else:
                fl["ranking"] = _rank_with_ties(group, metric)
            result_flights.append(fl)
        out["flights"] = result_flights
        out["status"] = "determined"
        return out


def _flight_skins(conn, group: list[dict]) -> dict:
    """Gross skins within one flight: a hole's outright lowest gross
    wins a skin; any tie kills the hole. Returns skins + per-player
    counts (pot division = flight pot / total skins, done by the UI
    which owns the matrix amounts)."""
    holes: dict[int, list[tuple[int, dict]]] = {}
    for e in group:
        for h in conn.execute(
                "SELECT hole_number, strokes FROM scoring_holes "
                "WHERE scoring_round_id = ? AND strokes IS NOT NULL",
                (e["round_id"],)).fetchall():
            holes.setdefault(h["hole_number"], []).append((h["strokes"], e))
    skins, per_player = [], {}
    for hole in sorted(holes):
        scores = holes[hole]
        low = min(s for s, _ in scores)
        holders = [e for s, e in scores if s == low]
        if len(holders) == 1:
            w = holders[0]
            skins.append({"hole": hole, "player": w["player"],
                          "customer_id": w["customer_id"], "strokes": low})
            per_player[w["player"]] = per_player.get(w["player"], 0) + 1
    return {"skins": skins, "skin_count": len(skins),
            "per_player": per_player}


# ── GG-recorded game results: CTP / Longest Putt / HIO / TEAM Net ──────
# (v2.36.0, Kerry ruling 2026-07-07): these winners are manually entered
# into GG post-round, so the portal is the source of record — pull them
# in rather than compute. Same walk mechanism as import_gg_event_mvps
# (round selector → per-round tournament links → result tables). Live
# page recon (s9.17, 2026-07-07): CTP tables are Pos./Player/Details;
# TEAM Net tables are Pos./Foursome/…/TotalNet with "A + B + C + D TGF
# <chapter>" team strings. Team rows store the full team string with
# is_team=1 (no single customer_id — display-only truth capture).

_GG_GAME_PATTERNS = [
    ("ctp", r"CLOSEST\s+TO\s+(?:THE\s+)?PIN|\bCTP\b"),
    ("longest_putt", r"LONGEST\s+PUTT"),
    ("hio", r"HOLE\s*[- ]?\s*IN\s*[- ]?\s*ONE|\bHIO\b"),
    ("team_net", r"\b(?:TEAM|CART)\s+NET\b"),
]


def _ensure_gg_game_results_tables(conn: sqlite3.Connection) -> None:
    conn.execute("""CREATE TABLE IF NOT EXISTS gg_game_results (
        id                INTEGER PRIMARY KEY AUTOINCREMENT,
        event_id          INTEGER REFERENCES events(id),
        event_code        TEXT,
        gg_round_id       TEXT,
        gg_tournament_id  TEXT,
        game              TEXT NOT NULL,
        game_label        TEXT,
        customer_id       INTEGER REFERENCES customers(customer_id),
        player_name       TEXT NOT NULL,
        is_team           INTEGER NOT NULL DEFAULT 0,
        chapter           TEXT,
        position          TEXT,
        detail            TEXT,
        purse             REAL,
        imported_at       TEXT DEFAULT (datetime('now')),
        UNIQUE (gg_tournament_id, player_name))""")
    conn.execute("""CREATE TABLE IF NOT EXISTS gg_game_results_rounds (
        gg_round_id  TEXT NOT NULL,
        host         TEXT NOT NULL,
        imported_at  TEXT DEFAULT (datetime('now')),
        PRIMARY KEY (gg_round_id, host))""")
    # Rounds whose game boards exist but carry NO winners yet (CTPs are
    # inherently entered after the round — Kerry 2026-07-22: "check back
    # later"). A round listed here is NOT marked done; every import pass
    # re-walks it until winners land or the recheck window lapses.
    conn.execute("""CREATE TABLE IF NOT EXISTS gg_game_recheck (
        gg_round_id  TEXT NOT NULL,
        host         TEXT NOT NULL,
        event_id     INTEGER REFERENCES events(id),
        awaiting     TEXT,
        first_seen   TEXT DEFAULT (datetime('now')),
        PRIMARY KEY (gg_round_id, host))""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_gg_game_results_event "
                 "ON gg_game_results(event_id, game)")


def _game_winners_from_table(table: list) -> list[dict]:
    """Winner rows from a GG proxies/team result table.

    Returns [{player, chapter, position, detail, purse, is_team}].
    Winners = rows with purse > 0; if no purse column/values, rows at
    position 1 (incl. "T1" ties). Blank/notice rows (len mismatch) skip.
    """
    if not table or not table[0]:
        return []
    head = [(c or "").strip().lower() for c in table[0]]

    def col(*names):
        for n in names:
            for i, h in enumerate(head):
                if n in h:
                    return i
        return -1

    pos_i = col("pos")
    player_i = col("player", "foursome", "team", "twosome", "cart")
    purse_i = col("purse")
    detail_i = col("detail")
    if player_i < 0:
        return []
    is_team = 1 if "player" not in head[player_i] else 0
    rows = []
    for r in table[1:]:
        if len(r) != len(head):
            continue
        raw = (r[player_i] or "").strip()
        if not raw:
            continue
        m = re.search(r"\s+TGF\s+([A-Za-z .'-]+)$", raw)
        chapter = m.group(1).strip() if m else None
        name = raw[:m.start()].strip() if m else raw
        rows.append({
            "player": name, "chapter": chapter,
            "position": (r[pos_i] or "").strip() if pos_i > -1 else "",
            "detail": (r[detail_i] or "").strip() if detail_i > -1 else None,
            "purse": _parse_money(r[purse_i]) if purse_i > -1 else 0.0,
            "is_team": is_team,
        })
    winners = [r for r in rows if r["purse"] > 0]
    if not winners:
        winners = [r for r in rows
                   if re.fullmatch(r"t?1\.?", r["position"].lower())]
    return winners


def import_gg_game_results(widget_url: str, db_path: str | Path = DB_PATH,
                           time_budget: float = 42.0,
                           rewalk_recent: int = 0,
                           recheck_days: int = 14,
                           force_event: str | None = None) -> dict:
    """Walk a portal's Event Results rounds and record CTP / Longest
    Putt / Hole-in-One / TEAM Net winners as GG-recorded truth.

    force_event (v2.188.5, championship close-out): the round→event map
    keys on the GG code ([sa]N.N) embedded in an event's item_name —
    "TGF SAN ANTONIO CHAMPIONSHIP" carries none, so its round's winners
    recorded with no event and the Payouts assembly never saw them. A
    round that fails to self-map attaches to the named event instead
    (substring match on item_name); rounds that DO self-map are never
    overridden, so a rewalk window covering older rounds stays safe.

    Same contract as import_gg_event_mvps: widget_url is the
    tournament_results widget (optionally &round=<id>); already-walked
    rounds are skipped via gg_game_results_rounds; stops at time_budget
    seconds — call repeatedly until rounds_left == 0.

    Check-back-later (Kerry-ratified 2026-07-22): CTPs (and any manually
    entered game) are inherently recorded AFTER the round, so a round
    whose game board exists but carries no winners yet is NOT marked
    done — it lands in gg_game_recheck and re-walks on every pass until
    winners appear or the event is `recheck_days` old (then give up and
    mark done). The result's `events_updated` lists events whose winner
    set actually CHANGED this pass, so the caller can refresh their
    recorded payouts (a late CTP flows through to the Payouts tab).
    """
    from time import monotonic
    from datetime import date as _date, timedelta as _timedelta
    from urllib.parse import urlparse, parse_qs, urlencode, urlunparse
    from golf_genius_sync import fetch_public_page, parse_page_structure
    from .timezone_utils import today_central

    started = monotonic()
    parts = urlparse(widget_url)
    host = parts.netloc
    qs = parse_qs(parts.query)
    only_round = (qs.pop("round", [None]) or [None])[0]
    base_url = urlunparse(parts._replace(query=urlencode(qs, doseq=True)))

    def fetch(url):
        page = fetch_public_page(url, xhr=False)
        if page["status_code"] != 200:
            raise RuntimeError(f"GG returned HTTP {page['status_code']} for {url}")
        return page["html"]

    html = fetch(base_url)
    sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>', html, re.S)
    options = re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                         sel.group(1) if sel else "", re.S)
    if only_round:
        options = [(rid, lbl) for rid, lbl in options if rid == only_round] \
            or [(only_round, "")]

    result = {"rounds_done": 0, "rounds_skipped": 0, "winners_recorded": 0,
              "rounds_left": 0, "unresolved_names": [], "notes": []}
    with _connect(db_path) as conn:
        _ensure_gg_game_results_tables(conn)
        done = {r["gg_round_id"] for r in conn.execute(
            "SELECT gg_round_id FROM gg_game_results_rounds WHERE host = ?",
            (host,)).fetchall()}
        # A live round gets marked done before its results are entered —
        # always re-walk the newest N rounds (upserts make it safe).
        done -= {rid for rid, _ in options[:rewalk_recent]}
        # Rounds awaiting late-entered winners (gg_game_recheck) re-walk
        # on every pass regardless of the done marker.
        done -= {r["gg_round_id"] for r in conn.execute(
            "SELECT gg_round_id FROM gg_game_recheck WHERE host = ?",
            (host,)).fetchall()}
        # An EXPLICITLY requested round (&round=<id> on the widget URL)
        # always re-walks — that's how a stale capture is healed on demand.
        if only_round:
            done.discard(only_round)
        code_map = {}
        for r in conn.execute(
                "SELECT id, item_name, event_date FROM events").fetchall():
            m = _GG_EVENT_CODE_COMPOUND_RE.match((r["item_name"] or "").strip())
            if m:
                code_map.setdefault(m.group(1).lower(),
                                    (r["id"], r["item_name"], r["event_date"]))
        forced = None
        if force_event:
            fr = conn.execute(
                "SELECT id, item_name, event_date FROM events "
                "WHERE item_name LIKE ? ORDER BY event_date DESC LIMIT 1",
                ("%" + force_event.strip() + "%",)).fetchone()
            if not fr:
                return {"error": f"force_event {force_event!r} matches no "
                                 "event"}
            forced = (fr["id"], fr["item_name"], fr["event_date"])
        _today = today_central()

        pending = [(rid, lbl) for rid, lbl in options if rid not in done]
        for rid, _lbl in pending:
            if monotonic() - started > time_budget:
                break
            round_url = f"{base_url}&round={rid}"
            struct = parse_page_structure(fetch(round_url), round_url)
            links = struct.get("links") or []
            names_blob = " ".join(l.get("text") or "" for l in links)
            ev_id, ev_code = None, None
            m = re.search(r"\b([sa]\d+(?:\.\d+)?)\b", names_blob)
            if m and m.group(1).lower() in code_map:
                ev_code = m.group(1).lower()
                ev_id = code_map[ev_code][0]
            elif "kickoff" in names_blob.lower() and "austin" in host:
                ev_code = "a18.2"
                ev_id = code_map.get("a18.2", (None,))[0]
            if ev_id is None and forced:
                # championship rounds carry no calendar-mapped code — the
                # caller names the event (see force_event in the docstring)
                ev_code = ((m.group(1).lower() if m else None)
                           or forced[1].strip().lower())
                ev_id = forced[0]
                code_map.setdefault(ev_code, forced)
            awaiting = []       # game boards present but no winners entered yet
            round_changed = False   # any tournament's winner set changed
            for l in links:
                text = (l.get("text") or "").strip()
                if "POINTS" in text.upper() or re.search(r"\bMVP\b", text, re.I):
                    continue
                game = next((g for g, pat in _GG_GAME_PATTERNS
                             if re.search(pat, text, re.I)), None)
                if not game:
                    continue
                href = l.get("href") or ""
                tid_m = re.search(r"/v2tournaments/(\d+)", href)
                if not tid_m:
                    continue
                if href.startswith("/"):
                    href = f"https://{host}{href}"
                tstruct = parse_page_structure(fetch(href), href)
                tid = tid_m.group(1)
                fresh: list = []
                for table in tstruct.get("tables") or []:
                    fresh.extend(_game_winners_from_table(table))
                if not fresh:
                    # Board exists but no winners entered yet (CTPs are
                    # inherently recorded after the round) — check back
                    # later instead of marking the round done.
                    awaiting.append(text)
                    continue
                prior = {(r["player_name"], round(float(r["purse"] or 0), 2))
                         for r in conn.execute(
                             "SELECT player_name, purse FROM gg_game_results "
                             "WHERE gg_tournament_id = ?", (tid,)).fetchall()}
                if {(w["player"], round(float(w["purse"] or 0), 2))
                        for w in fresh} != prior:
                    round_changed = True
                for w in fresh:
                    cid = None
                    if not w["is_team"]:
                        cid = _resolve_scoring_player(conn, w["player"])
                        if cid is None and w["player"] not in result["unresolved_names"]:
                            result["unresolved_names"].append(w["player"])
                    conn.execute(
                        """INSERT INTO gg_game_results
                               (event_id, event_code, gg_round_id,
                                gg_tournament_id, game, game_label,
                                customer_id, player_name, is_team,
                                chapter, position, detail, purse)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                           ON CONFLICT (gg_tournament_id, player_name)
                           DO UPDATE SET purse = excluded.purse,
                                         position = excluded.position,
                                         detail = excluded.detail,
                                         customer_id = COALESCE(excluded.customer_id, gg_game_results.customer_id),
                                         event_id = COALESCE(excluded.event_id, gg_game_results.event_id)""",
                        (ev_id, ev_code, rid, tid, game, text,
                         cid, w["player"], w["is_team"], w["chapter"],
                         w["position"], w["detail"], w["purse"]))
                    result["winners_recorded"] += 1
                # REPLACE semantics per tournament (v2.126.3): drop rows a
                # previous walk stored that are NOT in the current winner
                # set. A walk during a live round captures transient
                # standings (e.g. every team "T1 · $0"); the later re-walk
                # upserted the real winners but left the stale rows — the
                # a9.18/s18.8 phantom Team Net "ties".
                if fresh:
                    names = [w["player"] for w in fresh]
                    ph = ",".join("?" * len(names))
                    stale = conn.execute(
                        f"DELETE FROM gg_game_results WHERE gg_tournament_id"
                        f" = ? AND player_name NOT IN ({ph})",
                        [tid, *names]).rowcount
                    if stale:
                        result.setdefault("stale_rows_dropped", 0)
                        result["stale_rows_dropped"] += stale
            # A round with empty game boards stays PENDING (re-walked every
            # pass) until winners land or the event ages past recheck_days.
            ev_date = code_map[ev_code][2] if ev_code and ev_code in code_map else None
            recheck = False
            if awaiting and ev_id:
                try:
                    age = (_today - _date.fromisoformat(ev_date)).days if ev_date else 0
                except Exception:
                    age = 0
                recheck = age <= recheck_days
            if recheck:
                conn.execute(
                    """INSERT INTO gg_game_recheck (gg_round_id, host, event_id, awaiting)
                       VALUES (?, ?, ?, ?)
                       ON CONFLICT (gg_round_id, host)
                       DO UPDATE SET awaiting = excluded.awaiting""",
                    (rid, host, ev_id, " | ".join(awaiting)))
                result.setdefault("rechecks", []).append(
                    {"round": rid, "event": ev_code, "awaiting": awaiting})
            else:
                conn.execute(
                    "INSERT OR IGNORE INTO gg_game_results_rounds (gg_round_id, host) VALUES (?, ?)",
                    (rid, host))
                conn.execute(
                    "DELETE FROM gg_game_recheck WHERE gg_round_id = ? AND host = ?",
                    (rid, host))
            if round_changed and ev_code and ev_code in code_map:
                result.setdefault("events_updated", [])
                _iname = code_map[ev_code][1]
                if _iname not in result["events_updated"]:
                    result["events_updated"].append(_iname)
            conn.commit()
            result["rounds_done"] += 1
        result["rounds_skipped"] = len(options) - len(pending)
        result["rounds_left"] = len(pending) - result["rounds_done"]
    return result


# ── Per-game flights (v2.37.0, Kerry design ruling 2026-07-07) ─────────
# Flights vary per game (Net, Gross, and Skins cut differently), so a
# player's flight is a property of (game, event), NOT of their round —
# scoring_rounds.flight (one label per round, last-import-wins) stays
# only as a legacy fallback. gg_game_flights holds "Joe Smith is in
# flight X for THIS game": captured by walking each flighted game's own
# GG tournament page, whose per-player details fragments carry the
# "Flight …" section label (the same parse the scorecard importer uses).

_GG_FLIGHT_GAME_PATTERNS = [
    ("individual_net", r"INDIVIDUAL\s+NET"),
    ("individual_gross", r"INDIVIDUAL\s+GROSS"),
    ("skins", r"\bSKINS\b"),
]


def _skins_flights_from_expandall(tables: list) -> dict:
    """Flight membership from a skins Expand-All page
    (/tournaments2/details?adjusting=false&event_id=<tid>).

    Skins leaderboards have no per-player detail fragments, but Expand
    All renders one per-player skin GRID per flight: a table whose first
    row is the flight label (single cell), second row the hole header
    (contains Out/Total), and remaining rows one player each (name in
    column 0). The hole/Won summary tables (header Hole/Par/Score/Won)
    are skipped. Returns {flight_label: [player names]}.
    """
    out: dict = {}
    for t in tables or []:
        if not t or len(t) < 3 or not t[0]:
            continue
        first = [c for c in t[0] if (c or "").strip()]
        if len(first) != 1:
            continue
        label = first[0].strip()
        header = [(c or "").strip().lower() for c in (t[1] or [])]
        if "out" not in header and "total" not in header:
            continue
        for row in t[2:]:
            name = (row[0] or "").strip() if row else ""
            if name and name.lower() not in ("hole", "total"):
                out.setdefault(label, []).append(name)
    return out


def _flight_sections_from_leaderboard(tables: list) -> dict:
    """Flight membership from a flight-SECTIONED leaderboard table.

    The Austin portal renders flighted Ind Net/Gross boards as ONE
    table with single-cell section headings ("LOW Flight" / "HIGH
    Flight") each followed by a Pos./Player header row — and exposes
    NO per-player detail fragments (a9.17 Falconhead), so the fragment
    walk records nothing there. Returns {flight_label: [names]} with
    chapter suffixes stripped; empty for unsectioned boards.
    """
    out: dict = {}
    for t in tables or []:
        label, player_i = None, -1
        for row in t or []:
            cells = [(c or "").strip() for c in (row or [])]
            nonempty = [c for c in cells if c]
            if len(cells) <= 1:
                if not nonempty:
                    continue          # blank separator row — stay in section
                # single-cell row with text: a new section heading (must
                # say "flight") or a footer — either way the previous
                # section ends here.
                label = nonempty[0] if re.search(
                    r"flight", nonempty[0], re.I) else None
                player_i = -1
                continue
            low = [c.lower() for c in cells]
            if label and player_i < 0:
                if any("player" in c for c in low):
                    player_i = next(i for i, c in enumerate(low) if "player" in c)
                continue
            if label and player_i > -1 and len(cells) > player_i:
                raw = cells[player_i]
                if not raw:
                    continue
                m = re.search(r"\s+TGF\s+([A-Za-z .'-]+)$", raw)
                name = raw[:m.start()].strip() if m else raw
                if name:
                    out.setdefault(label, []).append(name)
    return out


def _ensure_gg_game_flights_tables(conn: sqlite3.Connection) -> None:
    conn.execute("""CREATE TABLE IF NOT EXISTS gg_game_flights (
        id                INTEGER PRIMARY KEY AUTOINCREMENT,
        event_id          INTEGER REFERENCES events(id),
        event_code        TEXT,
        gg_round_id       TEXT,
        gg_tournament_id  TEXT NOT NULL,
        game              TEXT NOT NULL,
        flight_label      TEXT NOT NULL,
        customer_id       INTEGER REFERENCES customers(customer_id),
        player_name       TEXT NOT NULL,
        imported_at       TEXT DEFAULT (datetime('now')),
        UNIQUE (gg_tournament_id, player_name))""")
    conn.execute("""CREATE TABLE IF NOT EXISTS gg_game_flights_rounds (
        gg_round_id  TEXT NOT NULL,
        host         TEXT NOT NULL,
        imported_at  TEXT DEFAULT (datetime('now')),
        PRIMARY KEY (gg_round_id, host))""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_gg_game_flights_event "
                 "ON gg_game_flights(event_id, game)")


def import_gg_game_flights(widget_url: str, db_path: str | Path = DB_PATH,
                           time_budget: float = 42.0,
                           reset: bool = False,
                           rewalk_recent: int = 0) -> dict:
    """Walk a portal's rounds and capture per-game flight membership.

    For every flighted-game leaderboard (Individual Net / Individual
    Gross / Skins) in each round, fetch the per-player details fragments
    and record (game, flight_label, player). Unflighted tournaments
    (fragments carry no Flight section) record nothing — single-flight
    games don't need labels. Same contract as the other portal walks:
    time-budgeted, per-round dedup via gg_game_flights_rounds, call
    repeatedly until rounds_left == 0.
    """
    from time import monotonic
    from urllib.parse import urlparse, parse_qs, urlencode, urlunparse
    from golf_genius_sync import (fetch_public_page, parse_page_structure,
                                  parse_tournament_aggregates,
                                  parse_scorecard_details, _unwrap_js_string)

    started = monotonic()
    parts = urlparse(widget_url)
    host = parts.netloc
    qs = parse_qs(parts.query)
    only_round = (qs.pop("round", [None]) or [None])[0]
    base_url = urlunparse(parts._replace(query=urlencode(qs, doseq=True)))

    def fetch(url, xhr=False):
        page = fetch_public_page(url, xhr=xhr)
        if page["status_code"] != 200:
            raise RuntimeError(f"GG returned HTTP {page['status_code']} for {url}")
        return page["html"]

    html = fetch(base_url)
    sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>', html, re.S)
    options = re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                         sel.group(1) if sel else "", re.S)
    if only_round:
        options = [(rid, lbl) for rid, lbl in options if rid == only_round] \
            or [(only_round, "")]

    result = {"rounds_done": 0, "rounds_skipped": 0, "flights_recorded": 0,
              "rounds_left": 0, "per_game": {}, "unresolved_names": []}
    with _connect(db_path) as conn:
        _ensure_gg_game_flights_tables(conn)
        if reset:
            # Re-walk (e.g. after a parser extension like the skins
            # Expand-All membership capture). Upserts make it safe. A
            # ?round=<id> on the widget URL scopes the reset to that round —
            # a full-host reset would force the next auto sync to re-walk
            # every historical round just to re-capture one.
            if only_round:
                conn.execute("DELETE FROM gg_game_flights_rounds "
                             "WHERE host = ? AND gg_round_id = ?",
                             (host, only_round))
            else:
                conn.execute("DELETE FROM gg_game_flights_rounds WHERE host = ?",
                             (host,))
            conn.commit()
        done = {r["gg_round_id"] for r in conn.execute(
            "SELECT gg_round_id FROM gg_game_flights_rounds WHERE host = ?",
            (host,)).fetchall()}
        done -= {rid for rid, _ in options[:rewalk_recent]}
        code_map = {}
        for r in conn.execute("SELECT id, item_name FROM events").fetchall():
            m = _GG_EVENT_CODE_COMPOUND_RE.match((r["item_name"] or "").strip())
            if m:
                code_map.setdefault(m.group(1).lower(), (r["id"], r["item_name"]))

        pending = [(rid, lbl) for rid, lbl in options if rid not in done]
        out_of_time = False
        for rid, _lbl in pending:
            if monotonic() - started > time_budget:
                break
            round_url = f"{base_url}&round={rid}"
            struct = parse_page_structure(fetch(round_url), round_url)
            links = struct.get("links") or []
            names_blob = " ".join(l.get("text") or "" for l in links)
            ev_id, ev_code = None, None
            m = re.search(r"\b([sa]\d+(?:\.\d+)?)\b", names_blob)
            if m and m.group(1).lower() in code_map:
                ev_code = m.group(1).lower()
                ev_id = code_map[ev_code][0]
            if ev_id is None:
                # No [sa]N.N code in the round's board names (championship
                # events carry full names, not codes) — resolve through the
                # scorecard import's own linkage: scoring_rounds already
                # maps this GG league round to an event, and flight labels
                # recorded without an event_id are invisible to
                # determine_event_game_results (its lookup keys on event_id).
                lr = conn.execute(
                    "SELECT event_id FROM scoring_rounds "
                    "WHERE gg_league_round_id = ? AND event_id IS NOT NULL "
                    "GROUP BY event_id ORDER BY COUNT(*) DESC LIMIT 1",
                    (rid,)).fetchone()
                if lr:
                    ev_id = lr["event_id"]
            for l in links:
                text = (l.get("text") or "").strip()
                if "POINTS" in text.upper() or re.search(r"\bMVP\b|\bALL\b", text, re.I):
                    continue
                game = next((g for g, pat in _GG_FLIGHT_GAME_PATTERNS
                             if re.search(pat, text, re.I)), None)
                if not game:
                    continue
                href = l.get("href") or ""
                tid_m = re.search(r"/v2tournaments/(\d+)", href)
                if not tid_m:
                    continue
                if href.startswith("/"):
                    href = f"https://{host}{href}"

                def _record(flight_label, player_name):
                    cid = _resolve_scoring_player(conn, player_name)
                    if cid is None and player_name not in result["unresolved_names"]:
                        result["unresolved_names"].append(player_name)
                    conn.execute(
                        """INSERT INTO gg_game_flights
                               (event_id, event_code, gg_round_id,
                                gg_tournament_id, game, flight_label,
                                customer_id, player_name)
                           VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                           ON CONFLICT (gg_tournament_id, player_name)
                           DO UPDATE SET flight_label = excluded.flight_label,
                                         customer_id = COALESCE(excluded.customer_id, gg_game_flights.customer_id),
                                         event_id = COALESCE(excluded.event_id, gg_game_flights.event_id)""",
                        (ev_id, ev_code, rid, tid_m.group(1), game,
                         flight_label, cid, player_name))
                    result["flights_recorded"] += 1
                    result["per_game"][game] = result["per_game"].get(game, 0) + 1

                if game == "skins":
                    # Skins leaderboards have no per-player fragments; the
                    # Expand-All view renders full membership per flight
                    # (Kerry, 2026-07-07).
                    ex_url = (f"https://{host}/tournaments2/details"
                              f"?adjusting=false&event_id={tid_m.group(1)}")
                    ex_struct = parse_page_structure(fetch(ex_url), ex_url)
                    membership = _skins_flights_from_expandall(
                        ex_struct.get("tables") or [])
                    if len(membership) > 1:   # single section = unflighted
                        for flight_label, names in membership.items():
                            for nm in names:
                                _record(flight_label, nm)
                    continue

                page_html = fetch(href)
                before = result["flights_recorded"]
                for agg in parse_tournament_aggregates(page_html):
                    if monotonic() - started > time_budget:
                        out_of_time = True
                        break
                    frag = _unwrap_js_string(
                        fetch(f"https://{host}/tournaments2/details/{agg}",
                              xhr=True))
                    if not frag:
                        continue
                    parsed = parse_scorecard_details(frag)
                    if not parsed["flight"]:
                        continue        # unflighted tournament — no labels
                    for p in parsed["players"]:
                        if not p.get("player_name"):
                            continue
                        _record(parsed["flight"], p["player_name"])
                if out_of_time:
                    break
                if result["flights_recorded"] == before:
                    # Fragments carried no flight labels (Austin) — fall
                    # back to flight-section headings on the leaderboard
                    # itself (v2.41.2, a9.17 Falconhead Ind Net).
                    sec_struct = parse_page_structure(page_html, href)
                    membership = _flight_sections_from_leaderboard(
                        sec_struct.get("tables") or [])
                    if len(membership) > 1:   # single section = unflighted
                        for flight_label, names in membership.items():
                            for nm in names:
                                _record(flight_label, nm)
            if out_of_time:
                # do NOT mark the round done — resume here next call
                conn.commit()
                break
            conn.execute(
                "INSERT OR IGNORE INTO gg_game_flights_rounds (gg_round_id, host) VALUES (?, ?)",
                (rid, host))
            conn.commit()
            result["rounds_done"] += 1
        result["rounds_skipped"] = len(options) - len(pending)
        result["rounds_left"] = len(pending) - result["rounds_done"]
    return result


_GG_RESULT_PORTALS = [
    "https://tgf-sa.golfgenius.com/leagues/514047/widgets/tournament_results?shared=false",
    "https://tgf-austin.golfgenius.com/leagues/514705/widgets/tournament_results?shared=false",
]


def auto_gg_results_sync(db_path: str | Path = DB_PATH,
                         scorecard_rounds: int = 2,
                         rewalk_recent: int = 2,
                         recent_force_days: int = 3) -> dict:
    """One pass of the close-the-event-in-GG → results-in-Tracker pipeline
    (v2.40.0, Kerry: "I expected that once I closed the event on GG that
    results would show up in Tracker").

    For each portal: (1) import scorecards for the newest N rounds' ALL
    Net then ALL Gross boards (idempotent; net-first per the ordering
    rule so handicaps land); (2) re-walk the newest rounds for
    GG-recorded winners (CTP/LP/HIO/Team Net) and per-game flights —
    live rounds get marked done before results exist, so recent rounds
    always re-walk; (3) refresh auto-recorded payouts, force-replacing
    events from the last few days so late GG entries flow through.
    Runs from the hourly scheduler job; trigger on demand via the
    probe_golf_genius bridge (scoring-auto-sync).
    """
    from urllib.parse import urlparse
    from golf_genius_sync import fetch_public_page, parse_page_structure
    from .timezone_utils import today_central
    from datetime import timedelta as _td

    # Results only change after events (Kerry, 2026-07-08): skip the GG
    # walk entirely unless an event happened today or yesterday (Central)
    # — yesterday covers late-evening closes rolling past midnight. The
    # on-demand bridge (scoring-auto-sync) bypasses nothing: it calls this
    # same function, so a no-event day returns the skip marker; use the
    # targeted bridge commands for manual pulls on off days.
    _today = today_central()
    _days = {_today.isoformat(), (_today - _td(days=1)).isoformat()}
    with _connect(db_path) as _conn:
        _hit = _conn.execute(
            "SELECT 1 FROM events WHERE event_date IN (?, ?) LIMIT 1",
            tuple(sorted(_days))).fetchone()
        if not _hit:
            # Late-entered winners (CTPs land days after the round —
            # Kerry 2026-07-22): outstanding rechecks keep the sweep
            # alive on off days until the winners appear or the recheck
            # window lapses inside import_gg_game_results.
            try:
                _hit = _conn.execute(
                    "SELECT 1 FROM gg_game_recheck LIMIT 1").fetchone()
            except sqlite3.OperationalError:
                _hit = None
    if not _hit:
        return {"skipped": "no event today/yesterday and no rounds awaiting "
                           "late winners — GG results only change after events",
                "portals": []}

    out: dict = {"portals": []}
    for widget in _GG_RESULT_PORTALS:
        host = urlparse(widget).netloc
        p: dict = {"host": host}
        # Each step gets its own try/except (v2.41.0): a transient GG
        # failure while walking scorecard rounds must not skip the games
        # and flights walks for the portal — that's how s9.17 Silverhorn
        # got payouts recorded with no Team Net/CTP winners attached.
        try:
            page = fetch_public_page(widget, xhr=False)
            if page["status_code"] != 200:
                raise RuntimeError(f"GG returned HTTP {page['status_code']}")
            sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>',
                            page["html"], re.S)
            options = re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                                 sel.group(1) if sel else "", re.S)
        except Exception as e:
            p["error"] = str(e)
            options = []
        if options:
            p["scorecards"] = []
            try:
                with _connect(db_path) as conn:
                    code_map = {}
                    for r in conn.execute("SELECT id, item_name FROM events").fetchall():
                        m = _GG_EVENT_CODE_COMPOUND_RE.match((r["item_name"] or "").strip())
                        if m:
                            code_map.setdefault(m.group(1).lower(), r["item_name"])
                for rid, _lbl in options[:scorecard_rounds]:
                    round_url = f"{widget}&round={rid}"
                    try:
                        struct = parse_page_structure(
                            fetch_public_page(round_url, xhr=False)["html"], round_url)
                    except Exception as e:
                        p["scorecards"].append({"round": rid, "error": str(e)})
                        continue
                    links = struct.get("links") or []
                    blob = " ".join(l.get("text") or "" for l in links)
                    m = re.search(r"\b([sa]\d+(?:\.\d+)?)\b", blob)
                    code = m.group(1).lower() if (m and m.group(1).lower() in code_map) else None
                    if not code:
                        p["scorecards"].append({"round": rid, "note": "no event code — skipped"})
                        continue
                    # Board names vary per portal: SA uses "ALL Net"/"ALL
                    # Gross", Austin "ALL Net 9"/"ALL Gross 9" — prefix
                    # match (v2.41.1; exact match meant Austin events never
                    # got scorecards from the auto-sync, a9.17 Falconhead).
                    for want in ("ALL Net", "ALL Gross"):   # net FIRST (handicaps)
                        board_links = [l for l in links
                                       if (l.get("text") or "").strip().lower()
                                       .startswith(want.lower())]
                        for link in board_links:
                            label = (link.get("text") or "").strip() or want
                            href = link.get("href") or ""
                            if href.startswith("/"):
                                href = f"https://{host}{href}"
                            try:
                                res = import_gg_scorecards(href, event_code=code,
                                                           db_path=db_path)
                                p["scorecards"].append({
                                    "round": rid, "board": label, "event": code,
                                    **{k: v for k, v in (res or {}).items()
                                       if isinstance(v, (int, float, str))}})
                            except Exception as e:
                                p["scorecards"].append({"round": rid, "board": label,
                                                        "error": str(e)})
            except Exception as e:
                p["scorecards_error"] = str(e)
        try:
            p["games"] = import_gg_game_results(widget, db_path=db_path,
                                                rewalk_recent=rewalk_recent)
        except Exception as e:
            p["games"] = {"error": str(e)}
        try:
            p["flights"] = import_gg_game_flights(widget, db_path=db_path,
                                                  rewalk_recent=rewalk_recent)
        except Exception as e:
            p["flights"] = {"error": str(e)}
        out["portals"].append(p)
    # Events whose GG winner set CHANGED this pass (late CTP finally
    # entered) force a payout re-record even outside recent_force_days.
    changed_events: list = []
    for p in out["portals"]:
        for name in (p.get("games") or {}).get("events_updated") or []:
            if name not in changed_events:
                changed_events.append(name)
    try:
        out["payouts"] = record_all_event_game_payouts(
            db_path=db_path, time_budget=60,
            recent_force_days=recent_force_days,
            force_events=changed_events)
    except Exception as e:
        out["payouts"] = {"error": str(e)}
    return out


def import_event_scorecards_by_code(widget_url: str, event_code: str,
                                    only_round: str | None = None,
                                    refresh_players: list | None = None,
                                    time_budget: float = 45.0,
                                    db_path: str | Path = DB_PATH) -> dict:
    """Targeted scorecard import for ONE past event: walk the portal
    widget's round selector, find the round whose tournament links carry
    `event_code`, and import that round's ALL Net then ALL Gross boards
    (net first so handicaps land — same recipe as the auto-sync). Built
    for backfilling events older than the auto-sync's newest-N window
    (the 2026-07-20 Austin match-play hole-data gap). only_round skips
    the scan and imports that GG round id directly. Read-only on GG;
    idempotent on our side (import_gg_scorecards replaces existing).

    refresh_players: names whose STALE stored cards should be force-replaced
    from GG's current board — GG score corrections made after our import
    can't self-heal because the cross-tournament dedup treats the existing
    row as owned (the s18.8 Wilson case: GG edited his front nine post-
    import, 97 → 91). For each named player the stored scoring_rounds row,
    its holes, AND its bridged handicap_rounds are deleted first, so the
    board import brings the current card in fresh and re-bridges."""
    from time import monotonic
    from urllib.parse import urlparse
    from golf_genius_sync import fetch_public_page, parse_page_structure

    started = monotonic()
    host = urlparse(widget_url).netloc
    code = (event_code or "").strip().lower()
    out: dict = {"event_code": code, "host": host, "boards": []}

    if refresh_players:
        keys = {_cmp_person_key(p) for p in refresh_players if p and p.strip()}
        with _connect(db_path) as conn:
            ev = conn.execute(
                "SELECT id FROM events WHERE item_name LIKE ? ORDER BY id "
                "LIMIT 1", (code + " %",)).fetchone()
            dropped = []
            if ev:
                for r in conn.execute(
                        "SELECT id, player_name FROM scoring_rounds "
                        "WHERE event_id = ?", (ev["id"],)).fetchall():
                    if _cmp_person_key(r["player_name"]) in keys:
                        conn.execute("DELETE FROM handicap_rounds "
                                     "WHERE scoring_round_id = ?", (r["id"],))
                        conn.execute("DELETE FROM scoring_holes "
                                     "WHERE scoring_round_id = ?", (r["id"],))
                        conn.execute("DELETE FROM scoring_rounds WHERE id = ?",
                                     (r["id"],))
                        dropped.append(r["player_name"])
                conn.commit()
            out["refreshed_players_dropped"] = dropped

    def fetch(url):
        page = fetch_public_page(url, xhr=False)
        if page["status_code"] != 200:
            raise RuntimeError(f"GG returned HTTP {page['status_code']} for {url}")
        return page["html"]

    if only_round:
        options = [(str(only_round), "")]
    else:
        html = fetch(widget_url)
        sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>',
                        html, re.S)
        options = re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                             sel.group(1) if sel else "", re.S)
        if not options:
            return {**out, "error": "no round selector on widget page"}

    scanned = 0
    for rid, _lbl in options:
        if monotonic() - started > time_budget:
            out["error"] = (f"time budget exhausted after {scanned} rounds — "
                            f"re-run, or pass @<round_id>")
            return out
        round_url = f"{widget_url}&round={rid}"
        try:
            struct = parse_page_structure(fetch(round_url), round_url)
        except Exception as e:
            out.setdefault("round_errors", []).append({"round": rid, "error": str(e)})
            continue
        scanned += 1
        links = struct.get("links") or []
        blob = " ".join(l.get("text") or "" for l in links)
        m = re.search(r"\b([sa]\d+(?:\.\d+)?)\b", blob)
        if not only_round and (not m or m.group(1).lower() != code):
            continue
        out["round"] = rid
        for want in ("ALL Net", "ALL Gross"):   # net FIRST (handicaps)
            board_links = [l for l in links
                           if (l.get("text") or "").strip().lower()
                           .startswith(want.lower())]
            for link in board_links:
                label = (link.get("text") or "").strip() or want
                href = link.get("href") or ""
                if href.startswith("/"):
                    href = f"https://{host}{href}"
                try:
                    # round_key stamps gg_league_round_id on the imported
                    # rows (v2.188.7 — the omission left championship
                    # rounds with no round identity to repair by)
                    res = import_gg_scorecards(href, event_code=code,
                                               round_key=str(rid),
                                               db_path=db_path)
                    out["boards"].append({
                        "board": label,
                        **{k: v for k, v in (res or {}).items()
                           if isinstance(v, (int, float, str))}})
                except Exception as e:
                    out["boards"].append({"board": label, "error": str(e)})
        if not out["boards"]:
            out["note"] = "round found but no ALL Net/ALL Gross board links"
        return out
    out["error"] = f"no round matching '{code}' found ({scanned} rounds scanned)"
    return out


def get_gg_game_results(event_name: str, db_path: str | Path = DB_PATH) -> dict:
    """GG-recorded winners (CTP/LP/HIO/TEAM Net) for one event."""
    with _connect(db_path) as conn:
        _ensure_gg_game_results_tables(conn)
        ev = conn.execute(
            "SELECT id, item_name FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        rows = [dict(r) for r in conn.execute(
            """SELECT game, game_label, player_name, is_team, chapter,
                      position, detail, purse, customer_id
               FROM gg_game_results WHERE event_id = ?
               ORDER BY game, game_label, purse DESC, player_name""",
            (ev["id"],)).fetchall()]
        return {"event_name": ev["item_name"], "results": rows}


# ── Monthly points races (v2.30.0) ─────────────────────────────────────
# Each chapter portal publishes per-month season-points pages ("JUNE
# Points"). The monthly race counts ALL points earned that month (no
# best-10 cap); the award is $1 per active TGF member at the close of
# the month, split on ties. Standings merge both chapters; a player
# appearing in both portals (cross-chapter play) keeps their higher
# total, never the sum.

_MONTH_NUMS = {m.lower(): i + 1 for i, m in enumerate(
    ["January", "February", "March", "April", "May", "June", "July",
     "August", "September", "October", "November", "December"])}


def _synthesize_month_points(conn, month_key: str, errors: list) -> dict:
    """Best-effort monthly standings for a month with no GG "<MONTH>
    Points" page yet (Kerry, 2026-07-08: JULY must show without waiting
    for the portal page to be built each month). Walks the per-player
    season-points detail (the same individual_info XHR the drill-down
    uses) for ONLY the players who have a scoring round in the month,
    and sums the points lines dated in-month. Once the GG page exists,
    link discovery takes over and this path is skipped for that month.
    Returns the same best-of-both-portals dict the page path builds.
    """
    from golf_genius_sync import fetch_points_race_member_detail

    played = conn.execute(
        """SELECT DISTINCT customer_id, player_name FROM scoring_rounds
           WHERE round_date LIKE ?""", (month_key + "%",)).fetchall()
    if not played:
        return {}
    played_cids = {r["customer_id"] for r in played if r["customer_id"]}
    played_names = {(r["player_name"] or "").strip().lower() for r in played}

    best: dict = {}
    for race_key in ("san_antonio_net", "austin_net"):
        cfg = _GG_POINTS_RACES[race_key]
        cards = conn.execute(
            """SELECT player_name, customer_id, affiliation, member_card_id
               FROM gg_points_standings
               WHERE race_key = ? AND member_card_id IS NOT NULL""",
            (race_key,)).fetchall()
        for c in cards:
            cid = c["customer_id"]
            if not ((cid and cid in played_cids)
                    or (c["player_name"] or "").strip().lower() in played_names):
                continue
            try:
                detail = fetch_points_race_member_detail(
                    page_id=cfg["page_id"],
                    member_card_id=c["member_card_id"],
                    league_id=cfg["league_id"], host=cfg["host"])
            except Exception as e:
                errors.append(
                    f"{cfg['chapter']} {month_key} {c['player_name']}: {e}")
                continue
            pts, rounds = 0.0, 0
            for t in detail.get("tables") or []:
                if not t or len(t) < 2:
                    continue
                head = [str(h or "").strip().lower() for h in t[0]]
                d_i = next((i for i, h in enumerate(head) if "date" in h), -1)
                p_i = next((i for i, h in enumerate(head)
                            if h == "pts" or "point" in h), -1)
                if d_i == -1 or p_i == -1:
                    continue
                for row in t[1:]:
                    if len(row) <= max(d_i, p_i):
                        continue
                    if not str(row[d_i] or "").strip().startswith(month_key):
                        continue
                    try:
                        pts += float(str(row[p_i]).replace(",", ""))
                        rounds += 1
                    except ValueError:
                        continue
            if rounds == 0 and pts == 0:
                continue
            k = cid if cid is not None else f"n:{(c['player_name'] or '').lower()}"
            cur = best.get(k)
            if cur is None or pts > cur["points"]:
                aff = re.sub(r"^TGF\s+", "", (c["affiliation"] or "").strip())
                best[k] = {"player_name": c["player_name"],
                           "customer_id": cid,
                           "chapter": aff or cfg["chapter"],
                           "rounds": rounds,
                           "points": round(pts, 2),
                           "member_card_id": c["member_card_id"]}
    return best


def get_monthly_points(db_path: str | Path = DB_PATH) -> dict:
    import calendar
    from golf_genius_sync import (fetch_public_page, parse_page_structure,
                                  fetch_season_points_race)
    from .timezone_utils import today_central

    month_pages: dict = {}
    errors = []
    for race_key in ("san_antonio_net", "austin_net"):
        cfg = _GG_POINTS_RACES[race_key]
        host, league, chapter = cfg["host"], cfg["league_id"], cfg["chapter"]
        try:
            page = fetch_public_page(f"https://{host}/")
            struct = parse_page_structure(
                page["html"], page.get("final_url") or f"https://{host}/")
        except Exception as e:
            errors.append(f"{chapter}: {e}")
            continue
        for l in struct.get("links") or []:
            m = re.match(r"^([A-Za-z]+)\s+Points$", (l.get("text") or "").strip())
            if not m or m.group(1).lower() not in _MONTH_NUMS:
                continue
            pid = re.search(r"/pages/(\d+)", l.get("href") or "")
            if not pid:
                continue
            key = f"{today_central().year}-{_MONTH_NUMS[m.group(1).lower()]:02d}"
            month_pages.setdefault(key, []).append(
                (chapter, host, league, pid.group(1)))

    # The CURRENT month may have no "<MONTH> Points" page on either
    # portal yet (they get built by hand each month). Synthesize it from
    # per-player detail so the tab appears on day one (Kerry, 2026-07-08).
    # Bounded by the RATIFIED active months (admin 2026-07-06): monthly
    # races run Mar-Jul and Sep-Oct only — never invent an August or
    # off-season race.
    _ACTIVE_MONTHLY_MONTHS = {3, 4, 5, 6, 7, 9, 10}
    cur_key = f"{today_central().year}-{today_central().month:02d}"
    synth_keys = (
        {cur_key} - set(month_pages)
        if month_pages and today_central().month in _ACTIVE_MONTHLY_MONTHS
        else set())

    out_months = []
    with _connect(db_path) as conn:
        today = today_central().isoformat()
        for key in sorted(set(month_pages) | synth_keys):
            year, mnum = int(key[:4]), int(key[5:7])
            last_day = calendar.monthrange(year, mnum)[1]
            month_end = f"{year:04d}-{mnum:02d}-{last_day:02d}"
            complete = today > month_end
            member_count = conn.execute(
                """SELECT COUNT(DISTINCT customer_id) AS c
                   FROM customer_memberships
                   WHERE date(started_at) <= ? AND date(expires_at) >= ?""",
                (month_end, month_end)).fetchone()["c"]
            best: dict = {}
            if key in synth_keys:
                best = _synthesize_month_points(conn, key, errors)
            else:
                for chapter, host, league, pid in month_pages[key]:
                    try:
                        rows = fetch_season_points_race(pid, league, host)
                    except Exception as e:
                        errors.append(f"{chapter} {key}: {e}")
                        continue
                    for r in rows:
                        pts = r.get("total_points")
                        if pts is None:
                            continue
                        cid = _resolve_scoring_player(conn, r["player_name"])
                        k = cid if cid is not None else f"n:{r['player_name'].lower()}"
                        cur = best.get(k)
                        if cur is None or pts > cur["points"]:
                            # chapter from the ROW's affiliation ("TGF Austin"),
                            # not the portal — the monthly tables are TGF-wide
                            aff = re.sub(r"^TGF\s+", "",
                                         (r.get("affiliation") or "").strip())
                            best[k] = {"player_name": r["player_name"],
                                       "customer_id": cid,
                                       "chapter": aff or chapter,
                                       "rounds": r.get("tournaments"),
                                       "points": pts,
                                       "member_card_id": r.get("member_card_id")}
            standings = sorted(best.values(), key=lambda x: -x["points"])
            last_pts, last_rank = None, 0
            for i, row in enumerate(standings, 1):
                if row["points"] != last_pts:
                    last_rank, last_pts = i, row["points"]
                row["rank"] = last_rank
            for row in standings:
                tied = sum(1 for x in standings if x["rank"] == row["rank"]) > 1
                row["rank_label"] = f"T{row['rank']}" if tied else str(row["rank"])
            top = standings[0]["points"] if standings else None
            winners = [x for x in standings
                       if top is not None and x["points"] == top and top > 0]
            share = (round(member_count / len(winners), 2)
                     if complete and winners else None)
            out_months.append({
                "month": key,
                "name": calendar.month_name[mnum].upper(),
                "month_end": month_end,
                "complete": complete,
                "member_count": member_count,
                "purse": member_count,
                "winners": ([{"player_name": w["player_name"],
                              "customer_id": w["customer_id"],
                              "share": share} for w in winners]
                            if complete else []),
                "standings": standings,
            })
    return {"months": out_months, "errors": errors}


def get_customer_gg_cards(customer_id: int, db_path: str | Path = DB_PATH) -> list[dict]:
    """Races a customer appears in, from the gg_points_standings snapshot.

    Powers the Customers Points tab: each row carries the member_card_id
    the points-race detail endpoint needs plus the last-known standings
    line for the summary strip. Freshness rides the standings' 12h
    auto-refresh (any Contests visit also refreshes) — fetched_at shows
    the age.
    """
    with _connect(db_path) as conn:
        _ensure_gg_points_table(conn)
        rows = conn.execute(
            """SELECT race_key, rank, player_name, tournaments, wins,
                      total_points, points_behind, member_card_id, fetched_at
               FROM gg_points_standings WHERE customer_id = ?
               ORDER BY race_key""",
            (customer_id,),
        ).fetchall()
    out = []
    for r in rows:
        d = dict(r)
        d["race_label"] = (_GG_POINTS_RACES.get(r["race_key"]) or {}).get("label") or r["race_key"]
        out.append(d)
    return out


def _repair_matrix_gross_totals(conn) -> None:
    """Matrix audit fixes (admin-ratified 2026-07-05, live audit same
    day). Repairs value-guarded defect patterns in the DB-saved matrix
    copies (both 9h and 18h):
    (1) grossTotalPot overstating the GROSS pool at $15xN/hole-multiple
        while the game pots themselves sum to the correct $13xN (admin
        rule: $13 of $16 / $26 of $30 add-on is pot) — the bad total
        fed the Events Games-tab subtotals;
    (2) skins-array cells that violate the ratified flight-pot /
        skin-count formula — includes stale arrays left behind when a
        Matrix UI edit lowered skinsTotal without recomputing payouts
        (live audit found 18h N=12-15 still paying full-pool values);
    (3) teamMWP cells that violate the ratified MWP = team1st / team
        size formula — stale after a UI edit split team1st/team2nd
        without recomputing MWP (live audit found 18h N=32-35);
    (4) grossLow (Individual Gross per-flight payout) cells that
        violate flight pot = individualGross / grossFlights — winner-
        take-all per flight, 2/3-1/3 once grossLow2nd is in play
        (admin ruled 2026-07-05 the hand-rounded 9h N=16-19 values
        should snap to exact division).
    The static seed file mirrors the corrected live copy in-repo.
    Idempotent."""
    for key, mult in (("games_matrix_9", 1), ("games_matrix_18", 2)):
        row = conn.execute(
            "SELECT value FROM app_settings WHERE key = ?", (key,)
        ).fetchone()
        if not row or not row["value"]:
            continue
        matrix = json.loads(row["value"])
        changed = 0
        for pc, e in matrix.items():
            try:
                n = int(pc)
            except (TypeError, ValueError):
                continue
            nums = lambda *vs: all(isinstance(v, (int, float)) for v in vs)
            st, ig, gt = e.get("skinsTotal"), e.get("individualGross"), e.get("grossTotalPot")
            pool = 13.0 * mult * n
            if nums(st, ig, gt) and abs(st + ig - pool) < 0.02 and abs(gt - 15.0 * mult * n) < 0.02:
                e["grossTotalPot"] = pool
                changed += 1
            sf, arr = e.get("skinsFlights"), e.get("skins")
            if nums(st, sf) and sf and isinstance(arr, list):
                pot = st / sf
                for i, v in enumerate(arr):
                    good = round(pot / (i + 1), 2)
                    if isinstance(v, (int, float)) and abs(v - good) > 0.02:
                        arr[i] = good
                        changed += 1
            t1, mwp = e.get("team1st"), e.get("teamMWP")
            size = 2 if "CART" in str(e.get("teamType") or "").upper() else 4
            if nums(t1, mwp) and abs(mwp - t1 / size) > 0.02:
                e["teamMWP"] = round(t1 / size, 2)
                changed += 1
            g1, g2 = e.get("grossLow1st"), e.get("grossLow2nd")
            ig2, gfl = e.get("individualGross"), e.get("grossFlights")
            if nums(ig2, gfl) and gfl:
                fpot = ig2 / gfl
                two_places = isinstance(g2, (int, float)) and g2 > 0
                exp1 = round(fpot * 2 / 3, 2) if two_places else round(fpot, 2)
                if isinstance(g1, (int, float)) and abs(g1 - exp1) > 0.02:
                    e["grossLow1st"] = exp1
                    changed += 1
                if two_places and abs(g2 - fpot / 3) > 0.02:
                    e["grossLow2nd"] = round(fpot / 3, 2)
                    changed += 1
        if changed:
            conn.execute(
                "UPDATE app_settings SET value = ?, updated_at = datetime('now') "
                "WHERE key = ?",
                (json.dumps(matrix), key),
            )
            conn.commit()
            logger.info("Matrix repair: corrected %d cells in %s", changed, key)


# ── Platform dialogue (tracker-claude <-> platform-claude mailbox) ─────
# Durable two-way channel between the Claude Code sessions building the
# Tracker ("tracker-claude") and the claude.ai Golf Fellowship Project
# planning the TGF Platform ("platform-claude"). Both sides read/write
# through MCP tools; the admin triggers each side's turn. created_at is
# a UTC audit stamp (see CLAUDE.md Timezone rules).

def _ensure_platform_dialogue_table(conn) -> None:
    conn.execute(
        """CREATE TABLE IF NOT EXISTS platform_dialogue (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            author TEXT NOT NULL,
            topic TEXT,
            body TEXT NOT NULL,
            created_at TEXT NOT NULL DEFAULT (datetime('now'))
        )"""
    )


def post_platform_dialogue_entry(author: str, body: str, topic: str = "",
                                 db_path: str | Path = DB_PATH) -> dict:
    author = (author or "").strip() or "unknown"
    body = (body or "").strip()
    if not body:
        raise ValueError("body is required")
    with _connect(db_path) as conn:
        _ensure_platform_dialogue_table(conn)
        cur = conn.execute(
            "INSERT INTO platform_dialogue (author, topic, body) VALUES (?, ?, ?)",
            (author, (topic or "").strip(), body),
        )
        conn.commit()
        row = conn.execute(
            "SELECT id, author, topic, body, created_at FROM platform_dialogue WHERE id = ?",
            (cur.lastrowid,),
        ).fetchone()
    return dict(row)


def read_platform_dialogue_entries(limit: int = 20, topic: str = "",
                                   since_id: int = 0,
                                   db_path: str | Path = DB_PATH) -> list[dict]:
    with _connect(db_path) as conn:
        _ensure_platform_dialogue_table(conn)
        clauses, params = [], []
        if topic:
            clauses.append("topic LIKE ?")
            params.append(f"%{topic}%")
        if since_id:
            clauses.append("id > ?")
            params.append(int(since_id))
        where = f" WHERE {' AND '.join(clauses)}" if clauses else ""
        params.append(max(1, min(int(limit or 20), 200)))
        rows = conn.execute(
            f"""SELECT id, author, topic, body, created_at
                FROM platform_dialogue{where}
                ORDER BY id DESC LIMIT ?""",
            params,
        ).fetchall()
    return [dict(r) for r in rows]


def _seed_platform_dialogue(conn) -> None:
    """Boot step: post #1 welcomes the Platform Claude and points it at
    the docs tool. Idempotent — fires only on an empty table."""
    _ensure_platform_dialogue_table(conn)
    if conn.execute("SELECT COUNT(*) FROM platform_dialogue").fetchone()[0]:
        return
    conn.execute(
        "INSERT INTO platform_dialogue (author, topic, body) VALUES (?, ?, ?)",
        ("tracker-claude", "welcome",
         "Hello from tracker-claude — the Claude Code sessions building the "
         "TGF Tracker. This mailbox is our durable two-way channel: post "
         "planning questions, decisions, and directives here and I read them "
         "at the start of each working session; I post session digests and "
         "questions for you the same way. To catch up on everything built to "
         "date, call get_tracker_docs('state-of-the-tracker.md') first, then "
         "get_tracker_docs() with no args to browse the full living docs. "
         "Live production data is available through the other tools on this "
         "server. — 2026-07-05"),
    )
    conn.commit()


# ── Golf Genius data snapshots ──────────────────────────────────────────
# GG-derived payloads persisted so page opens serve instantly from the DB
# instead of waiting on live portal fetches. Refreshed by a daily
# scheduler job and on demand (Refresh button / ?force=1).

def _ensure_gg_snapshot_table(conn) -> None:
    conn.execute(
        """CREATE TABLE IF NOT EXISTS gg_data_snapshots (
            snapshot_key TEXT PRIMARY KEY,
            payload TEXT NOT NULL,
            fetched_at TEXT NOT NULL
        )"""
    )


def save_gg_snapshot(key: str, data: dict, db_path: str | Path = DB_PATH) -> str:
    """Persist a GG payload under ``key``; returns the display-ready
    Central-time stamp written to ``fetched_at``."""
    fetched_at = now_central().strftime("%Y-%m-%d %H:%M")
    with _connect(db_path) as conn:
        _ensure_gg_snapshot_table(conn)
        conn.execute(
            "INSERT INTO gg_data_snapshots (snapshot_key, payload, fetched_at) "
            "VALUES (?, ?, ?) "
            "ON CONFLICT(snapshot_key) DO UPDATE SET "
            "payload = excluded.payload, fetched_at = excluded.fetched_at",
            (key, json.dumps(data), fetched_at),
        )
        conn.commit()
    return fetched_at


def load_gg_snapshot(key: str, db_path: str | Path = DB_PATH) -> dict | None:
    with _connect(db_path) as conn:
        _ensure_gg_snapshot_table(conn)
        row = conn.execute(
            "SELECT payload, fetched_at FROM gg_data_snapshots WHERE snapshot_key = ?",
            (key,),
        ).fetchone()
    if not row:
        return None
    data = json.loads(row["payload"])
    data["fetched_at"] = row["fetched_at"]
    return data


def refresh_monthly_points_snapshot(db_path: str | Path = DB_PATH) -> dict:
    """Live-fetch monthly points from GG and persist the snapshot.

    Called by the daily scheduler job, the Refresh button (?force=1),
    and the boot-time bootstrap when no snapshot exists yet.
    """
    data = get_monthly_points(db_path)
    data["fetched_at"] = save_gg_snapshot("monthly_points", data, db_path)
    return data


# ── Member portal (M1): magic-link tokens + per-member summary ─────────
# Members are customers, not staff — no PINs. A per-customer HMAC token
# (same signing pattern as the roster opt-in links) is the only key, and
# every /api/me/* endpoint derives customer_id FROM THE TOKEN, never from
# a parameter. Bumping customers.portal_token_version revokes all
# outstanding links for that member. See docs/claude/member-portal.md.

def _portal_secret() -> bytes:
    import os as _os
    s = _os.getenv("SECRET_KEY") or "tgf-portal-token-dev-fallback-do-not-use-in-prod"
    return ("portal:" + s).encode("utf-8")


def make_portal_token(customer_id: int, db_path: str | Path = DB_PATH) -> str | None:
    import base64, hashlib, hmac as _hmac
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        row = conn.execute(
            "SELECT portal_token_version FROM customers WHERE customer_id = ?",
            (customer_id,)).fetchone()
    if not row:
        return None
    raw = json.dumps({"c": customer_id, "v": row["portal_token_version"]},
                     separators=(",", ":")).encode("utf-8")
    body = base64.urlsafe_b64encode(raw).rstrip(b"=").decode("ascii")
    sig = _hmac.new(_portal_secret(), body.encode("ascii"), hashlib.sha256).hexdigest()[:32]
    return f"{body}.{sig}"


def verify_portal_token(token: str, db_path: str | Path = DB_PATH) -> int | None:
    """Return the customer_id the token grants, or None."""
    import base64, hashlib, hmac as _hmac
    if not token or "." not in token:
        return None
    body, sig = token.rsplit(".", 1)
    expected = _hmac.new(_portal_secret(), body.encode("ascii"),
                         hashlib.sha256).hexdigest()[:32]
    if not _hmac.compare_digest(sig, expected):
        return None
    try:
        raw = base64.urlsafe_b64decode(body + "=" * (-len(body) % 4))
        payload = json.loads(raw)
        cid, ver = int(payload["c"]), int(payload["v"])
    except (ValueError, KeyError, json.JSONDecodeError):
        return None
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        row = conn.execute(
            "SELECT portal_token_version FROM customers WHERE customer_id = ?",
            (cid,)).fetchone()
    if not row or row["portal_token_version"] != ver:
        return None
    return cid


def get_member_summary(customer_id: int, db_path: str | Path = DB_PATH) -> dict | None:
    """Everything the My TGF page header needs — own data only."""
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        cust = conn.execute(
            """SELECT customer_id, TRIM(first_name || ' ' || last_name) AS name,
                      chapter, current_player_status
               FROM customers WHERE customer_id = ?""",
            (customer_id,)).fetchone()
        if not cust:
            return None
        s = conn.execute(
            """SELECT COUNT(*) AS rounds,
                      MIN(CASE WHEN holes_played <= 9 THEN gross END) AS best_gross_9,
                      MIN(CASE WHEN holes_played <= 9 THEN net END)  AS best_net_9,
                      MIN(CASE WHEN holes_played > 9 THEN gross END) AS best_gross_18,
                      MIN(CASE WHEN holes_played > 9 THEN net END)  AS best_net_18
               FROM scoring_rounds WHERE customer_id = ?""",
            (customer_id,)).fetchone()
        trend = [dict(r) for r in conn.execute(
            """SELECT round_date, differential FROM handicap_rounds
               WHERE customer_id = ? AND differential IS NOT NULL
               ORDER BY round_date DESC, id DESC LIMIT 20""",
            (customer_id,))][::-1]
        par_splits = [dict(r) for r in conn.execute(
            """SELECT cth.par, COUNT(*) AS holes,
                      ROUND(AVG(sh.strokes), 2) AS avg_strokes,
                      ROUND(AVG(sh.strokes) - cth.par, 2) AS avg_vs_par
               FROM scoring_holes sh
               JOIN scoring_rounds sr ON sr.id = sh.scoring_round_id
               JOIN course_tee_holes cth
                 ON cth.tee_id = sr.tee_id AND cth.hole_number = sh.hole_number
               WHERE sr.customer_id = ? AND sh.strokes IS NOT NULL
                 AND cth.par IN (3, 4, 5)
               GROUP BY cth.par ORDER BY cth.par""",
            (customer_id,))]
        si_buckets = [dict(r) for r in conn.execute(
            """SELECT CASE WHEN cth.stroke_index <= 6 THEN 'hardest (SI 1-6)'
                           WHEN cth.stroke_index <= 12 THEN 'middle (SI 7-12)'
                           ELSE 'easiest (SI 13-18)' END AS bucket,
                      COUNT(*) AS holes,
                      ROUND(AVG(sh.strokes - cth.par), 2) AS avg_vs_par
               FROM scoring_holes sh
               JOIN scoring_rounds sr ON sr.id = sh.scoring_round_id
               JOIN course_tee_holes cth
                 ON cth.tee_id = sr.tee_id AND cth.hole_number = sh.hole_number
               WHERE sr.customer_id = ? AND sh.strokes IS NOT NULL
                 AND cth.stroke_index IS NOT NULL AND cth.par IS NOT NULL
               GROUP BY 1 ORDER BY MIN(cth.stroke_index)""",
            (customer_id,))]
        # Current 18-hole index — same read-time source the points races use
        hcp_index = None
        try:
            idx_by_name = {
                p["player_name"]: p["handicap_index_18"]
                for p in get_all_handicap_players(db_path)
                if p.get("handicap_index_18") is not None}
            for lr in conn.execute(
                    """SELECT player_name FROM handicap_player_links
                       WHERE customer_id = ?""", (customer_id,)):
                v = idx_by_name.get(lr["player_name"])
                if v is not None:
                    hcp_index = v
                    break
        except Exception:
            logger.exception("member summary: handicap index lookup failed")
    # Points races: read from the cached snapshots (own row only)
    races = []
    for key, race in _GG_POINTS_RACES.items():
        try:
            data = get_points_race_standings(key, db_path=db_path)
        except Exception:
            continue
        for r in data.get("standings", []):
            if r.get("customer_id") == customer_id:
                races.append({"race": race.get("label", key),
                              "rank": r.get("rank"),
                              "points": r.get("total_points"),
                              "points_reset_projected": r.get("points_reset"),
                              "flight": r.get("flight")})
                break
    return {"customer": dict(cust), "handicap_index_18": hcp_index,
            "season": dict(s), "handicap_trend": trend,
            "par_splits": par_splits, "si_buckets": si_buckets,
            "points_races": races}


def get_differential_parity(db_path: str | Path = DB_PATH) -> dict:
    """Phase 2 parity proof: recompute each bridged handicap round's
    adjusted gross and WHS differential from OUR scorecard facts and
    compare to the values imported from GG's handicap export.

    differential = (113 / slope) x (adjusted_gross - rating), rounded to
    0.1 (PCC assumed 0 — TGF does not use it). Computed with the slope/
    rating stored on the handicap row (what GG used); tee rows whose
    slope/rating disagree with the handicap row are flagged separately.
    9-hole rounds only for now: an 18-hole scoring round bridges TWO
    9-hole differentials (front/back) and splitting those is a later
    pass — they're counted as skipped_18hole.
    """
    formulas = get_scoring_formulas(db_path=db_path)
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        pairs = conn.execute(
            """SELECT hr.id AS hr_id, hr.player_name, hr.round_date,
                      hr.adjusted_score AS gg_adj, hr.differential AS gg_diff,
                      hr.rating AS hr_rating, hr.slope AS hr_slope,
                      sr.id AS srid, sr.holes_played, sr.tee_id, sr.gross,
                      ct.tee_name, ct.rating AS tee_rating, ct.slope AS tee_slope,
                      c.name AS course_name
               FROM handicap_rounds hr
               JOIN scoring_rounds sr ON sr.id = hr.scoring_round_id
               LEFT JOIN course_tees ct ON ct.tee_id = sr.tee_id
               LEFT JOIN courses c ON c.course_id = sr.course_id"""
        ).fetchall()
        n_18 = tee_mismatch = missing_par = 0
        adj_match = diff_match = compared = 0
        # Mismatch families (triage 2026-07-14): GG's handicap export
        # often carries the RAW gross as "adjusted" (no net-double-bogey
        # cap applied), so rounds where our WHS cap binds mismatch low.
        # The opposite family (GG BELOW our capped value) is the
        # mis-bridge / harder-cap residue that needs per-case review.
        fam_gg_is_gross = fam_gg_below = fam_other = 0
        mismatches: list = []
        tee_detail: list = []
        for p in pairs:
            if (p["holes_played"] or 0) > 9:
                n_18 += 1
                continue
            holes = conn.execute(
                """SELECT sh.hole_number, sh.strokes, sh.strokes_received, cth.par
                   FROM scoring_holes sh
                   LEFT JOIN course_tee_holes cth
                     ON cth.tee_id = ? AND cth.hole_number = sh.hole_number
                   WHERE sh.scoring_round_id = ?""",
                (p["tee_id"], p["srid"])).fetchall()
            adj = 0
            bad_par = False
            for h in holes:
                if h["strokes"] is None:
                    continue
                if h["par"] is None:
                    bad_par = True
                    adj += h["strokes"]
                    continue
                adj += compute_hole_derivations(
                    h["par"], h["strokes"], h["strokes_received"] or 0,
                    formulas)["adjusted_strokes"]
            if bad_par:
                missing_par += 1
            if (p["tee_slope"] is not None and p["hr_slope"] is not None
                    and (p["tee_slope"] != p["hr_slope"]
                         or abs((p["tee_rating"] or 0) - p["hr_rating"]) > 0.05)):
                tee_mismatch += 1
                if len(tee_detail) < 15:
                    # Enough context to tell a front/back-nine rating pair
                    # from a genuinely stale tee row: which holes the tee
                    # row covers vs which nine was actually played.
                    rng = conn.execute(
                        """SELECT MIN(hole_number) AS lo, MAX(hole_number) AS hi
                           FROM course_tee_holes WHERE tee_id = ?""",
                        (p["tee_id"],)).fetchone()
                    played = [h["hole_number"] for h in holes
                              if h["strokes"] is not None]
                    tee_detail.append({
                        "player_name": p["player_name"],
                        "round_date": p["round_date"],
                        "course_name": p["course_name"],
                        "tee_name": p["tee_name"],
                        "round_slope_rating": f'{p["tee_slope"]}/{p["tee_rating"]}',
                        "gg_export_slope_rating": f'{p["hr_slope"]}/{p["hr_rating"]}',
                        "tee_holes": f'{rng["lo"]}-{rng["hi"]}' if rng and rng["lo"] else None,
                        "first_hole_played": min(played) if played else None,
                    })
            compared += 1
            our_diff = round((113.0 / p["hr_slope"]) * (adj - p["hr_rating"]), 1) \
                if p["hr_slope"] else None
            gg_diff = p["gg_diff"]
            if gg_diff is None and p["hr_slope"]:
                gg_diff = round((113.0 / p["hr_slope"]) * (p["gg_adj"] - p["hr_rating"]), 1)
            a_ok = (adj == p["gg_adj"])
            d_ok = (our_diff is not None and gg_diff is not None
                    and abs(our_diff - gg_diff) <= 0.05)
            if a_ok:
                adj_match += 1
            if d_ok:
                diff_match += 1
            if not (a_ok and d_ok):
                gross = int(p["gross"]) if p["gross"] is not None else None
                if not a_ok and gross is not None and p["gg_adj"] == gross and adj < gross:
                    fam_gg_is_gross += 1
                elif not a_ok and p["gg_adj"] < adj:
                    fam_gg_below += 1
                else:
                    fam_other += 1
                if len(mismatches) < 40:
                    mismatches.append({
                        "scoring_round_id": p["srid"], "handicap_round_id": p["hr_id"],
                        "player_name": p["player_name"], "round_date": p["round_date"],
                        "gross": gross,
                        "our_adjusted": adj, "gg_adjusted": p["gg_adj"],
                        "our_differential": our_diff, "gg_differential": gg_diff,
                        "gg_equals_gross": (gross is not None and p["gg_adj"] == gross),
                        "missing_par": bad_par,
                    })
        return {"pairs": len(pairs), "compared_9hole": compared,
                "adjusted_gross_match": adj_match,
                "differential_match": diff_match,
                "mismatch_families": {
                    # GG exported the raw gross (no NDB cap) while our WHS
                    # cap bound at least one hole — a POLICY difference,
                    # not a math bug (Kerry ruling pending on which is
                    # TGF's standard for self-derived differentials).
                    "gg_adjusted_equals_gross": fam_gg_is_gross,
                    # GG below our capped value — mis-bridged cards /
                    # different strokes-received allocation; per-case queue.
                    "gg_below_ours": fam_gg_below,
                    "other": fam_other,
                },
                "mismatches": mismatches,
                "skipped_18hole": n_18,
                "tee_data_mismatches": tee_mismatch,
                "tee_mismatch_detail": tee_detail,
                "rounds_with_missing_par": missing_par}


def get_scoring_handicap_preview(event_query: str,
                                 db_path: str | Path = DB_PATH) -> dict:
    """READ-ONLY preview of the handicap rounds we WOULD derive from our
    own scorecards for one event — the export-free path, shown before
    it's trusted (Kerry 2026-07-14). Writes nothing.

    For every 9-hole scoring round of the event, computes BOTH
    adjusted-gross variants side by side:
      * ndb  — WHS net double bogey cap through the formula layer
               (what our parity math does today)
      * raw  — uncapped gross (what GG's handicap export was observed
               to carry on the 2026 mismatch cluster)
    plus each player's current index and the index either variant would
    produce, so the admin can eyeball the real-world impact per player.
    Slope/rating come from the round's OWN tee row (captured from GG's
    tee block at scorecard import — per-round truth, immune to a course
    having front/back or re-rated tee variants under one name).

    Rows already bridged to a handicap_rounds record are flagged
    already_imported and carry GG's stored values for comparison; a real
    import would dedupe-skip them.
    """
    formulas = get_scoring_formulas(db_path=db_path)
    settings = get_handicap_settings(db_path)
    lookback_months = int(settings.get("lookback_months", 12))
    cutoff_str = (datetime.now()
                  - timedelta(days=lookback_months * 30.44)).strftime("%Y-%m-%d")
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        rounds = conn.execute(
            """SELECT sr.id AS srid, sr.player_name, sr.customer_id,
                      sr.round_date, sr.holes_played, sr.gross, sr.tee_id,
                      e.item_name AS event_name, c.name AS course_name,
                      ct.tee_name, ct.slope, ct.rating,
                      (SELECT hr.id FROM handicap_rounds hr
                       WHERE hr.scoring_round_id = sr.id LIMIT 1) AS hr_id
               FROM scoring_rounds sr
               JOIN events e ON e.id = sr.event_id
               LEFT JOIN courses c ON c.course_id = sr.course_id
               LEFT JOIN course_tees ct ON ct.tee_id = sr.tee_id
               WHERE e.item_name LIKE ?
               ORDER BY sr.player_name""",
            (f"%{event_query}%",)).fetchall()
        if not rounds:
            return {"error": f"no imported scoring rounds match event "
                             f"{event_query!r} — run the scorecard import first"}

        out_rows: list = []
        skipped_18 = 0
        cap_bound = already = 0
        events_seen: set = set()
        for r in rounds:
            events_seen.add(r["event_name"])
            if (r["holes_played"] or 0) > 9:
                skipped_18 += 1
                continue
            holes = conn.execute(
                """SELECT sh.strokes, sh.strokes_received, cth.par
                   FROM scoring_holes sh
                   LEFT JOIN course_tee_holes cth
                     ON cth.tee_id = ? AND cth.hole_number = sh.hole_number
                   WHERE sh.scoring_round_id = ?""",
                (r["tee_id"], r["srid"])).fetchall()
            adj_ndb = raw = capped = 0
            bad_par = False
            for h in holes:
                if h["strokes"] is None:
                    continue
                raw += h["strokes"]
                if h["par"] is None:
                    bad_par = True
                    adj_ndb += h["strokes"]
                    continue
                a = compute_hole_derivations(
                    h["par"], h["strokes"], h["strokes_received"] or 0,
                    formulas)["adjusted_strokes"]
                adj_ndb += a
                if a < h["strokes"]:
                    capped += 1

            flags = []
            if bad_par:
                flags.append("missing_par_holes")
            diff_ndb = diff_raw = None
            if r["slope"] and r["rating"] is not None:
                diff_ndb = round((adj_ndb - r["rating"]) * 113.0 / r["slope"], 1)
                diff_raw = round((raw - r["rating"]) * 113.0 / r["slope"], 1)
            else:
                flags.append("no_tee_slope_rating")

            # Existing differential pool: every handicap_rounds row for
            # this PERSON (all player_name variants linked to their
            # customer_id — stale duplicates exist; see export dedup),
            # within the lookback window, excluding a row already bridged
            # to this very card.
            names = {_normalize_player_name(r["player_name"])}
            if r["customer_id"]:
                for lk in conn.execute(
                        "SELECT player_name FROM handicap_player_links "
                        "WHERE customer_id = ?", (r["customer_id"],)).fetchall():
                    names.add(lk["player_name"])
            qmarks = ",".join("?" * len(names))
            hist = conn.execute(
                f"""SELECT round_date, differential FROM handicap_rounds
                    WHERE player_name IN ({qmarks})
                      AND differential IS NOT NULL
                      AND round_date >= ?
                      AND (scoring_round_id IS NULL OR scoring_round_id != ?)
                    ORDER BY round_date, id""",
                (*names, cutoff_str, r["srid"])).fetchall()
            pool = [h["differential"] for h in hist[-20:]]
            index_now = compute_handicap_index(pool, settings)

            def _with(new_diff):
                if new_diff is None:
                    return None
                merged = sorted(
                    [(h["round_date"], h["differential"]) for h in hist]
                    + [(r["round_date"], new_diff)])
                return compute_handicap_index(
                    [d for _, d in merged[-20:]], settings)

            is_imported = r["hr_id"] is not None
            if is_imported:
                already += 1
            if capped and diff_ndb != diff_raw:
                cap_bound += 1
            row = {
                "scoring_round_id": r["srid"],
                "player_name": _normalize_player_name(r["player_name"]),
                "customer_id": r["customer_id"],
                "event_name": r["event_name"],
                "round_date": r["round_date"],
                "course_name": r["course_name"], "tee_name": r["tee_name"],
                "slope": r["slope"], "rating": r["rating"],
                "gross": int(r["gross"]) if r["gross"] is not None else None,
                "adjusted_ndb": adj_ndb, "capped_holes": capped,
                "differential_ndb": diff_ndb, "differential_raw": diff_raw,
                "index_now": index_now,
                "index_after_ndb": _with(diff_ndb),
                "index_after_raw": _with(diff_raw),
                "prior_rounds_in_window": len(hist),
                "already_imported": is_imported,
                "flags": flags,
            }
            if is_imported:
                gg = conn.execute(
                    """SELECT adjusted_score, differential FROM handicap_rounds
                       WHERE id = ?""", (r["hr_id"],)).fetchone()
                row["gg_adjusted"] = gg["adjusted_score"]
                row["gg_differential"] = gg["differential"]
            out_rows.append(row)

        return {
            "event_query": event_query,
            "events_matched": sorted(events_seen),
            "rounds": out_rows,
            "summary": {
                "previewed": len(out_rows),
                "skipped_18hole": skipped_18,
                "already_imported": already,
                # rounds where the NDB-vs-raw policy choice actually
                # changes the differential — the judgment calls to show
                # the admin; everyone else is identical either way.
                "cap_changes_differential": cap_bound,
            },
            "note": "READ-ONLY preview — nothing written. differential_ndb "
                    "applies the WHS net-double-bogey cap; differential_raw "
                    "is uncapped gross (GG's export behavior on the 2026 "
                    "cluster). Which becomes TGF's standard needs Kerry's "
                    "ruling before any self-derived import ships.",
        }


def project_playing_handicaps(event_query: str, allowance: float = 1.0,
                              max_hcp: float | None = None,
                              db_path: str | Path = DB_PATH) -> dict:
    """Task #16 parity sweep — project each player's PLAYING HANDICAP and
    per-hole stroke allocation from OUR index + the SELECTED TEE, with NO
    Golf Genius input, and compare to what GG actually did. READ-ONLY.

    Per 9-hole round of the event:
      * our_index — the player's index the same way get_scoring_handicap_preview
        computes it (differential pool up to, and excluding, this round)
      * our_ch / our_ph — course & playing handicap from our_index + the
        round's own tee (slope/rating) and its par, via handicap_calc
      * two allocations, to separate the tee math from index differences:
          - alloc(gg_ph)   — allocate GG's OWN playing handicap; matching
            GG's stored dots proves the tee/stroke-index/allocation machinery
            independent of any index disagreement (the 100% target)
          - alloc(our_ph)  — the full self-contained chain
    Compares our_ph vs GG's imported playing_handicap and both allocations
    vs GG's stored per-hole strokes_received.

    allowance/max_hcp are the per-game hooks (default 100% / no cap = the
    base milestone Kerry wants ratified first).
    """
    from email_parser.handicap_calc import (
        course_handicap, playing_handicap, allocate_strokes)

    settings = get_handicap_settings(db_path)
    lookback_months = int(settings.get("lookback_months", 12))
    cutoff_str = (datetime.now()
                  - timedelta(days=lookback_months * 30.44)).strftime("%Y-%m-%d")

    rows_out: list = []
    events_seen: set = set()
    n_ph_exact = n_alloc_gg = n_full = n_rounds = 0
    skipped_18 = skipped_no_ph = skipped_no_tee = 0

    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        rounds = conn.execute(
            """SELECT sr.id AS srid, sr.player_name, sr.customer_id,
                      sr.round_date, sr.holes_played, sr.tee_id,
                      sr.playing_handicap AS gg_ph,
                      e.item_name AS event_name, ct.tee_name, ct.slope, ct.rating
               FROM scoring_rounds sr
               JOIN events e ON e.id = sr.event_id
               LEFT JOIN course_tees ct ON ct.tee_id = sr.tee_id
               WHERE e.item_name LIKE ?
               ORDER BY sr.player_name""",
            (f"%{event_query}%",)).fetchall()
        if not rounds:
            return {"error": f"no imported scoring rounds match event "
                             f"{event_query!r} — run the scorecard import first"}

        for r in rounds:
            events_seen.add(r["event_name"])
            if (r["holes_played"] or 0) > 9:
                skipped_18 += 1
                continue
            if not (r["slope"] and r["rating"] is not None):
                skipped_no_tee += 1
                continue

            holes = conn.execute(
                """SELECT sh.hole_number, sh.strokes, sh.strokes_received,
                          cth.par, cth.stroke_index
                   FROM scoring_holes sh
                   LEFT JOIN course_tee_holes cth
                     ON cth.tee_id = ? AND cth.hole_number = sh.hole_number
                   WHERE sh.scoring_round_id = ? AND sh.strokes IS NOT NULL""",
                (r["tee_id"], r["srid"])).fetchall()
            si_by_hole = {h["hole_number"]: h["stroke_index"] for h in holes
                          if h["stroke_index"] is not None}
            par9 = sum(h["par"] for h in holes if h["par"] is not None)
            gg_dots = {h["hole_number"]: (h["strokes_received"] or 0)
                       for h in holes}
            if not si_by_hole or not par9:
                skipped_no_tee += 1
                continue

            # our index at event time (pool excludes this round) — same as
            # the self-derived preview
            names = {_normalize_player_name(r["player_name"])}
            if r["customer_id"]:
                for lk in conn.execute(
                        "SELECT player_name FROM handicap_player_links "
                        "WHERE customer_id = ?", (r["customer_id"],)).fetchall():
                    names.add(lk["player_name"])
            qmarks = ",".join("?" * len(names))
            hist = conn.execute(
                f"""SELECT differential FROM handicap_rounds
                    WHERE player_name IN ({qmarks})
                      AND differential IS NOT NULL AND round_date >= ?
                      AND (scoring_round_id IS NULL OR scoring_round_id != ?)
                    ORDER BY round_date, id""",
                (*names, cutoff_str, r["srid"])).fetchall()
            pool = [h["differential"] for h in hist[-20:]]
            our_index = compute_handicap_index(pool, settings)

            n_rounds += 1
            our_ch = our_ph = None
            our_dots = alloc_gg = {}
            if our_index is not None:
                our_ch = round(course_handicap(our_index, r["slope"],
                                               r["rating"], par9), 2)
                our_ph = playing_handicap(our_index, r["slope"], r["rating"],
                                          par9, allowance=allowance,
                                          max_hcp=max_hcp)
                our_dots = allocate_strokes(our_ph, si_by_hole)
            gg_ph = int(r["gg_ph"]) if r["gg_ph"] is not None else None
            if gg_ph is None:
                skipped_no_ph += 1
            else:
                alloc_gg = allocate_strokes(gg_ph, si_by_hole)

            ph_exact = (our_ph is not None and gg_ph is not None
                        and our_ph == gg_ph)
            alloc_gg_match = (bool(alloc_gg)
                              and all(alloc_gg.get(h, 0) == gg_dots.get(h, 0)
                                      for h in si_by_hole))
            full_match = (bool(our_dots)
                          and all(our_dots.get(h, 0) == gg_dots.get(h, 0)
                                  for h in si_by_hole))
            if ph_exact:
                n_ph_exact += 1
            if alloc_gg_match:
                n_alloc_gg += 1
            if full_match:
                n_full += 1

            if not (ph_exact and alloc_gg_match and full_match):
                rows_out.append({
                    "player_name": _normalize_player_name(r["player_name"]),
                    "round_date": r["round_date"], "tee_name": r["tee_name"],
                    "slope": r["slope"], "rating": r["rating"], "par9": par9,
                    "our_index": our_index, "our_ch": our_ch,
                    "our_ph": our_ph, "gg_ph": gg_ph,
                    "ph_exact": ph_exact, "alloc_gg_match": alloc_gg_match,
                    "full_match": full_match,
                    "gg_dots": gg_dots,
                    "alloc_from_gg_ph": alloc_gg,
                    "alloc_from_our_ph": our_dots,
                })

    return {
        "event_query": event_query,
        "events_matched": sorted(events_seen),
        "allowance": allowance, "max_hcp": max_hcp,
        "summary": {
            "rounds_projected": n_rounds,
            "playing_hcp_exact": n_ph_exact,
            "alloc_matches_gg_dots_using_gg_ph": n_alloc_gg,
            "full_chain_matches_gg_dots": n_full,
            "skipped_18hole": skipped_18,
            "skipped_no_tee_or_par": skipped_no_tee,
            "skipped_no_gg_ph": skipped_no_ph,
        },
        "mismatches": rows_out,
        "note": "READ-ONLY. alloc_matches_gg_dots_using_gg_ph isolates the "
                "tee/stroke-index/allocation math from index differences — "
                "that is the 100% target. playing_hcp_exact additionally "
                "depends on our index equaling GG's (the separate index "
                "untether). Only non-perfect rounds are listed in mismatches.",
    }


def derive_handicap_rounds_from_scoring(event_query: str, dry_run: bool = True,
                                        db_path: str | Path = DB_PATH) -> dict:
    """Write handicap_rounds for one event from OUR scorecards — the
    export-free path. **Kerry-ratified 2026-07-14: WHS standards for
    adjusted gross** (net double bogey through the formula layer), after
    the GG Spreadsheet Composer exports for a9.17/s9.17 confirmed the
    export carries only the RAW gross (no adjusted column at all).

    dry_run=True (default) returns the plan without writing. Apply
    inserts one handicap_rounds row per eligible 9-hole scoring round:
    adjusted_score = WHS NDB adjusted gross, slope/rating from the
    round's own tee row, differential from those, scoring_round_id
    bridged at birth.

    Identity: reuses the customer's EXISTING handicap player_name (the
    variant with the most recent/most rounds — the export-dedup rule)
    so a self-derived row never splits a player's record under a new
    name spelling; falls back to the normalized scoring name and creates
    the handicap_player_links row when the player is brand new.

    Skips (listed, never written): 18-hole rounds, rounds missing tee
    slope/rating or holes pars, rounds already bridged to a handicap
    row, and rows whose import-dedup key (player, date, round_id=NULL,
    course, tee) already exists. CAVEAT: do NOT also import the GG
    export file for an event processed here — a file carrying round_ids
    would slip past the fallback dedup key and double-count the round.
    """
    preview = get_scoring_handicap_preview(event_query, db_path=db_path)
    if preview.get("error"):
        return preview
    plan: list = []
    skipped: list = []
    with _connect(db_path) as conn:
        for row in preview["rounds"]:
            why = None
            if row["already_imported"]:
                why = "already bridged to a handicap round"
            elif "no_tee_slope_rating" in row["flags"]:
                why = "no tee slope/rating on the round"
            elif "missing_par_holes" in row["flags"]:
                why = "course tee is missing hole pars"
            if why:
                skipped.append({"player_name": row["player_name"],
                                "scoring_round_id": row["scoring_round_id"],
                                "reason": why})
                continue

            # Reuse the existing handicap identity for this customer —
            # freshest-record variant wins (same rule as the CSV export
            # dedup) — so we extend the record instead of forking it.
            target_name = row["player_name"]
            if row["customer_id"]:
                best = conn.execute(
                    """SELECT l.player_name,
                              (SELECT MAX(hr.round_date) FROM handicap_rounds hr
                               WHERE hr.player_name = l.player_name) AS last_round,
                              (SELECT COUNT(*) FROM handicap_rounds hr
                               WHERE hr.player_name = l.player_name) AS n
                       FROM handicap_player_links l
                       WHERE l.customer_id = ?
                       ORDER BY last_round DESC, n DESC, l.player_name
                       LIMIT 1""", (row["customer_id"],)).fetchone()
                if best and best["n"]:
                    target_name = best["player_name"]

            dup = conn.execute(
                """SELECT id FROM handicap_rounds
                   WHERE player_name = ? AND round_date = ? AND round_id IS NULL
                     AND COALESCE(course_name,'') = COALESCE(?,'')
                     AND COALESCE(tee_name,'') = COALESCE(?,'')""",
                (target_name, row["round_date"], row["course_name"],
                 row["tee_name"])).fetchone()
            if dup:
                skipped.append({"player_name": target_name,
                                "scoring_round_id": row["scoring_round_id"],
                                "reason": f"dedup key already present (hr {dup['id']})"})
                continue
            plan.append({
                "player_name": target_name,
                "customer_id": row["customer_id"],
                "scoring_round_id": row["scoring_round_id"],
                "round_date": row["round_date"],
                "course_name": row["course_name"], "tee_name": row["tee_name"],
                "adjusted_score": row["adjusted_ndb"],
                "gross": row["gross"], "capped_holes": row["capped_holes"],
                "rating": row["rating"], "slope": row["slope"],
                "differential": row["differential_ndb"],
                "index_now": row["index_now"],
                "index_after": row["index_after_ndb"],
            })

        if not dry_run:
            for p in plan:
                conn.execute(
                    """INSERT INTO handicap_rounds
                       (player_name, round_date, round_id, course_name, tee_name,
                        adjusted_score, rating, slope, differential, scoring_round_id)
                       VALUES (?, ?, NULL, ?, ?, ?, ?, ?, ?, ?)""",
                    (p["player_name"], p["round_date"], p["course_name"],
                     p["tee_name"], p["adjusted_score"], p["rating"],
                     p["slope"], p["differential"], p["scoring_round_id"]))
                # brand-new player: create the link so the handicap card
                # and GG-export paths can resolve them to the customer
                if not conn.execute(
                        "SELECT 1 FROM handicap_player_links WHERE player_name = ?",
                        (p["player_name"],)).fetchone():
                    cname = None
                    if p["customer_id"]:
                        c = conn.execute(
                            """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                                       COALESCE(last_name,'')) AS nm
                               FROM customers WHERE customer_id = ?""",
                            (p["customer_id"],)).fetchone()
                        cname = (c["nm"] or "").strip() or None
                    conn.execute(
                        """INSERT INTO handicap_player_links
                           (player_name, customer_name, customer_id)
                           VALUES (?, ?, ?)""",
                        (p["player_name"], cname, p["customer_id"]))
            conn.commit()
            logger.info("Self-derived %d handicap rounds for %r (WHS NDB, "
                        "Kerry-ratified 2026-07-14)", len(plan), event_query)

    if not dry_run:
        # Record the played side on the rounds just derived (bridged to their
        # card, so the side resolves cleanly). Non-fatal.
        try:
            persist_handicap_round_nines(dry_run=False, db_path=db_path)
        except Exception:
            logger.exception("Non-fatal: persist_handicap_round_nines after derive failed")

    # Manager recap email per posting (Kerry 2026-07-29: "auto send manager
    # handicap reports for each chapter after each posting"). Non-fatal —
    # a mail hiccup must never roll back or mask a successful posting.
    recap = None
    if not dry_run and plan:
        try:
            recap = send_handicap_recap_email(
                (preview["events_matched"] or [event_query])[0],
                plan, db_path=db_path)
        except Exception:
            logger.exception("Non-fatal: handicap recap email failed")
            recap = {"ok": False, "error": "exception (see logs)"}

    return {"event_query": event_query,
            "events_matched": preview["events_matched"],
            "dry_run": dry_run,
            "would_write" if dry_run else "written": plan,
            "skipped": skipped,
            "recap_email": recap,
            "summary": {"planned": len(plan), "skipped": len(skipped),
                        "cap_changes_differential":
                            preview["summary"]["cap_changes_differential"]},
            "standard": "WHS net double bogey adjusted gross "
                        "(Kerry-ratified 2026-07-14)"}


def _handicap_recap_recipient(conn, chapter: str) -> str | None:
    """Recipient for a chapter's handicap recap — rules-as-data:
    app_setting 'hcp_recap_email_<slug>' (hcp_recap_email_austin /
    hcp_recap_email_san_antonio), then 'hcp_recap_email_default', then
    env COO_EMAIL_TO, then EMAIL_ADDRESS (the owner's inbox). Values may
    be comma-separated lists (send_mail_graph splits them)."""
    import os as _os
    slug = re.sub(r"[^a-z0-9]+", "_", (chapter or "").strip().lower()).strip("_")
    keys = ([f"hcp_recap_email_{slug}"] if slug else []) + ["hcp_recap_email_default"]
    for key in keys:
        try:
            row = conn.execute(
                "SELECT value FROM app_settings WHERE key = ?", (key,)).fetchone()
            if row and (row["value"] or "").strip():
                return row["value"].strip()
        except Exception:
            pass
    return ((_os.getenv("COO_EMAIL_TO") or "").strip()
            or (_os.getenv("EMAIL_ADDRESS") or "").strip() or None)


def send_handicap_recap_email(event_label: str, written: list,
                              db_path: str | Path | None = None) -> dict:
    """Email the chapter manager a recap of one handicap posting — the
    same shape as the chat recap Kerry approved 2026-07-29: header
    (event / course / date / standard), biggest index movers up top,
    then the full per-player table (gross, NDB-adjusted, differential,
    index before -> after). Fired automatically by
    derive_handicap_rounds_from_scoring(apply); safe to call manually.
    Returns {ok, sent_to, chapter, players} without ever raising."""
    import os as _os
    from email_parser.fetcher import send_mail_graph
    if not written:
        return {"ok": False, "error": "nothing written — no recap to send"}
    with _connect(db_path) as conn:
        chapter = None
        row = conn.execute(
            """SELECT e.chapter FROM scoring_rounds sr
               JOIN events e ON e.id = sr.event_id
               WHERE sr.id = ? LIMIT 1""",
            (written[0]["scoring_round_id"],)).fetchone()
        if row:
            chapter = (row["chapter"] or "").strip() or None
        to_address = _handicap_recap_recipient(conn, chapter or "")
    if not to_address:
        return {"ok": False, "error": "no recipient configured", "chapter": chapter}
    tenant_id = _os.getenv("AZURE_TENANT_ID")
    client_id = _os.getenv("AZURE_CLIENT_ID")
    client_secret = _os.getenv("AZURE_CLIENT_SECRET")
    from_address = _os.getenv("EMAIL_ADDRESS")
    if not all([tenant_id, client_id, client_secret, from_address]):
        return {"ok": False, "error": "email not configured on server"}

    course = written[0].get("course_name") or ""
    rdate = written[0].get("round_date") or ""

    def _fi(v):
        # A brand-new player has no prior index (None) — show a dash.
        return f"{v:.1f}" if v is not None else "&mdash;"

    def _fx(v):
        # Index values carry the "N" suffix — TGF indexes are 9-hole
        # indexes (Kerry 2026-08-03). Differentials stay bare.
        return f"{v:.1f}N" if v is not None else "&mdash;"

    from urllib.parse import quote as _q

    def _plink(name):
        # Names link to the member handicap page with the player pinned to
        # the top and their rounds expanded (Kerry 2026-08-03).
        return (f'<a href="https://tgf-tracker.up.railway.app/member/handicaps'
                f'?player={_q(name)}" style="color:#2563eb;text-decoration:none;">'
                f'{name}</a>')

    def _delta(p):
        if p.get("index_after") is None or p.get("index_now") is None:
            return None
        return round(p["index_after"] - p["index_now"], 1)

    rows = sorted(written, key=lambda p: (_delta(p) if _delta(p) is not None
                                          else 99.0, p["player_name"]))
    # One entry per PLAYER for the movers lines — a two-nine posting has
    # two rows with the same before/after index and would list twice.
    _seen_names: set = set()
    uniq = [p for p in rows
            if not (p["player_name"] in _seen_names
                    or _seen_names.add(p["player_name"]))]
    movers_dn = [p for p in uniq if (_delta(p) or 0) <= -0.4]
    movers_up = [p for p in uniq if (_delta(p) or 0) >= 0.4]
    capped_n = sum(1 for p in rows if p.get("capped_holes"))

    def _mover_line(players):
        return ", ".join(
            f"{_plink(p['player_name'])} {_fx(p['index_now'])} &rarr; "
            f"<b>{_fx(p['index_after'])}</b>" for p in players)

    # One block per PLAYER (Kerry 2026-08-03: "listed the name only once
    # and the final Index and change only once"): a two-nine posting shows
    # two side rows (Front/Back) under one name, with the index and change
    # spanning both. Single-round postings keep one row; the SIDE column
    # only renders when a posting actually has sides.
    def _side(p):
        t = p.get("tee_name") or ""
        return "Front" if "Front 9" in t else ("Back" if "Back 9" in t else "")

    has_side = any(_side(p) for p in rows)
    groups: dict = {}
    order: list = []
    for p in rows:
        if p["player_name"] not in groups:
            order.append(p["player_name"])
        groups.setdefault(p["player_name"], []).append(p)

    trs = []
    for name in order:
        grp = sorted(groups[name], key=lambda p: 0 if _side(p) == "Front" else 1)
        n = len(grp)
        first = grp[0]
        delta = _delta(first)
        if delta is None:
            arrow = '<span style="color:#9CA3AF;">new</span>'
        elif delta < 0:
            arrow = f'<span style="color:#15803D;">&#9660; {abs(delta):.1f}</span>'
        elif delta > 0:
            arrow = f'<span style="color:#B45309;">&#9650; {delta:.1f}</span>'
        else:
            arrow = '<span style="color:#9CA3AF;">&mdash;</span>'
        span_td = ('style="padding:4px 10px;border-bottom:1px solid #E5E7EB;'
                   'vertical-align:top;"')
        for i, p in enumerate(grp):
            cap = " &dagger;" if p.get("capped_holes") else ""
            # inner rows of a group get a lighter divider so the block
            # reads as one player
            bb = "#E5E7EB" if i == n - 1 else "#F3F4F6"
            row_td = (f'style="padding:4px 10px;border-bottom:1px solid {bb};'
                      f'text-align:right;"')
            cells = []
            if i == 0:
                name_cap = "" if has_side else cap
                cells.append(f'<td rowspan="{n}" {span_td}>{_plink(name)}{name_cap}</td>')
            if has_side:
                cells.append(
                    f'<td style="padding:4px 10px;border-bottom:1px solid {bb};">'
                    f'{_side(p)}{cap}</td>')
            cells.append(f'<td {row_td}>{p["gross"]}</td>')
            cells.append(f'<td {row_td}>{p["adjusted_score"]}</td>')
            cells.append(f'<td {row_td}>{_fi(p.get("differential"))}</td>')
            if i == 0:
                cells.append(
                    f'<td rowspan="{n}" {span_td.replace("vertical-align:top;", "text-align:right;white-space:nowrap;vertical-align:top;")}>'
                    f'{_fx(first["index_now"])} &rarr; <b>{_fx(first["index_after"])}</b></td>')
                cells.append(
                    f'<td rowspan="{n}" {span_td.replace("vertical-align:top;", "text-align:right;vertical-align:top;")}>'
                    f'{arrow}</td>')
            trs.append(f'<tr>{"".join(cells)}</tr>')

    movers_html = ""
    if movers_dn:
        movers_html += (f'<p style="margin:4px 0;"><b style="color:#15803D;">'
                        f'Down:</b> {_mover_line(movers_dn)}</p>')
    if movers_up:
        movers_html += (f'<p style="margin:4px 0;"><b style="color:#B45309;">'
                        f'Up:</b> {_mover_line(movers_up)}</p>')
    if not movers_html:
        movers_html = '<p style="margin:4px 0;">No index moved more than 0.3.</p>'

    chapter_label = chapter or "TGF"
    subject = (f"TGF Handicap Update — {event_label}"
               f" ({chapter_label}) — {len(rows)} rounds posted")
    html = f"""
    <div style="font-family:-apple-system,'Helvetica Neue',Arial,sans-serif;color:#1B1B1B;max-width:640px;">
      <h2 style="margin:0 0 2px;">Handicap Update — {event_label}</h2>
      <p style="margin:0 0 12px;color:#6B7280;">{course} &middot; {rdate} &middot; {chapter_label}
         &middot; {len(rows)} rounds posted</p>
      <h3 style="margin:12px 0 4px;">Biggest movers</h3>
      {movers_html}
      <h3 style="margin:16px 0 4px;">All rounds</h3>
      <table style="border-collapse:collapse;font-size:13px;width:100%;">
        <thead><tr style="text-align:right;color:#6B7280;">
          <th style="text-align:left;padding:4px 10px;">Player</th>
          {'<th style="text-align:left;padding:4px 10px;">Side</th>' if has_side else ''}
          <th style="padding:4px 10px;">Gross</th>
          <th style="padding:4px 10px;">Adj</th>
          <th style="padding:4px 10px;">Diff</th>
          <th style="padding:4px 10px;">9-Hole Index</th>
          <th style="padding:4px 10px;">&Delta;</th>
        </tr></thead>
        <tbody>{''.join(trs)}</tbody>
      </table>
      <p style="margin:14px 0 0;color:#6B7280;font-size:12px;">
        Standard: WHS net double bogey adjusted gross (ratified 2026-07-14).
        {f'&dagger; {capped_n} round{"s" if capped_n != 1 else ""} had a hole capped to net double bogey.' if capped_n else ''}
        New differentials are live — next event's playing handicaps project off these.
      </p>
    </div>"""

    ok = send_mail_graph(tenant_id=tenant_id, client_id=client_id,
                         client_secret=client_secret,
                         from_address=from_address, to_address=to_address,
                         subject=subject, html_body=html)
    logger.info("Handicap recap for %r (%s) -> %s: %s", event_label,
                chapter_label, to_address, "sent" if ok else "FAILED")
    return {"ok": bool(ok), "sent_to": to_address, "chapter": chapter_label,
            "players": len(rows)}


def build_player_snapshot_email(customer_id: int,
                                to_address: str | None = None,
                                send: bool = False,
                                db_path: str | Path | None = None) -> dict:
    """YOUR TGF SNAPSHOT — the personalized member email (Kerry
    2026-08-03: 'clean and totally about them', sharp, NO bait; 'anyone
    within 15 points of first has a very realistic chance').

    The story it tells is the Points Reset (Kerry: the reset is TGF's
    Tour Championship — it puts ~30 players within possible range of
    winning it all, and Mark Freund's 2024 run is the proof of concept:
    30th on the seeded board when championship weekend started, 14.5
    back, won the Fellowship Cup by 2.5, passing all 29 players ahead
    of him — verified off the tgf-champ24 GG portal 2026-08-03).

    Every number comes from the live spotlight payload — nothing is
    hand-typed. MOCK PHASE: sends only to `to_address` (or the admin
    recap recipient when omitted) — NEVER to the player. Member sends
    are a Kerry rule-3b ratification away.
    """
    import os as _os

    spot = get_player_spotlight(customer_id,
                                db_path=db_path or DB_PATH)
    if spot.get("error"):
        return {"ok": False, "error": spot["error"]}
    name = spot.get("name") or spot.get("player_name") or ""
    first_name = (name.split() or [""])[0]
    chapter = spot.get("chapter") or ""

    # Feature race: the CUP the player is closest to the lead in
    # (enrolled first; the hypothetical path only if they're in neither)
    cup_keys = ("fellowship_cup", "players_cup_gross")
    cups = [r for r in spot.get("races", [])
            if r.get("key") in cup_keys and r.get("points_back") is not None]
    enrolled_cups = [r for r in cups if r.get("enrolled")]
    feature = min(enrolled_cups or cups, key=lambda r: r["points_back"],
                  default=None)
    if feature is None:
        return {"ok": False,
                "error": "player appears on no cup board — no story to tell"}

    def n1(v):
        # 100.0 -> "100", 99.5 -> "99.5"
        return f"{v:g}" if v is not None else "—"

    from .timezone_utils import today_central
    today_lbl = today_central().strftime("%B %-d, %Y")
    idx18 = spot.get("handicap_index_18")
    idx9 = round(idx18 / 2, 1) if idx18 is not None else None

    back = max(feature["points_back"], 0)
    lead = feature.get("leader_points")
    within = feature.get("n_within_15")
    rank = feature.get("rank")
    npl = feature.get("n_players")
    seed = feature.get("points_reset") if feature.get(
        "points_reset") is not None else feature.get("total_points")

    ORANGE, DARK, NAVY, MUTE = "#E87C3E", "#1B1B1B", "#002868", "#6B7280"
    serif = "font-family:Georgia,'Times New Roman',serif;"
    sans = "font-family:-apple-system,'Helvetica Neue',Arial,sans-serif;"

    # WHERE YOU STAND (Kerry 2026-08-03 v2): the city Net race is DONE —
    # it renders as a FINAL result (finish, points total, what the Points
    # Reset converted to) as the lead-in; then THE FELLOWSHIP CUP
    # standings immediately after, THE PLAYERS CUP last. A player who
    # hasn't bought in still sees where they'd stand — that IS the
    # snapshot's point for them — with a muted "not entered" tag.
    races_all = spot.get("races", [])
    # Every standings mention deep-links to that live board on the member
    # Leaderboard page — the hash handler centers the player's row and
    # pulses it, same as the Spotlight links (Kerry 2026-08-03).
    _TAB_OF = {"san_antonio_net": "net", "austin_net": "austin",
               "fellowship_cup": "tfc", "players_cup_gross": "gross"}

    def _board_link(key):
        t = _TAB_OF.get(key)
        return (f"https://tgf-tracker.up.railway.app/member/contests"
                f"#race={t}&player={customer_id}") if t else None

    def _linked(key, label):
        u = _board_link(key)
        return (f'<a href="{u}" style="color:inherit;text-decoration:underline;text-decoration-color:#CBD5E1;text-underline-offset:2px;">{label}</a>'
                if u else label)

    city = next((r for r in races_all
                 if str(r.get("key", "")).endswith("_net")
                 and (r.get("enrolled") or r.get("points_back") is not None)),
                None)
    # The city NET reset carries ONLY into THE FELLOWSHIP CUP; THE
    # PLAYERS CUP ran its OWN Points Reset and flights (Kerry 2026-08-03)
    # — the lead-in names the Fellowship Cup specifically and the Players
    # Cup row shows its own reset + the player's flight.
    city_html = ""
    if city and city.get("rank") is not None:
        city_html = f"""
      <div style="border:1px solid #E5E7EB;border-left:4px solid {DARK};border-radius:0 8px 8px 0;padding:10px 14px;margin:0 0 14px;{sans}font-size:13px;line-height:1.5;">
        <div style="{serif}font-size:11px;letter-spacing:0.12em;text-transform:uppercase;color:{MUTE};margin-bottom:3px;">{_linked(city.get('key'), city.get('label', ''))} — Final</div>
        You finished <b>{city.get('rank')} of {city.get('n_players')}</b> with <b>{n1(city.get('total_points'))} points</b> — converting to a <b>{n1(city.get('points_reset'))} Points Reset</b> seed carried into {_linked('fellowship_cup', 'THE FELLOWSHIP CUP')} below.
      </div>"""
    stand_rows = ""
    for k in ("fellowship_cup", "players_cup_gross"):
        r = next((x for x in races_all if x.get("key") == k), None)
        if not r or (not r.get("enrolled") and r.get("points_back") is None):
            continue
        pb = r.get("points_back")
        tag = ("" if r.get("enrolled") else
               f' <span style="font-size:10px;color:{MUTE};font-weight:400;">(not entered)</span>')
        if k == "players_cup_gross":
            _fl = (r.get("flight") or "").strip()
            tag += (f' <span style="font-size:10px;color:{MUTE};font-weight:400;">'
                    f'(own reset{" · " + _fl if _fl else ""})</span>')
        stand_rows += f"""
        <tr>
          <td style="padding:7px 10px;border-bottom:1px solid #E5E7EB;font-weight:700;">{_linked(k, r.get('label', ''))}{tag}</td>
          <td style="padding:7px 10px;border-bottom:1px solid #E5E7EB;text-align:center;white-space:nowrap;">{r.get('rank', '—')} of {r.get('n_players', '—')}</td>
          <td style="padding:7px 10px;border-bottom:1px solid #E5E7EB;text-align:center;font-weight:700;">{n1(r.get('points_reset') if r.get('points_reset') is not None else r.get('total_points'))}</td>
          <td style="padding:7px 10px;border-bottom:1px solid #E5E7EB;text-align:center;color:{'#15803D' if pb == 0 else DARK};white-space:nowrap;">{'leader' if pb == 0 else (f'{n1(pb)} back' if pb is not None else '—')}</td>
        </tr>"""
    _pc_row = next((x for x in races_all
                    if x.get("key") == "players_cup_gross"), None)
    stand_html = city_html + (f"""
      <table style="border-collapse:collapse;width:100%;font-size:13px;{sans}">
        <thead><tr style="color:{MUTE};font-size:11px;text-transform:uppercase;letter-spacing:0.04em;">
          <th style="text-align:left;padding:4px 10px;">Race</th>
          <th style="padding:4px 10px;">Place</th>
          <th style="padding:4px 10px;">Points</th>
          <th style="padding:4px 10px;">Off the lead</th>
        </tr></thead>
        <tbody>{stand_rows}</tbody>
      </table>""" + (f"""
      <div style="font-size:11px;color:{MUTE};margin:4px 0 0;padding:0 10px;">THE PLAYERS CUP runs its own Points Reset and flights — the city Net reset feeds THE FELLOWSHIP CUP only.</div>"""
                     if _pc_row and (_pc_row.get("enrolled")
                                     or _pc_row.get("points_back") is not None)
                     else "") if stand_rows else "")

    # LONE STAR CUP line — factual, same modes as the Spotlight. For the
    # hunt/hypothetical modes it measures from the SEAT LINE on each cup
    # path (Kerry 2026-08-03: "making your city's Lone Star Cup team is
    # an even lower bar. Measuring from that on either the Fellowship or
    # Players Cup would be really good").
    lsc = spot.get("lone_star_cup") or {}

    def _seat_line(p):
        gap, cut = p.get("gap_to_seat"), p.get("seat_cut_points")
        _pk = ("fellowship_cup" if "FELLOWSHIP" in (p.get("path") or "")
               else "players_cup_gross")
        _pl = (f'<a href="{_board_link(_pk)}" style="color:#fff;text-decoration:underline;text-decoration-color:#9DB4D6;text-underline-offset:2px;"><b>{p.get("path", "")}</b></a>')
        if gap is None:
            return (f"{_pl} path: spot "
                    f"{p.get('place')} for {p.get('seats')} seats.")
        if gap >= 0:
            return (f"{_pl} path: you'd be <b>inside "
                    f"the seat line</b> — spot {p.get('place')} of "
                    f"{p.get('seats')}, {n1(gap)} clear of the cut.")
        # Translate a small gap into golf (Kerry 2026-08-03: "you're 1
        # point from... is equal to one net bogey in the TGF
        # Championship!") — a net bogey scores 1 point, so the gap IS a
        # hole count at championship scoring.
        k = -gap
        if k <= 1:
            kick = " That's <b>one net bogey</b> at the TGF Championship."
        elif k <= 4:
            import math as _m
            kick = (f" That's <b>{_m.ceil(k)} net bogeys</b> at the TGF "
                    "Championship — a couple of holes.")
        else:
            kick = ""
        return (f"{_pl} path: the last seat sits at "
                f"{n1(cut)} — you're <b>{n1(-gap)} "
                f"point{'' if abs(gap) == 1 else 's'} from a seat</b>.{kick}")

    def _seat_lines():
        paths = lsc.get("paths") or []
        lines = "".join(f'<div style="margin:3px 0;">{_seat_line(p)}</div>'
                        for p in paths)
        lead = ("Winning it all isn't the only prize — making your city's "
                "Lone Star Cup team is an even lower bar, and you're "
                "already knocking:"
                if lsc.get("mode") == "hypothetical" else
                "Winning the cup isn't the only prize — your city's Lone "
                "Star Cup seats run through these same standings:")
        return f"{lead}{lines}" if lines else None

    lsc_bits = {
        "seat": lambda: ("Your current Lone Star Cup projection: "
                         f"<b>{lsc.get('seat', 'a seat')}</b>"
                         + (" — <b>secured</b>." if lsc.get("status") == "secured"
                            else ". Projections move until selection day —"
                                 " every fall point defends it.")),
        "alternate": lambda: ("You currently project as "
                              f"<b>alternate #{lsc.get('alternate_rank')}</b> "
                              "for the Lone Star Cup — one seat away."),
        "in_hunt": _seat_lines,
        "hypothetical": _seat_lines,
    }.get(lsc.get("mode"))
    lsc_text = lsc_bits() if lsc_bits else None
    lsc_html = (f"""
      <div style="background:{NAVY};color:#fff;border-radius:8px;padding:12px 16px;margin:18px 0 0;{sans}font-size:13px;line-height:1.5;">
        <div style="{serif}font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:#9DB4D6;margin-bottom:3px;">Lone Star Cup</div>
        {lsc_text}
      </div>""" if lsc_text else "")

    # WAYS IN (Kerry 2026-08-03): direct buy-in links + what's actually
    # purchasable now that City Net is over — The Fellowship Cup by
    # itself ($50, Kerry-stated), The Players Cup ($50), and the Fall
    # City Points Race ($50, Best 6 + Fall Championship — its own race,
    # does NOT feed the TGF Championship or Lone Star Cup). Rendered
    # only for players not bought into both cups.
    SHOP = "https://thegolffellowship.com/shop/ols/products/season-contests"
    in_fc = any(r.get("key") == "fellowship_cup" and r.get("enrolled")
                for r in races_all)
    in_pc = any(r.get("key") == "players_cup_gross" and r.get("enrolled")
                for r in races_all)
    ways_html = ""
    if not (in_fc and in_pc):
        opts = []
        if not in_fc:
            opts.append("<b>The Fellowship Cup — $50.</b> City Net is "
                        "done, so you can now buy the Cup by itself — your "
                        "reset seed above is waiting on it.")
        if not in_pc:
            opts.append("<b>The Players Cup — $50.</b> The gross-points "
                        "path to the same weekend.")
        opts.append("<b>Fall City Points Race — $50.</b> Best 6 + Fall "
                    "Championship. Its own race and its own money — it "
                    "doesn't feed the TGF Championship or Lone Star Cup, "
                    "but it's another way to compete this fall.")
        _lis = "".join(f'<div style="margin:4px 0;">• {o}</div>' for o in opts)
        ways_html = f"""
      <div style="border-left:4px solid {ORANGE};background:#FDF0E6;border-radius:0 8px 8px 0;padding:12px 16px;margin:18px 0 0;{sans}font-size:13px;line-height:1.5;">
        <div style="{serif}font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:#9A5B2E;margin-bottom:4px;">Ways in</div>
        {_lis}
        <div style="margin-top:10px;"><a href="{SHOP}" style="background:{ORANGE};color:#fff;text-decoration:none;font-weight:700;padding:8px 20px;border-radius:9999px;{serif}font-size:12.5px;letter-spacing:0.04em;">BUY IN NOW</a></div>
      </div>"""

    # THE WEEKEND SELL (Kerry 2026-08-03): entering the points race is
    # only half the ask — they need to BE at the TGF Championship. When a
    # fall championship event is posted and this player isn't signed up
    # or RSVP'd, sell the weekend itself: TGF's two best experiences,
    # family-friendly getaways — with the direct signup link. No event
    # posted yet → no section.
    CHAMP_SHOP = ("https://thegolffellowship.com/shop/ols/products/"
                  "2026-tgf-championship")
    weekend_html = ""
    _needs_champ_signup = False
    try:
        with _connect(db_path) as conn:
            _evs, _champ_cids, _ = _tgf_champ_signups(conn)
        if _evs is not None and customer_id not in _champ_cids:
            _needs_champ_signup = True
            _ev0 = _evs[0]
            _evbit = " · ".join(x for x in (
                _ev0.get("item_name"), _ev0.get("event_date")) if x)
            weekend_html = f"""
      <div style="border:1px solid #E5E7EB;border-radius:8px;padding:14px 18px;margin:18px 0 0;{sans}font-size:14px;line-height:1.55;">
        <div style="{serif}font-size:15px;font-weight:700;margin-bottom:6px;">Be there for the weekend itself.</div>
        <p style="margin:0 0 8px;">The TGF Championship and the Lone Star Cup are, hands down, the two best weekends TGF puts on — our top two experiences of the year. Great courses, the whole fellowship in one place, families welcome, a proper getaway. You don't have to win it all for it to be worth it — plenty of players place in the money. But you do have to be there.</p>
        <p style="margin:0 0 10px;font-size:12px;color:{MUTE};">You're not signed up yet{f" — {_evbit}" if _evbit else ""}.</p>
        <a href="{CHAMP_SHOP}" style="background:{DARK};color:#fff;text-decoration:none;font-weight:700;padding:8px 20px;border-radius:9999px;{serif}font-size:12.5px;letter-spacing:0.04em;">SIGN UP FOR THE TGF CHAMPIONSHIP</a>
      </div>"""
    except Exception:
        pass

    _lbl = feature.get("label", "")
    _race = _lbl if _lbl.upper().startswith("THE ") else f"the {_lbl}"
    story_lead = (
        f"First place carries <b>{n1(lead)}</b> into the fall. You carry "
        f"<b>{n1(seed)}</b> — <b>{n1(back)} "
        f"point{'' if back == 1 else 's'} off the lead</b> in "
        f"{_race}"
        if back else
        f"You lead {_race} at <b>{n1(seed)}</b> — "
        "and the reset means everyone behind you is still in range")
    within_line = (
        f"Right now <b>{within} players</b> sit within 15 points of the "
        "lead. That's the design — the same thing the Tour Championship "
        "does on the PGA: bring the field back within reach, then let the "
        "fall decide it." if within else "")

    subject = (f"Your TGF Snapshot — {n1(back)} "
               f"point{'' if back == 1 else 's'} off the lead"
               if back else f"Your TGF Snapshot — you're the one they're chasing")

    # IMMEDIATE CTA under WHERE YOU STAND (Kerry 2026-08-03: "Needs to be
    # an immediate CTA button after the Where you stand summary"): the
    # single most relevant next action — buy in if they're outside a cup,
    # else the TGF Championship signup if they still need it.
    if not (in_fc and in_pc):
        early_cta = f'''
        <div style="text-align:center;margin:14px 0 4px;">
          <a href="{SHOP}" style="background:{ORANGE};color:#fff;text-decoration:none;font-weight:700;padding:10px 24px;border-radius:9999px;{serif}font-size:13px;letter-spacing:0.04em;">BUY IN NOW</a>
        </div>'''
    elif _needs_champ_signup:
        early_cta = f'''
        <div style="text-align:center;margin:14px 0 4px;">
          <a href="{CHAMP_SHOP}" style="background:{DARK};color:#fff;text-decoration:none;font-weight:700;padding:10px 24px;border-radius:9999px;{serif}font-size:13px;letter-spacing:0.04em;">SIGN UP FOR THE TGF CHAMPIONSHIP</a>
        </div>'''
    else:
        early_cta = ""

    # Header (Kerry 2026-08-03): TGF logo mark on the LEFT (hosted PNG —
    # email clients don't render SVG), "YOUR TGF SNAPSHOT" as the small
    # eyebrow, and the PLAYER'S NAME as the big line.
    LOGO = "https://tgf-tracker.up.railway.app/static/icon-180.png"
    html = f"""
    <div style="{sans}color:{DARK};max-width:620px;margin:0 auto;">
      <div style="background:{DARK};border-radius:10px 10px 0 0;padding:20px 26px 18px;">
        <table style="border-collapse:collapse;" role="presentation"><tr>
          <td style="vertical-align:middle;padding-right:16px;"><img src="{LOGO}" alt="TGF" width="48" height="48" style="display:block;border-radius:10px;"></td>
          <td style="vertical-align:middle;">
            <div style="{serif}color:{ORANGE};font-size:11px;letter-spacing:0.18em;text-transform:uppercase;margin-bottom:3px;">Your TGF Snapshot</div>
            <div style="{serif}color:#fff;font-size:28px;font-weight:700;line-height:1.1;">{name}</div>
            <div style="color:#B9B7B2;font-size:13px;margin-top:4px;">{chapter} &middot; {today_lbl}</div>
          </td>
        </tr></table>
      </div>
      <div style="border:1px solid #E5E7EB;border-top:0;border-radius:0 0 10px 10px;padding:22px 26px 26px;">
        {f'<div style="margin:0 0 16px;font-size:13px;color:{MUTE};">9-Hole Index <b style="color:{DARK};font-size:16px;">{idx9}N</b></div>' if idx9 is not None else ''}
        <div style="{serif}font-size:15px;font-weight:700;margin:0 0 8px;">Where you stand</div>
        {stand_html}
        {early_cta}
        <div style="border-left:4px solid {ORANGE};background:#FDF0E6;border-radius:0 8px 8px 0;padding:14px 18px;margin:20px 0 0;font-size:14px;line-height:1.55;">
          <div style="{serif}font-size:15px;font-weight:700;margin-bottom:6px;">The reset just put you in it, {first_name}.</div>
          <p style="margin:0 0 10px;">{story_lead} — with the whole fall season and the TGF Championship still to play.</p>
          {f'<p style="margin:0 0 10px;">{within_line}</p>' if within_line else ''}
          <p style="margin:0 0 10px;">A championship weekend where you simply shoot your handicap is worth roughly <b>72 points</b> on its own. The math is not against you. The math is the invitation.</p>
          <p style="margin:0;">And it's been done. In 2024, Mark Freund started championship weekend <b>30th on the reset board — dead last among the seeds, 14.5 points back</b>. He won the Fellowship Cup by 2.5, passing all 29 players ahead of him.</p>
        </div>
        {lsc_html}
        {ways_html}
        {weekend_html}
        <div style="text-align:center;margin:24px 0 4px;">
          <a href="https://tgf-tracker.up.railway.app/member/spotlight?player={customer_id}"
             style="background:{ORANGE};color:#fff;text-decoration:none;font-weight:700;padding:11px 26px;border-radius:9999px;{serif}font-size:14px;letter-spacing:0.04em;">SEE YOUR FULL SPOTLIGHT</a>
        </div>
        <p style="text-align:center;color:{MUTE};font-size:11px;margin:14px 0 0;">
          Every number above is live from the TGF Tracker as of {today_lbl}.
        </p>
      </div>
    </div>"""

    result = {"ok": True, "player": name, "customer_id": customer_id,
              "feature_race": feature.get("key"), "points_back": back,
              "n_within_15": within, "rank": f"{rank} of {npl}",
              "subject": subject, "html_chars": len(html), "sent": False}
    if not send:
        result["preview"] = html
        return result

    with _connect(db_path) as conn:
        to = (to_address or "").strip() or _handicap_recap_recipient(conn, "")
    if not to:
        return {**result, "ok": False, "error": "no recipient configured"}
    tenant_id = _os.getenv("AZURE_TENANT_ID")
    client_id = _os.getenv("AZURE_CLIENT_ID")
    client_secret = _os.getenv("AZURE_CLIENT_SECRET")
    from_address = _os.getenv("EMAIL_ADDRESS")
    if not all([tenant_id, client_id, client_secret, from_address]):
        return {**result, "ok": False, "error": "email not configured on server"}
    from email_parser.fetcher import send_mail_graph
    ok = send_mail_graph(tenant_id=tenant_id, client_id=client_id,
                         client_secret=client_secret,
                         from_address=from_address, to_address=to,
                         subject=subject, html_body=html)
    logger.info("Snapshot email for cid=%s (%s) -> %s: %s", customer_id,
                name, to, "sent" if ok else "FAILED")
    return {**result, "ok": bool(ok), "sent": bool(ok), "sent_to": to}


def _tgf_champ_signups(conn) -> tuple:
    """Upcoming TGF Championship events (any chapter) + who's in.

    Returns (events_list_or_None, paid_cids, rsvp_only_cids) — PAID means
    a registration purchase row exists; RSVP_ONLY means a matched YES
    RSVP with NO purchase (Kerry 2026-08-06, Mike Marques: "We have
    players RSVP'd but not paid" — they must NOT read as signed up).
    None events means no fall championship is posted yet, so signup
    status is unknowable."""
    from .timezone_utils import today_central_str
    evs = conn.execute(
        """SELECT id, item_name, event_date, chapter FROM events
           WHERE UPPER(item_name) LIKE '%CHAMPIONSHIP%' AND event_date >= ?
           ORDER BY event_date""", (today_central_str(),)).fetchall()
    if not evs:
        return None, set(), set()
    paid, rsvp = set(), set()
    for ev in evs:
        # a purchase row — the rsvp_only placeholder rows the RSVP
        # matcher creates are NOT purchases and land in the rsvp set
        for r in conn.execute(
                """SELECT DISTINCT customer_id FROM items
                   WHERE item_name = ? AND customer_id IS NOT NULL
                     AND COALESCE(transaction_status, '')
                         NOT IN ('credited', 'rsvp_only')""",
                (ev["item_name"],)).fetchall():
            paid.add(r["customer_id"])
        for r in conn.execute(
                """SELECT DISTINCT customer_id FROM items
                   WHERE item_name = ? AND customer_id IS NOT NULL
                     AND COALESCE(transaction_status, '') = 'rsvp_only'""",
                (ev["item_name"],)).fetchall():
            rsvp.add(r["customer_id"])
        for r in conn.execute(
                """SELECT DISTINCT i.customer_id FROM rsvps rv
                   JOIN items i ON i.id = rv.matched_item_id
                   WHERE rv.matched_event = ? AND UPPER(rv.response) LIKE 'Y%'
                     AND i.customer_id IS NOT NULL""",
                (ev["item_name"],)).fetchall():
            rsvp.add(r["customer_id"])
    return [dict(e) for e in evs], paid, rsvp - paid


def snapshot_target_list(window_points: float = 15.0,
                         seat_window: float = 15.0,
                         db_path: str | Path | None = None) -> dict:
    """WHO GETS WHICH SNAPSHOT EMAIL — the targeting queue (Kerry
    2026-08-03: "a list of identifying who is in our window to push on
    entry because they're realistically in the mix, versus those who
    just gets a more normalized spotlight email").

    Walks the two cup boards once and segments every player with a
    tracker profile:
      push_entry — IN THE WINDOW but NOT bought into either cup: within
                   `window_points` of the lead on the reset seeds (best
                   path). Seat-line proximity alone no longer qualifies
                   (Kerry 2026-08-06: 16+ off the Fellowship lead =
                   Normal, whatever the seat gap says); `seat_window`
                   is retained for signature compatibility and display.
      defend     — in the window AND bought in (motivate, don't pitch).
      normal     — on a board but outside the window (the normalized
                   snapshot).
    This is a REVIEW QUEUE, not a send list — availability and personal
    context (the "he'll be in Hawaii" factor) is Kerry's knowledge, so
    every send stays a per-player decision. Nothing here emails anyone.
    """
    cup = get_fellowship_cup_projection(db_path=db_path)
    gross = get_points_race_live("players_cup_gross", db_path=db_path)
    proj = get_lone_star_cup_projection(db_path=db_path)

    def _val(r):
        return (r.get("points_reset") if r.get("points_reset") is not None
                else r.get("total_points"))

    # per-chapter seat counts (co-captain years shave Fellowship 6 -> 5)
    fc_seats_by_ch = {}
    for ch in proj.get("chapters", []):
        n = sum(1 for s in ch.get("seats", [])
                if str(s.get("seat", "")).startswith("THE FELLOWSHIP CUP"))
        fc_seats_by_ch[ch.get("chapter")] = n or 6
    secured_cids = {s.get("customer_id")
                    for ch in proj.get("chapters", [])
                    for s in ch.get("seats", []) if s.get("customer_id")}

    paths = {
        "fellowship_cup": {"rows": cup.get("standings", []),
                           "ch_field": "chapter", "label": "Fellowship"},
        "players_cup": {"rows": gross.get("standings", []),
                        "ch_field": "player_chapter", "label": "Players"},
    }
    players: dict = {}
    for key, p in paths.items():
        # leader + seat cut per chapter, among enrolled players
        by_ch: dict = {}
        for r in p["rows"]:
            ch = (r.get(p["ch_field"]) or "").strip()
            v = _val(r)
            if not ch or v is None:
                continue
            by_ch.setdefault(ch, {"enrolled_vals": [], "lead": None})
            d = by_ch[ch]
            d["lead"] = v if d["lead"] is None else max(d["lead"], v)
            if r.get("enrolled"):
                d["enrolled_vals"].append(v)
        for d in by_ch.values():
            vals = sorted(d["enrolled_vals"], reverse=True)
            d["cuts"] = vals
        for r in p["rows"]:
            cid = r.get("customer_id")
            ch = (r.get(p["ch_field"]) or "").strip()
            v = _val(r)
            if not cid or not ch or v is None:
                continue
            # only chapters that actually field Lone Star Cup teams — a
            # lone player from an inactive chapter is otherwise "leading"
            # a pool of one (live find: Julius Jenkins, Houston)
            if ch not in fc_seats_by_ch:
                continue
            seats = (fc_seats_by_ch.get(ch, 6)
                     if key == "fellowship_cup" else 4)
            d = by_ch[ch]
            cut = d["cuts"][seats - 1] if len(d["cuts"]) >= seats else None
            e = players.setdefault(cid, {
                "customer_id": cid, "chapter": ch,
                "name": (r.get("player_name") or r.get("customer_name")
                         or "").strip(),
                "enrolled_any": False, "paths": {}})
            if not e["name"]:
                e["name"] = (r.get("player_name") or "").strip()
            e["enrolled_any"] = e["enrolled_any"] or bool(r.get("enrolled"))
            e["paths"][p["label"]] = {
                "points": v, "enrolled": bool(r.get("enrolled")),
                "points_back": round(max(d["lead"] - v, 0), 2),
                "gap_to_seat": (round(v - cut, 2) if cut is not None
                                else None),
                "seats": seats,
            }

    # THE SECOND LAYER (Kerry 2026-08-03): being in the points window is
    # only half the ask — they also need to be signed up for the TGF
    # Championship itself. Signup status rides every entry so the
    # Command Center can show who needs the weekend sold to them.
    champ_evs, champ_cids, champ_rsvp = None, set(), set()
    try:
        with _connect(db_path) as conn:
            champ_evs, champ_cids, champ_rsvp = _tgf_champ_signups(conn)
    except Exception:
        logger.warning("champ signup lookup failed", exc_info=True)

    push, defend, normal = [], [], []
    for e in players.values():
        backs = [pp["points_back"] for pp in e["paths"].values()]
        gaps = [pp["gap_to_seat"] for pp in e["paths"].values()
                if pp["gap_to_seat"] is not None]
        e["best_back"] = min(backs) if backs else None
        e["best_gap_to_seat"] = max(gaps) if gaps else None
        # WHICH cup produced each best number (Kerry 2026-08-06: "I
        # can't tell which cup the stat columns apply to") — the two
        # cells can come from DIFFERENT boards for the same player
        e["best_back_path"] = (
            min(e["paths"].items(),
                key=lambda kv: kv[1]["points_back"])[0]
            if backs else None)
        gap_items = [kv for kv in e["paths"].items()
                     if kv[1]["gap_to_seat"] is not None]
        e["best_gap_path"] = (
            max(gap_items, key=lambda kv: kv[1]["gap_to_seat"])[0]
            if gap_items else None)
        # Seat-line proximity no longer overrides a blown points gap
        # (Kerry 2026-08-06: "Move these 16 or more from the Fellowship
        # Cup to the Normal tab" — Ingram/White/Horton et al. sat 15.5+
        # off the lead yet stayed in the active queue because their
        # seat gap squeaked under seat_window). More than window_points
        # off the lead on the BEST path = NORMAL, whatever the seat
        # math says; best_gap_to_seat stays on the row for display.
        in_window = (e["best_back"] is not None
                     and e["best_back"] <= window_points)
        e["secured_seat"] = e["customer_id"] in secured_cids
        e["tgf_champ_signed_up"] = (
            (e["customer_id"] in champ_cids) if champ_evs is not None
            else None)
        # RSVP'd yes but no purchase (Kerry 2026-08-06, Mike Marques):
        # NOT signed up — the email owes them the two-steps ask
        e["tgf_champ_rsvp_only"] = (champ_evs is not None
                                    and e["customer_id"] in champ_rsvp)
        if in_window and not e["enrolled_any"]:
            push.append(e)
        elif in_window:
            defend.append(e)
        else:
            normal.append(e)
    push.sort(key=lambda x: (x["best_back"] if x["best_back"] is not None
                             else 99))
    defend.sort(key=lambda x: (x["best_back"] if x["best_back"] is not None
                               else 99))
    return {
        "criteria": {"window_points": window_points,
                     "seat_window": seat_window,
                     "note": "review queue only — availability is a "
                             "human call; nothing auto-sends"},
        "championship_events": champ_evs,
        "push_entry": push,
        "defend": defend,
        "normal": [{"customer_id": e["customer_id"], "name": e["name"],
                    "chapter": e["chapter"],
                    "enrolled_any": e["enrolled_any"],
                    "tgf_champ_signed_up": e["tgf_champ_signed_up"],
                    "tgf_champ_rsvp_only": e["tgf_champ_rsvp_only"]}
                   for e in normal],
        "counts": {"push_entry": len(push), "defend": len(defend),
                   "normal": len(normal)},
    }


# ── EVENT PACKAGE CONFIGURATIONS (Kerry 2026-08-03) ──
# Outlier events (the TGF Championship: Friday practice + Sat/Sun
# championship, sold as day-combination packages with a $100 side-game
# bundle) don't fit the single-price event model. Packages are
# rules-as-data in ONE app setting — no schema change:
#   {"<event_id>": {"packages": [{"label": str, "price": float}, ...],
#                   "assignments": {"<item_id>": <package index>}}}
# Registrations auto-match a package by exact paid price; credit rows
# and odd payments get a manual assignment. The roster's due badge and
# balance requests compute against the matched package price.

_EVENT_PACKAGES_KEY = "event_package_configs"


def _event_packages_all(db_path=None) -> dict:
    try:
        raw = get_app_setting(_EVENT_PACKAGES_KEY, db_path=db_path)
        return json.loads(raw) if raw else {}
    except Exception:
        return {}


def get_all_event_packages(db_path: str | Path | None = None) -> dict:
    """The full per-event package map (small — one page load serves it)."""
    return _event_packages_all(db_path)


#: Hole counts a package may declare. 36 and 54 are the two- and
#: three-day multi-day counts (v2.206.0).
_PACKAGE_HOLES_CHOICES = (9, 18, 36, 54)


def set_event_packages(event_id: int, packages: list,
                       db_path: str | Path | None = None) -> dict:
    """Replace an event's package list. Each: {label, price, holes?}.
    Prices are Kerry-entered through the UI — that entry IS the
    ratification. `holes` is optional: when set it is how many holes the
    package buys (18 one day / 36 both days / 54 all three), and the
    roster shows it in the Holes column in place of the order's per-day
    value. Assignments pointing past the new list length are dropped."""
    clean = []
    for p in packages or []:
        label = str(p.get("label") or "").strip()[:80]
        try:
            price = round(float(p.get("price")), 2)
        except (TypeError, ValueError):
            continue
        try:
            holes = int(p.get("holes"))
        except (TypeError, ValueError):
            holes = None
        if holes not in _PACKAGE_HOLES_CHOICES:
            holes = None
        if label and price >= 0:
            pkg = {"label": label, "price": price}
            if holes:
                pkg["holes"] = holes
            clean.append(pkg)
    allp = _event_packages_all(db_path)
    key = str(int(event_id))
    entry = allp.setdefault(key, {})
    entry["packages"] = clean
    entry["assignments"] = {k: v for k, v in
                            (entry.get("assignments") or {}).items()
                            if isinstance(v, int) and 0 <= v < len(clean)}
    if not clean and not entry["assignments"]:
        allp.pop(key, None)
    set_app_setting(_EVENT_PACKAGES_KEY, json.dumps(allp), db_path=db_path)
    return {"ok": True, "event_id": int(event_id), "packages": clean}


def assign_event_package(event_id: int, item_id: int,
                         package_index,
                         db_path: str | Path | None = None) -> dict:
    """Pin a registration to a package (None clears the pin)."""
    allp = _event_packages_all(db_path)
    entry = allp.setdefault(str(int(event_id)), {})
    packages = entry.get("packages") or []
    assignments = entry.setdefault("assignments", {})
    if package_index is None:
        assignments.pop(str(int(item_id)), None)
    else:
        idx = int(package_index)
        if not (0 <= idx < len(packages)):
            return {"ok": False, "error": f"package index {idx} out of range"}
        assignments[str(int(item_id))] = idx
    set_app_setting(_EVENT_PACKAGES_KEY, json.dumps(allp), db_path=db_path)
    return {"ok": True, "event_id": int(event_id), "item_id": int(item_id),
            "package_index": package_index}


# ── 2026 Championship: per-bucket payout accounts + bundle reclass ──
# Mailbox #276 items A/B, approved #279 (Kerry "I approve", 2026-08-05).
# Ratified side-games bundle: $100 = $30 SAT / $30 SUN / $40 COMBINED,
# $0 taxable, pure pot pass-through; single-day bundle $30 (day games
# only). Pots are FIELD-BASED and purses are DERIVED at record time so
# late adds (Jenkins, Callaway completing his balance) self-correct.

_CHAMP_EVENT_ID = 3291
_CHAMP_EVENT_NAME = "2026 TGF CHAMPIONSHIP"
_CHAMP_BUCKETS = (
    ("2026 TGF CHAMPIONSHIP — SATURDAY", "2026-08-15"),
    ("2026 TGF CHAMPIONSHIP — SUNDAY", "2026-08-16"),
    ("2026 TGF CHAMPIONSHIP — COMBINED", "2026-08-16"),
)


def _champ_roster_bundles(conn, db_path=None) -> dict:
    """Classify the championship's ACTIVE roster into side-games bundle
    carriers.

    A registration carries the bundle when its package label (pinned
    assignment first, else exact price match against Kerry's package
    configs) mentions side games, or when a +PAY child holds a $100
    BOTH-games payment (Robert Straiton's comp case). Single-day bundles
    ($30) need a day; that lives in the `champ_single_day_assignments`
    dial ("Name=SAT,Name=SUN") until assigned, and unassigned players are
    surfaced rather than silently counted.
    """
    entry = _event_packages_all(db_path).get(str(_CHAMP_EVENT_ID)) or {}
    packages = entry.get("packages") or []
    assignments = entry.get("assignments") or {}
    day_dial = {}
    for part in (get_app_setting("champ_single_day_assignments",
                                 db_path=db_path) or "").split(","):
        name, _, day = part.partition("=")
        if name.strip() and day.strip().upper() in ("SAT", "SUN"):
            day_dial[name.strip().lower()] = day.strip().upper()

    parents = [dict(r) for r in conn.execute(
        """SELECT id, customer, item_price, order_id, order_date, chapter, notes
             FROM items
            WHERE event_id = ? AND parent_item_id IS NULL
              AND COALESCE(transaction_status, 'active') = 'active'
              AND COALESCE(item_price, '') NOT LIKE '%comp%'""",
        (_CHAMP_EVENT_ID,)).fetchall()]
    comps = [dict(r) for r in conn.execute(
        """SELECT id, customer, item_price, order_id, order_date, chapter
             FROM items
            WHERE event_id = ? AND parent_item_id IS NULL
              AND COALESCE(transaction_status, 'active') = 'active'
              AND COALESCE(item_price, '') LIKE '%comp%'""",
        (_CHAMP_EVENT_ID,)).fetchall()]

    def _pkg_label(item):
        pin = assignments.get(str(item["id"]))
        if pin is not None and 0 <= int(pin) < len(packages):
            return (packages[int(pin)].get("label") or "").upper()
        price = _parse_dollar(item.get("item_price"))
        for p in packages:
            if abs(float(p.get("price") or 0) - price) < 0.005:
                return (p.get("label") or "").upper()
        return ""

    full, singles, unassigned, no_bundle = [], {"SAT": [], "SUN": []}, [], []
    rows_by_bundle = {}  # item_id -> bundle dollars (for the reclass pass)
    for it in parents:
        label = _pkg_label(it)
        has_games = "SIDE GAMES" in label or "+ GAMES" in label \
            or "+ PRACTICE + GAMES" in label or "GAMES)" in label
        if not has_games:
            no_bundle.append(it["customer"])
            continue
        if "ONE DAY" in label:
            rows_by_bundle[it["id"]] = 30.0
            # Dial is the OVERRIDE (#282); the order email's "WHICH DAYS?"
            # answer (carried in notes by the extractor) self-assigns when
            # no override is set.
            day = day_dial.get((it["customer"] or "").lower())
            if not day:
                m = re.search(r"WHICH DAYS\?:\s*(SATURDAY|SUNDAY)",
                              (it.get("notes") or "").upper())
                if m:
                    day = "SAT" if m.group(1) == "SATURDAY" else "SUN"
            if day:
                singles[day].append(it["customer"])
            else:
                unassigned.append(it["customer"])
        else:
            rows_by_bundle[it["id"]] = 100.0
            full.append(it["customer"])
    # Comp registrations join via a $100 BOTH-games +PAY child.
    child_bundle_ids = {}
    for it in comps:
        ch = conn.execute(
            """SELECT id FROM items WHERE parent_item_id = ?
                 AND COALESCE(transaction_status,'active') = 'active'
                 AND UPPER(COALESCE(side_games,'')) = 'BOTH'
                 AND item_price LIKE '%100%'""",
            (it["id"],)).fetchone()
        if ch:
            full.append(it["customer"])
            child_bundle_ids[ch["id"]] = 100.0
    return {"full": full, "singles": singles, "unassigned": unassigned,
            "no_bundle": no_bundle, "rows_by_bundle": rows_by_bundle,
            "child_bundle_ids": child_bundle_ids}


# One-off TGF Championship sub-game rates (Kerry 2026-08-06, "still a
# one off for the TGF Championship right now"; per-game breakdown
# re-confirmed verbatim 2026-08-07). Per side-games-bundle player:
# DAILY $30/day = Team Net $8 + Skins $18 (divided by 2 flights)
# + Closest to Pins $4; COMBINED $40 = Individual Net $20 + Individual
# Gross $20. The per-game pot derives from the bucket purse: n players
# = purse / rate-sum, pot = rate x n.
_CHAMP_SUBGAME_RATES = {
    "daily": (30.0, [("Team Net", 8.0, None),
                     ("Skins", 18.0, "2 flights"),
                     ("Closest to Pins", 4.0, None)]),
    "combined": (40.0, [("Individual Net", 20.0, None),
                        ("Individual Gross", 20.0, None)]),
}


def _champ_subgame_optouts(db_path=None) -> dict:
    """Per-player SUB-GAME opt-outs — the `champ_subgame_optouts` app
    setting (Kerry 2026-08-07, Carlos Zapata: credit the handicap-games
    portion — Team Net both days + Individual Net — while he stays in
    Skins, CTPs and Individual Gross). Shape:

      {"Carlos Zapata": {"SAT": ["Team Net"], "SUN": ["Team Net"],
                         "COMBINED": ["Individual Net"]}}

    The registration credit moves the actual money; this dial is what
    makes the DERIVED pot math agree with it — bucket purses drop by the
    opted-out rates and the named games' pots count one fewer head,
    while every other game keeps the full field."""
    try:
        raw = get_app_setting("champ_subgame_optouts", db_path=db_path)
        return json.loads(raw) if raw else {}
    except Exception:
        return {}


def _subgame_optout_key(bucket: str) -> str:
    """Dial keys are SAT/SUN/COMBINED; bucket ACCOUNTS are named
    SATURDAY/SUNDAY/COMBINED — normalize either form to the dial key."""
    b = (bucket or "").strip().upper()
    if b.startswith("SAT"):
        return "SAT"
    if b.startswith("SUN"):
        return "SUN"
    return b


def _subgame_optout_counts(bucket: str, optouts: dict) -> dict:
    """{game label: n opted out} for one bucket (SAT/SUN/COMBINED)."""
    key = _subgame_optout_key(bucket)
    counts: dict = {}
    for per_player in (optouts or {}).values():
        for lbl in (per_player or {}).get(key) or []:
            counts[lbl] = counts.get(lbl, 0) + 1
    return counts


def _subgame_optout_dollars(bucket: str, optouts: dict) -> float:
    kind = "combined" if (bucket or "").strip().upper() == "COMBINED" else "daily"
    rate_by_label = {l: r for l, r, _ in _CHAMP_SUBGAME_RATES[kind][1]}
    return sum(rate_by_label.get(lbl, 0.0) * n
               for lbl, n in _subgame_optout_counts(bucket, optouts).items())


def _bucket_subgames(bucket: str, purse: float, optouts: dict | None = None) -> list:
    """Per-game pots for one bucket. `optouts` is {game label: heads out}
    for THIS bucket: the stored purse is real money (already short the
    opted-out dollars), so the full-field head count is recovered by
    adding those dollars back before dividing, and only the named games
    lose heads."""
    kind = "combined" if (bucket or "").strip().upper() == "COMBINED" else "daily"
    per_head, games = _CHAMP_SUBGAME_RATES[kind]
    optouts = optouts or {}
    rate_by_label = {l: r for l, r, _ in games}
    oo_dollars = sum(rate_by_label.get(lbl, 0.0) * n
                     for lbl, n in optouts.items())
    n = round(((purse or 0) + oo_dollars) / per_head) if per_head else 0
    out = []
    for label, rate, note in games:
        n_g = max(0, n - int(optouts.get(label) or 0))
        pot = rate * n_g
        if note == "2 flights":
            note = f"2 flights · ${pot / 2:.2f} each"
        if optouts.get(label):
            oo_note = f"{int(optouts[label])} opted out"
            note = f"{note} · {oo_note}" if note else oo_note
        out.append({"label": label, "rate": rate, "pot": pot, "note": note})
    return out


def get_event_bucket_accounts(db_path=None) -> dict:
    """Map events.id -> its per-bucket payout accounts.

    A bucket account is a tgf_events row whose code is
    '<event item_name> — <BUCKET>' (the 2A championship pattern). Events
    with bucket accounts replace the regular GAMES-matrix panel with
    these purses (Kerry 2026-08-05: the matrix doesn't apply to the
    championship, and managers shouldn't read it as "the games").
    Each bucket carries its sub-game pot breakdown (_CHAMP_SUBGAME_RATES).
    """
    out: dict = {}
    optouts = _champ_subgame_optouts(db_path)
    # LOCKED payout schedules (Kerry-ratified) — the `event_payout_schedules`
    # app setting, keyed by event id. When present, a bucket's per-game pots
    # come from the LOCKED schedule (which may reallocate within the bucket,
    # e.g. the championship's $10/hole skins cap boosting Team Net + CTPs)
    # and each game carries its payout lines. Bucket PURSES stay derived —
    # a lock reallocates inside a bucket, never changes its total.
    try:
        _raw_sched = get_app_setting("event_payout_schedules", db_path=db_path)
        schedules = json.loads(_raw_sched) if _raw_sched else {}
    except Exception:
        schedules = {}
    with _connect(db_path) as conn:
        by_prefix: dict = {}
        for r in conn.execute(
                "SELECT code, total_purse FROM tgf_events "
                "WHERE code LIKE '% — %'").fetchall():
            prefix, _, bucket = r["code"].rpartition(" — ")
            if prefix and bucket:
                by_prefix.setdefault(prefix.strip().lower(), []).append(
                    {"code": r["code"], "bucket": bucket,
                     "purse": r["total_purse"] or 0,
                     "games": _bucket_subgames(
                         bucket, r["total_purse"] or 0,
                         _subgame_optout_counts(bucket, optouts))})
        if not by_prefix:
            return out
        for e in conn.execute("SELECT id, item_name FROM events").fetchall():
            b = by_prefix.get((e["item_name"] or "").strip().lower())
            if not b:
                continue
            sched = schedules.get(str(e["id"]))
            if sched:
                b = [dict(bk) for bk in b]
                for bk in b:
                    bs = (sched.get("buckets") or {}).get(
                        (bk["bucket"] or "").strip().upper())
                    if not bs:
                        continue
                    bk["locked"] = True
                    bk["payout_note"] = sched.get("note") or ""
                    games = []
                    for g in bk.get("games") or []:
                        gs = bs.get(g["label"])
                        if gs:
                            g = dict(g)
                            g["pot"] = float(gs.get("pot", g["pot"]))
                            g["payouts"] = list(gs.get("lines") or [])
                            # the auto note (derived flight split / opt-out
                            # count) is superseded by the locked lines
                            g["note"] = None
                        games.append(g)
                    bk["games"] = games
            out[str(e["id"])] = b
    return out


def get_event_games_axis(db_path=None) -> dict:
    """Per-event DAY-GAMES vocabulary (Kerry-ratified 2026-08-07:
    YES/SAT/SUN/NO REPLACES NET|GROSS|NONE — for the TGF Championship
    ONLY, because its games are day-shaped: the $100 bundle is
    $30 SAT / $30 SUN / $40 COMBINED and a single-day buyer pays $30
    for that day's games).

    An event uses this vocabulary when it has bucket accounts (the
    championship pattern — same marker that swaps the GAMES matrix for
    bucket purses). Rows are classified by _champ_roster_bundles: full
    bundle → YES, single-day → SAT/SUN (dial/order-notes), single-day
    with no day yet → DAY?, everyone else → NO. Keyed by lowercased
    customer name (the classification is name-keyed throughout).

    Returns {event_id: {"vocabulary": [...], "rows": {name: value},
    "unassigned": [names]}} — the roster tabs and GAMES cells read this
    instead of items.side_games on these events."""
    out: dict = {}
    if not get_event_bucket_accounts(db_path):
        return out
    with _connect(db_path) as conn:
        b = _champ_roster_bundles(conn, db_path=db_path)
    rows: dict = {}
    for n in b["no_bundle"]:
        rows[(n or "").lower()] = "NO"
    for n in b["singles"]["SAT"]:
        rows[(n or "").lower()] = "SAT"
    for n in b["singles"]["SUN"]:
        rows[(n or "").lower()] = "SUN"
    for n in b["unassigned"]:
        rows[(n or "").lower()] = "DAY?"
    for n in b["full"]:
        rows[(n or "").lower()] = "YES"
    out[str(_CHAMP_EVENT_ID)] = {
        "vocabulary": ["YES", "SAT", "SUN", "NO"],
        "rows": rows,
        "unassigned": b["unassigned"],
    }
    return out


def record_championship_bucket_accounts(db_path=None) -> dict:
    """Upsert the three championship payout accounts with DERIVED purses.

    SAT/SUN purse = (full bundles + that day's single-day buyers) × $30;
    COMBINED purse = full bundles × $40. Re-running recomputes purses from
    the live roster (idempotent); payout rows are recorded separately
    after play through the normal flows.
    """
    with _connect(db_path) as conn:
        b = _champ_roster_bundles(conn, db_path=db_path)
        n_full = len(b["full"])
        # Sub-game opt-outs (champ_subgame_optouts) reduce the REAL money
        # in a bucket: the player was credited those rates, so the purse
        # is short exactly that amount while every other game keeps the
        # full field (_bucket_subgames adds the dollars back to recover
        # the head count).
        oo = _champ_subgame_optouts(db_path)
        purses = {
            _CHAMP_BUCKETS[0][0]: 30.0 * (n_full + len(b["singles"]["SAT"]))
            - _subgame_optout_dollars("SAT", oo),
            _CHAMP_BUCKETS[1][0]: 30.0 * (n_full + len(b["singles"]["SUN"]))
            - _subgame_optout_dollars("SUN", oo),
            _CHAMP_BUCKETS[2][0]: 40.0 * n_full
            - _subgame_optout_dollars("COMBINED", oo),
        }
        out = []
        for (code, date), purse in zip(_CHAMP_BUCKETS,
                                       purses.values()):
            row = conn.execute(
                "SELECT id, total_purse FROM tgf_events WHERE LOWER(code) = LOWER(?)",
                (code,)).fetchone()
            if row:
                conn.execute(
                    "UPDATE tgf_events SET total_purse = ? WHERE id = ?",
                    (purse, row["id"]))
                out.append({"code": code, "purse": purse,
                            "was": row["total_purse"], "action": "updated"})
            else:
                conn.execute(
                    """INSERT INTO tgf_events (code, name, event_date,
                                               course, chapter, total_purse)
                       VALUES (?, ?, ?, 'Lost Pines', 'TGF', ?)""",
                    (code, code, date, purse))
                out.append({"code": code, "purse": purse, "action": "created"})
        conn.commit()
    return {"accounts": out, "full_bundles": b["full"],
            "single_day": b["singles"],
            "single_day_unassigned_needs_kerry": b["unassigned"],
            "no_bundle": b["no_bundle"]}


