def championship_close_payouts(apply: bool = False, db_path=None) -> dict:
    """Record the 2026 TGF CHAMPIONSHIP weekend's payouts per Kerry's
    consolidation directive: ALL game money (SAT/SUN/COMBINED) on the ONE
    '2026 TGF CHAMPIONSHIP' payout event alongside the existing MVP row,
    the two cups as their own events, and the three empty per-day bucket
    events deleted. Preview by default; apply=True writes.

    Guards: refuses to touch the championship event if it carries any
    non-mvp rows already (double-record); bucket events are deleted only
    while they hold zero payout rows; cup events go through
    record_season_contest_payouts which refuses codes already carrying
    their category."""
    champ_code = "2026 TGF CHAMPIONSHIP"
    bucket_codes = [f"{champ_code} — SATURDAY", f"{champ_code} — SUNDAY",
                    f"{champ_code} — COMBINED"]
    game_rows = [{"golferName": n, "category": c, "amount": a,
                  "description": d}
                 for (n, c, a, d) in _CHAMP_CLOSE_GAME_ROWS]
    out: dict = {
        "mode": "apply" if apply else "preview",
        "champ_event": {"code": champ_code,
                        "rows": len(game_rows),
                        "total": round(sum(r["amount"] for r in game_rows), 2)},
        "cup_events": {code: {"category": cat, "rows": len(rows),
                              "total": round(sum(a for _, a, _ in rows), 2)}
                       for code, (cat, rows) in _CHAMP_CLOSE_CUP_EVENTS.items()},
        "delete_buckets": [],
    }
    with _connect(db_path) as conn:
        ev = conn.execute(
            "SELECT id FROM tgf_events WHERE LOWER(code) = LOWER(?)",
            (champ_code,)).fetchone()
        if not ev:
            return {"error": f"no tgf_event {champ_code!r}"}
        champ_id = ev["id"]
        non_mvp = conn.execute(
            "SELECT COUNT(*) FROM tgf_payouts WHERE event_id = ? "
            "AND category != 'mvp'", (champ_id,)).fetchone()[0]
        if non_mvp:
            return {"error": f"{non_mvp} non-mvp payout row(s) already on "
                             f"{champ_code!r} — already closed?"}
        for code in bucket_codes:
            b = conn.execute(
                "SELECT id FROM tgf_events WHERE LOWER(code) = LOWER(?)",
                (code,)).fetchone()
            if not b:
                out["delete_buckets"].append({"code": code, "state": "absent"})
                continue
            n = conn.execute(
                "SELECT COUNT(*) FROM tgf_payouts WHERE event_id = ?",
                (b["id"],)).fetchone()[0]
            out["delete_buckets"].append(
                {"code": code, "event_id": b["id"], "payout_rows": n,
                 "state": ("blocked — has payout rows" if n else
                           ("deleted" if apply else "will delete"))})
            if apply and not n:
                conn.execute("DELETE FROM tgf_events WHERE id = ?",
                             (b["id"],))
        if apply:
            conn.commit()
    if not apply:
        return out
    out["champ_event"]["result"] = import_tgf_payouts(
        champ_id, game_rows, db_path=db_path)
    for code, (cat, rows) in _CHAMP_CLOSE_CUP_EVENTS.items():
        payouts = [{"golferName": n, "category": cat, "amount": a,
                    "description": f"auto: {d}"} for (n, a, d) in rows]
        out["cup_events"][code]["result"] = record_season_contest_payouts(
            code, "TGF", payouts, append_category=cat, db_path=db_path)
    return out


def championship_close_memo_fix(db_path=None) -> dict:
    """One-shot: rewrite the already-recorded cup payout descriptions to
    the memo-ready '<Cup> — <tail>' shape in _CHAMP_CLOSE_*_ROWS (the
    first apply recorded pre-fix text). Matches rows by (event code,
    category, exact amount + resolved name via description swap is
    overkill — amount+old/new description equality is enough here since
    each cup row is unique per player). Idempotent."""
    changed, missed = [], []
    with _connect(db_path) as conn:
        for code, (cat, rows) in _CHAMP_CLOSE_CUP_EVENTS.items():
            ev = conn.execute(
                "SELECT id FROM tgf_events WHERE LOWER(code) = LOWER(?)",
                (code,)).fetchone()
            if not ev:
                missed.append({"code": code, "why": "event absent"})
                continue
            for (name, amount, desc) in rows:
                new_desc = f"auto: {desc}"
                cid = _resolve_customer_for_payout(conn, name)
                row = conn.execute(
                    """SELECT id, description FROM tgf_payouts
                       WHERE event_id = ? AND customer_id = ?
                         AND category = ? AND ABS(amount - ?) < 0.005""",
                    (ev["id"], cid, cat, amount)).fetchone()
                if not row:
                    missed.append({"code": code, "name": name,
                                   "amount": amount, "why": "row not found"})
                    continue
                if row["description"] == new_desc:
                    continue
                conn.execute(
                    "UPDATE tgf_payouts SET description = ? WHERE id = ?",
                    (new_desc, row["id"]))
                changed.append({"payout_id": row["id"], "name": name,
                                "was": row["description"], "now": new_desc})
        conn.commit()
    return {"changed": changed, "missed": missed}


def delete_tgf_payout_row(payout_id: int, db_path=None) -> dict:
    """Delete ONE tgf_payouts row + its linked PENDING ledger entry, then
    refresh the event's aggregates (Kerry 2026-08-17: 'The MARROQUIN MVP
    should not have happened or been awarded. Remove that.'). Refuses when
    the linked acct_transactions row is non-pending — a paid row must be
    unwound through reconciliation, not deleted."""
    with _connect(db_path) as conn:
        r = conn.execute(
            """SELECT p.id, p.event_id, p.customer_id, p.category, p.amount,
                      p.description, p.acct_transaction_id,
                      t.source AS acct_source
               FROM tgf_payouts p
               LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
               WHERE p.id = ?""", (payout_id,)).fetchone()
        if not r:
            return {"error": f"no tgf_payouts row {payout_id}"}
        r = dict(r)
        if r["acct_transaction_id"] and r["acct_source"] not in (None, "pending"):
            return {"error": f"payout {payout_id} is linked to a "
                             f"{r['acct_source']!r} ledger row (paid?) — "
                             "refusing to delete"}
        if r["acct_transaction_id"] and r["acct_source"] == "pending":
            conn.execute("DELETE FROM acct_transactions WHERE id = ?",
                         (r["acct_transaction_id"],))
        conn.execute("DELETE FROM tgf_payouts WHERE id = ?", (payout_id,))
        stats = conn.execute(
            """SELECT COUNT(*) AS cnt, COALESCE(SUM(amount), 0) AS total,
                      COUNT(DISTINCT customer_id) AS winners
               FROM tgf_payouts WHERE event_id = ?""",
            (r["event_id"],)).fetchone()
        conn.execute(
            "UPDATE tgf_events SET total_purse = ?, winners_count = ?, "
            "payouts_count = ? WHERE id = ?",
            (stats["total"], stats["winners"], stats["cnt"], r["event_id"]))
        conn.commit()
    return {"deleted": {k: r[k] for k in
                        ("id", "event_id", "customer_id", "category",
                         "amount", "description")},
            "pending_ledger_row_deleted": bool(
                r["acct_transaction_id"] and r["acct_source"] == "pending"),
            "event_totals": {"total_purse": stats["total"],
                             "winners": stats["winners"],
                             "payouts": stats["cnt"]}}


def reclass_championship_allocations(db_path=None) -> dict:
    """Apply the #279-approved bundle reclass on event 3291 allocations.

    Bundle dollars ($100 full / $30 single-day) move to prize_pool with $0
    tax; on existing rows the delta comes OUT of tgf_operating and
    course_payable stays untouched. Pure-bundle rows (Robert's $100 +PAY
    child) zero their other buckets — there is no golf in that $100.
    Missing allocations are created with ONLY the ratified fields and
    status 'pending' (the schema's word for the proposal's 'partial');
    they complete when the event-model decomposition lands. Idempotent.
    """
    changed, created, skipped = [], [], []
    with _connect(db_path) as conn:
        b = _champ_roster_bundles(conn, db_path=db_path)
        targets = dict(b["rows_by_bundle"])
        targets.update(b["child_bundle_ids"])
        for item_id, bundle in targets.items():
            it = dict(conn.execute(
                "SELECT * FROM items WHERE id = ?", (item_id,)).fetchone())
            alloc = conn.execute(
                "SELECT * FROM acct_allocations WHERE item_id = ?",
                (item_id,)).fetchone()
            pure_bundle = abs(_parse_dollar(it.get("item_price")) - bundle) < 0.005
            if alloc:
                alloc = dict(alloc)
                if abs((alloc.get("prize_pool") or 0) - bundle) < 0.005 \
                        and (alloc.get("tax_reserve") or 0) == 0:
                    skipped.append({"item_id": item_id,
                                    "customer": it.get("customer"),
                                    "reason": "already reclassed"})
                    continue
                delta = bundle - (alloc.get("prize_pool") or 0)
                new_op = 0.0 if pure_bundle else \
                    max(0.0, round((alloc.get("tgf_operating") or 0) - delta, 2))
                new_course = 0.0 if pure_bundle else alloc.get("course_payable")
                conn.execute(
                    """UPDATE acct_allocations
                          SET prize_pool = ?, tgf_operating = ?,
                              course_payable = ?, tax_reserve = 0,
                              notes = COALESCE(notes || ' | ', '') || ?
                        WHERE id = ?""",
                    (bundle, new_op, new_course,
                     f"reclass #279: bundle ${bundle:.0f} -> prize_pool, "
                     f"$0 tax; delta from tgf_operating",
                     alloc["id"]))
                changed.append({"item_id": item_id,
                                "customer": it.get("customer"),
                                "prize_pool": bundle,
                                "tgf_operating": new_op})
            else:
                conn.execute(
                    """INSERT OR IGNORE INTO acct_allocations
                           (order_id, item_id, event_name, chapter,
                            allocation_date, prize_pool, total_collected,
                            allocation_status, notes)
                       VALUES (?, ?, ?, ?, ?, ?, ?, 'pending', ?)""",
                    (it.get("order_id") or f"manual-{item_id}", item_id,
                     _CHAMP_EVENT_NAME, it.get("chapter"),
                     it.get("order_date"), bundle,
                     _parse_dollar(it.get("item_price")),
                     "reclass #279: ratified fields only (bundle -> "
                     "prize_pool, $0 tax); golf-side buckets await the "
                     "event-model decomposition"))
                created.append({"item_id": item_id,
                                "customer": it.get("customer"),
                                "prize_pool": bundle})
        conn.commit()
    return {"changed": changed, "created": created, "skipped": skipped,
            "single_day_unassigned_needs_kerry": b["unassigned"]}


# ── SNAPSHOT COMMAND CENTER (Kerry 2026-08-03: "an interactive Command
#    Center for me to approve, preview, mark accordingly") ──
# Marks live in the snapshot_center_marks app-setting (rules-as-data, no
# schema change): {"<cid>": {status, note, marked_at, sent_at, sent_to}}.
# status ∈ approved | skipped | deferred | sent. A REAL send requires an
# APPROVED mark — Kerry clicking Approve+Send in the Command Center IS
# the per-send rule-3b ratification; nothing sends in bulk.

_SNAPSHOT_MARKS_KEY = "snapshot_center_marks"


def _snapshot_marks(db_path=None) -> dict:
    try:
        raw = get_app_setting(_SNAPSHOT_MARKS_KEY, db_path=db_path)
        return json.loads(raw) if raw else {}
    except Exception:
        return {}


# ── EMAIL OPEN/CLICK TRACKING (Kerry 2026-08-06: "Build the email
#    tracking") ──
# Every outbound chase email carries a per-send token: a 1x1 pixel
# (GET /t/o/<token>.gif) records opens, and every tracked link is
# rewritten through GET /t/c/<token>?u=... which records the click and
# 302s to the real destination (allowlisted hosts only — never an open
# redirect). Aggregates live on email_sends; the raw beacon stream in
# email_send_events. Caveat for the admin UI: Apple/Gmail image proxies
# prefetch pixels, so "opened" is a floor-of-truth signal, and clients
# that block images never report an open at all.

def _ensure_email_tracking_tables(conn) -> None:
    conn.execute("""CREATE TABLE IF NOT EXISTS email_sends (
        token TEXT PRIMARY KEY,
        customer_id INTEGER REFERENCES customers(customer_id),
        email_kind TEXT NOT NULL DEFAULT 'chase',
        sent_to TEXT,
        is_test INTEGER NOT NULL DEFAULT 0,
        subject TEXT,
        sent_at TEXT,
        created_at TEXT DEFAULT (datetime('now')),
        opened_at TEXT,
        open_count INTEGER NOT NULL DEFAULT 0,
        clicked_at TEXT,
        click_count INTEGER NOT NULL DEFAULT 0
    )""")
    conn.execute("""CREATE TABLE IF NOT EXISTS email_send_events (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        token TEXT NOT NULL REFERENCES email_sends(token),
        kind TEXT NOT NULL,
        url TEXT,
        user_agent TEXT,
        created_at TEXT DEFAULT (datetime('now'))
    )""")
    conn.execute("""CREATE INDEX IF NOT EXISTS idx_email_sends_customer
                    ON email_sends(customer_id)""")


def email_tracking_register(token: str, customer_id: int,
                            sent_to: str | None, is_test: bool,
                            subject: str | None = None,
                            email_kind: str = "chase",
                            db_path: str | Path | None = None) -> None:
    """Record an outbound send so its beacons have somewhere to land."""
    from .timezone_utils import now_central
    with _connect(db_path) as conn:
        _ensure_email_tracking_tables(conn)
        conn.execute(
            """INSERT OR REPLACE INTO email_sends
               (token, customer_id, email_kind, sent_to, is_test,
                subject, sent_at)
               VALUES (?, ?, ?, ?, ?, ?, ?)""",
            (token, int(customer_id), email_kind, sent_to,
             1 if is_test else 0, subject,
             now_central().strftime("%Y-%m-%d %H:%M")))
        conn.commit()


def email_tracking_record(token: str, kind: str, url: str | None = None,
                          user_agent: str | None = None,
                          db_path: str | Path | None = None) -> bool:
    """Record an open/click beacon. Returns False for unknown tokens
    (the beacon route still serves its pixel/redirect either way)."""
    from .timezone_utils import now_central
    if kind not in ("open", "click"):
        return False
    ts = now_central().strftime("%Y-%m-%d %H:%M")
    with _connect(db_path) as conn:
        _ensure_email_tracking_tables(conn)
        row = conn.execute("SELECT token FROM email_sends WHERE token = ?",
                           (token,)).fetchone()
        if not row:
            return False
        col = "open" if kind == "open" else "click"
        conn.execute(
            f"""UPDATE email_sends
                SET {col}_count = {col}_count + 1,
                    {col}ed_at = COALESCE({col}ed_at, ?)
                WHERE token = ?""", (ts, token))
        conn.execute(
            """INSERT INTO email_send_events (token, kind, url, user_agent)
               VALUES (?, ?, ?, ?)""",
            (token, kind, (url or "")[:500] or None,
             (user_agent or "")[:200] or None))
        conn.commit()
        return True


def _email_tracking_latest(db_path=None) -> dict:
    """Latest REAL (non-test) send per customer, keyed by str(cid) —
    what the Command Center queue joins its OPENED/CLICKED chips from."""
    with _connect(db_path) as conn:
        try:
            rows = conn.execute(
                """SELECT s.customer_id, s.sent_at, s.opened_at,
                          s.open_count, s.clicked_at, s.click_count
                   FROM email_sends s
                   JOIN (SELECT customer_id, MAX(created_at) AS mc
                         FROM email_sends WHERE is_test = 0
                         GROUP BY customer_id) last
                     ON last.customer_id = s.customer_id
                    AND last.mc = s.created_at
                   WHERE s.is_test = 0""").fetchall()
        except sqlite3.OperationalError:
            return {}
    return {str(r["customer_id"]): dict(r) for r in rows}


def snapshot_center_queue(db_path: str | Path | None = None) -> dict:
    """The targeting queue + Kerry's marks, one payload for the UI."""
    q = snapshot_target_list(db_path=db_path)
    marks = _snapshot_marks(db_path)
    tracking = _email_tracking_latest(db_path)
    for seg in ("push_entry", "defend", "normal"):
        for e in q.get(seg) or []:
            m = marks.get(str(e["customer_id"])) or {}
            e["mark"] = m.get("status")
            e["mark_note"] = m.get("note")
            e["sent_at"] = m.get("sent_at")
            e["sent_to"] = m.get("sent_to")
            t = tracking.get(str(e["customer_id"])) or {}
            e["opened_at"] = t.get("opened_at")
            e["open_count"] = t.get("open_count") or 0
            e["clicked_at"] = t.get("clicked_at")
            e["click_count"] = t.get("click_count") or 0
    return q


def snapshot_center_mark(customer_id: int, status: str,
                         note: str | None = None,
                         db_path: str | Path | None = None) -> dict:
    """Set/clear a player's mark. status: approved|skipped|deferred|clear."""
    from .timezone_utils import now_central
    if status not in ("approved", "skipped", "deferred", "clear"):
        return {"ok": False, "error": f"unknown status {status!r}"}
    marks = _snapshot_marks(db_path)
    key = str(int(customer_id))
    if status == "clear":
        marks.pop(key, None)
    else:
        entry = marks.setdefault(key, {})
        entry["status"] = status
        if note is not None:
            entry["note"] = note.strip()[:300]
        entry["marked_at"] = now_central().strftime("%Y-%m-%d %H:%M")
    set_app_setting(_SNAPSHOT_MARKS_KEY, json.dumps(marks), db_path=db_path)
    return {"ok": True, "customer_id": int(customer_id),
            "status": None if status == "clear" else status}


def snapshot_center_send(customer_id: int, test: bool = False,
                         db_path: str | Path | None = None) -> dict:
    """Send a player's snapshot email. test=True mails the ADMIN recap
    recipient (safe preview in a real inbox). A real send goes to the
    player's primary email and requires an APPROVED mark — the Command
    Center approval is the per-send ratification."""
    from .timezone_utils import now_central
    marks = _snapshot_marks(db_path)
    key = str(int(customer_id))
    to = None
    if not test:
        if (marks.get(key) or {}).get("status") != "approved":
            return {"ok": False,
                    "error": "not approved — approve this player in the "
                             "Command Center before sending"}
        with _connect(db_path) as conn:
            row = conn.execute(
                """SELECT email FROM customer_emails
                   WHERE customer_id = ? AND TRIM(COALESCE(email,'')) != ''
                   ORDER BY is_primary DESC, email_id LIMIT 1""",
                (int(customer_id),)).fetchone()
            to = (row["email"] or "").strip() if row else None
        if not to:
            return {"ok": False, "error": "no email on file for this player"}
    # R6 chase email is the send of record (Kerry 2026-08-06) — the same
    # Kerry-approved build the test sends used; the old R5 snapshot
    # builder (build_player_snapshot_email) is retired from this path.
    # Lazy import: chase_email imports from this module.
    from .chase_email import build_chase_email
    res = build_chase_email(int(customer_id), to_address=to,
                            send=True, db_path=db_path)
    res.pop("preview", None)
    if res.get("sent") and not test:
        entry = marks.setdefault(key, {})
        entry["status"] = "sent"
        entry["sent_at"] = now_central().strftime("%Y-%m-%d %H:%M")
        entry["sent_to"] = res.get("sent_to")
        set_app_setting(_SNAPSHOT_MARKS_KEY, json.dumps(marks),
                        db_path=db_path)
    return res


def _two_nine_recap_rows(event_query: str,
                         db_path: str | Path | None = None) -> list:
    """Posted TWO-NINE handicap rows for an 18-hole event, rebuilt for the
    manager recap email. Rating/slope/differential come straight off the
    POSTED handicap_rounds rows (no per-nine map needed); gross/adjusted/
    capped are recomputed per nine from the bridged scorecard; the index
    before/after pair excludes/includes this event's own rows."""
    formulas = get_scoring_formulas(db_path=db_path)
    settings = get_handicap_settings(db_path)
    lookback_months = int(settings.get("lookback_months", 12))
    cutoff = (datetime.now()
              - timedelta(days=lookback_months * 30.44)).strftime("%Y-%m-%d")
    out: list = []
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT hr.id AS hrid, hr.player_name, hr.round_date,
                      hr.course_name, hr.tee_name, hr.adjusted_score,
                      hr.rating, hr.slope, hr.differential,
                      hr.scoring_round_id, sr.tee_id, sr.customer_id
               FROM handicap_rounds hr
               JOIN scoring_rounds sr ON sr.id = hr.scoring_round_id
               JOIN events e ON e.id = sr.event_id
               WHERE e.item_name LIKE ? AND sr.holes_played > 9
                 AND (hr.tee_name LIKE '%Front 9' OR hr.tee_name LIKE '%Back 9')
               ORDER BY hr.player_name, hr.tee_name""",
            (f"%{event_query}%",)).fetchall()
        event_ids_by_player: dict = {}
        for r in rows:
            event_ids_by_player.setdefault(r["player_name"], set()).add(r["hrid"])
        for r in rows:
            holeset = (range(1, 10) if "Front 9" in (r["tee_name"] or "")
                       else range(10, 19))
            hrows = conn.execute(
                """SELECT sh.hole_number, sh.strokes, sh.strokes_received, cth.par
                   FROM scoring_holes sh
                   LEFT JOIN course_tee_holes cth
                     ON cth.tee_id = ? AND cth.hole_number = sh.hole_number
                   WHERE sh.scoring_round_id = ?""",
                (r["tee_id"], r["scoring_round_id"])).fetchall()
            by_hole = {h["hole_number"]: h for h in hrows}
            gross9 = capped = 0
            for hn in holeset:
                h = by_hole.get(hn)
                if not h or h["strokes"] is None:
                    continue
                gross9 += h["strokes"]
                if h["par"] is not None:
                    a = compute_hole_derivations(
                        h["par"], h["strokes"], h["strokes_received"] or 0,
                        formulas)["adjusted_strokes"]
                    if a < h["strokes"]:
                        capped += 1
            hist = conn.execute(
                """SELECT id, round_date, differential FROM handicap_rounds
                   WHERE player_name = ? AND differential IS NOT NULL
                     AND round_date >= ?
                   ORDER BY round_date, id""",
                (r["player_name"], cutoff)).fetchall()
            own = event_ids_by_player.get(r["player_name"], set())
            all_pairs = [(h["round_date"], h["differential"]) for h in hist]
            pre_pairs = [(h["round_date"], h["differential"]) for h in hist
                         if h["id"] not in own]
            out.append({
                "player_name": r["player_name"], "customer_id": r["customer_id"],
                "scoring_round_id": r["scoring_round_id"],
                "round_date": r["round_date"], "course_name": r["course_name"],
                "tee_name": r["tee_name"],
                "adjusted_score": r["adjusted_score"], "gross": gross9,
                "capped_holes": capped, "rating": r["rating"],
                "slope": r["slope"], "differential": r["differential"],
                "index_now": compute_handicap_index(
                    [d for _, d in pre_pairs[-20:]], settings),
                "index_after": compute_handicap_index(
                    [d for _, d in all_pairs[-20:]], settings),
            })
    return out


def send_handicap_recap_for_event(event_query: str,
                                  db_path: str | Path | None = None) -> dict:
    """Manual (re)send of the manager recap for an ALREADY-POSTED event.
    Rebuilds the posting rows from the preview — whose differential pool
    excludes each card's own bridged round, so index before/after stay
    correct even after the rounds are in — and sends the same email the
    apply path fires automatically. Recaps a posting, not a plan: only
    rounds already bridged to a handicap round are included. 18-hole
    events posted as two nines (the 9-hole preview skips them) rebuild
    from the posted rows instead."""
    preview = get_scoring_handicap_preview(event_query, db_path=db_path)
    if preview.get("error"):
        return preview
    written = [{
        "player_name": r["player_name"], "customer_id": r["customer_id"],
        "scoring_round_id": r["scoring_round_id"],
        "round_date": r["round_date"], "course_name": r["course_name"],
        "tee_name": r["tee_name"], "adjusted_score": r["adjusted_ndb"],
        "gross": r["gross"], "capped_holes": r["capped_holes"],
        "rating": r["rating"], "slope": r["slope"],
        "differential": r["differential_ndb"],
        "index_now": r["index_now"], "index_after": r["index_after_ndb"],
    } for r in preview["rounds"] if r["already_imported"]]
    if not written:
        written = _two_nine_recap_rows(event_query, db_path=db_path)
    if not written:
        return {"ok": False,
                "error": f"no posted handicap rounds for {event_query!r} yet "
                         "— run scoring-hcp-import:<event>|apply first"}
    return send_handicap_recap_email(
        (preview["events_matched"] or [event_query])[0], written,
        db_path=db_path)


# Per-nine (front/back) course ratings are NOT in course_tees (which stores
# only the 18-hole rating/slope). For an 18-hole event posted as two 9-hole
# records, the caller supplies each tee's per-nine rating/slope. Vaaler Creek
# (from GG course setup, Kerry 2026-07-18) — F rating + B rating sum exactly to
# the stored 18-hole rating, confirming the numbers:
_VAALER_PER_NINE = {
    # tee_id: {"front": (rating, slope), "back": (rating, slope)}
    2491: {"front": (34.2, 121), "back": (34.7, 128)},   # 23 - White  (18: 68.9/125)
    2492: {"front": (35.6, 130), "back": (36.2, 140)},   # 1 - Blue    (18: 71.8/135)
    2509: {"front": (33.3, 114), "back": (34.4, 123)},   # 4 - Red (L) (18: 67.7/119)
}


def derive_18hole_rounds_as_two_nines(event_query: str, per_nine: dict,
                                      dry_run: bool = True,
                                      db_path: str | Path = DB_PATH) -> dict:
    """Post an 18-hole event as TWO 9-hole handicap_rounds per player (front +
    back), each with its OWN per-nine course rating + slope. TGF is a 9-hole-
    index league, so an 18-hole round is two 9-hole scores — the 9-hole derive
    path deliberately skips 18-hole rounds, and this is the companion for them.

    `per_nine` maps tee_id -> {"front": (rating, slope), "back": (rating, slope)}.
    A round on a tee absent from `per_nine` is SKIPPED and listed — never guess
    a rating. Same WHS math as the 9-hole path (per-hole net-double-bogey via
    compute_hole_derivations; differential = (adjusted_9 - rating_9)*113/slope_9)
    and the same identity-reuse + dedup rules; the two rows get distinct tee
    labels ("<tee> — Front 9" / "<tee> — Back 9") so re-runs dedupe cleanly.
    dry_run=True (default) returns the plan without writing.
    """
    formulas = get_scoring_formulas(db_path=db_path)
    settings = get_handicap_settings(db_path)
    lookback_months = int(settings.get("lookback_months", 12))
    cutoff_str = (datetime.now()
                  - timedelta(days=lookback_months * 30.44)).strftime("%Y-%m-%d")
    plan: list = []
    skipped: list = []
    events_seen: set = set()
    planned_keys: set = set()   # intra-run dedup — see below
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        rounds = conn.execute(
            """SELECT sr.id AS srid, sr.player_name, sr.customer_id,
                      sr.round_date, sr.holes_played, sr.gross, sr.tee_id,
                      e.item_name AS event_name, c.name AS course_name,
                      ct.tee_name
               FROM scoring_rounds sr
               JOIN events e ON e.id = sr.event_id
               LEFT JOIN courses c ON c.course_id = sr.course_id
               LEFT JOIN course_tees ct ON ct.tee_id = sr.tee_id
               WHERE e.item_name LIKE ?
               ORDER BY sr.player_name, sr.id""",
            (f"%{event_query}%",)).fetchall()
        if not rounds:
            return {"error": f"no imported scoring rounds match event "
                             f"{event_query!r} — run the scorecard import first"}

        for r in rounds:
            events_seen.add(r["event_name"])
            if (r["holes_played"] or 0) <= 9:
                skipped.append({"player_name": r["player_name"],
                                "scoring_round_id": r["srid"],
                                "reason": "not an 18-hole round (use the 9-hole path)"})
                continue
            pn = per_nine.get(r["tee_id"])
            if not pn:
                skipped.append({"player_name": r["player_name"],
                                "scoring_round_id": r["srid"],
                                "reason": f"no per-nine rating for tee_id {r['tee_id']} "
                                          f"({r['tee_name']}) — provide it, not guessing"})
                continue

            hrows = conn.execute(
                """SELECT sh.hole_number, sh.strokes, sh.strokes_received, cth.par
                   FROM scoring_holes sh
                   LEFT JOIN course_tee_holes cth
                     ON cth.tee_id = ? AND cth.hole_number = sh.hole_number
                   WHERE sh.scoring_round_id = ?""",
                (r["tee_id"], r["srid"])).fetchall()
            by_hole = {h["hole_number"]: h for h in hrows}

            # Reuse the freshest existing handicap identity for this customer.
            target_name = _normalize_player_name(r["player_name"])
            if r["customer_id"]:
                best = conn.execute(
                    """SELECT l.player_name,
                              (SELECT COUNT(*) FROM handicap_rounds hr
                               WHERE hr.player_name = l.player_name) AS n,
                              (SELECT MAX(hr.round_date) FROM handicap_rounds hr
                               WHERE hr.player_name = l.player_name) AS last_round
                       FROM handicap_player_links l WHERE l.customer_id = ?
                       ORDER BY last_round DESC, n DESC, l.player_name LIMIT 1""",
                    (r["customer_id"],)).fetchone()
                if best and best["n"]:
                    target_name = best["player_name"]

            names = {_normalize_player_name(r["player_name"]), target_name}
            if r["customer_id"]:
                for lk in conn.execute(
                        "SELECT player_name FROM handicap_player_links WHERE customer_id = ?",
                        (r["customer_id"],)).fetchall():
                    names.add(lk["player_name"])
            qmarks = ",".join("?" * len(names))
            hist = conn.execute(
                f"""SELECT round_date, differential FROM handicap_rounds
                    WHERE player_name IN ({qmarks}) AND differential IS NOT NULL
                      AND round_date >= ?
                    ORDER BY round_date, id""",
                (*names, cutoff_str)).fetchall()
            hist_pairs = [(h["round_date"], h["differential"]) for h in hist]
            index_now = compute_handicap_index(
                [d for _, d in hist_pairs[-20:]], settings)

            nines_out = []
            for nine, holeset in (("Front 9", range(1, 10)),
                                  ("Back 9", range(10, 19))):
                rating9, slope9 = (pn["front"] if nine == "Front 9" else pn["back"])
                adj = gross9 = capped = 0
                missing = False
                for hn in holeset:
                    h = by_hole.get(hn)
                    if not h or h["strokes"] is None:
                        missing = True
                        continue
                    gross9 += h["strokes"]
                    if h["par"] is None:
                        missing = True
                        adj += h["strokes"]
                        continue
                    a = compute_hole_derivations(
                        h["par"], h["strokes"], h["strokes_received"] or 0,
                        formulas)["adjusted_strokes"]
                    adj += a
                    if a < h["strokes"]:
                        capped += 1
                diff9 = round((adj - rating9) * 113.0 / slope9, 1)
                tee_lbl = f"{r['tee_name']} — {nine}"
                dup = conn.execute(
                    """SELECT id FROM handicap_rounds
                       WHERE player_name = ? AND round_date = ? AND round_id IS NULL
                         AND COALESCE(course_name,'') = COALESCE(?,'')
                         AND COALESCE(tee_name,'') = COALESCE(?,'')""",
                    (target_name, r["round_date"], r["course_name"], tee_lbl)).fetchone()
                nines_out.append({
                    "nine": nine, "tee_name": tee_lbl, "rating": rating9,
                    "slope": slope9, "gross9": gross9, "adjusted9": adj,
                    "capped_holes": capped, "differential": diff9,
                    "missing": missing, "dup_id": dup["id"] if dup else None,
                })

            merged = sorted(hist_pairs + [(r["round_date"], n["differential"])
                                          for n in nines_out])
            index_after = compute_handicap_index(
                [d for _, d in merged[-20:]], settings)

            for n in nines_out:
                if n["dup_id"]:
                    skipped.append({"player_name": target_name, "nine": n["nine"],
                                    "scoring_round_id": r["srid"],
                                    "reason": f"already posted (hr {n['dup_id']})"})
                    continue
                # Intra-run dedup: the ALL Net -> ALL Gross scorecard
                # backfill banks TWO scoring_rounds per player for the same
                # day (one per board) — the pre-existing dup check above
                # only sees rows already WRITTEN, so without this a single
                # apply would post every nine twice.
                pkey = (target_name, r["round_date"], n["tee_name"])
                if pkey in planned_keys:
                    skipped.append({"player_name": target_name, "nine": n["nine"],
                                    "scoring_round_id": r["srid"],
                                    "reason": "duplicate scoring round for the same "
                                              "day/tee (net+gross board imports)"})
                    continue
                planned_keys.add(pkey)
                plan.append({
                    "player_name": target_name, "customer_id": r["customer_id"],
                    "scoring_round_id": r["srid"], "round_date": r["round_date"],
                    "course_name": r["course_name"], "tee_name": n["tee_name"],
                    "nine": n["nine"], "gross9": n["gross9"],
                    "adjusted_score": n["adjusted9"], "capped_holes": n["capped_holes"],
                    "rating": n["rating"], "slope": n["slope"],
                    "differential": n["differential"],
                    "index_now": index_now, "index_after": index_after,
                    "flags": (["missing_par_or_holes"] if n["missing"] else []),
                })

        if not dry_run:
            for p in plan:
                # The played side is authoritative here (the round was split
                # into its front/back nines) — record it so the card never has
                # to re-derive it. Named-nine courses keep NULL (nine in name).
                nine_val = None if _course_names_its_nines(p["course_name"]) else p.get("nine")
                conn.execute(
                    """INSERT INTO handicap_rounds
                       (player_name, round_date, round_id, course_name, tee_name,
                        adjusted_score, rating, slope, differential, scoring_round_id, nine)
                       VALUES (?, ?, NULL, ?, ?, ?, ?, ?, ?, ?, ?)""",
                    (p["player_name"], p["round_date"], p["course_name"],
                     p["tee_name"], p["adjusted_score"], p["rating"], p["slope"],
                     p["differential"], p["scoring_round_id"], nine_val))
                if not conn.execute(
                        "SELECT 1 FROM handicap_player_links WHERE player_name = ?",
                        (p["player_name"],)).fetchone():
                    cname = None
                    if p["customer_id"]:
                        c = conn.execute(
                            """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                                       COALESCE(last_name,'')) AS nm
                               FROM customers WHERE customer_id = ?""",
                            (p["customer_id"],)).fetchone()
                        cname = (c["nm"] or "").strip() or None
                    conn.execute(
                        """INSERT INTO handicap_player_links
                           (player_name, customer_name, customer_id) VALUES (?, ?, ?)""",
                        (p["player_name"], cname, p["customer_id"]))
            conn.commit()
            logger.info("Posted %d two-nine handicap rounds for %r (18-hole "
                        "event split, WHS NDB per nine)", len(plan), event_query)

    return {"event_query": event_query, "events_matched": sorted(events_seen),
            "dry_run": dry_run,
            ("would_write" if dry_run else "written"): plan,
            "skipped": skipped,
            "summary": {"planned": len(plan), "skipped": len(skipped),
                        "players": len(set(p["player_name"] for p in plan))},
            "standard": "WHS net double bogey per nine; each nine its own "
                        "course rating + slope (18-hole event → two 9-hole records)"}


def _player_diff_history(conn, cutoff: str | None = None) -> dict:
    """player_name -> [(round_date, differential, rating, slope,
    adjusted_score)] ordered by date, id — the raw pool every handicap
    analysis draws from. cutoff (YYYY-MM-DD) bounds the window; None = all."""
    q = ("SELECT player_name, round_date, differential, rating, slope, "
         "adjusted_score FROM handicap_rounds WHERE differential IS NOT NULL ")
    args: tuple = ()
    if cutoff:
        q += "AND round_date >= ? "
        args = (cutoff,)
    q += "ORDER BY player_name, round_date, id"
    out: dict = {}
    for r in conn.execute(q, args).fetchall():
        out.setdefault(r["player_name"], []).append(
            (r["round_date"], r["differential"], r["rating"], r["slope"],
             r["adjusted_score"]))
    return out


def r1_multiplier_impact(apply: bool = False,
                         db_path: str | Path | None = None) -> dict:
    """R1 impact sweep (Kerry-ratified 2026-07-16, sequenced 'sweep first
    → report → apply'): recompute every current index with the ×0.96
    multiplier removed and report the movement. apply=True flips the
    handicap_settings multiplier dial to 1.0 (indexes recompute everywhere
    they are read — the RECORD layer updates retroactively by design; paid
    results are never touched, per the retroactivity boundary)."""
    settings = get_handicap_settings(db_path)
    lookback_months = int(settings.get("lookback_months", 12))
    cutoff = (datetime.now()
              - timedelta(days=lookback_months * 30.44)).strftime("%Y-%m-%d")
    s_old = dict(settings, multiplier="0.96")
    s_new = dict(settings, multiplier="1.0")
    changed = []
    same = 0
    unchanged_players = []
    with _connect(db_path) as conn:
        hist = _player_diff_history(conn, cutoff)
    for name, rounds in hist.items():
        diffs = [d for _, d, *_ in rounds][-20:]
        old = compute_handicap_index(diffs, s_old)
        new = compute_handicap_index(diffs, s_new)
        if old is None and new is None:
            continue
        if old == new:
            same += 1
            unchanged_players.append({"player_name": name, "index": new})
            continue
        changed.append({"player_name": name, "index_096": old,
                        "index_100": new,
                        "delta": (round(new - old, 1)
                                  if old is not None and new is not None
                                  else None)})
    changed.sort(key=lambda p: -(abs(p["delta"]) if p["delta"] else 0))
    deltas = [p["delta"] for p in changed if p["delta"] is not None]
    out = {
        "current_multiplier": settings.get("multiplier"),
        "players_with_index": same + len(changed),
        "unchanged": same,
        "changed": len(changed),
        "mean_delta": round(sum(deltas) / len(deltas), 2) if deltas else 0,
        "max_delta": max(deltas) if deltas else 0,
        "top_moves": changed[:25],
        "unchanged_players": unchanged_players[:30],
        "applied": False,
    }
    if apply:
        update_handicap_settings({"multiplier": "1.0"}, db_path=db_path)
        out["applied"] = True
        out["new_multiplier"] = "1.0"
    return out


def ghin_comparison_analysis(db_path: str | Path | None = None) -> dict:
    """Comparable-GHIN analysis (Kerry 2026-08-03): from TGF event scores
    ONLY, build 18-hole scores the old GHIN way — combine consecutive
    9-hole rounds chronologically (adj = a1+a2, rating = r1+r2, slope =
    avg) — compute a WHS-style 18-hole index (best 8 of last 20, NO 0.96,
    no time window, like real GHIN), and compare it to the player's TGF
    index expressed as its 18-hole equivalent (9-hole index × 2).

    Also validates the 75% onboarding rule: players with a manager-stamped
    starting_handicap_18 (their external/GHIN handicap at onboarding) are
    compared current-TGF-18 vs that original number.
    """
    settings = get_handicap_settings(db_path)
    lookback_months = int(settings.get("lookback_months", 12))
    cutoff = (datetime.now()
              - timedelta(days=lookback_months * 30.44)).strftime("%Y-%m-%d")
    ghin_settings = dict(settings, multiplier="1.0")

    players = []
    with _connect(db_path) as conn:
        hist_all = _player_diff_history(conn, cutoff=None)
        hist_win = _player_diff_history(conn, cutoff)
        onboarded = conn.execute(
            """SELECT customer_id,
                      TRIM(COALESCE(first_name,'') || ' ' ||
                           COALESCE(last_name,'')) AS nm,
                      starting_handicap_18
               FROM customers WHERE starting_handicap_18 IS NOT NULL"""
        ).fetchall()
        links = {r["player_name"]: r["customer_id"] for r in conn.execute(
            "SELECT player_name, customer_id FROM handicap_player_links "
            "WHERE customer_id IS NOT NULL").fetchall()}

    for name, rounds in hist_all.items():
        # GHIN-comparable: combine consecutive nines into 18s
        combined = []
        usable = [r for r in rounds
                  if r[2] is not None and r[3] is not None
                  and r[4] is not None]
        for i in range(0, len(usable) - 1, 2):
            d1, d2 = usable[i], usable[i + 1]
            adj18 = d1[4] + d2[4]
            rat18 = d1[2] + d2[2]
            slp18 = (d1[3] + d2[3]) / 2.0
            if not slp18:
                continue
            combined.append(round((adj18 - rat18) * 113.0 / slp18, 1))
        ghin18 = compute_handicap_index(combined[-20:], ghin_settings)
        # TGF side: current 9-hole index (live settings, 12-mo window)
        win = hist_win.get(name) or []
        tgf9 = compute_handicap_index([d for _, d, *_ in win][-20:], settings)
        if ghin18 is None or tgf9 is None:
            continue
        tgf18 = round(tgf9 * 2, 1)
        ratio = (round(tgf18 / ghin18, 3)
                 if ghin18 and ghin18 >= 4.0 else None)
        players.append({"player_name": name, "nines": len(usable),
                        "combined_18s": len(combined),
                        "tgf_index_9": tgf9, "tgf_index_18_equiv": tgf18,
                        "ghin_comparable_18": ghin18, "ratio": ratio})

    ratios = sorted(p["ratio"] for p in players
                    if p["ratio"] is not None and p["combined_18s"] >= 6)
    def _pct(q):
        if not ratios:
            return None
        k = max(0, min(len(ratios) - 1, int(round(q * (len(ratios) - 1)))))
        return ratios[k]
    in_band = sum(1 for r in ratios if 0.75 <= r <= 0.90)

    # 75% onboarding validation — original external handicap vs where the
    # player's TGF index actually settled
    onboarding = []
    name_by_cid = {}
    for nm, cid in links.items():
        name_by_cid.setdefault(cid, nm)
    for r in onboarded:
        nm = name_by_cid.get(r["customer_id"])
        match = next((p for p in players if p["player_name"] == nm), None)
        if not match or not r["starting_handicap_18"]:
            continue
        onboarding.append({
            "player_name": nm, "external_18": r["starting_handicap_18"],
            "onboard_75pct_18": round(r["starting_handicap_18"] * 0.75, 1),
            "settled_tgf_18": match["tgf_index_18_equiv"],
            "settled_ratio": round(
                match["tgf_index_18_equiv"] / r["starting_handicap_18"], 3)
            if r["starting_handicap_18"] >= 4 else None,
            "rounds_since": match["nines"]})

    players.sort(key=lambda p: (p["ratio"] is None, p["ratio"] or 99))
    return {
        "method": ("GHIN-comparable = consecutive TGF nines combined into "
                   "18s (adj sum, rating sum, slope avg), WHS best-8-of-20, "
                   "no 0.96, no time window; TGF-18 = 9-hole index × 2 "
                   "(live settings)"),
        "summary": {
            "players_compared": len(ratios),
            "ratio_mean": round(sum(ratios) / len(ratios), 3) if ratios else None,
            "ratio_median": _pct(0.5), "ratio_p25": _pct(0.25),
            "ratio_p75": _pct(0.75),
            "pct_in_75_90_band": (round(100.0 * in_band / len(ratios), 1)
                                  if ratios else None),
        },
        "players": players,
        "onboarding_75pct": sorted(onboarding,
                                   key=lambda o: o["settled_ratio"] or 99),
    }


def _event_first_nine(item_name: str,
                      db_path: str | Path | None = None) -> str:
    """Which nine an 18-hole event PLAYED FIRST — 'front' (default) or
    'back'. Rules-as-data: the app_settings dial `event_first_nine` maps
    lowercased event names to the nine that teed off first (Kerry
    2026-08-03: the SA championship started on the back)."""
    try:
        raw = get_app_setting("event_first_nine", db_path=db_path)
        m = json.loads(raw) if raw else {}
        return (m or {}).get((item_name or "").strip().lower(), "front")
    except Exception:
        return "front"


def set_event_nine_order(event_query: str, first_nine: str,
                         dry_run: bool = True,
                         db_path: str | Path | None = None) -> dict:
    """Record which nine an 18-hole event PLAYED FIRST (Kerry 2026-08-03:
    the SA championship played the back nine first) and make every surface
    agree:

    - the `event_first_nine` dial records the order per event, so
      scorecard renderers show the nines in play order;
    - each player's TWO-NINE handicap_rounds pair swaps payloads when
      needed so the first-played nine holds the LOWER id — the newest-
      first differentials list then shows the second-played nine on top.

    Idempotent: already-ordered pairs no-op; the dial write is a merge.
    """
    first_nine = (first_nine or "").strip().lower()
    if first_nine not in ("front", "back"):
        return {"error": "first_nine must be 'front' or 'back'"}
    swapped = []
    events_matched: set = set()
    SWAP_COLS = ("tee_name", "adjusted_score", "rating", "slope",
                 "differential", "nine")
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        for r in conn.execute(
                """SELECT DISTINCT e.item_name FROM scoring_rounds sr
                   JOIN events e ON e.id = sr.event_id
                   WHERE e.item_name LIKE ? AND sr.holes_played > 9""",
                (f"%{event_query}%",)).fetchall():
            events_matched.add(r["item_name"])
        pairs = conn.execute(
            """SELECT hr.id, hr.player_name, hr.scoring_round_id, hr.tee_name,
                      hr.adjusted_score, hr.rating, hr.slope,
                      hr.differential, hr.nine
               FROM handicap_rounds hr
               JOIN scoring_rounds sr ON sr.id = hr.scoring_round_id
               JOIN events e ON e.id = sr.event_id
               WHERE e.item_name LIKE ? AND sr.holes_played > 9
                 AND (hr.tee_name LIKE '%Front 9' OR hr.tee_name LIKE '%Back 9')
               ORDER BY hr.player_name, hr.id""",
            (f"%{event_query}%",)).fetchall()
        by_player: dict = {}
        for r in pairs:
            by_player.setdefault(
                (r["player_name"], r["scoring_round_id"]), []).append(dict(r))
        for (pname, srid), rows in by_player.items():
            if len(rows) != 2:
                continue
            lo, hi = rows          # ordered by id
            lo_is_front = "Front 9" in (lo["tee_name"] or "")
            # lower id must be the FIRST-PLAYED nine
            needs_swap = (first_nine == "back" and lo_is_front) or \
                         (first_nine == "front" and not lo_is_front)
            if not needs_swap:
                continue
            swapped.append({"player_name": pname, "ids": [lo["id"], hi["id"]]})
            if not dry_run:
                for a, b in ((lo, hi), (hi, lo)):
                    conn.execute(
                        f"UPDATE handicap_rounds SET "
                        f"{', '.join(c + ' = ?' for c in SWAP_COLS)} "
                        f"WHERE id = ?",
                        (*[b[c] for c in SWAP_COLS], a["id"]))
        if not dry_run:
            conn.commit()
    if not dry_run and events_matched:
        try:
            raw = get_app_setting("event_first_nine", db_path=db_path)
            m = json.loads(raw) if raw else {}
        except Exception:
            m = {}
        for nm in events_matched:
            m[nm.strip().lower()] = first_nine
        set_app_setting("event_first_nine", json.dumps(m), db_path=db_path)
    return {"event_query": event_query, "first_nine": first_nine,
            "dry_run": dry_run,
            "events_stamped": sorted(events_matched),
            "pairs_swapped": len(swapped), "swapped": swapped[:40]}


def repair_handicap_adjusted_scores(cells: list[dict], dry_run: bool = True,
                                    db_path: str | Path = DB_PATH) -> dict:
    """Repair 2026 handicap_rounds whose adjusted_score was imported as
    the RAW gross (the Spreadsheet Composer files carry no adjusted
    column), using GG's true Adjusted Gross from Kerry's season-scores
    workbooks (Kerry: 'run it', 2026-07-14).

    Each cell: {name (GG 'LAST, First'), date (YYYY-MM-DD), gross,
    adjusted}. A row is repaired ONLY when every guard holds:
      * date in 2026, adjusted < gross (capping only lowers)
      * exactly ONE handicap_rounds row matches the normalized player
        name (case-insensitive) + date — ambiguity skips
      * the stored adjusted_score equals the cell's GROSS (proof the
        row came from an uncapped import); rows already storing the
        true adjusted skip as 'already correct'; anything else skips
        for review — never guess.
    Repair sets adjusted_score to GG's value and recomputes the
    differential from the row's OWN stored slope/rating (the tee-rating
    question is deliberately untouched — this fixes capping only).
    """
    plan: list = []
    skipped: list = []
    with _connect(db_path) as conn:
        for cell in cells:
            name = _normalize_player_name(cell.get("name") or "")
            date = (cell.get("date") or "").strip()
            try:
                gross = int(cell["gross"]); adjusted = int(cell["adjusted"])
            except (KeyError, TypeError, ValueError):
                skipped.append({"cell": cell, "reason": "malformed cell"})
                continue
            if not date.startswith("2026-") or adjusted >= gross or not name:
                skipped.append({"cell": cell, "reason": "guard: date/direction"})
                continue
            rows = conn.execute(
                """SELECT id, player_name, adjusted_score, rating, slope,
                          differential
                   FROM handicap_rounds
                   WHERE LOWER(player_name) = LOWER(?) AND round_date = ?""",
                (name, date)).fetchall()
            if not rows:
                skipped.append({"name": name, "date": date,
                                "reason": "no matching handicap round"})
                continue
            if len(rows) > 1:
                skipped.append({"name": name, "date": date,
                                "reason": f"ambiguous ({len(rows)} rows)"})
                continue
            row = rows[0]
            if row["adjusted_score"] == adjusted:
                skipped.append({"name": name, "date": date,
                                "reason": "already correct"})
                continue
            if row["adjusted_score"] != gross:
                skipped.append({"name": name, "date": date,
                                "stored": row["adjusted_score"],
                                "file_gross": gross, "file_adjusted": adjusted,
                                "reason": "stored value matches neither — review"})
                continue
            if not row["slope"]:
                skipped.append({"name": name, "date": date,
                                "reason": "row has no slope"})
                continue
            new_diff = round((adjusted - row["rating"]) * 113.0 / row["slope"], 1)
            plan.append({"handicap_round_id": row["id"],
                         "player_name": row["player_name"], "round_date": date,
                         "adjusted": f'{row["adjusted_score"]} -> {adjusted}',
                         "differential": f'{row["differential"]} -> {new_diff}',
                         "_adj": adjusted, "_diff": new_diff})
        if not dry_run:
            for p in plan:
                conn.execute(
                    "UPDATE handicap_rounds SET adjusted_score = ?, "
                    "differential = ? WHERE id = ?",
                    (p["_adj"], p["_diff"], p["handicap_round_id"]))
            conn.commit()
            logger.info("Repaired %d handicap rounds to GG true adjusted "
                        "gross (Composer raw-score import fix)", len(plan))
        for p in plan:
            p.pop("_adj"); p.pop("_diff")
    from collections import Counter
    return {"dry_run": dry_run,
            "repaired" if not dry_run else "would_repair": plan,
            "skipped_reasons": dict(Counter(s["reason"] for s in skipped)),
            "skipped": skipped,
            "summary": {"planned": len(plan), "skipped": len(skipped)}}


def audit_handicap_bridges(db_path: str | Path = DB_PATH) -> dict:
    """Full-table audit of every handicap record's link to its scorecard
    (Kerry 2026-07-14: 'audit all the records and see if you find any
    other issues'). READ-ONLY. Classifies every handicap_rounds row:

      bridged_reconciled   — bridged; adjusted equals a nine's WHS total
      bridged_mismatch     — bridged; adjusted matches NEITHER nine (review)
      overclaimed_card     — more records on one card than it has nines
      unbridged_card_exists— no bridge but the player HAS a card that date
                             (review — the repair left it because nothing
                             reconciled)
      unbridged_no_card    — no scorecard exists for that player+date
                             (expected: pre-scorecard eras)
      unbridged_no_customer— record has no customer_id to even look with
    """
    from collections import Counter
    from itertools import groupby
    formulas = get_scoring_formulas(db_path=db_path)
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        recs = conn.execute(
            """SELECT hr.id, hr.player_name, hr.customer_id, hr.round_date,
                      hr.adjusted_score, hr.scoring_round_id,
                      sr.holes_played, sr.tee_id
               FROM handicap_rounds hr
               LEFT JOIN scoring_rounds sr ON sr.id = hr.scoring_round_id
               ORDER BY hr.scoring_round_id, hr.id""").fetchall()
        counts: Counter = Counter()
        mismatches: list = []
        orphans: list = []
        bridged = [r for r in recs if r["scoring_round_id"]]
        unbridged = [r for r in recs if not r["scoring_round_id"]]
        for srid, grp_it in groupby(bridged, key=lambda r: r["scoring_round_id"]):
            grp = list(grp_it)
            sp = _nine_totals_for_card(conn, srid, grp[0]["tee_id"], formulas)
            sides = [s for s in ("front", "back") if sp[s]["n"]]
            if len(grp) > len(sides):
                counts["overclaimed_card"] += len(grp) - len(sides)
            claimed: set = set()
            for r in sorted(grp, key=lambda x: x["id"]):
                cands = [s for s in sides if s not in claimed
                         and sp[s]["adj"] == r["adjusted_score"]]
                if cands:
                    claimed.add(cands[0])
                    counts["bridged_reconciled"] += 1
                else:
                    counts["bridged_mismatch"] += 1
                    if len(mismatches) < 40:
                        mismatches.append({
                            "handicap_round_id": r["id"],
                            "player_name": r["player_name"],
                            "round_date": r["round_date"],
                            "stored_adjusted": r["adjusted_score"],
                            "card_nines": {s: {"gross": sp[s]["gross"],
                                               "whs_adjusted": sp[s]["adj"]}
                                           for s in sides},
                            "scoring_round_id": srid,
                        })
        card_days = {f'{r["customer_id"]}:{r["round_date"]}' for r in conn.execute(
            "SELECT customer_id, round_date FROM scoring_rounds "
            "WHERE customer_id IS NOT NULL")}
        for r in unbridged:
            if not r["customer_id"]:
                counts["unbridged_no_customer"] += 1
            elif f'{r["customer_id"]}:{r["round_date"]}' in card_days:
                counts["unbridged_card_exists"] += 1
                if len(orphans) < 40:
                    orphans.append({
                        "handicap_round_id": r["id"],
                        "player_name": r["player_name"],
                        "round_date": r["round_date"],
                        "stored_adjusted": r["adjusted_score"],
                    })
            else:
                counts["unbridged_no_card"] += 1
        return {"total_records": len(recs),
                "counts": dict(counts),
                "bridged_mismatches": mismatches,
                "unbridged_with_cards": orphans,
                "note": "READ-ONLY audit. bridged_mismatch + "
                        "unbridged_card_exists are the review queues; "
                        "unbridged_no_card is expected for eras with no "
                        "imported scorecards."}


def _cleanup_empty_scoring_rounds(conn: sqlite3.Connection) -> None:
    """Delete zero-hole scoring rounds (tee-sheet no-show/WD artifacts the
    importer stored before v2.26.1), reset their handicap bridges, and
    close their discrepancy action items. Idempotent."""
    _ensure_scoring_tables(conn)
    rows = conn.execute(
        """SELECT id, player_name FROM scoring_rounds
           WHERE COALESCE(holes_played, 0) = 0""").fetchall()
    for r in rows:
        conn.execute(
            "UPDATE handicap_rounds SET scoring_round_id = NULL WHERE scoring_round_id = ?",
            (r["id"],))
        conn.execute("DELETE FROM scoring_holes WHERE scoring_round_id = ?", (r["id"],))
        conn.execute("DELETE FROM scoring_rounds WHERE id = ?", (r["id"],))
        conn.execute(
            """UPDATE action_items SET status = 'completed'
               WHERE status = 'open'
                 AND subject = ?""",
            (f"Scorecard discrepancy: {r['player_name']} (round {r['id']})",))
        logger.info("Removed empty scorecard: %r (round %s) — tee-sheet "
                    "artifact, no holes played", r["player_name"], r["id"])
    conn.commit()


def import_gg_scorecards(tournament_url: str, event_code: str | None = None,
                         round_key: str | None = None,
                         round_date: str | None = None,
                         source: str | None = None,
                         db_path: str | Path = DB_PATH) -> dict:
    """Import every player scorecard from a GG tournament page.

    Idempotent: re-import replaces holes for existing (aggregate, player)
    rows. Commits courses/tees, scoring rounds/holes, raw archives, cid
    resolution, event linkage (by code), and handicap_rounds bridging.

    round_key: the GG league round id — REQUIRED for multi-round days
    (Hill Country Matches has six rounds all dated the same Saturday);
    the cross-tournament dedupe scopes to it so different rounds of the
    same day don't collapse into one. Omit for ordinary one-round events.

    round_date: explicit round date for ARCHIVE imports whose event has
    no Tracker events row (GG-history Phase B). Without it the
    cross-tournament dedupe has nothing to scope on (round_date NULL
    never matches in SQL) and ALL Net + ALL Gross would double-import
    every player. An event_code hit still wins over this value.

    source: scoring_rounds.source tag for new rows ('gg_history:<sub>'
    for archive walks); existing rows keep their original tag.
    """
    import zlib
    from golf_genius_sync import fetch_tournament_scorecards
    data = fetch_tournament_scorecards(tournament_url)

    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        event_id, event_date = None, round_date
        if event_code:
            # Exact full-name match FIRST (v2.188.6: championship events —
            # "TGF SAN ANTONIO CHAMPIONSHIP" — carry no [sa]N.N code, so
            # the prefix pattern below can never find them and the
            # imported rounds landed with event_id NULL, invisible to MVP
            # and the payouts assembly), then the code-prefix convention.
            ev = conn.execute(
                """SELECT id, event_date, course FROM events
                   WHERE LOWER(item_name) = LOWER(?) ORDER BY id LIMIT 1""",
                (event_code.strip(),)).fetchone()
            if not ev:
                ev = conn.execute(
                    """SELECT id, event_date, course FROM events
                       WHERE item_name LIKE ? ORDER BY id LIMIT 1""",
                    (event_code.strip() + " %",)).fetchone()
            if ev:
                event_id, event_date = ev["id"], ev["event_date"]

        for url, body in data["raw"]:
            conn.execute("INSERT INTO gg_raw_archive (url, body_gz) VALUES (?, ?)",
                         (url, zlib.compress(body.encode("utf-8"))))

        imported = replaced = upgraded = unresolved = skipped = bridged = 0
        skipped_empty = 0
        verified_ids: list = []
        for p in data["players"]:
            if not p.get("player_name") or not p.get("holes"):
                continue
            # A card with no strokes on any hole is a tee-sheet artifact
            # (no-show/WD left on the sheet — GG publishes it with sums of
            # 0), not a scoring record. Don't store it.
            if not any(h.get("strokes") is not None for h in p["holes"].values()):
                skipped_empty += 1
                continue
            cid = _resolve_scoring_player(conn, p["player_name"])
            existing = conn.execute(
                """SELECT id FROM scoring_rounds
                   WHERE gg_aggregate_id = ? AND player_name = ?""",
                (p.get("gg_aggregate_id"), p["player_name"])).fetchone()
            # One physical round appears under EVERY GG game for that day
            # (ALL Net, ALL Gross, Individual Net, Skins, ...) with a
            # different aggregate id. The first tournament to bring a
            # player's card owns the row; later tournaments only FILL
            # players still missing — except a richer card UPGRADES a
            # poorer one: a net-game card (carries playing handicap +
            # strokes-received dots) replaces a stored raw-gross card for
            # the same physical round, never the reverse. Recipe: ALL Net
            # first (full field with handicaps), ALL Gross to fill anyone
            # left (raw-score baseline).
            is_upgrade = False
            if not existing:
                dup = conn.execute(
                    """SELECT id, playing_handicap, holes_played FROM scoring_rounds
                       WHERE (round_date = ? OR (event_id IS NOT NULL AND event_id = ?))
                         AND COALESCE(gg_league_round_id, '') = ?
                         AND (customer_id = ? OR LOWER(player_name) = LOWER(?))""",
                    (event_date, event_id, round_key or "",
                     cid or -1, p["player_name"])).fetchone()
                if dup:
                    incoming_holes = sum(1 for h in p["holes"].values()
                                         if h.get("strokes") is not None)
                    # Upgrade a stored card when the incoming one is richer:
                    # (a) it carries a playing handicap and the stored card
                    # didn't (a net card upgrades a raw-gross one), or
                    # (b) it scored MORE holes than the stored card. Case (b)
                    # is the self-heal path for a card grabbed mid-round
                    # before GG finished score entry: GG re-keys the
                    # tournament's aggregate ids when the round finalizes, so
                    # the complete card arrives under a NEW aggregate id and
                    # would otherwise be skipped as "other tournament",
                    # freezing the partial card forever (a9.18 Forest Creek,
                    # 2026-07-14: imported at 11pm with 4-7 of 9 holes).
                    handicap_upgrade = (p.get("playing_handicap") is not None
                                        and dup["playing_handicap"] is None)
                    completeness_upgrade = incoming_holes > (dup["holes_played"] or 0)
                    if handicap_upgrade or completeness_upgrade:
                        existing = dup
                        is_upgrade = True
                    else:
                        skipped += 1
                        continue
            if not cid:
                unresolved += 1
            course_id = tee_id = None
            if p.get("tee"):
                course_id, tee_id = _upsert_course_tee(conn, p["tee"])
            holes_played = sum(1 for h in p["holes"].values()
                               if h.get("strokes") is not None)
            # FREEZE INVARIANT (H-2, Kerry standing rule — past-events-frozen +
            # retroactivity boundary): scoring_rounds.playing_handicap is the
            # EVENT-TIME playing handicap and is authoritative for that round's
            # results. It is set here at import from GG's own value and is only
            # ever re-carried from GG on a completeness/handicap upgrade — it is
            # NEVER recomputed by our handicap engine. When the untether path
            # begins writing OUR self-computed playing handicap, it MUST write
            # only where playing_handicap IS NULL (mirror the handicap_upgrade
            # guard above) so a later index/cap change can never retroactively
            # alter a frozen round. Our projection (project_playing_handicaps)
            # stays read-only shadow until then.
            if existing:
                srid = existing["id"]
                conn.execute("DELETE FROM scoring_holes WHERE scoring_round_id = ?", (srid,))
                conn.execute(
                    """UPDATE scoring_rounds SET customer_id=?, event_id=?, gg_event_id=?,
                           gg_aggregate_id=?, gg_profile_id=?, round_date=?, course_id=?,
                           tee_id=?, holes_played=?, playing_handicap=?, gross=?, net=?,
                           flight=?, gg_league_round_id=?
                       WHERE id=?""",
                    (cid, event_id, p.get("gg_event_id"), p.get("gg_aggregate_id"),
                     p.get("gg_profile_id"), event_date, course_id, tee_id, holes_played,
                     p.get("playing_handicap"), p.get("gross"), p.get("net"),
                     p.get("flight"), round_key, srid))
                if is_upgrade:
                    upgraded += 1
                else:
                    replaced += 1
                verified_ids.append(srid)
            else:
                cur = conn.execute(
                    """INSERT INTO scoring_rounds
                           (customer_id, player_name, event_id, gg_event_id,
                            gg_aggregate_id, gg_profile_id, round_date,
                            course_id, tee_id, holes_played, playing_handicap,
                            gross, net, flight, gg_league_round_id, source)
                       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                    (cid, p["player_name"], event_id, p.get("gg_event_id"),
                     p.get("gg_aggregate_id"), p.get("gg_profile_id"),
                     event_date, course_id, tee_id, holes_played,
                     p.get("playing_handicap"), p.get("gross"), p.get("net"),
                     p.get("flight"), round_key, source or "gg"))
                srid = cur.lastrowid
                imported += 1
                verified_ids.append(srid)
            # Plus-handicap players (ph stored negative) GIVE BACK a stroke
            # on each of the |ph| easiest holes played (highest stroke
            # index) — WHS allocation. GG renders no dot for these, so the
            # fact is derived from the tee's stroke indexes; verification
            # then re-checks it against GG's own net markings.
            give_back: dict = {}
            ph = p.get("playing_handicap")
            if ph is not None and ph < 0 and tee_id:
                played = {h for h, v in p["holes"].items()
                          if v.get("strokes") is not None}
                si = {r["hole_number"]: r["stroke_index"] for r in conn.execute(
                    """SELECT hole_number, stroke_index FROM course_tee_holes
                       WHERE tee_id = ? AND stroke_index IS NOT NULL""",
                    (tee_id,)) if r["hole_number"] in played}
                for hole in sorted(si, key=lambda h: -si[h])[:int(round(-ph))]:
                    give_back[hole] = -1
            for hole, h in sorted(p["holes"].items()):
                conn.execute(
                    """INSERT OR REPLACE INTO scoring_holes
                           (scoring_round_id, hole_number, strokes,
                            strokes_received, gg_result)
                       VALUES (?,?,?,?,?)""",
                    (srid, hole, h.get("strokes"),
                     give_back.get(hole, h.get("dots") or 0),
                     h.get("result")))
            # Bridge the legacy derived layer (same physical round) — by
            # RECONCILIATION, not date alone: on multi-round days the old
            # date-only claim let the first card swallow every record
            # (Comanche CREEKS/HILLS/VALLEY, Kerry 2026-07-14).
            if cid and event_date:
                bridged += _bridge_handicap_records(
                    conn, srid, cid, event_date, tee_id, db_path=db_path)
        conn.commit()

    # Parallel-run verification (admin requirement): every imported card is
    # checked against GG's own numbers immediately; discrepancies surface as
    # COO action items (category 'scoring') with the failing checks in the
    # summary, so nothing drifts silently. Fix path is usually re-import or
    # course/tee data curation, described in the item.
    n_ok = 0
    discrepancies = []
    with _connect(db_path) as conn:
        for srid in verified_ids:
            try:
                v = verify_scoring_round(srid, db_path=db_path)
            except Exception as exc:
                v = {"all_ok": False, "player_name": "?",
                     "checks": [{"check": "verify_crashed", "ok": False,
                                 "detail": str(exc)}]}
            subject = f"Scorecard discrepancy: {v.get('player_name')} (round {srid})"
            if v.get("all_ok"):
                n_ok += 1
                # A re-import that now verifies clean closes its own alarm
                conn.execute(
                    """UPDATE action_items SET status = 'completed'
                       WHERE status = 'open' AND subject = ?""", (subject,))
                continue
            fails = "; ".join(f"{c['check']}: {c['detail']}"
                              for c in v.get("checks", []) if not c.get("ok"))
            discrepancies.append({"scoring_round_id": srid,
                                  "player_name": v.get("player_name"),
                                  "failed_checks": fails})
            exists = conn.execute(
                """SELECT 1 FROM action_items
                   WHERE subject = ? AND status = 'open' LIMIT 1""",
                (subject,)).fetchone()
            if not exists:
                conn.execute(
                    """INSERT INTO action_items
                           (subject, from_name, summary, urgency, category)
                       VALUES (?, 'Scorecard verifier', ?, 'medium', 'scoring')""",
                    (subject, f"Tracker vs Golf Genius mismatch — {fails}. "
                              f"Usual fixes: re-import the tournament, or "
                              f"correct the course/tee data."))
        conn.commit()

    # HOLE-IN-ONE watch (Kerry 2026-07-20: "look out for any actual hole
    # in one's"). An ace — strokes = 1 on any imported hole — raises a
    # HIGH action item: the accrued HIO pot pays out to that player, and
    # recording the payout under category 'hio' is what drains the pot
    # (get_hio_pot). Dedup by subject so re-imports don't re-alarm.
    holes_in_one = []
    with _connect(db_path) as conn:
        for srid in verified_ids:
            for h in conn.execute(
                    """SELECT sh.hole_number, sr.player_name, sr.round_date
                         FROM scoring_holes sh
                         JOIN scoring_rounds sr ON sr.id = sh.scoring_round_id
                        WHERE sh.scoring_round_id = ? AND sh.strokes = 1""",
                    (srid,)):
                ace = {"player_name": h["player_name"],
                       "hole": h["hole_number"], "date": h["round_date"],
                       "scoring_round_id": srid}
                holes_in_one.append(ace)
                subject = (f"HOLE-IN-ONE: {h['player_name']} — "
                           f"hole {h['hole_number']} ({h['round_date']})")
                if not conn.execute(
                        """SELECT 1 FROM action_items
                           WHERE subject = ? AND status IN
                                 ('open', 'in_progress') LIMIT 1""",
                        (subject,)).fetchone():
                    conn.execute(
                        """INSERT INTO action_items
                               (subject, from_name, summary, urgency,
                                category)
                           VALUES (?, 'HIO watch', ?, 'high', 'scoring')""",
                        (subject,
                         "An ACE was imported on this scorecard. The "
                         "running Hole-In-One pot pays out — verify on the "
                         "GG board, then record the payout with category "
                         "'hio' so the pot drains correctly."))
                    logger.info("HOLE-IN-ONE detected: %s hole %s (%s)",
                                h["player_name"], h["hole_number"],
                                h["round_date"])
        conn.commit()

    logger.info("Scorecard import: %d new, %d replaced, %d upgraded with "
                "handicap, %d skipped (round already captured from another "
                "tournament), %d unresolved names, %d handicap rounds "
                "bridged, %d verified OK, %d discrepancies",
                imported, replaced, upgraded, skipped, unresolved, bridged,
                n_ok, len(discrepancies))
    # Refresh the self-computed MVP / TGF MVP badges for this event's day as
    # soon as its scores land — the badge no longer waits on the GG MVP
    # import (Kerry 2026-07-16). Never let a badge-refresh failure break an
    # otherwise-successful import.
    if event_id and (imported or replaced or upgraded):
        try:
            with _connect(db_path) as _c:
                ev = _c.execute("SELECT item_name FROM events WHERE id = ?",
                                (event_id,)).fetchone()
            if ev:
                recompute_computed_mvps(ev["item_name"], db_path=db_path)
        except Exception:
            logger.warning("MVP recompute after import failed", exc_info=True)
    return {"imported": imported, "replaced": replaced,
            "upgraded_with_handicap": upgraded,
            "skipped_other_tournament": skipped,
            "skipped_empty_cards": skipped_empty,
            "unresolved_names": unresolved, "handicap_rounds_bridged": bridged,
            "players_seen": len(data["players"]), "event_id": event_id,
            "verified_ok": n_ok, "discrepancies": discrepancies}


def get_scoring_rounds_list(player: str | None = None, event: str | None = None,
                            customer_id: int | None = None, limit: int = 100,
                            db_path: str | Path = DB_PATH) -> list:
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        _ensure_mvp_tables(conn)
        clauses, params = ["1=1"], []
        if player:
            clauses.append("sr.player_name LIKE ?"); params.append(f"%{player}%")
        if customer_id:
            clauses.append("sr.customer_id = ?"); params.append(customer_id)
        if event:
            clauses.append("e.item_name LIKE ?"); params.append(f"%{event}%")
        params.append(limit)
        # Badge source of truth is our self-computed determination
        # (event_mvp_computed; Kerry-ratified 2026-07-16) with split -> Co-.
        # The GG import (event_mvps) is a fallback for any round we haven't
        # computed yet, so no historical badge is lost during rollout.
        rows = conn.execute(
            f"""SELECT sr.*, e.item_name AS event_name, c.name AS course_name,
                       t.tee_name, t.slope, t.rating,
                       (SELECT MIN(h.hole_number) FROM scoring_holes h
                        WHERE h.scoring_round_id = sr.id
                          AND h.strokes IS NOT NULL) AS first_hole,
                       EXISTS(SELECT 1 FROM mvp_computed_events ce
                              WHERE ce.event_id = sr.event_id) AS _ev_computed,
                       (SELECT cm.split FROM event_mvp_computed cm
                          WHERE cm.event_id = sr.event_id
                            AND cm.customer_id = sr.customer_id
                            AND cm.kind = 'mvp') AS _cm_split,
                       (SELECT ct.split FROM event_mvp_computed ct
                          WHERE ct.event_id = sr.event_id
                            AND ct.customer_id = sr.customer_id
                            AND ct.kind = 'tgf_mvp') AS _ct_split,
                       EXISTS(SELECT 1 FROM event_mvps m
                              WHERE m.event_id = sr.event_id
                                AND m.customer_id = sr.customer_id
                                AND m.kind = 'mvp') AS _gg_mvp,
                       EXISTS(SELECT 1 FROM event_mvps m
                              WHERE m.event_id = sr.event_id
                                AND m.customer_id = sr.customer_id
                                AND m.kind = 'tgf_mvp') AS _gg_tgf,
                       EXISTS(SELECT 1 FROM event_mvps m
                              WHERE m.event_id = sr.event_id) AS _gg_event_has,
                       (SELECT COUNT(*) FROM event_mvps m
                          WHERE m.event_id = sr.event_id
                            AND m.kind = 'mvp') AS _gg_mvp_ct,
                       (SELECT COUNT(*) FROM event_mvps m
                          WHERE m.event_id = sr.event_id
                            AND m.kind = 'tgf_mvp') AS _gg_tgf_ct,
                       e.event_date AS _event_date
                FROM scoring_rounds sr
                LEFT JOIN events e ON e.id = sr.event_id
                LEFT JOIN courses c ON c.course_id = sr.course_id
                LEFT JOIN course_tees t ON t.tee_id = sr.tee_id
                WHERE {' AND '.join(clauses)}
                ORDER BY sr.round_date DESC, sr.id DESC LIMIT ?""",
            params).fetchall()
        out = []
        for r in rows:
            d = dict(r)
            ev_computed = d.pop("_ev_computed", 0)
            cm, ct = d.pop("_cm_split", None), d.pop("_ct_split", None)
            gg_mvp, gg_tgf = d.pop("_gg_mvp", 0), d.pop("_gg_tgf", 0)
            gg_event_has = d.pop("_gg_event_has", 0)
            gg_mvp_ct = d.pop("_gg_mvp_ct", 0) or 0
            gg_tgf_ct = d.pop("_gg_tgf_ct", 0) or 0
            event_date = d.pop("_event_date", None)
            # RETROACTIVITY BOUNDARY (Kerry): our self-computed determination
            # is authoritative from a9.18/s9.18 (2026-07-14) FORWARD (inclusive
            # — a9.18 is the first event the cap affects). For events BEFORE
            # the boundary GG is bible — our post-cap handicaps must not alter a
            # frozen result — so where GG recorded an MVP we defer to it; our
            # computation only fills events GG never recorded (import lag, e.g.
            # s9.17). Events with no date fall to "ours" only when GG is silent.
            use_ours = (ev_computed and
                        ((event_date and event_date >= _MVP_RETRO_BOUNDARY)
                         or not gg_event_has))
            if use_ours:
                d["mvp"] = 1 if cm == 0 else 0
                d["co_mvp"] = 1 if cm == 1 else 0
                d["tgf_mvp"] = 1 if ct == 0 else 0
                d["co_tgf_mvp"] = 1 if ct == 1 else 0
            else:
                # GG-authoritative (pre-boundary): if GG recorded MORE THAN
                # ONE winner it was a SPLIT (co-MVP) — GG paid the pot in
                # shares rather than applying a tiebreaker (e.g. s18.6 Flying L,
                # Young/Sanford/Fehlis $33.33 each). This split is an OUTLIER
                # to our Net->Gross tiebreaker; going forward only an admin
                # override should force a split over our computed sole winner.
                d["mvp"] = 1 if (gg_mvp and gg_mvp_ct <= 1) else 0
                d["co_mvp"] = 1 if (gg_mvp and gg_mvp_ct > 1) else 0
                d["tgf_mvp"] = 1 if (gg_tgf and gg_tgf_ct <= 1) else 0
                d["co_tgf_mvp"] = 1 if (gg_tgf and gg_tgf_ct > 1) else 0
            out.append(d)
        return out


def get_scorecard(scoring_round_id: int, db_path: str | Path = DB_PATH) -> dict | None:
    """Full card: facts + per-hole derivations through the formula layer."""
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        sr = conn.execute(
            """SELECT sr.*, e.item_name AS event_name, c.name AS course_name,
                      t.tee_name, t.slope, t.rating
               FROM scoring_rounds sr
               LEFT JOIN events e ON e.id = sr.event_id
               LEFT JOIN courses c ON c.course_id = sr.course_id
               LEFT JOIN course_tees t ON t.tee_id = sr.tee_id
               WHERE sr.id = ?""", (scoring_round_id,)).fetchone()
        if not sr:
            return None
        holes = conn.execute(
            """SELECT sh.hole_number, sh.strokes, sh.strokes_received,
                      sh.gg_result, cth.par, cth.yardage, cth.stroke_index
               FROM scoring_holes sh
               LEFT JOIN course_tee_holes cth
                 ON cth.tee_id = ? AND cth.hole_number = sh.hole_number
               WHERE sh.scoring_round_id = ? ORDER BY sh.hole_number""",
            (sr["tee_id"], scoring_round_id)).fetchall()
    formulas = get_scoring_formulas(db_path)
    out_holes = []
    totals = {"stableford_net": 0, "stableford_gross": 0, "adjusted_gross": 0}
    for h in holes:
        d = compute_hole_derivations(h["par"], h["strokes"],
                                     h["strokes_received"] or 0, formulas)
        row = dict(h) | d
        out_holes.append(row)
        if d["stableford_net"] is not None:
            totals["stableford_net"] += d["stableford_net"]
            totals["stableford_gross"] += d["stableford_gross"]
            totals["adjusted_gross"] += d["adjusted_strokes"] or 0
    round_out = dict(sr)
    # Play order for the scorecard renderers (Kerry 2026-08-03: SA champ
    # teed off on the back): first_hole 10 puts the IN block on top.
    round_out["first_hole"] = (
        10 if (round_out.get("holes_played") or 9) > 9
        and _event_first_nine(round_out.get("event_name"),
                              db_path=db_path) == "back" else 1)
    # Per-nine adjusted gross + differential for 18-hole rounds (Kerry
    # 2026-08-03: "18 hole adjusted gross and differentials need to show
    # as 9 hole adjusted and diffs under each 9") — read from the POSTED
    # two-nine handicap rows so the card shows exactly what was banked,
    # each nine against its own GG-course-setup rating/slope.
    nines = []
    if (round_out.get("holes_played") or 9) > 9 and round_out.get("tee_name"):
        try:
            with _connect(db_path) as conn:
                names = {_normalize_player_name(
                    round_out.get("player_name") or "")}
                if round_out.get("customer_id"):
                    for lk in conn.execute(
                            "SELECT player_name FROM handicap_player_links "
                            "WHERE customer_id = ?",
                            (round_out["customer_id"],)).fetchall():
                        names.add(lk["player_name"])
                qm = ",".join("?" * len(names))
                for hr in conn.execute(
                        f"""SELECT tee_name, adjusted_score, rating, slope,
                                   differential
                            FROM handicap_rounds
                            WHERE player_name IN ({qm}) AND round_date = ?
                              AND tee_name IN (?, ?)
                            ORDER BY id""",
                        (*names, round_out.get("round_date"),
                         f"{round_out['tee_name']} — Front 9",
                         f"{round_out['tee_name']} — Back 9")).fetchall():
                    nines.append({
                        "nine": ("front" if "Front" in (hr["tee_name"] or "")
                                 else "back"),
                        "adjusted_gross": hr["adjusted_score"],
                        "rating": hr["rating"], "slope": hr["slope"],
                        "differential": hr["differential"]})
        except Exception:
            logger.warning("per-nine scorecard lookup failed", exc_info=True)
    return {"round": round_out, "holes": out_holes, "derived_totals": totals,
            "nines": nines or None, "formulas": formulas}


def verify_scoring_round(scoring_round_id: int,
                         db_path: str | Path = DB_PATH) -> dict:
    """Parallel-run checks against GG's own numbers (admin requirement):
    stored sums vs recomputed, net vs gross-minus-handicap, and GG's
    par-relative markings vs our par data."""
    card = get_scorecard(scoring_round_id, db_path=db_path)
    if not card:
        return {"error": f"scoring_round {scoring_round_id} not found"}
    r, holes = card["round"], card["holes"]
    checks = []
    def chk(name, ok, detail):
        checks.append({"check": name, "ok": bool(ok), "detail": detail})
    strokes = [h["strokes"] for h in holes if h["strokes"] is not None]
    front = sum(h["strokes"] for h in holes
                if h["strokes"] is not None and h["hole_number"] <= 9)
    total = sum(strokes)
    chk("gross_sum", r["gross"] is None or total == r["gross"],
        f"holes sum {total} vs GG gross {r['gross']}")
    if r["gross"] is not None and r["net"] is not None and r["playing_handicap"] is not None:
        chk("net_equals_gross_minus_handicap",
            abs((r["gross"] - r["playing_handicap"]) - r["net"]) < 0.01,
            f"{r['gross']} - {r['playing_handicap']} vs GG net {r['net']}")
    # GG's circle/square markings are NET-relative (verified on live data:
    # 2 strokes on a par 3 WITH a handicap dot renders double_circle = net
    # eagle) — so compare against net_vs_par, not gross vs par
    mismatches = []
    for h in holes:
        if h["par"] is None or h["strokes"] is None:
            continue
        vs = h["net_vs_par"]
        expected = ("double_circle" if vs <= -2 else
                    "simple_circle" if vs == -1 else
                    "simple_square" if vs == 1 else
                    "double_square" if vs >= 2 else None)
        if (h["gg_result"] or None) != expected:
            mismatches.append(f"hole {h['hole_number']}: net_vs_par {vs} "
                              f"gg={h['gg_result']} expected={expected}")
    chk("gg_net_markings_match_course_par", not mismatches,
        "; ".join(mismatches) or "all holes consistent")
    return {"scoring_round_id": scoring_round_id,
            "player_name": r["player_name"], "checks": checks,
            "all_ok": all(c["ok"] for c in checks),
            "derived_totals": card["derived_totals"]}


# ═══════════════════════════════════════════════════════════════════════
# LIVE SCORING TEST CENTER (admin sandbox) — Stage 1 of the untether plan
#
# Everything below writes ONLY to the ls_test_* tables. No production row
# is ever created, updated, or deleted by this surface: seeding from a real
# event COPIES scoring_rounds/scoring_holes into the sandbox and remembers
# the source round id so the parity harness can diff against it. See
# docs/claude/live-scoring-test-center.md.
#
# Tables are created lazily (the _ensure_pairing_tables pattern) so live
# deployments self-migrate on first use and init_db's boot path is
# untouched. Per Guiding Principle 6 every table that references a person
# carries customer_id as a FK to customers(customer_id).
# ═══════════════════════════════════════════════════════════════════════

def _ensure_live_scoring_tables(conn: sqlite3.Connection) -> None:
    conn.execute("""CREATE TABLE IF NOT EXISTS ls_test_sessions (
        id            INTEGER PRIMARY KEY AUTOINCREMENT,
        name          TEXT NOT NULL,
        source_kind   TEXT NOT NULL DEFAULT 'synthetic',
        event_id      INTEGER REFERENCES events(id),
        event_name    TEXT,
        round_date    TEXT,
        course_id     INTEGER REFERENCES courses(course_id),
        tee_id        INTEGER REFERENCES course_tees(tee_id),
        holes         INTEGER NOT NULL DEFAULT 9,
        championship  INTEGER NOT NULL DEFAULT 0,
        notes         TEXT,
        created_by    TEXT,
        created_at    TEXT DEFAULT (datetime('now')),
        updated_at    TEXT DEFAULT (datetime('now')))""")
    conn.execute("""CREATE TABLE IF NOT EXISTS ls_test_players (
        id               INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id       INTEGER NOT NULL REFERENCES ls_test_sessions(id)
                             ON DELETE CASCADE,
        customer_id      INTEGER REFERENCES customers(customer_id),
        player_name      TEXT NOT NULL,
        playing_handicap REAL,
        handicap_index   REAL,
        flight           TEXT,
        team_num         INTEGER,
        buys_net         INTEGER NOT NULL DEFAULT 1,
        buys_gross       INTEGER NOT NULL DEFAULT 1,
        is_member        INTEGER NOT NULL DEFAULT 1,
        source_round_id  INTEGER REFERENCES scoring_rounds(id),
        created_at       TEXT DEFAULT (datetime('now')))""")
    conn.execute("""CREATE TABLE IF NOT EXISTS ls_test_holes (
        id               INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id       INTEGER NOT NULL REFERENCES ls_test_sessions(id)
                             ON DELETE CASCADE,
        player_id        INTEGER NOT NULL REFERENCES ls_test_players(id)
                             ON DELETE CASCADE,
        hole_number      INTEGER NOT NULL,
        strokes          INTEGER,
        strokes_received INTEGER,
        UNIQUE(player_id, hole_number))""")
    # Per-session course overrides. A synthetic session has no real tee, and
    # a seeded session may want a what-if par/stroke-index. Rows here WIN
    # over course_tee_holes; absent, the real tee data is used.
    conn.execute("""CREATE TABLE IF NOT EXISTS ls_test_course_holes (
        session_id   INTEGER NOT NULL REFERENCES ls_test_sessions(id)
                         ON DELETE CASCADE,
        hole_number  INTEGER NOT NULL,
        par          INTEGER,
        yardage      INTEGER,
        stroke_index INTEGER,
        PRIMARY KEY (session_id, hole_number))""")
    # CTP / Longest Putt are measured on course and HIO payouts are
    # adjudicated — none of the three is derivable from hole scores, so the
    # sandbox records them by hand exactly as a manager would.
    conn.execute("""CREATE TABLE IF NOT EXISTS ls_test_contests (
        id          INTEGER PRIMARY KEY AUTOINCREMENT,
        session_id  INTEGER NOT NULL REFERENCES ls_test_sessions(id)
                        ON DELETE CASCADE,
        kind        TEXT NOT NULL,
        hole_number INTEGER,
        player_id   INTEGER REFERENCES ls_test_players(id) ON DELETE CASCADE,
        customer_id INTEGER REFERENCES customers(customer_id),
        note        TEXT,
        created_at  TEXT DEFAULT (datetime('now')),
        UNIQUE(session_id, kind, hole_number))""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_ls_players_session "
                 "ON ls_test_players(session_id)")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_ls_holes_session "
                 "ON ls_test_holes(session_id)")


_LS_DEFAULT_NINE = [
    # A neutral par-36 nine used when a synthetic session names no course:
    # two par 3s, two par 5s, stroke indexes 1-9. Overridable per session.
    (1, 4, 380, 3), (2, 3, 155, 9), (3, 5, 520, 1), (4, 4, 400, 5),
    (5, 4, 365, 7), (6, 3, 190, 8), (7, 4, 430, 2), (8, 4, 375, 6),
    (9, 5, 505, 4),
]


def _ls_tee_holes(conn: sqlite3.Connection, tee_id: int | None) -> list[dict]:
    """Course holes for a tee, MERGED across the tee's per-nine ratings.

    TGF plays nines, and Golf Genius rates each nine separately — so one
    physical tee becomes several `course_tees` rows, each holding only its
    own nine's holes. The Quarry's "1 - Gold Tee" is three rows: the front
    nine (slope 117 / rating 34.2, holes 1-9) and the back nine (128 / 35.6,
    holes 10-18), plus a re-rating of the front. Reading a single tee_id
    therefore returns HALF a golf course, which on an 18-hole event silently
    scores nine holes.

    So: collect holes from every tee row sharing this tee's course AND tee
    name, preferring the requested tee_id and then the most recent rating
    when a hole appears in more than one row (par / yardage / stroke index
    agree between re-ratings, so the tie-break is cosmetic).

    Stroke indexes stored on these rows are already 18-hole-scoped (the
    Quarry's front nine carries the odds 1-17, the back the evens 2-18), so
    the merged set is the correct basis for allocating handicap strokes
    across all 18 holes — TGF's rule: course/playing handicaps come off the
    18-hole rating and apply across all 18. (Handicap DIFFERENTIALS are a
    separate path keyed to the 9-hole ratings; nothing here touches them.)
    """
    if not tee_id:
        return []
    row = conn.execute(
        "SELECT course_id, tee_name FROM course_tees WHERE tee_id = ?",
        (tee_id,)).fetchone()
    if not row:
        return []
    siblings = [r["tee_id"] for r in conn.execute(
        """SELECT tee_id FROM course_tees
           WHERE course_id = ? AND tee_name IS ?
           ORDER BY tee_id DESC""",
        (row["course_id"], row["tee_name"])).fetchall()]
    # Requested tee wins, then newest rating.
    order = [tee_id] + [t for t in siblings if t != tee_id]
    merged: dict = {}
    for t in order:
        for h in conn.execute(
                """SELECT hole_number, par, yardage, stroke_index
                   FROM course_tee_holes WHERE tee_id = ?""", (t,)).fetchall():
            cur = merged.setdefault(h["hole_number"], {
                "hole_number": h["hole_number"], "par": None,
                "yardage": None, "stroke_index": None, "from_tee": t})
            for col in ("par", "yardage", "stroke_index"):
                if cur[col] is None and h[col] is not None:
                    cur[col] = h[col]
    return [merged[k] for k in sorted(merged)]


def _ls_touch(conn: sqlite3.Connection, session_id: int) -> None:
    conn.execute("UPDATE ls_test_sessions SET updated_at = datetime('now') "
                 "WHERE id = ?", (session_id,))


def ls_list_sessions(db_path: str | Path = DB_PATH) -> list:
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        rows = conn.execute(
            """SELECT s.*, c.name AS course_name, t.tee_name,
                      (SELECT COUNT(*) FROM ls_test_players p
                        WHERE p.session_id = s.id) AS n_players,
                      (SELECT COUNT(*) FROM ls_test_holes h
                        WHERE h.session_id = s.id AND h.strokes IS NOT NULL)
                        AS n_scores
               FROM ls_test_sessions s
               LEFT JOIN courses c ON c.course_id = s.course_id
               LEFT JOIN course_tees t ON t.tee_id = s.tee_id
               ORDER BY s.updated_at DESC, s.id DESC""").fetchall()
        return [dict(r) for r in rows]


def ls_create_session(name: str, holes: int = 9, event_name: str | None = None,
                      course_id: int | None = None, tee_id: int | None = None,
                      championship: bool = False, notes: str | None = None,
                      created_by: str | None = None,
                      db_path: str | Path = DB_PATH) -> dict:
    """Create an empty synthetic sandbox session."""
    holes = 18 if int(holes or 9) > 9 else 9
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        _ensure_scoring_tables(conn)
        event_id = None
        if event_name:
            ev = conn.execute(
                "SELECT id FROM events WHERE item_name = ? COLLATE NOCASE",
                (event_name,)).fetchone()
            event_id = ev["id"] if ev else None
        sid = conn.execute(
            """INSERT INTO ls_test_sessions
                   (name, source_kind, event_id, event_name, course_id, tee_id,
                    holes, championship, notes, created_by)
               VALUES (?, 'synthetic', ?, ?, ?, ?, ?, ?, ?, ?)""",
            (name.strip() or "Untitled test", event_id, event_name, course_id,
             tee_id, holes, 1 if championship else 0, notes,
             created_by)).lastrowid
        # Seed the course holes: the real tee when one was named, else the
        # neutral nine (mirrored onto the back for an 18).
        tee_rows = _ls_tee_holes(conn, tee_id)
        if tee_rows:
            for r in tee_rows[:holes]:
                conn.execute(
                    """INSERT OR REPLACE INTO ls_test_course_holes
                           (session_id, hole_number, par, yardage, stroke_index)
                       VALUES (?, ?, ?, ?, ?)""",
                    (sid, r["hole_number"], r["par"], r["yardage"],
                     r["stroke_index"]))
        else:
            for h, par, yd, si in _LS_DEFAULT_NINE:
                conn.execute(
                    """INSERT OR REPLACE INTO ls_test_course_holes
                           (session_id, hole_number, par, yardage, stroke_index)
                       VALUES (?, ?, ?, ?, ?)""", (sid, h, par, yd, si))
                if holes == 18:
                    conn.execute(
                        """INSERT OR REPLACE INTO ls_test_course_holes
                               (session_id, hole_number, par, yardage, stroke_index)
                           VALUES (?, ?, ?, ?, ?)""",
                        (sid, h + 9, par, yd, si + 9))
        conn.commit()
        return {"session_id": sid, "name": name, "holes": holes}


def _ls_is_member(current_player_status: str | None,
                  item_user_status: str | None) -> int:
    """1 when the player is a MEMBER, by the roster — not by the label.

    Kerry 2026-07-30: "1st Timer is what throws you because with our current
    system a 1st timer could be either a guest or a member. But if you match
    it against the current roster, you'll see that they aren't members yet."

    So `customers.current_player_status` decides it whenever we have a
    customer record. `items.user_status` is a per-order SNAPSHOT (the
    identity-drift class in CLAUDE.md) and is only a fallback for a
    registration with no linked customer — and then only to rule someone
    OUT, never in.

    This gates hole-in-one eligibility: guests and first timers pay in but
    cannot win. Getting it wrong is a money error, so the ambiguous label
    never decides on its own.
    """
    st = (current_player_status or "").strip().lower()
    if st:
        return 1 if st in _MEMBER_PLAYER_STATUSES else 0
    label = (item_user_status or "").strip().upper()
    return 0 if label in ("GUEST", "1ST TIMER", "FIRST TIMER",
                          "1ST-TIMER", "FIRSTTIMER") else 1


def _ls_seed_from_registrations(conn: sqlite3.Connection, ev: dict,
                                name: str | None,
                                created_by: str | None) -> dict:
    """Seed a session for an event that has NOT been played yet.

    The field comes from active registrations rather than scorecards: buyer
    flags from what each player actually bought, teams from the pairings if
    they exist, the course from the event, and NO scores. That makes the
    pre-flight possible — confirm course coverage, buyer counts and flights
    days before the round — and on the day `ls_refresh_session_from_gg`
    fills in the scores and playing handicaps.
    """
    holes = 9
    row = conn.execute(
        """SELECT holes, COUNT(*) c FROM items
           WHERE LOWER(item_name) = LOWER(?) AND holes IS NOT NULL
             AND COALESCE(transaction_status,'active') = 'active'
           GROUP BY holes ORDER BY c DESC LIMIT 1""",
        (ev["item_name"],)).fetchone()
    if row and str(row["holes"]).strip() == "18":
        holes = 18
    elif _event_holes_type(ev["item_name"], ev.get("format")) == 18:
        holes = 18

    # Course + the tee the field usually plays there. _ls_tee_holes then
    # merges that tee's per-nine ratings into a full 18 where needed.
    course_id = ev.get("course_id")
    if not course_id and ev.get("course"):
        c = conn.execute(
            """SELECT course_id FROM courses WHERE LOWER(name) = LOWER(?)
               UNION SELECT course_id FROM course_aliases
               WHERE LOWER(alias_name) = LOWER(?) LIMIT 1""",
            (ev["course"], ev["course"])).fetchone()
        course_id = c["course_id"] if c else None
    tee_id = None
    if course_id:
        t = conn.execute(
            """SELECT sr.tee_id, COUNT(*) c FROM scoring_rounds sr
               WHERE sr.course_id = ? AND sr.tee_id IS NOT NULL
               GROUP BY sr.tee_id ORDER BY c DESC LIMIT 1""",
            (course_id,)).fetchone()
        tee_id = t["tee_id"] if t else None

    championship = 1 if "championship" in ev["item_name"].lower() else 0
    sid = conn.execute(
        """INSERT INTO ls_test_sessions
               (name, source_kind, event_id, event_name, round_date,
                course_id, tee_id, holes, championship, notes, created_by)
           VALUES (?, 'seeded', ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
        (name or f"{ev['item_name']} — shadow", ev["id"], ev["item_name"],
         ev.get("event_date"), course_id, tee_id, holes, championship,
         "Seeded from REGISTRATIONS — this event has no scorecards yet. "
         "Use Pull from GG on the day to bring in scores and handicaps.",
         created_by)).lastrowid

    for r in _ls_tee_holes(conn, tee_id):
        conn.execute(
            """INSERT OR REPLACE INTO ls_test_course_holes
                   (session_id, hole_number, par, yardage, stroke_index)
               VALUES (?, ?, ?, ?, ?)""",
            (sid, r["hole_number"], r["par"], r["yardage"], r["stroke_index"]))

    net_buyers = _event_game_buyers(conn, ev["item_name"], "NET")["buyers"]
    gross_buyers = _event_game_buyers(conn, ev["item_name"], "GROSS")["buyers"]
    teams = {}
    for p in conn.execute(
            "SELECT group_num, player_name FROM event_pairings WHERE event_id = ?",
            (ev["id"],)).fetchall():
        teams[(p["player_name"] or "").strip().lower()] = p["group_num"]

    seen, seeded = set(), 0
    # MEMBERSHIP comes from the customer's CURRENT status, not the item's
    # user_status label (Kerry 2026-07-30). "1st TIMER" is ambiguous — a
    # first timer can be a guest OR a member — so the label cannot decide
    # it; the roster does. is_member gates HIO eligibility (guests pay in
    # but cannot win), so guessing here would be a money error.
    for it in conn.execute(
            """SELECT i.customer_id, i.customer, i.user_status,
                      c.current_player_status
               FROM items i
               LEFT JOIN customers c ON c.customer_id = i.customer_id
               WHERE LOWER(i.item_name) = LOWER(?)
                 AND COALESCE(i.transaction_status,'active') NOT IN
                     ('credited','refunded','transferred','rsvp_only')
               ORDER BY i.customer""", (ev["item_name"],)).fetchall():
        cid = it["customer_id"]
        key = cid or (it["customer"] or "").strip().lower()
        if not key or key in seen:
            continue
        seen.add(key)
        nm = it["customer"] or ""
        if cid:
            c = conn.execute(
                "SELECT TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS customer_name FROM customers WHERE customer_id = ?",
                (cid,)).fetchone()
            if c and (c["customer_name"] or "").strip():
                nm = c["customer_name"].strip()
        conn.execute(
            """INSERT INTO ls_test_players
                   (session_id, customer_id, player_name, playing_handicap,
                    flight, team_num, buys_net, buys_gross, is_member)
               VALUES (?, ?, ?, NULL, NULL, ?, ?, ?, ?)""",
            (sid, cid, nm, teams.get(nm.strip().lower()),
             1 if (cid and cid in net_buyers) else 0,
             1 if (cid and cid in gross_buyers) else 0,
             _ls_is_member(it["current_player_status"], it["user_status"])))
        seeded += 1
    conn.commit()
    return {"session_id": sid, "event": ev["item_name"], "holes": holes,
            "players_seeded": seeded, "championship": bool(championship),
            "source": "registrations",
            "net_buyers": sum(1 for c in net_buyers),
            "gross_buyers": sum(1 for c in gross_buyers),
            "teams_from_pairings": bool(teams),
            "note": "No scorecards yet — seeded from registrations. Scores "
                    "and playing handicaps arrive with Pull from GG."}


def ls_seed_session_from_event(event_name: str, name: str | None = None,
                               created_by: str | None = None,
                               db_path: str | Path = DB_PATH) -> dict:
    """Clone a real event's imported scorecards into a sandbox session.

    Copies the FACTS only — gross strokes per hole, GG's own handicap dots,
    the playing handicap — and remembers each player's `source_round_id` so
    `ls_parity` can diff our engine against what GG recorded. Teams come
    from the event's saved pairings; NET/GROSS buyer flags come from the
    same eligibility rules the Games tab uses. Production data is READ, never
    written.
    """
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        _ensure_scoring_tables(conn)
        ev = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        ev = dict(ev)
        rounds = [dict(r) for r in conn.execute(
            """SELECT * FROM scoring_rounds WHERE event_id = ?
               ORDER BY player_name""", (ev["id"],)).fetchall()]
        if not rounds:
            # UPCOMING event — no cards yet. Seed the FIELD from the
            # registrations so the session can be set up and checked before
            # the round (course coverage, buyer counts, flights), then "Pull
            # from GG" fills the scores on the day. Without this the
            # pre-flight is impossible: the only events you could shadow
            # were ones already played.
            return _ls_seed_from_registrations(conn, ev, name, created_by)
        # The tee/course the field actually played: most common non-null.
        def _mode(key):
            vals = [r[key] for r in rounds if r[key] is not None]
            return max(set(vals), key=vals.count) if vals else None
        course_id, tee_id = _mode("course_id"), _mode("tee_id")
        holes = 18 if max((r["holes_played"] or 0) for r in rounds) > 9 else 9

        # A City/TGF Championship scores on the +1-per-net-category schedule
        # (get_championship_formulas). Deriving it from the event name beats
        # asking — Principle 1 — and the Field tab can still override.
        championship = 1 if "championship" in ev["item_name"].lower() else 0

        sid = conn.execute(
            """INSERT INTO ls_test_sessions
                   (name, source_kind, event_id, event_name, round_date,
                    course_id, tee_id, holes, championship, notes, created_by)
               VALUES (?, 'seeded', ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (name or f"{ev['item_name']} — shadow",
             ev["id"], ev["item_name"], _mode("round_date"), course_id, tee_id,
             holes, championship,
             "Seeded from imported GG scorecards. Scores are FACTS copied "
             "from scoring_holes; every game below is recomputed by our own "
             "engine.", created_by)).lastrowid

        # Merged across the tee's per-nine ratings — an 18-hole round needs
        # the front-nine row AND the back-nine row (see _ls_tee_holes).
        for r in _ls_tee_holes(conn, tee_id):
            conn.execute(
                """INSERT OR REPLACE INTO ls_test_course_holes
                       (session_id, hole_number, par, yardage, stroke_index)
                   VALUES (?, ?, ?, ?, ?)""",
                (sid, r["hole_number"], r["par"], r["yardage"],
                 r["stroke_index"]))

        net_buyers = _event_game_buyers(conn, ev["item_name"], "NET")["buyers"]
        gross_buyers = _event_game_buyers(conn, ev["item_name"], "GROSS")["buyers"]
        teams = {}
        for p in conn.execute(
                """SELECT group_num, player_name FROM event_pairings
                   WHERE event_id = ?""", (ev["id"],)).fetchall():
            teams[(p["player_name"] or "").strip().lower()] = p["group_num"]

        seeded = 0
        for r in rounds:
            cid = r["customer_id"]
            pid = conn.execute(
                """INSERT INTO ls_test_players
                       (session_id, customer_id, player_name, playing_handicap,
                        flight, team_num, buys_net, buys_gross, is_member,
                        source_round_id)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?)""",
                (sid, cid, r["player_name"], r["playing_handicap"],
                 r["flight"], teams.get((r["player_name"] or "").strip().lower()),
                 1 if (cid and cid in net_buyers) else 0,
                 1 if (cid and cid in gross_buyers) else 0,
                 r["id"])).lastrowid
            for h in conn.execute(
                    """SELECT hole_number, strokes, strokes_received
                       FROM scoring_holes WHERE scoring_round_id = ?""",
                    (r["id"],)).fetchall():
                conn.execute(
                    """INSERT OR REPLACE INTO ls_test_holes
                           (session_id, player_id, hole_number, strokes,
                            strokes_received)
                       VALUES (?, ?, ?, ?, ?)""",
                    (sid, pid, h["hole_number"], h["strokes"],
                     h["strokes_received"]))
            seeded += 1
        conn.commit()
        return {"session_id": sid, "event": ev["item_name"], "holes": holes,
                "players_seeded": seeded, "championship": bool(championship),
                "net_buyers": sum(1 for r in rounds
                                  if r["customer_id"] in net_buyers),
                "gross_buyers": sum(1 for r in rounds
                                    if r["customer_id"] in gross_buyers),
                "teams_from_pairings": bool(teams)}


def ls_refresh_session_from_gg(session_id: int,
                               tournament_url: str | None = None,
                               db_path: str | Path = DB_PATH) -> dict:
    """Re-pull a seeded session's scores from GG, IN PLACE — the live path.

    Seeding is a snapshot; this is what makes the board move during a round.
    Pass `tournament_url` to fetch fresh cards from Golf Genius first (the
    normal live use: GG re-keys aggregate ids as a round progresses, and
    `import_gg_scorecards`'s completeness rule replaces a partial card with
    a more complete one). Omit it to re-sync from whatever is already in
    `scoring_rounds` — useful when the import ran from another surface.

    Refresh semantics, chosen so a mid-round refresh never destroys manager
    work: SCORES, handicap dots, and playing handicaps come from GG every
    time. Everything the manager may have adjusted by hand — teams, flight
    overrides, buyer flags, member status, the championship toggle, recorded
    CTP/Longest Putt/HIO winners — is PRESERVED. Players who appear in GG
    for the first time are added; players who vanish from GG are kept (a
    card pulled mid-round can disappear when GG re-keys, and silently
    dropping a player mid-event would be worse than a stale row).
    """
    data = ls_get_session(session_id, db_path=db_path)
    if not data:
        return {"error": f"session {session_id} not found"}
    meta = data["session"]
    if meta.get("source_kind") != "seeded" or not meta.get("event_name"):
        return {"error": "refresh needs a session seeded from a real event"}

    imported = None
    if tournament_url:
        code = (meta["event_name"] or "").split()[0] if meta["event_name"] else None
        try:
            imported = import_gg_scorecards(tournament_url, event_code=code,
                                            db_path=db_path)
        except Exception as e:  # a GG hiccup must not blank the board
            logger.exception("Test Center GG refresh failed")
            return {"error": f"GG import failed: {e}",
                    "hint": "the board still shows the last good pull"}

    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        _ensure_scoring_tables(conn)
        ev = conn.execute("SELECT id, item_name FROM events WHERE id = ?",
                          (meta["event_id"],)).fetchone()
        if not ev:
            return {"error": "the seeded event no longer exists"}
        rounds = [dict(r) for r in conn.execute(
            "SELECT * FROM scoring_rounds WHERE event_id = ? ORDER BY player_name",
            (ev["id"],)).fetchall()]

        # Existing sandbox players, keyed both ways: a refresh must re-find a
        # player whose GG aggregate id changed mid-round (id-first, then name).
        existing = [dict(r) for r in conn.execute(
            "SELECT * FROM ls_test_players WHERE session_id = ?",
            (session_id,)).fetchall()]
        by_cid = {p["customer_id"]: p for p in existing if p["customer_id"]}
        by_name = {(p["player_name"] or "").strip().lower(): p for p in existing}

        net_buyers = _event_game_buyers(conn, ev["item_name"], "NET")["buyers"]
        gross_buyers = _event_game_buyers(conn, ev["item_name"], "GROSS")["buyers"]
        teams = {}
        for p in conn.execute(
                "SELECT group_num, player_name FROM event_pairings WHERE event_id = ?",
                (ev["id"],)).fetchall():
            teams[(p["player_name"] or "").strip().lower()] = p["group_num"]

        added, updated, holes_written = 0, 0, 0
        for r in rounds:
            key = (r["player_name"] or "").strip().lower()
            row = by_cid.get(r["customer_id"]) if r["customer_id"] else None
            row = row or by_name.get(key)
            if row:
                # GG owns the handicap and the source card; the manager owns
                # everything else, so only these two columns are rewritten.
                conn.execute(
                    """UPDATE ls_test_players
                       SET playing_handicap = ?, source_round_id = ?,
                           customer_id = COALESCE(?, customer_id)
                       WHERE id = ?""",
                    (r["playing_handicap"], r["id"], r["customer_id"], row["id"]))
                pid = row["id"]
                updated += 1
            else:
                cid = r["customer_id"]
                pid = conn.execute(
                    """INSERT INTO ls_test_players
                           (session_id, customer_id, player_name,
                            playing_handicap, flight, team_num, buys_net,
                            buys_gross, is_member, source_round_id)
                       VALUES (?, ?, ?, ?, ?, ?, ?, ?, 1, ?)""",
                    (session_id, cid, r["player_name"], r["playing_handicap"],
                     r["flight"], teams.get(key),
                     1 if (cid and cid in net_buyers) else 0,
                     1 if (cid and cid in gross_buyers) else 0,
                     r["id"])).lastrowid
                added += 1
            # Scores are replaced wholesale from GG — a hole GG no longer
            # carries is cleared rather than left stale.
            conn.execute("DELETE FROM ls_test_holes WHERE player_id = ?", (pid,))
            for h in conn.execute(
                    """SELECT hole_number, strokes, strokes_received
                       FROM scoring_holes WHERE scoring_round_id = ?""",
                    (r["id"],)).fetchall():
                conn.execute(
                    """INSERT OR REPLACE INTO ls_test_holes
                           (session_id, player_id, hole_number, strokes,
                            strokes_received)
                       VALUES (?, ?, ?, ?, ?)""",
                    (session_id, pid, h["hole_number"], h["strokes"],
                     h["strokes_received"]))
                holes_written += 1

        # Re-accrete the course: an 18-hole tee block published mid-event
        # fills holes the session was seeded without (the Quarry front-nine
        # case). Existing rows are only overwritten where we now know more.
        tee_id = meta.get("tee_id")
        newest_tee = None
        tee_vals = [r["tee_id"] for r in rounds if r["tee_id"]]
        if tee_vals:
            newest_tee = max(set(tee_vals), key=tee_vals.count)
        for src_tee in {t for t in (tee_id, newest_tee) if t}:
            for r in _ls_tee_holes(conn, src_tee):
                conn.execute(
                    """INSERT INTO ls_test_course_holes
                           (session_id, hole_number, par, yardage, stroke_index)
                       VALUES (?, ?, ?, ?, ?)
                       ON CONFLICT(session_id, hole_number) DO UPDATE SET
                           par = COALESCE(ls_test_course_holes.par, excluded.par),
                           yardage = COALESCE(ls_test_course_holes.yardage,
                                              excluded.yardage),
                           stroke_index = COALESCE(
                               ls_test_course_holes.stroke_index,
                               excluded.stroke_index)""",
                    (session_id, r["hole_number"], r["par"], r["yardage"],
                     r["stroke_index"]))
        if newest_tee and newest_tee != tee_id:
            conn.execute("UPDATE ls_test_sessions SET tee_id = ? WHERE id = ?",
                         (newest_tee, session_id))
        _ls_touch(conn, session_id)
        conn.commit()

    out = {"session_id": session_id, "event": ev["item_name"],
           "gg_cards": len(rounds), "players_added": added,
           "players_updated": updated, "hole_scores": holes_written}
    if imported is not None:
        out["import"] = {k: imported.get(k) for k in
                         ("imported", "updated", "upgraded_with_handicap",
                          "skipped_other_tournament", "skipped_empty_cards",
                          "verified_ok", "discrepancies") if k in imported}
    return out


def ls_get_session(session_id: int, db_path: str | Path = DB_PATH) -> dict | None:
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        s = conn.execute(
            """SELECT s.*, c.name AS course_name, t.tee_name, t.slope, t.rating
               FROM ls_test_sessions s
               LEFT JOIN courses c ON c.course_id = s.course_id
               LEFT JOIN course_tees t ON t.tee_id = s.tee_id
               WHERE s.id = ?""", (session_id,)).fetchone()
        if not s:
            return None
        holes = [dict(r) for r in conn.execute(
            """SELECT hole_number, par, yardage, stroke_index
               FROM ls_test_course_holes WHERE session_id = ?
               ORDER BY hole_number""", (session_id,)).fetchall()]
        players = [dict(r) for r in conn.execute(
            """SELECT * FROM ls_test_players WHERE session_id = ?
               ORDER BY team_num IS NULL, team_num, player_name""",
            (session_id,)).fetchall()]
        scores = {}
        for r in conn.execute(
                """SELECT player_id, hole_number, strokes, strokes_received
                   FROM ls_test_holes WHERE session_id = ?""",
                (session_id,)).fetchall():
            scores.setdefault(r["player_id"], {})[r["hole_number"]] = {
                "strokes": r["strokes"],
                "strokes_received": r["strokes_received"]}
        for p in players:
            p["scores"] = scores.get(p["id"], {})
        contests = [dict(r) for r in conn.execute(
            """SELECT * FROM ls_test_contests WHERE session_id = ?
               ORDER BY kind, hole_number""", (session_id,)).fetchall()]
        return {"session": dict(s), "holes": holes, "players": players,
                "contests": contests}


def ls_update_session(session_id: int, fields: dict,
                      db_path: str | Path = DB_PATH) -> dict:
    allowed = {"name", "notes", "championship", "holes"}
    sets, vals = [], []
    for k, v in (fields or {}).items():
        if k not in allowed:
            continue
        if k == "championship":
            v = 1 if v else 0
        if k == "holes":
            v = 18 if int(v or 9) > 9 else 9
        sets.append(f"{k} = ?")
        vals.append(v)
    if not sets:
        return {"updated": 0}
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        conn.execute(f"UPDATE ls_test_sessions SET {', '.join(sets)}, "
                     f"updated_at = datetime('now') WHERE id = ?",
                     vals + [session_id])
        conn.commit()
        return {"updated": 1}


def ls_delete_session(session_id: int, db_path: str | Path = DB_PATH) -> dict:
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        for tbl in ("ls_test_contests", "ls_test_holes", "ls_test_players",
                    "ls_test_course_holes"):
            conn.execute(f"DELETE FROM {tbl} WHERE session_id = ?", (session_id,))
        conn.execute("DELETE FROM ls_test_sessions WHERE id = ?", (session_id,))
        conn.commit()
        return {"deleted": session_id}


def ls_set_course_hole(session_id: int, hole_number: int, par: int | None = None,
                       yardage: int | None = None,
                       stroke_index: int | None = None,
                       db_path: str | Path = DB_PATH) -> dict:
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        conn.execute(
            """INSERT INTO ls_test_course_holes
                   (session_id, hole_number, par, yardage, stroke_index)
               VALUES (?, ?, ?, ?, ?)
               ON CONFLICT(session_id, hole_number) DO UPDATE SET
                   par = COALESCE(excluded.par, par),
                   yardage = COALESCE(excluded.yardage, yardage),
                   stroke_index = COALESCE(excluded.stroke_index, stroke_index)""",
            (session_id, hole_number, par, yardage, stroke_index))
        _ls_touch(conn, session_id)
        conn.commit()
        return {"session_id": session_id, "hole": hole_number}


def ls_add_player(session_id: int, player_name: str,
                  customer_id: int | None = None,
                  playing_handicap: float | None = None,
                  handicap_index: float | None = None,
                  flight: str | None = None, team_num: int | None = None,
                  buys_net: bool = True, buys_gross: bool = True,
                  is_member: bool = True,
                  db_path: str | Path = DB_PATH) -> dict:
    """Add one player. When `customer_id` is given the canonical name wins
    (Principle 6: identity is the id, the name is a display label)."""
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        if customer_id:
            row = conn.execute(
                "SELECT TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS customer_name FROM customers WHERE customer_id = ?",
                (customer_id,)).fetchone()
            if row and (row["customer_name"] or "").strip():
                player_name = row["customer_name"].strip()
        pid = conn.execute(
            """INSERT INTO ls_test_players
                   (session_id, customer_id, player_name, playing_handicap,
                    handicap_index, flight, team_num, buys_net, buys_gross,
                    is_member)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (session_id, customer_id, (player_name or "").strip() or "Player",
             playing_handicap, handicap_index, flight, team_num,
             1 if buys_net else 0, 1 if buys_gross else 0,
             1 if is_member else 0)).lastrowid
        _ls_touch(conn, session_id)
        conn.commit()
        return {"player_id": pid, "player_name": player_name}


def ls_update_player(player_id: int, fields: dict,
                     db_path: str | Path = DB_PATH) -> dict:
    allowed = {"player_name", "playing_handicap", "handicap_index", "flight",
               "team_num", "buys_net", "buys_gross", "is_member"}
    sets, vals = [], []
    for k, v in (fields or {}).items():
        if k not in allowed:
            continue
        if k in ("buys_net", "buys_gross", "is_member"):
            v = 1 if v else 0
        sets.append(f"{k} = ?")
        vals.append(v)
    if not sets:
        return {"updated": 0}
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        conn.execute(f"UPDATE ls_test_players SET {', '.join(sets)} WHERE id = ?",
                     vals + [player_id])
        row = conn.execute("SELECT session_id FROM ls_test_players WHERE id = ?",
                           (player_id,)).fetchone()
        if row:
            _ls_touch(conn, row["session_id"])
        conn.commit()
        return {"updated": 1}


def ls_delete_player(player_id: int, db_path: str | Path = DB_PATH) -> dict:
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        conn.execute("DELETE FROM ls_test_holes WHERE player_id = ?", (player_id,))
        conn.execute("DELETE FROM ls_test_contests WHERE player_id = ?", (player_id,))
        conn.execute("DELETE FROM ls_test_players WHERE id = ?", (player_id,))
        conn.commit()
        return {"deleted": player_id}


def ls_set_score(session_id: int, player_id: int, hole_number: int,
                 strokes: int | None,
                 strokes_received: int | None = None,
                 db_path: str | Path = DB_PATH) -> dict:
    """Record (or clear, with strokes=None) one hole for one player.

    This is the Stage-2 write path in miniature: a single hole, entered by a
    person, with the leaderboard recomputed on read. `strokes_received` is
    left NULL unless explicitly supplied so the engine derives the dots from
    the playing handicap — the untethered behaviour.
    """
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        if strokes is None and strokes_received is None:
            conn.execute("DELETE FROM ls_test_holes WHERE player_id = ? "
                         "AND hole_number = ?", (player_id, hole_number))
        else:
            conn.execute(
                """INSERT INTO ls_test_holes
                       (session_id, player_id, hole_number, strokes,
                        strokes_received)
                   VALUES (?, ?, ?, ?, ?)
                   ON CONFLICT(player_id, hole_number) DO UPDATE SET
                       strokes = excluded.strokes,
                       strokes_received = COALESCE(excluded.strokes_received,
                                                   ls_test_holes.strokes_received)""",
                (session_id, player_id, hole_number, strokes, strokes_received))
        _ls_touch(conn, session_id)
        conn.commit()
        return {"session_id": session_id, "player_id": player_id,
                "hole": hole_number, "strokes": strokes}


def ls_clear_scores(session_id: int, db_path: str | Path = DB_PATH) -> dict:
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        n = conn.execute("DELETE FROM ls_test_holes WHERE session_id = ?",
                         (session_id,)).rowcount
        _ls_touch(conn, session_id)
        conn.commit()
        return {"cleared": n}


def ls_autoplay(session_id: int, through_hole: int | None = None,
                seed: int | None = None, overwrite: bool = False,
                db_path: str | Path = DB_PATH) -> dict:
    """Fill in simulated scores so the live surface has something to move.

    Plays every player through `through_hole` (default: the whole round).
    Existing scores are kept unless `overwrite` — so repeatedly advancing
    the through-hole reproduces a round unfolding in real time, which is the
    behaviour the live leaderboard needs to be tested against.
    """
    from . import live_scoring as _ls
    rng = random.Random(seed)
    data = ls_get_session(session_id, db_path=db_path)
    if not data:
        return {"error": f"session {session_id} not found"}
    holes = data["holes"] or []
    limit = through_hole or (holes[-1]["hole_number"] if holes else 0)
    written = 0
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        for p in data["players"]:
            for h in holes:
                hn = h["hole_number"]
                if hn > limit:
                    continue
                existing = p["scores"].get(hn, {}).get("strokes")
                if existing is not None and not overwrite:
                    continue
                strokes = _ls.simulate_strokes(h["par"] or 4,
                                               p["playing_handicap"], rng)
                conn.execute(
                    """INSERT INTO ls_test_holes
                           (session_id, player_id, hole_number, strokes)
                       VALUES (?, ?, ?, ?)
                       ON CONFLICT(player_id, hole_number) DO UPDATE SET
                           strokes = excluded.strokes""",
                    (session_id, p["id"], hn, strokes))
                written += 1
        _ls_touch(conn, session_id)
        conn.commit()
    return {"session_id": session_id, "through_hole": limit,
            "scores_written": written}


def ls_record_contest(session_id: int, kind: str, hole_number: int | None,
                      player_id: int | None, note: str | None = None,
                      db_path: str | Path = DB_PATH) -> dict:
    """Record a manually-adjudicated contest result (CTP / Longest Putt /
    HIO claim). `player_id` of None clears the slot."""
    kind = (kind or "").strip().lower()
    if kind not in ("ctp", "longest_putt", "hio"):
        return {"error": f"unknown contest kind: {kind}"}
    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        if player_id is None:
            conn.execute("DELETE FROM ls_test_contests WHERE session_id = ? "
                         "AND kind = ? AND hole_number IS ?",
                         (session_id, kind, hole_number))
            conn.commit()
            return {"cleared": True, "kind": kind, "hole": hole_number}
        row = conn.execute("SELECT customer_id FROM ls_test_players WHERE id = ?",
                           (player_id,)).fetchone()
        conn.execute(
            """INSERT INTO ls_test_contests
                   (session_id, kind, hole_number, player_id, customer_id, note)
               VALUES (?, ?, ?, ?, ?, ?)
               ON CONFLICT(session_id, kind, hole_number) DO UPDATE SET
                   player_id = excluded.player_id,
                   customer_id = excluded.customer_id,
                   note = excluded.note""",
            (session_id, kind, hole_number, player_id,
             row["customer_id"] if row else None, note))
        _ls_touch(conn, session_id)
        conn.commit()
        return {"kind": kind, "hole": hole_number, "player_id": player_id}


def ls_build_state(session_id: int, db_path: str | Path = DB_PATH) -> dict | None:
    """Sandbox rows -> the engine's plain-data round state."""
    data = ls_get_session(session_id, db_path=db_path)
    if not data:
        return None
    holes = [{"hole": h["hole_number"], "par": h["par"],
              "yardage": h["yardage"], "stroke_index": h["stroke_index"]}
             for h in data["holes"]]
    players = []
    for p in data["players"]:
        scores = {hn: v["strokes"] for hn, v in p["scores"].items()
                  if v["strokes"] is not None}
        received = {hn: v["strokes_received"] for hn, v in p["scores"].items()
                    if v["strokes_received"] is not None}
        players.append({
            "key": str(p["id"]), "customer_id": p["customer_id"],
            "name": p["player_name"], "playing_handicap": p["playing_handicap"],
            "flight": p["flight"], "team": p["team_num"],
            "buys_net": bool(p["buys_net"]), "buys_gross": bool(p["buys_gross"]),
            "is_member": bool(p["is_member"]),
            "scores": scores, "strokes_received": received})
    return {"holes": holes, "players": players, "meta": data["session"],
            "contests": data["contests"]}


def ls_flight_lab(event_name: str, game: str = "individual_net",
                  overrides: dict | None = None,
                  db_path: str | Path = DB_PATH) -> dict:
    """Run one event's real field through BOTH flighting modes, side by side.

    The flighting rule is the last piece of event scoring we do not own —
    `determine_event_game_results` takes GG's labels and refuses to guess
    (`flights_unknown`) when they are missing. This computes what each mode
    WOULD produce from raw handicap indexes, and where GG's own captured
    flights exist (`gg_game_flights`, per game, from the game's own
    leaderboard) it grades both modes against them.

    That grading is the point: it derives the rule from what was actually
    done across past events instead of from recollection. Read-only.
    """
    from . import live_scoring as _ls
    cfg = dict(_ls.SEED_FLIGHT_CONFIG)
    for k, v in (overrides or {}).items():
        if k in ("min_flight_size", "tie_direction", "index_scale",
                 "bands", "low_flight_ceiling") and v not in (None, ""):
            cfg[k] = v
    kind = "GROSS" if game in ("individual_gross", "skins") else "NET"

    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        _ensure_gg_game_flights_tables(conn)
        ev = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        ev = dict(ev)
        buyers = _event_game_buyers(conn, ev["item_name"], kind)["buyers"]
        gg_labels = {}
        for r in conn.execute(
                "SELECT customer_id, player_name, flight_label FROM "
                "gg_game_flights WHERE event_id = ? AND game = ?",
                (ev["id"], game)).fetchall():
            if r["customer_id"]:
                gg_labels[r["customer_id"]] = r["flight_label"]

    # Current index per player. get_all_handicap_players keys by name, so
    # resolve through customer_name (canonical) with a player_name fallback.
    idx_by_name = {}
    for p in get_all_handicap_players(db_path):
        for nm in (p.get("customer_name"), p.get("player_name")):
            if nm:
                idx_by_name.setdefault(nm.strip().lower(), p)
    scale = str(cfg.get("index_scale") or "9")
    field = []
    for cid, name in buyers.items():
        rec = idx_by_name.get((name or "").strip().lower())
        idx = None
        if rec:
            idx = (rec.get("handicap_index_18") if scale == "18"
                   else rec.get("handicap_index"))
        field.append({"key": str(cid), "customer_id": cid, "name": name,
                      "index": idx, "gg_flight": gg_labels.get(cid)})

    n = len(field)
    holes_key = "18" if _event_holes_type(ev["item_name"], ev.get("format")) == 18 else "9"
    gcfg = (_ls.SEED_LIVE_SCORING_CONFIG["games"].get(game) or {})
    count = _ls._bands_lookup((gcfg.get("flight_bands") or {}).get(holes_key), n, 1)
    min_buyers = (gcfg.get("min_buyers") or {}).get(holes_key)

    out = {"event": ev["item_name"], "game": game, "kind": kind,
           "holes": holes_key, "buyers": n, "matrix_flights": count,
           "index_scale": scale, "config": cfg,
           "gg_flights_captured": len(gg_labels),
           "field": sorted(field, key=lambda p: (
               p["index"] if p["index"] is not None else 999, p["name"] or "")),
           "modes": {}}
    if min_buyers is not None and n < min_buyers:
        out["inactive"] = (f"{game} activates at {min_buyers} buyers on an "
                           f"{holes_key}-hole event; {n} bought in.")

    for mode in ("equal_size", "fixed_bands"):
        plan = _ls.flight_plan(field, count, game=game, config=cfg, mode=mode)
        if gg_labels:
            # Grade against GG: same PARTITION, not the same labels — GG may
            # name flights differently while cutting in the same places.
            ours = {}
            for f in plan["flights"]:
                for m in f["members"]:
                    ours[m["key"]] = f["flight"]
            agree = disagree = 0
            mapping: dict = {}
            for p in field:
                if p["gg_flight"] is None or p["key"] not in ours:
                    continue
                mapping.setdefault(ours[p["key"]], {}).setdefault(
                    p["gg_flight"], 0)
                mapping[ours[p["key"]]][p["gg_flight"]] += 1
            best = {k: max(v, key=v.get) for k, v in mapping.items()}
            for p in field:
                if p["gg_flight"] is None or p["key"] not in ours:
                    continue
                if best.get(ours[p["key"]]) == p["gg_flight"]:
                    agree += 1
                else:
                    disagree += 1
            plan["vs_gg"] = {"agree": agree, "disagree": disagree,
                             "graded": agree + disagree,
                             "match": disagree == 0 and agree > 0,
                             "our_flight_to_gg": best}
        out["modes"][mode] = plan
    return out


def ls_flight_audit(overrides: dict | None = None, limit: int = 400,
                    db_path: str | Path = DB_PATH) -> dict:
    """Grade BOTH flighting modes against GG's own flights, across history.

    CA's method option C step 2 (mailbox #253): rather than specifying the
    flighting rule from recollection, derive it from what was actually done.
    Every event where `gg_game_flights` captured a multi-flight game becomes
    a graded case; the mode that reproduces GG's partition more often is the
    evidence.

    **Disagreement is a finding, not a failure.** A split result most likely
    means the rule changed at some point or differed by chapter, so results
    are reported per event AND aggregated by chapter and by year — never
    collapsed to a single score that would hide exactly that.
    """
    with _connect(db_path) as conn:
        _ensure_gg_game_flights_tables(conn)
        rows = [dict(r) for r in conn.execute(
            """SELECT g.event_id, g.game, e.item_name, e.event_date, e.chapter,
                      COUNT(DISTINCT g.flight_label) AS n_flights,
                      COUNT(*) AS n_players
               FROM gg_game_flights g
               JOIN events e ON e.id = g.event_id
               WHERE g.event_id IS NOT NULL
               GROUP BY g.event_id, g.game
               HAVING n_flights > 1
               ORDER BY e.event_date DESC
               LIMIT ?""", (limit,)).fetchall()]

    out = {"cases": [], "graded": 0, "skipped": 0,
           "by_mode": {"equal_size": {"match": 0, "differ": 0},
                       "fixed_bands": {"match": 0, "differ": 0}},
           "by_chapter": {}, "by_year": {}, "notes": []}
    if not rows:
        out["notes"].append(
            "No multi-flight events found in gg_game_flights. Run the "
            "scoring-flights-import walker first — without captured GG "
            "flights there is nothing to grade against.")
        return out

    for r in rows:
        lab = ls_flight_lab(r["item_name"], r["game"], overrides, db_path=db_path)
        if "error" in lab:
            out["skipped"] += 1
            continue
        case = {"event": r["item_name"], "date": r["event_date"],
                "chapter": r["chapter"], "game": r["game"],
                "gg_flights": r["n_flights"], "gg_players": r["n_players"],
                "our_flight_count": lab.get("matrix_flights"),
                "buyers": lab.get("buyers"), "modes": {}}
        any_graded = False
        for mode, plan in (lab.get("modes") or {}).items():
            v = plan.get("vs_gg")
            if not v or not v.get("graded"):
                continue
            any_graded = True
            case["modes"][mode] = {"agree": v["agree"], "disagree": v["disagree"],
                                   "match": v["match"]}
            bucket = "match" if v["match"] else "differ"
            out["by_mode"][mode][bucket] = out["by_mode"][mode].get(bucket, 0) + 1
            ch = r["chapter"] or "?"
            yr = (r["event_date"] or "?")[:4]
            for key, grp in (("by_chapter", ch), ("by_year", yr)):
                out[key].setdefault(grp, {}).setdefault(
                    mode, {"match": 0, "differ": 0})
                out[key][grp][mode][bucket] += 1
        if any_graded:
            out["graded"] += 1
            out["cases"].append(case)
        else:
            out["skipped"] += 1

    # Say plainly whether the evidence actually separates the two modes.
    eq, fb = out["by_mode"]["equal_size"], out["by_mode"]["fixed_bands"]
    if out["graded"] == 0:
        out["notes"].append("Nothing gradable — every case lacked buyer/index "
                            "data on our side.")
    else:
        out["verdict"] = {
            "equal_size_match_rate": round(eq["match"] / out["graded"], 3),
            "fixed_bands_match_rate": round(fb["match"] / out["graded"], 3)}
        if eq["match"] == fb["match"]:
            out["notes"].append(
                "Both modes score identically — this field set does not "
                "separate them. Not evidence for either.")
        if max(eq["match"], fb["match"]) < out["graded"] * 0.6:
            out["notes"].append(
                "NEITHER mode reproduces GG on most events. Do not tune "
                "parameters to close this — it more likely means the rule "
                "changed over time, differed by chapter, or that flight "
                "COUNT (not the cut lines) is what disagrees. Read the "
                "per-chapter and per-year splits before concluding.")
    return out


def _ls_course_coverage(state: dict) -> dict:
    """Which holes can actually be SCORED, and which are silently dead.

    A hole with no par derives nothing — no vs-par, no Stableford, no net —
    so it contributes zero to every game while looking perfectly normal on
    the board. That is the single most dangerous failure mode of this
    surface, because a half-scored leaderboard is indistinguishable from a
    low-scoring one. The Quarry is the live example: TGF has only ever
    played its BACK nine, so holes 1-9 carry no par or stroke index and an
    18-hole round there would silently score nine holes.

    Stroke index is called out separately: it is not needed for gross, but
    without it handicap dots cannot be allocated, so every NET game is wrong
    rather than merely incomplete.
    """
    holes = state.get("holes") or []
    scored = {h for p in (state.get("players") or [])
              for h, v in (p.get("scores") or {}).items() if v is not None}
    no_par = sorted(h["hole"] for h in holes if h.get("par") is None)
    no_si = sorted(h["hole"] for h in holes if h.get("stroke_index") is None)
    # Only holes people are actually playing make this urgent.
    blind = sorted(h for h in no_par if h in scored)
    out = {"holes": len(holes), "missing_par": no_par,
           "missing_stroke_index": no_si, "scored_but_no_par": blind,
           "ok": not no_par and not no_si, "warnings": []}
    if blind:
        out["warnings"].append(
            f"{len(blind)} hole(s) have SCORES but NO PAR "
            f"({', '.join(str(h) for h in blind)}) — they score ZERO in every "
            f"game and the board is silently short. Import the event's tee "
            f"block from GG (or fill par on the Field & Course tab) before "
            f"trusting any number here.")
    elif no_par:
        out["warnings"].append(
            f"Holes {', '.join(str(h) for h in no_par)} have no par yet — "
            f"they will score zero the moment anyone posts a score on them.")
    if no_si:
        out["warnings"].append(
            f"Holes {', '.join(str(h) for h in no_si)} have no stroke index — "
            f"handicap strokes cannot be allocated there, so every NET game "
            f"is wrong, not just incomplete.")
    return out


def ls_leaderboard(session_id: int, db_path: str | Path = DB_PATH) -> dict:
    """The live leaderboard: every game, computed from raw gross scores."""
    from . import live_scoring as _ls
    state = ls_build_state(session_id, db_path=db_path)
    if not state:
        return {"error": f"session {session_id} not found"}
    meta = state["meta"]
    formulas = (get_championship_formulas(db_path=db_path)
                if meta.get("championship")
                else get_scoring_formulas(db_path))
    board = _ls.compute_leaderboard(state, formulas)
    board["session"] = meta
    board["formulas_used"] = ("championship" if meta.get("championship")
                              else "regular")
    board["course_coverage"] = _ls_course_coverage(state)
    # Fold the hand-recorded CTP / Longest Putt winners onto the CTP slots.
    by_slot = {(c["kind"], c["hole_number"]): c for c in state["contests"]}
    name_by_pid = {str(p["key"]): p["name"] for p in state["players"]}
    for slot in (board["games"]["ctp"]["slots"]
                 + board["games"]["ctp"]["spillover"]):
        rec = by_slot.get((slot["kind"], slot["hole"]))
        slot["winner"] = (name_by_pid.get(str(rec["player_id"]))
                          if rec else None)
        slot["note"] = rec["note"] if rec else None
    return board


def ls_parity(session_id: int, db_path: str | Path = DB_PATH) -> dict:
    """Diff our engine against Golf Genius, player by player.

    Only meaningful on a SEEDED session: each sandbox player carries the
    `source_round_id` of the GG scorecard it was cloned from, and that row's
    stored gross / net / playing handicap — plus the derived Stableford
    totals from `get_scorecard` — are what we diff against. This is the
    Stage-1 confidence gate: parity here is what earns the right to stop
    asking GG.
    """
    from . import live_scoring as _ls
    state = ls_build_state(session_id, db_path=db_path)
    if not state:
        return {"error": f"session {session_id} not found"}
    meta = state["meta"]
    if meta.get("source_kind") != "seeded":
        return {"error": "parity needs a session seeded from a real event — "
                         "a synthetic field has no GG numbers to diff against",
                "source_kind": meta.get("source_kind")}
    formulas = (get_championship_formulas(db_path=db_path)
                if meta.get("championship") else get_scoring_formulas(db_path))
    cards = _ls.build_cards(state, formulas)

    with _connect(db_path) as conn:
        _ensure_live_scoring_tables(conn)
        src = {str(r["id"]): r["source_round_id"] for r in conn.execute(
            "SELECT id, source_round_id FROM ls_test_players WHERE session_id = ?",
            (session_id,)).fetchall()}
    gg_rows = {}
    for key, round_id in src.items():
        if not round_id:
            continue
        card = get_scorecard(round_id, db_path=db_path)
        if not card:
            continue
        r, totals = card["round"], card["derived_totals"]
        gg_rows[key] = {
            "gross": r["gross"], "net": r["net"],
            "playing_handicap": r["playing_handicap"],
            # These two are OUR formula layer applied to GG's stored dots —
            # a mismatch here means the engine read the same card differently,
            # which is a real defect, not a GG disagreement.
            "stableford_net": totals["stableford_net"],
            "stableford_gross": totals["stableford_gross"],
            "strokes_received": {h["hole_number"]: h["strokes_received"]
                                 for h in card["holes"]},
        }
    out = _ls.parity_diff(cards, gg_rows)
    out["session"] = meta
    out["source_rounds"] = len(gg_rows)
    return out


def list_courses(db_path: str | Path = DB_PATH) -> list:
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        rows = conn.execute(
            """SELECT c.course_id, c.name, c.short_name, c.city, c.state,
                      c.status, ch.name AS chapter,
                      COUNT(DISTINCT t.tee_id) AS n_tees,
                      COUNT(DISTINCT sr.id) AS n_rounds
               FROM courses c
               LEFT JOIN chapters ch ON ch.chapter_id = c.chapter_id
               LEFT JOIN course_tees t ON t.course_id = c.course_id
               LEFT JOIN scoring_rounds sr ON sr.course_id = c.course_id
               GROUP BY c.course_id ORDER BY c.name""").fetchall()
        out = []
        for r in rows:
            tees = conn.execute(
                """SELECT tee_id, tee_name, slope, rating, yardage_total
                   FROM course_tees WHERE course_id = ? ORDER BY tee_id""",
                (r["course_id"],)).fetchall()
            out.append(dict(r) | {"tees": [dict(t) for t in tees]})
        return out


def update_course(course_id: int, fields: dict, db_path: str | Path = DB_PATH) -> dict:
    """Admin Courses UI (v2.57.0, Kerry): whitelist-edit a course row.

    Editable: short_name, city, state, status (active/archived), chapter
    (by chapter NAME; empty clears). `name` stays read-only — items/events
    dim-backfills join courses by name, so renames belong to a dedicated
    (alias-aware) flow, not a grid edit.
    """
    allowed = {"short_name", "city", "state", "status", "chapter"}
    bad = set(fields) - allowed
    if bad:
        raise ValueError(f"not editable: {', '.join(sorted(bad))}")
    with _connect(db_path) as conn:
        row = conn.execute("SELECT course_id FROM courses WHERE course_id = ?", (course_id,)).fetchone()
        if not row:
            raise ValueError(f"course {course_id} not found")
        sets, vals = [], []
        for k, v in fields.items():
            v = (str(v).strip() or None) if v is not None else None
            if k == "chapter":
                cid = None
                if v:
                    ch = conn.execute("SELECT chapter_id FROM chapters WHERE LOWER(name) = LOWER(?)", (v,)).fetchone()
                    if not ch:
                        raise ValueError(f"unknown chapter: {v}")
                    cid = ch["chapter_id"]
                sets.append("chapter_id = ?"); vals.append(cid)
            elif k == "status":
                if v not in ("active", "archived"):
                    raise ValueError("status must be active or archived")
                sets.append("status = ?"); vals.append(v)
            elif k == "state":
                if v and len(v) > 2:
                    raise ValueError("state is the 2-letter code")
                sets.append("state = ?"); vals.append((v or "").upper() or None)
            else:
                sets.append(f"{k} = ?"); vals.append(v)
        conn.execute(f"UPDATE courses SET {', '.join(sets)} WHERE course_id = ?", (*vals, course_id))
        conn.commit()
        out = conn.execute(
            """SELECT c.course_id, c.name, c.short_name, c.city, c.state, c.status,
                      ch.name AS chapter
               FROM courses c LEFT JOIN chapters ch ON ch.chapter_id = c.chapter_id
               WHERE c.course_id = ?""", (course_id,)).fetchone()
        return dict(out)


# Kerry's ratified course short names (2026-07-10) — applied ONCE via the
# scoring-course-short-pins bridge command, not at boot, so later manual
# edits in the /courses UI are never overwritten. First matching pattern
# wins; most-specific patterns first.
_COURSE_SHORT_PINS: list = [
    (r"tpc\s+san\s+antonio.*canyons", "TPC | Canyons"),
    (r"tpc\s+san\s+antonio.*oaks", "TPC | Oaks"),
    (r"tpc.*canyons", "TPC | Canyons"),
    (r"tpc.*oaks", "TPC | Oaks"),
    (r"comanche.*creeks?", "Comanche | Creeks"),
    (r"comanche.*hills", "Comanche | Hills"),
    (r"comanche.*valley", "Comanche | Valley"),
    (r"hill\s+country.*creeks?", "Hill Country | Creeks"),
    (r"hill\s+country.*lakes", "Hill Country | Lakes"),
    (r"hill\s+country.*oaks", "Hill Country | Oaks"),
    # Squaw Valley (Glen Rose) has two 18-hole courses — Apache Links and
    # Comanche Lakes. Short them to Links / Lakes (Kerry 2026-07-19). Keyed on
    # "squaw" so they never collide with The Club at Comanche Trace.
    (r"squaw.*(apache|links)", "Squaw Valley | Links"),
    (r"squaw.*(comanche|lakes)", "Squaw Valley | Lakes"),
    # Multi-course Houston facilities — reduce to Facility | Course
    # (Kerry 2026-07-19).
    (r"cypresswood.*tradition", "Cypresswood | Tradition"),
    (r"bentwater.*weiskopf", "Bentwater | Weiskopf"),
    # Silverhorn's formal name is "Silverhorn Golf Club of Texas" — it must
    # match BEFORE the (distinct) Golf Club of Texas course (v2.57.2 fix)
    (r"silverhorn", "Silverhorn"),
    (r"golf\s+club\s+of\s+texas", "GC of Texas"),
    (r"la\s+cantera", "La Cantera | Resort"),
    # Austin's Riverside is not the SA one (v2.57.2 fix)
    (r"riverside.*austin|austin.*riverside", "Riverside | ATX"),
    (r"riverside", "Riverside | SA"),
    (r"olympia\s+hills", "Olympia Hills"),
    (r"black\s*jack", "Black Jack's"),
    (r"brackenridge", "Brackenridge"),
    # "The Golf Club Star Ranch" imported with short_name = the FULL name,
    # which the fill-only-if-empty boot seed skips (Kerry 2026-08-06:
    # shorten to "Star Ranch"). Keyed on "star ranch" so Texas Star Golf
    # Course never matches.
    (r"star\s+ranch", "Star Ranch"),
]


def apply_course_short_name_pins(db_path: str | Path = DB_PATH) -> dict:
    """Apply Kerry's short-name pins to the courses table (one-shot).

    Returns what changed, what already matched, and which pins found no
    course — so the run is verifiable from the bridge response.
    """
    updated, unchanged, ambiguous = [], [], []
    hit_pins = set()
    with _connect(db_path) as conn:
        rows = conn.execute("SELECT course_id, name, short_name FROM courses").fetchall()
        for r in rows:
            nm = (r["name"] or "").lower()
            for i, (pat, short) in enumerate(_COURSE_SHORT_PINS):
                if re.search(pat, nm):
                    hit_pins.add(i)
                    if (r["short_name"] or "") == short:
                        unchanged.append(r["name"])
                    else:
                        conn.execute("UPDATE courses SET short_name = ? WHERE course_id = ?",
                                     (short, r["course_id"]))
                        updated.append({"name": r["name"], "short_name": short,
                                        "was": r["short_name"]})
                    break
        conn.commit()
    inserted = []
    with _connect(db_path) as conn:
        have = {r["name"].strip().lower() for r in conn.execute("SELECT name FROM courses").fetchall()}
        round_names = [r["course_name"] for r in conn.execute(
            "SELECT DISTINCT course_name FROM handicap_rounds "
            "WHERE course_name IS NOT NULL AND TRIM(course_name) != ''").fetchall()]
        for nm in round_names:
            key = nm.strip().lower()
            if key in have:
                continue
            for i, (pat, short) in enumerate(_COURSE_SHORT_PINS):
                if re.search(pat, key):
                    conn.execute("INSERT OR IGNORE INTO courses (name, short_name) VALUES (?, ?)",
                                 (nm.strip(), short))
                    have.add(key)
                    hit_pins.add(i)
                    inserted.append({"name": nm.strip(), "short_name": short})
                    break
        conn.commit()
    missed = [
        {"pattern": pat, "short_name": short}
        for i, (pat, short) in enumerate(_COURSE_SHORT_PINS) if i not in hit_pins
    ]
    return {"updated": updated, "already_set": unchanged,
            "created_from_round_history": inserted, "pins_without_a_course": missed}


def _course_dedup_key(n) -> str:
    """Normalize a course name to a comparison key for dedupe/backfill: strip
    the archived suffix and generic boilerplate so obvious variants of the same
    venue collapse. Advisory — the audit surfaces clusters for human review."""
    s = str(n or "").lower()
    s = re.sub(r"\(old\).*$", " ", s)
    s = re.sub(r"archived on.*$", " ", s)
    s = re.sub(r"\b(the|golf|club|course|country|resort|of|at|conference|"
               r"center|event|gc|spa|yacht|and)\b", " ", s)
    s = re.sub(r"[^a-z0-9]+", " ", s)
    return " ".join(s.split())


def audit_courses(db_path: str | Path | None = None) -> dict:
    """READ-ONLY course-table health (Kerry 2026-07-19). Duplicate clusters in
    `courses` (grouped by normalized key, with per-row scoring-round counts) and
    the handicap_rounds course names that have no matching courses row yet."""
    from collections import defaultdict
    with _connect(db_path) as conn:
        courses = [dict(r) for r in conn.execute(
            "SELECT course_id, name, short_name, status FROM courses").fetchall()]
        srcnt = {r["course_id"]: r["n"] for r in conn.execute(
            "SELECT course_id, COUNT(*) n FROM scoring_rounds "
            "WHERE course_id IS NOT NULL GROUP BY course_id").fetchall()}
        clusters: dict = defaultdict(list)
        for c in courses:
            clusters[_course_dedup_key(c["name"])].append(c)
        dup_clusters = []
        for k, rows in clusters.items():
            if len(rows) > 1:
                rows2 = sorted(rows, key=lambda x: -srcnt.get(x["course_id"], 0))
                dup_clusters.append({
                    "key": k,
                    "total_scoring_rounds": sum(srcnt.get(x["course_id"], 0) for x in rows),
                    "courses": [{"course_id": c["course_id"], "name": c["name"],
                                 "short_name": c["short_name"], "status": c["status"],
                                 "scoring_rounds": srcnt.get(c["course_id"], 0)}
                                for c in rows2]})
        dup_clusters.sort(key=lambda d: -d["total_scoring_rounds"])
        have = {c["name"].strip().lower() for c in courses}
        try:
            have |= {r["alias_name"].strip().lower() for r in conn.execute(
                "SELECT alias_name FROM course_aliases")}
        except Exception:
            pass
        have_keys = {_course_dedup_key(c["name"]) for c in courses}
        missing = []
        for r in conn.execute(
                "SELECT course_name, COUNT(*) n FROM handicap_rounds "
                "WHERE course_name IS NOT NULL AND TRIM(course_name) != '' "
                "GROUP BY course_name").fetchall():
            nm = r["course_name"]
            if nm.strip().lower() in have:
                continue
            missing.append({"course_name": nm, "handicap_rounds": r["n"],
                            "matches_existing_course": _course_dedup_key(nm) in have_keys})
        missing.sort(key=lambda m: -m["handicap_rounds"])
        return {"total_courses": len(courses),
                "duplicate_cluster_count": len(dup_clusters),
                "duplicate_clusters": dup_clusters,
                "missing_from_courses_count": len(missing),
                "handicap_names_missing_from_courses": missing}


def ensure_courses_from_history(dry_run: bool = True,
                                db_path: str | Path | None = None) -> dict:
    """Give every course that appears in handicap_rounds a `courses` row (and
    thus a course_id) — Kerry 2026-07-19. Inserts a row for each distinct
    handicap course name not already present (exact OR by normalized key, so a
    known venue under a different label isn't duplicated). Names whose key
    matches an existing course are withheld for the dedupe review instead.
    short_name comes from the pin list, else derive_course_short_name(). New
    rows carry only name + short_name; chapter/city/rating details are enriched
    later as GG history fills in (Kerry). Idempotent."""
    def short_for(name):
        low = name.lower()
        for pat, short in _COURSE_SHORT_PINS:
            if re.search(pat, low):
                return short
        return derive_course_short_name(name)

    _NINE_FRAGMENTS = {"lakes", "creeks", "oaks", "hills", "valley", "links",
                       "front", "back", "cypress", "tradition", "creek"}

    def looks_like_junk(nm):
        low = nm.strip().lower()
        if re.match(r"^copy of\b", low):            # GG copy-of-event artifact
            return True
        if re.search(r"[-|]\s*\d+\s*$", nm):         # GG "- 2" second instance
            return True
        if len(low.split()) == 1 and low in _NINE_FRAGMENTS:
            return True                              # bare nine fragment ("Lakes")
        return False

    inserted, skipped_variant, skipped_junk = [], [], []
    with _connect(db_path) as conn:
        have = {r["name"].strip().lower() for r in conn.execute(
            "SELECT name FROM courses").fetchall()}
        have_keys = {_course_dedup_key(n) for n in have}
        names = [r["course_name"] for r in conn.execute(
            "SELECT DISTINCT course_name FROM handicap_rounds "
            "WHERE course_name IS NOT NULL AND TRIM(course_name) != ''").fetchall()]
        for raw in names:
            nm = (raw or "").strip()
            if not nm or nm.lower() in have:
                continue
            if looks_like_junk(nm):
                skipped_junk.append({"course_name": nm,
                                     "reason": "GG artifact / fragment — not a real course"})
                continue
            k = _course_dedup_key(nm)
            if k in have_keys:
                skipped_variant.append({"course_name": nm,
                                        "reason": "normalized-key matches an existing course"})
                continue
            sn = short_for(nm)
            if not dry_run:
                conn.execute("INSERT OR IGNORE INTO courses (name, short_name) "
                             "VALUES (?, ?)", (nm, sn))
            have.add(nm.lower()); have_keys.add(k)
            inserted.append({"name": nm, "short_name": sn})
        if not dry_run:
            conn.commit()
    return {("inserted" if not dry_run else "would_insert"): inserted,
            "inserted_count": len(inserted),
            "skipped_as_variant": skipped_variant,
            "skipped_variant_count": len(skipped_variant),
            "skipped_as_junk": skipped_junk,
            "skipped_junk_count": len(skipped_junk)}


# ─── Member-side traffic analytics (v2.62.0, Kerry) ────────────────────
# Anonymous, PII-free: event ('open'|'click'), path, and a short label.
# No customer reference by design — the member tier is anonymous.

def _ensure_member_analytics_table(conn: sqlite3.Connection) -> None:
    conn.execute(
        """CREATE TABLE IF NOT EXISTS member_analytics (
               id         INTEGER PRIMARY KEY AUTOINCREMENT,
               event      TEXT NOT NULL,
               path       TEXT NOT NULL,
               detail     TEXT,
               created_at TEXT DEFAULT (datetime('now'))
           )"""
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_member_analytics_time"
        " ON member_analytics(created_at)"
    )


def log_member_event(event: str, path: str, detail: str = "",
                     db_path: str | Path = DB_PATH) -> None:
    """Record one anonymous member-page event. Inputs are whitelisted /
    truncated by the API layer; this just writes."""
    with _connect(db_path) as conn:
        _ensure_member_analytics_table(conn)
        conn.execute(
            "INSERT INTO member_analytics (event, path, detail) VALUES (?, ?, ?)",
            (event[:16], path[:80], (detail or "")[:80]),
        )
        conn.commit()


def get_member_traffic_summary(db_path: str | Path = DB_PATH) -> dict:
    """Aggregates for the admin Traffic view. Rolling windows (24h/7d/30d)
    so UTC storage needs no timezone gymnastics."""
    with _connect(db_path) as conn:
        _ensure_member_analytics_table(conn)

        def _count(event, days=None, hours=None):
            q = "SELECT COUNT(*) FROM member_analytics WHERE event = ?"
            args = [event]
            if hours is not None:
                q += " AND created_at >= datetime('now', ?)"
                args.append(f"-{hours} hours")
            elif days is not None:
                q += " AND created_at >= datetime('now', ?)"
                args.append(f"-{days} days")
            return conn.execute(q, args).fetchone()[0]

        by_path = [dict(r) for r in conn.execute(
            """SELECT path,
                      SUM(CASE WHEN event='open' THEN 1 ELSE 0 END) AS opens_30d,
                      SUM(CASE WHEN event='click' THEN 1 ELSE 0 END) AS clicks_30d
               FROM member_analytics
               WHERE created_at >= datetime('now', '-30 days')
               GROUP BY path ORDER BY opens_30d DESC"""
        )]
        daily = [dict(r) for r in conn.execute(
            """SELECT date(created_at) AS day,
                      SUM(CASE WHEN event='open' THEN 1 ELSE 0 END) AS opens,
                      SUM(CASE WHEN event='click' THEN 1 ELSE 0 END) AS clicks
               FROM member_analytics
               WHERE created_at >= datetime('now', '-14 days')
               GROUP BY day ORDER BY day"""
        )]
        top_clicks = [dict(r) for r in conn.execute(
            """SELECT COALESCE(NULLIF(TRIM(detail), ''), '(unlabeled)') AS label,
                      COUNT(*) AS n
               FROM member_analytics
               WHERE event = 'click'
                 AND created_at >= datetime('now', '-30 days')
               GROUP BY label ORDER BY n DESC LIMIT 25"""
        )]
        return {
            "totals": {
                "opens_24h": _count("open", hours=24),
                "opens_7d": _count("open", days=7),
                "opens_30d": _count("open", days=30),
                "clicks_24h": _count("click", hours=24),
                "clicks_7d": _count("click", days=7),
                "clicks_30d": _count("click", days=30),
            },
            "by_path": by_path,
            "daily": daily,
            "top_clicks": top_clicks,
        }


def list_chapter_names(db_path: str | Path = DB_PATH) -> list:
    with _connect(db_path) as conn:
        return [r["name"] for r in conn.execute("SELECT name FROM chapters ORDER BY chapter_id").fetchall()]


def _repair_gg_email_pins(conn: sqlite3.Connection) -> None:
    """Set is_golf_genius=1 on admin-confirmed sync addresses (idempotent).

    Skips (with a warning) when the player's name doesn't resolve to exactly
    one customer, so a wrong guess is impossible. Clears any other GG flag on
    the same customer first — the partial UNIQUE(customer_id, is_golf_genius)
    index allows one designated address per customer.
    """
    for name, email in _GG_EMAIL_PINS:
        cid = _lookup_customer_id(conn, name, None)
        if cid is None:
            logger.warning("GG email pin: %r not uniquely resolvable — skipping", name)
            continue
        row = conn.execute(
            "SELECT email_id, is_golf_genius FROM customer_emails "
            "WHERE customer_id = ? AND LOWER(email) = LOWER(?)",
            (cid, email),
        ).fetchone()
        if row and row["is_golf_genius"]:
            continue  # already pinned
        conn.execute(
            "UPDATE customer_emails SET is_golf_genius = 0 WHERE customer_id = ?",
            (cid,),
        )
        if row:
            conn.execute(
                "UPDATE customer_emails SET is_golf_genius = 1 WHERE email_id = ?",
                (row["email_id"],),
            )
        else:
            conn.execute(
                """INSERT INTO customer_emails (customer_id, email, is_primary, is_golf_genius, label)
                   VALUES (?, ?, 0, 1, 'gg-pin')""",
                (cid, email),
            )
        conn.commit()
        logger.info("GG email pin: %s syncs to Golf Genius as %r (cid %d)", name, email, cid)


def _log_gg_export_email_changes(conn: sqlite3.Connection) -> None:
    """Log players whose Golf Genius sync email differs under canonical-first
    resolution (v2.16.26) vs the legacy latest-transaction-snapshot method.

    Golf Genius matches league members BY EMAIL, so a changed address only
    updates the right member if GG knows them under it. This runs at every
    boot (log-only, quiet when nothing differs) so the deploy log lists the
    affected players before the nightly 02:00 sync uploads them. Losing an
    email is impossible — the legacy resolution remains the fallback — so
    the diff can only show changed addresses and newly-included players.
    """
    rows = conn.execute(
        """SELECT l.player_name, l.customer_name,
                  (SELECT LOWER(TRIM(ce.email)) FROM customer_emails ce
                    WHERE ce.customer_id = l.customer_id
                      AND ce.email IS NOT NULL AND TRIM(ce.email) != ''
                    ORDER BY ce.is_golf_genius DESC, ce.is_primary DESC,
                             ce.email_id ASC LIMIT 1) AS canonical,
                  COALESCE(
                    (SELECT LOWER(TRIM(i1.customer_email)) FROM items i1
                      WHERE LOWER(i1.customer) = LOWER(l.customer_name)
                        AND i1.customer_email IS NOT NULL AND TRIM(i1.customer_email) != ''
                      ORDER BY i1.id DESC LIMIT 1),
                    (SELECT LOWER(TRIM(ca.alias_value)) FROM customer_aliases ca
                      WHERE LOWER(ca.customer_name) = LOWER(l.customer_name)
                        AND ca.alias_type = 'email' LIMIT 1),
                    '') AS legacy
           FROM handicap_player_links l
           WHERE l.customer_name IS NOT NULL"""
    ).fetchall()
    changed = gained = 0
    for r in rows:
        if (r["player_name"] or "").strip().lower() in _GG_SYNC_EXCLUDES or \
                (r["customer_name"] or "").strip().lower() in _GG_SYNC_EXCLUDES:
            continue  # admin-removed from GG; export skips them, so must this diff
        canon = (r["canonical"] or "").strip()
        legacy = (r["legacy"] or "").strip()
        if canon and legacy and canon != legacy:
            changed += 1
            logger.warning(
                "GG sync email change: %s (%s) will sync as %r (was %r) — "
                "confirm Golf Genius knows them by the new address",
                r["player_name"], r["customer_name"], canon, legacy,
            )
        elif canon and not legacy:
            gained += 1
            logger.info(
                "GG sync: %s (%s) NEWLY included via canonical email %r "
                "(legacy resolution found none)",
                r["player_name"], r["customer_name"], canon,
            )
    if changed or gained:
        logger.info(
            "GG sync email diff: %d player(s) change address, %d newly included",
            changed, gained,
        )


def _log_duplicate_name_customers(conn: sqlite3.Connection) -> None:
    """Log same-first+last customer pairs and what each profile holds.

    The v2.16.14 ambiguity guard refuses to guess between same-named
    profiles, so name-keyed backfills leave rows unlinked until a human
    decides which profile is canonical. This census puts everything needed
    for that decision in the deploy log: which customer_ids share a name,
    each profile's emails, and per-table reference counts. Changes nothing.
    """
    dupes = conn.execute(
        """SELECT LOWER(TRIM(first_name)) AS f, LOWER(TRIM(last_name)) AS l,
                  GROUP_CONCAT(customer_id) AS cids, COUNT(*) AS n
           FROM customers
           WHERE COALESCE(TRIM(first_name), '') != ''
             AND COALESCE(TRIM(last_name), '') != ''
           GROUP BY 1, 2 HAVING n > 1"""
    ).fetchall()
    for d in dupes:
        cid_set = frozenset(int(c) for c in d["cids"].split(","))
        if cid_set in _KNOWN_DISTINCT_SAME_NAME:
            logger.info(
                "Duplicate-name census: %s %s → cids %s are known-distinct "
                "people (confirmed) — OK", d["f"].title(), d["l"].title(),
                sorted(cid_set),
            )
            continue
        parts = []
        for cid_str in d["cids"].split(","):
            cid = int(cid_str)
            refs = []
            emails = [
                r["email"] for r in conn.execute(
                    "SELECT email FROM customer_emails WHERE customer_id = ?", (cid,)
                )
            ]
            if emails:
                refs.append("emails=" + "/".join(emails))
            for table, col in _CUSTOMER_FK_COLUMNS:
                try:
                    cnt = conn.execute(
                        f"SELECT COUNT(*) AS c FROM {table} WHERE {col} = ?", (cid,)
                    ).fetchone()["c"]
                except sqlite3.OperationalError:
                    continue
                if cnt:
                    label = table if col == "customer_id" else f"{table}.{col}"
                    refs.append(f"{label}={cnt}")
            parts.append(f"cid {cid}: {', '.join(refs) or 'EMPTY (no references anywhere)'}")
        logger.warning(
            "Duplicate-name census: %s %s → %s",
            d["f"].title(), d["l"].title(), " | ".join(parts),
        )


def _merge_duplicate_customers(conn: sqlite3.Connection) -> None:
    """Merge known duplicate customer records (idempotent).

    For each pair, reassigns all customer-FK rows from the duplicate to the
    canonical record via _repoint_customer_fks, then deletes the duplicate
    customer row and its emails/aliases.
    """
    # Pairs: (lookup_column, lookup_value, canonical_name_preference, email_to_keep)
    # We find pairs by email or phone, keep the lower customer_id (older),
    # unless a specific name is preferred.
    MERGE_PAIRS = [
        # Matt Jenkins / Matthew Jenkins — same email mattjenkins521@gmail.com
        {
            "find_by": "email",
            "find_value": "mattjenkins521@gmail.com",
            "canonical_rule": "lower_id",  # keep whichever customer_id is older
        },
        # Stu Kirksey / Stuart Kirksey — same phone (512) 964-7371
        {
            "find_by": "phone_digits",
            "find_value": "5129647371",
            "canonical_name": "Stu",  # keep the customer whose first_name = 'Stu'
            "canonical_email": "stuartkirksey@gmail.com",
        },
        # Michael Murphy / Mike Murphy — same email mmurphy4250@gmail.com
        {
            "find_by": "email",
            "find_value": "mmurphy4250@gmail.com",
            "canonical_rule": "lower_id",
        },
    ]

    for pair in MERGE_PAIRS:
        try:
            if pair["find_by"] == "email":
                # Find all customer_ids linked to this email
                rows = conn.execute(
                    "SELECT DISTINCT customer_id FROM customer_emails WHERE LOWER(email) = ?",
                    (pair["find_value"].lower(),),
                ).fetchall()
            elif pair["find_by"] == "phone_digits":
                # Find customers by phone digits (strip non-digits for comparison)
                rows = conn.execute(
                    """SELECT customer_id FROM customers
                       WHERE REPLACE(REPLACE(REPLACE(REPLACE(phone, '(', ''), ')', ''), '-', ''), ' ', '') LIKE ?""",
                    (f"%{pair['find_value']}%",),
                ).fetchall()
            else:
                continue

            cids = sorted(set(r["customer_id"] for r in rows))
            if len(cids) < 2:
                continue  # no duplicates found or already merged

            # Determine canonical (keep) vs duplicate (remove)
            if pair.get("canonical_name"):
                # Find the one matching the preferred first_name
                canonical_id = None
                for cid in cids:
                    cust = conn.execute(
                        "SELECT first_name FROM customers WHERE customer_id = ?", (cid,)
                    ).fetchone()
                    if cust and cust["first_name"] == pair["canonical_name"]:
                        canonical_id = cid
                        break
                if not canonical_id:
                    canonical_id = cids[0]
            else:
                # lower_id = older record
                canonical_id = cids[0]

            duplicates = [cid for cid in cids if cid != canonical_id]

            for dup_id in duplicates:
                # Count items before merge
                dup_count = conn.execute(
                    "SELECT COUNT(*) as cnt FROM items WHERE customer_id = ?", (dup_id,)
                ).fetchone()["cnt"]

                # Reassign every customer FK (items, memberships, statuses,
                # roles, RSVPs, ledger rows, ...) from duplicate to canonical
                _repoint_customer_fks(conn, dup_id, canonical_id)

                # Move any customer_emails not already on canonical
                dup_emails = conn.execute(
                    "SELECT email FROM customer_emails WHERE customer_id = ?", (dup_id,)
                ).fetchall()
                for de in dup_emails:
                    try:
                        conn.execute(
                            "INSERT OR IGNORE INTO customer_emails (customer_id, email) VALUES (?, ?)",
                            (canonical_id, de["email"]),
                        )
                    except sqlite3.IntegrityError:
                        pass
                conn.execute("DELETE FROM customer_emails WHERE customer_id = ?", (dup_id,))

                # Move customer_aliases
                try:
                    dup_name_row = conn.execute(
                        "SELECT first_name, last_name FROM customers WHERE customer_id = ?", (dup_id,)
                    ).fetchone()
                    if dup_name_row:
                        dup_full = f"{dup_name_row['first_name']} {dup_name_row['last_name']}"
                        canon_row = conn.execute(
                            "SELECT first_name, last_name FROM customers WHERE customer_id = ?",
                            (canonical_id,),
                        ).fetchone()
                        if canon_row:
                            canon_full = f"{canon_row['first_name']} {canon_row['last_name']}"
                            # Add dup name as alias of canonical
                            conn.execute(
                                "INSERT OR IGNORE INTO customer_aliases (customer_name, alias_value, alias_type) "
                                "VALUES (?, ?, 'name')",
                                (canon_full, dup_full),
                            )
                except Exception:
                    logger.debug("Failed to create alias during customer merge", exc_info=True)

                # Delete the duplicate customer record
                conn.execute("DELETE FROM customers WHERE customer_id = ?", (dup_id,))

                # Update canonical email if specified
                if pair.get("canonical_email"):
                    conn.execute(
                        "UPDATE customer_emails SET is_primary = 1 WHERE customer_id = ? AND email = ?",
                        (canonical_id, pair["canonical_email"]),
                    )

                logger.info(
                    "Merged duplicate customer #%d into #%d (%d items reassigned)",
                    dup_id, canonical_id, dup_count,
                )

        except Exception:
            logger.exception("Customer merge failed for pair: %s", pair)

    # ── Generic email-based auto-merge ──
    # Build unified email → customer_ids map from ALL sources
    email_to_cids = {}

    # Source 1: customer_emails table
    for row in conn.execute("SELECT customer_id, LOWER(TRIM(email)) as email FROM customer_emails WHERE email IS NOT NULL").fetchall():
        em = row["email"]
        if em:
            email_to_cids.setdefault(em, set()).add(row["customer_id"])

    # Source 2: items.customer_email
    for row in conn.execute(
        "SELECT DISTINCT customer_id, LOWER(TRIM(customer_email)) as email FROM items WHERE customer_email IS NOT NULL AND customer_id IS NOT NULL"
    ).fetchall():
        em = row["email"]
        if em:
            email_to_cids.setdefault(em, set()).add(row["customer_id"])

    # Find emails with multiple customer_ids
    all_email_dups = {em: cids for em, cids in email_to_cids.items() if len(cids) >= 2}
    logger.info("Email dedup: %d emails with multiple customer_ids to merge", len(all_email_dups))
    for email, cids in all_email_dups.items():
        logger.info("  %s → customer_ids: %s", email, sorted(cids))

    for email, cid_set in all_email_dups.items():
        cids = sorted(cid_set)
        if len(cids) < 2:
            continue
        canonical_id = cids[0]  # keep oldest
        for dup_id in cids[1:]:
            try:
                # Check dup still exists (may have been merged already)
                if not conn.execute("SELECT customer_id FROM customers WHERE customer_id = ?", (dup_id,)).fetchone():
                    continue

                dup_count = conn.execute(
                    "SELECT COUNT(*) as cnt FROM items WHERE customer_id = ?", (dup_id,)
                ).fetchone()["cnt"]

                # Reassign every customer FK, not just items — deleting the
                # dup row below must not orphan memberships/statuses/roles.
                _repoint_customer_fks(conn, dup_id, canonical_id)

                # Move emails
                for de in conn.execute("SELECT email FROM customer_emails WHERE customer_id = ?", (dup_id,)).fetchall():
                    try:
                        conn.execute("INSERT OR IGNORE INTO customer_emails (customer_id, email) VALUES (?, ?)", (canonical_id, de["email"]))
                    except sqlite3.IntegrityError:
                        pass
                conn.execute("DELETE FROM customer_emails WHERE customer_id = ?", (dup_id,))

                # Create name alias
                dup_row = conn.execute("SELECT first_name, last_name FROM customers WHERE customer_id = ?", (dup_id,)).fetchone()
                canon_row = conn.execute("SELECT first_name, last_name FROM customers WHERE customer_id = ?", (canonical_id,)).fetchone()
                if dup_row and canon_row:
                    dup_full = f"{dup_row['first_name']} {dup_row['last_name']}"
                    canon_full = f"{canon_row['first_name']} {canon_row['last_name']}"
                    conn.execute(
                        "INSERT OR IGNORE INTO customer_aliases (customer_name, alias_value, alias_type) VALUES (?, ?, 'name')",
                        (canon_full, dup_full),
                    )

                conn.execute("DELETE FROM customers WHERE customer_id = ?", (dup_id,))
                logger.info("Auto-merged customer #%d into #%d by shared email %s (%d items)",
                            dup_id, canonical_id, email, dup_count)
            except Exception:
                logger.warning("Auto-merge failed for customer #%d → #%d", dup_id, canonical_id, exc_info=True)

    # ── Normalize items.customer text for same-email name variants ──
    # The Customers page groups by items.customer text, so "Will Peterson" and
    # "William Peterson" show as separate entries even with the same customer_id.
    # Find emails with multiple distinct customer name strings and normalize.
    # GUARD: skip if items with this email have multiple distinct customer_ids —
    # that means different people share the email due to a bad merge, not name variants.
    name_variants = conn.execute(
        """SELECT LOWER(TRIM(customer_email)) as email,
                  GROUP_CONCAT(DISTINCT customer) as names,
                  COUNT(DISTINCT customer) as cnt,
                  COUNT(DISTINCT customer_id) as cid_cnt
           FROM items
           WHERE customer_email IS NOT NULL AND customer_email != ''
             AND customer IS NOT NULL AND customer != ''
           GROUP BY LOWER(TRIM(customer_email))
           HAVING cnt > 1"""
    ).fetchall()

    for row in name_variants:
        email = row["email"]
        # Multiple distinct customer_ids sharing an email = different people, not variants
        if row["cid_cnt"] > 1:
            continue
        names = [n.strip() for n in row["names"].split(",") if n.strip()]
        if len(names) < 2:
            continue
        # Keep the name with the most items (most established)
        best_name = None
        best_count = 0
        for n in names:
            cnt = conn.execute(
                "SELECT COUNT(*) as cnt FROM items WHERE customer = ?", (n,)
            ).fetchone()["cnt"]
            if cnt > best_count:
                best_count = cnt
                best_name = n
        if not best_name:
            continue
        # Rewrite all variant names to the canonical one
        for n in names:
            if n != best_name:
                updated = conn.execute(
                    "UPDATE items SET customer = ? WHERE customer = ?",
                    (best_name, n),
                ).rowcount
                if updated:
                    # Create alias for future lookups
                    conn.execute(
                        "INSERT OR IGNORE INTO customer_aliases (customer_name, alias_value, alias_type) VALUES (?, ?, 'name')",
                        (best_name, n),
                    )
                    logger.info("Normalized items.customer '%s' → '%s' (%d items, shared email %s)",
                                n, best_name, updated, email)

    conn.commit()


def _backfill_customer_ids(conn: sqlite3.Connection) -> int:
    """Populate customer_id for existing items that don't have one yet.

    Uses ``_resolve_or_create_customer`` so that expanded partner rows
    (e.g. "Will Massey") get a customer record auto-created if one
    doesn't already exist.  Emits ``UNLINKED_PARTNER`` parse warnings
    for any names that can't be resolved.

    Covers 'Customer Entry' (+ Add Customer modal), 'Roster Import' /
    'RSVP Import' rows, and 'RSVP Email Link' rows — all four insert paths
    now resolve/create customer_id at insert time (see create_customer(),
    import_roster(), create_customer_from_rsvp(), link_rsvp_to_customer()),
    but this backfill is what heals any rows that predate those fixes.
    'RSVP Email Link' used to be excluded on the assumption that a NULL
    customer_id there meant the target hadn't resolved yet and would get
    picked up under its own name on a later pass — live-data audit proved
    that assumption false (the target is typically *already* resolved by
    the time this merchant fires; it's the row's own link that's missing),
    so no merchant is excluded from this backfill anymore. Name-based
    resolution here is safe for it specifically because the row's
    `customer` string always matches an already-established person.

    Returns the number of item rows updated.
    """
    # Pull one representative row per distinct customer name so we have
    # context fields (chapter, user_status, phone, email_uid, etc.)
    rows = conn.execute(
        """SELECT customer, customer_email, customer_phone, chapter,
                  user_status, first_name, last_name,
                  email_uid, order_id, item_name
           FROM items
           WHERE customer_id IS NULL
             AND (customer IS NOT NULL AND customer != '')
           GROUP BY customer"""
    ).fetchall()

    if not rows:
        return 0

    updated = 0
    for row in rows:
        cid = _resolve_or_create_customer(
            conn, row["customer"], row["customer_email"],
            phone=row["customer_phone"],
            chapter=row["chapter"],
            user_status=row["user_status"],
            first_name=row["first_name"],
            last_name=row["last_name"],
            email_uid=row["email_uid"],
            order_id=row["order_id"],
            item_name=row["item_name"],
        )
        if cid is not None:
            cur = conn.execute(
                """UPDATE items SET customer_id = ?
                   WHERE customer_id IS NULL AND customer = ?""",
                (cid, row["customer"]),
            )
            updated += cur.rowcount

    # Always commit — _resolve_or_create_customer() may have INSERTed
    # new customer records even if no item rows were updated.
    conn.commit()
    if updated:
        logger.info("Backfilled customer_id for %d item rows", updated)
    return updated


def _backfill_approved_expenses_to_ledger(conn: sqlite3.Connection) -> int:
    """Promote approved expense_transactions that aren't yet linked to acct_transactions.

    Safe to call on every startup — skips rows that already have acct_transaction_id.
    Also skips Venmo "received" rows that are already matched to a balance-due
    item (auto_match_venmo_inbound_to_balance_due owns the ledger entry for
    those — promoting here would create a duplicate).
    """
    rows = conn.execute(
        """SELECT * FROM expense_transactions
           WHERE review_status IN ('approved', 'corrected')
             AND (acct_transaction_id IS NULL)
             AND amount IS NOT NULL AND amount > 0
             AND NOT (transaction_type = 'received' AND matched_item_id IS NOT NULL)"""
    ).fetchall()
    if not rows:
        return 0
    count = 0
    for row in rows:
        try:
            result = _sync_expense_ledger_entry(conn, dict(row))
            if result:
                count += 1
        except Exception:
            logger.warning(
                "_backfill_approved_expenses_to_ledger: failed for expense id=%s", row["id"],
                exc_info=True,
            )
    if count:
        conn.commit()
        logger.info("Backfilled %d approved expenses into acct_transactions", count)
    return count


def _backfill_customer_id_on_acct_transactions(conn: sqlite3.Connection) -> int:
    """Populate customer_id on acct_transactions rows that have a customer name but no FK.

    Uses _lookup_customer_id (5-step cascade) so the backfill works even for
    customers that predate the identity unification.  Safe to call repeatedly.
    """
    rows = conn.execute(
        """SELECT DISTINCT customer FROM acct_transactions
           WHERE customer_id IS NULL
             AND customer IS NOT NULL AND customer != ''
             AND entry_type IS NOT NULL"""
    ).fetchall()

    if not rows:
        return 0

    updated = 0
    for row in rows:
        cid = _lookup_customer_id(conn, row["customer"], None)
        if cid is not None:
            cur = conn.execute(
                """UPDATE acct_transactions SET customer_id = ?
                   WHERE customer_id IS NULL AND customer = ?""",
                (cid, row["customer"]),
            )
            updated += cur.rowcount

    conn.commit()
    if updated:
        logger.info("Backfilled customer_id for %d acct_transactions rows", updated)
    return updated


def _backfill_customer_id_on_player_links(conn: sqlite3.Connection) -> int:
    """Populate customer_id on handicap_player_links rows that lack it.

    Resolves via _lookup_customer_id using the linked customer_name.
    """
    rows = conn.execute(
        """SELECT player_name, customer_name FROM handicap_player_links
           WHERE customer_id IS NULL
             AND customer_name IS NOT NULL AND customer_name != ''"""
    ).fetchall()

    if not rows:
        return 0

    updated = 0
    for row in rows:
        cid = _lookup_customer_id(conn, row["customer_name"], None)
        if cid is not None:
            cur = conn.execute(
                """UPDATE handicap_player_links SET customer_id = ?
                   WHERE player_name = ? AND customer_id IS NULL""",
                (cid, row["player_name"]),
            )
            updated += cur.rowcount

    conn.commit()
    if updated:
        logger.info("Backfilled customer_id for %d handicap_player_links rows", updated)
    return updated


def _backfill_customer_id_on_rsvps(conn: sqlite3.Connection) -> int:
    """Populate customer_id on rsvps rows that lack it.

    Tries email-first via customer_emails, then name via customers table.
    Unresolved rows are left with customer_id=NULL so the admin can spot them.
    """
    rows = conn.execute(
        "SELECT id, player_name, player_email FROM rsvps WHERE customer_id IS NULL"
    ).fetchall()

    if not rows:
        return 0

    updated = 0
    for row in rows:
        cid = _lookup_customer_id(conn, row["player_name"], row["player_email"])
        if cid is not None:
            cur = conn.execute(
                "UPDATE rsvps SET customer_id = ? WHERE id = ? AND customer_id IS NULL",
                (cid, row["id"]),
            )
            updated += cur.rowcount

    conn.commit()
    if updated:
        logger.info("Backfilled customer_id for %d rsvps rows", updated)
    return updated


def _backfill_customer_id_on_aliases(conn: sqlite3.Connection) -> int:
    """Populate customer_id on customer_aliases rows that lack it.

    Resolves via name match in customers table (aliases are keyed by customer_name).
    UPDATE OR IGNORE so the unique alias index can't blow up the backfill; a
    skipped row means the customer already owns that exact alias, so the
    unlinked shadow row is deleted rather than left to linger.
    """
    rows = conn.execute(
        "SELECT id, customer_name FROM customer_aliases WHERE customer_id IS NULL"
    ).fetchall()
    if not rows:
        return 0
    updated = 0
    for row in rows:
        cid = _lookup_customer_id(conn, row["customer_name"], None)
        if cid is not None:
            cur = conn.execute(
                "UPDATE OR IGNORE customer_aliases SET customer_id = ? "
                "WHERE id = ? AND customer_id IS NULL",
                (cid, row["id"]),
            )
            if cur.rowcount:
                updated += cur.rowcount
            else:
                conn.execute(
                    "DELETE FROM customer_aliases WHERE id = ? AND customer_id IS NULL",
                    (row["id"],),
                )
    conn.commit()
    if updated:
        logger.info("Backfilled customer_id for %d customer_aliases rows", updated)
    return updated


def _dedup_customer_aliases(conn: sqlite3.Connection) -> int:
    """Collapse duplicate customer_aliases rows and enforce uniqueness forever.

    Repeated captures piled up identical alias rows (Stu Kirksey carried
    seven 'Stuart Kirksey' name aliases). Keeps the earliest row per
    (customer_id, alias_type, alias_value) — per (customer_name, ...) for
    unlinked rows — deletes unlinked shadows of already-linked aliases, then
    creates partial UNIQUE indexes so every future duplicate capture becomes
    a no-op (all insert sites use INSERT OR IGNORE). Idempotent, runs at
    every boot.
    """
    removed = conn.execute(
        """DELETE FROM customer_aliases
           WHERE id NOT IN (
               SELECT MIN(id) FROM customer_aliases
               GROUP BY COALESCE(customer_id, -1),
                        CASE WHEN customer_id IS NULL
                             THEN LOWER(TRIM(COALESCE(customer_name, '')))
                             ELSE '' END,
                        alias_type,
                        LOWER(TRIM(COALESCE(alias_value, '')))
           )"""
    ).rowcount
    # Unlinked rows that duplicate an already-linked alias with the same
    # customer name are shadows (e.g. a backfill skipped by the unique
    # index) — the linked row already provides the same mapping, stronger.
    removed += conn.execute(
        """DELETE FROM customer_aliases
           WHERE customer_id IS NULL
             AND EXISTS (
                 SELECT 1 FROM customer_aliases ca2
                 WHERE ca2.customer_id IS NOT NULL
                   AND LOWER(TRIM(COALESCE(ca2.customer_name, ''))) =
                       LOWER(TRIM(COALESCE(customer_aliases.customer_name, '')))
                   AND ca2.alias_type = customer_aliases.alias_type
                   AND LOWER(TRIM(COALESCE(ca2.alias_value, ''))) =
                       LOWER(TRIM(COALESCE(customer_aliases.alias_value, '')))
             )"""
    ).rowcount
    conn.execute(
        """CREATE UNIQUE INDEX IF NOT EXISTS idx_customer_aliases_cid_unique
           ON customer_aliases(customer_id, alias_type, LOWER(TRIM(alias_value)))
           WHERE customer_id IS NOT NULL"""
    )
    conn.execute(
        """CREATE UNIQUE INDEX IF NOT EXISTS idx_customer_aliases_name_unique
           ON customer_aliases(LOWER(TRIM(COALESCE(customer_name, ''))), alias_type,
                               LOWER(TRIM(alias_value)))
           WHERE customer_id IS NULL"""
    )
    conn.commit()
    if removed:
        logger.info("Alias dedup: removed %d duplicate customer_aliases row(s)", removed)
    return removed


