# RSVPs — Golf Genius round signup confirmations
# ---------------------------------------------------------------------------

def get_known_rsvp_uids(db_path: str | Path | None = None) -> set[str]:
    """Return the set of email_uid values already stored in rsvps."""
    with _connect(db_path) as conn:
        rows = conn.execute("SELECT DISTINCT email_uid FROM rsvps").fetchall()
        return {r["email_uid"] for r in rows}


# Multi-round GG event names append a round qualifier the tracker's single
# event row doesn't carry (Kerry 2026-07-30, the 2026 TGF CHAMPIONSHIP):
# "… round 1", "… round 2", "… Practice Round" (optionally after a dash or
# colon). Strip it before event matching.
_RSVP_ROUND_SUFFIX_RE = re.compile(
    r"\s*[-–—:]*\s*(?:PRACTICE\s+ROUND|ROUND\s*\d+)\s*$", re.IGNORECASE)


def match_rsvp_to_event(event_identifier: str, event_date: str | None,
                         db_path: str | Path | None = None) -> str | None:
    """Try to match an RSVP event identifier to an events.item_name.

    Only returns a match when confident. Returns None for ambiguous cases
    so they can be resolved manually.

    Strategies (in order of confidence):
      1. item_name contains the full event_identifier substring (exact)
      2. Extract course name from identifier and match course + date
      3. Extract course name from identifier and match course alone (single match)
      4. Match by event_date alone ONLY if single event on that date AND
         the chapter from the identifier matches the event's chapter
    """
    with _connect(db_path) as conn:
        identifier_upper = (event_identifier or "").upper().strip()

        # Strategy 1: Direct substring match on full identifier
        rows = conn.execute(
            "SELECT item_name FROM events WHERE UPPER(item_name) LIKE ?",
            (f"%{identifier_upper}%",),
        ).fetchall()
        if len(rows) == 1:
            return rows[0]["item_name"]

        # Strategy 1b (Kerry 2026-07-30): multi-round GG events append a
        # round suffix the tracker's single event doesn't carry — "2026
        # TGF CHAMPIONSHIP round 1" / "round 2" / "Practice Round" all
        # belong to "2026 TGF CHAMPIONSHIP". Strip the suffix and retry
        # the direct match.
        base_identifier = _RSVP_ROUND_SUFFIX_RE.sub("", identifier_upper).strip(" -:")
        if base_identifier and base_identifier != identifier_upper:
            rows = conn.execute(
                "SELECT item_name FROM events WHERE UPPER(item_name) LIKE ?",
                (f"%{base_identifier}%",),
            ).fetchall()
            if len(rows) == 1:
                return rows[0]["item_name"]
            # Round-stripped base against aliases too, same confidence bar.
            rows = conn.execute(
                "SELECT canonical_event_name FROM event_aliases WHERE UPPER(alias_name) LIKE ?",
                (f"%{base_identifier}%",),
            ).fetchall()
            if len(rows) == 1:
                return rows[0]["canonical_event_name"]

        # Extract the course name portion from the identifier.
        # GG identifiers look like: "a18.2 PRIME TIME KICKOFF | SHADOWGLEN"
        # or "s9.1 The Quarry" — the course is typically the last segment.
        from email_parser.parser import _normalize_course_name
        course_part = event_identifier
        if "|" in event_identifier:
            course_part = event_identifier.split("|")[-1].strip()
        elif " " in event_identifier:
            # Try the last word(s) after any prefix like "a18.2"
            parts = event_identifier.split()
            # Skip leading codes like "s9.1", "a18.2"
            start = 0
            for i, p in enumerate(parts):
                if re.match(r'^[a-z]\d+\.\d+$', p, re.IGNORECASE):
                    start = i + 1
            course_part = " ".join(parts[start:])

        # Strip trailing golf-course qualifiers (e.g. "TERAVISTA front" → "TERAVISTA")
        _COURSE_SUFFIXES = {"front", "back", "nine", "side", "course"}
        cp_words = course_part.split()
        if len(cp_words) > 1 and cp_words[-1].lower() in _COURSE_SUFFIXES:
            course_part = " ".join(cp_words[:-1])

        normalized_course = _normalize_course_name(course_part)

        # Strategy 2: Normalized course name + date (high confidence)
        if normalized_course and event_date:
            rows = conn.execute(
                "SELECT item_name FROM events WHERE UPPER(course) LIKE ? AND event_date = ?",
                (f"%{normalized_course.upper()}%", event_date),
            ).fetchall()
            if len(rows) == 1:
                return rows[0]["item_name"]

        # Strategy 3: Normalized course name alone (only if single match)
        if normalized_course:
            rows = conn.execute(
                "SELECT item_name FROM events WHERE UPPER(course) LIKE ?",
                (f"%{normalized_course.upper()}%",),
            ).fetchall()
            if len(rows) == 1:
                return rows[0]["item_name"]

        # Strategy 4: Also try the raw course_part (un-normalized) in item_name
        if course_part and course_part != event_identifier:
            rows = conn.execute(
                "SELECT item_name FROM events WHERE UPPER(item_name) LIKE ?",
                (f"%{course_part.upper()}%",),
            ).fetchall()
            if len(rows) == 1:
                return rows[0]["item_name"]

            # With date as additional filter
            if event_date:
                rows = conn.execute(
                    "SELECT item_name FROM events WHERE UPPER(item_name) LIKE ? AND event_date = ?",
                    (f"%{course_part.upper()}%", event_date),
                ).fetchall()
                if len(rows) == 1:
                    return rows[0]["item_name"]

        # Strategy 5: Check if the identifier matches an alias name
        rows = conn.execute(
            "SELECT canonical_event_name FROM event_aliases WHERE UPPER(alias_name) LIKE ?",
            (f"%{identifier_upper}%",),
        ).fetchall()
        if len(rows) == 1:
            return rows[0]["canonical_event_name"]

        # Also try course part against aliases
        if course_part and course_part != event_identifier:
            rows = conn.execute(
                "SELECT canonical_event_name FROM event_aliases WHERE UPPER(alias_name) LIKE ?",
                (f"%{course_part.upper()}%",),
            ).fetchall()
            if len(rows) == 1:
                return rows[0]["canonical_event_name"]

        # If none of the above matched confidently, return None.
        # Do NOT fall back to date-only matching — too risky for mismatches.
        return None


def match_rsvp_to_item(player_email: str | None, player_name: str | None,
                        event_name: str, db_path: str | Path | None = None) -> int | None:
    """Try to match an RSVP player to an items row (transaction).

    Searches items whose item_name matches the canonical event_name
    OR any alias that maps to it.

    Strategies:
      1. Match by player email + event name (or alias)
      2. Match by player first name + event name (or alias, only if single match)
    """
    with _connect(db_path) as conn:

        # Build list of names to search: canonical + all aliases
        aliases = conn.execute(
            "SELECT alias_name FROM event_aliases WHERE canonical_event_name = ?",
            (event_name,),
        ).fetchall()
        name_list = [event_name] + [r["alias_name"] for r in aliases]
        placeholders = ",".join(["?"] * len(name_list))

        # Strategy 1: Email match
        if player_email:
            row = conn.execute(
                f"""SELECT id FROM items
                   WHERE LOWER(customer_email) = LOWER(?)
                     AND item_name COLLATE NOCASE IN ({placeholders})
                     AND COALESCE(transaction_status, 'active') = 'active'""",
                [player_email] + name_list,
            ).fetchone()
            if row:
                return row["id"]

        # Strategy 1b: Match via customer_aliases email lookup
        # If the RSVP email matches a customer alias email, find that customer's items
        if player_email:
            alias_customer = conn.execute(
                """SELECT ca.customer_name FROM customer_aliases ca
                   WHERE ca.alias_type = 'email'
                     AND LOWER(ca.alias_value) = LOWER(?)""",
                (player_email,),
            ).fetchone()
            if alias_customer:
                row = conn.execute(
                    f"""SELECT id FROM items
                       WHERE customer = ?
                         AND item_name COLLATE NOCASE IN ({placeholders})
                         AND COALESCE(transaction_status, 'active') = 'active'""",
                    [alias_customer["customer_name"]] + name_list,
                ).fetchone()
                if row:
                    return row["id"]

        # Strategy 2: First name match (loose — only if exactly one match)
        # Guard: only use first-name matching when there's no ambiguity.
        # If there are multiple items with names starting with the same first name,
        # do NOT match (e.g. "Daniel" could be "Daniel South" or "Daniel Miller").
        if player_name:
            rows = conn.execute(
                f"""SELECT id, customer FROM items
                   WHERE customer LIKE ?
                     AND item_name COLLATE NOCASE IN ({placeholders})
                     AND COALESCE(transaction_status, 'active') = 'active'""",
                [f"{player_name}%"] + name_list,
            ).fetchall()
            if len(rows) == 1:
                return rows[0]["id"]

        return None


# ---------------------------------------------------------------------------
# Credit detection helpers
# ---------------------------------------------------------------------------

_PER_GAME_ADDON = 16.0  # $ per game (NET or GROSS) — 9 Holes and 9/18 Combo
_PER_GAME_ADDON_18 = 30.0  # $ per game for standalone 18 Hole events
_PER_GAME_ADDON_27 = 27.0  # default $ per game for 27 Hole events (overridable per-event via events.per_game_addon)


def _credit_origin_event(conn, credit, _depth: int = 0) -> str:
    """The ORIGINAL event a credit traces back to (Kerry 2026-07-16: a
    refund/Venmo-back memo must name the event the credit ORIGINALLY came
    from). A normal rain-out/WD credit's ``item_name`` IS its event. An
    excess/overpayment credit row — email_uid ``credit-excess-<rid>-…`` /
    ``overpayment-credit-<rid>-…`` — is named for the event it was APPLIED
    to, so trace the chain instead: the registration it funded (<rid>) →
    that registration's ``transferred_from_id`` (the source credit) →
    recurse — until an ordinary credit whose item_name is the origin event.
    """
    if not credit or _depth > 12:
        return (credit or {}).get("item_name") or ""
    uid = credit.get("email_uid") or ""
    name = credit.get("item_name") or ""
    m = re.match(r"^(?:credit-excess|overpayment-credit)-(\d+)-", uid)
    if m:
        reg = conn.execute("SELECT * FROM items WHERE id = ?",
                           (int(m.group(1)),)).fetchone()
        if reg:
            reg = dict(reg)
            src_id = reg.get("transferred_from_id")
            if src_id:
                src = conn.execute("SELECT * FROM items WHERE id = ?",
                                   (src_id,)).fetchone()
                if src:
                    return _credit_origin_event(conn, dict(src), _depth + 1)
            # No transfer link recorded — fall back to the funded event name.
            return reg.get("item_name") or name
    # Defensive: a display-named excess/overpayment row with no traceable uid.
    for pref in ("Excess credit — ", "Excess credit -- ", "Excess credit from ",
                 "Overpayment credit from ", "Overpayment — "):
        if name.startswith(pref):
            return name[len(pref):].strip()
    return name


def _item_credit_value(conn, item: dict) -> float:
    """THE credit value of a credited/WD items row — single source of
    truth (Kerry 2026-07-20). Entry price only (fees are never
    credited), minus any partial carve-out children (Partial Credit /
    Partial Refund / Refund(<method>) rows from event downgrades or
    dropped side games), floored at $0. Used by get_player_credits,
    payout_credit, and get_refunds_overview so the Apply Credit modal,
    the REFUNDS console, and the money actually paid can never
    disagree."""
    status = (item.get("transaction_status") or "").lower()
    if status == "wd":
        return max(0.0, round(_parse_dollar(item.get("credit_amount") or "0"), 2))
    val = _parse_dollar(item.get("item_price"))
    for k in conn.execute(
            "SELECT item_price FROM items "
            "WHERE CAST(parent_item_id AS INTEGER) = ? "
            "AND (merchant = 'Partial Credit' "
            "     OR merchant = 'Partial Refund' "
            "     OR merchant LIKE 'Refund (%')",
            (item["id"],)).fetchall():
        val -= abs(_parse_dollar(k["item_price"]))
    return max(0.0, round(val, 2))


def get_player_credits(
    customer_name: str,
    db_path: str | Path | None = None,
    customer_id: int | None = None,
    player_email: str | None = None,
) -> list[dict]:
    """Return all unredeemed credited items for a player, most recent first.

    Includes both parent items and child add-on items (e.g. game add-ons that
    were credited when an event was cancelled via credit_item cascade).

    Lookup priority:
    1. customer_id → items.customer_id
    2. Name fallback → items.customer COLLATE NOCASE
    3. Email fallback via customer_emails → resolve customer_id → retry #1
    """
    _CREDIT_SQL = """SELECT i.*, e.item_name as event_canonical
                     FROM items i
                     LEFT JOIN events e ON e.item_name = i.item_name COLLATE NOCASE
                     WHERE {where}
                       AND (i.transaction_status = 'credited'
                            OR (i.transaction_status = 'wd'
                                AND COALESCE(i.credit_amount, '') != ''))
                     ORDER BY i.order_date DESC"""

    with _connect(db_path) as conn:
        rows = []
        if customer_id:
            rows = conn.execute(
                _CREDIT_SQL.format(where="i.customer_id = ?"),
                (customer_id,),
            ).fetchall()

        if not rows:
            # Name lookup (case-insensitive)
            rows = conn.execute(
                _CREDIT_SQL.format(where="i.customer = ? COLLATE NOCASE"),
                (customer_name,),
            ).fetchall()

        # If still empty and we have an email, try resolving via customer_emails table
        if not rows and player_email:
            email_lc = player_email.strip().lower()
            ce_row = conn.execute(
                "SELECT customer_id FROM customer_emails WHERE LOWER(email) = ? LIMIT 1",
                (email_lc,),
            ).fetchone()
            if ce_row and ce_row["customer_id"]:
                rows = conn.execute(
                    _CREDIT_SQL.format(where="i.customer_id = ?"),
                    (ce_row["customer_id"],),
                ).fetchall()

    result = []
    with _connect(db_path) as conn:
        for r in rows:
            d = dict(r)
            d["credit_amount"] = _item_credit_value(conn, d)
            # Original event this credit traces back to — for refund memos.
            d["origin_event"] = _credit_origin_event(conn, d)
            result.append(d)
    return result


def build_entry_confirmation_email(item_id: int, result: dict | None = None,
                                   db_path: str | Path | None = None) -> dict | None:
    """Payload for the 'you're entered' confirmation email — sent when an
    applied credit covers the WHOLE entry fee (Kerry 2026-07-16). Returns a
    dict {subject, html_body, event_name, player_name, player_email}, or None
    if the item is missing or the player has no email on file."""
    import html as _html
    with _connect(db_path) as conn:
        row = conn.execute("SELECT * FROM items WHERE id = ?", (item_id,)).fetchone()
        if not row:
            return None
        item = dict(row)
        event_name = item.get("item_name") or ""
        ev = conn.execute("SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
                          (event_name,)).fetchone()
        event = dict(ev) if ev else {}
    player_name = (item.get("customer") or "").strip()
    try:
        player_email = resolve_player_email(item)
    except Exception:
        player_email = (item.get("customer_email") or "").strip()
    if not player_email:
        return None
    e = _html.escape
    first = player_name.split(" ", 1)[0] if player_name else "there"
    date = event.get("event_date") or ""
    course = event.get("course") or ""
    holes = (item.get("holes") or "").strip()
    tee = (item.get("tee_choice") or "").strip()
    games = (item.get("side_games") or "").strip()
    rows = []
    if date:
        rows.append(("Date", date))
    if course:
        rows.append(("Course", course))
    if holes:
        rows.append(("Holes", holes))
    if tee:
        rows.append(("Tee", tee))
    # Always show side games, incl. NONE (Kerry 2026-07-16 — a "NONE" line
    # is clearer than an omitted row: the player sees exactly what they're in).
    games_disp = games if games and games.upper() not in ("", "NO GAMES") else "None"
    rows.append(("Side games", games_disp))
    applied = (result or {}).get("amount_applied")
    if not applied:
        applied = _parse_dollar(item.get("item_price"))
    if applied:
        rows.append(("Credit applied", f"${float(applied):.2f}"))
    detail = "".join(
        f"<tr><td style='padding:4px 14px 4px 0;color:#64748b;'>{e(l)}</td>"
        f"<td style='padding:4px 0;font-weight:600;'>{e(str(v))}</td></tr>"
        for l, v in rows)
    excess = (result or {}).get("excess") or 0
    excess_note = ""
    if excess and float(excess) > 0.005:
        excess_note = (f"<p style='color:#475569;'>Your credit more than covered the "
                       f"entry — ${float(excess):.2f} remains on your account.</p>")
    subject = f"You're registered for {event_name}" + (f" — {date}" if date else "")
    html_body = f"""
<div style="font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;
            max-width:560px; color:#0f172a; line-height:1.5;">
  <p>Hi {e(first)},</p>
  <p>You're all set — your credit has been applied and you're
  <strong>entered into {e(event_name)}</strong>. Nothing further is due.</p>
  <table style="border-collapse:collapse; margin:0.75rem 0; font-size:0.95rem;">{detail}</table>
  {excess_note}
  <p>See you on the course!</p>
  <p style="color:#64748b;">— The Golf Fellowship</p>
</div>"""
    return {"subject": subject, "html_body": html_body, "event_name": event_name,
            "player_name": player_name, "player_email": player_email}


# Admin copy CC'd on automated member-facing sends for the record (Kerry
# 2026-07-16). Configurable / disable via env (AUTO_EMAIL_CC="").
def _auto_email_cc() -> str:
    import os as _os
    v = _os.getenv("AUTO_EMAIL_CC")
    return "admin@thegolffellowship.com" if v is None else v.strip()


def send_entry_confirmation_email(item_id: int, result: dict | None = None,
                                  db_path: str | Path | None = None,
                                  force: bool = False,
                                  override: str | None = None,
                                  cc: str | None = None) -> dict:
    """Build + send the entry-confirmation email via Microsoft Graph and log
    it. ``force=True`` skips the amount_owed guard (manual / retroactive
    resend). ``override`` sends to that address instead of the player (test /
    copy). ``cc`` defaults to the admin CC (``_auto_email_cc()``); pass ``""``
    to suppress it (e.g. when sending a plain copy). Test routing:
    ``CREDIT_ENTRY_EMAIL_OVERRIDE`` env. Returns {ok, sent_to, player_name}."""
    import os as _os
    from email_parser.fetcher import send_mail_graph
    if not force:
        owed = (result or {}).get("amount_owed")
        if owed is None or float(owed) > 0.005:
            return {"ok": False, "error": "balance still due"}
    payload = build_entry_confirmation_email(item_id, result, db_path)
    if not payload:
        return {"ok": False, "error": "item not found or no email on file"}
    tenant_id = _os.getenv("AZURE_TENANT_ID")
    client_id = _os.getenv("AZURE_CLIENT_ID")
    client_secret = _os.getenv("AZURE_CLIENT_SECRET")
    from_address = _os.getenv("EMAIL_ADDRESS")
    if not all([tenant_id, client_id, client_secret, from_address]):
        return {"ok": False, "error": "email not configured on server"}
    to_address = (override or (_os.getenv("CREDIT_ENTRY_EMAIL_OVERRIDE") or "").strip()
                  or payload["player_email"])
    cc_addr = _auto_email_cc() if cc is None else cc
    ok = send_mail_graph(tenant_id=tenant_id, client_id=client_id,
                         client_secret=client_secret, from_address=from_address,
                         to_address=to_address, subject=payload["subject"],
                         html_body=payload["html_body"],
                         cc_address=(cc_addr or None))
    try:
        log_message({"event_name": payload["event_name"], "channel": "email",
                     "recipient_name": payload["player_name"],
                     "recipient_address": to_address, "subject": payload["subject"],
                     "body_preview": f"Entry confirmation — credit covered fee (item:{item_id})",
                     "status": "sent" if ok else "failed",
                     "sent_by": "manual" if force else "auto"})
    except Exception:
        logger.warning("Failed to log entry-confirmation email", exc_info=True)
    return {"ok": bool(ok), "sent_to": to_address, "player_name": payload["player_name"]}


def _calc_event_pricing_breakdown(
    event: dict,
    user_status: str,
    holes: str,
    side_games: str,
) -> dict | None:
    """Server-side pricing breakdown matching the JS calcPricingLine in events.html.

    Returns a dict with:
        subtotal:     ceil(course_cost) + markup + side_game_fee + game_addon
                      (the whole-dollar charge BEFORE the transaction fee)
        tx_fee:       transaction fee on subtotal (typically 3.5%)
        total:        subtotal + tx_fee (full player-facing price)

    Returns None if the event has no pricing configured.
    """
    import math

    # Normalise inputs
    holes_str = str(holes or "").strip()
    status_upper = (user_status or "").upper()
    games_upper = (side_games or "").upper()
    fmt_raw = event.get("format") or ""
    fmt = fmt_raw.lower()
    is_combo = "combo" in fmt or "9/18" in fmt
    is_27 = fmt_raw.strip() == "27 Holes"

    # Pick course cost / markup / side-game-fee based on holes
    if is_combo and holes_str == "18":
        cc = event.get("course_cost_18")
        mu_member = event.get("tgf_markup_18") or event.get("tgf_markup")
        sg = event.get("side_game_fee_18") or event.get("side_game_fee")
    elif is_combo or holes_str == "9":
        cc = event.get("course_cost_9") or event.get("course_cost")
        mu_member = event.get("tgf_markup_9") or event.get("tgf_markup")
        sg = event.get("side_game_fee_9") or event.get("side_game_fee")
    else:
        cc = event.get("course_cost")
        mu_member = event.get("tgf_markup")
        sg = event.get("side_game_fee")

    if cc is None or mu_member is None:
        return None

    cc = float(cc or 0)
    mu_member = float(mu_member or 0)
    sg = float(sg or 0)
    tf = float(event.get("transaction_fee_pct") or 3.5)

    # Player-type markup adjustment.
    # 27 Holes: guest +$25, no 1st Timer tier (1st Timer falls back to guest pricing).
    if is_27:
        guest_extra = 25.0
    elif holes_str == "18" and not is_combo:
        guest_extra = 15.0
    else:
        guest_extra = 10.0

    if "GUEST" in status_upper:
        mu = mu_member + guest_extra
    elif "1ST" in status_upper or "FIRST" in status_upper:
        # 27 Holes does not offer 1st Timer pricing — charge as guest
        mu = mu_member + guest_extra if is_27 else (mu_member + guest_extra - 25.0)
    else:
        mu = mu_member

    # Game addon. 27 Holes uses the per-event override (events.per_game_addon),
    # falling back to $27. 18 Holes standalone = $30, everything else = $16.
    if is_27:
        per_game_override = event.get("per_game_addon")
        if per_game_override is not None and per_game_override != "":
            try:
                per_game = float(per_game_override)
            except (TypeError, ValueError):
                per_game = _PER_GAME_ADDON_27
        else:
            per_game = _PER_GAME_ADDON_27
    elif holes_str == "18" and not is_combo:
        per_game = _PER_GAME_ADDON_18
    else:
        per_game = _PER_GAME_ADDON
    if games_upper in ("BOTH",):
        game_addon = per_game * 2
    elif games_upper in ("NET", "GROSS"):
        game_addon = per_game
    else:
        game_addon = 0.0

    rounded_cc = math.ceil(cc)
    event_charge = rounded_cc + mu + sg + game_addon
    subtotal = float(math.ceil(event_charge))
    tx_fee = round(subtotal * tf / 100, 2)
    return {
        "subtotal": subtotal,
        "tx_fee": tx_fee,
        "total": round(subtotal + tx_fee, 2),
    }


def _calc_event_price_for_player(
    event: dict,
    user_status: str,
    holes: str,
    side_games: str,
) -> float | None:
    """Returns the full player-facing total (including tx fee), or None if the event
    has no pricing configured. Thin wrapper around _calc_event_pricing_breakdown.
    """
    breakdown = _calc_event_pricing_breakdown(event, user_status, holes, side_games)
    return breakdown["total"] if breakdown else None


def get_rsvp_credit_info(rsvp_id: int, db_path: str | Path | None = None) -> dict | None:
    """Full credit analysis for a single RSVP row.

    Returns None if the RSVP isn't matched to an event, or the player has no credits.
    Returns a dict with:
        player_name, player_email, event_name, credits (list), total_credit,
        new_event_price (or None), amount_owed (positive = owes, negative = excess),
        can_calculate, selections (holes/games/tee/status from most recent credit)
    """
    with _connect(db_path) as conn:
        rsvp = conn.execute("SELECT * FROM rsvps WHERE id = ?", (rsvp_id,)).fetchone()
        if not rsvp:
            return None
        rsvp = dict(rsvp)

        if not rsvp.get("matched_event"):
            return None

        # Resolve the player. The rsvp's own customer_id is authoritative
        # (rule 6) — the matched item is only trusted when its email
        # matches the rsvp's, because the first-name matcher can pin a
        # rsvp to the WRONG player's item (Daniel South's Vaaler rsvp →
        # Daniel Lehan's purchase, 2026-07-15). Resolving through such an
        # item would surface — and apply — the other player's credits.
        customer_name = rsvp.get("player_name") or ""
        cust_id = rsvp.get("customer_id")
        rsvp_email = (rsvp.get("player_email") or "").strip()
        if cust_id:
            crow = conn.execute(
                "SELECT TRIM(first_name || ' ' || last_name) AS n "
                "FROM customers WHERE customer_id = ?",
                (cust_id,),
            ).fetchone()
            if crow and (crow["n"] or "").strip():
                customer_name = crow["n"].strip()
        elif rsvp.get("matched_item_id"):
            item_row = conn.execute(
                "SELECT customer, customer_email FROM items WHERE id = ?",
                (rsvp["matched_item_id"],),
            ).fetchone()
            if item_row:
                item_email = (item_row["customer_email"] or "").strip().lower()
                if (not rsvp_email or not item_email
                        or rsvp_email.lower() == item_email):
                    customer_name = item_row["customer"] or customer_name

        credits = get_player_credits(customer_name, db_path,
                                     customer_id=cust_id,
                                     player_email=rsvp_email or None)
        if not credits:
            return None

        total_credit = sum(c["credit_amount"] for c in credits)

        # Previous selections from the most recent credited item
        most_recent = credits[0]
        selections = {
            "user_status": most_recent.get("user_status") or "MEMBER",
            "holes":       most_recent.get("holes") or "9",
            "side_games":  most_recent.get("side_games") or "NONE",
            "tee_choice":  most_recent.get("tee_choice") or "",
        }

        # New event pricing
        event_row = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (rsvp["matched_event"],),
        ).fetchone()
        event = dict(event_row) if event_row else {}

        breakdown = _calc_event_pricing_breakdown(
            event,
            selections["user_status"],
            selections["holes"],
            selections["side_games"],
        )
        can_calculate = breakdown is not None
        new_event_price = breakdown["total"] if breakdown else None
        new_event_subtotal = breakdown["subtotal"] if breakdown else None

        # Balance due is computed against the pre-tx-fee subtotal — the difference
        # will be paid via Venmo (no merchant fee), so charging tx fee on it is unnecessary.
        amount_owed = round((new_event_subtotal or 0) - total_credit, 2)

        return {
            "rsvp_id": rsvp_id,
            "player_name": customer_name,
            "player_email": rsvp.get("player_email") or "",
            "event_name": rsvp["matched_event"],
            "event_date": event.get("event_date") or "",
            "course": event.get("course") or "",
            "credits": [
                {
                    "item_id": c["id"],
                    "id": c["id"],
                    "event_name": c["item_name"],
                    "item_name": c["item_name"],
                    "origin_event": c.get("origin_event") or c["item_name"],
                    "credit_amount": c["credit_amount"],
                    "order_date": c.get("order_date") or "",
                    "user_status": c.get("user_status") or "",
                    "holes": c.get("holes") or "",
                    "side_games": c.get("side_games") or "",
                    "tee_choice": c.get("tee_choice") or "",
                }
                for c in credits
            ],
            "total_credit": total_credit,
            "new_event_price": new_event_price,
            "new_event_subtotal": new_event_subtotal,
            "amount_owed": amount_owed,
            "can_calculate": can_calculate,
            "selections": selections,
        }


def get_event_rsvp_credit_map(event_name: str, db_path: str | Path | None = None) -> dict:
    """Return {customer_name: credit_info} for all RSVP-only players in an event.

    Covers both items-table RSVPs (rsvp_only / gg_rsvp) and unmatched GG RSVPs
    from the rsvps table (synthetic rows on the frontend).
    """
    with _connect(db_path) as conn:
        rsvp_items = conn.execute(
            """SELECT i.id, i.customer, i.customer_id,
                      r.player_email AS gg_email
               FROM items i
               LEFT JOIN rsvps r ON r.matched_item_id = i.id
               WHERE i.item_name = ? COLLATE NOCASE
                 AND COALESCE(i.transaction_status, 'active') IN ('rsvp_only', 'gg_rsvp')
                 AND i.parent_item_id IS NULL""",
            (event_name,),
        ).fetchall()

        # GG RSVPs that render as synthetic JS rows on the frontend. MUST
        # stay in parity with the frontend's unmatchedPlaying filter: a
        # rsvp whose matched item is active but carries a DIFFERENT email
        # is treated as mis-matched (the first-name matcher pinned it to
        # the wrong player's item — Daniel South → Daniel Lehan's Vaaler
        # purchase, 2026-07-15) and re-displayed as its own row; without
        # this branch the credit map never considered those players, so
        # their badge silently vanished.
        rsvp_rows = conn.execute(
            """SELECT r.id, r.player_name, r.player_email, r.customer_id
               FROM rsvps r
               WHERE r.matched_event = ? COLLATE NOCASE
                 AND r.response = 'PLAYING'
                 AND (r.matched_item_id IS NULL
                      OR NOT EXISTS (
                          SELECT 1 FROM items i
                          WHERE i.id = r.matched_item_id
                            AND COALESCE(i.transaction_status, 'active') = 'active'
                      )
                      OR EXISTS (
                          SELECT 1 FROM items i
                          WHERE i.id = r.matched_item_id
                            AND COALESCE(i.transaction_status, 'active') = 'active'
                            AND COALESCE(i.customer_email, '') != ''
                            AND COALESCE(r.player_email, '') != ''
                            AND LOWER(i.customer_email) != LOWER(r.player_email)
                      ))""",
            (event_name,),
        ).fetchall()

        # Build email → canonical customer name lookup for rsvp rows
        email_to_customer = {}
        email_to_customer_id: dict[str, int] = {}
        email_to_canonical_name: dict[str, str] = {}
        for rr in rsvp_rows:
            email = (rr["player_email"] or "").strip().lower()
            if email and email not in email_to_customer:
                card = conn.execute(
                    """SELECT customer FROM items
                       WHERE LOWER(customer_email) = ?
                         AND customer IS NOT NULL AND customer != ''
                       ORDER BY order_date DESC LIMIT 1""",
                    (email,),
                ).fetchone()
                if card:
                    email_to_customer[email] = card["customer"]
            # Also look up customer_id via customer_emails table for robust credit matching
            if email and email not in email_to_customer_id:
                ce_row = conn.execute(
                    """SELECT ce.customer_id,
                              TRIM(c.first_name || ' ' || c.last_name) AS full_name
                       FROM customer_emails ce
                       JOIN customers c ON c.customer_id = ce.customer_id
                       WHERE LOWER(ce.email) = ?
                       LIMIT 1""",
                    (email,),
                ).fetchone()
                if ce_row:
                    email_to_customer_id[email] = ce_row["customer_id"]
                    cname = (ce_row["full_name"] or "").strip()
                    if cname:
                        email_to_canonical_name[email] = cname

        # The rsvps row's own customer_id is the most reliable identity
        # (rule 6): it's resolved at parse time and survives a wrong
        # matched_item_id, which only carries the OTHER player's identity.
        rsvpid_to_cid: dict[int, int] = {}
        rsvpid_to_name: dict[int, str] = {}
        for rr in rsvp_rows:
            if rr["customer_id"]:
                crow = conn.execute(
                    "SELECT TRIM(first_name || ' ' || last_name) AS n "
                    "FROM customers WHERE customer_id = ?",
                    (rr["customer_id"],),
                ).fetchone()
                rsvpid_to_cid[rr["id"]] = rr["customer_id"]
                if crow and (crow["n"] or "").strip():
                    rsvpid_to_name[rr["id"]] = crow["n"].strip()

    result = {}

    # Item-based RSVPs (rsvp_only / gg_rsvp items in the items table)
    for row in rsvp_items:
        customer = row["customer"]
        if not customer:
            continue
        cust_id = row["customer_id"] if row["customer_id"] else None
        gg_email = (row["gg_email"] or "").strip().lower() or None
        credits = get_player_credits(customer, db_path, customer_id=cust_id, player_email=gg_email)
        if credits:
            result[customer] = {
                "total_credit": sum(c["credit_amount"] for c in credits),
                "credits": [
                    {"item_id": c["id"], "event_name": c["item_name"],
                     "origin_event": c.get("origin_event") or c["item_name"],
                     "credit_amount": c["credit_amount"]}
                    for c in credits
                ],
                "item_id": row["id"],
                "rsvp_id": None,
            }

    # GG RSVPs from rsvps table (synthetic frontend rows)
    for rr in rsvp_rows:
        email = (rr["player_email"] or "").strip().lower()
        # Name resolution mirrors get_rsvps_for_event (which feeds the
        # frontend's resolved_name): customers table via the rsvp's own
        # customer_id first, then email lookups, then raw GG first name.
        customer = (
            rsvpid_to_name.get(rr["id"])
            or email_to_customer.get(email)
            or email_to_canonical_name.get(email)
            or rr["player_name"]
            or ""
        )
        cust_id = (rsvpid_to_cid.get(rr["id"])
                   or (email_to_customer_id.get(email) if email else None))
        if not customer or customer in result:
            continue
        credits = get_player_credits(
            customer, db_path, customer_id=cust_id, player_email=email or None
        )
        if credits:
            result[customer] = {
                "total_credit": sum(c["credit_amount"] for c in credits),
                "credits": [
                    {"item_id": c["id"], "event_name": c["item_name"],
                     "origin_event": c.get("origin_event") or c["item_name"],
                     "credit_amount": c["credit_amount"]}
                    for c in credits
                ],
                "item_id": None,
                "rsvp_id": rr["id"],
            }

    return result


def create_rsvp_only_item(
    event_name: str,
    player_name: str,
    player_email: str,
    rsvp_id: int | None = None,
    db_path: str | Path | None = None,
) -> int:
    """Create a rsvp_only items row for a GG RSVP player so credits can be applied.

    Idempotent — returns existing item_id if the row was already created for this rsvp_id.
    """
    import datetime as _dt

    with _connect(db_path) as conn:
        uid = f"manual-gg-rsvp-{rsvp_id}" if rsvp_id else f"manual-gg-rsvp-name-{player_name}"
        existing = conn.execute(
            "SELECT id FROM items WHERE email_uid = ?", (uid,)
        ).fetchone()
        if existing:
            return existing["id"]

        event_row = conn.execute(
            "SELECT chapter FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,),
        ).fetchone()
        chapter = event_row["chapter"] if event_row else ""

        # Promoting a GG RSVP has no transaction to trigger the normal
        # _resolve_or_create_customer() call, so resolve/create the canonical
        # customers row now — otherwise customer_id stays NULL forever
        # (Membership Terms, roles, and status edits all require it), and
        # apply_credit_to_rsvp() runs against this row immediately after.
        cid = _resolve_or_create_customer(conn, player_name, player_email or None)

        conn.execute(
            """INSERT INTO items
               (email_uid, merchant, customer, customer_email, item_name,
                item_price, transaction_status, order_date, chapter, customer_id)
               VALUES (?, 'Golf Genius RSVP', ?, ?, ?, '', 'rsvp_only', date('now'), ?, ?)""",
            (uid, player_name, player_email or "", event_name, chapter or "", cid),
        )
        conn.commit()
        return conn.execute("SELECT last_insert_rowid() AS id").fetchone()["id"]


def reverse_credit_application(item_id: int, db_path: str | Path | None = None) -> dict:
    """Undo a credit application: restore source credits and revert the registration.

    - Finds items that were transferred to item_id and reverts them to 'credited'.
    - Removes the excess credit item if one was created.
    - Marks the transfer accounting entries as reversed.
    - Reverts the target item to 'rsvp_only' (or deletes it if it was a synthetic GG item).
    - Detaches every +PAY child (whether tagged [xfer-consumed:<id>] or attached
      later by auto_match_venmo_inbound_to_balance_due). Any payment-bearing child
      is converted to a standalone 'credited' item so the player keeps the money
      they actually paid.
    """
    import time as _time
    with _connect(db_path) as conn:
        item = conn.execute("SELECT * FROM items WHERE id = ?", (item_id,)).fetchone()
        if not item:
            return {"ok": False, "error": "Item not found"}
        item = dict(item)

        if item.get("merchant") != "Paid Separately (Credit Transfer)":
            return {"ok": False, "error": "Not a credit-transfer registration"}

        sources = conn.execute(
            "SELECT * FROM items WHERE transferred_to_id = ? AND transaction_status = 'transferred'",
            (item_id,),
        ).fetchall()
        if not sources:
            return {"ok": False, "error": "No transferred source items found — may already be reversed"}

        for s in sources:
            conn.execute(
                """UPDATE items
                   SET transaction_status = 'credited',
                       credit_note = NULL,
                       transferred_to_id = NULL
                   WHERE id = ?""",
                (s["id"],),
            )
            conn.execute(
                "UPDATE acct_transactions SET status = 'reversed' WHERE source_ref = ?",
                (f"xfer-flat-{s['id']}-out",),
            )

        # ── Handle every +PAY child attached to this parent ──
        # Two distinct paths put rows here:
        #   1. apply_credit_to_rsvp's _consume_unallocated_payments path tags
        #      the child with [xfer-consumed:<id>] (drops the tag, detaches).
        #   2. auto_match_venmo_inbound_to_balance_due creates a fresh +PAY row
        #      with no tag — its underlying Venmo payment is real money in.
        # The fix: detach all of them, and for any row that carries a real
        # item_price, convert it to a standalone 'credited' item so the player
        # keeps the credit on their account.
        consumed_tag = _XFER_CONSUMED_TAG.format(parent_id=item_id)
        children = conn.execute(
            "SELECT * FROM items WHERE parent_item_id = ?",
            (item_id,),
        ).fetchall()
        converted_to_credit = []
        detached_consumed = []
        for cr in children:
            cr = dict(cr)
            notes = cr.get("notes") or ""
            child_status = cr.get("transaction_status") or "active"
            had_consumed_tag = consumed_tag in notes

            if had_consumed_tag:
                cleaned = " ".join(notes.replace(consumed_tag, "").split())
                conn.execute(
                    "UPDATE items SET parent_item_id = NULL, notes = ? WHERE id = ?",
                    (cleaned or None, cr["id"]),
                )
                detached_consumed.append(cr["id"])
                continue

            # Untagged +PAY child — created by Venmo auto-match (or manual entry).
            # Convert to a standalone credited item so the money stays as a credit.
            price_amt = _parse_dollar(cr.get("item_price"))
            if price_amt > 0 and child_status not in ("credited", "refunded"):
                customer_name = cr.get("customer") or item.get("customer", "")
                event_name = cr.get("item_name") or item.get("item_name", "")
                credit_note = (
                    f"Credit from cancelled credit transfer — ${price_amt:.2f} from {event_name}"
                ).strip()
                conn.execute(
                    """UPDATE items
                       SET parent_item_id = NULL,
                           transaction_status = 'credited',
                           credit_note = ?,
                           merchant = COALESCE(NULLIF(merchant, ''), 'Manual Entry')
                       WHERE id = ?""",
                    (credit_note, cr["id"]),
                )
                converted_to_credit.append({"id": cr["id"], "amount": price_amt})
                # Clear matched_item_id on any expense_transaction that pointed
                # here so a future "Match Venmo" run can re-attach it cleanly.
                conn.execute(
                    "UPDATE expense_transactions SET matched_item_id = NULL WHERE matched_item_id = ?",
                    (cr["id"],),
                )
            else:
                # Zero-price or already-credited child — just detach.
                conn.execute(
                    "UPDATE items SET parent_item_id = NULL WHERE id = ?",
                    (cr["id"],),
                )
                detached_consumed.append(cr["id"])

        # Remove excess + overpayment credit items if created
        conn.execute(
            "DELETE FROM items WHERE email_uid LIKE ?",
            (f"credit-excess-{item_id}-%",),
        )
        conn.execute(
            "DELETE FROM items WHERE email_uid LIKE ?",
            (f"overpayment-credit-{item_id}-%",),
        )

        # Reverse transfer_in accounting entry
        conn.execute(
            "UPDATE acct_transactions SET status = 'reversed' WHERE source_ref = ?",
            (f"xfer-flat-{item_id}-in",),
        )

        # Revert or delete target item
        email_uid = item.get("email_uid") or ""
        if email_uid.startswith("manual-gg-rsvp-"):
            conn.execute("DELETE FROM items WHERE id = ?", (item_id,))
        else:
            conn.execute(
                """UPDATE items
                   SET transaction_status = 'rsvp_only',
                       merchant = '',
                       item_price = '',
                       holes = '',
                       side_games = '',
                       tee_choice = '',
                       user_status = '',
                       transferred_from_id = NULL,
                       credit_note = NULL
                   WHERE id = ?""",
                (item_id,),
            )

        conn.commit()
        return {
            "ok": True,
            "sources_restored": len(sources),
            "children_converted_to_credit": converted_to_credit,
            "children_detached": detached_consumed,
        }


def mark_rsvp_credit_notified(rsvp_id: int, db_path: str | Path | None = None) -> None:
    """Stamp credit_notified_at on the rsvp row so we don't re-send."""
    import datetime as _dt
    with _connect(db_path) as conn:
        conn.execute(
            "UPDATE rsvps SET credit_notified_at = ? WHERE id = ?",
            (_dt.datetime.utcnow().isoformat(), rsvp_id),
        )
        conn.commit()


# Tag appended to a +PAY item's `notes` when its parent_item_id was set by
# Apply Credit / reconcile_orphan_venmo_payments. Lets undo find and detach it.
_XFER_CONSUMED_TAG = "[xfer-consumed:{parent_id}]"


def _sum_existing_child_payments(conn, parent_item_id: int) -> dict:
    """Sum active manual-entry +PAY children already attached to this parent.
    Catches the case where a Venmo / cash payment was entered against the
    credit-transfer parent but the parent's credit_note was never reduced.

    Case-insensitive match on `merchant LIKE 'Manual Entry%'` so we accept
    "Manual Entry", "Manual Entry (venmo)", "Manual Entry (Venmo)",
    "Manual Entry (Cash)", etc.
    """
    rows = conn.execute(
        """SELECT id, item_price
           FROM items
           WHERE parent_item_id = ?
             AND COALESCE(transaction_status, 'active') = 'active'
             AND merchant LIKE 'Manual Entry%' COLLATE NOCASE""",
        (parent_item_id,),
    ).fetchall()
    total = 0.0
    ids: list[int] = []
    for r in rows:
        amt = _parse_dollar(r["item_price"])
        if amt > 0:
            total += amt
            ids.append(r["id"])
    return {"total": round(total, 2), "ids": ids}


def _consume_unallocated_payments_for_credit_transfer(
    conn,
    parent_item_id: int,
    customer: str,
    amount_owed: float,
    max_days_back: int = 14,
    exclude_ids: set | None = None,
) -> dict:
    """Find orphan manual-payment +PAY items for this customer and reparent them
    onto the credit-transfer item, up to (and beyond) amount_owed.

    Greedy: consumes oldest-first until amount_owed is covered. Continues
    consuming any further orphans dated *after* the most recent consumed one
    only if amount_owed > 0; otherwise stops once paid (we don't want to sweep
    unrelated future deposits).

    Returns: {"consumed_total": float, "consumed_ids": list[int], "remaining_owed": float}
    """
    exclude_ids = exclude_ids or set()
    rows = conn.execute(
        """SELECT id, item_price, notes, order_date
           FROM items
           WHERE customer = ? COLLATE NOCASE
             AND parent_item_id IS NULL
             AND COALESCE(transaction_status, 'active') = 'active'
             AND merchant LIKE 'Manual Entry%' COLLATE NOCASE
             AND order_date >= date('now', ?)
           ORDER BY order_date ASC, id ASC""",
        (customer, f"-{int(max_days_back)} days"),
    ).fetchall()

    consumed_total = 0.0
    consumed_ids: list[int] = []
    remaining = max(0.0, float(amount_owed or 0))

    for r in rows:
        rid = r["id"]
        if rid in exclude_ids or rid == parent_item_id:
            continue
        amt = _parse_dollar(r["item_price"])
        if amt <= 0:
            continue
        # Stop once we've covered the owed amount — leaves later deposits
        # untouched so we don't grab unrelated payments.
        if remaining <= 0 and consumed_total >= float(amount_owed or 0):
            break

        tag = _XFER_CONSUMED_TAG.format(parent_id=parent_item_id)
        existing_notes = r["notes"] or ""
        new_notes = (existing_notes + " " + tag).strip() if existing_notes else tag
        conn.execute(
            "UPDATE items SET parent_item_id = ?, notes = ? WHERE id = ?",
            (parent_item_id, new_notes, rid),
        )
        consumed_total += amt
        consumed_ids.append(rid)
        remaining = max(0.0, remaining - amt)

    return {
        "consumed_total": round(consumed_total, 2),
        "consumed_ids": consumed_ids,
        "remaining_owed": round(max(0.0, float(amount_owed or 0) - consumed_total), 2),
    }


def _post_overpayment_credit(
    conn,
    rsvp_item: dict,
    parent_item_id: int,
    overpayment: float,
) -> int | None:
    """Post a new transaction_status='credited' item for an overpayment surplus
    so it shows up in the customer's available credit pool. Returns the new id.
    """
    if overpayment <= 0:
        return None
    import time as _time
    uid = f"overpayment-credit-{parent_item_id}-{int(_time.time() * 1000)}"
    cur = conn.execute(
        """INSERT INTO items
           (email_uid, merchant, customer, customer_email, item_name,
            item_price, transaction_status, credit_note,
            order_date, chapter, customer_id)
           VALUES (?, 'Manual Entry', ?, ?, ?,
            ?, 'credited', ?,
            date('now'), ?, ?)""",
        (
            uid,
            rsvp_item.get("customer"), rsvp_item.get("customer_email"),
            f"Overpayment credit — {rsvp_item.get('item_name') or ''}".strip(" —"),
            f"${overpayment:.2f}",
            f"Overpayment credit — ${overpayment:.2f} from prior Venmo payment",
            rsvp_item.get("chapter") or "",
            # Copy from the registration this surplus came from — already
            # resolved (create_rsvp_only_item / a real order), no new lookup
            # needed.
            rsvp_item.get("customer_id"),
        ),
    )
    return cur.lastrowid


def apply_credit_to_rsvp(
    rsvp_item_id: int,
    credited_item_ids: list[int],
    excess_action: str = "keep",
    holes: str = "",
    side_games: str = "",
    tee_choice: str = "",
    user_status: str = "",
    package_index: int | None = None,
    db_path: str | Path | None = None,
) -> dict:
    """Apply player credits to an RSVP-only item, converting it to an active registration.

    - Carries selections (holes, side_games, tee_choice, user_status) onto the item.
    - Marks credited items as 'transferred'.
    - Creates accounting transfer entries.
    - excess_action='keep': leftover credit stays as a new credited item.
    - excess_action='note': just records the excess amount, admin handles manually.
    - package_index (mailbox #281, Kerry-ratified 2026-08-05): on events with
      package configs the selected PACKAGE is the price — the per-holes pricing
      chain produces prices matching no sellable combination on multi-day
      events (Callaway $355 case). Games derive from the package label and the
      registration is pinned to the package so the roster chips it.
    Returns dict with ok, amount_applied, excess.
    """
    import time as _time
    import datetime as _dt

    with _connect(db_path) as conn:
        # Load the RSVP item
        rsvp_item = conn.execute("SELECT * FROM items WHERE id = ?", (rsvp_item_id,)).fetchone()
        if not rsvp_item:
            return {"ok": False, "error": "RSVP item not found"}
        rsvp_item = dict(rsvp_item)

        # Load the credited items to sum (supports both 'credited' rows and
        # WD rows that carry an outstanding credit in their credit_amount column)
        credited_items = []
        total_credit = 0.0
        for cid in credited_item_ids:
            row = conn.execute("SELECT * FROM items WHERE id = ?", (cid,)).fetchone()
            if not row:
                continue
            d = dict(row)
            status = d.get("transaction_status")
            if status not in ("credited", "wd"):
                continue
            # Single source of truth (Kerry 2026-07-20): _item_credit_value
            # — no fees, minus partial carve-outs. The old inline formula
            # here still counted fees, so the SERVER applied $141.92 of
            # John White's $122 credit (owed $17 became owed $0, no
            # balance email) and armed Larry's excess watch at $14.08
            # when the true excess was $4.00.
            amt = _item_credit_value(conn, d)
            if amt <= 0:
                continue
            d["_is_wd_credit"] = (status == "wd")
            d["_credit_amt"] = amt
            total_credit += amt
            credited_items.append(d)

        if not credited_items:
            return {"ok": False, "error": "No valid credited items found"}

        # Determine new event price
        event_row = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (rsvp_item["item_name"],),
        ).fetchone()
        event = dict(event_row) if event_row else {}

        u_status = user_status or credited_items[0].get("user_status") or "MEMBER"
        # For non-combo events the holes value is fully determined by the event
        # format — must NOT inherit from the credited source item (which can be
        # a 9-hole credit applied at an 18-hole event). Inheriting was producing
        # wrong subtotals (PER_GAME_ADDON $16 vs $30) and writing 9 into the
        # HOLES column on 18-hole registrations.
        _evt_fmt = (event.get("format") or "")
        _is_combo = "combo" in _evt_fmt.lower() or "9/18" in _evt_fmt
        if _evt_fmt == "18 Holes" or _evt_fmt == "27 Holes":
            u_holes = "18"
        elif _evt_fmt == "9 Holes":
            u_holes = "9"
        else:
            # Combo — override > credited source > 9 fallback
            u_holes = holes or credited_items[0].get("holes") or "9"
        u_games = side_games or credited_items[0].get("side_games") or "NONE"
        u_tee = tee_choice or credited_items[0].get("tee_choice") or ""

        # Package-aware path (#281): validate the selected package against the
        # stored configs — the server reads the price from the configs, never
        # from the client.
        package = None
        if package_index is not None and event.get("id"):
            _pkgs = (_event_packages_all(db_path).get(str(event["id"]))
                     or {}).get("packages") or []
            try:
                package = _pkgs[int(package_index)]
            except (IndexError, ValueError, TypeError):
                return {"ok": False,
                        "error": f"package index {package_index} out of range"}
            _lbl = (package.get("label") or "").upper()
            u_games = "BOTH" if ("SIDE GAMES" in _lbl or "+ GAMES" in _lbl
                                 or "+ PRACTICE + GAMES" in _lbl
                                 or "GAMES)" in _lbl) else "NONE"

        breakdown = None if package else \
            _calc_event_pricing_breakdown(event, u_status, u_holes, u_games)
        # Compare credit against the pre-tx-fee subtotal: any balance due is paid via
        # Venmo (no merchant fee), so we don't charge tx fee on it. With a
        # package selected, the package price IS the subtotal (#281).
        new_subtotal = float(package["price"]) if package else \
            (breakdown["subtotal"] if breakdown else None)
        applied = min(total_credit, new_subtotal) if new_subtotal else total_credit
        excess = round(total_credit - (new_subtotal or total_credit), 2)

        # Update the RSVP item → active registration
        price_str = f"${applied:.2f} (credit transfer)"
        amount_owed = round((new_subtotal or 0) - applied, 2)

        # Net any prior payments by this customer against the balance due:
        #   1. Existing manual-entry +PAY children already attached to this row.
        #   2. Orphan manual-entry +PAY items dated in the last 14 days.
        existing_children = _sum_existing_child_payments(conn, rsvp_item_id)
        consumed = {"consumed_total": 0.0, "consumed_ids": [], "remaining_owed": amount_owed}
        overpayment_credit_id = None
        already_paid = existing_children["total"]
        if amount_owed > 0 and rsvp_item.get("customer"):
            remainder = max(0.0, round(amount_owed - already_paid, 2))
            if remainder > 0:
                consumed = _consume_unallocated_payments_for_credit_transfer(
                    conn,
                    parent_item_id=rsvp_item_id,
                    customer=rsvp_item["customer"],
                    amount_owed=remainder,
                    max_days_back=14,
                    exclude_ids={rsvp_item_id, *existing_children["ids"],
                                 *(ci["id"] for ci in credited_items)},
                )
        total_paid = round(already_paid + consumed["consumed_total"], 2)
        remaining_after_payments = max(0.0, round(amount_owed - total_paid, 2))
        overpayment = max(0.0, round(total_paid - amount_owed, 2))
        if amount_owed <= 0:
            balance_note = None
        elif remaining_after_payments > 0:
            balance_note = f"balance_due:{remaining_after_payments:.2f}"
        else:
            balance_note = f"paid_at:{_dt.datetime.utcnow().strftime('%Y-%m-%d')}"
            if overpayment > 0:
                overpayment_credit_id = _post_overpayment_credit(
                    conn, rsvp_item, rsvp_item_id, overpayment,
                )

        conn.execute(
            """UPDATE items
               SET transaction_status = 'active',
                   merchant = 'Paid Separately (Credit Transfer)',
                   item_price = ?,
                   holes = ?,
                   side_games = ?,
                   tee_choice = ?,
                   user_status = ?,
                   transferred_from_id = ?,
                   credit_note = ?
               WHERE id = ?""",
            (price_str, u_holes, u_games, u_tee, u_status,
             credited_items[0]["id"], balance_note, rsvp_item_id),
        )

        # Mark all credited items as consumed
        now_str = _dt.datetime.utcnow().isoformat()
        for ci in credited_items:
            if ci.get("_is_wd_credit"):
                # WD rows keep their status; just clear the credit_amount
                conn.execute(
                    """UPDATE items
                       SET credit_amount = NULL,
                           transferred_to_id = ?,
                           credit_note = ?
                       WHERE id = ?""",
                    (rsvp_item_id,
                     f"WD credit applied to {rsvp_item['item_name']} on {now_str[:10]}",
                     ci["id"]),
                )
            else:
                conn.execute(
                    """UPDATE items
                       SET transaction_status = 'transferred',
                           credit_note = ?,
                           transferred_to_id = ?
                       WHERE id = ?""",
                    (f"Applied to {rsvp_item['item_name']} on {now_str[:10]}",
                     rsvp_item_id, ci["id"]),
                )
            # Accounting: transfer_out on source (use the computed credit amount)
            try:
                _write_acct_entry(
                    conn,
                    item_id=ci["id"],
                    event_name=ci["item_name"],
                    customer=ci.get("customer", ""),
                    order_id=ci.get("order_id", ""),
                    entry_type="contra",
                    category="transfer_out",
                    source="manual",
                    amount=ci["_credit_amt"],
                    description=f"Credit transfer out → {rsvp_item['item_name']}",
                    account="TGF Checking",
                    source_ref=f"xfer-flat-{ci['id']}-out",
                    date=now_str[:10],
                )
            except Exception:
                logger.warning("Failed to write transfer_out for credit %s", ci["id"], exc_info=True)

        # Accounting: transfer_in on target
        try:
            _write_acct_entry(
                conn,
                item_id=rsvp_item_id,
                event_name=rsvp_item["item_name"],
                customer=rsvp_item.get("customer", ""),
                order_id=rsvp_item.get("order_id", ""),
                entry_type="income",
                category="transfer_in",
                source="credit_transfer",
                amount=applied,
                description=f"Credit transfer in from {credited_items[0]['item_name']}",
                account="TGF Checking",
                source_ref=f"xfer-flat-{rsvp_item_id}-in",
                date=now_str[:10],
            )
        except Exception:
            logger.warning("Failed to write transfer_in for rsvp item %s", rsvp_item_id, exc_info=True)

        # If excess and keep/venmo: create a new credited item for the remainder.
        # The excess credit row is the audit trail; for 'venmo' the caller
        # (app layer) arms a refund watch on excess_credit_id and opens Venmo,
        # so the receipt auto-records the refund — no manual followup.
        excess_credit_id = None
        if excess > 0 and excess_action in ("keep", "venmo"):
            uid = f"credit-excess-{rsvp_item_id}-{int(_time.time() * 1000)}"
            cur = conn.execute(
                """INSERT INTO items
                   (email_uid, merchant, customer, customer_email, item_name,
                    item_price, transaction_status, credit_note,
                    order_date, chapter, customer_id)
                   VALUES (?, 'Manual Entry', ?, ?, ?,
                    ?, 'credited', ?,
                    date('now'), ?, ?)""",
                (
                    uid,
                    rsvp_item.get("customer"), rsvp_item.get("customer_email"),
                    f"Excess credit — {rsvp_item['item_name'] or ''}".strip(" —"),
                    f"${excess:.2f}",
                    f"Excess credit from transfer — ${excess:.2f} remaining",
                    rsvp_item.get("chapter") or "",
                    # Copy from the registration being credited — already
                    # resolved, no new lookup needed.
                    rsvp_item.get("customer_id"),
                ),
            )
            excess_credit_id = cur.lastrowid

        conn.commit()
        # Pin the registration to its package AFTER the commit (the pin
        # writes app_settings through its own connection) so the roster
        # chips it and future balance math reads the same package (#281).
        if package is not None:
            try:
                assign_event_package(event["id"], rsvp_item_id,
                                     int(package_index), db_path=db_path)
            except Exception:
                logger.warning("apply-credit package pin failed for item %d",
                               rsvp_item_id, exc_info=True)
        return {
            "ok": True,
            "amount_applied": applied,
            "excess": excess,
            "excess_credit_id": excess_credit_id,
            "amount_owed": amount_owed,
            "already_paid_via_children": already_paid,
            "existing_child_payment_ids": existing_children["ids"],
            "consumed_payment_ids": consumed["consumed_ids"],
            "consumed_payment_total": consumed["consumed_total"],
            "total_paid": total_paid,
            "remaining_owed": remaining_after_payments,
            "overpayment_credit_id": overpayment_credit_id,
            "new_price": float(package["price"]) if package else
                (breakdown["total"] if breakdown else None),
            "new_subtotal": new_subtotal,
            "package": (package or {}).get("label"),
        }


def capture_venmo_handle_for_customer(
    expense_id: int,
    db_path: str | Path | None = None,
) -> bool:
    """If the expense has both a customer_id and an other_party_handle, set the
    customer's venmo_username (only when currently empty). Returns True if updated.
    Idempotent — safe to call multiple times for the same expense."""
    with _connect(db_path) as conn:
        exp = conn.execute(
            """SELECT customer_id, other_party_handle FROM expense_transactions
               WHERE id = ?""",
            (expense_id,),
        ).fetchone()
        if not exp:
            return False
        cust_id = exp["customer_id"]
        handle = (exp["other_party_handle"] or "").strip().lstrip("@")
        if not cust_id or not handle:
            return False
        cur = conn.execute(
            """UPDATE customers SET venmo_username = ?
               WHERE customer_id = ?
                 AND (venmo_username IS NULL OR venmo_username = '')""",
            (handle, cust_id),
        )
        conn.commit()
        return cur.rowcount > 0


# Monthly-points winnings memos ("Winnings for MARCH Points") — resolved
# to the month's own tgf_events account (v2.51.0); never to an event group
_MONTHLY_MEMO_RE = re.compile(
    r"winnings\s+for\s+(january|february|march|april|may|june|july|august|"
    r"september|october|november|december)\s+points", re.I)

# tgf_events accounts that are SEASON CONTESTS, not golf events (monthly
# points months; future: fellowship cup, match play). The /tgf page's
# SEASON CONTESTS tab and the monthly repair both use this convention.
_CONTEST_ACCOUNT_RE = re.compile(
    r"^(january|february|march|april|may|june|july|august|september|"
    r"october|november|december)\s+points|^(fellowship\s+cup|match\s+play)", re.I)


def record_monthly_points_payouts(force: bool = False, db_path=None) -> dict:
    """Record completed months' Monthly Points winners as tgf_payouts under
    a per-month tgf_events account (Kerry, 2026-07-08: monthly payouts must
    be trackable/confirmable like events — PAYOUTS → SEASON CONTESTS tab —
    and appear in Customers → Winnings).

    Winners + shares come from the persisted monthly-points snapshot
    ($1/member at month close, ties split). Each complete month gets a
    tgf_events row code '<MONTH> Points <YYYY>' (event_date = month end,
    chapter TGF); inserts delegate to import_tgf_payouts so ledger
    placeholders + Venmo reconciliation reuse the proven path, then the
    Venmo payout matcher runs so already-received 'Winnings for MARCH
    Points' receipts confirm immediately. Skips months whose account
    already has payout rows (force=True re-records auto rows). The daily
    monthly-points snapshot job calls this after each refresh.
    """
    import calendar as _cal
    snapshot = load_gg_snapshot("monthly_points", db_path or DB_PATH)
    if not snapshot or not snapshot.get("months"):
        return {"error": "no monthly points snapshot"}
    recorded, skipped = [], []
    for m in snapshot["months"]:
        if not m.get("complete") or not m.get("winners"):
            skipped.append({"month": m.get("month"), "reason": "incomplete or no winners"})
            continue
        year, mnum = int(m["month"][:4]), int(m["month"][5:7])
        code = f"{_cal.month_name[mnum].upper()} Points {year}"
        with _connect(db_path) as conn:
            row = conn.execute(
                "SELECT id FROM tgf_events WHERE LOWER(code) = LOWER(?)",
                (code,)).fetchone()
            if row:
                tgf_event_id = row["id"]
            else:
                cur = conn.execute(
                    """INSERT INTO tgf_events (code, name, event_date, course, chapter)
                       VALUES (?, ?, ?, ?, 'TGF')""",
                    (code, code, m.get("month_end") or "", "Monthly Points Race"))
                tgf_event_id = cur.lastrowid
            existing = conn.execute(
                "SELECT id, acct_transaction_id, description FROM tgf_payouts WHERE event_id = ?",
                (tgf_event_id,)).fetchall()
            if existing and not force:
                skipped.append({"month": m["month"], "reason": "already recorded"})
                conn.commit()
                continue
            if existing and force:
                for r in existing:
                    if not (r["description"] or "").startswith("auto:"):
                        continue
                    if r["acct_transaction_id"]:
                        txn = conn.execute(
                            "SELECT id, source FROM acct_transactions WHERE id = ?",
                            (r["acct_transaction_id"],)).fetchone()
                        if txn and txn["source"] == "pending":
                            conn.execute("DELETE FROM acct_transactions WHERE id = ?",
                                         (txn["id"],))
                    conn.execute("DELETE FROM tgf_payouts WHERE id = ?", (r["id"],))
            conn.commit()
        share = None
        winners = m["winners"]
        payouts = []
        for w in winners:
            share = w.get("share")
            if share is None:
                continue
            payouts.append({
                "golferName": w.get("player_name"),
                "category": "monthly_points",
                "amount": round(float(share), 2),
                "description": (f"auto: {code} winner — ${m.get('purse')} purse"
                                + (f" split {len(winners)} ways" if len(winners) > 1 else "")),
            })
        if not payouts:
            skipped.append({"month": m["month"], "reason": "winners have no share"})
            continue
        result = import_tgf_payouts(tgf_event_id, payouts, db_path=db_path)
        recorded.append({"month": m["month"], "code": code,
                         "winners": len(payouts), "result": result})
    out = {"recorded": recorded, "skipped": skipped}
    if recorded:
        try:
            vm = auto_match_venmo_payouts_to_tgf(db_path=db_path)
            out["venmo_matched"] = vm.get("matched", 0)
        except Exception:
            logger.warning("post-monthly-record venmo match failed", exc_info=True)
    return out


def _repair_false_monthly_venmo_matches(conn: sqlite3.Connection) -> None:
    """v2.50.1: revert tgf_payouts wrongly marked PAID by MONTHLY-points
    Venmo payments. Found live within an hour of v2.50.0: Straiton's
    $70.00 'Winnings for MARCH Points' payment ±$1-matched his $70.37
    a9.17 Falconhead group via the amount fallback. Monthly races are
    paid from the Contests page, not tgf_payouts — any payout row backed
    by an exp-promoted venmo txn whose memo is a monthly-points memo gets
    its pending placeholder reinstated (source_ref 'payout-<id>') and
    paid_at cleared. Idempotent."""
    rows = conn.execute(
        """SELECT p.id AS payout_id, p.amount, p.category,
                  x.notes, e.event_date, e.name AS event_name, e.code AS event_code
           FROM tgf_payouts p
           JOIN acct_transactions t ON t.id = p.acct_transaction_id
           JOIN expense_transactions x ON x.acct_transaction_id = t.id
           JOIN tgf_events e ON e.id = p.event_id
           WHERE t.source = 'venmo' AND t.source_ref LIKE 'exp-promoted-%'"""
    ).fetchall()
    fixed = 0
    for r in rows:
        if not _MONTHLY_MEMO_RE.search(r["notes"] or ""):
            continue
        # a monthly payment linked to the month's OWN account is the
        # correct outcome (v2.51.0 SEASON CONTESTS accounts) — leave it
        if _CONTEST_ACCOUNT_RE.match((r["event_code"] or "").strip()):
            continue
        ph = conn.execute(
            "SELECT id FROM acct_transactions WHERE source = 'pending' AND source_ref = ?",
            (f"payout-{r['payout_id']}",)).fetchone()
        if ph:
            conn.execute("UPDATE acct_transactions SET status = 'active' WHERE id = ?",
                         (ph["id"],))
            new_id = ph["id"]
        else:
            cur = conn.execute(
                """INSERT INTO acct_transactions
                       (date, description, total_amount, type, source, source_ref,
                        customer, order_id, entry_type, category, amount, account,
                        status, event_name)
                   VALUES (?, ?, ?, 'expense', 'pending', ?, ?, ?, 'expense', 'prize_payout',
                           ?, 'Venmo', 'active', ?)""",
                (r["event_date"], f"Payout: {r['category']} — {r['event_name']}",
                 round(float(r["amount"]), 2), f"payout-{r['payout_id']}", "",
                 f"PAYOUT-{r['payout_id']}", -round(float(r["amount"]), 2),
                 r["event_name"]))
            new_id = cur.lastrowid
        conn.execute(
            "UPDATE tgf_payouts SET acct_transaction_id = ?, paid_at = NULL WHERE id = ?",
            (new_id, r["payout_id"]))
        fixed += 1
        logger.info("Reverted payout %d falsely matched to a monthly-points Venmo payment",
                    r["payout_id"])
    if fixed:
        conn.commit()


def bulk_mark_payouts_paid(before_date: str, db_path=None) -> dict:
    """One-time cleanup (Kerry, 2026-07-09): every pending payout group
    from events dated before ``before_date`` was paid outside the receipt
    window (Venmo email capture only began mid-May), so mark them PAID.

    Per group, cheapest-honest accounting:
      1. If the customer has an UNCONSUMED promoted Venmo payout receipt
         within $3 of the group total, link the group to that receipt's
         ledger entry and reverse the pending placeholders — one real
         expense, receipt consumed (the "since May" class).
      2. Otherwise convert the group's pending placeholders to
         source='venmo' entries annotated '(bulk-confirmed paid)' and
         stamp paid_at = event_date — the payment predates receipt
         capture, so the placeholder becomes the expense of record.
         Rows with no ledger entry at all get one created.
    Idempotent — already-paid groups are not selected."""
    summary = {"groups": 0, "linked_receipt": 0, "converted": 0, "errors": 0}
    with _connect(db_path) as conn:
        groups = [dict(g) for g in conn.execute(
            """SELECT p.event_id, p.customer_id, e.event_date,
                      e.name AS event_name, ROUND(SUM(p.amount), 2) AS total
               FROM tgf_payouts p
               JOIN tgf_events e ON e.id = p.event_id
               LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
               WHERE e.event_date != '' AND e.event_date < ?
                 AND (p.acct_transaction_id IS NULL
                      OR (t.source = 'pending'
                          AND COALESCE(t.status, 'active') = 'active'))
               GROUP BY p.event_id, p.customer_id""",
            (before_date,)).fetchall()]
        for g in groups:
            try:
                rows = conn.execute(
                    """SELECT p.id, p.amount, p.category, p.acct_transaction_id,
                              t.source AS src
                       FROM tgf_payouts p
                       LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
                       WHERE p.event_id = ? AND p.customer_id = ?
                         AND (p.acct_transaction_id IS NULL
                              OR (t.source = 'pending'
                                  AND COALESCE(t.status, 'active') = 'active'))""",
                    (g["event_id"], g["customer_id"])).fetchall()
                rec = conn.execute(
                    """SELECT x.acct_transaction_id AS aid, x.transaction_date, x.amount
                       FROM expense_transactions x
                       WHERE x.source_type = 'venmo' AND x.transaction_type = 'payout'
                         AND x.customer_id = ? AND x.acct_transaction_id IS NOT NULL
                         AND ABS(x.amount - ?) <= 3.00
                         AND NOT EXISTS (SELECT 1 FROM tgf_payouts tp
                                         WHERE tp.acct_transaction_id = x.acct_transaction_id)
                       ORDER BY ABS(x.amount - ?) ASC LIMIT 1""",
                    (g["customer_id"], g["total"], g["total"])).fetchone()
                if rec:
                    paid = str(rec["transaction_date"] or "")
                    if not re.match(r"^\d{4}-\d{2}-\d{2}", paid):
                        paid = g["event_date"]
                    for r in rows:
                        if r["acct_transaction_id"] and r["src"] == "pending":
                            conn.execute(
                                "UPDATE acct_transactions SET status = 'reversed' WHERE id = ?",
                                (r["acct_transaction_id"],))
                        conn.execute(
                            "UPDATE tgf_payouts SET acct_transaction_id = ?, paid_at = ? WHERE id = ?",
                            (rec["aid"], paid, r["id"]))
                    summary["linked_receipt"] += 1
                else:
                    for r in rows:
                        if r["acct_transaction_id"] and r["src"] == "pending":
                            conn.execute(
                                """UPDATE acct_transactions
                                   SET source = 'venmo',
                                       description = description || ' (bulk-confirmed paid)'
                                   WHERE id = ?""", (r["acct_transaction_id"],))
                            new_id = r["acct_transaction_id"]
                        else:
                            cur = conn.execute(
                                """INSERT INTO acct_transactions
                                       (date, description, total_amount, type, source, source_ref,
                                        customer, order_id, entry_type, category, amount, account,
                                        status, event_name)
                                   VALUES (?, ?, ?, 'expense', 'venmo', ?, ?, ?, 'expense',
                                           'prize_payout', ?, 'Venmo', 'active', ?)""",
                                (g["event_date"],
                                 f"Payout: {r['category']} — {g['event_name']} (bulk-confirmed paid)",
                                 round(float(r["amount"]), 2), f"payout-{r['id']}", "",
                                 f"PAYOUT-{r['id']}", -round(float(r["amount"]), 2),
                                 g["event_name"]))
                            new_id = cur.lastrowid
                        conn.execute(
                            "UPDATE tgf_payouts SET acct_transaction_id = ?, paid_at = ? WHERE id = ?",
                            (new_id, g["event_date"], r["id"]))
                    summary["converted"] += 1
                summary["groups"] += 1
            except Exception:
                logger.exception("bulk mark paid failed for event %s customer %s",
                                 g.get("event_id"), g.get("customer_id"))
                summary["errors"] += 1
        conn.commit()
    logger.info("bulk_mark_payouts_paid(%s): %s", before_date, summary)
    return summary


def inspect_event_payouts(event_query: str, player: str | None = None,
                          db_path=None) -> dict:
    """READ-ONLY payout-state tracer (v2.139.1): every tgf_payouts row for
    one tgf event (code/name substring), with the linked acct_transactions
    row's source / source_ref / date / amount / status inlined. A payout
    linked to a non-pending ledger row renders PAID in the UI — this shows
    exactly WHICH ledger row claims it, so a wrong paid state is traceable
    (Kerry 2026-07-22: Reed showed paid with no receipt anywhere)."""
    with _connect(db_path) as conn:
        evs = [dict(r) for r in conn.execute(
            "SELECT id, code FROM tgf_events WHERE LOWER(code) LIKE LOWER(?) "
            "ORDER BY id", (f"%{event_query.strip()}%",)).fetchall()]
        if not evs:
            return {"error": f"no tgf_events match: {event_query}"}
        out = {"events": [], "query": event_query}
        for ev in evs:
            rows = [dict(r) for r in conn.execute(
                """SELECT p.id, p.customer_id,
                          TRIM(COALESCE(c.first_name,'') || ' ' ||
                               COALESCE(c.last_name,'')) AS player,
                          p.category, p.amount, p.description, p.paid_at,
                          p.acct_transaction_id,
                          t.source AS acct_source, t.source_ref AS acct_ref,
                          t.date AS acct_date, t.amount AS acct_amount,
                          t.status AS acct_status,
                          t.description AS acct_description
                   FROM tgf_payouts p
                   LEFT JOIN customers c ON c.customer_id = p.customer_id
                   LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
                   WHERE p.event_id = ?
                   ORDER BY player, p.category""", (ev["id"],)).fetchall()]
            if player:
                pl = player.lower()
                rows = [r for r in rows if pl in (r["player"] or "").lower()]
            for r in rows:
                r["state"] = ("UNLINKED" if not r["acct_transaction_id"]
                              else "DANGLING" if r["acct_source"] is None
                              else "PENDING" if r["acct_source"] == "pending"
                              else "PAID")
            out["events"].append({"tgf_event_id": ev["id"], "code": ev["code"],
                                  "rows": rows})
        return out


def get_unpaid_payout_groups(db_path=None) -> dict:
    """Every non-paid payout group (customer+account) with that customer's
    recent Venmo payout receipts alongside — the data behind the /tgf
    UNPAID tab investigation and the "why didn't this match?" question
    (Kerry, 2026-07-09). A receipt with linked=1 already backs some other
    payout group; amounts that differ from the group total explain the
    no-match."""
    with _connect(db_path) as conn:
        groups = [dict(g) for g in conn.execute(
            """SELECT e.code, e.event_date, p.customer_id,
                      TRIM(c.first_name || ' ' || c.last_name ||
                           COALESCE(' ' || NULLIF(TRIM(c.suffix), ''), '')) AS name,
                      ROUND(SUM(p.amount), 2) AS total, COUNT(*) AS payout_rows
               FROM tgf_payouts p
               JOIN tgf_events e ON e.id = p.event_id
               JOIN customers c ON c.customer_id = p.customer_id
               LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
               WHERE p.acct_transaction_id IS NULL
                  OR (t.source = 'pending' AND COALESCE(t.status, 'active') = 'active')
               GROUP BY p.event_id, p.customer_id
               ORDER BY e.event_date DESC, total DESC""").fetchall()]
        for g in groups:
            g["venmo_receipts"] = [dict(r) for r in conn.execute(
                """SELECT x.id, x.amount, x.transaction_date, x.notes,
                          CASE WHEN EXISTS (
                              SELECT 1 FROM tgf_payouts tp
                              WHERE tp.acct_transaction_id = x.acct_transaction_id)
                          THEN 1 ELSE 0 END AS linked
                   FROM expense_transactions x
                   WHERE x.source_type = 'venmo' AND x.transaction_type = 'payout'
                     AND x.customer_id = ?
                   ORDER BY x.transaction_date DESC LIMIT 6""",
                (g["customer_id"],)).fetchall()]
        total = round(sum(g["total"] for g in groups), 2)
        return {"unpaid_groups": len(groups), "unpaid_total": total, "groups": groups}


# ── Refund watches (v2.106.0, Kerry 2026-07-15) ──────────────────────
# The red Refund buttons pay via P2P deep links (Venmo/PayPal/Cash App;
# Zelle is record-and-watch, no deep link) and the provider's receipt
# email is the VERIFICATION: tapping a pay link registers a watch, the
# expense inbox ingests the receipt, and the matcher below records the
# credit payout automatically through payout_credit — same books as a
# manual Record Refund. Memo format (Kerry):
# "[First Name] [Last Name] - Credit for [Event Name]".

def _ensure_refund_watch_table(conn: sqlite3.Connection) -> None:
    conn.execute(
        """CREATE TABLE IF NOT EXISTS refund_watches (
            id                  INTEGER PRIMARY KEY AUTOINCREMENT,
            item_id             INTEGER NOT NULL REFERENCES items(id),
            customer_id         INTEGER REFERENCES customers(customer_id),
            customer_name       TEXT,
            method              TEXT NOT NULL,
            handle              TEXT,
            amount              REAL NOT NULL,
            memo                TEXT,
            initiated_at        TEXT DEFAULT (datetime('now')),
            verified_at         TEXT,
            verified_expense_id INTEGER,
            recorded            INTEGER DEFAULT 0
        )"""
    )
    conn.execute("CREATE INDEX IF NOT EXISTS idx_refund_watches_item "
                 "ON refund_watches(item_id)")


def create_refund_watch(item_id: int, method: str, amount: float,
                        memo: str = "", handle: str = "",
                        db_path: str | Path | None = None) -> dict:
    """Register 'a refund payment was just initiated for this credit'.
    One OPEN watch per item — re-tapping the pay link replaces the prior
    unverified watch instead of stacking (double-tap guard)."""
    with _connect(db_path) as conn:
        _ensure_refund_watch_table(conn)
        item = conn.execute("SELECT * FROM items WHERE id = ?",
                            (item_id,)).fetchone()
        if not item:
            return {"ok": False, "error": "Item not found"}
        item = dict(item)
        status = (item.get("transaction_status") or "active")
        if status not in ("credited", "wd"):
            return {"ok": False, "error": f"Item is '{status}' — only "
                    "credited/withdrawn rows carry a refundable credit"}
        try:
            amt = round(float(amount), 2)
        except (TypeError, ValueError):
            return {"ok": False, "error": "amount must be a number"}
        if amt <= 0:
            return {"ok": False, "error": "amount must be positive"}
        conn.execute("DELETE FROM refund_watches "
                     "WHERE item_id = ? AND verified_at IS NULL", (item_id,))
        cur = conn.execute(
            """INSERT INTO refund_watches
               (item_id, customer_id, customer_name, method, handle,
                amount, memo)
               VALUES (?, ?, ?, ?, ?, ?, ?)""",
            (item_id, item.get("customer_id"), item.get("customer"),
             method, (handle or "").strip(), amt, memo or ""),
        )
        conn.commit()
        return {"ok": True, "watch_id": cur.lastrowid, "amount": amt}


def get_refund_watch(item_id: int,
                     db_path: str | Path | None = None) -> dict | None:
    """Latest watch for an item (open or verified), or None."""
    with _connect(db_path) as conn:
        _ensure_refund_watch_table(conn)
        row = conn.execute(
            "SELECT * FROM refund_watches WHERE item_id = ? "
            "ORDER BY id DESC LIMIT 1", (item_id,)).fetchone()
        return dict(row) if row else None


def get_open_refund_watches(db_path: str | Path | None = None) -> list[dict]:
    with _connect(db_path) as conn:
        _ensure_refund_watch_table(conn)
        return [dict(r) for r in conn.execute(
            "SELECT * FROM refund_watches WHERE verified_at IS NULL "
            "ORDER BY initiated_at DESC").fetchall()]


def get_refunds_overview(db_path: str | Path | None = None,
                         completed_days: int = 120) -> dict:
    """Consolidated REFUNDS console (Kerry 2026-07-15: "I don't want to go to
    25 places … nothing falls thru the cracks").

    Three buckets, mirroring the PAYOUTS view's structure:

      * ``outstanding`` — credit balances we're holding that could be paid
        back: WD rows (credit in ``credit_amount``) and standalone credited
        rows (credit in ``item_price``), minus any with an OPEN refund watch
        (those are in flight). Sorted OLDEST FIRST so aging credits surface
        (Kerry's age-sorting; a per-item "Held" marker is a separate,
        ratification-pending schema add).
      * ``in_flight`` — open refund watches: a P2P pay link was tapped and we
        are waiting on the provider's receipt to verify.
      * ``completed`` — payouts recorded in the last ``completed_days`` days
        (status 'refunded', or WD rows stamped 'Refunded …'), newest first.

    Amounts are floats; ``age_days`` is Central-day based. Read-only.
    """
    import datetime as _dt
    import re as _re
    from email_parser.timezone_utils import today_central

    today = today_central()

    today_str = today.isoformat()

    def _age(datestr):
        try:
            d = _dt.datetime.strptime((datestr or "")[:10], "%Y-%m-%d").date()
            return max(0, (today - d).days)
        except Exception:
            return None

    def _credit_anchor(row):
        """Date a held credit's age counts from. For a real registration
        flipped to credited/wd (rain-out, withdrawal) the row's order_date is
        the REGISTRATION date, not when the credit arose — so anchor to the
        EVENT date (consistent across same-event credits, ≈ when the credit
        was actually created). Synthetic credit rows (excess/overpayment) are
        created AT credit time, so their order_date IS the credit date; keep
        it. Fall back to order_date when the event has no date or is still in
        the future (a credit on an upcoming event isn't aging yet)."""
        uid = (row.get("email_uid") or "").lower()
        name = (row.get("item_name") or "").lower()
        synthetic = (uid.startswith("credit-excess-") or uid.startswith("credit-overpay")
                     or name.startswith("excess credit") or name.startswith("overpayment"))
        ev = row.get("event_date")
        if synthetic or not ev or ev > today_str:
            return row.get("order_date")
        return ev

    stamp_re = _re.compile(r"Refunded \$([\d,]+\.?\d*) via (.+?) on (\d{4}-\d{2}-\d{2})")

    with _connect(db_path) as conn:
        _ensure_refund_watch_table(conn)
        open_watch_ids = {r["item_id"] for r in conn.execute(
            "SELECT item_id FROM refund_watches WHERE verified_at IS NULL").fetchall()}
        verified_ids = {r["item_id"] for r in conn.execute(
            "SELECT item_id FROM refund_watches WHERE verified_at IS NOT NULL").fetchall()}

        # OUTSTANDING — held credits not yet in flight / paid
        outstanding = []
        completed_removals: list = []
        for r in conn.execute(
            """SELECT it.id, it.customer, it.customer_id, it.item_name,
                      it.item_price, it.credit_amount, it.transaction_status,
                      it.order_date, it.credit_note, it.email_uid,
                      ev.event_date AS event_date
               FROM items it
               LEFT JOIN events ev ON ev.id = it.event_id
               WHERE LOWER(COALESCE(it.transaction_status,'')) IN ('wd','credited')"""
        ).fetchall():
            r = dict(r)
            status = (r.get("transaction_status") or "").lower()
            amt = _item_credit_value(conn, r)
            if amt <= 0 or r["id"] in open_watch_ids:
                continue
            anchor = _credit_anchor(r)
            # Inline Venmo refund (Kerry 2026-07-20: "Open up Venmo right
            # there... to allow me to refund"): handle + a memo in his
            # ratified shape, naming the ORIGIN event of the credit even
            # when it was applied elsewhere.
            _vh = None
            if r.get("customer_id"):
                _vrow = conn.execute(
                    "SELECT venmo_username FROM customers WHERE customer_id = ? "
                    "AND venmo_username IS NOT NULL AND venmo_username != ''",
                    (r["customer_id"],)).fetchone()
                if _vrow:
                    _vh = _vrow["venmo_username"]
            try:
                _full = dict(conn.execute(
                    "SELECT * FROM items WHERE id = ?", (r["id"],)).fetchone())
                _origin = _credit_origin_event(conn, _full) or r.get("item_name")
            except Exception:
                _origin = r.get("item_name")
            _kindword = ("Excess credit" if (r.get("item_name") or "")
                         .lower().startswith("excess credit")
                         else ("WD credit" if status == "wd" else "Credit"))
            _memo = f"{r.get('customer')} - {_kindword} from {_origin}"
            outstanding.append({
                "item_id": r["id"], "customer": r.get("customer"),
                "customer_id": r.get("customer_id"), "event": r.get("item_name"),
                "amount": round(amt, 2), "kind": status,
                "order_date": r.get("order_date"),
                "age_days": _age(anchor),
                "note": r.get("credit_note") or "",
                "venmo_handle": _vh, "memo": _memo,
            })

        # Season-contest removal refunds (Kerry 2026-07-20: "is it in overall
        # PAYOUTS where it should be, so I don't miss it?"). A removal
        # recorded with a refund amount is a promise to pay that previously
        # lived ONLY on the Enrollment tab's removals list — the Campos $40
        # sat invisible here. OUTSTANDING until a matching outbound Venmo
        # receipt lands (same person, same amount, on/after the removal
        # date — the expense inbox ingests those within ~2 min of sending);
        # then it shows COMPLETED. Rules-based, no new schema.
        try:
            venmo_out = [dict(v) for v in conn.execute(
                """SELECT date, description, customer, amount
                     FROM acct_transactions
                    WHERE source = 'venmo'
                      AND entry_type IN ('expense', 'contra')
                      AND COALESCE(status, 'active') = 'active'""").fetchall()]
            for rm in conn.execute(
                """SELECT r.*, c.venmo_username
                     FROM season_contest_removals r
                     LEFT JOIN customers c ON c.customer_id = r.customer_id
                    WHERE COALESCE(r.refund_amount, 0) > 0""").fetchall():
                rm = dict(rm)
                rm_day = (rm.get("removed_at") or "")[:10]
                pk = _cmp_person_key(rm.get("customer_name") or "")
                paid = next(
                    (v for v in venmo_out
                     if abs(float(v.get("amount") or 0)
                            - float(rm["refund_amount"])) < 0.005
                     and (v.get("date") or "") >= rm_day
                     and pk in (_cmp_person_key(v.get("customer") or ""),
                                _cmp_person_key(v.get("description") or ""))),
                    None)
                label = (f"{rm.get('contest_type')} {rm.get('season')} "
                         f"({rm.get('chapter')}) — removal refund")
                # Venmo memo format (Kerry 2026-07-20, refined same day):
                # "[Player] - [Reason] Refund for [Contest]" where a
                # stored reason like "Withdrew — Injury" condenses to
                # "WD (Injury)". No "City" prefix, no chapter, no
                # trailing "removal refund".
                _contest = re.sub(r"^City\s+", "",
                                  rm.get("contest_type") or "", flags=re.I)
                _raw = (rm.get("reason") or "").strip()
                _head, _detail = _raw, ""
                _m = re.match(r"^\s*([^—:-]+?)\s*(?:[—:-]|\()\s*(.*?)\)?\s*$",
                              _raw)
                if _m:
                    _head, _detail = _m.group(1).strip(), _m.group(2).strip()
                if re.match(r"^(withdrew|withdrawal|withdrawn|wd)\b",
                            _head, flags=re.I):
                    _head = "WD"
                elif _head:
                    _head = _head.title() if len(_head) <= 20 else "Removal"
                else:
                    _head = "Removal"
                _reason = _head + (f" ({_detail.title()})" if _detail else "")
                memo = (f"{rm.get('customer_name')} - {_reason} Refund "
                        f"for {_contest} {rm.get('season')}").strip()
                if paid:
                    age = _age(paid["date"])
                    if age is None or age <= completed_days:
                        completed_removals.append({
                            "removal_id": rm["id"],
                            "customer": rm.get("customer_name"),
                            "customer_id": rm.get("customer_id"),
                            "event": label,
                            "amount": round(float(rm["refund_amount"]), 2),
                            "method": rm.get("refund_method") or "Venmo",
                            "date": paid["date"], "via_watch": False,
                            "kind": "contest_refund"})
                else:
                    outstanding.append({
                        "removal_id": rm["id"],
                        "customer": rm.get("customer_name"),
                        "customer_id": rm.get("customer_id"),
                        "event": label,
                        "amount": round(float(rm["refund_amount"]), 2),
                        "kind": "contest_refund", "memo": memo,
                        "order_date": rm_day, "age_days": _age(rm_day),
                        "venmo_handle": rm.get("venmo_username"),
                        "note": rm.get("note") or ""})
        except Exception:
            logger.exception("refunds overview: removal-refund merge failed")

        outstanding.sort(key=lambda x: (x["age_days"] is None, -(x["age_days"] or 0)))

        # IN FLIGHT — open watches
        in_flight = []
        for w in conn.execute(
            """SELECT rw.*, it.item_name AS event
               FROM refund_watches rw
               LEFT JOIN items it ON it.id = rw.item_id
               WHERE rw.verified_at IS NULL
               ORDER BY rw.initiated_at"""
        ).fetchall():
            w = dict(w)
            in_flight.append({
                "item_id": w["item_id"], "customer": w.get("customer_name"),
                "customer_id": w.get("customer_id"), "event": w.get("event"),
                "amount": round(float(w.get("amount") or 0), 2),
                "method": w.get("method"), "handle": w.get("handle"),
                "memo": w.get("memo"), "initiated_at": w.get("initiated_at"),
                "age_days": _age(w.get("initiated_at")),
            })

        # COMPLETED — recorded payouts (recent window)
        completed = []
        for r in conn.execute(
            """SELECT id, customer, customer_id, item_name, credit_note,
                      transaction_status
               FROM items
               WHERE LOWER(COALESCE(transaction_status,'')) = 'refunded'
                  OR (LOWER(COALESCE(transaction_status,'')) = 'wd'
                      AND credit_note LIKE 'Refunded %')"""
        ).fetchall():
            r = dict(r)
            m = stamp_re.search(r.get("credit_note") or "")
            if not m:
                continue
            date = m.group(3)
            age = _age(date)
            if age is not None and age > completed_days:
                continue
            completed.append({
                "item_id": r["id"], "customer": r.get("customer"),
                "customer_id": r.get("customer_id"), "event": r.get("item_name"),
                "amount": round(_parse_dollar(m.group(1)), 2),
                "method": m.group(2).strip(), "date": date,
                "via_watch": r["id"] in verified_ids,
            })
        completed.extend(completed_removals)
        completed.sort(key=lambda x: x["date"], reverse=True)

    def _sum(rows):
        return round(sum(x["amount"] for x in rows), 2)

    # Referral fees ride along in the same console payload (Kerry
    # 2026-07-22: "I would like to add referral fee tracking") — best
    # effort so a referral-sync failure can never break the refunds view.
    referrals = None
    try:
        sync_referral_fees(db_path=db_path)
        referrals = get_referral_fees(db_path=db_path)
    except Exception:
        logger.warning("referral fee sync/read failed (non-fatal)", exc_info=True)

    return {
        "outstanding": outstanding, "in_flight": in_flight, "completed": completed,
        "referrals": referrals,
        "totals": {
            "outstanding_count": len(outstanding),
            "outstanding_amount": _sum(outstanding),
            "in_flight_count": len(in_flight),
            "in_flight_amount": _sum(in_flight),
            "completed_count": len(completed),
            "completed_amount": _sum(completed),
        },
        "completed_days": completed_days,
    }


# ── Referral fee tracking (v2.140.0, Kerry 2026-07-22) ────────────────
# The referral program's data trail: a referred signup carries a coupon
# code "tgf-referral-<referrer>" (parser extracts coupon_code/amount).
# A redeemed coupon IS the referrer's compensation (Kerry 2026-07-28),
# so the coupon scan records the referral as COMPED — no cash fee owed.
# For word-of-mouth referrals with no coupon, Kerry pays the REFERRER a
# flat fee via P2P with the memo "Referral fee for <referred person>";
# the receipt scan records those PAID (auto-completes, same philosophy
# as the refund watches). Fee amount is rules-as-data: app_setting
# 'referral_fee_amount' (default 25).

_REFERRAL_COUPON_RE = re.compile(r"^tgf-?referr?al-?(.+)$", re.I)
_REFERRAL_MEMO_RE = re.compile(r"referr?al\s+fee\s+for\s+(.+?)\s*$", re.I)


def _ensure_referral_tables(conn: sqlite3.Connection) -> None:
    conn.execute("""CREATE TABLE IF NOT EXISTS referral_fees (
        id                    INTEGER PRIMARY KEY AUTOINCREMENT,
        referrer_customer_id  INTEGER REFERENCES customers(customer_id),
        referrer_name         TEXT,
        referred_customer_id  INTEGER REFERENCES customers(customer_id),
        referred_name         TEXT COLLATE NOCASE,
        source                TEXT,      -- coupon | receipt | manual
        source_item_id        INTEGER REFERENCES items(id),
        coupon_code           TEXT,
        amount                REAL,
        status                TEXT DEFAULT 'owed',   -- owed | paid
        paid_at               TEXT,
        method                TEXT,
        acct_transaction_id   INTEGER REFERENCES acct_transactions(id),
        note                  TEXT,
        created_at            TEXT DEFAULT (datetime('now')))""")
    conn.execute("CREATE INDEX IF NOT EXISTS idx_referral_fees_status "
                 "ON referral_fees(status)")


def _referral_fee_amount(conn) -> float:
    try:
        row = conn.execute(
            "SELECT value FROM app_settings WHERE key = 'referral_fee_amount'"
        ).fetchone()
        return float(row["value"]) if row and row["value"] else 25.0
    except Exception:
        return 25.0


def _backfill_split_category_fks(conn) -> int:
    """Connect category FKs on promoted splits (v2.149.9). For every
    acct_split with a NULL category_id whose transaction was promoted from
    an expense row carrying a category name, register the name in
    acct_categories if absent and stamp the id. Idempotent — shrinks to
    zero rows once connected."""
    rows = conn.execute(
        """SELECT s.id AS sid, e.category AS cname, e.transaction_type AS ttype
           FROM acct_splits s
           JOIN acct_transactions a ON a.id = s.transaction_id
           JOIN expense_transactions e ON a.source_ref = 'exp-promoted-' || e.id
           WHERE s.category_id IS NULL
             AND e.category IS NOT NULL AND TRIM(e.category) != ''""").fetchall()
    if not rows:
        return 0
    cache: dict = {}
    fixed = 0
    for r in rows:
        cname = str(r["cname"]).strip()
        key = cname.lower()
        if key not in cache:
            c = conn.execute(
                "SELECT id FROM acct_categories WHERE LOWER(name) = LOWER(?) LIMIT 1",
                (cname,)).fetchone()
            if not c:
                conn.execute(
                    "INSERT INTO acct_categories (name, type) VALUES (?, ?)",
                    (cname, "income" if r["ttype"] == "received" else "expense"))
                c = conn.execute(
                    "SELECT id FROM acct_categories WHERE LOWER(name) = LOWER(?) LIMIT 1",
                    (cname,)).fetchone()
            cache[key] = c["id"] if c else None
        if cache[key]:
            conn.execute("UPDATE acct_splits SET category_id = ? WHERE id = ?",
                         (cache[key], r["sid"]))
            fixed += 1
    conn.commit()
    return fixed


def _repair_atkinson_folded_receipts(conn) -> int:
    """One-off heal (v2.140.3): Kerry paid Bob Atkinson (customer 219) four
    times on 2026-07-21 — $58 credit refunds for s9.15 and s9.19 THE QUARRY
    plus $25 referral fees for Hector Aguilera and David Decareaux. The
    expense re-key guard folded each same-amount pair into one row (same
    payee/amount/date reads as a Graph re-key), dropping the s9.19 $58 and
    the Decareaux $25 from the ledger. Recreate the missing receipt +
    ledger rows; the referral receipt scan then files the Decareaux fee
    from the recovered memo. raw_extract deliberately carries NO
    transaction_id so a late-arriving real receipt adopts these rows
    instead of duplicating them.
    """
    # Fresh DBs create expense tables later in init — nothing to heal there.
    if not conn.execute(
            "SELECT 1 FROM sqlite_master WHERE type='table' AND name='expense_transactions'"
    ).fetchone():
        return 0
    heals = [
        (58.0, "Bob Atkinson - Credit from s9.19 THE QUARRY",
         "%credit from s9.19 the quarry%"),
        (25.0, "Robert Atkinson - Referral fee for David Decareaux",
         "%referral fee for david decareaux%"),
    ]
    fixed = 0
    for amount, memo, needle in heals:
        have = conn.execute(
            """SELECT 1 FROM expense_transactions
               WHERE customer_id = 219 AND amount = ?
                 AND LOWER(COALESCE(notes, '')) LIKE ?""",
            (amount, needle),
        ).fetchone()
        if have:
            continue
        cur = conn.execute(
            """INSERT INTO expense_transactions
               (source_type, merchant, amount, transaction_date,
                transaction_type, entity, customer_id, confidence,
                review_status, notes, raw_extract)
               VALUES ('venmo', 'Robert Atkinson', ?, '2026-07-21',
                       'payout', 'TGF', 219, 95, 'approved', ?, ?)""",
            (amount, memo, json.dumps({
                "recipient_name": "Robert Atkinson", "amount": amount,
                "memo": memo, "sent_from_account": "@tgf-payments",
                "transaction_date": "2026-07-21",
                "transaction_type": "payout",
                "note": "recovered from folded receipt (v2.140.3 heal)",
            })),
        )
        exp = dict(conn.execute(
            "SELECT * FROM expense_transactions WHERE id = ?",
            (cur.lastrowid,)).fetchone())
        _sync_expense_ledger_entry(conn, exp)
        fixed += 1
    return fixed


def sync_referral_fees(db_path: str | Path | None = None) -> dict:
    """Idempotent two-way sync of the referral_fees table.

    1. COUPON scan: items whose coupon_code matches tgf-referral-<name>
       create a COMPED row (referrer resolved from the code token; the
       referred person is the item's customer). A redeemed referral
       coupon IS the referrer's compensation — no cash fee is owed on
       top of it (Kerry 2026-07-28: "this denotes that they already
       used a coupon that I issued them. So I don't need to be notified
       to issue another referral fee"). One row per referred person —
       the same coupon on later orders doesn't stack.
    2. RECEIPT scan: P2P payout receipts whose memo reads "Referral fee
       for <person>" mark the matching OWED row PAID (or create a paid
       row when we never saw a coupon — the word-of-mouth referral Kerry
       compensates in cash/Venmo: Atkinson/Aguilera 07-21,
       Atkinson/Decareaux 07-22). Cash fees only ever arise from that
       receipt path or manual entry now that coupon rows are comped.
    """
    out = {"coupon_comped": 0, "paid_recorded": 0, "comped_migrated": 0,
           "notes": []}
    with _connect(db_path) as conn:
        _ensure_referral_tables(conn)
        fee = _referral_fee_amount(conn)

        # 0. migrate pre-rule coupon rows still sitting as OWED — the
        #    coupon was the compensation, so no fee is pending. Runs on
        #    every sync; shrinks to zero rows once flipped.
        out["comped_migrated"] = conn.execute(
            """UPDATE referral_fees
               SET status = 'comped', method = 'coupon',
                   paid_at = COALESCE(paid_at, DATE('now')),
                   note = CASE WHEN COALESCE(note, '') = ''
                          THEN 'coupon was the compensation - no fee owed (Kerry 2026-07-28)'
                          ELSE note || '; coupon was the compensation - no fee owed (Kerry 2026-07-28)'
                          END
               WHERE source = 'coupon' AND status = 'owed'""").rowcount

        # 1. coupon scan — one row per referred person
        for it in conn.execute(
                """SELECT id, customer, customer_id, coupon_code, order_date
                   FROM items
                   WHERE coupon_code IS NOT NULL AND coupon_code != ''
                     AND transaction_status NOT IN ('rsvp_only')
                   ORDER BY order_date, id""").fetchall():
            m = _REFERRAL_COUPON_RE.match((it["coupon_code"] or "").strip())
            if not m:
                continue
            referred_name = (it["customer"] or "").strip()
            if not referred_name:
                continue
            dup = conn.execute(
                """SELECT 1 FROM referral_fees
                   WHERE referred_name = ? OR
                         (referred_customer_id IS NOT NULL
                          AND referred_customer_id = ?)""",
                (referred_name, it["customer_id"])).fetchone()
            if dup:
                continue
            token = m.group(1).strip().replace("-", " ")
            ref_cid = _lookup_customer_id(conn, token, None)
            ref_name = None
            if ref_cid:
                row = conn.execute(
                    """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                                   COALESCE(last_name,'')) AS n
                       FROM customers WHERE customer_id = ?""",
                    (ref_cid,)).fetchone()
                ref_name = row["n"] if row else None
            base_note = ("coupon was the compensation - no fee owed "
                         "(Kerry 2026-07-28)")
            conn.execute(
                """INSERT INTO referral_fees
                       (referrer_customer_id, referrer_name,
                        referred_customer_id, referred_name,
                        source, source_item_id, coupon_code, amount, status,
                        method, paid_at, note)
                   VALUES (?, ?, ?, ?, 'coupon', ?, ?, ?, 'comped',
                           'coupon', ?, ?)""",
                (ref_cid, ref_name or token.title(), it["customer_id"],
                 referred_name, it["id"], it["coupon_code"], fee,
                 it["order_date"] or None,
                 base_note if ref_cid else
                 f"referrer '{token}' not resolved to a customer; {base_note}"))
            out["coupon_comped"] += 1

        # 2. receipt scan — paid referral fees auto-complete
        for exp in conn.execute(
                """SELECT id, merchant, amount, transaction_date, customer_id,
                          notes, source_type, acct_transaction_id
                   FROM expense_transactions
                   WHERE transaction_type = 'payout'
                     AND source_type IN ('venmo','paypal','cashapp','zelle')
                     AND notes IS NOT NULL""").fetchall():
            m = _REFERRAL_MEMO_RE.search(exp["notes"] or "")
            if not m:
                continue
            referred_name = m.group(1).strip().rstrip(".")
            already = conn.execute(
                "SELECT 1 FROM referral_fees WHERE acct_transaction_id = ?",
                (exp["acct_transaction_id"],)).fetchone() \
                if exp["acct_transaction_id"] else None
            if already:
                continue
            open_row = conn.execute(
                """SELECT id FROM referral_fees
                   WHERE status = 'owed' AND referred_name = ?
                   ORDER BY id LIMIT 1""", (referred_name,)).fetchone()
            vals = (exp["transaction_date"], exp["source_type"],
                    exp["acct_transaction_id"], round(float(exp["amount"] or 0), 2))
            if open_row:
                conn.execute(
                    """UPDATE referral_fees
                       SET status = 'paid', paid_at = ?, method = ?,
                           acct_transaction_id = ?, amount = ?
                       WHERE id = ?""", (*vals, open_row["id"]))
            else:
                ref_cid = exp["customer_id"] or _lookup_customer_id(
                    conn, (exp["merchant"] or "").strip(), None)
                ref_name = (exp["merchant"] or "").strip()
                if ref_cid:
                    row = conn.execute(
                        """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                                       COALESCE(last_name,'')) AS n
                           FROM customers WHERE customer_id = ?""",
                        (ref_cid,)).fetchone()
                    if row and row["n"]:
                        ref_name = row["n"]
                referred_cid = _lookup_customer_id(conn, referred_name, None)
                conn.execute(
                    """INSERT INTO referral_fees
                           (referrer_customer_id, referrer_name,
                            referred_customer_id, referred_name,
                            source, amount, status, paid_at, method,
                            acct_transaction_id)
                       VALUES (?, ?, ?, ?, 'receipt', ?, 'paid', ?, ?, ?)""",
                    (ref_cid, ref_name, referred_cid, referred_name,
                     vals[3], vals[0], vals[1], vals[2]))
            out["paid_recorded"] += 1
        conn.commit()
    return out


def get_referral_fees(db_path: str | Path | None = None) -> dict:
    """Referral fees for the console: owed (with the referrer's Venmo
    handle for a prefilled pay link) + paid + comped (coupon-compensated
    — recorded for the referral history, no cash owed), newest first."""
    with _connect(db_path) as conn:
        _ensure_referral_tables(conn)
        rows = [dict(r) for r in conn.execute(
            """SELECT rf.*, c.venmo_username AS referrer_venmo
               FROM referral_fees rf
               LEFT JOIN customers c ON c.customer_id = rf.referrer_customer_id
               ORDER BY rf.status DESC, rf.paid_at DESC, rf.id DESC""").fetchall()]
    owed = [r for r in rows if r["status"] == "owed"]
    paid = [r for r in rows if r["status"] == "paid"]
    comped = [r for r in rows if r["status"] == "comped"]
    return {"owed": owed, "paid": paid, "comped": comped,
            "owed_total": round(sum(r["amount"] or 0 for r in owed), 2),
            "paid_total": round(sum(r["amount"] or 0 for r in paid), 2)}


def link_referral_fee_referrer(fee_id: int, customer_id: int,
                               db_path: str | Path | None = None) -> dict:
    """Set the referrer on a fee whose coupon token didn't resolve
    (e.g. 'tgf-referral-jesse' — which Jesse? Kerry says)."""
    with _connect(db_path) as conn:
        _ensure_referral_tables(conn)
        row = conn.execute(
            """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                           COALESCE(last_name,'')) AS n
               FROM customers WHERE customer_id = ?""",
            (customer_id,)).fetchone()
        if not row or not (row["n"] or "").strip():
            return {"ok": False, "error": f"customer {customer_id} not found"}
        n = conn.execute(
            """UPDATE referral_fees
               SET referrer_customer_id = ?, referrer_name = ?, note = NULL
               WHERE id = ?""",
            (customer_id, row["n"], fee_id)).rowcount
        conn.commit()
    return {"ok": n > 0, "referrer": row["n"], "customer_id": customer_id}


def mark_referral_fee_paid(fee_id: int, method: str = "Venmo",
                           paid_date: str | None = None, note: str = "",
                           db_path: str | Path | None = None) -> dict:
    """Manual completion for a referral fee paid outside the receipt flow
    (cash, or a memo the scanner can't read)."""
    with _connect(db_path) as conn:
        _ensure_referral_tables(conn)
        n = conn.execute(
            """UPDATE referral_fees
               SET status = 'paid', paid_at = COALESCE(?, DATE('now')),
                   method = ?, note = COALESCE(NULLIF(?, ''), note)
               WHERE id = ? AND status != 'paid'""",
            (paid_date, method, note, fee_id)).rowcount
        conn.commit()
    return {"ok": n > 0, "updated": n}


def auto_match_refund_watches(expense_ids: list[int] | None= None,
                              db_path: str | Path | None = None) -> dict:
    """Verify open refund watches against outbound P2P payment receipts
    and record the payout.

    Runs AFTER auto_match_venmo_payouts_to_tgf on ingest (winnings get
    first claim on a receipt) and skips any receipt already backing a
    tgf_payout. Match rule, oldest watch first, receipts ingested after
    the watch started: amount exact to the cent AND at least one of
    (same customer_id | same normalized handle | the watch memo appears
    in the receipt note). One receipt verifies exactly one watch.

    On match: payout_credit(item, method, refund_date=receipt date,
    note='Auto-verified …') — identical books to a manual Record Refund.
    If the item was already paid out manually in the meantime, the watch
    is marked verified with recorded=0 (no double recording:
    payout_credit refuses non-credited rows). Idempotent.
    """
    summary = {"verified": 0, "recorded": 0, "unmatched_watches": 0,
               "errors": 0, "matches": []}

    def norm_handle(h):
        return (h or "").lstrip("@").lstrip("$").strip().lower()

    with _connect(db_path) as conn:
        _ensure_refund_watch_table(conn)
        watches = [dict(r) for r in conn.execute(
            "SELECT * FROM refund_watches WHERE verified_at IS NULL "
            "ORDER BY initiated_at").fetchall()]
        # NO early return when there are no open watches (v2.149.22 —
        # Kerry 2026-07-28 "Refunds don't seem to be clearing"): Kerry
        # pays credits straight from the Venmo app, so watches are
        # usually EMPTY and the early return made the watchless pass
        # below unreachable — four fresh credit-refund receipts sat
        # parsed while their credits stayed OUTSTANDING.
        params: list = []
        sql = ("SELECT * FROM expense_transactions "
               "WHERE source_type IN ('venmo', 'paypal', 'cashapp', 'zelle') "
               "AND transaction_type = 'payout' "
               "AND review_status IN ('approved', 'pending', 'corrected')")
        if expense_ids:
            sql += " AND id IN (%s)" % ",".join(["?"] * len(expense_ids))
            params.extend(expense_ids)
        expenses = [dict(r) for r in conn.execute(sql, params).fetchall()]
        used = {r["verified_expense_id"] for r in conn.execute(
            "SELECT verified_expense_id FROM refund_watches "
            "WHERE verified_expense_id IS NOT NULL").fetchall()}
        # Receipts already backing a WINNINGS payout are off the table
        payout_backed = set()
        for exp in expenses:
            if exp.get("acct_transaction_id"):
                row = conn.execute(
                    "SELECT 1 FROM tgf_payouts WHERE acct_transaction_id = ? "
                    "LIMIT 1", (exp["acct_transaction_id"],)).fetchone()
                if row:
                    payout_backed.add(exp["id"])

    for w in watches:
        cand = None
        for exp in expenses:
            if exp["id"] in used or exp["id"] in payout_backed:
                continue
            try:
                amt = round(float(exp.get("amount") or 0), 2)
            except (TypeError, ValueError):
                continue
            if abs(amt - round(float(w["amount"]), 2)) > 0.009:
                continue
            if (exp.get("created_at") or "") < (w.get("initiated_at") or ""):
                continue  # receipt predates the watch — not this payment
            same_cust = bool(w.get("customer_id")) and \
                exp.get("customer_id") == w["customer_id"]
            same_handle = bool(norm_handle(w.get("handle"))) and \
                norm_handle(exp.get("other_party_handle")) == norm_handle(w.get("handle"))
            memo = (w.get("memo") or "").strip().lower()
            notes = (exp.get("notes") or "").strip().lower()
            memo_hit = bool(memo) and bool(notes) and memo in notes
            if same_cust or same_handle or memo_hit:
                cand = exp
                break
        if not cand:
            summary["unmatched_watches"] += 1
            continue
        used.add(cand["id"])
        recorded = 0
        try:
            res = payout_credit(
                w["item_id"], method=w["method"],
                note=(f"Auto-verified via {w['method']} receipt "
                      f"(expense #{cand['id']})"),
                refund_date=(cand.get("transaction_date") or "")[:10],
                db_path=db_path,
            )
            recorded = 1 if res.get("ok") else 0
            if not recorded:
                logger.info("Refund watch %s verified but not recorded: %s",
                            w["id"], res.get("error"))
        except Exception:
            logger.exception("Refund watch %s: recording failed", w["id"])
            summary["errors"] += 1
        with _connect(db_path) as conn:
            conn.execute(
                "UPDATE refund_watches SET verified_at = datetime('now'), "
                "verified_expense_id = ?, recorded = ? WHERE id = ?",
                (cand["id"], recorded, w["id"]))
            conn.commit()
        summary["verified"] += 1
        summary["recorded"] += recorded
        summary["matches"].append({
            "watch_id": w["id"], "item_id": w["item_id"],
            "expense_id": cand["id"], "amount": w["amount"],
            "customer": w.get("customer_name"),
        })

    # ── Watchless pass (Kerry 2026-07-20, the Jeff Rideout case) ──
    # Kerry often pays a credit refund straight from the Venmo app with
    # no in-app Refund tap, so no watch exists and the credited item sat
    # OUTSTANDING forever (his receipt even arrived under the alias
    # 'Paul Rideout' — but the memo resolved customer_id). A payout
    # receipt whose memo reads like a credit refund and that matches
    # exactly ONE open credited/wd item by customer_id + exact amount
    # completes that item the same way a verified watch would.
    summary["watchless_recorded"] = 0
    try:
        with _connect(db_path) as conn:
            open_credits = [dict(r) for r in conn.execute(
                "SELECT id, customer_id, item_name, item_price, "
                "credit_amount, transaction_status, created_at FROM items "
                "WHERE LOWER(COALESCE(transaction_status,'')) "
                "IN ('credited','wd')").fetchall()]
        for exp in expenses:
            if exp["id"] in used or exp["id"] in payout_backed:
                continue
            notes = (exp.get("notes") or "").lower()
            if not any(k in notes for k in ("credit", "refund")):
                continue
            if not exp.get("customer_id"):
                continue
            try:
                amt = round(float(exp.get("amount") or 0), 2)
            except (TypeError, ValueError):
                continue
            cands = []
            with _connect(db_path) as _vc:
                for it in open_credits:
                    if it["customer_id"] != exp["customer_id"]:
                        continue
                    val = _item_credit_value(_vc, it)
                    if abs(val - amt) <= 0.009 and \
                            (exp.get("created_at") or "") >= (it.get("created_at") or ""):
                        cands.append(it)
            if len(cands) != 1:
                continue
            it = cands[0]
            try:
                res = payout_credit(
                    it["id"], method="Venmo",
                    note=(f"Auto-verified via Venmo receipt "
                          f"(expense #{exp['id']}, no watch)"),
                    refund_date=(exp.get("transaction_date") or "")[:10],
                    db_path=db_path)
                if res.get("ok"):
                    used.add(exp["id"])
                    open_credits.remove(it)
                    summary["watchless_recorded"] += 1
            except Exception:
                logger.exception("watchless refund complete failed for "
                                 "item %s / expense %s", it["id"], exp["id"])
    except Exception:
        # This append used to live HERE with watch-loop variables (w/cand)
        # that don't exist on this path — a latent NameError inside the
        # error handler. It now lives in the watch loop where it belongs.
        logger.exception("watchless refund pass failed")
    return summary


def _ensure_tgf_overpayments(conn) -> None:
    """Overpaid winnings ledger (v2.141.0, Kerry — the Hogue a9.19 case:
    Robert awarded Jay both CTPs, Kerry paid $98.50, GG then re-awarded one
    CTP to Paul Reed → $17 owed BACK). One row per receipt that exceeds the
    recorded group after a results correction; the console offers a Venmo
    REQUEST for the difference and the inbound receipt scan closes the loop."""
    conn.execute(
        """CREATE TABLE IF NOT EXISTS tgf_overpayments (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            customer_id INTEGER REFERENCES customers(customer_id),
            event_id INTEGER,
            acct_transaction_id INTEGER,
            expense_id INTEGER,
            amount REAL NOT NULL,
            status TEXT NOT NULL DEFAULT 'open',
            note TEXT,
            created_at TEXT DEFAULT (datetime('now')),
            resolved_at TEXT,
            method TEXT,
            recovered_acct_id INTEGER
        )"""
    )


# The REQUEST button writes this memo on the Venmo charge; when the player
# pays it, the incoming receipt carries the same text and the recovery scan
# extracts the event code from it.
_OVERPAY_MEMO_RE = re.compile(
    r"overpaid\s+winnings\s+for\s+([a-z]+\d+(?:\.\s*\d+)?)", re.I)


def recover_tgf_overpayments(expense_ids: list[int] | None = None,
                             db_path: str | Path | None = None) -> dict:
    """Close open tgf_overpayments from INBOUND P2P receipts.

    A 'received' expense whose memo reads "Overpaid winnings for <code> …"
    is a player returning money the app requested. Match on the payer's
    customer + the memo's event + the exact overpayment amount (±$0.01),
    mark the overpayment recovered, and promote the receipt to the ledger
    as income so the books show the money coming back.
    """
    out = {"recovered": 0, "no_match": 0, "errors": 0}
    with _connect(db_path) as conn:
        _ensure_tgf_overpayments(conn)
        params: list = []
        sql = ("SELECT * FROM expense_transactions "
               "WHERE source_type IN ('venmo', 'paypal', 'cashapp', 'zelle') "
               "AND transaction_type = 'received' AND notes IS NOT NULL")
        if expense_ids:
            sql += " AND id IN (%s)" % ",".join(["?"] * len(expense_ids))
            params.extend(expense_ids)
        for exp in [dict(r) for r in conn.execute(sql, params).fetchall()]:
            try:
                m = _OVERPAY_MEMO_RE.search(exp.get("notes") or "")
                if not m:
                    continue
                already = conn.execute(
                    "SELECT 1 FROM tgf_overpayments WHERE recovered_acct_id = ? "
                    "OR (expense_id IS NOT NULL AND status = 'recovered' AND note LIKE ?)",
                    (exp.get("acct_transaction_id") or -1,
                     f"%recovered-exp-{exp['id']}%")).fetchone()
                if already:
                    continue
                cid = exp.get("customer_id") or _lookup_customer_id(
                    conn, (exp.get("merchant") or "").strip(), None)
                code = m.group(1).replace(" ", "")
                amt = round(float(exp.get("amount") or 0), 2)
                cand = conn.execute(
                    """SELECT o.* FROM tgf_overpayments o
                       JOIN tgf_events e ON e.id = o.event_id
                       WHERE o.status = 'open'
                         AND (? IS NULL OR o.customer_id = ?)
                         AND LOWER(e.code) LIKE LOWER(?)
                         AND ABS(o.amount - ?) <= 0.01""",
                    (cid, cid, code + "%", amt)).fetchall()
                if len(cand) != 1:
                    out["no_match"] += 1
                    continue
                acct_id = exp.get("acct_transaction_id")
                if not acct_id:
                    acct_id = _sync_expense_ledger_entry(conn, exp)
                    if acct_id:
                        conn.execute(
                            """UPDATE expense_transactions
                               SET acct_transaction_id = ?,
                                   review_status = CASE WHEN review_status = 'pending'
                                                        THEN 'approved' ELSE review_status END
                               WHERE id = ?""", (acct_id, exp["id"]))
                paid_date = str(exp.get("transaction_date") or "")
                if not re.match(r"^\d{4}-\d{2}-\d{2}", paid_date):
                    paid_date = today_central_str()
                conn.execute(
                    """UPDATE tgf_overpayments
                       SET status = 'recovered', resolved_at = ?, method = ?,
                           recovered_acct_id = ?,
                           note = COALESCE(note || ' · ', '') || ?
                       WHERE id = ?""",
                    (paid_date, exp.get("source_type"), acct_id,
                     f"recovered-exp-{exp['id']}", cand[0]["id"]))
                out["recovered"] += 1
                logger.info("overpayment %s recovered: %s $%.2f (exp %s)",
                            cand[0]["id"], exp.get("merchant"), amt, exp["id"])
            except Exception:
                logger.exception("overpayment recovery failed for exp %s", exp.get("id"))
                out["errors"] += 1
        conn.commit()
    return out


def resolve_tgf_overpayment(overpay_id: int, status: str = "recovered",
                            method: str | None = None, date: str | None = None,
                            note: str | None = None,
                            db_path: str | Path | None = None) -> dict:
    """Manually close an overpayment (cash handed back, or Kerry waives it)."""
    if status not in ("recovered", "waived", "open"):
        raise ValueError("status must be recovered, waived, or open")
    with _connect(db_path) as conn:
        _ensure_tgf_overpayments(conn)
        row = conn.execute("SELECT * FROM tgf_overpayments WHERE id = ?",
                           (overpay_id,)).fetchone()
        if not row:
            return {"error": f"overpayment {overpay_id} not found"}
        conn.execute(
            """UPDATE tgf_overpayments
               SET status = ?, method = COALESCE(?, method),
                   resolved_at = CASE WHEN ? = 'open' THEN NULL
                                      ELSE COALESCE(?, resolved_at, date('now')) END,
                   note = CASE WHEN ? IS NULL THEN note
                               ELSE COALESCE(note || ' · ', '') || ? END
               WHERE id = ?""",
            (status, method, status, date, note, note, overpay_id))
        conn.commit()
        return dict(conn.execute("SELECT * FROM tgf_overpayments WHERE id = ?",
                                 (overpay_id,)).fetchone())


def get_tgf_overpayments(db_path: str | Path | None = None) -> list[dict]:
    """Open + recently resolved overpayments with player/event context."""
    with _connect(db_path) as conn:
        _ensure_tgf_overpayments(conn)
        return [dict(r) for r in conn.execute(
            """SELECT o.*, e.code AS event_code, e.name AS event_name,
                      e.event_date,
                      TRIM(c.first_name || ' ' || c.last_name) AS customer_name,
                      c.venmo_username
               FROM tgf_overpayments o
               LEFT JOIN tgf_events e ON e.id = o.event_id
               LEFT JOIN customers c ON c.customer_id = o.customer_id
               WHERE o.status = 'open'
                  OR COALESCE(o.resolved_at, '') >= date('now', '-30 days')
               ORDER BY (o.status = 'open') DESC, o.created_at DESC""").fetchall()]


def auto_match_venmo_payouts_to_tgf(
    expense_ids: list[int] | None = None,
    db_path: str | Path | None = None,
) -> dict:
    """Match OUTBOUND Venmo payment receipts to pending tgf_payouts and
    mark them PAID (Kerry, 2026-07-08: "use the Venmo transaction emails
    to confirm and mark paid the transactions I send with these links").

    The expense inbox already ingests Venmo "you paid" emails as
    expense_transactions rows with transaction_type='payout' — recipient
    in merchant, memo in notes ("Winnings for s9.16 …"), customer_id and
    event_id resolved when possible. For each such row, find the pending
    payout group (source='pending' placeholder or unlinked) for that
    customer+event whose sum matches the payment; link the group to the
    expense's promoted ledger entry (source='venmo' → PAID on the
    PAYOUTS tab), reverse the placeholders, stamp paid_at.

    Resolution order per expense:
      1. customer: expense.customer_id → venmo handle → name/alias cascade
      2. tgf event: expense.event_id (events.id) via tgf_events.events_id
         or tgf_events.code == events.item_name; else the memo's event
         code ("Winnings for s9.16 …" → tgf_events.code LIKE 's9.16%');
         else unique-by-amount across the customer's pending groups
      3. amount: exact to the cent first, then ±$1.00 only when unique

    Idempotent: an expense whose ledger entry already backs payout rows
    counts as already_matched. Returns
    {matched, ambiguous, no_candidate, already_matched, errors, matches}.
    """
    summary = {"matched": 0, "ambiguous": 0, "no_candidate": 0,
               "already_matched": 0, "errors": 0, "matches": []}
    with _connect(db_path) as conn:
        params: list = []
        # All peer-to-peer providers ride the same matcher — recipient in
        # merchant, memo in notes ("<Name> - Winnings for s9.16 …"),
        # customer/event resolved on ingest. PayPal + Cash App carry the
        # note the same as Venmo (v2.84.0, Kerry).
        sql = ("SELECT * FROM expense_transactions "
               "WHERE source_type IN ('venmo', 'paypal', 'cashapp', 'zelle') "
               "AND transaction_type = 'payout' "
               "AND review_status IN ('approved', 'pending', 'corrected')")
        if expense_ids:
            sql += " AND id IN (%s)" % ",".join(["?"] * len(expense_ids))
            params.extend(expense_ids)
        expenses = [dict(r) for r in conn.execute(sql, params).fetchall()]

        for exp in expenses:
            try:
                amt = round(float(exp.get("amount") or 0), 2)
                if amt <= 0:
                    summary["no_candidate"] += 1
                    continue
                if exp.get("acct_transaction_id"):
                    linked = conn.execute(
                        "SELECT 1 FROM tgf_payouts WHERE acct_transaction_id = ? LIMIT 1",
                        (exp["acct_transaction_id"],)).fetchone()
                    if linked:
                        summary["already_matched"] += 1
                        continue

                # 1. recipient customer
                cid = exp.get("customer_id")
                if not cid:
                    handle = (exp.get("other_party_handle") or "").lstrip("@").lower()
                    if handle:
                        row = conn.execute(
                            """SELECT customer_id FROM customers
                               WHERE LOWER(REPLACE(COALESCE(venmo_username,''), '@', '')) = ?
                               LIMIT 1""", (handle,)).fetchone()
                        cid = row["customer_id"] if row else None
                if not cid:
                    cid = _lookup_customer_id(conn, (exp.get("merchant") or "").strip(), None)
                # The Venmo RECIPIENT name is the account's display name,
                # which often isn't the player's real name (Kerry,
                # 2026-07-13: Matt Griffin's Venmo shows "robert griffin",
                # so his $38.25 s9.17 payout never matched). Two fallbacks
                # keyed off the MEMO, which the app writes from the payout
                # row itself:
                #  (a) memo payee name — "Matt Griffin - Winnings for …"
                #      (present going forward now the parser keeps it verbatim)
                #  (b) memo EVENT + the payment's EXACT amount: if exactly
                #      one PENDING payout in that event owes this exact
                #      amount, it is unambiguously the payee.
                memo_txt = exp.get("notes") or ""
                if not cid:
                    # Optional leading "For " — Cash App note format.
                    pm = re.match(r"\s*(?:for\s+)?(.+?)\s+-\s+winnings\s+for\b", memo_txt, re.I)
                    if pm:
                        cid = _lookup_customer_id(conn, pm.group(1).strip(), None)
                if not cid:
                    em = re.search(r"winnings\s+for\s+([a-z]+\d+(?:\.\s*\d+)?)",
                                   memo_txt, re.I)
                    erow = None
                    if em:
                        ecode = em.group(1).replace(" ", "")
                        erow = conn.execute(
                            "SELECT id FROM tgf_events WHERE LOWER(code) LIKE LOWER(?) LIMIT 1",
                            (ecode + "%",)).fetchone()
                    if not erow:
                        # Full-name events (championships, season contests)
                        # carry no [sa]N.N code — match the memo's event
                        # verbatim against tgf_events.code, dropping any
                        # " — 1st place" detail tail. This is what rescues a
                        # receipt whose Venmo display name is unknown AND
                        # whose memo payee prefix got dropped in extraction
                        # (Chuck Fehlis / "Charles Fehlis", 2026-08-02).
                        fm = re.search(
                            r"winnings\s+for\s+(.+?)(?:\s+[—–-]\s+.*)?$",
                            memo_txt, re.I)
                        if fm and fm.group(1).strip():
                            erow = conn.execute(
                                "SELECT id FROM tgf_events "
                                "WHERE LOWER(code) = LOWER(?) LIMIT 1",
                                (fm.group(1).strip(),)).fetchone()
                    if erow:
                        uniq = conn.execute(
                            """SELECT p.customer_id AS cid,
                                      ROUND(SUM(p.amount), 2) AS total
                               FROM tgf_payouts p
                               LEFT JOIN acct_transactions t
                                      ON t.id = p.acct_transaction_id
                               WHERE p.event_id = ?
                                 AND (p.acct_transaction_id IS NULL
                                      OR (t.source = 'pending'
                                          AND COALESCE(t.status,'active')='active'))
                               GROUP BY p.customer_id
                               HAVING ABS(total - ?) <= 0.01""",
                            (erow["id"], amt)).fetchall()
                        if len(uniq) == 1:
                            cid = uniq[0]["cid"]
                if not cid:
                    summary["no_candidate"] += 1
                    continue

                # 2. this customer's pending payout groups (one per tgf event)
                groups = [dict(g) for g in conn.execute(
                    """SELECT p.event_id AS tgf_event_id,
                              ROUND(SUM(p.amount), 2) AS total
                       FROM tgf_payouts p
                       JOIN tgf_events e ON e.id = p.event_id
                       LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
                       WHERE p.customer_id = ?
                         AND (p.acct_transaction_id IS NULL
                              OR (t.source = 'pending'
                                  AND COALESCE(t.status, 'active') = 'active'))
                         -- Causality guard (v2.139.2, the Reed case): a
                         -- payment can never cover winnings for an event
                         -- played AFTER it. An unconsumed April receipt
                         -- exact-cents-matched a July group ($64.50 both)
                         -- and stamped it paid months before it existed.
                         -- +1 day slack for date fuzz; date-less pseudo
                         -- accounts (monthly points) stay eligible.
                         AND (e.event_date IS NULL
                              OR e.event_date <= DATE(?, '+1 day'))
                       GROUP BY p.event_id""",
                    (cid, exp.get("transaction_date")
                     or exp.get("created_at") or "9999-12-31")).fetchall()]
                if not groups:
                    summary["no_candidate"] += 1
                    continue

                tgf_event_id = None
                memo_resolved = False
                # Monthly-points memos resolve ONLY to the month's own
                # account (v2.51.0). Never to a golf event: a $70.00 MARCH
                # Points payment once ±$1-matched a $70.37 event group.
                mm = _MONTHLY_MEMO_RE.search(exp.get("notes") or "")
                if mm:
                    row = conn.execute(
                        """SELECT id FROM tgf_events WHERE LOWER(code) LIKE LOWER(?)
                           ORDER BY event_date DESC LIMIT 1""",
                        (mm.group(1) + " points%",)).fetchone()
                    if not row:
                        summary["no_candidate"] += 1
                        continue
                    tgf_event_id = row["id"]
                    memo_resolved = True
                if tgf_event_id is None:
                    # The MEMO is what Kerry typed — it outranks the expense
                    # pipeline's event guess, which is routinely wrong
                    # (v2.52.1 audit: 'Winnings for s9.16 …' receipts tagged
                    # event s9.12, so exact-amount matches were missed).
                    # Tolerate a space after the dot ('s9. 10' → s9.10).
                    m = re.search(r"winnings\s+for\s+([a-z]+\d+(?:\.\s*\d+)?)",
                                  exp.get("notes") or "", re.I)
                    if m:
                        code = m.group(1).replace(" ", "")
                        row = conn.execute(
                            "SELECT id FROM tgf_events WHERE LOWER(code) LIKE LOWER(?) LIMIT 1",
                            (code + "%",)).fetchone()
                        if row:
                            tgf_event_id = row["id"]
                            memo_resolved = True
                if tgf_event_id is None and exp.get("event_id"):
                    row = conn.execute(
                        """SELECT te.id FROM tgf_events te
                           LEFT JOIN events ev ON ev.id = ?
                           WHERE te.events_id = ?
                              OR (ev.item_name IS NOT NULL
                                  AND LOWER(te.code) = LOWER(ev.item_name))
                           LIMIT 1""",
                        (exp["event_id"], exp["event_id"])).fetchone()
                    tgf_event_id = row["id"] if row else None

                cands = [g for g in groups
                         if tgf_event_id is None or g["tgf_event_id"] == tgf_event_id]
                if not cands and memo_resolved:
                    # The memo names an event where this customer has NO
                    # pending group — usually a same-day cross-chapter memo
                    # typo (Austin players paid with the 's9.8 SILVERHORN'
                    # memo on a9.8 day, v2.52.2). Fall back to EXACT-cents
                    # unique across all their pending groups — the same
                    # evidence tier a memo-less receipt gets.
                    cands = groups
                    memo_resolved = False
                    tgf_event_id = None
                exact = [g for g in cands if abs(g["total"] - amt) <= 0.01]
                pick = None
                if len(exact) == 1:
                    pick = exact[0]
                elif len(exact) > 1:
                    summary["ambiguous"] += 1
                    continue
                else:
                    # Tolerance scales with evidence (v2.52.1): the memo
                    # naming the event + the right customer is strong —
                    # Kerry often paid GG's printed amounts, which differ
                    # from our computed cents by a few dollars ($37 vs
                    # $39 class). Event from the pipeline guess only: ±$1.
                    # No event at all: exact match only (v2.50.1).
                    tol = 3.00 if memo_resolved else (1.00 if tgf_event_id is not None else 0)
                    close = ([g for g in cands if abs(g["total"] - amt) <= tol]
                             if tol else [])
                    if len(close) == 1:
                        pick = close[0]
                    elif len(close) > 1:
                        summary["ambiguous"] += 1
                        continue
                # PARTIAL/SUBSET pass (Kerry 2026-07-20, the Barna a9.18
                # case): a re-record can grow a group AFTER its receipt was
                # sent ($146.83 paid, then a $26 TGF MVP row added → group
                # totals $172.83 and nothing matches). When no group total
                # matches, look for a SUBSET of one candidate group's unpaid
                # rows summing exactly to the receipt — mark just those rows
                # paid, leaving the remainder due (the UI then offers a Pay
                # button for the difference).
                partial_rows = None
                # STRONG-EVIDENCE GATE (v2.129.2): subset matching only when
                # the MEMO names this exact event — without it, an old
                # receipt whose amount happens to equal one row of ANY
                # pending group false-positives (an April $32 receipt
                # subset-matched a July s18.8 row on the first live run).
                if pick is None and memo_resolved and tgf_event_id is not None:
                    from itertools import combinations
                    for g in [c for c in cands
                              if c["tgf_event_id"] == tgf_event_id][:1]:
                        rws = conn.execute(
                            """SELECT p.id, p.amount, p.acct_transaction_id,
                                      t.source AS txn_source
                               FROM tgf_payouts p
                               LEFT JOIN acct_transactions t
                                      ON t.id = p.acct_transaction_id
                               WHERE p.customer_id = ? AND p.event_id = ?
                                 AND (p.acct_transaction_id IS NULL
                                      OR (t.source = 'pending'
                                          AND COALESCE(t.status,'active') = 'active'))
                               ORDER BY p.id""",
                            (cid, g["tgf_event_id"])).fetchall()
                        if not (2 <= len(rws) <= 16):
                            continue
                        cents = [round(float(r["amount"]) * 100) for r in rws]
                        target = round(amt * 100)
                        found = None
                        for k in range(len(rws) - 1, 0, -1):
                            for combo in combinations(range(len(rws)), k):
                                if sum(cents[i] for i in combo) == target:
                                    found = combo
                                    break
                            if found:
                                break
                        if found:
                            pick = g
                            partial_rows = [rws[i] for i in found]
                            break
                # OVERPAY pass (Kerry 2026-07-22, the Hogue a9.19 case): a
                # results correction can SHRINK a group after its receipt
                # was sent — Robert awarded Jay both CTPs, Kerry paid
                # $98.50, GG re-awarded one CTP to Paul Reed → recorded due
                # is now $81.50. Same strong-evidence gate as the subset
                # pass (memo must name this exact event): link the whole
                # group PAID and record the overage in tgf_overpayments so
                # the console can REQUEST the difference back.
                overpay_delta = None
                if pick is None and memo_resolved and tgf_event_id is not None:
                    evg = [c for c in cands if c["tgf_event_id"] == tgf_event_id]
                    if evg and evg[0]["total"] > 0 and amt > evg[0]["total"] + 0.01:
                        pick = evg[0]
                        overpay_delta = round(amt - evg[0]["total"], 2)
                if pick is None:
                    summary["no_candidate"] += 1
                    continue

                # 3. make sure the payment itself is in the ledger, then link
                acct_id = exp.get("acct_transaction_id")
                if not acct_id:
                    acct_id = _sync_expense_ledger_entry(conn, exp)
                    if not acct_id:
                        summary["errors"] += 1
                        continue
                    conn.execute(
                        """UPDATE expense_transactions
                           SET acct_transaction_id = ?,
                               review_status = CASE WHEN review_status = 'pending'
                                                    THEN 'approved' ELSE review_status END
                           WHERE id = ?""", (acct_id, exp["id"]))

                paid_date = str(exp.get("transaction_date") or "")
                if not re.match(r"^\d{4}-\d{2}-\d{2}", paid_date):
                    paid_date = today_central_str()

                rows = partial_rows if partial_rows is not None else conn.execute(
                    """SELECT p.id, p.acct_transaction_id, t.source AS txn_source
                       FROM tgf_payouts p
                       LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
                       WHERE p.customer_id = ? AND p.event_id = ?
                         AND (p.acct_transaction_id IS NULL
                              OR (t.source = 'pending'
                                  AND COALESCE(t.status, 'active') = 'active'))""",
                    (cid, pick["tgf_event_id"])).fetchall()
                for r in rows:
                    if r["acct_transaction_id"] and r["txn_source"] == "pending":
                        conn.execute(
                            "UPDATE acct_transactions SET status = 'reversed' WHERE id = ?",
                            (r["acct_transaction_id"],))
                    conn.execute(
                        "UPDATE tgf_payouts SET acct_transaction_id = ?, paid_at = ? WHERE id = ?",
                        (acct_id, paid_date, r["id"]))
                if overpay_delta:
                    _ensure_tgf_overpayments(conn)
                    dup = conn.execute(
                        "SELECT 1 FROM tgf_overpayments WHERE expense_id = ?",
                        (exp["id"],)).fetchone()
                    if not dup:
                        conn.execute(
                            """INSERT INTO tgf_overpayments
                               (customer_id, event_id, acct_transaction_id,
                                expense_id, amount, note)
                               VALUES (?, ?, ?, ?, ?, ?)""",
                            (cid, pick["tgf_event_id"], acct_id, exp["id"],
                             overpay_delta,
                             f"receipt ${amt:.2f} vs recorded ${pick['total']:.2f}"))
                        logger.info(
                            "overpayment recorded: %s $%.2f over on tgf_event %s (exp %s)",
                            exp.get("merchant"), overpay_delta,
                            pick["tgf_event_id"], exp["id"])
                summary["matched"] += 1
                summary["matches"].append({
                    "expense_id": exp["id"], "customer_id": cid,
                    "recipient": exp.get("merchant"),
                    "tgf_event_id": pick["tgf_event_id"], "amount": amt,
                    "payout_rows": len(rows), "acct_transaction_id": acct_id,
                    "partial": partial_rows is not None,
                    "overpaid": overpay_delta,
                })
                logger.info("venmo payout matched: exp %s %s $%.2f -> tgf_event %s (%d rows)",
                            exp["id"], exp.get("merchant"), amt,
                            pick["tgf_event_id"], len(rows))
            except Exception:
                logger.exception("venmo payout auto-match failed for exp %s", exp.get("id"))
                summary["errors"] += 1
        conn.commit()
    return summary


def _memo_match_names(conn, customer: str | None, customer_id) -> set[str]:
    """Full-name strings (canonical + name aliases) for a customer, lowercased.

    Only names with a space and >=5 chars are returned — a single token like
    "Richard" is too collision-prone to key a memo match on. Used by the
    inbound balance-due memo fallback: our prefilled Venmo memo carries the
    PLAYER's full name ("Richard Palacios - Balance due for ..."), so a
    spouse's payment can be tied back to the player even when the payer's
    handle/name doesn't resolve.
    """
    names: set[str] = set()

    def _add(n):
        n = (n or "").strip().lower()
        if n and " " in n and len(n) >= 5:
            names.add(n)

    _add(customer)
    if customer_id:
        row = conn.execute(
            "SELECT first_name, last_name FROM customers WHERE customer_id = ?",
            (customer_id,),
        ).fetchone()
        if row:
            _add(f"{row['first_name'] or ''} {row['last_name'] or ''}")
        try:
            for a in conn.execute(
                "SELECT alias_value FROM customer_aliases "
                "WHERE customer_id = ? AND alias_type = 'name'",
                (customer_id,),
            ).fetchall():
                _add(a["alias_value"])
        except sqlite3.OperationalError:
            pass  # customer_aliases may lack customer_id on very old DBs
    return names


def _memo_names_hit(conn, customer, customer_id, memo_lower: str) -> bool:
    """True if any of the customer's full names appears in the memo text."""
    if not memo_lower:
        return False
    return any(nm in memo_lower for nm in _memo_match_names(conn, customer, customer_id))


def auto_match_venmo_inbound_to_balance_due(
    expense_ids: list[int] | None = None,
    db_path: str | Path | None = None,
) -> dict:
    """Match incoming Venmo payments to open credit-transfer balance-due items.

    For each approved Venmo IN expense_transaction (optionally limited to
    `expense_ids`), find the unique active credit-transfer item that:
      - belongs to the paying customer, resolved handle-first (v2.16.12):
        other_party_handle → customers.venmo_username is authoritative and,
        when it resolves, is trusted exclusively; display-name matching
        (exact, then customer_aliases) runs only when there is no handle or
        the handle is unknown
      - has a credit_note starting with 'balance_due:'
      - has a balance amount within ±$1.00 of the expense amount

    On a unique match: create a +PAY child item via add_payment_to_event,
    flip the parent's credit_note from 'balance_due:X.XX' to
    'paid_at:YYYY-MM-DD', and stamp expense_transactions.matched_item_id.

    Returns {matched, ambiguous, no_candidate, already_matched, errors}.
    """
    import time as _time
    summary = {
        "matched": 0,
        "ambiguous": 0,
        "no_candidate": 0,
        "already_matched": 0,
        "errors": 0,
        "matches": [],
    }
    with _connect(db_path) as conn:
        # Pull approved or pending Venmo IN expenses, optionally filtered to specific IDs
        # pending Venmo INs are auto-approved when they match a balance-due item.
        # Both 'received' and 'income' are inbound — the LLM parser splits them
        # inconsistently, so we accept either.
        params: list = ["venmo"]
        sql = (
            "SELECT * FROM expense_transactions "
            "WHERE source_type = ? AND transaction_type IN ('received', 'income') "
            "AND review_status IN ('approved', 'pending') "
            "AND COALESCE(matched_item_id, 0) = 0"
        )
        if expense_ids:
            placeholders = ",".join(["?"] * len(expense_ids))
            sql += f" AND id IN ({placeholders})"
            params.extend(expense_ids)
        expenses = [dict(r) for r in conn.execute(sql, params).fetchall()]

        for exp in expenses:
            try:
                exp_amount = float(exp.get("amount") or 0)
                if exp_amount <= 0:
                    summary["no_candidate"] += 1
                    continue
                payer_name = (exp.get("merchant") or "").strip()
                if not payer_name:
                    summary["no_candidate"] += 1
                    continue

                # Find candidate active credit-transfer items for this payer.
                #
                # ORDER MATTERS (v2.16.12): the Venmo @handle is the
                # authoritative key — customers.venmo_username maps a handle to
                # exactly ONE customer — while the display name is free text
                # the payer controls, and it can collide with a different
                # customer's registered name (same-surname family members do
                # this routinely). The old order matched by display name FIRST
                # and only consulted the handle when the name found nothing, so
                # a son paying from an account displaying his father's name
                # could clear the FATHER's balance due whenever the amounts
                # fell within the ±$1 tolerance. Now: resolve the handle first;
                # when it identifies a customer, trust it EXCLUSIVELY (a known
                # payer with no open balance due must not borrow a same-named
                # customer's balance — that lands in no_candidate for manual
                # review instead). Display-name matching only runs when the
                # expense has no handle or the handle isn't on any customer.
                _BALANCE_DUE_SQL = """SELECT id, customer, item_name, credit_note, item_price
                           FROM items
                           WHERE merchant = 'Paid Separately (Credit Transfer)'
                             AND COALESCE(transaction_status, 'active') = 'active'
                             AND credit_note LIKE 'balance_due:%'
                             AND customer = ? COLLATE NOCASE"""
                candidates: list[dict] = []
                handle_resolved = False
                raw_handle = (exp.get("other_party_handle") or "").lstrip("@").lower()
                if raw_handle:
                    handle_row = conn.execute(
                        """SELECT c.customer_id,
                                  TRIM(COALESCE(NULLIF(c.company_name,''),
                                       NULLIF(TRIM(COALESCE(c.first_name,'') || ' '
                                              || COALESCE(c.last_name,'')), ''))) AS canonical_name
                           FROM customers c
                           WHERE REPLACE(LOWER(COALESCE(c.venmo_username,'')), '@', '') = ?
                           LIMIT 1""",
                        (raw_handle,),
                    ).fetchone()
                    if handle_row:
                        handle_resolved = True
                        logger.info(
                            "venmo match: handle %s → customer_id %s (%s)",
                            raw_handle, handle_row["customer_id"], handle_row["canonical_name"],
                        )
                        # customer_id first (reliable); canonical-name fallback
                        # covers balance_due items with a NULL customer_id.
                        candidates = [
                            dict(r) for r in conn.execute(
                                """SELECT id, customer, item_name, credit_note, item_price
                                   FROM items
                                   WHERE merchant = 'Paid Separately (Credit Transfer)'
                                     AND COALESCE(transaction_status, 'active') = 'active'
                                     AND credit_note LIKE 'balance_due:%'
                                     AND customer_id = ?""",
                                (handle_row["customer_id"],),
                            ).fetchall()
                        ]
                        if not candidates and handle_row["canonical_name"]:
                            candidates = [
                                dict(r) for r in conn.execute(
                                    _BALANCE_DUE_SQL, (handle_row["canonical_name"],)
                                ).fetchall()
                            ]
                    else:
                        logger.info(
                            "venmo match: handle '%s' (exp %s payer '%s') not found in "
                            "customers.venmo_username — falling back to display-name match",
                            raw_handle, exp.get("id"), payer_name,
                        )
                if not handle_resolved:
                    # Display-name match: exact name first, then customer_aliases
                    # so names like "Robert Callaway" match items stored as
                    # "Rob Callaway".
                    candidates = [
                        dict(r) for r in conn.execute(_BALANCE_DUE_SQL, (payer_name,)).fetchall()
                    ]
                    if not candidates:
                        alias_row = conn.execute(
                            """SELECT customer_name AS canonical
                               FROM customer_aliases
                               WHERE alias_value = ? COLLATE NOCASE
                                 AND alias_type = 'name'
                               LIMIT 1""",
                            (payer_name,),
                        ).fetchone()
                        if alias_row:
                            candidates = [
                                dict(r) for r in conn.execute(
                                    _BALANCE_DUE_SQL, (alias_row["canonical"],)
                                ).fetchall()
                            ]
                if not candidates:
                    logger.info(
                        "venmo no-candidate: exp %s payer='%s' handle=%r handle_resolved=%s",
                        exp.get("id"), payer_name, exp.get("other_party_handle"), handle_resolved,
                    )
                # Filter by amount tolerance (±$1.00)
                matched: list[dict] = []
                for c in candidates:
                    cnote = c.get("credit_note") or ""
                    try:
                        owed = float(cnote.split(":", 1)[1])
                    except (ValueError, IndexError):
                        continue
                    if abs(owed - exp_amount) <= 1.00:
                        c["_owed"] = owed
                        matched.append(c)

                matched_via_memo = False
                if not matched:
                    # Memo fallback (spouse-pays-for-player): the payer's identity
                    # didn't resolve — no handle on file, display name isn't the
                    # player, no alias. But the balance-due LINK we emailed the
                    # player prefills the memo with the PLAYER's name ("Richard
                    # Palacios - Balance due for s18.8 Vaaler Creek"), so when the
                    # wife taps it from her own Venmo the memo still names Richard.
                    # Find the UNIQUE open balance-due whose amount matches AND
                    # whose player's full name (or alias) appears in the receipt
                    # note. Amount + a named open balance make a misfire nearly
                    # impossible; anything ambiguous stays manual.
                    memo_text = (exp.get("notes") or "").lower()
                    if memo_text:
                        near = [dict(r) for r in conn.execute(
                            """SELECT id, customer, customer_id, item_name,
                                      credit_note, item_price
                               FROM items
                               WHERE merchant = 'Paid Separately (Credit Transfer)'
                                 AND COALESCE(transaction_status, 'active') = 'active'
                                 AND credit_note LIKE 'balance_due:%'"""
                        ).fetchall()]
                        memo_hits = []
                        for c in near:
                            cnote = c.get("credit_note") or ""
                            try:
                                owed = float(cnote.split(":", 1)[1])
                            except (ValueError, IndexError):
                                continue
                            if abs(owed - exp_amount) > 1.00:
                                continue
                            if _memo_names_hit(conn, c.get("customer"),
                                               c.get("customer_id"), memo_text):
                                c["_owed"] = owed
                                memo_hits.append(c)
                        if len(memo_hits) == 1:
                            matched = memo_hits
                            matched_via_memo = True
                            logger.info(
                                "venmo memo-match: exp %s payer='%s' handle=%r -> "
                                "item %s (%s) via memo name",
                                exp.get("id"), payer_name,
                                exp.get("other_party_handle"),
                                memo_hits[0]["id"], memo_hits[0].get("customer"),
                            )
                        elif len(memo_hits) > 1:
                            logger.info(
                                "venmo memo-match ambiguous: exp %s matched %d open "
                                "balances by memo name — leaving for manual",
                                exp.get("id"), len(memo_hits),
                            )

                if not matched:
                    summary["no_candidate"] += 1
                    continue
                if len(matched) > 1:
                    # Ambiguous — leave for manual handling
                    summary["ambiguous"] += 1
                    continue

                target = matched[0]
                target_id = target["id"]
                event_name = target["item_name"]
                customer_name = target["customer"]

                # Idempotency safety net: skip if any +PAY child already references this expense
                already = conn.execute(
                    """SELECT id FROM items
                       WHERE parent_item_id = ?
                         AND notes LIKE ? LIMIT 1""",
                    (target_id, f"%[venmo-bd-exp:{exp['id']}]%"),
                ).fetchone()
                if already:
                    summary["already_matched"] += 1
                    # Backfill the matched_item_id pointer if missing
                    conn.execute(
                        "UPDATE expense_transactions SET matched_item_id = ? WHERE id = ?",
                        (target_id, exp["id"]),
                    )
                    conn.commit()
                    continue

                # Create the +PAY child item
                txn_date = exp.get("transaction_date") or _dt.datetime.utcnow().strftime("%Y-%m-%d")
                amount_str = f"${exp_amount:.2f}"
                # Marker stays in notes so the match is auditable later
                note = f"Balance due — Venmo {amount_str} [venmo-bd-exp:{exp['id']}]"
                if matched_via_memo:
                    note += " [memo-match]"
                # We bypass add_payment_to_event() to set our own email_uid
                # (add_payment_to_event uses a timestamp uid; we want a deterministic one
                # so re-running the matcher is naturally idempotent on the items table too).
                event = dict(conn.execute(
                    "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
                    (event_name,),
                ).fetchone() or {})
                parent_full = dict(conn.execute(
                    "SELECT * FROM items WHERE id = ?", (target_id,),
                ).fetchone() or {})
                parent_snap = {}
                for fld in ("side_games", "holes", "tee_choice", "user_status"):
                    if parent_full.get(fld) is not None:
                        parent_snap[fld] = parent_full[fld]

                uid = f"venmo-bd-{exp['id']}"
                new_values = {col: None for col in ITEM_COLUMNS}
                new_values["email_uid"] = uid
                new_values["item_index"] = 0
                new_values["customer"] = customer_name
                new_values["customer_email"] = parent_full.get("customer_email")
                new_values["customer_phone"] = parent_full.get("customer_phone")
                new_values["item_name"] = event_name
                new_values["order_date"] = txn_date
                new_values["course"] = event.get("course") or parent_full.get("course") or ""
                new_values["chapter"] = event.get("chapter") or parent_full.get("chapter") or ""
                new_values["transaction_status"] = "active"
                new_values["merchant"] = "Manual Entry (venmo)"
                new_values["item_price"] = amount_str
                new_values["side_games"] = ""
                new_values["notes"] = note
                new_values["parent_item_id"] = target_id
                new_values["parent_snapshot"] = json.dumps(parent_snap) if parent_snap else None

                # The +PAY child inherits the parent's identity — the payment
                # settles THAT item's balance, so re-resolving by name/email
                # could pin the child to a different same-named customer.
                # Only fall back to resolution when the parent has no cid.
                cust_id = parent_full.get("customer_id") or _resolve_or_create_customer(
                    conn,
                    customer_name=customer_name,
                    customer_email=parent_full.get("customer_email") or "",
                    phone=parent_full.get("customer_phone") or "",
                )
                if cust_id:
                    new_values["customer_id"] = cust_id

                cols = ", ".join(new_values.keys())
                placeholders = ", ".join(["?"] * len(new_values))
                try:
                    cur = conn.execute(
                        f"INSERT INTO items ({cols}) VALUES ({placeholders})",
                        list(new_values.values()),
                    )
                    new_item_id = cur.lastrowid
                except sqlite3.IntegrityError:
                    # Race: a previous run already created this +PAY. Look it up.
                    row = conn.execute(
                        "SELECT id FROM items WHERE email_uid = ? AND item_index = 0",
                        (uid,),
                    ).fetchone()
                    if row:
                        new_item_id = row["id"]
                        summary["already_matched"] += 1
                    else:
                        summary["errors"] += 1
                        continue

                # Flip parent's credit_note from balance_due:X.XX to paid_at:YYYY-MM-DD
                conn.execute(
                    "UPDATE items SET credit_note = ? WHERE id = ?",
                    (f"paid_at:{txn_date}", target_id),
                )

                # Stamp the expense as matched and auto-approve if still pending
                conn.execute(
                    """UPDATE expense_transactions
                       SET matched_item_id = ?,
                           review_status = CASE WHEN review_status = 'pending'
                                                THEN 'approved' ELSE review_status END
                       WHERE id = ?""",
                    (new_item_id, exp["id"]),
                )

                # If _sync_expense_ledger_entry already promoted this expense
                # to acct_transactions (description=merchant, no event/category),
                # soft-delete that row so the venmo-bd entry below is the single
                # source of truth — otherwise we double-count the same payment.
                old_acct_id = exp.get("acct_transaction_id")
                if old_acct_id:
                    conn.execute(
                        "UPDATE acct_transactions SET status = 'reversed', updated_at = datetime('now') WHERE id = ?",
                        (old_acct_id,),
                    )

                # Write accounting entries (income/addon + allocation) for the +PAY child
                try:
                    new_acct_id = _write_acct_entry(
                        conn,
                        item_id=new_item_id,
                        event_name=event_name,
                        customer=customer_name,
                        order_id=f"VENMO-BD-{new_item_id}",
                        entry_type="income",
                        category="addon",
                        source="venmo",
                        amount=exp_amount,
                        description=f"Venmo balance-due payment from {customer_name}",
                        account="Venmo",
                        source_ref=f"venmo-bd-{exp['id']}",
                        date=txn_date,
                    )
                    # Re-point the expense_transaction at the venmo-bd row so
                    # subsequent sync calls don't recreate the exp-promoted dup.
                    if new_acct_id:
                        conn.execute(
                            "UPDATE expense_transactions SET acct_transaction_id = ? WHERE id = ?",
                            (new_acct_id, exp["id"]),
                        )
                except Exception:
                    logger.warning(
                        "Failed to write acct entry for venmo balance-due match (exp %s)",
                        exp["id"], exc_info=True,
                    )

                conn.commit()
                # Also stamp the player's Venmo @handle on their customer record if not set.
                # Best-effort; ignore failures.
                try:
                    capture_venmo_handle_for_customer(exp["id"], db_path=db_path)
                except Exception:
                    logger.warning(
                        "capture_venmo_handle_for_customer failed for exp %s",
                        exp["id"], exc_info=True,
                    )
                summary["matched"] += 1
                summary["matches"].append({
                    "expense_id": exp["id"],
                    "item_id": new_item_id,
                    "parent_item_id": target_id,
                    "customer": customer_name,
                    "event_name": event_name,
                    "amount": exp_amount,
                })
            except Exception:
                logger.warning(
                    "auto_match_venmo_inbound_to_balance_due failed for expense %s",
                    exp.get("id"), exc_info=True,
                )
                summary["errors"] += 1

    return summary


def reconcile_orphan_venmo_payments(
    db_path: str | Path | None = None,
    max_days_back: int = 14,
    dry_run: bool = False,
) -> dict:
    """Sweep credit-transfer items with `balance_due:` notes and net them against:
      1. Existing manual-entry +PAY children already attached to the parent
         (case-insensitive match on `merchant LIKE 'Manual Entry%'`), and
      2. Orphan +PAY items by the same customer in the last `max_days_back`
         days (these get reparented onto the credit-transfer item).

    Fixes both:
      - "Paid via Venmo before RSVP, then Apply Credit" (orphan case)
      - "+PAY entered against the parent but credit_note was never reduced"
        (already-attached child case — Joshua Bartz)

    Idempotent and safe to re-run.

    Returns: {"scanned", "fixed", "fully_paid", "partially_paid",
              "overpayments_posted", "details": [...]}
    """
    import datetime as _dt
    summary = {
        "scanned": 0, "fixed": 0, "fully_paid": 0,
        "partially_paid": 0, "overpayments_posted": 0,
        "details": [],
    }
    with _connect(db_path) as conn:
        parents = conn.execute(
            """SELECT id, customer, customer_email, item_name, chapter, credit_note
               FROM items
               WHERE merchant = 'Paid Separately (Credit Transfer)'
                 AND COALESCE(transaction_status, 'active') = 'active'
                 AND credit_note LIKE 'balance_due:%'"""
        ).fetchall()
        summary["scanned"] = len(parents)

        for p in parents:
            p = dict(p)
            try:
                owed = float((p["credit_note"] or "").split(":", 1)[1])
            except (ValueError, IndexError):
                continue
            if owed <= 0:
                continue
            customer = (p.get("customer") or "").strip()
            if not customer:
                continue

            # Pass 1: existing manual-entry children already attached.
            existing = _sum_existing_child_payments(conn, p["id"])
            already_paid = existing["total"]

            # Pass 2: any remainder consumed from orphan payments by this customer.
            remainder_owed = max(0.0, round(owed - already_paid, 2))
            consumed = {"consumed_total": 0.0, "consumed_ids": [], "remaining_owed": remainder_owed}
            if remainder_owed > 0:
                consumed = _consume_unallocated_payments_for_credit_transfer(
                    conn,
                    parent_item_id=p["id"],
                    customer=customer,
                    amount_owed=remainder_owed,
                    max_days_back=max_days_back,
                    exclude_ids={p["id"], *existing["ids"]},
                )

            total_paid = round(already_paid + consumed["consumed_total"], 2)
            if total_paid <= 0:
                continue  # nothing to apply for this parent

            remaining = max(0.0, round(owed - total_paid, 2))
            overpayment = max(0.0, round(total_paid - owed, 2))
            new_note = (
                f"balance_due:{remaining:.2f}" if remaining > 0
                else f"paid_at:{_dt.datetime.utcnow().strftime('%Y-%m-%d')}"
            )

            if dry_run:
                # Roll back any reparenting so dry-run leaves the DB unchanged.
                tag = _XFER_CONSUMED_TAG.format(parent_id=p["id"])
                for cid in consumed["consumed_ids"]:
                    cur = conn.execute(
                        "SELECT notes FROM items WHERE id = ?", (cid,)
                    ).fetchone()
                    cleaned = " ".join((cur["notes"] or "").replace(tag, "").split())
                    conn.execute(
                        "UPDATE items SET parent_item_id = NULL, notes = ? WHERE id = ?",
                        (cleaned or None, cid),
                    )
            else:
                conn.execute(
                    "UPDATE items SET credit_note = ? WHERE id = ?",
                    (new_note, p["id"]),
                )
                if overpayment > 0:
                    _post_overpayment_credit(conn, p, p["id"], overpayment)
                    summary["overpayments_posted"] += 1

            summary["fixed"] += 1
            if remaining > 0:
                summary["partially_paid"] += 1
            else:
                summary["fully_paid"] += 1
            summary["details"].append({
                "parent_item_id": p["id"],
                "customer": customer,
                "event": p.get("item_name"),
                "owed": owed,
                "already_paid_via_children": already_paid,
                "existing_child_ids": existing["ids"],
                "consumed_orphan_total": consumed["consumed_total"],
                "consumed_orphan_ids": consumed["consumed_ids"],
                "total_paid": total_paid,
                "remaining": remaining,
                "overpayment": overpayment,
            })

        if not dry_run:
            conn.commit()
    return summary


def save_rsvp(rsvp: dict, db_path: str | Path | None = None) -> int | None:
    """
    Save a parsed RSVP to the database.

    Performs event and item matching before insert.
    Returns the rsvp id, or None if it was a duplicate.
    """
    with _connect(db_path) as conn:

        # Match event
        matched_event = match_rsvp_to_event(
            rsvp["event_identifier"], rsvp.get("event_date"), db_path,
        )

        # Match transaction
        matched_item_id = None
        if matched_event:
            matched_item_id = match_rsvp_to_item(
                rsvp.get("player_email"), rsvp.get("player_name"),
                matched_event, db_path,
            )

        # Resolve customer_id at insert time so the FK is populated immediately
        rsvp_customer_id = _lookup_customer_id(
            conn, rsvp.get("player_name"), rsvp.get("player_email")
        )

        try:
            cursor = conn.execute(
                """INSERT OR IGNORE INTO rsvps
                   (email_uid, player_name, player_email, gg_event_name,
                    event_identifier, event_date, response, received_at,
                    matched_event, matched_item_id, customer_id)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (
                    rsvp["email_uid"],
                    rsvp.get("player_name"),
                    rsvp.get("player_email"),
                    rsvp.get("gg_event_name"),
                    rsvp.get("event_identifier"),
                    rsvp.get("event_date"),
                    rsvp["response"],
                    rsvp.get("received_at"),
                    matched_event,
                    matched_item_id,
                    rsvp_customer_id,
                ),
            )
            conn.commit()
            if cursor.rowcount > 0:
                rsvp_id = cursor.lastrowid
                logger.info(
                    "Saved RSVP: %s %s for %s (matched_event=%s, matched_item=%s)",
                    rsvp.get("player_name"), rsvp["response"],
                    rsvp.get("event_identifier"), matched_event, matched_item_id,
                )
                return rsvp_id
        except sqlite3.IntegrityError:
            logger.debug("Duplicate RSVP skipped: email_uid=%s", rsvp.get("email_uid"))

        return None


def save_rsvps(rsvps: list[dict], db_path: str | Path | None = None) -> int:
    """Save a batch of parsed RSVPs. Returns count of newly inserted."""
    inserted = 0
    for rsvp in rsvps:
        result = save_rsvp(rsvp, db_path)
        if result is not None:
            inserted += 1
    logger.info("Saved %d new RSVPs (%d total provided)", inserted, len(rsvps))
    return inserted


def get_rsvps_for_event(event_name: str, db_path: str | Path | None = None) -> list[dict]:
    """
    Return the latest RSVP for each player for the given event.

    Groups by player_email and returns only the most recent response.
    Also resolves the full player name from existing items (player cards)
    by matching on player_email, and flags whether a player card was found.
    """
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT r1.*
               FROM rsvps r1
               INNER JOIN (
                   SELECT player_email, MAX(received_at) AS max_date
                   FROM rsvps
                   WHERE matched_event = ?
                     AND player_email IS NOT NULL AND player_email != ''
                   GROUP BY player_email
               ) r2 ON r1.player_email = r2.player_email AND r1.received_at = r2.max_date
               WHERE r1.matched_event = ?
               ORDER BY r1.player_name ASC""",
            (event_name, event_name),
        ).fetchall()

        # Resolve full names. Prefer the customers table via customer_id FK
        # (authoritative for RSVP-only players who never bought a ticket);
        # fall back to items.customer by email; last fall back to player_name.
        results = []
        for r in rows:
            rsvp = dict(r)
            rsvp["resolved_name"] = rsvp.get("player_name")
            rsvp["has_player_card"] = False
            rsvp["customer_status"] = None
            cid = rsvp.get("customer_id")
            if cid:
                cust = conn.execute(
                    """SELECT TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')) AS full_name,
                              c.current_player_status,
                              EXISTS(SELECT 1 FROM customer_roles r
                                     WHERE r.customer_id = c.customer_id
                                       AND r.role_type IN ('manager','owner','admin')) AS is_staff
                       FROM customers c WHERE c.customer_id = ?""",
                    (cid,),
                ).fetchone()
                if cust:
                    if cust["full_name"]:
                        rsvp["resolved_name"] = cust["full_name"]
                    if cust["is_staff"]:
                        rsvp["customer_status"] = "MANAGER"
                    elif cust["current_player_status"] == "active_member":
                        rsvp["customer_status"] = "MEMBER"
                    elif cust["current_player_status"] == "member_plus":
                        rsvp["customer_status"] = "MEMBER+"
            email = (rsvp.get("player_email") or "").strip().lower()
            if email:
                card = conn.execute(
                    """SELECT customer FROM items
                       WHERE LOWER(customer_email) = ?
                         AND customer IS NOT NULL AND customer != ''
                       ORDER BY order_date DESC LIMIT 1""",
                    (email,),
                ).fetchone()
                if card:
                    if not cid:
                        rsvp["resolved_name"] = card["customer"]
                    rsvp["has_player_card"] = True
            results.append(rsvp)

        return results


def get_all_rsvps_bulk(db_path: str | Path | None = None) -> dict:
    """Return latest RSVP per player per event, grouped by event name.

    Also includes all rsvp_overrides and rsvp_email_overrides so the
    frontend can compute accurate player counts without per-event fetches.

    Returns {
        rsvps: {event_name: [rsvp, ...]},
        overrides: {event_name: {item_id: status, ...}},
        email_overrides: {event_name: {email: status, ...}},
    }
    """
    with _connect(db_path) as conn:
        # Latest RSVP per player per event
        rows = conn.execute(
            """SELECT r1.*
               FROM rsvps r1
               INNER JOIN (
                   SELECT matched_event, player_email, MAX(received_at) AS max_date
                   FROM rsvps
                   WHERE matched_event IS NOT NULL AND matched_event != ''
                     AND player_email IS NOT NULL AND player_email != ''
                   GROUP BY matched_event, player_email
               ) r2 ON r1.matched_event = r2.matched_event
                    AND r1.player_email = r2.player_email
                    AND r1.received_at = r2.max_date
               ORDER BY r1.matched_event, r1.player_name ASC"""
        ).fetchall()

        # Resolve player names from items table (bulk)
        emails = {(r["player_email"] or "").strip().lower() for r in rows if r["player_email"]}
        name_map = {}
        if emails:
            placeholders = ",".join("?" * len(emails))
            cards = conn.execute(
                f"""SELECT LOWER(customer_email) as email, customer
                    FROM items
                    WHERE LOWER(customer_email) IN ({placeholders})
                      AND customer IS NOT NULL AND customer != ''
                    ORDER BY order_date DESC""",
                list(emails),
            ).fetchall()
            for c in cards:
                if c["email"] not in name_map:
                    name_map[c["email"]] = c["customer"]

        # Resolve canonical full names + member status from customers table via customer_id FK.
        # Authoritative for RSVP-only players who never bought a ticket.
        cust_ids = {r["customer_id"] for r in rows if r["customer_id"]}
        cust_name_map = {}
        cust_status_map = {}
        if cust_ids:
            placeholders = ",".join("?" * len(cust_ids))
            cust_rows = conn.execute(
                f"""SELECT c.customer_id,
                           TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')) AS full_name,
                           c.current_player_status,
                           EXISTS(SELECT 1 FROM customer_roles r
                                  WHERE r.customer_id = c.customer_id
                                    AND r.role_type IN ('manager','owner','admin')) AS is_staff
                    FROM customers c
                    WHERE c.customer_id IN ({placeholders})""",
                list(cust_ids),
            ).fetchall()
            status_label = {"active_member": "MEMBER", "member_plus": "MEMBER+"}
            for c in cust_rows:
                if c["full_name"]:
                    cust_name_map[c["customer_id"]] = c["full_name"]
                if c["is_staff"]:
                    cust_status_map[c["customer_id"]] = "MANAGER"
                elif c["current_player_status"] in status_label:
                    cust_status_map[c["customer_id"]] = status_label[c["current_player_status"]]

        rsvps_by_event = {}
        for r in rows:
            rsvp = dict(r)
            email = (rsvp.get("player_email") or "").strip().lower()
            cid = rsvp.get("customer_id")
            rsvp["resolved_name"] = (
                cust_name_map.get(cid)
                or name_map.get(email)
                or rsvp.get("player_name")
            )
            rsvp["has_player_card"] = email in name_map
            rsvp["customer_status"] = cust_status_map.get(cid)
            evt = rsvp.get("matched_event") or ""
            rsvps_by_event.setdefault(evt, []).append(rsvp)

        # All overrides by event
        ov_rows = conn.execute("SELECT item_id, event_name, status FROM rsvp_overrides").fetchall()
        overrides = {}
        for r in ov_rows:
            overrides.setdefault(r["event_name"], {})[r["item_id"]] = r["status"]

        # All email overrides by event
        eov_rows = conn.execute("SELECT player_email, event_name, status FROM rsvp_email_overrides").fetchall()
        email_overrides = {}
        for r in eov_rows:
            email_overrides.setdefault(r["event_name"], {})[r["player_email"]] = r["status"]

        return {
            "rsvps": rsvps_by_event,
            "overrides": overrides,
            "email_overrides": email_overrides,
        }


def get_all_rsvps(event_name: str = "", response: str = "",
                   db_path: str | Path | None = None) -> list[dict]:
    """Return RSVPs with optional filtering by event and/or response.

    Also resolves the full customer name from the items table and
    customer_aliases (email type) so the frontend can show the canonical
    name and knows which RSVPs still need manual linking.
    """
    with _connect(db_path) as conn:
        clauses = []
        params = []

        if event_name:
            clauses.append("matched_event LIKE ?")
            params.append(f"%{event_name}%")
        if response:
            clauses.append("response = ?")
            params.append(response.upper())

        where = (" WHERE " + " AND ".join(clauses)) if clauses else ""
        rows = conn.execute(
            f"SELECT * FROM rsvps{where} ORDER BY received_at DESC",
            params,
        ).fetchall()

        # Bulk-resolve customer names from items table by email
        emails = {(r["player_email"] or "").strip().lower()
                  for r in rows if r["player_email"]}
        name_map: dict[str, str] = {}
        if emails:
            placeholders = ",".join("?" * len(emails))
            # Primary: match on items.customer_email
            cards = conn.execute(
                f"""SELECT LOWER(customer_email) as email, customer
                    FROM items
                    WHERE LOWER(customer_email) IN ({placeholders})
                      AND customer IS NOT NULL AND customer != ''
                    ORDER BY order_date DESC""",
                list(emails),
            ).fetchall()
            for c in cards:
                if c["email"] not in name_map:
                    name_map[c["email"]] = c["customer"]

            # Secondary: match on customer_aliases (email type)
            unresolved = emails - set(name_map.keys())
            if unresolved:
                ph2 = ",".join("?" * len(unresolved))
                alias_rows = conn.execute(
                    f"""SELECT LOWER(alias_value) as email, customer_name
                        FROM customer_aliases
                        WHERE alias_type = 'email'
                          AND LOWER(alias_value) IN ({ph2})""",
                    list(unresolved),
                ).fetchall()
                for a in alias_rows:
                    if a["email"] not in name_map:
                        name_map[a["email"]] = a["customer_name"]

        results = []
        for r in rows:
            rsvp = dict(r)
            email = (rsvp.get("player_email") or "").strip().lower()
            rsvp["resolved_name"] = name_map.get(email, rsvp.get("player_name"))
            rsvp["has_player_card"] = email in name_map
            results.append(rsvp)

        return results


def get_rsvp_stats(db_path: str | Path | None = None) -> dict:
    """Return summary RSVP statistics."""
    with _connect(db_path) as conn:
        total = conn.execute("SELECT COUNT(*) as c FROM rsvps").fetchone()["c"]
        playing = conn.execute(
            "SELECT COUNT(*) as c FROM rsvps WHERE response = 'PLAYING'"
        ).fetchone()["c"]
        not_playing = conn.execute(
            "SELECT COUNT(*) as c FROM rsvps WHERE response = 'NOT PLAYING'"
        ).fetchone()["c"]
        matched = conn.execute(
            "SELECT COUNT(*) as c FROM rsvps WHERE matched_item_id IS NOT NULL"
        ).fetchone()["c"]
        unmatched = conn.execute(
            "SELECT COUNT(*) as c FROM rsvps WHERE matched_event IS NOT NULL AND matched_item_id IS NULL AND response = 'PLAYING'"
        ).fetchone()["c"]
        return {
            "total_rsvps": total,
            "playing": playing,
            "not_playing": not_playing,
            "matched_to_transaction": matched,
            "playing_no_transaction": unmatched,
        }


def rematch_rsvps(db_path: str | Path | None = None) -> dict:
    """
    Re-run matching logic on all RSVPs that are missing matches.

    Useful after new events or transactions are added.
    Returns {"rematched_events": N, "rematched_items": N}.
    """
    with _connect(db_path) as conn:
        rows = conn.execute(
            "SELECT * FROM rsvps WHERE matched_event IS NULL OR matched_item_id IS NULL"
        ).fetchall()

        rematched_events = 0
        rematched_items = 0

        for row in rows:
            rsvp = dict(row)
            updates = {}

            # Re-match event
            if not rsvp.get("matched_event"):
                matched_event = match_rsvp_to_event(
                    rsvp["event_identifier"], rsvp.get("event_date"), db_path,
                )
                if matched_event:
                    updates["matched_event"] = matched_event
                    rematched_events += 1

            event_name = updates.get("matched_event") or rsvp.get("matched_event")

            # Re-match item
            if event_name and not rsvp.get("matched_item_id"):
                matched_item = match_rsvp_to_item(
                    rsvp.get("player_email"), rsvp.get("player_name"),
                    event_name, db_path,
                )
                if matched_item:
                    updates["matched_item_id"] = matched_item
                    rematched_items += 1

            if updates:
                set_clause = ", ".join(f"{k} = ?" for k in updates)
                values = list(updates.values()) + [rsvp["id"]]
                conn.execute(f"UPDATE rsvps SET {set_clause} WHERE id = ?", values)

        conn.commit()
        logger.info("Rematch: %d events, %d items rematched", rematched_events, rematched_items)
        return {"rematched_events": rematched_events, "rematched_items": rematched_items}


def audit_upcoming_event_rsvps(db_path: str | Path | None = None) -> dict:
    """Self-healing RSVP match hygiene (Kerry 2026-07-15: 'I don't want
    to worry that things aren't matching'): run audit_event_rsvps —
    clear email-mismatched matches + rematch — across every ACTIVE
    upcoming event (event_date >= today Central). Idempotent and pure
    DB work, so it's safe to run after every RSVP ingest and nightly.
    Returns totals plus a by_event map of only the events that changed.
    """
    with _connect(db_path) as conn:
        names = [r["item_name"] for r in conn.execute(
            """SELECT item_name FROM events
               WHERE event_date >= ?
                 AND COALESCE(status, 'active') = 'active'
               ORDER BY event_date""",
            (today_central_str(),),
        ).fetchall()]
    out = {"events_audited": 0, "cleared": 0, "rematched": 0, "by_event": {}}
    for nm in names:
        try:
            res = audit_event_rsvps(nm, db_path=db_path)
        except Exception:
            logger.exception("RSVP auto-audit failed for %s", nm)
            continue
        out["events_audited"] += 1
        c, m = res.get("cleared", 0), res.get("rematched", 0)
        out["cleared"] += c
        out["rematched"] += m
        if c or m:
            out["by_event"][nm] = {"cleared": c, "rematched": m}
    return out


def audit_event_rsvps(event_name: str, db_path: str | Path | None = None) -> dict:
    """Audit and fix RSVP-to-item matches for a specific event.

    Checks all RSVPs matched to this event and:
    1. Clears matched_item_id when the RSVP email doesn't match the item's email
       (fixes false positives from first-name matching)
    2. Re-attempts matching for RSVPs with no matched_item_id

    Returns {"cleared": N, "rematched": N, "details": [...]}
    """
    with _connect(db_path) as conn:
        rsvps = conn.execute(
            "SELECT * FROM rsvps WHERE matched_event = ?",
            (event_name,),
        ).fetchall()

        cleared = 0
        rematched = 0
        details = []

        for row in rsvps:
            rsvp = dict(row)

            # Check existing matched_item_id for email mismatch
            if rsvp.get("matched_item_id"):
                item = conn.execute(
                    "SELECT id, customer, customer_email FROM items WHERE id = ?",
                    (rsvp["matched_item_id"],),
                ).fetchone()
                if item:
                    rsvp_email = (rsvp.get("player_email") or "").strip().lower()
                    item_email = (item["customer_email"] or "").strip().lower()
                    if rsvp_email and item_email and rsvp_email != item_email:
                        # Mismatched — clear the bad match
                        conn.execute(
                            "UPDATE rsvps SET matched_item_id = NULL WHERE id = ?",
                            (rsvp["id"],),
                        )
                        details.append({
                            "action": "cleared",
                            "rsvp_player": rsvp.get("player_name"),
                            "rsvp_email": rsvp.get("player_email"),
                            "was_matched_to": item["customer"],
                            "item_email": item["customer_email"],
                        })
                        cleared += 1
                        rsvp["matched_item_id"] = None  # proceed to re-match below
                elif not item:
                    # Item was deleted — clear the stale reference
                    conn.execute(
                        "UPDATE rsvps SET matched_item_id = NULL WHERE id = ?",
                        (rsvp["id"],),
                    )
                    details.append({
                        "action": "cleared_deleted",
                        "rsvp_player": rsvp.get("player_name"),
                        "rsvp_email": rsvp.get("player_email"),
                        "was_matched_to_id": rsvp.get("matched_item_id"),
                    })
                    cleared += 1
                    rsvp["matched_item_id"] = None

            # Re-attempt matching for unmatched RSVPs
            if not rsvp.get("matched_item_id"):
                matched_item = match_rsvp_to_item(
                    rsvp.get("player_email"), rsvp.get("player_name"),
                    event_name, db_path,
                )
                if matched_item:
                    conn.execute(
                        "UPDATE rsvps SET matched_item_id = ? WHERE id = ?",
                        (matched_item, rsvp["id"]),
                    )
                    details.append({
                        "action": "rematched",
                        "rsvp_player": rsvp.get("player_name"),
                        "rsvp_email": rsvp.get("player_email"),
                        "matched_to_item_id": matched_item,
                    })
                    rematched += 1

        conn.commit()
        logger.info("Audit event '%s': cleared %d bad matches, rematched %d",
                     event_name, cleared, rematched)
        return {"cleared": cleared, "rematched": rematched, "details": details}


def manual_match_rsvp(rsvp_id: int, event_name: str,
                       db_path: str | Path | None = None) -> bool:
    """Manually set the matched_event for an RSVP.

    Also attempts to match the player to a specific item in that event.
    Returns True if the RSVP was updated.
    """
    with _connect(db_path) as conn:
        rsvp = conn.execute("SELECT * FROM rsvps WHERE id = ?", (rsvp_id,)).fetchone()
        if not rsvp:
            return False
        rsvp = dict(rsvp)

        # Try to match the player to an item
        matched_item_id = match_rsvp_to_item(
            rsvp.get("player_email"), rsvp.get("player_name"),
            event_name, db_path,
        )

        conn.execute(
            "UPDATE rsvps SET matched_event = ?, matched_item_id = ? WHERE id = ?",
            (event_name, matched_item_id, rsvp_id),
        )
        conn.commit()
        logger.info("Manual RSVP match: rsvp #%d → event '%s' (item=%s)",
                    rsvp_id, event_name, matched_item_id)
        return True


def unmatch_rsvp(rsvp_id: int, db_path: str | Path | None = None) -> bool:
    """Clear the matched_event and matched_item_id for an RSVP.

    Returns True if the RSVP was updated.
    """
    with _connect(db_path) as conn:
        cursor = conn.execute(
            "UPDATE rsvps SET matched_event = NULL, matched_item_id = NULL WHERE id = ?",
            (rsvp_id,),
        )
        conn.commit()
        return cursor.rowcount > 0


def normalize_tee_choices(db_path: str | Path | None = None) -> int:
    """
    One-time migration: standardise all tee_choice values in the DB.
    Standards: <50, 50-64, 65+, Forward.
    Returns the number of rows updated.
    """
    _TEE_MAP = [
        (re.compile(r"\bforward\b|\bfront\b", re.IGNORECASE), "Forward"),
        (re.compile(r"\b65\s*\+", re.IGNORECASE), "65+"),
        (re.compile(r"\b50\s*[-–]\s*64\b", re.IGNORECASE), "50-64"),
        (re.compile(r"(?:^|(?<=\s))<\s*50\b|\bunder\s*50\b", re.IGNORECASE), "<50"),
    ]
    canonical = {"<50", "50-64", "65+", "Forward"}

    with _connect(db_path) as conn:
        rows = conn.execute(
            "SELECT id, tee_choice FROM items WHERE tee_choice IS NOT NULL AND tee_choice != ''"
        ).fetchall()

        updated = 0
        for row_id, val in rows:
            cleaned = val.strip()
            if cleaned in canonical:
                continue
            new_val = cleaned
            for pattern, label in _TEE_MAP:
                if pattern.search(cleaned):
                    new_val = label
                    break
            if new_val != val:
                conn.execute("UPDATE items SET tee_choice = ? WHERE id = ?", (new_val, row_id))
                updated += 1

        conn.commit()
        return updated


