def get_message_templates(db_path: str | Path | None = None) -> list[dict]:
    """Return all message templates, system templates first."""
    with _connect(db_path) as conn:
        rows = conn.execute(
            "SELECT * FROM message_templates ORDER BY is_system DESC, name ASC"
        ).fetchall()
        return [dict(r) for r in rows]


def get_message_template(template_id: int, db_path: str | Path | None = None) -> dict | None:
    """Return a single template by ID."""
    with _connect(db_path) as conn:
        row = conn.execute(
            "SELECT * FROM message_templates WHERE id = ?", (template_id,)
        ).fetchone()
        return dict(row) if row else None


def create_message_template(data: dict, db_path: str | Path | None = None) -> dict:
    """Create a new message template. Returns the created template."""
    with _connect(db_path) as conn:
        cur = conn.execute(
            "INSERT INTO message_templates (name, channel, subject, html_body, sms_body) "
            "VALUES (?, ?, ?, ?, ?)",
            (data["name"], data.get("channel", "email"), data.get("subject"),
             data.get("html_body"), data.get("sms_body")),
        )
        conn.commit()
        return dict(conn.execute(
            "SELECT * FROM message_templates WHERE id = ?", (cur.lastrowid,)
        ).fetchone())


def update_message_template(template_id: int, data: dict, db_path: str | Path | None = None) -> dict | None:
    """Update a message template. Cannot edit system template names. Returns updated template."""
    with _connect(db_path) as conn:
        existing = conn.execute(
            "SELECT * FROM message_templates WHERE id = ?", (template_id,)
        ).fetchone()
        if not existing:
            return None
        fields = []
        values = []
        for col in ("name", "channel", "subject", "html_body", "sms_body"):
            if col in data:
                if col == "name" and existing["is_system"]:
                    continue
                fields.append(f"{col} = ?")
                values.append(data[col])
        if not fields:
            return dict(existing)
        fields.append("updated_at = datetime('now')")
        values.append(template_id)
        conn.execute(
            f"UPDATE message_templates SET {', '.join(fields)} WHERE id = ?",
            values,
        )
        conn.commit()
        return dict(conn.execute(
            "SELECT * FROM message_templates WHERE id = ?", (template_id,)
        ).fetchone())


def delete_message_template(template_id: int, db_path: str | Path | None = None) -> bool:
    """Delete a non-system template. Returns True if deleted."""
    with _connect(db_path) as conn:
        existing = conn.execute(
            "SELECT is_system FROM message_templates WHERE id = ?", (template_id,)
        ).fetchone()
        if not existing or existing["is_system"]:
            return False
        conn.execute("DELETE FROM message_templates WHERE id = ?", (template_id,))
        conn.commit()
        return True


def log_message(data: dict, db_path: str | Path | None = None) -> int:
    """Log a sent message. Returns the new log entry ID."""
    with _connect(db_path) as conn:
        cur = conn.execute(
            "INSERT INTO message_log "
            "(event_name, template_id, channel, recipient_name, recipient_address, "
            " subject, body_preview, status, error_message, sent_by) "
            "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
            (
                data.get("event_name"),
                data.get("template_id"),
                data["channel"],
                data.get("recipient_name"),
                data["recipient_address"],
                data.get("subject"),
                data.get("body_preview"),
                data.get("status", "sent"),
                data.get("error_message"),
                data.get("sent_by"),
            ),
        )
        conn.commit()
        return cur.lastrowid


def get_message_log(event_name: str | None = None, limit: int = 200,
                    db_path: str | Path | None = None) -> list[dict]:
    """Return message log entries, optionally filtered by event."""
    with _connect(db_path) as conn:
        if event_name:
            rows = conn.execute(
                "SELECT * FROM message_log WHERE event_name = ? ORDER BY sent_at DESC LIMIT ?",
                (event_name, limit),
            ).fetchall()
        else:
            rows = conn.execute(
                "SELECT * FROM message_log ORDER BY sent_at DESC LIMIT ?",
                (limit,),
            ).fetchall()
        return [dict(r) for r in rows]


# ---------------------------------------------------------------------------
# Handicap calculator
# ---------------------------------------------------------------------------

# WHS Rule 5.2a differential lookup: number of differentials to use.
_HANDICAP_DIFF_LOOKUP = {
    3: 1,  4: 1,  5: 1,
    6: 2,  7: 2,  8: 2,
    9: 3, 10: 3, 11: 3,
    12: 4, 13: 4, 14: 4,
    15: 5, 16: 5,
    17: 6, 18: 6,
    19: 7,
    20: 8,
}

# WHS Rule 5.2a adjustments (added after avg × 0.96).
# Applied when fewer rounds yield an index that could be too favourable.
_HANDICAP_ADJUSTMENT = {3: -2.0, 4: -1.0, 6: -1.0}

_HANDICAP_SETTINGS_DEFAULTS = {
    "lookback_months": "12",      # max age of rounds to count
    "min_rounds": "3",            # minimum rounds before index is shown
    # R1 APPLIED 2026-08-03 (ratified 2026-07-16): the pre-2020 USGA 0.96
    # "bonus for excellence" is removed per WHS — dial + default are 1.0
    # so a settings wipe can't resurrect it.
    "multiplier": "1.0",
}


def _normalize_player_name(raw: str) -> str:
    """Convert 'LAST, First' or 'Last, First' to 'First Last' Title Case.

    If no comma is present, applies Title Case as-is.
    """
    raw = (raw or "").strip()
    if "," in raw:
        parts = raw.split(",", 1)
        last = parts[0].strip().title()
        first = parts[1].strip().title()
        return f"{first} {last}"
    return raw.title()


def get_handicap_settings(db_path: str | Path | None = None) -> dict:
    """Return all handicap settings as a dict of {key: value} strings."""
    with _connect(db_path) as conn:
        rows = conn.execute("SELECT key, value FROM handicap_settings").fetchall()
    result = dict(_HANDICAP_SETTINGS_DEFAULTS)
    for row in rows:
        result[row["key"]] = row["value"]
    return result


def update_handicap_settings(settings: dict,
                               db_path: str | Path | None = None) -> None:
    """Upsert one or more handicap settings keys."""
    with _connect(db_path) as conn:
        for key, value in settings.items():
            conn.execute(
                "INSERT INTO handicap_settings (key, value) VALUES (?, ?) "
                "ON CONFLICT(key) DO UPDATE SET value = excluded.value, "
                "updated_at = datetime('now')",
                (key, str(value)),
            )
        conn.commit()


def compute_handicap_index(differentials: list[float],
                            settings: dict | None = None) -> float | None:
    """Compute 9-hole handicap index from a list of 9-hole differentials.

    Uses up to 20 most-recent differentials, USGA WHS lookup table, and the
    configurable multiplier (default 0.96).  Returns None if fewer than
    min_rounds (default 3) rounds are provided.
    Truncates (floors) to one decimal place.
    """
    cfg = settings or _HANDICAP_SETTINGS_DEFAULTS
    min_rounds = int(cfg.get("min_rounds", 3))
    multiplier = float(cfg.get("multiplier", 0.96))

    n = min(len(differentials), 20)
    if n < min_rounds:
        return None
    n = max(n, 3)  # lookup table starts at 3
    count = _HANDICAP_DIFF_LOOKUP.get(n, 10)
    best = sorted(differentials)[:count]
    avg = sum(best) / count
    adjustment = _HANDICAP_ADJUSTMENT.get(n, 0.0)
    index = avg * multiplier + adjustment
    # WHS Rule 5.2: round to nearest tenth (.5 rounds toward +infinity / toward zero for negatives).
    return round(index * 10) / 10


def _attach_running_index_9(rounds: list[dict], settings: dict | None = None) -> None:
    """Mutate `rounds` in place to add a 'running_index_9' field on each row.

    The running index is "the handicap that would have been in effect
    after this round was entered" — using today's fixed lookback cutoff
    so the most-recent round always equals the player's current displayed
    handicap. Computing this server-side replaces an O(N^2) loop the
    browser used to run on every player expand, which is the dominant
    cost of opening a player's score history.

    Mirrors the JS algorithm in templates/handicaps.html so values match
    byte-for-byte and the client can render without recomputing.
    """
    if not rounds:
        return

    cfg = settings or _HANDICAP_SETTINGS_DEFAULTS
    lookback_months = int(cfg.get("lookback_months", 12))
    min_rounds = int(cfg.get("min_rounds", 3))
    multiplier = float(cfg.get("multiplier", 0.96))

    # Match build_handicap_card_data's cutoff (~30.44 days/month) so the
    # running index at the latest date agrees with the canonical current
    # value rendered on the handicap card.
    cutoff = datetime.now() - timedelta(days=lookback_months * 30.44)
    cutoff_str = cutoff.strftime("%Y-%m-%d")

    def _index_for(window: list[dict]) -> float | None:
        n = len(window)
        if n < min_rounds:
            return None
        n_capped = min(n, 20)
        count = _HANDICAP_DIFF_LOOKUP.get(n_capped, 0)
        if count == 0:
            return None
        diffs = sorted(
            r["differential"] for r in window if r.get("differential") is not None
        )
        if len(diffs) < count:
            return None
        avg = sum(diffs[:count]) / count
        adj = _HANDICAP_ADJUSTMENT.get(n_capped, 0.0)
        return round((avg * multiplier + adj) * 10) / 10

    # Chronological order (oldest first); ties broken by id descending to
    # match the DB's "round_date DESC, id DESC" secondary sort when read
    # back chronologically — keeps running indices stable for same-date rounds.
    chrono = sorted(rounds, key=lambda r: (r["round_date"], -(r.get("id") or 0)))

    running: dict = {}
    for i, rnd in enumerate(chrono):
        pool = [r for r in chrono[: i + 1] if r["round_date"] >= cutoff_str]
        running[rnd["id"]] = _index_for(pool[-20:])

    # Canonical override on the latest date — the sequential loop can
    # diverge from the server's canonical "current index" when same-date
    # ties shuffle the tail of the pool. Force rounds on the most recent
    # date to the same value the handicap card displays.
    latest_date = max(r["round_date"] for r in rounds)
    active = [r for r in rounds if r["round_date"] >= cutoff_str]
    active_sorted = sorted(
        active, key=lambda r: (r["round_date"], r.get("id") or 0), reverse=True
    )
    current_idx = _index_for(active_sorted[:20])
    if current_idx is not None:
        for r in rounds:
            if r["round_date"] == latest_date:
                running[r["id"]] = current_idx

    for r in rounds:
        r["running_index_9"] = running.get(r["id"])


def _match_customer_by_email(conn: sqlite3.Connection, email: str,
                             player_name: str = "") -> str | None:
    """Match a player to a customer by email address.

    Looks up the email in the items table (customer_email column) and returns
    the canonical customer name. When multiple customers share the same email,
    prefers the one whose name is most similar to ``player_name``.
    """
    if not email:
        return None
    rows = conn.execute(
        """SELECT DISTINCT customer FROM items
           WHERE LOWER(customer_email) = LOWER(?)
           AND customer IS NOT NULL AND customer != ''""",
        (email,),
    ).fetchall()
    if rows:
        if len(rows) == 1:
            return rows[0]["customer"]
        # Multiple customers share this email — pick the best name match
        if player_name:
            pn = player_name.lower().strip()
            best = None
            best_score = -1
            for row in rows:
                cname = (row["customer"] or "").lower().strip()
                # Score: count matching words between player name and customer name
                pn_words = set(pn.split())
                cn_words = set(cname.split())
                score = len(pn_words & cn_words)
                if score > best_score:
                    best_score = score
                    best = row["customer"]
            if best:
                return best
        return rows[0]["customer"]
    # Also check customer_aliases for email aliases
    row = conn.execute(
        """SELECT ca.customer_name FROM customer_aliases ca
           WHERE ca.alias_type = 'email' AND LOWER(ca.alias_value) = LOWER(?)
           LIMIT 1""",
        (email,),
    ).fetchone()
    if row:
        return row["customer_name"]
    return None


def _match_customer_name(conn: sqlite3.Connection, player_name: str) -> str | None:
    """Try to find a matching customer name in the items table.

    Tries in order:
    1. Exact case-insensitive match on the customer field.
    2. Match on first_name + last_name parts (handles 'John Smith' vs stored parts).
    3. LIKE match: customer field contains the player name or vice versa.
    4. Name alias match: check customer_aliases for a matching name alias.
    5. Reversed name match: 'Last First' when player is 'First Last'.
    Returns the canonical customer name as stored in items, or None if no match.
    """
    # 1. Exact name match
    row = conn.execute(
        "SELECT DISTINCT customer FROM items WHERE customer = ? COLLATE NOCASE "
        "AND customer IS NOT NULL AND customer != '' LIMIT 1",
        (player_name,),
    ).fetchone()
    if row:
        return row["customer"]

    parts = player_name.strip().split()

    # 2. First + last name match using parsed name parts
    if len(parts) >= 2:
        first = parts[0].lower()
        last = parts[-1].lower()
        row = conn.execute(
            """SELECT DISTINCT customer FROM items
               WHERE LOWER(first_name) = ? AND LOWER(last_name) = ?
               AND customer IS NOT NULL AND customer != ''
               LIMIT 1""",
            (first, last),
        ).fetchone()
        if row:
            return row["customer"]

    # 3. LIKE match — player name contains within customer field or vice versa
    #    Handles suffixes like "Jr", "III", middle names, etc.
    if len(parts) >= 2:
        first = parts[0]
        last = parts[-1]
        # Customer might be "First Last Jr" while player is "First Last"
        row = conn.execute(
            """SELECT DISTINCT customer FROM items
               WHERE customer LIKE ? COLLATE NOCASE
               AND customer IS NOT NULL AND customer != ''
               LIMIT 1""",
            (f"{first}%{last}%",),
        ).fetchone()
        if row:
            return row["customer"]

        # Also try: customer is "First Last" but player is "First Middle Last"
        row = conn.execute(
            """SELECT DISTINCT customer FROM items
               WHERE customer LIKE ? COLLATE NOCASE
               AND customer IS NOT NULL AND customer != ''
               LIMIT 1""",
            (f"{first}%{last}",),
        ).fetchone()
        if row:
            return row["customer"]

    # 4. Name alias match
    row = conn.execute(
        """SELECT ca.customer_name FROM customer_aliases ca
           WHERE ca.alias_type = 'name' AND ca.alias_value = ? COLLATE NOCASE
           LIMIT 1""",
        (player_name,),
    ).fetchone()
    if row:
        return row["customer_name"]

    # 5. Reversed name: try "Last First" if player is "First Last"
    if len(parts) == 2:
        reversed_name = f"{parts[1]} {parts[0]}"
        row = conn.execute(
            "SELECT DISTINCT customer FROM items WHERE customer = ? COLLATE NOCASE "
            "AND customer IS NOT NULL AND customer != '' LIMIT 1",
            (reversed_name,),
        ).fetchone()
        if row:
            return row["customer"]

    # 6. Last-name-only match: if exactly one customer shares the same last name,
    #    assume it's the same person (handles nickname differences like Rob/Robert).
    if len(parts) >= 2:
        last = parts[-1]
        rows = conn.execute(
            """SELECT DISTINCT customer FROM items
               WHERE LOWER(last_name) = LOWER(?)
               AND customer IS NOT NULL AND customer != ''""",
            (last,),
        ).fetchall()
        if len(rows) == 1:
            return rows[0]["customer"]

    return None


def relink_all_unlinked_players(db_path: str | Path | None = None) -> dict:
    """Try to match every unlinked handicap player to a customer record.

    Runs _match_customer_name for all players in handicap_player_links where
    customer_name IS NULL. Useful after adding new customers or after the initial
    import when auto-linking may have failed.

    Returns {"linked": N, "still_unlinked": M, "total": T}
    """
    with _connect(db_path) as conn:
        unlinked = conn.execute(
            "SELECT player_name FROM handicap_player_links WHERE customer_name IS NULL"
        ).fetchall()

        linked = 0
        for row in unlinked:
            pname = row["player_name"]
            customer_name = _match_customer_name(conn, pname)
            if customer_name:
                cid = _lookup_customer_id(conn, customer_name, None)
                conn.execute(
                    "UPDATE handicap_player_links SET customer_name = ?, customer_id = ? WHERE player_name = ?",
                    (customer_name, cid, pname),
                )
                linked += 1

        still_unlinked = conn.execute(
            "SELECT COUNT(*) FROM handicap_player_links WHERE customer_name IS NULL"
        ).fetchone()[0]
        total = conn.execute(
            "SELECT COUNT(*) FROM handicap_player_links"
        ).fetchone()[0]

    return {"linked": linked, "still_unlinked": still_unlinked, "total": total}


def import_handicap_rounds(rounds: list[dict],
                            db_path: str | Path | None = None) -> dict:
    """Upsert handicap rounds from a Golf Genius / Handicap Server export.

    Each dict should contain:
      player_name (str), round_date (str YYYY-MM-DD), round_id (str|None),
      course_name (str|None), tee_name (str|None),
      adjusted_score (int|str), rating (float|str), slope (int|str),
      differential (float|str|None) — used as-is when provided, else computed.
      player_email (str|None) — optional; when provided, used as first-priority
      method to link the player to a customer record via customer_email.

    Names in 'Last, First' format are normalised to 'First Last' Title Case.
    Dedup key: (player_name, round_date, round_id) when round_id present;
               (player_name, round_date, course_name, tee_name) otherwise.

    Returns {"inserted": N, "skipped": M, "matched": N, "errors": [...]}
    where "matched" is the number of players linked to an existing customer.
    """
    inserted = 0
    skipped = 0
    errors = []
    matched = 0
    # Track which player_names we've already attempted to link this import
    _linked: set[str] = set()

    with _connect(db_path) as conn:
        for i, r in enumerate(rounds):
            try:
                raw_name = (r.get("player_name") or "").strip()
                if not raw_name:
                    errors.append(f"Row {i+1}: missing player_name")
                    continue
                player_name = _normalize_player_name(raw_name)

                # Try to link to a customer (once per unique player_name per import)
                player_email = (r.get("player_email") or "").strip().lower() or None
                if player_name not in _linked:
                    _linked.add(player_name)
                    existing = conn.execute(
                        "SELECT customer_name FROM handicap_player_links WHERE player_name = ?",
                        (player_name,),
                    ).fetchone()
                    # Re-attempt linking if player exists but has no customer_name yet
                    if existing is None:
                        # Try email-based match first (highest confidence)
                        customer_name = None
                        if player_email:
                            customer_name = _match_customer_by_email(conn, player_email, player_name)
                        if not customer_name:
                            customer_name = _match_customer_name(conn, player_name)
                        cid = _lookup_customer_id(conn, customer_name, player_email) if customer_name else None
                        conn.execute(
                            """INSERT INTO handicap_player_links (player_name, customer_name, customer_id)
                               VALUES (?, ?, ?)
                               ON CONFLICT(player_name) DO NOTHING""",
                            (player_name, customer_name, cid),
                        )
                        if customer_name:
                            matched += 1
                    elif not existing["customer_name"]:
                        customer_name = None
                        if player_email:
                            customer_name = _match_customer_by_email(conn, player_email, player_name)
                        if not customer_name:
                            customer_name = _match_customer_name(conn, player_name)
                        if customer_name:
                            cid = _lookup_customer_id(conn, customer_name, player_email)
                            conn.execute(
                                "UPDATE handicap_player_links SET customer_name = ?, customer_id = ? WHERE player_name = ?",
                                (customer_name, cid, player_name),
                            )
                            matched += 1

                round_date = (r.get("round_date") or "").strip()
                if not round_date:
                    errors.append(f"Row {i+1}: missing round_date")
                    continue

                round_id = (r.get("round_id") or "").strip() or None
                course_name = (r.get("course_name") or "").strip() or None
                tee_name = (r.get("tee_name") or "").strip() or None

                adjusted_score = int(float(str(r["adjusted_score"]).strip()))
                rating = float(str(r["rating"]).strip())
                slope = int(float(str(r["slope"]).strip()))

                # Reject 18-hole rounds (9-hole course ratings are ~30–42;
                # 18-hole ratings are ~60–80).
                if rating > 50:
                    errors.append(
                        f"Row {i+1}: course rating {rating} looks like an 18-hole "
                        f"rating (9-hole ratings are typically 30–42). Only 9-hole "
                        f"rounds are supported — please split into two 9-hole scores."
                    )
                    continue

                # Use pre-calculated differential when available.
                # Per WHS Rule 5.2 ("nearest tenth"), every DIFF in the
                # system is stored at 1-decimal precision so the values
                # shown on the handicap card match what's averaged.
                raw_diff = r.get("differential")
                if raw_diff is not None and str(raw_diff).strip() not in ("", "None"):
                    differential = round(float(str(raw_diff).strip()), 1)
                else:
                    if slope == 0:
                        errors.append(f"Row {i+1}: slope is 0 (invalid)")
                        continue
                    differential = round((adjusted_score - rating) * 113.0 / slope, 1)

                # Dedup check
                if round_id:
                    # Include course_name so that multi-course events (e.g. VALLEY /
                    # HILLS / CREEKS on the same day) sharing one round_id aren't
                    # collapsed into a single round.
                    existing = conn.execute(
                        "SELECT id FROM handicap_rounds "
                        "WHERE player_name = ? AND round_date = ? AND round_id = ? "
                        "AND COALESCE(course_name,'') = COALESCE(?,'')",
                        (player_name, round_date, round_id, course_name),
                    ).fetchone()
                else:
                    existing = conn.execute(
                        "SELECT id FROM handicap_rounds "
                        "WHERE player_name = ? AND round_date = ? "
                        "AND COALESCE(course_name,'') = COALESCE(?,'') "
                        "AND COALESCE(tee_name,'') = COALESCE(?,'')",
                        (player_name, round_date, course_name, tee_name),
                    ).fetchone()

                if existing:
                    skipped += 1
                    continue

                conn.execute(
                    "INSERT INTO handicap_rounds "
                    "(player_name, round_date, round_id, course_name, tee_name, "
                    " adjusted_score, rating, slope, differential) "
                    "VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)",
                    (player_name, round_date, round_id, course_name, tee_name,
                     adjusted_score, rating, slope, differential),
                )
                inserted += 1
            except (KeyError, ValueError, TypeError) as e:
                errors.append(f"Row {i+1}: {e}")

        conn.commit()

    # Stamp the played side (front/back) onto any newly-inserted rounds that
    # can be resolved from a scorecard (Kerry 2026-07-19). Non-fatal.
    try:
        persist_handicap_round_nines(dry_run=False, db_path=db_path)
    except Exception:
        logger.exception("Non-fatal: persist_handicap_round_nines after import failed")

    return {"inserted": inserted, "skipped": skipped, "matched": matched, "errors": errors[:50]}


def _bridge_handicap_records(conn: sqlite3.Connection, srid: int, cid: int,
                             round_date: str, tee_id: int | None,
                             db_path: str | Path | None = None) -> int:
    """Bridge handicap records to a just-imported card by RECONCILIATION,
    not by date alone. The old date-only UPDATE let the first card of a
    multi-round day claim EVERY same-date record for the player (Comanche
    Trace CREEKS/HILLS/VALLEY all showed one card — Kerry 2026-07-14).

    Each nine of the card claims at most ONE unbridged record whose
    adjusted_score equals that nine's WHS-adjusted total. Fallback to the
    old behavior only in the provably-safe case: the player has no other
    card that date and exactly one unbridged record.
    """
    formulas = get_scoring_formulas(db_path=db_path)
    sp = _nine_totals_for_card(conn, srid, tee_id, formulas)
    pend = conn.execute(
        """SELECT id, adjusted_score FROM handicap_rounds
           WHERE scoring_round_id IS NULL AND customer_id = ?
             AND round_date = ? ORDER BY id""",
        (cid, round_date)).fetchall()
    claimed: set = set()
    n = 0
    for side in ("front", "back"):
        if not sp[side]["n"]:
            continue
        for p in pend:
            if p["id"] not in claimed and p["adjusted_score"] == sp[side]["adj"]:
                conn.execute(
                    "UPDATE handicap_rounds SET scoring_round_id = ? WHERE id = ?",
                    (srid, p["id"]))
                claimed.add(p["id"])
                n += 1
                break
    if n == 0 and len(pend) == 1:
        other_cards = conn.execute(
            """SELECT COUNT(*) AS c FROM scoring_rounds
               WHERE customer_id = ? AND round_date = ? AND id != ?""",
            (cid, round_date, srid)).fetchone()["c"]
        if other_cards == 0:
            conn.execute(
                "UPDATE handicap_rounds SET scoring_round_id = ? WHERE id = ?",
                (srid, pend[0]["id"]))
            n = 1
    return n


def _repair_handicap_bridge_assignments(conn: sqlite3.Connection,
                                        db_path: str | Path | None = None) -> None:
    """Boot repair (idempotent): re-assign handicap↔scorecard bridges on
    days where the old date-only bridger could mis-claim — a player with
    MULTIPLE cards on one date, or multiple records sharing one card.
    Every suspect day is re-derived from scratch: reset the day's bridges,
    then let each record claim the (card, nine) whose WHS-adjusted total
    equals its adjusted_score. Unmatched records stay NULL (rendered "—")
    rather than guessed. Legitimate 18-hole pairs re-bridge identically,
    so re-running is a no-op."""
    _ensure_scoring_tables(conn)
    suspects = set()
    for r in conn.execute(
            """SELECT customer_id AS cid, round_date AS d FROM scoring_rounds
               WHERE customer_id IS NOT NULL AND round_date IS NOT NULL
               GROUP BY customer_id, round_date HAVING COUNT(*) > 1"""):
        suspects.add((r["cid"], r["d"]))
    for r in conn.execute(
            """SELECT customer_id AS cid, round_date AS d FROM handicap_rounds
               WHERE scoring_round_id IS NOT NULL AND customer_id IS NOT NULL
               GROUP BY customer_id, round_date, scoring_round_id
               HAVING COUNT(*) > 1"""):
        suspects.add((r["cid"], r["d"]))
    # Days with an UNBRIDGED record but at least one card — resolvable,
    # not coverable (Kerry: "figure out what's accurate"). Covers the
    # 18-hole Composer-era records the workbook repair skipped.
    for r in conn.execute(
            """SELECT DISTINCT hr.customer_id AS cid, hr.round_date AS d
               FROM handicap_rounds hr
               JOIN scoring_rounds sr ON sr.customer_id = hr.customer_id
                                     AND sr.round_date = hr.round_date
               WHERE hr.scoring_round_id IS NULL
                 AND hr.customer_id IS NOT NULL"""):
        suspects.add((r["cid"], r["d"]))
    if not suspects:
        return
    formulas = get_scoring_formulas(db_path=db_path)
    fixed = corrected = unmatched = 0
    for cid, d in sorted(suspects):
        cards = conn.execute(
            "SELECT id, tee_id FROM scoring_rounds "
            "WHERE customer_id = ? AND round_date = ?", (cid, d)).fetchall()
        recs = conn.execute(
            "SELECT id, adjusted_score, scoring_round_id, rating, slope "
            "FROM handicap_rounds "
            "WHERE customer_id = ? AND round_date = ? ORDER BY id",
            (cid, d)).fetchall()
        if not cards or not recs:
            continue
        slots = []  # each nine of each card, claimable once
        for c in cards:
            sp = _nine_totals_for_card(conn, c["id"], c["tee_id"], formulas)
            for side in ("front", "back"):
                if sp[side]["n"]:
                    slots.append({"card": c["id"], "side": side,
                                  "adj": sp[side]["adj"],
                                  "gross": sp[side]["gross"]})
        taken: set = set()
        assigned: dict = {}
        # Pass 1: exact WHS-adjusted match.
        for rec in recs:
            assigned[rec["id"]] = None
            for i, s in enumerate(slots):
                if i not in taken and s["adj"] == rec["adjusted_score"]:
                    assigned[rec["id"]] = s["card"]
                    taken.add(i)
                    break
        # Pass 2: a record whose stored adjusted equals a nine's RAW gross
        # (while the WHS adjusted differs) is an uncapped import — correct
        # it to the WHS value (Kerry-ratified standard 2026-07-14) and
        # bridge, instead of leaving a dash. Unique matches only.
        for rec in recs:
            if assigned[rec["id"]] is not None:
                continue
            cand = [i for i, s in enumerate(slots)
                    if i not in taken and s["gross"] == rec["adjusted_score"]
                    and s["adj"] != s["gross"]]
            if len(cand) == 1:
                i = cand[0]
                s = slots[i]
                taken.add(i)
                assigned[rec["id"]] = s["card"]
                new_diff = (round((s["adj"] - rec["rating"]) * 113.0 / rec["slope"], 1)
                            if rec["slope"] else None)
                conn.execute(
                    "UPDATE handicap_rounds SET adjusted_score = ?, "
                    "differential = COALESCE(?, differential) WHERE id = ?",
                    (s["adj"], new_diff, rec["id"]))
                corrected += 1
                logger.info("Handicap bridge repair: record %s (%s) stored "
                            "raw gross %s — corrected to WHS adjusted %s",
                            rec["id"], d, rec["adjusted_score"], s["adj"])
        for rec in recs:
            new_srid = assigned[rec["id"]]
            if new_srid != rec["scoring_round_id"]:
                conn.execute(
                    "UPDATE handicap_rounds SET scoring_round_id = ? WHERE id = ?",
                    (new_srid, rec["id"]))
                fixed += 1
            if new_srid is None:
                unmatched += 1
    conn.commit()
    if fixed or corrected:
        logger.info("Handicap bridge repair: re-assigned %d record(s), "
                    "corrected %d uncapped adjusted score(s), across %d "
                    "suspect day(s); %d left unbridged (no reconciling "
                    "card nine — review)", fixed, corrected, len(suspects),
                    unmatched)


# Nine NAMES a course may use instead of generic Front/Back. A course whose
# name ends with one of these after a separator (| / -) is a NAMED-nine course
# (Comanche Creeks/Hills/Valley, Hyatt Hill Country Lakes/Oaks/Creeks) — it
# shows its nine's name and is NEVER labeled Front/Back. Any OTHER 9-hole round
# is a front/back of an 18-hole course (no true 9-hole courses on the schedule,
# Kerry 2026-07-18). Editable list — add a chapter's nine names here.
_NAMED_NINE_WORDS = {
    "oaks", "creeks", "hills", "valley", "lakes", "canyons",
}

# Facilities that have MULTIPLE 18-hole courses whose names happen to reuse a
# nine word. TPC San Antonio has two 18-hole courses — the Oaks Course and the
# Canyons Course — so "Oaks"/"Canyons" name the 18-hole COURSE, not a nine; a
# played side of them is a Front/Back like any other 18-hole course (Kerry
# 2026-07-19). Squaw Valley Golf Course is the same — two 18-hole courses,
# Lakes and Creeks (Kerry 2026-07-19). The nine word alone can't tell
# "TPC | Oaks" (a course) from "Hill Country | Oaks" (a nine), so we key off
# the facility.
_MULTI_COURSE_18_FACILITIES = ("tpc", "squaw")


def _course_names_its_nines(course_name) -> bool:
    """True when the course names its nines (nine name after a | / - separator),
    so it should show that NAME, not a generic Front/Back. Requiring a separator
    avoids matching a base course name like 'Cedar Creek'. A multi-18-course
    facility (TPC San Antonio) is excluded — its trailing name is a COURSE, not
    a nine, so its played side reads Front/Back."""
    s = str(course_name or "")
    m = re.search(r"[|/\-]\s*([A-Za-z]+)\s*$", s)
    if not (m and m.group(1).lower() in _NAMED_NINE_WORDS):
        return False
    if any(fac in s.lower() for fac in _MULTI_COURSE_18_FACILITIES):
        return False
    return True


def _nine_totals_for_card(conn: sqlite3.Connection, scoring_round_id: int,
                          tee_id: int | None, formulas: dict) -> dict:
    """Per-nine gross + WHS-adjusted totals for one scoring card. Used to
    resolve which nine of an 18-hole round a 9-hole handicap record
    represents (each nine posts as its own handicap round)."""
    holes = conn.execute(
        """SELECT sh.hole_number, sh.strokes, sh.strokes_received, cth.par
           FROM scoring_holes sh
           LEFT JOIN course_tee_holes cth
             ON cth.tee_id = ? AND cth.hole_number = sh.hole_number
           WHERE sh.scoring_round_id = ?""",
        (tee_id, scoring_round_id)).fetchall()
    out = {"front": {"gross": 0, "adj": 0, "n": 0},
           "back": {"gross": 0, "adj": 0, "n": 0}}
    for h in holes:
        if h["strokes"] is None:
            continue
        side = out["front"] if h["hole_number"] <= 9 else out["back"]
        side["n"] += 1
        side["gross"] += h["strokes"]
        side["adj"] += (compute_hole_derivations(
            h["par"], h["strokes"], h["strokes_received"] or 0,
            formulas)["adjusted_strokes"] if h["par"] is not None else h["strokes"])
    return out


def debug_dump_handicap_rounds(player_substr: str, date_substr: str | None = None,
                               db_path: str | Path | None = None) -> list[dict]:
    """READ-ONLY: dump handicap_rounds rows matching a player-name substring
    (and optional date substring) with the columns that drive the played-side
    resolution — so a blank side can be diagnosed against the scorecard."""
    with _connect(db_path) as conn:
        q = ("SELECT id, player_name, round_date, course_name, tee_name, "
             "adjusted_score, scoring_round_id, nine FROM handicap_rounds "
             "WHERE player_name LIKE ?")
        args = [f"%{player_substr}%"]
        if date_substr:
            q += " AND round_date LIKE ?"
            args.append(f"%{date_substr}%")
        q += " ORDER BY round_date DESC, id DESC"
        return [dict(r) for r in conn.execute(q, args).fetchall()]


def persist_handicap_round_nines(dry_run: bool = True,
                                 db_path: str | Path | None = None) -> dict:
    """RECORD the played side (front/back) onto handicap_rounds.nine so the
    Scores/Handicaps card reads a STORED value instead of re-deriving it live
    from each round's scorecard bridge every page load (Kerry 2026-07-19). A
    posting with no clean bridge otherwise shows a blank side even when a
    scorecard proving the nine exists.

    For every round whose nine is not yet stored and whose course does NOT name
    its nines, resolve front/back from the player's scorecard: the round's
    bridged card when present, else any scorecard for the same customer+date
    (matched by customer_id via handicap_player_links; name is last resort).
    Holes 1-9 = front, 10-18 = back; an 18-hole card is split by matching the
    posting's adjusted score to the nine's WHS-adjusted total. Idempotent —
    only fills NULL nines, never overwrites. Named-nine courses stay NULL
    (their nine lives in course_name). Never touches scores/differentials, so
    frozen results are unaffected.
    """
    from collections import defaultdict
    formulas = get_scoring_formulas(db_path=db_path)
    res = {"set_front": 0, "set_back": 0, "already_stored": 0,
           "skipped_named_nine": 0, "skipped_no_card": 0,
           "skipped_ambiguous": 0, "examples": []}
    with _connect(db_path) as conn:
        _ensure_scoring_tables(conn)
        try:
            conn.execute("ALTER TABLE handicap_rounds ADD COLUMN nine TEXT")
        except sqlite3.OperationalError:
            pass
        rows = conn.execute(
            "SELECT id, player_name, round_date, course_name, adjusted_score, "
            "scoring_round_id, nine FROM handicap_rounds").fetchall()
        cards = conn.execute(
            "SELECT sr.id, sr.player_name, sr.round_date, sr.tee_id, "
            "sr.customer_id, c.name AS course_name "
            "FROM scoring_rounds sr "
            "LEFT JOIN courses c ON c.course_id = sr.course_id").fetchall()
        cards_by_id = {c["id"]: c for c in cards}

        def _norm(n):
            # "LAST, First" (scorecards) and "First Last" (handicap postings)
            # collapse to the same key so an unlinked posting still matches.
            s = str(n or "").strip()
            if "," in s:
                last, _, first = s.partition(",")
                s = f"{first.strip()} {last.strip()}"
            return " ".join(s.lower().split())

        def _course_key(n):
            # Reduce a course name to its distinctive core so "The Quarry Golf
            # Club" and "The Quarry Golf Course (OLD) - Archived on 04-01-2025"
            # match. Used only for the date-tolerant fallback.
            s = str(n or "").lower()
            s = re.sub(r"\(old\).*$", " ", s)
            s = re.sub(r"archived on.*$", " ", s)
            s = re.sub(r"[|/].*$", " ", s)          # drop a nine/chapter suffix
            s = re.sub(r"\b(the|golf|club|course|country|resort|of|texas|at|"
                       r"conference|center|event|links|gc|spa)\b", " ", s)
            s = re.sub(r"[^a-z0-9]+", " ", s)
            return " ".join(s.split())

        def _days_apart(a, b):
            try:
                da = datetime.strptime(str(a)[:10], "%Y-%m-%d")
                db = datetime.strptime(str(b)[:10], "%Y-%m-%d")
                return abs((da - db).days)
            except (ValueError, TypeError):
                return 999

        # An unbridged posting is matched to a scorecard by customer_id (the one
        # true identity key) first, then by normalized name (handicap_rounds
        # store "First Last" while scorecards store "LAST, First"). Exact date
        # wins; if none, a same-course card within ±1 day is accepted — GG
        # sometimes stamps the handicap posting a day off the scorecard (e.g.
        # the s9.1 Quarry posting is 03-18 while the card is 03-17).
        cards_by_cust: dict = defaultdict(list)   # customer_id -> [cards]
        cards_by_norm: dict = defaultdict(list)   # normalized_name -> [cards]
        for c in cards:
            if c["customer_id"]:
                cards_by_cust[c["customer_id"]].append(c)
            cards_by_norm[_norm(c["player_name"])].append(c)
        hr_cust = {r["player_name"]: r["customer_id"] for r in conn.execute(
            "SELECT player_name, customer_id FROM handicap_player_links "
            "WHERE customer_id IS NOT NULL").fetchall()}
        sp_cache: dict = {}

        def _sides_for(card):
            key = card["id"]
            if key not in sp_cache:
                sp = _nine_totals_for_card(conn, card["id"], card["tee_id"], formulas)
                sp_cache[key] = [(s, sp[s]["adj"]) for s in ("front", "back")
                                 if sp[s]["n"]]
            return sp_cache[key]

        updates = []
        for r in rows:
            if r["nine"]:
                res["already_stored"] += 1
                continue
            if _course_names_its_nines(r["course_name"]):
                res["skipped_named_nine"] += 1
                continue
            cand = []
            if r["scoring_round_id"]:
                c = cards_by_id.get(r["scoring_round_id"])
                if c:
                    cand = [c]
            if not cand:
                pool = (cards_by_cust.get(hr_cust.get(r["player_name"]))
                        or cards_by_norm.get(_norm(r["player_name"])) or [])
                cand = [c for c in pool if c["round_date"] == r["round_date"]]
                if not cand:
                    rk = _course_key(r["course_name"])
                    cand = [c for c in pool
                            if _course_key(c["course_name"]) == rk
                            and _days_apart(c["round_date"], r["round_date"]) <= 1]
            options = []  # (side, adjusted_total)
            for c in cand:
                options.extend(_sides_for(c))
            if not options:
                res["skipped_no_card"] += 1
                continue
            # Prefer the nine whose adjusted total matches this posting; else
            # fall back only when every candidate agrees on the same side.
            by_adj = [s for (s, adj) in options if adj == r["adjusted_score"]]
            distinct_sides = {s for (s, _) in options}
            side = None
            if len(by_adj) == 1:
                side = by_adj[0]
            elif len(distinct_sides) == 1:
                side = next(iter(distinct_sides))
            if not side:
                res["skipped_ambiguous"] += 1
                continue
            updates.append((side, r["id"]))
            res["set_" + side] += 1
            if len(res["examples"]) < 25:
                res["examples"].append(
                    {"id": r["id"], "player": r["player_name"],
                     "date": r["round_date"], "course": r["course_name"],
                     "nine": side})
        if not dry_run and updates:
            conn.executemany(
                "UPDATE handicap_rounds SET nine = ? WHERE id = ?", updates)
            conn.commit()
        res["would_update" if dry_run else "updated"] = len(updates)
    return res


def get_handicap_rounds(player_name: str | None = None,
                         db_path: str | Path | None = None,
                         include_running_index: bool = True) -> list[dict]:
    """Return handicap rounds, optionally filtered to one player, newest first.

    When called with a player_name, each row is enriched with
    'running_index_9' — the handicap-after-this-round value — so the UI
    can render directly instead of recomputing O(N^2) in the browser.
    Pass include_running_index=False to skip the compute when the caller
    only needs the raw rows (e.g. build_handicap_card_data).
    """
    with _connect(db_path) as conn:
        # RAW gross rides along from the bridged scorecard (v2.90.0, Kerry:
        # "show the raw score and adjusted score columns"). Legacy rounds
        # with no scorecard bridge return gross=NULL and render as "—".
        # 18-hole cards are NULLed here and resolved below to the ONE NINE
        # this handicap row represents (v2.90.1, Kerry screenshot: Kissing
        # Tree showed GROSS 80 beside ADJ 41 and false-flagged as capped —
        # an 18-hole round posts as TWO 9-hole handicap records).
        _ensure_scoring_tables(conn)
        _sel = ("SELECT hr.*, "
                "CASE WHEN COALESCE(sr.holes_played, 9) > 9 THEN NULL "
                "     ELSE CAST(sr.gross AS INTEGER) END AS gross, "
                "sr.holes_played AS sr_holes, sr.tee_id AS sr_tee_id "
                "FROM handicap_rounds hr "
                "LEFT JOIN scoring_rounds sr ON sr.id = hr.scoring_round_id ")
        if player_name:
            round_rows = conn.execute(
                _sel + "WHERE hr.player_name = ? "
                "ORDER BY hr.round_date DESC, hr.id DESC",
                (player_name,),
            ).fetchall()
        else:
            round_rows = conn.execute(
                _sel + "ORDER BY hr.round_date DESC, hr.id DESC"
            ).fetchall()
        rounds = [dict(r) for r in round_rows]
        # Resolve each 18-hole bridge to its nine: compute per-nine gross +
        # WHS adjusted from the holes and match the row's adjusted_score.
        # Player-scoped calls only (the UI path) — the unscoped dump stays
        # cheap and simply shows no gross for 18-hole bridges.
        if player_name:
            need = [r for r in rounds if r.get("scoring_round_id")]
            if need:
                formulas = get_scoring_formulas(db_path=db_path)
                # Resolve per CARD, not per row: when both nines of an
                # 18-hole round have the SAME adjusted total (Flying L
                # 5/30: 41 out / 41 in — Kerry screenshot) a per-row
                # unique-match test fails for both records. Records
                # sharing a card claim nines together, in id order,
                # front first — a tie assigns cleanly instead of
                # dashing out. 9-hole cards (v2.91.0, Kerry) simply
                # report the nine that was PLAYED (hole numbers are
                # physical: a back-nine event carries holes 10-18).
                by_srid: dict = {}
                for r in need:
                    by_srid.setdefault(r["scoring_round_id"], []).append(r)
                for srid, group in by_srid.items():
                    sp = _nine_totals_for_card(
                        conn, srid, group[0].get("sr_tee_id"), formulas)
                    sides = [s for s in ("front", "back") if sp[s]["n"]]
                    if (group[0].get("sr_holes") or 0) <= 9:
                        # Label the played side (Front = holes 1-9, Back = 10-18)
                        # on every course EXCEPT one that NAMES its nines
                        # (Comanche Creeks/Hills/Valley, Hyatt Hill Country
                        # Lakes/Oaks/Creeks) — those already carry the nine's
                        # NAME in course_name and must never read "Front/Back".
                        # TPC San Antonio's Oaks/Canyons are 18-hole COURSES, not
                        # nines, so they DO read Front/Back. No true
                        # 9-hole courses are on the schedule, so any other 9-hole
                        # round is a front/back of an 18-hole course (Kerry
                        # 2026-07-18; supersedes the tee-hole-count guard, which
                        # wrongly skipped 18-hole courses only ever played as one
                        # nine — Silverhorn, The Quarry, Canyon Springs).
                        played_side = ("back" if sides == ["back"]
                                       else "front" if sides == ["front"]
                                       else None)
                        if played_side and not _course_names_its_nines(
                                group[0].get("course_name")):
                            for r in group:
                                r["nine"] = played_side
                        continue
                    claimed: set = set()
                    for r in sorted(group, key=lambda x: x["id"]):
                        cands = [s for s in sides
                                 if s not in claimed
                                 and sp[s]["adj"] == r["adjusted_score"]]
                        if cands:
                            claimed.add(cands[0])
                            r["gross"] = sp[cands[0]]["gross"]
                            r["nine"] = cands[0]
        for r in rounds:
            # card_holes lets the client distinguish a record backed by an
            # 18-hole card (which-nine note + slicing on expand) from a
            # 9-hole event round that merely carries a Front/Back label
            # (v2.92.1 — the note wrongly fired on 9-hole rounds too).
            r["card_holes"] = r.pop("sr_holes", None)
            r.pop("sr_tee_id", None)
            # A cap can only LOWER a score — adjusted above the card's
            # gross means the bridge is wrong (multi-round-day mis-claim);
            # never display an impossible pairing.
            if (r.get("gross") is not None and r.get("adjusted_score") is not None
                    and r["adjusted_score"] > r["gross"]):
                r["gross"] = None
                r.pop("nine", None)
        # Attach the admin-editable short name from the course DB (v2.57.0):
        # exact-name match wins; unmatched course names fall back to the
        # client-side derivation. Case-insensitive, one lookup per call.
        if rounds:
            short_by_name = {
                r["name"].strip().lower(): r["short_name"]
                for r in conn.execute(
                    "SELECT name, short_name FROM courses WHERE short_name IS NOT NULL"
                ).fetchall()
            }
            for r in rounds:
                key = (r.get("course_name") or "").strip().lower()
                r["course_short"] = short_by_name.get(key)
        if include_running_index and player_name and rounds:
            cfg = dict(_HANDICAP_SETTINGS_DEFAULTS)
            for row in conn.execute(
                "SELECT key, value FROM handicap_settings"
            ).fetchall():
                cfg[row["key"]] = row["value"]
            _attach_running_index_9(rounds, cfg)
        return rounds


def delete_handicap_round(round_id: int,
                           db_path: str | Path | None = None) -> bool:
    """Delete a single handicap round row by primary key. Returns True if deleted."""
    with _connect(db_path) as conn:
        rows_affected = conn.execute(
            "DELETE FROM handicap_rounds WHERE id = ?", (round_id,)
        ).rowcount
        conn.commit()
        return rows_affected > 0


def delete_all_handicap_rounds_for_player(player_name: str,
                                           db_path: str | Path | None = None) -> int:
    """Delete all handicap rounds for a player. Returns count deleted."""
    with _connect(db_path) as conn:
        rows_affected = conn.execute(
            "DELETE FROM handicap_rounds WHERE player_name = ?", (player_name,)
        ).rowcount
        conn.commit()
        return rows_affected


def get_handicap_export_data(chapter: str | None = None,
                             test_player_email: str | None = None,
                             db_path: str | Path | None = None) -> dict:
    """Return handicap data formatted for Golf Genius CSV export.

    Joins handicap players → handicap_player_links → items to get
    email address and chapter for each linked player.

    The 9-hole TGF handicap index is multiplied by 2 to produce the
    18-hole equivalent that Golf Genius stores and displays.

    Args:
        chapter: If given (e.g. "San Antonio" or "Austin"), filters to that chapter only.
        test_player_email: If given, returns only the single matching player — for
                           test runs before committing to a full league sync.

    Returns:
        {
          "rows": [{"email": ..., "player_name": ...,
                    "handicap_index_9": float,   # raw 9-hole index
                    "handicap_index": float,      # ×2 for GG (18-hole)
                    "chapter": ...}],
          "no_email": [player_name, ...],   # have an index but no linked email
          "no_index": [player_name, ...],   # linked but N/A index
          "chapter": chapter or "All",
        }
    """
    players = get_all_handicap_players(db_path)
    player_map = {p["player_name"]: p for p in players}

    with _connect(db_path) as conn:
        links = conn.execute(
            """SELECT l.player_name, l.customer_name,
                      COALESCE(
                        -- Canonical first (v2.16.26): the customer profile's
                        -- designated Golf Genius email, then primary email,
                        -- then any profile email — via the link's customer_id.
                        -- Golf Genius matches league members BY EMAIL, and the
                        -- legacy latest-transaction snapshot below could be a
                        -- guest-purchase blank, a buyer's context, or an old
                        -- typo; it remains only as fallback for unlinked rows.
                        (SELECT LOWER(TRIM(ce.email)) FROM customer_emails ce
                         WHERE ce.customer_id = l.customer_id
                           AND ce.email IS NOT NULL AND TRIM(ce.email) != ''
                         ORDER BY ce.is_golf_genius DESC, ce.is_primary DESC,
                                  ce.email_id ASC
                         LIMIT 1),
                        (SELECT LOWER(TRIM(i1.customer_email)) FROM items i1
                         WHERE LOWER(i1.customer) = LOWER(l.customer_name)
                           AND i1.customer_email IS NOT NULL AND TRIM(i1.customer_email) != ''
                         ORDER BY i1.id DESC LIMIT 1),
                        (SELECT LOWER(TRIM(ca.alias_value)) FROM customer_aliases ca
                         WHERE LOWER(ca.customer_name) = LOWER(l.customer_name)
                           AND ca.alias_type = 'email'
                         LIMIT 1),
                        ''
                      ) AS customer_email,
                      COALESCE(
                        (SELECT i2.chapter FROM items i2
                         WHERE LOWER(i2.customer) = LOWER(l.customer_name)
                           AND i2.chapter IS NOT NULL AND TRIM(i2.chapter) != ''
                         ORDER BY i2.id DESC LIMIT 1),
                        ''
                      ) AS chapter,
                      COALESCE(
                        (SELECT i3.last_name FROM items i3
                         WHERE LOWER(i3.customer) = LOWER(l.customer_name)
                           AND i3.last_name IS NOT NULL AND TRIM(i3.last_name) != ''
                         ORDER BY i3.id DESC LIMIT 1),
                        ''
                      ) AS last_name,
                      COALESCE(
                        (SELECT i4.first_name FROM items i4
                         WHERE LOWER(i4.customer) = LOWER(l.customer_name)
                           AND i4.first_name IS NOT NULL AND TRIM(i4.first_name) != ''
                         ORDER BY i4.id DESC LIMIT 1),
                        ''
                      ) AS first_name,
                      COALESCE(
                        (SELECT i5.suffix FROM items i5
                         WHERE LOWER(i5.customer) = LOWER(l.customer_name)
                           AND i5.suffix IS NOT NULL AND TRIM(i5.suffix) != ''
                         ORDER BY i5.id DESC LIMIT 1),
                        ''
                      ) AS suffix
               FROM handicap_player_links l
               WHERE l.customer_name IS NOT NULL""",
        ).fetchall()

        # Also collect ALL chapters per customer for multi-chapter players
        all_chapters = conn.execute(
            """SELECT DISTINCT LOWER(l.customer_name) AS cname_lower,
                      i.chapter
               FROM handicap_player_links l
               JOIN items i ON LOWER(i.customer) = LOWER(l.customer_name)
               WHERE l.customer_name IS NOT NULL
                 AND i.chapter IS NOT NULL AND TRIM(i.chapter) != ''""",
        ).fetchall()

    # Build set of chapters per customer name (lowercase)
    customer_chapters: dict[str, set[str]] = {}
    for row in all_chapters:
        customer_chapters.setdefault(row["cname_lower"], set()).add(
            row["chapter"].lower()
        )

    # Build a map: player_name → (email, chapter, all_chapters) from best linked record
    link_map: dict[str, dict] = {}
    for lnk in links:
        pname = lnk["player_name"]
        if pname not in link_map:
            cname_lower = (lnk["customer_name"] or "").strip().lower()
            link_map[pname] = {
                "email": (lnk["customer_email"] or "").strip().lower(),
                "chapter": lnk["chapter"] or "",
                "all_chapters": customer_chapters.get(cname_lower, set()),
                "last_name": (lnk["last_name"] or "").strip(),
                "first_name": (lnk["first_name"] or "").strip(),
                "suffix": (lnk["suffix"] or "").strip(),
                "customer_name": cname_lower,
            }

    # Check if ANY linked player has chapter data; if not, skip chapter filtering
    has_chapter_data = any(v["chapter"] for v in link_map.values())

    rows = []
    no_email = []
    no_index = []
    excluded = []

    # First pass: collect every eligible (pname, p) candidate keyed by email.
    # Multiple handicap_rounds player_name variants can link to the same customer
    # (e.g. legacy un-normalized names alongside the current "First Last" form).
    # Iterating player_map directly and skipping by first-seen email would let
    # the alphabetically-first variant win — which is often a stale record with
    # an old index. Group, then pick the freshest per email.
    candidates_by_email: dict[str, list[tuple[str, dict]]] = {}
    for pname, p in player_map.items():
        info = link_map.get(pname)
        # Admin-removed from Golf Genius (see _GG_SYNC_EXCLUDES): never
        # export — the nightly sync would silently re-add them to GG.
        if pname.strip().lower() in _GG_SYNC_EXCLUDES or \
                (info and info.get("customer_name") in _GG_SYNC_EXCLUDES):
            excluded.append(pname)
            continue
        if info is None:
            if p["handicap_index"] is not None:
                no_email.append(pname)
            continue

        if chapter and has_chapter_data:
            if chapter.lower() not in info["all_chapters"]:
                continue

        if p["handicap_index"] is None:
            no_index.append(pname)
            continue

        email = info["email"]
        if not email:
            if p["handicap_index"] is not None:
                no_email.append(pname)
            continue

        if test_player_email and email != test_player_email.strip().lower():
            continue

        candidates_by_email.setdefault(email, []).append((pname, p))

    # Pick the freshest record per email. Tiebreakers: more active rounds,
    # then more total rounds, then the player_name (deterministic).
    def _freshness_key(item: tuple[str, dict]) -> tuple:
        pname, p = item
        return (
            p.get("latest_round_date") or "",
            p.get("active_rounds") or 0,
            p.get("total_rounds") or 0,
            pname,
        )

    duplicate_emails: list[dict] = []
    for email, group in candidates_by_email.items():
        if len(group) > 1:
            ordered = sorted(group, key=_freshness_key, reverse=True)
            duplicate_emails.append({
                "email": email,
                "chosen": ordered[0][0],
                "chosen_index_9": ordered[0][1].get("handicap_index"),
                "chosen_latest": ordered[0][1].get("latest_round_date"),
                "dropped": [
                    {"player_name": pn,
                     "handicap_index_9": pp.get("handicap_index"),
                     "latest_round_date": pp.get("latest_round_date"),
                     "active_rounds": pp.get("active_rounds")}
                    for pn, pp in ordered[1:]
                ],
            })
            chosen = ordered[0]
        else:
            chosen = group[0]

        pname, p = chosen
        info = link_map[pname]

        # GG stores 18-hole indexes; our index is 9-hole → multiply by 2
        idx_9 = p["handicap_index"]
        idx_18 = round(idx_9 * 2, 1)

        rows.append({
            "email": email,
            "player_name": pname,
            "handicap_index_9": idx_9,   # kept for reference / display
            "handicap_index": idx_18,    # value written to CSV / sent to GG
            "chapter": info["chapter"],
            "last_name": info["last_name"],
            "first_name": info["first_name"],
            "suffix": info["suffix"],
        })

    # Sort by player name
    rows.sort(key=lambda r: (r["last_name"].lower(), r["first_name"].lower()))

    return {
        "rows": rows,
        "no_email": sorted(no_email),
        "no_index": sorted(no_index),
        "excluded": sorted(excluded),  # admin-removed from GG, never exported
        "chapter": chapter or "All",
        "_debug": {
            "total_players": len(player_map),
            "total_linked": len(link_map),
            "has_chapter_data": has_chapter_data,
            "chapter_filter": chapter,
            "duplicate_emails": duplicate_emails,
            "link_sample": [
                {"player": k, "email": v["email"][:3] + "..." if v["email"] else None,
                 "chapter": v["chapter"]}
                for k, v in list(link_map.items())[:10]
            ],
        },
    }


def derive_course_short_name(name: str) -> str:
    """Mobile-friendly course name (v2.56.4, Kerry): drop the venue
    boilerplate — "Golf Club", "The Club at", "Resort", "Hyatt", etc.
    "The Quarry Golf Club" -> "The Quarry"; "The Club at Comanche Trace
    - CREEKS" -> "Comanche Trace - CREEKS". Never returns empty."""
    s = str(name or "").strip()
    out = re.sub(r"^\s*(the\s+)?(club|course)\s+at\s+", "", s, flags=re.I)
    out = re.sub(r"^\s*hyatt\s+(regency\s+)?", "", out, flags=re.I)
    for _ in range(2):  # "X Golf Club Resort" needs two trailing passes
        out = re.sub(
            r"\s+(golf\s+(club|course|resort|links)|country\s+club"
            r"|golf\s*&\s*country\s+club|resort(\s*&\s*spa)?|ranch\s+resort"
            r"|golf|club)\s*$",
            "", out, flags=re.I)
    out = out.strip(" -|\u2013\u2014").strip()
    return out or s


def set_starting_handicap(customer_id: int, index_18: float | None,
                          set_by: str | None = None, note: str | None = None,
                          db_path: str | Path | None = None) -> dict:
    """Stamp (or clear, with index_18=None) a placeholder handicap.

    Stands in for a guest / first timer who has no TGF rounds yet, so they
    can be flighted and shown on a roster instead of reading "—". It is NOT
    a handicap round: no differential, never feeds the index calculation,
    and the moment real rounds establish a computed index that index wins.
    The value stays on the record afterwards as history.

    `index_18` is the 18-HOLE TGF handicap — the number TGF quotes and the
    roster displays. Stored as given; the 9-hole equivalent is half of it.
    """
    if index_18 is not None:
        try:
            index_18 = round(float(index_18), 1)
        except (TypeError, ValueError):
            return {"error": "starting handicap must be a number"}
        # Wide enough for a plus handicap and a genuine beginner, tight
        # enough to catch a 9-hole number typed into an 18-hole field only
        # by accident of magnitude — so it is a sanity bound, not a rule.
        if not (-10.0 <= index_18 <= 60.0):
            return {"error": f"starting handicap {index_18} is out of range "
                             f"(-10 to 60, on the 18-hole scale)"}
    with _connect(db_path) as conn:
        row = conn.execute(
            "SELECT TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS customer_name FROM customers WHERE customer_id = ?",
            (customer_id,)).fetchone()
        if not row:
            return {"error": f"customer {customer_id} not found"}
        conn.execute(
            """UPDATE customers SET starting_handicap_18 = ?,
                   starting_handicap_set_at = CASE WHEN ? IS NULL THEN NULL
                                                   ELSE datetime('now') END,
                   starting_handicap_set_by = ?, starting_handicap_note = ?
               WHERE customer_id = ?""",
            (index_18, index_18, set_by if index_18 is not None else None,
             note if index_18 is not None else None, customer_id))
        conn.commit()
    return {"customer_id": customer_id, "customer_name": row["customer_name"],
            "starting_handicap_18": index_18,
            "starting_handicap_9": round(index_18 / 2, 1)
            if index_18 is not None else None,
            "cleared": index_18 is None}


def set_referred_by(customer_id: int, referrer_customer_id: int | None,
                    db_path: str | Path | None = None) -> dict:
    """Record who brought a player in. Relationship only — never a fee.

    Referral FEES live in `referral_fees` and, per the ratified rules, arise
    only from a redeemed coupon (comped) or a payout receipt (paid). Writing
    a relationship here must never mint a liability, so nothing is inserted
    there.

    `acquisition_source` is deliberately NOT touched (Kerry 2026-07-30):
    "godaddy" and "referral" are not alternatives — they answer different
    questions, and a transaction can be both. The channel someone came
    through and the person who brought them are independent facts, so who
    referred them lives here and nowhere else.
    """
    if referrer_customer_id is not None and referrer_customer_id == customer_id:
        return {"error": "a player cannot refer themselves"}
    _NAME = ("TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) "
             "AS customer_name")
    with _connect(db_path) as conn:
        row = conn.execute(f"SELECT {_NAME} FROM customers WHERE customer_id = ?",
                           (customer_id,)).fetchone()
        if not row:
            return {"error": f"customer {customer_id} not found"}
        ref_name = None
        if referrer_customer_id is not None:
            r = conn.execute(f"SELECT {_NAME} FROM customers WHERE customer_id = ?",
                             (referrer_customer_id,)).fetchone()
            if not r:
                return {"error": f"referrer {referrer_customer_id} not found"}
            ref_name = (r["customer_name"] or "").strip() or None
        conn.execute(
            """UPDATE customers
               SET referred_by_customer_id = ?,
                   referred_at = CASE WHEN ? IS NULL THEN NULL
                                      ELSE COALESCE(referred_at, datetime('now')) END
               WHERE customer_id = ?""",
            (referrer_customer_id, referrer_customer_id, customer_id))
        conn.commit()
    return {"customer_id": customer_id,
            "customer_name": (row["customer_name"] or "").strip(),
            "referred_by_customer_id": referrer_customer_id,
            "referred_by_name": ref_name,
            "cleared": referrer_customer_id is None}


def get_starting_handicaps(db_path: str | Path | None = None) -> dict:
    """{customer_id: {"index_18", "index_9", "set_at", "set_by", "note"}}."""
    with _connect(db_path) as conn:
        try:
            rows = conn.execute(
                """SELECT customer_id,
                          TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS customer_name,
                          starting_handicap_18,
                          starting_handicap_set_at, starting_handicap_set_by,
                          starting_handicap_note
                   FROM customers WHERE starting_handicap_18 IS NOT NULL"""
            ).fetchall()
        except sqlite3.OperationalError:
            return {}          # columns not migrated yet
    return {r["customer_id"]: {
        "customer_name": r["customer_name"],
        "index_18": r["starting_handicap_18"],
        "index_9": round(r["starting_handicap_18"] / 2, 1),
        "set_at": r["starting_handicap_set_at"],
        "set_by": r["starting_handicap_set_by"],
        "note": r["starting_handicap_note"]} for r in rows}


def get_all_handicap_players(db_path: str | Path | None = None) -> list[dict]:
    """Return one record per player with current handicap index and round stats.

    Only rounds within the lookback_months window count toward the index.
    """
    cfg = get_handicap_settings(db_path)
    lookback_months = int(cfg.get("lookback_months", 12))

    # Cutoff date: today minus lookback_months
    cutoff = datetime.now() - timedelta(days=lookback_months * 30.44)
    cutoff_str = cutoff.strftime("%Y-%m-%d")

    with _connect(db_path) as conn:
        summary_rows = conn.execute(
            """
            SELECT r.player_name,
                   COUNT(*) AS total_rounds,
                   SUM(CASE WHEN r.round_date >= ? THEN 1 ELSE 0 END) AS active_rounds,
                   MAX(r.round_date) AS latest_round_date,
                   MIN(r.differential) AS best_differential,
                   AVG(r.differential) AS avg_differential,
                   l.customer_name,
                   c.chapter,
                   c.current_player_status AS player_status
            FROM handicap_rounds r
            LEFT JOIN handicap_player_links l ON l.player_name = r.player_name
            LEFT JOIN customers c ON c.customer_id = l.customer_id
            WHERE r.differential IS NOT NULL
            GROUP BY r.player_name
            ORDER BY r.player_name COLLATE NOCASE
            """,
            (cutoff_str,),
        ).fetchall()

        # Fetch last 20 differentials within the lookback window for each player
        all_diffs = conn.execute(
            """
            SELECT player_name, differential,
                   ROW_NUMBER() OVER (
                       PARTITION BY player_name
                       ORDER BY round_date DESC, id DESC
                   ) AS rn
            FROM handicap_rounds
            WHERE differential IS NOT NULL
              AND round_date >= ?
            """,
            (cutoff_str,),
        ).fetchall()

    player_diffs: dict[str, list[float]] = {}
    for d in all_diffs:
        if d["rn"] <= 20:
            player_diffs.setdefault(d["player_name"], []).append(d["differential"])

    players = []
    for row in summary_rows:
        name = row["player_name"]
        diffs = player_diffs.get(name, [])
        index = compute_handicap_index(diffs, cfg)
        # Trend (v2.56.1, design handoff contests-handicaps-071026 view 1a):
        # the index as it stood BEFORE the most recent round — negative
        # delta = improving. diffs are newest-first, so dropping [0]
        # reconstructs the prior pool.
        index_prev = compute_handicap_index(diffs[1:], cfg) if len(diffs) > 1 else None
        trend = (round(index - index_prev, 1)
                 if index is not None and index_prev is not None else None)
        # Suppress the trend mark for players idle 30+ days (Kerry 2026-07-17):
        # a trend arrow off stale rounds is misleading, so drop it once the
        # player hasn't posted a round in over a month.
        if trend is not None and row["latest_round_date"]:
            try:
                _last = datetime.strptime(
                    str(row["latest_round_date"])[:10], "%Y-%m-%d").date()
                if (today_central() - _last).days > 30:
                    trend = None
            except (ValueError, TypeError):
                pass
        players.append({
            "player_name": name,
            "customer_name": row["customer_name"],
            "chapter": row["chapter"],
            "player_status": row["player_status"],
            "handicap_index": index,
            "handicap_trend": trend,
            "handicap_index_18": round(index * 2, 1) if index is not None else None,
            "total_rounds": row["total_rounds"],
            "active_rounds": row["active_rounds"],
            "latest_round_date": row["latest_round_date"],
            "best_differential": round(row["best_differential"], 2) if row["best_differential"] is not None else None,
            "avg_differential": round(row["avg_differential"], 2) if row["avg_differential"] is not None else None,
        })

    # STARTING (placeholder) handicaps — Kerry 2026-07-30. A computed index
    # ALWAYS wins; the placeholder only fills a gap. Players who have a
    # placeholder and no rounds at all are appended so they stop reading "—"
    # on rosters and become flightable. `handicap_source` says which is
    # which, so nothing downstream can mistake a stand-in for a real index.
    starting = get_starting_handicaps(db_path)
    seen_cids = set()
    for p in players:
        p.setdefault("handicap_source",
                     "computed" if p.get("handicap_index") is not None else None)

    # Every player carries their customer_id, not just the placeholder-only
    # ones appended below. Callers that key on NAME alone (the events page's
    # handicap index map is the live example) cannot survive one person
    # being spelled two ways — guiding principle 6.
    by_name = {}
    with _connect(db_path) as conn:
        for r in conn.execute(
                """SELECT l.player_name, l.customer_id FROM
                   handicap_player_links l WHERE l.customer_id IS NOT NULL"""
        ).fetchall():
            by_name.setdefault((r["player_name"] or "").strip().lower(),
                               r["customer_id"])
    for p in players:
        if p.get("customer_id") is None:
            p["customer_id"] = by_name.get(
                (p.get("player_name") or "").strip().lower())

    if starting:
        for p in players:
            cid = by_name.get((p["player_name"] or "").strip().lower())
            if cid is None:
                for s_cid, s in starting.items():
                    if (s["customer_name"] or "").strip().lower() == \
                            (p["player_name"] or "").strip().lower():
                        cid = s_cid
                        break
            if cid is None or cid not in starting:
                continue
            seen_cids.add(cid)
            p["starting_handicap_18"] = starting[cid]["index_18"]
            if p.get("handicap_index") is None:
                p["handicap_index"] = starting[cid]["index_9"]
                p["handicap_index_18"] = starting[cid]["index_18"]
                p["handicap_source"] = "starting"
        for cid, s in starting.items():
            if cid in seen_cids:
                continue
            players.append({
                "player_name": s["customer_name"],
                "customer_name": s["customer_name"],
                "customer_id": cid,
                "chapter": None, "player_status": None,
                "handicap_index": s["index_9"],
                "handicap_index_18": s["index_18"],
                "starting_handicap_18": s["index_18"],
                "handicap_source": "starting",
                "handicap_trend": None,
                "total_rounds": 0, "active_rounds": 0,
                "latest_round_date": None,
                "best_differential": None, "avg_differential": None,
            })
    return players


def sweep_i2_multiplier_removal(db_path: str | Path | None = None) -> dict:
    """I-2 (READ-ONLY): impact of removing the ×0.96 'Bonus for Excellence'
    multiplier from the index formula. The 0.96 factor is the pre-2020 USGA
    rule; modern WHS averages the best differentials with NO 0.96. This sweep
    computes, for every handicap player, the current index (×0.96) vs the
    index WITHOUT it (×1.00), the delta, and whether the change crosses a
    whole-number 9-hole Playing Handicap line at reference tees.

    PH-crossing is course-dependent, so we report it at two reference slopes:
      - 113 (neutral: CH = index, PH = whs_round(index)) — the floor case;
      - 125 (a typical Texas 9-hole slope) — where the delta is amplified
        (CH change = delta × slope/113), so more players cross.
    Rating−par is taken as 0 at both references. A real home tee steeper than
    113 crosses at least as often as the 113 column. Changes NOTHING.
    Gates R1 (the multiplier apply) — decision package only.
    """
    from email_parser.handicap_calc import whs_round, course_handicap

    cfg = get_handicap_settings(db_path)
    lookback_months = int(cfg.get("lookback_months", 12))
    cutoff_str = (datetime.now()
                  - timedelta(days=lookback_months * 30.44)).strftime("%Y-%m-%d")
    cfg_96 = dict(cfg); cfg_96["multiplier"] = "0.96"
    cfg_no = dict(cfg); cfg_no["multiplier"] = "1.0"

    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT player_name, differential,
                      ROW_NUMBER() OVER (PARTITION BY player_name
                          ORDER BY round_date DESC, id DESC) AS rn
               FROM handicap_rounds
               WHERE differential IS NOT NULL AND round_date >= ?""",
            (cutoff_str,)).fetchall()
    diffs_by_player: dict[str, list[float]] = {}
    for r in rows:
        if r["rn"] <= 20:
            diffs_by_player.setdefault(r["player_name"], []).append(r["differential"])

    def _ph(index, slope):
        return whs_round(course_handicap(index, slope, 0.0, 0.0))

    players, cross113, cross125, both_none = [], 0, 0, 0
    max_delta = 0.0
    for name in sorted(diffs_by_player):
        diffs = diffs_by_player[name]
        i96 = compute_handicap_index(diffs, cfg_96)
        ino = compute_handicap_index(diffs, cfg_no)
        if i96 is None or ino is None:
            both_none += 1
            continue
        delta = round(ino - i96, 1)
        ph113_96, ph113_no = _ph(i96, 113), _ph(ino, 113)
        ph125_96, ph125_no = _ph(i96, 125), _ph(ino, 125)
        c113 = ph113_96 != ph113_no
        c125 = ph125_96 != ph125_no
        cross113 += int(c113)
        cross125 += int(c125)
        max_delta = max(max_delta, abs(delta))
        players.append({
            "player": name, "n_rounds": len(diffs),
            "index_0_96": i96, "index_no_96": ino, "delta": delta,
            "ph9_113": [ph113_96, ph113_no], "crosses_at_113": c113,
            "ph9_125": [ph125_96, ph125_no], "crosses_at_125": c125,
        })
    players.sort(key=lambda p: (-int(p["crosses_at_125"]), -abs(p["delta"])))
    return {
        "note": "READ-ONLY. Removing ×0.96 RAISES every index (0.96→1.00), "
                "more for higher handicaps. PH-crossing reported at slope 113 "
                "(floor) and 125 (typical); steeper home tees cross ≥ the 113 "
                "count. Gates R1.",
        "lookback_cutoff": cutoff_str,
        "players_evaluated": len(players),
        "players_insufficient_rounds": both_none,
        "max_abs_delta": round(max_delta, 1),
        "crossing_a_whole_PH_line_at_113": cross113,
        "crossing_a_whole_PH_line_at_125": cross125,
        "players": players,
    }


# ---------------------------------------------------------------------------
# Handicap Email Card — data assembly + HTML builder
# ---------------------------------------------------------------------------

def build_handicap_card_data(player_name: str,
                             db_path: str | Path | None = None) -> dict:
    """Assemble all data needed to render a TGF Handicap Card email.

    Returns a dict with player metadata, index values, annotated rounds
    (each marked USED or ACTIVE), and summary counts.
    """
    cfg = get_handicap_settings(db_path)
    lookback_months = int(cfg.get("lookback_months", 12))
    min_rounds = int(cfg.get("min_rounds", 3))

    cutoff = datetime.now() - timedelta(days=lookback_months * 30.44)
    cutoff_str = cutoff.strftime("%Y-%m-%d")

    # Get all rounds for this player
    all_rounds = get_handicap_rounds(
        player_name=player_name, db_path=db_path, include_running_index=False
    )

    # Filter to active rounds (within lookback window, with a differential)
    active_rounds = [
        r for r in all_rounds
        if r.get("differential") is not None and (r.get("round_date") or "") >= cutoff_str
    ]

    # Pool = most recent 20 active rounds (already sorted newest-first by get_handicap_rounds)
    pool = active_rounds[:20]

    # Compute index
    pool_diffs = [r["differential"] for r in pool]
    index_9 = compute_handicap_index(pool_diffs, cfg)
    index_18 = round(index_9 * 2, 1) if index_9 is not None else None

    # Determine which differentials are "USED" (lowest N per lookup table)
    multiplier = float(cfg.get("multiplier", 0.96))
    n = min(len(pool_diffs), 20)
    used_count = 0
    adjustment = 0.0
    if n >= min_rounds:
        n_clamped = max(n, 3)
        used_count = _HANDICAP_DIFF_LOOKUP.get(n_clamped, 8)
        adjustment = _HANDICAP_ADJUSTMENT.get(n_clamped, 0.0)

    # Mark rounds: sort by differential to find the N lowest, then restore date order
    if used_count > 0:
        indexed_pool = [(i, r["differential"]) for i, r in enumerate(pool)]
        indexed_pool.sort(key=lambda x: x[1])
        used_indices = {indexed_pool[j][0] for j in range(min(used_count, len(indexed_pool)))}
    else:
        used_indices = set()

    annotated_rounds = []
    for i, r in enumerate(pool):
        annotated_rounds.append({
            "round_date": r.get("round_date") or "",
            "course_name": r.get("course_name") or "",
            "tee_name": r.get("tee_name") or "",
            "adjusted_score": r.get("adjusted_score"),
            "rating": r.get("rating"),
            "slope": r.get("slope"),
            "differential": r.get("differential"),
            "status": "USED" if i in used_indices else "ACTIVE",
        })

    # Resolve player metadata via the canonical resolver helpers
    # (customers / customer_emails first; items.* only as last-resort fallback).
    email = ""
    chapter = ""
    first_name = ""
    last_name = ""
    with _connect(db_path) as conn:
        link = conn.execute(
            "SELECT customer_name FROM handicap_player_links WHERE player_name = ?",
            (player_name,),
        ).fetchone()
        if link and link["customer_name"]:
            cname = link["customer_name"]

            # Find the most recent items row for this name to seed the
            # resolvers with a customer_id (so they don't fall back to name match).
            seed_row = conn.execute(
                """SELECT customer, customer_id, customer_email, customer_phone,
                          chapter, first_name, last_name, user_status
                   FROM items
                   WHERE LOWER(customer) = LOWER(?)
                   ORDER BY id DESC LIMIT 1""",
                (cname,),
            ).fetchone()
            seed = dict(seed_row) if seed_row else {"customer": cname, "customer_id": None}

            email = resolve_player_email(seed, conn=conn)
            chapter = resolve_player_chapter(seed, conn=conn)
            name_parts = resolve_player_name(seed, conn=conn)
            first_name = name_parts.get("first_name", "")
            last_name = name_parts.get("last_name", "")

            # Last-resort: pick up an email alias if customers had nothing
            if not email:
                alias = conn.execute(
                    """SELECT alias_value FROM customer_aliases
                       WHERE LOWER(customer_name) = LOWER(?)
                         AND alias_type = 'email' LIMIT 1""",
                    (cname,),
                ).fetchone()
                if alias and alias["alias_value"]:
                    email = alias["alias_value"].strip().lower()

    # Gather calculation breakdown for display
    used_diffs = sorted([r["differential"] for r in annotated_rounds if r["status"] == "USED"])
    avg_used = sum(used_diffs) / len(used_diffs) if used_diffs else 0.0

    today_str = datetime.now().strftime("%Y-%m-%d")
    return {
        "player_name": player_name,
        "first_name": first_name,
        "last_name": last_name,
        "chapter": chapter,
        "email": email,
        "handicap_index_9": index_9,
        "handicap_index_18": index_18,
        "rounds": annotated_rounds,
        "rounds_used": used_count,
        "rounds_pool": len(pool),
        "generated_date": today_str,
        "lookback_months": lookback_months,
        "used_diffs": used_diffs,
        "avg_used": avg_used,
        "multiplier": multiplier,
        "adjustment": adjustment,
    }


def _fmt_handicap_display(index_9: float | None) -> str:
    """Format a 9-hole index for display: '+2.1N', '6.3N', or 'N/A'."""
    if index_9 is None:
        return "N/A"
    if index_9 < 0:
        return f"+{abs(index_9):.1f}N"
    return f"{index_9:.1f}N"


def build_handicap_card_html(card_data: dict) -> str:
    """Build a styled HTML email for a TGF Handicap Card.

    Uses only inline CSS and table-based layout for email client compatibility.
    """
    name = card_data["player_name"]
    first = card_data.get("first_name") or ""
    last = card_data.get("last_name") or ""
    display_name = f"{first} {last}".strip() if first or last else name
    chapter = card_data.get("chapter") or ""
    date_str = card_data.get("generated_date") or ""
    idx_9 = card_data.get("handicap_index_9")
    idx_18 = card_data.get("handicap_index_18")
    rounds = card_data.get("rounds") or []
    rounds_used = card_data.get("rounds_used", 0)
    rounds_pool = card_data.get("rounds_pool", 0)
    lookback = card_data.get("lookback_months", 12)

    idx_9_display = _fmt_handicap_display(idx_9)
    idx_18_display = f"{abs(idx_18):.1f}" if idx_18 is not None else "N/A"
    if idx_18 is not None and idx_18 < 0:
        idx_18_display = f"+{abs(idx_18):.1f}"

    idx_color = "#2563eb" if idx_9 is not None else "#94a3b8"

    # Build score history rows
    _font = "-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif"
    score_rows = ""
    for i, r in enumerate(rounds):
        diff_val = r.get("differential")
        diff_str = f"{diff_val:.1f}" if diff_val is not None else "—"
        is_used = r.get("status") == "USED"

        if is_used:
            bg = "#dcfce7"
            diff_style = f"font-weight:700; color:#166534; font-family:{_font};"
            status_html = '<span style="color:#16a34a; font-size:15px;">&#9733;</span>'
        else:
            bg = "#ffffff" if i % 2 == 0 else "#f8fafc"
            diff_style = f"color:#475569; font-family:{_font};"
            status_html = ""

        _td = f"padding:4px 8px; border-bottom:1px solid #f1f5f9; font-size:13px; font-family:{_font};"
        _nw = "white-space:nowrap;"
        score_rows += f"""<tr style="background-color:{bg};">
  <td style="{_td} {_nw}">{r.get('round_date', '')}</td>
  <td style="{_td}">{r.get('course_name', '')}</td>
  <td style="{_td} {_nw} text-align:center;">{r.get('tee_name', '')}</td>
  <td style="{_td} {_nw} text-align:center;">{r.get('adjusted_score', '')}</td>
  <td style="{_td} {_nw} text-align:center;">{r.get('rating', '')}</td>
  <td style="{_td} {_nw} text-align:center;">{r.get('slope', '')}</td>
  <td style="{_td} {_nw} text-align:center; {diff_style}">{diff_str}</td>
  <td style="{_td} {_nw} text-align:center;">{status_html}</td>
</tr>"""

    summary_text = ""
    calc_html = ""
    if idx_9 is not None:
        used_diffs = card_data.get("used_diffs") or []
        avg_used = card_data.get("avg_used", 0.0)
        multiplier = card_data.get("multiplier", 0.96)
        adjustment = card_data.get("adjustment", 0.0)

        summary_text = (
            f"Based on best {rounds_used} of {rounds_pool} round{'s' if rounds_pool != 1 else ''} "
            f"(last {lookback} months)"
        )

        # Compact calculation line \u2014 show the sum and divide explicitly so the
        # numbers reconcile with the visible DIFF column (sum of tenths \u00f7 N).
        sum_used = sum(used_diffs)
        after_mult = avg_used * multiplier
        adj_str = ""
        if adjustment != 0.0:
            sign = "+" if adjustment > 0 else "\u2013"
            adj_str = f" {sign} {abs(adjustment):.1f}"

        calc_html = (
            f'Sum of lowest {rounds_used}: {sum_used:.1f} &#247; {rounds_used} = '
            f'{avg_used:.2f} &#215; {multiplier} = '
            f'{after_mult:.2f}{adj_str} &#8594; <strong style="color:#64748b;">{idx_9_display}</strong>'
        )
    else:
        summary_text = f"Not enough rounds for a handicap index (minimum {card_data.get('min_rounds', 3)} required)"

    chapter_line = f'<div style="font-size:13px; color:#64748b; margin-top:2px;">{chapter}</div>' if chapter else ""

    _f = "Arial, Helvetica, sans-serif"
    _th = f"padding:5px 8px; font-size:11px; font-weight:600; color:#64748b; text-transform:uppercase; border-bottom:2px solid #e2e8f0; font-family:{_f};"

    html = f"""<html><head><meta http-equiv="Content-Type" content="text/html; charset=UTF-8"></head>
<body style="font-family:{_f};color:#333;margin:0;padding:0;background:#f1f5f9;">
<table cellpadding="0" cellspacing="0" border="0" width="100%" style="background:#f1f5f9;">
<tr><td align="center" style="padding:24px 8px;">
<table cellpadding="0" cellspacing="0" border="0" width="700" style="background:#ffffff;border:1px solid #e2e8f0;">

  <tr>
    <td style="background:#1e40af; padding:20px 24px;">
      <table cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr>
          <td style="vertical-align:middle; font-family:{_f};">
            <span style="font-size:28px; font-weight:800; color:#ffffff; letter-spacing:1px;">TGF</span><br>
            <span style="font-size:12px; color:#93c5fd;">The Golf Fellowship</span>
          </td>
          <td style="text-align:right; vertical-align:middle; font-size:14px; font-weight:600; color:#93c5fd; text-transform:uppercase; letter-spacing:1px; font-family:{_f};">
            Handicap Card
          </td>
        </tr>
      </table>
    </td>
  </tr>

  <tr>
    <td style="padding:24px;">
      <table cellpadding="0" cellspacing="0" border="0" width="100%">
        <tr>
          <td style="vertical-align:top; font-family:{_f};">
            <span style="font-size:22px; font-weight:700; color:#1e293b;">{display_name}</span><br>
            {('<span style="font-size:13px; color:#64748b;">' + chapter + '</span><br>') if chapter else ''}
            <span style="font-size:12px; color:#94a3b8;">As of {date_str}</span>
          </td>
          <td style="text-align:right; vertical-align:top; width:160px;">
            <table cellpadding="0" cellspacing="0" border="0" align="right" style="background:#f0f7ff; border:2px solid #bfdbfe;">
              <tr>
                <td style="padding:12px 20px; text-align:center; font-family:{_f};">
                  <span style="font-size:11px; color:#64748b; text-transform:uppercase; letter-spacing:1px;">9-Hole Index</span><br>
                  <span style="font-size:32px; font-weight:800; color:{idx_color};">{idx_9_display}</span><br>
                  <span style="font-size:12px; color:#64748b;">18-Hole: {idx_18_display}</span>
                </td>
              </tr>
            </table>
          </td>
        </tr>
      </table>
    </td>
  </tr>

  <tr>
    <td style="padding:0 24px 16px; font-family:{_f};">
      <hr style="border:none; border-top:1px solid #e2e8f0; margin:0 0 12px 0;">
      <span style="font-size:13px; color:#64748b;">{summary_text}</span><br>
      <span style="font-size:12px; color:#94a3b8;">{calc_html}</span>
    </td>
  </tr>

  <tr>
    <td style="padding:0 24px 24px;">
      <table cellpadding="0" cellspacing="0" border="0" width="100%" style="border-collapse:collapse; border:1px solid #e2e8f0;">
        <tr style="background:#f1f5f9;">
          <th style="{_th} text-align:left;">Date</th>
          <th style="{_th} text-align:left;">Course</th>
          <th style="{_th} text-align:center;">Tee</th>
          <th style="{_th} text-align:center;">Score</th>
          <th style="{_th} text-align:center;">Rating</th>
          <th style="{_th} text-align:center;">Slope</th>
          <th style="{_th} text-align:center;">Diff</th>
          <th style="{_th} text-align:center;">Status</th>
        </tr>
        {score_rows}
      </table>
    </td>
  </tr>

  <tr>
    <td style="background:#f8fafc; padding:16px 24px; border-top:1px solid #e2e8f0; font-family:{_f}; text-align:center; font-size:12px; color:#94a3b8;">
        <strong style="color:#64748b;">The Golf Fellowship</strong> &#8212; 9-Hole Handicap Index<br>
        <span style="font-size:11px;">This is not an official USGA handicap.
        Calculated per WHS rules for TGF league play.</span>
    </td>
  </tr>

</table>
</td></tr>
</table>
</body>
</html>"""
    return html


# ---------------------------------------------------------------------------
# Season Contest Enrollment
# ---------------------------------------------------------------------------

def enroll_season_contest(customer_name: str, contest_type: str,
                          chapter: str = "", season: str = "",
                          source_item_id: int | None = None,
                          manually_enrolled: bool = False,
                          db_path: str | Path | None = None) -> dict:
    """Enroll a customer in a season contest (NET Points Race, GROSS Points Race, City Match Play).

    Returns the enrollment dict. Idempotent — re-enrolling is a no-op.
    Set manually_enrolled=True for admin overrides (cash payments, etc.) so the
    reconciliation cleanup does not auto-remove the row.
    """
    with _connect(db_path) as conn:
        try:
            conn.execute(
                """INSERT INTO season_contests
                   (customer_name, contest_type, chapter, season, source_item_id, manually_enrolled)
                   VALUES (?, ?, ?, ?, ?, ?)""",
                (customer_name, contest_type, chapter or "", season or "",
                 source_item_id, 1 if manually_enrolled else 0),
            )
            conn.commit()
            logger.info("Enrolled %s in %s (%s/%s)", customer_name, contest_type, chapter, season)
        except sqlite3.IntegrityError:
            pass  # already enrolled
        row = conn.execute(
            "SELECT * FROM season_contests WHERE customer_name = ? AND contest_type = ? AND chapter = ? AND season = ?",
            (customer_name, contest_type, chapter or "", season or ""),
        ).fetchone()
        return dict(row) if row else {}


def get_season_contest_enrollments(contest_type: str | None = None,
                                    chapter: str | None = None,
                                    season: str | None = None,
                                    db_path: str | Path | None = None) -> list[dict]:
    """List season contest enrollments, optionally filtered."""
    clauses = []
    params = []
    if contest_type:
        clauses.append("contest_type = ?")
        params.append(contest_type)
    if chapter:
        clauses.append("chapter = ?")
        params.append(chapter)
    if season:
        clauses.append("season = ?")
        params.append(season)
    where = " AND ".join(clauses) if clauses else "1=1"
    with _connect(db_path) as conn:
        rows = conn.execute(
            f"SELECT * FROM season_contests WHERE {where} ORDER BY enrolled_at DESC", params
        ).fetchall()
        return [dict(r) for r in rows]


def get_customer_season_contests(customer_name: str,
                                  db_path: str | Path | None = None) -> list[dict]:
    """Get all season contest enrollments for a specific customer."""
    with _connect(db_path) as conn:
        rows = conn.execute(
            "SELECT * FROM season_contests WHERE customer_name = ? COLLATE NOCASE ORDER BY season, contest_type",
            (customer_name,),
        ).fetchall()
        return [dict(r) for r in rows]


def remove_season_contest_enrollment(enrollment_id: int,
                                     reason: str | None = None,
                                     refund_amount: float | None = None,
                                     refund_method: str | None = None,
                                     note: str | None = None,
                                     db_path: str | Path | None = None) -> dict | None:
    """Remove an enrollment AND record the removal in season_contest_removals.

    One transaction does all three steps so a removal can never half-apply:
      1. snapshot the enrollment into season_contest_removals (the permanent
         recordation the Enrollment tab lists at the bottom),
      2. clear the matching contest flag on the source purchase item so the
         next sync doesn't silently re-enroll the player,
      3. delete the enrollment row.

    Returns the removal record dict, or None if the enrollment id doesn't
    exist. removed_at is stamped in US/Central (user-facing business date).
    """
    flag_cols = {
        "NET Points Race": "net_points_race",
        "GROSS Points Race": "gross_points_race",
        "City Match Play": "city_match_play",
    }
    with _connect(db_path) as conn:
        row = conn.execute(
            "SELECT * FROM season_contests WHERE id = ?", (enrollment_id,)
        ).fetchone()
        if not row:
            return None
        row = dict(row)
        cur = conn.execute(
            """INSERT INTO season_contest_removals
               (customer_name, customer_id, contest_type, chapter, season,
                source_item_id, enrolled_at, removed_at, reason,
                refund_amount, refund_method, note)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (row["customer_name"], row.get("customer_id"), row["contest_type"],
             row.get("chapter"), row.get("season"), row.get("source_item_id"),
             row.get("enrolled_at"),
             now_central().strftime("%Y-%m-%d %H:%M:%S"),
             (reason or "").strip() or None,
             refund_amount,
             (refund_method or "").strip() or None,
             (note or "").strip() or None),
        )
        flag_col = flag_cols.get(row["contest_type"])
        if flag_col and row.get("source_item_id"):
            conn.execute(
                f"UPDATE items SET {flag_col} = NULL WHERE id = ?",
                (row["source_item_id"],),
            )
            logger.info(
                "Season contest unenroll: cleared %s on item %s (%s, %s)",
                flag_col, row["source_item_id"], row["customer_name"],
                row["contest_type"],
            )
        conn.execute("DELETE FROM season_contests WHERE id = ?", (enrollment_id,))
        conn.commit()
        removal = conn.execute(
            "SELECT * FROM season_contest_removals WHERE id = ?",
            (cur.lastrowid,),
        ).fetchone()
        logger.info(
            "Season contest removal recorded: %s / %s / %s (reason=%s, refund=%s %s)",
            row["customer_name"], row["contest_type"], row.get("season"),
            reason, refund_amount, refund_method,
        )
        return dict(removal) if removal else None


def get_season_contest_removals(contest_type: str | None = None,
                                chapter: str | None = None,
                                season: str | None = None,
                                db_path: str | Path | None = None) -> list[dict]:
    """List removal records (the Enrollment tab's recordation list)."""
    clauses = []
    params = []
    if contest_type:
        clauses.append("contest_type = ?")
        params.append(contest_type)
    if chapter:
        clauses.append("chapter = ?")
        params.append(chapter)
    if season:
        clauses.append("season = ?")
        params.append(season)
    where = " AND ".join(clauses) if clauses else "1=1"
    with _connect(db_path) as conn:
        rows = conn.execute(
            f"""SELECT * FROM season_contest_removals
                WHERE {where}
                ORDER BY removed_at DESC, id DESC""",
            params,
        ).fetchall()
        return [dict(r) for r in rows]


# Comp'd season-contest enrollments (admin-confirmed, 2026-07-03): the
# owner/managers play the races as a privilege of running them — no
# purchase exists, so the sync's reconcile would never create (and, if
# unprotected, would delete) these rows. cid + name pinned; INSERT OR
# IGNORE against UNIQUE(customer_name, contest_type, chapter, season).
_COMPED_CONTEST_ENROLLMENTS: tuple = (
    (18, "Kerry Niester", "NET Points Race", "San Antonio", "2026"),
    (18, "Kerry Niester", "GROSS Points Race", "San Antonio", "2026"),
)


def _seed_comped_contest_enrollments(conn: sqlite3.Connection) -> None:
    """Idempotently enroll comp'd owner/manager entries (manually_enrolled=1)."""
    for cid, name, contest, chapter, season in _COMPED_CONTEST_ENROLLMENTS:
        row = conn.execute(
            """SELECT 1 FROM customers
               WHERE customer_id = ?
                 AND LOWER(TRIM(first_name || ' ' || last_name)) = LOWER(?)""",
            (cid, name),
        ).fetchone()
        if not row:
            logger.warning(
                "Comped enrollment: cid %s is not %r — skipping", cid, name)
            continue
        cur = conn.execute(
            """INSERT OR IGNORE INTO season_contests
                   (customer_name, contest_type, chapter, season,
                    customer_id, manually_enrolled)
               VALUES (?, ?, ?, ?, ?, 1)""",
            (name, contest, chapter, season, cid),
        )
        if cur.rowcount:
            logger.info("Comped enrollment: %s -> %s (%s %s)",
                        name, contest, chapter, season)
    conn.commit()


def _seed_initial_contest_removals(conn: sqlite3.Connection) -> None:
    """Record the two pre-feature removals so the recordation list is complete.

    Neil Cheshire and Joseph Lourigan were refunded their 2026 City Match
    Play entries via Venmo (admin-confirmed, amounts/dates from Venmo
    records) and removed on the Enrollment tab BEFORE the removals table
    existed — so no record was written. removed_at carries the actual
    Venmo refund date, not the day this seed ran. Idempotent: a row that
    already carries a refund_amount is never touched again; a detail-less
    row from the first seed pass (v2.17.0 shipped before the amounts were
    known) gets the amount/date/note filled in once.
    """
    seeds = (
        ("Neil Cheshire", "City Match Play", "2026", 51.75, "2026-06-23",
         "Refund included transaction fees — Match Play had closed but was "
         "accidentally left open for purchase"),
        ("Joseph Lourigan", "City Match Play", "2026", 50.0, "2026-05-26",
         "Withdrew — wasn't able to play much; transaction fees not refunded"),
    )
    for name, contest, season, amount, refund_date, note in seeds:
        exists = conn.execute(
            """SELECT id, customer_id, refund_amount FROM season_contest_removals
               WHERE LOWER(customer_name) = LOWER(?)
                 AND contest_type = ? AND season = ?""",
            (name, contest, season),
        ).fetchone()
        if exists:
            # Row already seeded — but if it was written before the customer
            # profile was resolvable, link it now (identity key, Principle #6).
            if exists["customer_id"] is None:
                cid = _lookup_customer_id(conn, name, None)
                if cid:
                    conn.execute(
                        """UPDATE season_contest_removals
                           SET customer_id = ?,
                               chapter = COALESCE(chapter,
                                   (SELECT chapter FROM customers WHERE customer_id = ?))
                           WHERE id = ?""",
                        (cid, cid, exists["id"]),
                    )
                    logger.info(
                        "Removal seed: linked existing record for %s to cid %d",
                        name, cid,
                    )
            if exists["refund_amount"] is None:
                # First seed pass ran before the amounts were known — fill in
                # the Venmo details once.
                conn.execute(
                    """UPDATE season_contest_removals
                       SET refund_amount = ?, removed_at = ?, note = ?
                       WHERE id = ? AND refund_amount IS NULL""",
                    (amount, f"{refund_date} 00:00:00", note, exists["id"]),
                )
                logger.info(
                    "Removal seed: filled refund details for %s — $%.2f via Venmo on %s",
                    name, amount, refund_date,
                )
            continue
        enrolled = conn.execute(
            """SELECT 1 FROM season_contests
               WHERE LOWER(customer_name) = LOWER(?)
                 AND contest_type = ? AND season = ?""",
            (name, contest, season),
        ).fetchone()
        if enrolled:
            logger.info(
                "Removal seed: %s is currently enrolled in %s %s — not seeding",
                name, contest, season,
            )
            continue
        cid = _lookup_customer_id(conn, name, None)
        chapter = None
        if cid:
            ch = conn.execute(
                "SELECT chapter FROM customers WHERE customer_id = ?", (cid,)
            ).fetchone()
            chapter = (ch["chapter"] if ch else None) or None
        conn.execute(
            """INSERT INTO season_contest_removals
               (customer_name, customer_id, contest_type, chapter, season,
                removed_at, reason, refund_amount, refund_method, note)
               VALUES (?, ?, ?, ?, ?, ?, 'Refunded', ?, 'Venmo', ?)""",
            (name, cid, contest, chapter, season,
             f"{refund_date} 00:00:00", amount, note),
        )
        logger.info(
            "Removal seed: recorded %s / %s / %s ($%.2f Venmo refund %s, cid=%s)",
            name, contest, season, amount, refund_date, cid,
        )


def _repair_massey_shadow_alias(conn: sqlite3.Connection) -> None:
    """Delete the 'Will Massey' name alias from Colby Johnson's profile.

    The last shard of their old bad merge (which began with Colby paying
    for Will's first event — admin-confirmed 2026-07-02): the alias mapped
    Massey's NAME to Colby's profile, so any resolution path that reached
    the alias step could attribute Massey's activity to Colby. His emails
    and handicap link were decontaminated in v2.16.28/30; this removes the
    alias the identity audit surfaced. Idempotent.
    """
    rows = conn.execute(
        """SELECT ca.id FROM customer_aliases ca
           JOIN customers c ON c.customer_id = ca.customer_id
           WHERE ca.alias_type = 'name'
             AND LOWER(TRIM(ca.alias_value)) = 'will massey'
             AND LOWER(TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')))
                 = 'colby johnson'"""
    ).fetchall()
    for r in rows:
        conn.execute("DELETE FROM customer_aliases WHERE id = ?", (r["id"],))
        logger.info(
            "Massey shadow-alias repair: deleted 'Will Massey' name alias "
            "from Colby Johnson's profile"
        )


def _repair_reggie_johnson_profiles(conn: sqlite3.Connection,
                                    db_path: str | Path | None = None) -> None:
    """Merge the 'Reggie Johnson' shell into 'Reginald Johnson'.

    Same person (admin-confirmed 2026-07-02). The Reggie profile was an
    empty shell — no purchases, no email — carrying a 'Reginald Johnson'
    alias that shadowed the real profile's canonical name (surfaced by the
    identity audit). merge_customers moves anything it does hold and adds
    'Reggie Johnson' as an alias on the surviving profile. Idempotent.
    """
    def _one(name_lower: str):
        rows = conn.execute(
            """SELECT customer_id FROM customers
               WHERE LOWER(TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,''))) = ?
               LIMIT 2""",
            (name_lower,),
        ).fetchall()
        return rows[0]["customer_id"] if len(rows) == 1 else None

    src = _one("reggie johnson")
    tgt = _one("reginald johnson")
    if src is None or tgt is None or src == tgt:
        return
    conn.commit()  # merge_customers opens its own connection
    try:
        merge_customers("Reggie Johnson", "Reginald Johnson", db_path=db_path,
                        source_customer_id=src, target_customer_id=tgt)
        logger.info(
            "Reggie Johnson repair: merged shell cid %d -> cid %d (same person)",
            src, tgt,
        )
    except ValueError as e:
        logger.warning("Reggie Johnson repair failed: %s", e)


