def _repair_confirmed_profile_details(conn: sqlite3.Connection) -> None:
    """Fill admin-provided contact + membership details on known profiles.

    Steve Novosad and Matt Rose are former San Antonio members whose history
    predates the tracker (started 2026); Joe Garza played once as a guest.
    Their profiles existed with no contact info, which also left their
    Golf Genius decline RSVPs unlinked. Fills phone/venmo only when blank,
    adds emails (primary only when none exists), captures email aliases,
    inserts membership terms (UNIQUE(customer_id, started_at) makes it
    one-shot), and links any unlinked RSVP sent from one of the profile's
    emails. Pinned to (cid, exact name). Idempotent.
    """
    for (cid, expected_name, phone, venmo, primary,
         extras, name_aliases, terms) in _CONFIRMED_PROFILE_DETAILS:
        if cid is None:
            # Resolved by unique exact name (used when the cid wasn't known
            # at registry-authoring time). Refuses ambiguous names.
            matches = conn.execute(
                """SELECT customer_id FROM customers
                   WHERE LOWER(TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,''))) = ?
                   LIMIT 2""",
                (expected_name,),
            ).fetchall()
            if len(matches) != 1:
                logger.warning(
                    "Profile-details repair: %r matches %d profiles — skipping",
                    expected_name, len(matches),
                )
                continue
            cid = matches[0]["customer_id"]
        row = conn.execute(
            "SELECT customer_id, first_name, last_name, phone, venmo_username "
            "FROM customers WHERE customer_id = ?", (cid,),
        ).fetchone()
        if not row:
            continue
        actual = (f"{(row['first_name'] or '').strip()} "
                  f"{(row['last_name'] or '').strip()}").strip()
        if actual.lower() != expected_name:
            logger.warning(
                "Profile-details repair: cid %d is %r, expected %r — skipping",
                cid, actual, expected_name,
            )
            continue
        changed = 0
        if phone and not (row["phone"] or "").strip():
            conn.execute("UPDATE customers SET phone = ? WHERE customer_id = ?",
                         (phone, cid))
            changed += 1
        if venmo and not (row["venmo_username"] or "").strip():
            conn.execute(
                "UPDATE customers SET venmo_username = ? WHERE customer_id = ?",
                (venmo, cid))
            changed += 1
        has_primary = conn.execute(
            "SELECT 1 FROM customer_emails WHERE customer_id = ? AND is_primary = 1",
            (cid,),
        ).fetchone()
        for email, is_prim in ([(primary, 0 if has_primary else 1)] if primary else []) \
                + [(e, 0) for e in extras]:
            cur = conn.execute(
                "INSERT OR IGNORE INTO customer_emails (customer_id, email, is_primary, label) "
                "VALUES (?, ?, ?, 'admin')", (cid, email, is_prim))
            changed += cur.rowcount
            conn.execute(
                "INSERT OR IGNORE INTO customer_aliases "
                "(customer_name, alias_type, alias_value, customer_id) "
                "VALUES (?, 'email', ?, ?)", (actual, email, cid))
        for a in name_aliases:
            cur = conn.execute(
                "INSERT OR IGNORE INTO customer_aliases "
                "(customer_name, alias_type, alias_value, customer_id) "
                "VALUES (?, 'name', ?, ?)", (actual, a, cid))
            changed += cur.rowcount
        for start, end, price, note in terms:
            try:
                cur = conn.execute(
                    """INSERT OR IGNORE INTO customer_memberships
                       (customer_id, started_at, expires_at, source, price_paid, notes)
                       VALUES (?, ?, ?, 'manual', ?, ?)""",
                    (cid, start, end, price, note))
                changed += cur.rowcount
            except sqlite3.OperationalError:
                pass  # memberships table not created yet on this DB
        for email in ([primary] if primary else []) + list(extras):
            n = conn.execute(
                "UPDATE rsvps SET customer_id = ? "
                "WHERE customer_id IS NULL AND LOWER(TRIM(COALESCE(player_email,''))) = ?",
                (cid, email.lower()),
            ).rowcount
            if n:
                logger.info(
                    "Profile-details repair: linked %d RSVP(s) from %s to %s (cid %d)",
                    n, email, actual, cid,
                )
                changed += n
        if changed:
            logger.info(
                "Profile-details repair: %s (cid %d) — %d field(s)/row(s) filled",
                actual, cid, changed,
            )


def _repair_kirksey_profiles(conn: sqlite3.Connection,
                             db_path: str | Path | None = None) -> None:
    """Merge split Stu/Stuart Kirksey profiles into one.

    Same person (the original boot MERGE_PAIRS entry says so, keyed by his
    phone), but a second profile re-formed under the other spelling. The
    split actively broke his contest enrollment: his SEASON CONTESTS item
    carried one profile id while name-resolution put the enrollment's
    customer_id on the other, so the sync's reconciliation deleted the
    enrollment as "no backing purchase" on every run. Canonical = the
    profile holding the most items (tie: lowest id); merge_customers moves
    everything and adds the other spelling as an alias. Idempotent.
    """
    rows = conn.execute(
        """SELECT c.customer_id,
                  TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')) AS name,
                  (SELECT COUNT(*) FROM items i WHERE i.customer_id = c.customer_id) AS n_items
           FROM customers c
           WHERE LOWER(TRIM(c.last_name)) = 'kirksey'
             AND LOWER(TRIM(c.first_name)) IN ('stu', 'stuart')
           ORDER BY n_items DESC, c.customer_id ASC"""
    ).fetchall()
    if len(rows) < 2:
        return
    target = rows[0]
    conn.commit()  # merge_customers opens its own connection
    for src in rows[1:]:
        try:
            merge_customers(src["name"], target["name"], db_path=db_path,
                            source_customer_id=src["customer_id"],
                            target_customer_id=target["customer_id"])
            logger.info(
                "Kirksey profile repair: merged cid %d (%s) -> cid %d (%s)",
                src["customer_id"], src["name"],
                target["customer_id"], target["name"],
            )
        except ValueError as e:
            logger.warning(
                "Kirksey profile repair failed for cid %d: %s",
                src["customer_id"], e,
            )


def _repair_kirksey_season_contest_item(conn: sqlite3.Connection) -> None:
    """Assign order R747210347 to Stu Kirksey — and to a NAMED profile.

    A standalone SEASON CONTESTS purchase (City Match Play, 2026-05-25)
    parsed with a BLANK customer, so no enrollment was ever created and the
    Enrollment log showed a nameless row (purged in v2.16.28). The order
    email names the buyer: 'New order from: Stuart Kirksey'
    (stuart.kirksey@gmail.com) — admin-confirmed.

    Two failure shapes, both fixed here (idempotent):
    - item has no customer name → assign name + customer_id;
    - item has a name but its customer_id points at a NAMELESS shell
      profile (or dangles) → re-point to the real Kirksey profile, or name
      the shell if it's the only anchor. Without this, the sync's
      canonical-name normalization blanked his enrollment and the blank-row
      purge deleted it on every boot (seen live 2026-07-02).
    """
    # NB: an early boot migration rewrites blank items.customer to
    # '(Unknown)', so match that too — the row may be blank OR '(Unknown)'
    # depending on which migration ran first. LEFT JOIN so a dangling
    # customer_id (profile deleted) is visible as prof_exists NULL.
    row = conn.execute(
        """SELECT i.id, i.customer, i.customer_id,
                  c.customer_id AS prof_exists,
                  TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')) AS prof_name
           FROM items i
           LEFT JOIN customers c ON c.customer_id = i.customer_id
           WHERE i.order_id IN ('R747210347', '#R747210347')"""
    ).fetchone()
    if not row:
        return
    item_named = bool((row["customer"] or "").strip()) and row["customer"] != "(Unknown)"
    prof_name = (row["prof_name"] or "").strip()
    if item_named and row["prof_exists"] is not None and prof_name:
        return  # healthy: named item pointing at a real, NAMED profile

    # The item is blank/'(Unknown)', OR it points at a NAMELESS shell
    # profile / dangling id. The shell case is what the 2026-07-02 deploy
    # exposed: the admin's manual edit gave the item a name but resolved it
    # to a profile with blank first/last names, so the sync's canonical-name
    # normalization blanked his enrollment and the blank-row purge deleted
    # it — every boot.
    cid = _lookup_customer_id(conn, "Stu Kirksey", "stuartkirksey@gmail.com")
    if cid is not None and cid != row["customer_id"]:
        target = cid  # a distinct resolvable profile — re-point the purchase
    elif row["prof_exists"] is not None:
        target = row["customer_id"]  # the attached profile is the only anchor
    else:
        logger.warning(
            "Kirksey contest repair: no resolvable profile for order "
            "R747210347 — skipping"
        )
        return
    # Whatever profile we land on must carry his name, or the sync's
    # canonical-name step has nothing usable.
    conn.execute(
        """UPDATE customers
           SET first_name = COALESCE(NULLIF(TRIM(COALESCE(first_name, '')), ''), 'Stu'),
               last_name  = COALESCE(NULLIF(TRIM(COALESCE(last_name,  '')), ''), 'Kirksey')
           WHERE customer_id = ?
             AND TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) = ''""",
        (target,),
    )
    canon = conn.execute(
        """SELECT TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS n
           FROM customers WHERE customer_id = ?""",
        (target,),
    ).fetchone()
    display = (canon["n"] if canon and (canon["n"] or "").strip() else "Stu Kirksey")
    conn.execute(
        """UPDATE items
           SET customer = ?, customer_id = ?,
               customer_email = COALESCE(NULLIF(TRIM(COALESCE(customer_email,'')), ''),
                                         'stuart.kirksey@gmail.com')
           WHERE id = ?""",
        (display, target, row["id"]),
    )
    conn.execute(
        "INSERT OR IGNORE INTO customer_emails (customer_id, email, label) "
        "VALUES (?, 'stuart.kirksey@gmail.com', 'repaired')",
        (target,),
    )
    conn.commit()
    logger.info(
        "Kirksey contest repair: item %s (order R747210347) assigned to %s (cid %d)",
        row["id"], display, target,
    )


def _log_unenrolled_contest_purchases(conn: sqlite3.Connection) -> None:
    """Audit: every contest purchase must have its matching enrollment(s).

    Derives the expected contest set per active TGF MEMBERSHIP / SEASON
    CONTESTS item (same flag + keyword rules as the sync) and warns for any
    expected enrollment missing from season_contests — plus for SEASON
    CONTESTS purchases with no recognizable contest selection at all (the
    parser missed the flags; those enroll nobody silently). Log-only, runs
    at every boot after the boot contest sync, so anything reported is a
    genuine residual problem, not just a sync that hasn't run yet.
    """
    rows = conn.execute(
        """SELECT id, customer, customer_id, item_name, notes, order_date, order_id,
                  net_points_race, gross_points_race, city_match_play
           FROM items
           WHERE COALESCE(transaction_status, 'active') = 'active'
             AND (UPPER(item_name) = 'TGF MEMBERSHIP'
                  OR UPPER(item_name) LIKE '%SEASON CONTEST%')"""
    ).fetchall()
    missing = 0
    for r in rows:
        expected = set()
        if (r["net_points_race"] or "").upper() == "YES":
            expected.add("NET Points Race")
        if (r["gross_points_race"] or "").upper() == "YES":
            expected.add("GROSS Points Race")
        if (r["city_match_play"] or "").upper() == "YES":
            expected.add("City Match Play")
        nm = (r["item_name"] or "").upper()
        nt = (r["notes"] or "").upper()
        if "SEASON CONTEST" in nm:
            if "NET" in nm or "NET" in nt:
                expected.add("NET Points Race")
            if "GROSS" in nm or "GROSS" in nt:
                expected.add("GROSS Points Race")
            if "MATCH PLAY" in nm or "MATCH PLAY" in nt:
                expected.add("City Match Play")
            if not expected:
                missing += 1
                logger.warning(
                    "Contest enrollment audit: item %s (order %s, %r, %s) is a "
                    "SEASON CONTESTS purchase with NO recognizable contest "
                    "selection — review the order and set the right flag(s)",
                    r["id"], r["order_id"], r["customer"], r["order_date"],
                )
                continue
        if not expected:
            continue
        season = (r["order_date"] or "")[:4]
        for ct in sorted(expected):
            exists = conn.execute(
                """SELECT 1 FROM season_contests
                   WHERE contest_type = ? AND season = ?
                     AND (source_item_id = ?
                          OR (customer_id IS NOT NULL AND customer_id = ?)
                          OR LOWER(TRIM(customer_name)) = LOWER(TRIM(?)))
                   LIMIT 1""",
                (ct, season, r["id"], r["customer_id"] or -1, r["customer"] or ""),
            ).fetchone()
            if not exists:
                missing += 1
                logger.warning(
                    "Contest enrollment audit: %s (cid %s) bought %s "
                    "(item %s, order %s, %s) but has NO enrollment",
                    r["customer"] or "(no name)", r["customer_id"], ct,
                    r["id"], r["order_id"], r["order_date"],
                )
    if not missing:
        logger.info(
            "Contest enrollment audit: every contest purchase has matching enrollments"
        )


def _purge_blank_season_contest_rows(conn: sqlite3.Connection) -> None:
    """Fix season_contests rows with an empty customer_name — the blank
    CUSTOMER cell in the Enrollment log. Created before v2.16.28 when the
    contest sync enrolled a source item that had no customer name. A row
    whose customer_id is known is renamed from the profile; otherwise it is
    deleted, and its source purchase is logged so the rightful player can be
    identified (fix the source item's customer, then Sync re-enrolls them
    with the correct purchase date). Idempotent; does not commit.
    """
    rows = conn.execute(
        """SELECT sc.id, sc.contest_type, sc.season, sc.customer_id, sc.source_item_id,
                  i.item_name AS src_item, i.order_id AS src_order, i.order_date AS src_date
           FROM season_contests sc
           LEFT JOIN items i ON i.id = sc.source_item_id
           WHERE TRIM(COALESCE(sc.customer_name, '')) IN ('', '(Unknown)')"""
    ).fetchall()
    for r in rows:
        if r["customer_id"]:
            canon = conn.execute(
                "SELECT TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')) AS n "
                "FROM customers WHERE customer_id = ?", (r["customer_id"],),
            ).fetchone()
            if canon and canon["n"]:
                conn.execute(
                    "UPDATE season_contests SET customer_name = ? WHERE id = ?",
                    (canon["n"], r["id"]),
                )
                logger.info(
                    "Season contest blank-row repair: row %s renamed to %r "
                    "from profile %s", r["id"], canon["n"], r["customer_id"],
                )
                continue
        conn.execute("DELETE FROM season_contests WHERE id = ?", (r["id"],))
        logger.warning(
            "Season contest blank-row repair: deleted nameless %s/%s enrollment "
            "(source item %s: %r order %s dated %s) — fix that item's customer "
            "and re-run Sync to re-enroll the right player",
            r["contest_type"], r["season"], r["source_item_id"],
            r["src_item"], r["src_order"], r["src_date"],
        )


def _repair_season_contest_enrollment_dates(conn: sqlite3.Connection) -> int:
    """Re-date purchase-backed season contest enrollments to their source
    purchase's order_date.

    enrolled_at defaults to CURRENT_TIMESTAMP on insert, and the contest
    sync's cleanup passes can delete + re-create rows (name/chapter
    corrections, dedup) — which used to re-stamp the enrollment date to
    "today" every time it happened (the Paul Reed July-2nd date on a
    March-2nd membership purchase). Manual enrollments with no source item
    keep their admin-entry timestamp. Idempotent; runs at boot AND at the
    end of every contest sync. Does not commit.
    """
    redated = conn.execute(
        """UPDATE season_contests
           SET enrolled_at = (SELECT i.order_date FROM items i
                              WHERE i.id = season_contests.source_item_id)
           WHERE source_item_id IS NOT NULL
             AND EXISTS (
                 SELECT 1 FROM items i
                 WHERE i.id = season_contests.source_item_id
                   AND i.order_date IS NOT NULL AND TRIM(i.order_date) != ''
                   AND DATE(i.order_date) IS NOT NULL
                   AND (season_contests.enrolled_at IS NULL
                        OR DATE(season_contests.enrolled_at) IS NOT DATE(i.order_date))
             )"""
    ).rowcount
    if redated:
        logger.info(
            "Season contest enrollment dates: re-dated %d row(s) to their "
            "source purchase date", redated,
        )
    return redated


def sync_season_contests_from_items(db_path: str | Path | None = None) -> dict:
    """Scan all items and enroll customers in season contests based on their
    net_points_race, gross_points_race, city_match_play fields.

    Also handles standalone SEASON CONTESTS items.

    Two outcomes per row:
    - New enrollment  → INSERT with source_item_id set  (enrolled += 1)
    - Existing manual enrollment without a payment yet → UPDATE source_item_id
      to link the now-arrived transaction             (linked += 1)
    Existing enrollments that already have a source_item_id are left alone.

    Returns {"enrolled": N, "linked": N}.
    """
    enrolled = 0
    linked = 0
    deduped = 0
    cust_by_id: dict[int, dict] = {}

    def _upsert(conn, customer, contest_type, chapter, season, item_id,
                customer_id=None):
        nonlocal enrolled, linked
        if not (customer or "").strip() or customer.strip() == "(Unknown)":
            # A source item with a blank/placeholder customer must not create
            # a ghost enrollment row (an empty or '(Unknown)' CUSTOMER cell
            # in the Enrollment log).
            logger.warning(
                "Season contest sync: skipped %s enrollment from item %s — "
                "item has no customer name", contest_type, item_id,
            )
            return
        # Resolve the profile at insert time when the item doesn't carry one
        # (Guiding Principle #6) — alias-aware, refuses ambiguous names. The
        # deferred name-guess backfill left these rows to churn below.
        if customer_id is None:
            customer_id = _lookup_customer_id(conn, customer, None)
        # Enroll under the CANONICAL profile name/chapter when the profile is
        # known. Inserting the item's name variant (e.g. items.customer 'Stu
        # Kirksey' vs profile 'Stuart Kirksey') created a row that step 1's
        # rename immediately collided into the existing canonical row and
        # deleted — counted as a "new enrollment" on EVERY sync (the residual
        # '10 new enrollments' churn after the v2.16.32 fix).
        if customer_id and customer_id in cust_by_id:
            info = cust_by_id[customer_id]
            canon = (info["name"] or "").strip()
            if canon:
                customer = canon
            if info["chapter"]:
                chapter = info["chapter"]
        # customer_id comes straight from the source item (Guiding Principle
        # #6) — the name-based backfill used to guess, and with split
        # same-person profiles it could pick a DIFFERENT profile than the
        # item's, making the reconciliation below delete the enrollment as
        # "no backing purchase" on every run (the endless "9 new
        # enrollments" loop).
        # RULE (Kerry 2026-08-06, John Wade $150 bundle): a NET Points
        # Race buy-in that arrives AFTER the chapter's City NET race is
        # declared final can only be a FELLOWSHIP CUP entry — the city
        # race is over and its pot closed. Stamp cup_only=1 on INSERT so
        # the city board/pot never counts it; the Cup counts it fully.
        # Fall seasons and existing rows are untouched (ON CONFLICT does
        # not update cup_only).
        cup_only = 0
        if contest_type == "NET Points Race" and season and "Fall" not in season:
            _rk = {"Austin": "austin_net",
                   "San Antonio": "san_antonio_net"}.get(chapter)
            if _rk:
                try:
                    cup_only = 1 if _points_race_final(_rk, db_path=db_path) else 0
                except Exception:
                    cup_only = 0
        result = conn.execute(
            """INSERT INTO season_contests
               (customer_name, customer_id, contest_type, chapter, season,
                source_item_id, cup_only)
               VALUES (?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(customer_name, contest_type, chapter, season)
               DO UPDATE SET source_item_id = excluded.source_item_id,
                             customer_id = COALESCE(excluded.customer_id,
                                                    season_contests.customer_id)
                   WHERE season_contests.source_item_id IS NULL""",
            (customer, customer_id, contest_type, chapter, season, item_id,
             cup_only),
        )
        row = conn.execute(
            """SELECT source_item_id FROM season_contests
               WHERE customer_name = ? AND contest_type = ? AND chapter = ? AND season = ?""",
            (customer, contest_type, chapter, season),
        ).fetchone()
        if row and row["source_item_id"] == item_id:
            if result.lastrowid and result.lastrowid > 0:
                enrolled += 1
            else:
                linked += 1

    with _connect(db_path) as conn:
        # Season contest chapter must ALWAYS come from the customer's canonical chapter,
        # never from items.chapter.  items.chapter captures golf event/course location
        # (e.g. "San Antonio" from a shipping address), which is irrelevant for a season
        # contest purchase and actively wrong when the player's home chapter differs.
        cust_chapter = {}
        for r in conn.execute(
            """SELECT TRIM(first_name) || ' ' || TRIM(last_name) AS customer_name, chapter
               FROM customers
               WHERE chapter IS NOT NULL AND chapter != ''"""
        ).fetchall():
            cust_chapter[r["customer_name"].lower()] = r["chapter"]

        def _canonical_chapter(customer_name):
            return cust_chapter.get((customer_name or "").lower(), "")

        # customer_id → canonical {name, chapter}, used by _upsert (enroll
        # under the canonical identity up front) and the step 1/2 cleanup
        # below. NULL name parts COALESCE to '' so a shell profile yields ''
        # (never None).
        for r in conn.execute(
            """SELECT customer_id,
                      TRIM(COALESCE(first_name, '') || ' ' || COALESCE(last_name, '')) AS customer_name,
                      chapter
               FROM customers
               WHERE customer_id IS NOT NULL"""
        ).fetchall():
            cust_by_id[r["customer_id"]] = {
                "name":    r["customer_name"],
                "chapter": r["chapter"] or "",
            }

        rows = conn.execute(
            """SELECT id, customer, customer_id, net_points_race, gross_points_race,
                      city_match_play, fall_net_points_race, item_name, order_date
               FROM items
               WHERE COALESCE(transaction_status, 'active') = 'active'
                 AND (UPPER(item_name) = 'TGF MEMBERSHIP' OR UPPER(item_name) LIKE '%SEASON CONTEST%')
                 AND (net_points_race = 'YES' OR gross_points_race = 'YES' OR city_match_play = 'YES'
                      OR fall_net_points_race = 'YES'
                      OR UPPER(item_name) LIKE '%SEASON CONTEST%')"""
        ).fetchall()

        for row in rows:
            row = dict(row)
            customer = row.get("customer") or ""
            chapter = _canonical_chapter(customer)
            order_date = row.get("order_date") or ""
            season = order_date[:4] if len(order_date) >= 4 else ""
            item_id = row["id"]
            cid = row.get("customer_id")

            if (row.get("net_points_race") or "").upper() == "YES":
                _upsert(conn, customer, "NET Points Race", chapter, season, item_id, cid)
            if (row.get("gross_points_race") or "").upper() == "YES":
                _upsert(conn, customer, "GROSS Points Race", chapter, season, item_id, cid)
            if (row.get("city_match_play") or "").upper() == "YES":
                _upsert(conn, customer, "City Match Play", chapter, season, item_id, cid)
            # FALL NET is a $50 option under the umbrella SEASON CONTESTS
            # product (Kerry, 2026-07-10): same NET Points Race contest type,
            # season "<year> Fall" — populates the fall pages immediately on
            # receipt of new orders, like everything else.
            if (row.get("fall_net_points_race") or "").upper() == "YES" and season:
                _upsert(conn, customer, "NET Points Race", chapter,
                        f"{season} Fall", item_id, cid)

        # Handle standalone "SEASON CONTESTS" items (fallback for items where the parser
        # didn't populate the individual flag fields).
        bundle_rows = conn.execute(
            """SELECT id, customer, customer_id, item_name, notes, order_date
               FROM items
               WHERE UPPER(item_name) LIKE '%SEASON CONTEST%'
                 AND COALESCE(transaction_status, 'active') = 'active'"""
        ).fetchall()
        for row in bundle_rows:
            row = dict(row)
            customer = row.get("customer") or ""
            chapter = _canonical_chapter(customer)
            order_date = row.get("order_date") or ""
            season = order_date[:4] if len(order_date) >= 4 else ""
            item_name = (row.get("item_name") or "").upper()
            notes_upper = (row.get("notes") or "").upper()
            item_id = row["id"]
            cid = row.get("customer_id")

            # Each contest is independent.  "NET Bundle" does NOT imply City Match Play.
            has_net = "NET" in item_name or "NET" in notes_upper
            has_gross = "GROSS" in item_name or "GROSS" in notes_upper
            has_cmp = "MATCH PLAY" in item_name or "MATCH PLAY" in notes_upper

            contests_to_enroll = set()
            if has_net:
                contests_to_enroll.add("NET Points Race")
            if has_gross:
                contests_to_enroll.add("GROSS Points Race")
            if has_cmp:
                contests_to_enroll.add("City Match Play")

            for ct in contests_to_enroll:
                _upsert(conn, customer, ct, chapter, season, item_id, cid)

            # Stamp item flags so customer profile badges reflect the purchase.
            if contests_to_enroll:
                updates = []
                params = []
                if "NET Points Race" in contests_to_enroll:
                    updates.append("net_points_race = ?"); params.append("YES")
                if "GROSS Points Race" in contests_to_enroll:
                    updates.append("gross_points_race = ?"); params.append("YES")
                if "City Match Play" in contests_to_enroll:
                    updates.append("city_match_play = ?"); params.append("YES")
                if updates:
                    params.append(item_id)
                    conn.execute(f"UPDATE items SET {', '.join(updates)} WHERE id = ?", params)

        # Clear contest enrollment flags from event items where the parser set them
        # incorrectly (e.g. Hill Country Matches with city_match_play='YES').
        conn.execute(
            """UPDATE items
               SET net_points_race = NULL, gross_points_race = NULL, city_match_play = NULL
               WHERE (net_points_race = 'YES' OR gross_points_race = 'YES' OR city_match_play = 'YES')
                 AND UPPER(item_name) != 'TGF MEMBERSHIP'
                 AND UPPER(item_name) NOT LIKE '%SEASON CONTEST%'"""
        )

        # Remove enrollments sourced from non-membership/contest items (e.g. Hill Country
        # Matches erroneously had city_match_play='YES' set by the parser).
        conn.execute(
            """DELETE FROM season_contests
               WHERE source_item_id IN (
                   SELECT id FROM items
                   WHERE UPPER(item_name) != 'TGF MEMBERSHIP'
                     AND UPPER(item_name) NOT LIKE '%SEASON CONTEST%'
               )"""
        )

        # Backfill customer_id BEFORE reconciliation so rows that were never linked
        # (e.g. Eduardo Melchor sourced from a NULL source_item_id) get resolved and
        # the reconciliation below can act on them by customer_id.
        _backfill_customer_id_on_season_contests(conn)

        # Reconcile: remove auto-synced enrollments that have no valid backing purchase.
        # Uses customer_id as the identity key (Guiding Principle #6).
        # Only removes rows where:
        #   - manually_enrolled = 0 (admin-confirmed enrollments are protected)
        #   - customer_id is known (we can positively identify the customer)
        #   - There is no MEMBERSHIP or SEASON CONTESTS item for this customer
        #     that carries the matching contest flag
        #   - AND the row's OWN source purchase isn't still active+flagged.
        #     Without that last guard, an enrollment whose customer_id got
        #     resolved to a different (split/duplicate) profile than its
        #     source item's was deleted as "no backing purchase" on EVERY
        #     sync, then re-created by the next scan — the endless
        #     "9 new enrollments" loop.
        conn.execute(
            """DELETE FROM season_contests
               WHERE manually_enrolled = 0
                 AND customer_id IS NOT NULL
                 AND NOT EXISTS (
                     SELECT 1 FROM items i
                     WHERE i.customer_id = season_contests.customer_id
                       AND COALESCE(i.transaction_status, 'active') = 'active'
                       AND (UPPER(i.item_name) = 'TGF MEMBERSHIP'
                            OR UPPER(i.item_name) LIKE '%SEASON CONTEST%')
                       AND (
                           (season_contests.contest_type = 'NET Points Race'
                                AND i.net_points_race = 'YES')
                           OR (season_contests.contest_type = 'GROSS Points Race'
                                AND i.gross_points_race = 'YES')
                           OR (season_contests.contest_type = 'City Match Play'
                                AND i.city_match_play = 'YES')
                       )
                 )
                 AND NOT EXISTS (
                     SELECT 1 FROM items si
                     WHERE si.id = season_contests.source_item_id
                       AND COALESCE(si.transaction_status, 'active') = 'active'
                       AND (
                           (season_contests.contest_type = 'NET Points Race'
                                AND (si.net_points_race = 'YES'
                                     OR (UPPER(si.item_name) LIKE '%SEASON CONTEST%'
                                         AND (UPPER(si.item_name) LIKE '%NET%'
                                              OR UPPER(COALESCE(si.notes, '')) LIKE '%NET%'))))
                           OR (season_contests.contest_type = 'GROSS Points Race'
                                AND (si.gross_points_race = 'YES'
                                     OR (UPPER(si.item_name) LIKE '%SEASON CONTEST%'
                                         AND (UPPER(si.item_name) LIKE '%GROSS%'
                                              OR UPPER(COALESCE(si.notes, '')) LIKE '%GROSS%'))))
                           OR (season_contests.contest_type = 'City Match Play'
                                AND (si.city_match_play = 'YES'
                                     OR (UPPER(si.item_name) LIKE '%SEASON CONTEST%'
                                         AND (UPPER(si.item_name) LIKE '%MATCH PLAY%'
                                              OR UPPER(COALESCE(si.notes, '')) LIKE '%MATCH PLAY%'))))
                       )
                 )"""
        )

        # Fallback reconciliation for rows whose customer_id is STILL NULL after
        # backfill (unresolvable aliases or orphaned rows).  Uses name-based item
        # lookup.  Catches cases where source_item_id was also NULL so the
        # source-item deletion above couldn't act on them.
        conn.execute(
            """DELETE FROM season_contests
               WHERE manually_enrolled = 0
                 AND customer_id IS NULL
                 AND NOT EXISTS (
                     SELECT 1 FROM items i
                     WHERE LOWER(TRIM(i.customer)) = LOWER(TRIM(season_contests.customer_name))
                       AND COALESCE(i.transaction_status, 'active') = 'active'
                       AND (UPPER(i.item_name) = 'TGF MEMBERSHIP'
                            OR UPPER(i.item_name) LIKE '%SEASON CONTEST%')
                       AND (
                           (season_contests.contest_type = 'NET Points Race'
                                AND i.net_points_race = 'YES')
                           OR (season_contests.contest_type = 'GROSS Points Race'
                                AND i.gross_points_race = 'YES')
                           OR (season_contests.contest_type = 'City Match Play'
                                AND i.city_match_play = 'YES')
                       )
                 )
                 AND NOT EXISTS (
                     SELECT 1 FROM items si
                     WHERE si.id = season_contests.source_item_id
                       AND COALESCE(si.transaction_status, 'active') = 'active'
                       AND (
                           (season_contests.contest_type = 'NET Points Race'
                                AND (si.net_points_race = 'YES'
                                     OR (UPPER(si.item_name) LIKE '%SEASON CONTEST%'
                                         AND (UPPER(si.item_name) LIKE '%NET%'
                                              OR UPPER(COALESCE(si.notes, '')) LIKE '%NET%'))))
                           OR (season_contests.contest_type = 'GROSS Points Race'
                                AND (si.gross_points_race = 'YES'
                                     OR (UPPER(si.item_name) LIKE '%SEASON CONTEST%'
                                         AND (UPPER(si.item_name) LIKE '%GROSS%'
                                              OR UPPER(COALESCE(si.notes, '')) LIKE '%GROSS%'))))
                           OR (season_contests.contest_type = 'City Match Play'
                                AND (si.city_match_play = 'YES'
                                     OR (UPPER(si.item_name) LIKE '%SEASON CONTEST%'
                                         AND (UPPER(si.item_name) LIKE '%MATCH PLAY%'
                                              OR UPPER(COALESCE(si.notes, '')) LIKE '%MATCH PLAY%'))))
                       )
                 )"""
        )

        # cust_by_id (customer_id → {name, chapter}) was built before the scan
        # and customers aren't modified in between — reuse it here.

        # Step 1 — Correct chapters and normalise names on rows that have a customer_id.
        for sc in conn.execute(
            "SELECT id, customer_id, customer_name, contest_type, chapter, season FROM season_contests"
        ).fetchall():
            sc = dict(sc)
            cid = sc.get("customer_id")
            if not cid or cid not in cust_by_id:
                # Fall back to name-based chapter lookup for unlinked rows.
                correct = cust_chapter.get((sc["customer_name"] or "").lower(), "")
                canon  = sc["customer_name"]
            else:
                correct = cust_by_id[cid]["chapter"]
                canon   = (cust_by_id[cid]["name"] or "").strip()
                if not canon:
                    # NAMELESS shell profile (blank first/last names). Renaming
                    # to '' blanks the row and the blank-row purge then deletes
                    # the enrollment — exactly how Stu Kirksey's City Match
                    # Play entry vanished on every boot (his purchase pointed
                    # at a shell profile). Keep the item-sourced display name.
                    canon = sc["customer_name"]

            chapter_ok = not correct or sc["chapter"] == correct
            name_ok    = sc["customer_name"] == canon

            if chapter_ok and name_ok:
                continue

            # Try to UPDATE the row to correct chapter + canonical name.
            try:
                conn.execute(
                    "UPDATE season_contests SET chapter = ?, customer_name = ? WHERE id = ?",
                    (correct if correct else sc["chapter"], canon, sc["id"]),
                )
            except sqlite3.IntegrityError:
                # A row with the canonical (name, contest_type, chapter, season) already
                # exists — this is a duplicate; delete it.
                conn.execute("DELETE FROM season_contests WHERE id = ?", (sc["id"],))
                deduped += 1

        # Step 2 — Deduplicate by (customer_id, contest_type, season): same person enrolled
        # under two names (e.g. Stu + Stuart) now has the same customer_id on both rows after
        # step 1 corrected the name, but may have been a UNIQUE-conflict-delete on one already.
        # Run an explicit dedup pass to catch any remaining duplicates.
        for grp in conn.execute(
            """SELECT customer_id, contest_type, season
               FROM season_contests
               WHERE customer_id IS NOT NULL
               GROUP BY customer_id, contest_type, season
               HAVING COUNT(*) > 1"""
        ).fetchall():
            grp = dict(grp)
            rows = conn.execute(
                """SELECT id, customer_name, chapter FROM season_contests
                   WHERE customer_id = ? AND contest_type = ? AND season = ?
                   ORDER BY enrolled_at DESC""",
                (grp["customer_id"], grp["contest_type"], grp["season"]),
            ).fetchall()
            canon = cust_by_id.get(grp["customer_id"], {}).get("name")
            keep_id = next(
                (r["id"] for r in rows if r["customer_name"] == canon),
                rows[0]["id"],
            )
            for r in rows:
                if r["id"] != keep_id:
                    conn.execute("DELETE FROM season_contests WHERE id = ?", (r["id"],))
                    deduped += 1

        # Step 3 — enrolled_at must reflect WHEN THE MEMBER ENROLLED (their
        # source purchase's order_date), not when this sync happened to write
        # the row. Shared with init_db so a deploy re-dates existing rows
        # immediately — this sync only runs when new orders arrive or on the
        # manual button, which is too late for a repair.
        _repair_season_contest_enrollment_dates(conn)
        _purge_blank_season_contest_rows(conn)

        conn.commit()
    if deduped:
        # A nonzero count here means insert-then-delete churn survived the
        # canonical-name-at-insert fix — inflated "new enrollments" counts.
        logger.warning(
            "Season contest sync: %d duplicate row(s) removed by cleanup — "
            "these inflated the 'new enrollments' count", deduped,
        )
    logger.info("Season contest sync: %d new enrollments, %d payments linked", enrolled, linked)
    return {"enrolled": enrolled, "linked": linked}


# ---------------------------------------------------------------------------
# City Match Play — pools, members, matches, bracket
# ---------------------------------------------------------------------------

def cmp_gg_detail_dump(chapter: str, player_a: str, player_b: str,
                       db_path=None) -> dict:
    """READ-ONLY: return the stored gg_match_detail for one match (by chapter +
    the two players, nickname-robust) so we can inspect whether GG's per-hole
    strokes/pops were captured."""
    key = frozenset([_cmp_person_key(player_a), _cmp_person_key(player_b)])
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT m.id, m.player1_name, m.player2_name, m.winner_name,
                      m.margin, m.gg_match_detail, e.item_name AS event
                 FROM cmp_matches m
                 JOIN cmp_pools p ON p.id = m.pool_id
                 LEFT JOIN events e ON e.id = m.event_id
                WHERE p.chapter = ?""", (chapter,)).fetchall()
    for r in rows:
        if frozenset([_cmp_person_key(r["player1_name"]),
                      _cmp_person_key(r["player2_name"])]) == key:
            d = dict(r)
            try:
                d["gg_match_detail"] = json.loads(d["gg_match_detail"]) \
                    if d["gg_match_detail"] else None
            except Exception:
                pass
            # compact per-hole stroke view
            gg = d.get("gg_match_detail") or {}
            d["stroke_summary"] = [
                {"hole": h.get("hole"), "p1_str": h.get("p1_strokes"),
                 "p2_str": h.get("p2_strokes")}
                for h in (gg.get("holes") or []) if h.get("p1_gross") is not None]
            return d
    return {"error": "no match found", "chapter": chapter,
            "players": [player_a, player_b]}


def cmp_pools_audit(db_path=None) -> dict:
    """READ-ONLY: distinct (chapter, season) in cmp_pools with pool + match
    counts. Diagnoses why a chapter/season combo returns no pools (e.g. SA
    pools stored under a different season label than the selector sends).
    Also lists pool-member rows with no customer_id link (the class that
    made reconcilers report imported scorecards as missing) — the boot
    backfill should keep this empty."""
    with _connect(db_path) as conn:
        return {"pools": [dict(r) for r in conn.execute(
            """SELECT p.chapter, p.season,
                      COUNT(DISTINCT p.id) AS pools,
                      COUNT(DISTINCT pm.id) AS members,
                      COUNT(m.id) AS matches
                 FROM cmp_pools p
                 LEFT JOIN cmp_pool_members pm ON pm.pool_id = p.id
                 LEFT JOIN cmp_matches m ON m.pool_id = p.id
                GROUP BY p.chapter, p.season
                ORDER BY p.season DESC, p.chapter""")],
            "unlinked_members": [dict(r) for r in conn.execute(
            """SELECT pm.id, pm.customer_name, p.chapter, p.season,
                      p.pool_name
                 FROM cmp_pool_members pm
                 JOIN cmp_pools p ON p.id = pm.pool_id
                WHERE pm.customer_id IS NULL
                ORDER BY p.season DESC, p.chapter, pm.customer_name""")]}


_CMP_MP_WIDGETS = {
    "austin": "https://tgf-austin.golfgenius.com/leagues/514705/widgets/tournament_results?shared=false",
    "san antonio": "https://tgf-sa.golfgenius.com/leagues/514047/widgets/tournament_results?shared=false",
    "sa": "https://tgf-sa.golfgenius.com/leagues/514047/widgets/tournament_results?shared=false",
}
_CMP_LIVE_CACHE = {}    # (host, pairkey) -> (epoch_ts, detail)


def cmp_fetch_live_match(chapter: str, player_a: str, player_b: str,
                         max_age: float = 25.0, db_path=None) -> dict:
    """Fetch GG's CURRENT match-play detail for one (in-progress) match, live —
    for the minute-by-minute semifinal wiring. Walks the chapter's
    tournament_results widget, finds the newest round whose MATCH PLAY game
    contains the pair, and returns the parsed per-hole detail (same shape as
    the stored gg_match_detail, with thru / gg_margin reflecting the live
    state). In-memory cached `max_age` seconds so many viewers polling every
    60s collapse to one GG walk. Never writes."""
    import time as _t
    import re as _re
    from urllib.parse import urlparse
    from golf_genius_sync import (fetch_public_page, parse_page_structure,
                                  parse_tournament_aggregates)
    from email_parser.gg_match_play import parse_match_play_detail

    ch = (chapter or "").strip().lower()
    widget = _CMP_MP_WIDGETS.get(ch)
    if not widget:
        widget = (_CMP_MP_WIDGETS["austin"] if "austin" in ch
                  else _CMP_MP_WIDGETS["san antonio"] if "antonio" in ch or ch == "sa"
                  else None)
    if not widget:
        return {"error": "unknown chapter", "chapter": chapter}
    host = urlparse(widget).netloc
    base_host = f"https://{host}"
    pairkey = frozenset([_cmp_person_key(player_a), _cmp_person_key(player_b)])
    ck = (host, pairkey)
    now = _t.time()
    cached = _CMP_LIVE_CACHE.get(ck)
    if cached and now - cached[0] < max_age:
        return {**cached[1], "cached": True}

    def fetch(url, xhr=False):
        p = fetch_public_page(url, xhr=xhr)
        if p["status_code"] != 200:
            raise RuntimeError(f"GG HTTP {p['status_code']}")
        return p["html"]

    started = _t.monotonic()
    result = None
    try:
        html = fetch(widget)
        sel = _re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>', html, _re.S)
        options = _re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                              sel.group(1) if sel else "", _re.S)
        # newest first (GG lists most-recent round at the top); stop at first hit
        for rid, lbl in options:
            if _t.monotonic() - started > 20:
                break
            struct = parse_page_structure(fetch(f"{widget}&round={rid}"), widget)
            # ALL match-play games in the round, not just the first —
            # championship day carries TWO ("AUSTIN MATCH PLAY CHAMPIONSHIP"
            # for the Final and "...3RD PLACE PLAYOFF" for the consolation,
            # verified live 2026-08-01), and next() walked only the first,
            # so the 3rd-place pair was never found while its players were
            # visibly scoring (Kerry).
            mps = [l for l in (struct.get("links") or [])
                   if _re.search(r"match\s*play", l.get("text") or "", _re.I)
                   and "/v2tournaments/" in (l.get("href") or "")]
            if not mps:
                continue
            for mp in mps:
                if _t.monotonic() - started > 20:
                    break
                code_m = _re.search(r"\b([as]\d+(?:\.\d+)?)\b", mp.get("text") or "")
                for agg in parse_tournament_aggregates(fetch(mp["href"])):
                    if _t.monotonic() - started > 20:
                        break
                    d = parse_match_play_detail(fetch(
                        f"{base_host}/tournaments2/details/{agg}", xhr=True))
                    if not d or len(d.get("players", [])) < 2:
                        continue
                    if frozenset(_cmp_person_key(p["name"]) for p in d["players"]) == pairkey:
                        result = {**d, "gg_event": code_m.group(1) if code_m else None,
                                  "source_url": f"{base_host}/tournaments2/details/{agg}"}
                        break
                if result:
                    break
            if result:
                break
    except Exception as e:
        return {"error": str(e), "chapter": chapter,
                "players": [player_a, player_b]}

    if result:
        # Re-derive the close-out with the TRUE match length from the TGF
        # event code (a9.19 → 9 holes): the parser's column count is the
        # right default, but the flag-count walk it replaces left frozen
        # snapshots wrong, and an 18-column card for a 9-hole match would
        # under-close. Defensive + idempotent (v2.138.1).
        try:
            from email_parser.gg_match_play import rederive_close_out
            _cm = _re.search(r"\b[as](\d{1,2})\.\d", result.get("gg_event") or "")
            _mlen = (18 if int(_cm.group(1)) >= 10 else 9) if _cm else None
            rederive_close_out(result, _mlen)
        except Exception:
            logger.exception("close-out rederive failed (non-fatal)")

    if result and not result.get("hole_pars"):
        # Carry the hole pars in the live payload (Kerry 2026-07-21):
        # a LIVE match's bracket row often has no event linked yet, so
        # the card can't resolve pars any other way. GG's round label
        # gives us the event code — resolve it and embed the map. The
        # hardened snapshot then carries pars forever too.
        try:
            _code = (result.get("gg_event") or "").strip()
            if _code:
                with _connect(db_path) as _pconn:
                    _ev = _pconn.execute(
                        "SELECT id FROM events WHERE item_name LIKE ? "
                        "COLLATE NOCASE ORDER BY event_date DESC LIMIT 1",
                        (_code + " %",)).fetchone()
                    if _ev:
                        _pars = _cmp_hole_pars_for_event(_pconn, _ev["id"])
                        if _pars:
                            result["hole_pars"] = _pars
        except Exception:
            logger.exception("live hole-pars resolve failed (non-fatal)")

    out = result or {"error": "match not found on GG",
                     "chapter": chapter, "players": [player_a, player_b]}
    _CMP_LIVE_CACHE[ck] = (now, out)
    if result:
        # Harden FINISHED detail onto the bracket row (Kerry 2026-07-21)
        # so completed knockout cards paint their hole dots instantly on
        # future loads instead of waiting for a fresh GG walk. Mid-match
        # detail is never persisted — a partial snapshot would freeze the
        # card, since the poller stops once dots render on a recorded
        # match. Best-effort: a persist failure never breaks the live path.
        try:
            _cmp_persist_bracket_detail(chapter, player_a, player_b, result,
                                        db_path=db_path)
        except Exception:
            logger.exception("bracket detail persist failed (non-fatal)")
    return out


def _cmp_persist_bracket_detail(chapter: str, player_a: str, player_b: str,
                                detail: dict, db_path=None) -> bool:
    """Store a FINISHED match's GG hole detail on the matching cmp_bracket
    pair (even slot). Finished = played to the end (thru >= n_holes) or a
    decisive closeout margin ('3&2'). Returns True when a row was written."""
    thru = detail.get("thru") or 0
    n_holes = detail.get("n_holes") or 0
    margin = str(detail.get("gg_margin") or "")
    finished = (n_holes and thru >= n_holes) or \
               (detail.get("gg_winner_idx") and "&" in margin)
    if not finished:
        return False
    pk = frozenset([_cmp_person_key(player_a), _cmp_person_key(player_b)])
    payload = json.dumps(detail)
    with _connect(db_path) as conn:
        rows = conn.execute(
            "SELECT id, season, round, slot, player_name FROM cmp_bracket "
            "WHERE chapter = ? ORDER BY season DESC, round, slot",
            ((chapter or "").strip(),)).fetchall()
        pairs: dict = {}
        for r in rows:
            pairs.setdefault((r["season"], r["round"], r["slot"] // 2),
                             []).append(r)
        for pair in pairs.values():
            if len(pair) != 2:
                continue
            names = frozenset(_cmp_person_key(r["player_name"] or "")
                              for r in pair)
            if names == pk:
                even = min(pair, key=lambda r: r["slot"])
                conn.execute(
                    "UPDATE cmp_bracket SET gg_match_detail = ? WHERE id = ?",
                    (payload, even["id"]))
                conn.commit()
                return True
    return False


def _repair_cmp_detail_close_out(conn) -> int:
    """Boot heal (v2.138.1): re-derive closed_at_order / thru / gg_margin /
    gg_winner_* on every stored gg_match_detail snapshot with the
    match-length-aware close-out walk (see gg_match_play._close_out_walk).
    Snapshots frozen by the old flag-count walk marked the real deciding
    hole dead whenever it halved and the post-clinch holes were never
    posted. Idempotent — rewrites only snapshots whose summary changes.
    The per-hole data and the frozen winner_name/margin on the row itself
    are untouched."""
    from email_parser.gg_match_play import rederive_close_out
    fixed = 0
    for table in ("cmp_bracket", "cmp_matches"):
        try:
            rows = conn.execute(
                f"SELECT id, gg_match_detail FROM {table} "
                "WHERE gg_match_detail IS NOT NULL").fetchall()
        except sqlite3.OperationalError:
            continue        # table/column not created yet on this DB
        for r in rows:
            try:
                d = json.loads(r["gg_match_detail"])
            except Exception:
                continue
            if not isinstance(d, dict) or not d.get("holes"):
                continue
            if rederive_close_out(d):
                conn.execute(
                    f"UPDATE {table} SET gg_match_detail = ? WHERE id = ?",
                    (json.dumps(d), r["id"]))
                fixed += 1
    if fixed:
        conn.commit()
    return fixed


def cmp_get_pools(season: str, chapter: str, db_path=None) -> list[dict]:
    with _connect(db_path) as conn:
        pools = conn.execute(
            "SELECT * FROM cmp_pools WHERE season = ? AND chapter = ? ORDER BY pool_name",
            (season, chapter),
        ).fetchall()
        result = []
        for p in pools:
            pool = dict(p)
            members = conn.execute(
                "SELECT * FROM cmp_pool_members WHERE pool_id = ? ORDER BY customer_name",
                (p["id"],),
            ).fetchall()
            pool["members"] = [dict(m) for m in members]
            result.append(pool)
        return result


def cmp_create_pool(season: str, chapter: str, pool_name: str, db_path=None) -> dict:
    with _connect(db_path) as conn:
        try:
            conn.execute(
                "INSERT INTO cmp_pools (season, chapter, pool_name) VALUES (?, ?, ?)",
                (season, chapter, pool_name),
            )
            conn.commit()
        except sqlite3.IntegrityError:
            pass
        row = conn.execute(
            "SELECT * FROM cmp_pools WHERE season = ? AND chapter = ? AND pool_name = ?",
            (season, chapter, pool_name),
        ).fetchone()
        return dict(row) if row else {}


def cmp_delete_pool(pool_id: int, db_path=None) -> None:
    with _connect(db_path) as conn:
        conn.execute("DELETE FROM cmp_matches WHERE pool_id = ?", (pool_id,))
        conn.execute("DELETE FROM cmp_pool_members WHERE pool_id = ?", (pool_id,))
        conn.execute("DELETE FROM cmp_pools WHERE id = ?", (pool_id,))
        conn.commit()


def cmp_add_member(pool_id: int, customer_name: str, customer_id: int | None = None, db_path=None) -> dict:
    with _connect(db_path) as conn:
        try:
            conn.execute(
                "INSERT INTO cmp_pool_members (pool_id, customer_name, customer_id) VALUES (?, ?, ?)",
                (pool_id, customer_name, customer_id),
            )
            conn.commit()
        except sqlite3.IntegrityError:
            pass
        row = conn.execute(
            "SELECT * FROM cmp_pool_members WHERE pool_id = ? AND customer_name = ?",
            (pool_id, customer_name),
        ).fetchone()
        return dict(row) if row else {}


def cmp_set_member_withdrawn(pool_id: int, customer_name: str, withdrawn: bool,
                             reason: str | None = None, db_path=None) -> dict:
    """Record (or clear) a pool member's withdrawal (Kerry 2026-07-19).
    Keeps the member and their played matches — only the WD tag/state; the
    played-zero-matches heuristic can't see a mid-pool withdrawal. `reason`
    is an optional short code shown on the chip (INJ → 'WD · INJ');
    clearing the flag clears the reason too."""
    reason = (reason or "").strip().upper()[:12] or None
    with _connect(db_path) as conn:
        cur = conn.execute(
            "UPDATE cmp_pool_members SET withdrawn = ?, withdrawn_reason = ? "
            "WHERE pool_id = ? AND customer_name = ?",
            (1 if withdrawn else 0, reason if withdrawn else None,
             pool_id, customer_name))
        conn.commit()
        return {"pool_id": pool_id, "customer_name": customer_name,
                "withdrawn": bool(withdrawn), "reason": reason,
                "updated": cur.rowcount}


def cmp_set_withdrawn_by_name(season: str, chapter: str, player_substr: str,
                              withdrawn: bool, reason: str | None = None,
                              db_path=None) -> dict:
    """Bridge helper: flag withdrawal by (season, chapter, name substring)
    without needing the pool id. Errors if the name is ambiguous."""
    reason = (reason or "").strip().upper()[:12] or None
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT m.id, m.pool_id, m.customer_name, p.pool_name
               FROM cmp_pool_members m JOIN cmp_pools p ON p.id = m.pool_id
               WHERE p.season = ? AND p.chapter = ?
                 AND m.customer_name LIKE ?""",
            (season, chapter, f"%{player_substr}%")).fetchall()
        if not rows:
            return {"error": f"no pool member matching {player_substr!r} "
                             f"in {chapter} {season}"}
        if len(rows) > 1:
            return {"error": "ambiguous name",
                    "matches": [dict(r) for r in rows]}
        r = rows[0]
        conn.execute(
            "UPDATE cmp_pool_members SET withdrawn = ?, withdrawn_reason = ? "
            "WHERE id = ?",
            (1 if withdrawn else 0, reason if withdrawn else None, r["id"]))
        conn.commit()
        return {"pool": r["pool_name"], "customer_name": r["customer_name"],
                "withdrawn": bool(withdrawn), "reason": reason}


def cmp_remove_member(pool_id: int, customer_name: str, db_path=None) -> None:
    with _connect(db_path) as conn:
        conn.execute(
            "DELETE FROM cmp_pool_members WHERE pool_id = ? AND customer_name = ?",
            (pool_id, customer_name),
        )
        conn.execute(
            """DELETE FROM cmp_matches
               WHERE pool_id = ? AND (player1_name = ? OR player2_name = ?)""",
            (pool_id, customer_name, customer_name),
        )
        conn.commit()


def _cmp_hole_pars_for_event(conn, event_id, _cache: dict | None = None) -> dict:
    """{hole_number: par} for an event, via its imported scoring rounds'
    tees → course_tee_holes (Kerry 2026-07-21: the expanded match
    scorecard shows a Par row so scores read against par). Par rarely
    differs across tees; the first tee with data wins per hole. {} when
    the event has no banked cards / tee pars."""
    if not event_id:
        return {}
    if _cache is not None and event_id in _cache:
        return _cache[event_id]
    pars: dict = {}
    for r in conn.execute(
            """SELECT cth.hole_number, cth.par
                 FROM (SELECT DISTINCT tee_id FROM scoring_rounds
                        WHERE event_id = ? AND tee_id IS NOT NULL) t
                 JOIN course_tee_holes cth ON cth.tee_id = t.tee_id
                WHERE cth.par IS NOT NULL
                ORDER BY cth.hole_number""", (event_id,)):
        pars.setdefault(r["hole_number"], r["par"])
    if not pars:
        # Course-name fallback (Kerry 2026-07-21, the Falconhead
        # practice-round semifinal): the linked event has NO imported
        # cards (0-registration practice event), but the course's tee
        # pars are already banked from other events. Match the event's
        # course text against the course DB by containment
        # ("Falconhead" → "Falconhead Golf Club").
        ev = conn.execute("SELECT course FROM events WHERE id = ?",
                          (event_id,)).fetchone()
        cname = (ev["course"] or "").strip() if ev else ""
        if cname:
            for r in conn.execute(
                    """SELECT cth.hole_number, cth.par
                         FROM courses c
                         JOIN course_tees ct ON ct.course_id = c.course_id
                         JOIN course_tee_holes cth ON cth.tee_id = ct.tee_id
                        WHERE c.name LIKE '%' || ? || '%' COLLATE NOCASE
                          AND cth.par IS NOT NULL
                        ORDER BY c.course_id, ct.tee_id, cth.hole_number""",
                    (cname,)):
                pars.setdefault(r["hole_number"], r["par"])
    if _cache is not None:
        _cache[event_id] = pars
    return pars


def cmp_get_matches(pool_id: int, db_path=None) -> list[dict]:
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT m.*, e.item_name AS event_name, e.event_date AS event_date_val
               FROM cmp_matches m
               LEFT JOIN events e ON e.id = m.event_id
               WHERE m.pool_id = ? ORDER BY m.id""",
            (pool_id,),
        ).fetchall()
        out = [dict(r) for r in rows]
        # Par row feed for the expanded scorecards (Kerry 2026-07-21)
        _pc: dict = {}
        for m in out:
            m["hole_pars"] = _cmp_hole_pars_for_event(conn, m.get("event_id"), _pc)
        return out


def _cmp_round_row_for(conn, event_id, customer_id, player_name=None):
    """The scoring_rounds row (id, playing_handicap, tee_id) for a player at
    an event: by customer_id when linked, else by nickname-robust person-key
    against the event's imported cards. The name fallback exists because a
    cmp_pool_members row with a NULL/wrong customer_id used to make BOTH
    reconcilers report 'no_hole_scores_imported' for cards that were in fact
    imported (the 2026-07-20 Austin 'missing 11' — Barna/Marques/Cloer/Hogue
    all had cards under valid customer_ids)."""
    if not event_id:
        return None
    if customer_id:
        r = conn.execute(
            """SELECT id, playing_handicap, tee_id FROM scoring_rounds
               WHERE event_id = ? AND customer_id = ?
               ORDER BY holes_played DESC, id DESC LIMIT 1""",
            (event_id, customer_id)).fetchone()
        if r:
            return r
    if player_name:
        want = _cmp_person_key(player_name)
        cands = [r for r in conn.execute(
            """SELECT id, playing_handicap, tee_id, player_name
                 FROM scoring_rounds WHERE event_id = ?
                ORDER BY holes_played DESC, id DESC""",
            (event_id,)).fetchall()
            if _cmp_person_key(r["player_name"]) == want]
        if cands:
            return cands[0]
    return None


def _cmp_holes_for(conn, event_id, customer_id, player_name=None):
    """Per-hole (strokes, strokes_received) for a player at an event, from
    the imported GG scorecard. Returns {hole_number: (gross, pops)} or {}."""
    row = _cmp_round_row_for(conn, event_id, customer_id, player_name)
    if not row:
        return {}
    holes = {}
    for h in conn.execute(
            "SELECT hole_number, strokes, strokes_received FROM scoring_holes "
            "WHERE scoring_round_id = ? ORDER BY hole_number", (row["id"],)):
        holes[h["hole_number"]] = (h["strokes"], h["strokes_received"] or 0)
    return holes


def _cmp_play_order(holes, start_hole):
    """Sequence a set of hole numbers in PLAY order for a shotgun/staggered
    start: begin at start_hole, ascend, and WRAP within the holes actually
    played (Kerry 2026-07-20: a 9-hole match starting on 4 plays 4..9 then
    1..3 — it never goes to 10). Falls back to ascending when start_hole is
    unknown or not among the played holes."""
    base = sorted(holes)
    if start_hole is None or start_hole not in base:
        return base
    i = base.index(start_hole)
    return base[i:] + base[:i]


def _cmp_gg_play_order(m) -> tuple:
    """(play_order list | None, start_hole | None) from a cmp_matches row's
    gg_match_detail snapshot. Prefers GG's own explicit per-hole `order`
    sequence; falls back to wrapping from start_hole."""
    raw = m.get("gg_match_detail") if isinstance(m, dict) else None
    if not raw:
        return None, None
    try:
        gg = json.loads(raw) if isinstance(raw, str) else raw
    except Exception:
        return None, None
    start = gg.get("start_hole")
    hs = gg.get("holes") or []
    if hs and all(h.get("order") is not None for h in hs):
        seq = [h["hole"] for h in sorted(hs, key=lambda h: h["order"])
               if h.get("hole") is not None]
        if seq:
            return seq, start
    if start is not None and hs:
        return _cmp_play_order([h["hole"] for h in hs
                                if h.get("hole") is not None], start), start
    return None, start


def _cmp_derive_match(a_holes: dict, b_holes: dict,
                      play_order: list | None = None) -> dict:
    """Net match-play result from per-hole scores. a_holes/b_holes:
    {hole: (gross, pops)}. Net = gross − pops; lower net wins the hole.
    Returns {holes:[{h,winner:'A'|'B'|'H',a_net,b_net}], leader:'A'|'B'|None,
    margin, thru, closed_at, n_holes} using standard close-out semantics
    (X&Y = X up with Y to play). None if not enough data.

    `play_order` (hole numbers in the sequence actually played) matters for a
    shotgun start: close-out margins count holes REMAINING IN PLAY ORDER, so
    walking 1..9 for a match that started on 5 produces wrong X&Y margins even
    though the final winner is order-independent. Ascending order is only the
    fallback when the true sequence is unknown."""
    pool = set(a_holes) & set(b_holes)
    if play_order:
        common = [h for h in play_order if h in pool] + \
                 sorted(pool - set(play_order))
    else:
        common = sorted(pool)
    common = [h for h in common
              if a_holes[h][0] is not None and b_holes[h][0] is not None]
    if len(common) < 1:
        return None
    # Close-out counts holes remaining IN THE MATCH — the full play_order
    # length when known — not holes with scores posted. Scoring only the
    # posted holes clinches one hole early when the deciding hole is a
    # halve and the post-clinch holes were never played/posted (v2.138.1).
    total = len(play_order) if play_order else len(common)
    seq, up, closed_at, up_at_close = [], 0, None, None
    for i, h in enumerate(common):
        anet = a_holes[h][0] - (a_holes[h][1] or 0)
        bnet = b_holes[h][0] - (b_holes[h][1] or 0)
        w = "A" if anet < bnet else ("B" if bnet < anet else "H")
        up += 1 if w == "A" else (-1 if w == "B" else 0)
        seq.append({"h": h, "winner": w, "a_net": anet, "b_net": bnet})
        remaining = max(0, total - (i + 1))
        if closed_at is None and abs(up) > remaining:
            closed_at, up_at_close = i + 1, up
    if closed_at is not None:
        leader = "A" if up_at_close > 0 else "B"
        lead, to_play = abs(up_at_close), total - closed_at
        margin = f"{lead}&{to_play}" if to_play > 0 else f"{lead} UP"
        thru = closed_at
    else:
        leader = "A" if up > 0 else ("B" if up < 0 else None)
        margin = "AS" if up == 0 else f"{abs(up)} UP"
        thru = len(common)
    return {"holes": seq, "leader": leader, "margin": margin, "thru": thru,
            "closed_at": closed_at, "n_holes": len(common)}


def _cmp_norm_margin(s: str) -> str:
    s = (s or "").strip().upper().replace(" ", "")
    if s in ("HALVED", "ALLSQUARE", "AS", "TIE", "TIED", "T"):
        return "AS"
    return s


def cmp_reconcile_hole_results(season: str | None = None,
                               chapter: str | None = None,
                               db_path=None) -> dict:
    """READ-ONLY (Kerry 2026-07-17): derive each Match Play match's result
    from the imported GG per-hole scores (net = gross − pops, lower net wins
    the hole) and DIFF it against our stored winner/margin. Reports every
    match that does NOT align so Kerry can resolve it. Changes nothing.

    Buckets: aligned (computed winner+margin == stored), winner_mismatch,
    margin_mismatch, putt_off (stored has a winner but holes are all-square —
    a putt-off/extra-holes decision hole data can't show), no_event (match
    has no event assigned), no_holes (a player's GG scorecard isn't imported
    for that event)."""
    where, params = [], []
    if season:
        where.append("p.season = ?"); params.append(season)
    if chapter:
        where.append("p.chapter = ?"); params.append(chapter)
    wsql = (" WHERE " + " AND ".join(where)) if where else ""
    with _connect(db_path) as conn:
        matches = [dict(r) for r in conn.execute(
            f"""SELECT m.*, p.season, p.chapter, p.pool_name,
                       e.item_name AS event_name, e.event_date
                  FROM cmp_matches m
                  JOIN cmp_pools p ON p.id = m.pool_id
                  LEFT JOIN events e ON e.id = m.event_id
                  {wsql} ORDER BY p.season, p.chapter, p.pool_name, m.id""",
            params).fetchall()]
        memb = {}
        for r in conn.execute(
                """SELECT pm.pool_id, pm.customer_name, pm.customer_id
                     FROM cmp_pool_members pm"""):
            memb[(r["pool_id"], (r["customer_name"] or "").strip().lower())] = r["customer_id"]

        out = {"checked": 0, "aligned": 0, "mismatches": [], "putt_offs": [],
               "uncheckable": [], "season": season, "chapter": chapter}
        for m in matches:
            if not m.get("winner_name") and m.get("player1_stableford") is None:
                continue  # not played / no result recorded
            out["checked"] += 1
            p1, p2 = m["player1_name"], m["player2_name"]
            a_id = m.get("player1_id") or memb.get((m["pool_id"], (p1 or "").strip().lower()))
            b_id = m.get("player2_id") or memb.get((m["pool_id"], (p2 or "").strip().lower()))
            tag = {"season": m["season"], "chapter": m["chapter"],
                   "pool": m["pool_name"], "match": f"{p1} vs {p2}",
                   "event": m.get("event_name"), "date": m.get("event_date"),
                   "stored_winner": m.get("winner_name"),
                   "stored_margin": m.get("margin")}
            if not m.get("event_id"):
                out["uncheckable"].append({**tag, "reason": "no_event_assigned"})
                continue
            a_holes = _cmp_holes_for(conn, m["event_id"], a_id, p1)
            b_holes = _cmp_holes_for(conn, m["event_id"], b_id, p2)
            if not a_holes or not b_holes:
                miss = []
                if not a_holes: miss.append(p1)
                if not b_holes: miss.append(p2)
                out["uncheckable"].append(
                    {**tag, "reason": "no_hole_scores_imported",
                     "missing": miss})
                continue
            play_order, start_hole = _cmp_gg_play_order(m)
            tag["start_hole"] = start_hole
            d = _cmp_derive_match(a_holes, b_holes, play_order)
            if not d:
                out["uncheckable"].append({**tag, "reason": "insufficient_holes"})
                continue
            comp_winner = (p1 if d["leader"] == "A"
                           else p2 if d["leader"] == "B" else None)
            comp = {**tag, "computed_winner": comp_winner,
                    "computed_margin": d["margin"], "holes_used": d["n_holes"],
                    "thru": d["thru"]}
            stored_w = (m.get("winner_name") or "").strip()
            stored_m = _cmp_norm_margin(m.get("margin"))
            # Putt-off / tie class: holes all-square but a winner is stored.
            if d["leader"] is None and stored_w:
                out["putt_offs"].append(
                    {**comp, "note": "holes all-square; stored winner implies "
                     "a putt-off / extra holes (not in hole data)"})
                continue
            winner_ok = (not stored_w) or (comp_winner and
                         stored_w.lower() == comp_winner.lower())
            margin_ok = (not stored_m) or (stored_m == _cmp_norm_margin(d["margin"]))
            if winner_ok and margin_ok:
                out["aligned"] += 1
            else:
                out["mismatches"].append(
                    {**comp, "winner_ok": winner_ok, "margin_ok": margin_ok})
        out["mismatch_count"] = len(out["mismatches"])
        out["putt_off_count"] = len(out["putt_offs"])
        out["uncheckable_count"] = len(out["uncheckable"])
        return out


def _cmp_match_round(conn, event_id, customer_id, player_name=None):
    """A player's match-play round row: (playing_handicap, tee_id,
    {hole: gross}, [holes_played]) from the imported GG scorecard, or None.

    Unlike _cmp_holes_for this returns the FULL 18/9-hole playing handicap
    and the tee so the caller can re-allocate match-play pops (75% off the
    lowest), NOT the stroke-play strokes_received baked into the import."""
    r = _cmp_round_row_for(conn, event_id, customer_id, player_name)
    if not r:
        return None
    gross, si_sum = {}, 0
    for h in conn.execute(
            "SELECT hole_number, strokes, strokes_received FROM scoring_holes "
            "WHERE scoring_round_id = ? ORDER BY hole_number", (r["id"],)):
        gross[h["hole_number"]] = h["strokes"]
        si_sum += (h["strokes_received"] or 0)
    ph = r["playing_handicap"]
    # Fallback: if GG playing_handicap wasn't stored, the sum of the imported
    # (100%) strokes_received IS the full-allowance course handicap.
    if ph is None:
        ph = si_sum
    return {"ph": ph, "tee_id": r["tee_id"], "gross": gross,
            "holes": sorted(gross)}


def _cmp_si_for_tee(conn, tee_id):
    """{hole_number: stroke_index} for a tee, from course_tee_holes."""
    if not tee_id:
        return {}
    return {h["hole_number"]: h["stroke_index"] for h in conn.execute(
        "SELECT hole_number, stroke_index FROM course_tee_holes "
        "WHERE tee_id = ? AND stroke_index IS NOT NULL", (tee_id,))}


def _cmp_match_pops(a_round, b_round, si_map, allowance=0.75):
    """Match-play pops per hole under TGF's OFF-LOWEST 75% rule.

    Each player's playing handicap is taken to `allowance` (75%) and rounded;
    the lower plays off scratch, the higher receives the DIFFERENCE, allocated
    on the hardest holes actually played (stroke index ascending, wrap for
    diff > holes played). Returns (a_pops, b_pops, meta).  If the two round off
    to the same figure both play straight up (all zeros)."""
    holes = a_round["holes"] or b_round["holes"]
    n = len(holes)
    da = round((a_round["ph"] or 0) * allowance)
    db = round((b_round["ph"] or 0) * allowance)
    diff = da - db
    a_pops = {h: 0 for h in holes}
    b_pops = {h: 0 for h in holes}
    higher = None
    if diff != 0 and n:
        higher = "A" if diff > 0 else "B"
        strokes = abs(diff)
        # holes played, ordered by stroke index (hardest first); SI falls back
        # to hole order if the tee's stroke_index isn't loaded.
        ordered = sorted(holes, key=lambda h: (si_map.get(h, 99), h))
        target = a_pops if higher == "A" else b_pops
        for k in range(strokes):
            target[ordered[k % n]] += 1
    return a_pops, b_pops, {"da": da, "db": db, "diff": diff,
                            "higher": higher, "allowance": allowance,
                            "n_holes": n, "si_loaded": bool(si_map)}


# TGF match-play handicap allowance is per CHAPTER (Kerry 2026-07-17):
# San Antonio plays 75% off the lowest; Austin plays 100% off the lowest.
# Both chapters play OFF LOWEST (lower handicapper to scratch). This map is
# the read-only reconciler's assumption; the durable per-chapter config lives
# in the ratified game-engine version (see docs/claude/game-engine.md).
_CMP_ALLOWANCE_BY_CHAPTER = {
    "san antonio": 0.75, "sa": 0.75,
    "austin": 1.00,
}


def _cmp_allowance_for(chapter, amap=None, default=0.75):
    """Resolve the match-play handicap allowance for a chapter (case- and
    substring-insensitive). SA → 75%, Austin → 100%."""
    amap = amap or _CMP_ALLOWANCE_BY_CHAPTER
    key = (chapter or "").strip().lower()
    if key in amap:
        return amap[key]
    for k, v in amap.items():
        if k in key or key in k:
            return v
    return default


def cmp_reconcile_match_play_75(season: str | None = None,
                                chapter: str | None = None,
                                allowance: float | None = None,
                                allowance_by_chapter: dict | None = None,
                                db_path=None) -> dict:
    """READ-ONLY (Kerry 2026-07-17): re-derive each Match Play match's result
    from imported GG per-hole GROSS scores using TGF's REAL match-play pops —
    allowance OFF THE LOWEST (lower handicapper plays scratch, higher gets the
    difference on the hardest holes) — and diff vs our stored winner/margin.

    Allowance is PER CHAPTER: San Antonio 75%, Austin 100% (both off lowest).
    Pass `allowance` to force a single value for every match, or
    `allowance_by_chapter` to override the default map; otherwise each match
    uses _cmp_allowance_for(its chapter).

    This supersedes cmp_reconcile_hole_results, which used the stroke-play
    strokes_received baked into the import (100% allowance, full-field
    allocation) and therefore produced wrong margins/all-square calls (the
    Chandler/Rideout s9.15 case computed AS while GG shows Chandler 1 up).

    NOTE: hole GROSS is authoritative but CONCESSIONS/GIMMES and putt-offs are
    not in the scorecard, so a residual set of matches will still differ from
    GG's own computed match state; those need the GG match game itself. Buckets
    mirror cmp_reconcile_hole_results. Changes nothing."""
    where, params = [], []
    if season:
        where.append("p.season = ?"); params.append(season)
    if chapter:
        where.append("p.chapter = ?"); params.append(chapter)
    wsql = (" WHERE " + " AND ".join(where)) if where else ""
    with _connect(db_path) as conn:
        matches = [dict(r) for r in conn.execute(
            f"""SELECT m.*, p.season, p.chapter, p.pool_name,
                       e.item_name AS event_name, e.event_date
                  FROM cmp_matches m
                  JOIN cmp_pools p ON p.id = m.pool_id
                  LEFT JOIN events e ON e.id = m.event_id
                  {wsql} ORDER BY p.season, p.chapter, p.pool_name, m.id""",
            params).fetchall()]
        memb = {}
        for r in conn.execute(
                "SELECT pool_id, customer_name, customer_id FROM cmp_pool_members"):
            memb[(r["pool_id"], (r["customer_name"] or "").strip().lower())] = r["customer_id"]

        out = {"checked": 0, "aligned": 0, "mismatches": [], "putt_offs": [],
               "uncheckable": [], "season": season, "chapter": chapter,
               "rule": "off_lowest", "allowance_forced": allowance,
               "allowance_by_chapter": {}}
        for m in matches:
            if not m.get("winner_name") and m.get("player1_stableford") is None:
                continue
            out["checked"] += 1
            m_allow = (allowance if allowance is not None
                       else _cmp_allowance_for(m["chapter"], allowance_by_chapter))
            out["allowance_by_chapter"][m["chapter"]] = m_allow
            p1, p2 = m["player1_name"], m["player2_name"]
            a_id = m.get("player1_id") or memb.get((m["pool_id"], (p1 or "").strip().lower()))
            b_id = m.get("player2_id") or memb.get((m["pool_id"], (p2 or "").strip().lower()))
            tag = {"season": m["season"], "chapter": m["chapter"],
                   "pool": m["pool_name"], "match": f"{p1} vs {p2}",
                   "event": m.get("event_name"), "date": m.get("event_date"),
                   "stored_winner": m.get("winner_name"),
                   "stored_margin": m.get("margin")}
            if not m.get("event_id"):
                out["uncheckable"].append({**tag, "reason": "no_event_assigned"})
                continue
            ra = _cmp_match_round(conn, m["event_id"], a_id, p1)
            rb = _cmp_match_round(conn, m["event_id"], b_id, p2)
            if not ra or not rb:
                miss = []
                if not ra: miss.append(p1)
                if not rb: miss.append(p2)
                out["uncheckable"].append(
                    {**tag, "reason": "no_hole_scores_imported", "missing": miss})
                continue
            si_map = _cmp_si_for_tee(conn, ra["tee_id"]) or \
                _cmp_si_for_tee(conn, rb["tee_id"])
            a_pops, b_pops, meta = _cmp_match_pops(ra, rb, si_map, m_allow)
            a_holes = {h: (ra["gross"].get(h), a_pops.get(h, 0)) for h in ra["gross"]}
            b_holes = {h: (rb["gross"].get(h), b_pops.get(h, 0)) for h in rb["gross"]}
            play_order, start_hole = _cmp_gg_play_order(m)
            tag["start_hole"] = start_hole
            d = _cmp_derive_match(a_holes, b_holes, play_order)
            if not d:
                out["uncheckable"].append({**tag, "reason": "insufficient_holes"})
                continue
            comp_winner = (p1 if d["leader"] == "A"
                           else p2 if d["leader"] == "B" else None)
            comp = {**tag, "computed_winner": comp_winner,
                    "computed_margin": d["margin"], "holes_used": d["n_holes"],
                    "thru": d["thru"], "pops": {"da": meta["da"], "db": meta["db"],
                    "diff": meta["diff"], "higher": meta["higher"],
                    "si_loaded": meta["si_loaded"]}}
            stored_w = (m.get("winner_name") or "").strip()
            stored_m = _cmp_norm_margin(m.get("margin"))
            if d["leader"] is None and stored_w:
                out["putt_offs"].append(
                    {**comp, "note": "holes all-square under 75% off-lowest; "
                     "stored winner implies a putt-off / concession"})
                continue
            winner_ok = (not stored_w) or (comp_winner and
                         stored_w.lower() == comp_winner.lower())
            margin_ok = (not stored_m) or (stored_m == _cmp_norm_margin(d["margin"]))
            if winner_ok and margin_ok:
                out["aligned"] += 1
            else:
                out["mismatches"].append(
                    {**comp, "winner_ok": winner_ok, "margin_ok": margin_ok})
        out["mismatch_count"] = len(out["mismatches"])
        out["putt_off_count"] = len(out["putt_offs"])
        out["uncheckable_count"] = len(out["uncheckable"])
        return out


def _cmp_unwrap_name(name: str) -> str:
    """Unwrap a GG marker like 'Bl[HAMILTON, Doug]' → 'HAMILTON, Doug'."""
    m = re.search(r"\[([^\]]+)\]", name or "")
    return m.group(1).strip() if m else (name or "")


def _cmp_name_tokens(name: str) -> frozenset:
    """Order-insensitive comparable identity from a display name. Strips a
    trailing 'TGF <chapter>' club label GG appends. 'REYES, Isaac TGF Austin'
    and 'Isaac Reyes' both → frozenset({'reyes','isaac'})."""
    n = re.sub(r"\bTGF\b.*$", "", _cmp_unwrap_name(name), flags=re.I)
    return frozenset(t for t in re.findall(r"[a-z]+", n.lower()) if len(t) > 1)


def _cmp_person_key(name: str) -> tuple:
    """(surname, first-initial) — nickname-robust identity within an event.
    Handles both GG 'LAST, First TGF Austin' and our 'First Last'. Matt and
    Matthew collapse to ('jenkins','m'); unique enough inside one match pool."""
    n = re.sub(r"\bTGF\b.*$", "", _cmp_unwrap_name(name), flags=re.I).strip()
    if "," in n:
        last, _, first = n.partition(",")
    else:
        parts = n.split()
        first = parts[0] if parts else ""
        last = parts[-1] if len(parts) > 1 else (parts[0] if parts else "")
    last = re.sub(r"[^a-z]", "", last.lower())
    fi = re.sub(r"[^a-z]", "", first.lower())[:1]
    return (last, fi)


def cmp_import_gg_match_play(widget_url: str, db_path: str | Path = DB_PATH,
                             time_budget: float = 42.0,
                             only_round: str | None = None,
                             store: bool = True, reset: bool = False) -> dict:
    """Walk a portal's tournament_results widget, pull GG's OWN match-play
    detail for every match, and snapshot it onto cmp_matches.gg_match_detail
    (Kerry 2026-07-17). This is the AUDIT-THE-SOURCE path: GG computed the
    starting hole, the 75%/100% off-lowest NET strokes, the per-hole winner,
    and the margin — we read it, we do not recompute it.

    Per round: find the 'MATCH PLAY' game link → /v2tournaments/<tid> →
    parse_tournament_aggregates → /tournaments2/details/<agg> (XHR) →
    parse_match_play_detail. Match each GG pair to a cmp_matches row by event
    code + both players' name tokens. Stores the snapshot (unless store=False)
    and ALWAYS reports gg_winner/margin vs our FROZEN winner/margin — never
    overwrites the stored result; a disagreement is surfaced for review.

    Time-budgeted like import_gg_game_results — call repeatedly until
    rounds_left == 0. widget_url =
    .../leagues/<league_id>/widgets/tournament_results?shared=false
    """
    from time import monotonic
    from urllib.parse import urlparse, parse_qs, urlencode, urlunparse
    from golf_genius_sync import (fetch_public_page, parse_page_structure,
                                  parse_tournament_aggregates)
    from email_parser.gg_match_play import parse_match_play_detail

    started = monotonic()
    parts = urlparse(widget_url)
    base_host = f"https://{parts.netloc}"
    qs = parse_qs(parts.query)
    forced = only_round or (qs.pop("round", [None]) or [None])[0]
    base_url = urlunparse(parts._replace(query=urlencode(qs, doseq=True)))

    def fetch(url, xhr=False):
        page = fetch_public_page(url, xhr=xhr)
        if page["status_code"] != 200:
            raise RuntimeError(f"GG HTTP {page['status_code']} for {url}")
        return page["html"]

    html = fetch(base_url)
    sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>', html, re.S)
    options = re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                         sel.group(1) if sel else "", re.S)
    if forced:
        options = [(rid, lbl) for rid, lbl in options if rid == forced] \
            or [(forced, "")]

    out = {"host": parts.netloc, "rounds_done": 0, "matches_seen": 0,
           "stored": 0, "matched": 0, "unmatched": [], "mismatches": [],
           "aligned": 0, "no_match_play_game": 0, "rounds_left": 0}

    # A TGF match-play match is a unique PAIRING in a pool; it may be played
    # (or made up) at a DIFFERENT event than GG scored it under, so we align by
    # player pair across the whole chapter — NOT by event. Chapter comes from
    # the portal host.
    host_l = (parts.netloc or "").lower()
    chapter = ("Austin" if "austin" in host_l
               else "San Antonio" if "-sa" in host_l or "sanantonio" in host_l
               else None)

    with _connect(db_path) as conn:
        # index EVERY match in this chapter (all events) by pair
        crows = conn.execute(
            """SELECT m.id, m.player1_name, m.player2_name, m.player1_id,
                      m.player2_id, m.winner_name, m.margin, m.event_id,
                      e.item_name AS stored_event, p.chapter, p.season
                 FROM cmp_matches m
                 JOIN cmp_pools p ON p.id = m.pool_id
                 LEFT JOIN events e ON e.id = m.event_id
                WHERE (? IS NULL OR p.chapter = ?)""",
            (chapter, chapter)).fetchall()
        by_ids, by_key = {}, {}
        for r in crows:
            sm = dict(r)
            if sm.get("player1_id") and sm.get("player2_id"):
                by_ids.setdefault(
                    frozenset([sm["player1_id"], sm["player2_id"]]), sm)
            by_key.setdefault(
                frozenset([_cmp_person_key(sm["player1_name"]),
                           _cmp_person_key(sm["player2_name"])]), sm)
        out["chapter"] = chapter

        # done-rounds tracker so store-mode sweeps converge instead of
        # re-walking from the top each call (verify mode ignores it).
        conn.execute("""CREATE TABLE IF NOT EXISTS cmp_mp_import_rounds (
            host TEXT NOT NULL, round_id TEXT NOT NULL,
            imported_at TEXT DEFAULT (datetime('now')),
            PRIMARY KEY (host, round_id))""")
        if reset and store:
            conn.execute("DELETE FROM cmp_mp_import_rounds WHERE host = ?",
                         (parts.netloc,))
            conn.commit()
        done = set()
        if store and not reset:
            done = {r["round_id"] for r in conn.execute(
                "SELECT round_id FROM cmp_mp_import_rounds WHERE host = ?",
                (parts.netloc,)).fetchall()}

        pending = [(rid, lbl) for rid, lbl in options if rid not in done]
        out["rounds_skipped_done"] = len(options) - len(pending)
        for rid, lbl in pending:
            if monotonic() - started > time_budget:
                break
            round_url = f"{base_url}&round={rid}"
            struct = parse_page_structure(fetch(round_url), round_url)
            links = struct.get("links") or []
            mp = next((l for l in links
                       if re.search(r"match\s*play", l.get("text") or "", re.I)
                       and "/v2tournaments/" in (l.get("href") or "")), None)
            out["rounds_done"] += 1
            if not mp:
                out["no_match_play_game"] += 1
                if store:
                    conn.execute("INSERT OR IGNORE INTO cmp_mp_import_rounds "
                                 "(host, round_id) VALUES (?, ?)",
                                 (parts.netloc, rid))
                continue
            code_m = re.search(r"\b([as]\d+(?:\.\d+)?)\b", mp.get("text") or "")
            gg_event = code_m.group(1) if code_m else None

            tid_html = fetch(mp["href"])
            seen_pairs = set()          # dedup: each match has 2 aggregates
            for agg in parse_tournament_aggregates(tid_html):
                if monotonic() - started > time_budget:
                    break
                frag = fetch(f"{base_host}/tournaments2/details/{agg}", xhr=True)
                d = parse_match_play_detail(frag)
                if not d or len(d.get("players", [])) < 2:
                    continue
                gg_names = [p["name"] for p in d["players"]]
                keysig = frozenset(_cmp_person_key(n) for n in gg_names)
                if keysig in seen_pairs:
                    continue            # already handled this match's other card
                seen_pairs.add(keysig)
                out["matches_seen"] += 1
                # resolve GG names -> customer_id (LAST,First aware + aliases)
                cids = [_resolve_scoring_player(conn, n) for n in gg_names]
                sm = None
                if cids[0] and cids[1]:
                    sm = by_ids.get(frozenset(cids))
                if sm is None:
                    sm = by_key.get(keysig)
                tag = {"gg_event": gg_event, "gg_players": gg_names,
                       "gg_winner": d["gg_winner_name"],
                       "gg_margin": d["gg_margin"],
                       "start_hole": d["start_hole"]}
                if not sm:
                    out["unmatched"].append({**tag, "resolved_ids": cids})
                    continue
                out["matched"] += 1
                snap = {**d, "source_url":
                        f"{base_host}/tournaments2/details/{agg}",
                        "cmp_match_id": sm["id"], "gg_event": gg_event,
                        "stored_event": sm.get("stored_event"),
                        "p1_customer_id": cids[0], "p2_customer_id": cids[1]}
                if store:
                    conn.execute(
                        "UPDATE cmp_matches SET gg_match_detail = ? WHERE id = ?",
                        (json.dumps(snap), sm["id"]))
                    out["stored"] += 1
                # verify vs frozen result (never overwrite)
                sw = (sm.get("winner_name") or "").strip()
                gw = (d.get("gg_winner_name") or "").strip()
                sm_marg = _cmp_norm_margin(sm.get("margin"))
                gg_marg = _cmp_norm_margin(d.get("gg_margin"))
                # compare on the nickname-robust person key (Matt == Matthew),
                # not raw name tokens, so a spelling variant isn't a mismatch.
                win_ok = (not sw) or (not gw) or \
                    _cmp_person_key(sw) == _cmp_person_key(gw)
                marg_ok = (not sm_marg) or (sm_marg == gg_marg)
                if win_ok and marg_ok:
                    out["aligned"] += 1
                else:
                    out["mismatches"].append(
                        {**tag, "stored_event": sm.get("stored_event"),
                         "stored_winner": sm.get("winner_name"),
                         "stored_margin": sm.get("margin"),
                         "winner_ok": win_ok, "margin_ok": marg_ok})
            # mark the round done only if it finished within budget (a
            # mid-round budget cut leaves it undone so the next call retries).
            if store and monotonic() - started <= time_budget:
                conn.execute("INSERT OR IGNORE INTO cmp_mp_import_rounds "
                             "(host, round_id) VALUES (?, ?)",
                             (parts.netloc, rid))
        if store:
            conn.commit()
        out["rounds_left"] = max(0, len(pending) - out["rounds_done"])
        out["unmatched_count"] = len(out["unmatched"])
        out["mismatch_count"] = len(out["mismatches"])
        return out


def cmp_relabel_margins(updates: list, chapter: str | None = None,
                        apply: bool = False, db_path=None) -> dict:
    """Surgically relabel a match's MARGIN only (e.g. an extra-hole win stored
    as '1 UP' → '10H'). Winner, records, seeding, stableford are untouched.

    updates: [{"players": ["Luke Youngs", "Mike Marques"], "to": "10H",
               "expect_margin": "1 UP", "expect_winner": "Luke Youngs"}].
    Matches by nickname-robust person-key pair, scoped to `chapter` if given.
    Guards: only updates when the current margin/winner match the stated
    expectations (so a stale directive can't clobber the wrong row). Default is
    DRY-RUN (apply=False) — pass apply=True to write. Returns per-update audit
    (before/after, matched id, applied)."""
    out = {"chapter": chapter, "apply": apply, "results": []}
    with _connect(db_path) as conn:
        rows = [dict(r) for r in conn.execute(
            """SELECT m.id, m.player1_name, m.player2_name, m.winner_name,
                      m.margin, m.result_locked_at, e.item_name AS event,
                      p.chapter
                 FROM cmp_matches m
                 JOIN cmp_pools p ON p.id = m.pool_id
                 LEFT JOIN events e ON e.id = m.event_id
                WHERE (? IS NULL OR p.chapter = ?)""",
            (chapter, chapter)).fetchall()]
        index = {}
        for r in rows:
            index.setdefault(
                frozenset([_cmp_person_key(r["player1_name"]),
                           _cmp_person_key(r["player2_name"])]), []).append(r)
        for u in updates:
            pa, pb = u["players"]
            sig = frozenset([_cmp_person_key(pa), _cmp_person_key(pb)])
            cands = index.get(sig, [])
            rec = {"players": [pa, pb], "to": u["to"], "matched": len(cands)}
            if len(cands) != 1:
                rec["status"] = ("no_match" if not cands else "ambiguous")
                out["results"].append(rec); continue
            m = cands[0]
            rec.update({"id": m["id"], "event": m["event"],
                        "before_margin": m["margin"],
                        "winner": m["winner_name"]})
            if m.get("result_locked_at") and not u.get("force"):
                rec["status"] = "locked_skip"
                rec["locked_at"] = m["result_locked_at"]
                out["results"].append(rec); continue
            ok = True
            if u.get("expect_margin") is not None and \
               _cmp_norm_margin(m["margin"]) != _cmp_norm_margin(u["expect_margin"]):
                ok = False; rec["status"] = "margin_mismatch"
            if u.get("expect_winner") is not None and m["winner_name"] and \
               _cmp_person_key(m["winner_name"]) != _cmp_person_key(u["expect_winner"]):
                ok = False; rec["status"] = "winner_mismatch"
            if not ok:
                out["results"].append(rec); continue
            if apply:
                conn.execute("UPDATE cmp_matches SET margin = ? WHERE id = ?",
                             (u["to"], m["id"]))
                if m.get("result_locked_at") and u.get("force"):
                    # forced relabel of a locked row (Kerry-directed): keep the
                    # lock, refresh its note so it documents the final label.
                    conn.execute(
                        "UPDATE cmp_matches SET result_locked_note = ? "
                        "WHERE id = ?",
                        (f"gg-verified 2026: GG card AS after regulation; "
                         f"stored '{u['to']}' is the recorded extra-holes/"
                         f"putt-off outcome (relabeled from "
                         f"'{m['margin']}' per Kerry)", m["id"]))
                rec["status"] = "applied"
            else:
                rec["status"] = "would_apply"
            out["results"].append(rec)
        if apply:
            conn.commit()
    return out


def cmp_lock_verified_results(season: str | None = None,
                              chapter: str | None = None,
                              apply: bool = False, db_path=None) -> dict:
    """Harden GG-verified pool results (Kerry 2026-07-20: 'once we get these
    verified we need to harden these in the database so they don't change
    again'). For every PLAYED match, compare the stored winner/margin against
    the gg_match_detail snapshot (GG's own match card):

      * exact       — GG winner + margin equal stored → lock.
      * as_extra    — GG says AS (all square) and we store a winner with an
                      extra-holes label (Putt Off / 10H / ...) → lock; the
                      hole data can't show a putt-off, the adjudication is
                      Kerry's recorded outcome.
      * no_gg_card  — no snapshot (e.g. a makeup GG never published) → NOT
                      locked automatically; listed for manual review.
      * conflict    — GG's card disagrees with the stored result → NOT
                      locked; listed for Kerry to adjudicate.

    Locking stamps result_locked_at/result_locked_note; already-locked rows
    are left untouched (idempotent). Default is DRY-RUN — apply=True writes."""
    where, params = ["m.played_at IS NOT NULL OR m.winner_name IS NOT NULL"], []
    where = [f"({where[0]})"]
    if season:
        where.append("p.season = ?"); params.append(season)
    if chapter:
        where.append("p.chapter = ?"); params.append(chapter)
    out = {"season": season, "chapter": chapter, "apply": apply,
           "locked": [], "already_locked": 0, "no_gg_card": [],
           "conflicts": []}
    with _connect(db_path) as conn:
        rows = [dict(r) for r in conn.execute(
            f"""SELECT m.*, p.season AS p_season, p.chapter AS p_chapter,
                       p.pool_name, e.item_name AS event_name
                  FROM cmp_matches m
                  JOIN cmp_pools p ON p.id = m.pool_id
                  LEFT JOIN events e ON e.id = m.event_id
                 WHERE {' AND '.join(where)}""", params).fetchall()]
        for m in rows:
            if not m.get("winner_name") and m.get("player1_stableford") is None:
                continue                      # scheduled, no result yet
            label = f"{m['player1_name']} vs {m['player2_name']}"
            tag = {"id": m["id"], "match": label, "event": m.get("event_name"),
                   "pool": m.get("pool_name"), "chapter": m.get("p_chapter"),
                   "stored_winner": m.get("winner_name"),
                   "stored_margin": m.get("margin")}
            if m.get("result_locked_at"):
                out["already_locked"] += 1
                continue
            raw = m.get("gg_match_detail")
            gg = None
            if raw:
                try:
                    gg = json.loads(raw) if isinstance(raw, str) else raw
                except Exception:
                    gg = None
            if not gg:
                out["no_gg_card"].append(tag)
                continue
            gg_margin = _cmp_norm_margin(gg.get("gg_margin"))
            gg_winner = gg.get("gg_winner_name")
            stored_m = _cmp_norm_margin(m.get("margin"))
            stored_w = (m.get("winner_name") or "").strip()
            note = None
            if gg_margin == "AS" and stored_w:
                note = (f"gg-verified 2026: GG card AS after regulation; "
                        f"stored '{m.get('margin')}' is the recorded "
                        f"extra-holes/putt-off outcome")
            elif (stored_m == gg_margin and stored_w and gg_winner and
                  _cmp_person_key(stored_w) == _cmp_person_key(gg_winner)):
                note = "gg-verified 2026: matches GG's own match card exactly"
            elif stored_m == "AS" and gg_margin == "AS" and \
                    not stored_w and not gg_winner:
                # halved pool match (tie allowed in pool play): both sides
                # agree — AS/Tied with no winner on either record.
                note = "gg-verified 2026: halved, matches GG's own match card"
            else:
                out["conflicts"].append(
                    {**tag, "gg_winner": gg_winner, "gg_margin": gg_margin})
                continue
            if apply:
                conn.execute(
                    "UPDATE cmp_matches SET result_locked_at = datetime('now'),"
                    " result_locked_note = ? WHERE id = ?", (note, m["id"]))
            out["locked"].append({**tag, "note": note})
        if apply:
            conn.commit()
    out["locked_count"] = len(out["locked"])
    out["no_gg_card_count"] = len(out["no_gg_card"])
    out["conflict_count"] = len(out["conflicts"])
    return out


def cmp_lock_match_manual(chapter: str, player_a: str, player_b: str,
                          apply: bool = False, note: str | None = None,
                          db_path=None) -> dict:
    """Manually lock ONE played match that cmp_lock_verified_results cannot
    auto-lock because GG never published a match card (no_gg_card class) —
    the result is confirmed by Kerry instead of by GG. Stamps
    result_locked_at + a note recording the Kerry confirmation. Refuses to
    lock a resultless (unplayed) match; already-locked rows are reported,
    not restamped. Default is DRY-RUN — apply=True writes."""
    from .timezone_utils import today_central_str
    out = {"chapter": chapter, "players": [player_a, player_b], "apply": apply}
    sig = frozenset([_cmp_person_key(player_a), _cmp_person_key(player_b)])
    with _connect(db_path) as conn:
        rows = [dict(r) for r in conn.execute(
            """SELECT m.*, p.chapter AS p_chapter, p.pool_name,
                      e.item_name AS event_name
                 FROM cmp_matches m
                 JOIN cmp_pools p ON p.id = m.pool_id
                 LEFT JOIN events e ON e.id = m.event_id
                WHERE p.chapter = ?""", (chapter,)).fetchall()]
        cands = [m for m in rows if frozenset(
            [_cmp_person_key(m["player1_name"]),
             _cmp_person_key(m["player2_name"])]) == sig]
        if len(cands) != 1:
            out["status"] = "no_match" if not cands else "ambiguous"
            out["matched"] = len(cands)
            return out
        m = cands[0]
        out.update({"id": m["id"], "event": m.get("event_name"),
                    "pool": m.get("pool_name"),
                    "stored_winner": m.get("winner_name"),
                    "stored_margin": m.get("margin")})
        if not m.get("winner_name") and m.get("player1_stableford") is None:
            out["status"] = "no_result"
            return out
        if m.get("result_locked_at"):
            out["status"] = "already_locked"
            out["locked_at"] = m["result_locked_at"]
            return out
        stamp_note = note or (
            f"Kerry-confirmed {today_central_str()}, no GG card — stored "
            f"result {m.get('winner_name')} {m.get('margin') or ''} stands")
        out["note"] = stamp_note
        if apply:
            conn.execute(
                "UPDATE cmp_matches SET result_locked_at = datetime('now'),"
                " result_locked_note = ? WHERE id = ?", (stamp_note, m["id"]))
            conn.commit()
            out["status"] = "locked"
        else:
            out["status"] = "would_lock"
    return out


def cmp_clear_match(pool_id: int, player1: str, player2: str,
                    force: bool = False, db_path=None) -> None:
    p1, p2 = sorted([player1, player2])
    with _connect(db_path) as conn:
        if not force:
            row = conn.execute(
                "SELECT result_locked_at FROM cmp_matches WHERE pool_id = ? "
                "AND player1_name = ? AND player2_name = ?",
                (pool_id, p1, p2)).fetchone()
            if row and row["result_locked_at"]:
                raise ValueError(
                    f"match {p1} vs {p2} is result-locked "
                    f"({row['result_locked_at']}); pass force=True to delete")
        conn.execute(
            "DELETE FROM cmp_matches WHERE pool_id = ? AND player1_name = ? AND player2_name = ?",
            (pool_id, p1, p2),
        )
        conn.commit()


def cmp_save_match(pool_id: int, player1: str, player2: str,
                   winner_name: str | None = None,
                   margin: str | None = None,
                   p1_stableford: float | None = None,
                   p2_stableford: float | None = None,
                   match_date: str | None = None, notes: str | None = None,
                   event_id: int | None = None,
                   force: bool = False,
                   db_path=None) -> dict:
    """Upsert a pool match result. Canonical key is (pool_id, sorted player names).

    winner_name  — who won the match play match (traditional result)
    margin       — margin of victory e.g. "1 Up", "5&4", "Putt Off", "Halved"
    p1_stableford / p2_stableford — Stableford points scored independently;
                   loser may outscore winner. Stored per player1_name / player2_name
                   (alphabetical canonical order).
    event_id     — FK to events.id; links the match to a TGF event.

    A row whose result is LOCKED (result_locked_at, GG-verified) refuses any
    change to winner_name/margin: the save is rejected with
    {"blocked": "result_locked"} unless the incoming values equal the stored
    ones (idempotent re-save) or force=True is passed deliberately.
    """
    # Always store names in alphabetical order so UNIQUE constraint is stable
    if player1 > player2:
        player1, player2 = player2, player1
        p1_stableford, p2_stableford = p2_stableford, p1_stableford
        # winner_name stays as-is — it's a name reference, not positional
    played_at_expr = (
        "datetime('now')"
        if (winner_name is not None or p1_stableford is not None or p2_stableford is not None)
        else "NULL"
    )
    with _connect(db_path) as conn:
        if not force:
            ex = conn.execute(
                """SELECT winner_name, margin, result_locked_at
                     FROM cmp_matches WHERE pool_id = ?
                      AND player1_name = ? AND player2_name = ?""",
                (pool_id, player1, player2)).fetchone()
            if ex and ex["result_locked_at"]:
                same_w = _cmp_person_key(winner_name or "") == \
                    _cmp_person_key(ex["winner_name"] or "")
                same_m = _cmp_norm_margin(margin) == _cmp_norm_margin(ex["margin"])
                if not (same_w and same_m):
                    return {"blocked": "result_locked",
                            "locked_at": ex["result_locked_at"],
                            "stored_winner": ex["winner_name"],
                            "stored_margin": ex["margin"],
                            "attempted_winner": winner_name,
                            "attempted_margin": margin}
        conn.execute(
            f"""INSERT INTO cmp_matches
               (pool_id, player1_name, player2_name,
                winner_name, margin, player1_stableford, player2_stableford,
                match_date, notes, event_id, played_at)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, {played_at_expr})
               ON CONFLICT(pool_id, player1_name, player2_name)
               DO UPDATE SET winner_name        = excluded.winner_name,
                             margin             = excluded.margin,
                             player1_stableford = excluded.player1_stableford,
                             player2_stableford = excluded.player2_stableford,
                             match_date         = excluded.match_date,
                             notes              = excluded.notes,
                             event_id           = excluded.event_id,
                             played_at          = {played_at_expr}""",
            (pool_id, player1, player2, winner_name, margin,
             p1_stableford, p2_stableford, match_date, notes, event_id),
        )
        conn.commit()
        row = conn.execute(
            """SELECT m.*, e.item_name AS event_name, e.event_date AS event_date_val
               FROM cmp_matches m
               LEFT JOIN events e ON e.id = m.event_id
               WHERE m.pool_id = ? AND m.player1_name = ? AND m.player2_name = ?""",
            (pool_id, player1, player2),
        ).fetchone()
        return dict(row) if row else {}


def _cmp_apply_wd_sort(standings: list[dict]) -> list[dict]:
    """WD display rule (Kerry ruling 2026-07-20): withdrawn players who
    PLAYED matches sort to the bottom of their pool (tag + played record
    kept — Campos stays visible with WD · INJ); withdrawn players with NO
    played matches disappear from standings entirely (a clean removal +
    refund). Ranks renumber in display order; nothing about points,
    records, or advancement computation changes."""
    out: list[dict] = []
    by_pool: dict = {}
    for row in standings:
        by_pool.setdefault(row.get("pool_id"), []).append(row)
    for pool_rows in by_pool.values():
        kept = []
        for r in pool_rows:
            played = r.get("played")
            if played is None:
                played = (r.get("wins", 0) + r.get("losses", 0)
                          + r.get("draws", 0))
            if r.get("withdrawn") and not played:
                continue
            kept.append(r)
        kept.sort(key=lambda r: (1 if r.get("withdrawn") else 0,
                                 r.get("rank") or 0))
        for i, r in enumerate(kept, 1):
            r["rank"] = i
        out.extend(kept)
    return out


def cmp_get_standings(season: str, chapter: str, db_path=None,
                      advance_per_pool: int = 2) -> list[dict]:
    """Return pool standings for a chapter/season.

    W/L/D is determined by match play winner_name (traditional match play result).
    Stableford points are accumulated independently — a match loser can outscore the winner.
    Advancement (top advance_per_pool, from the versioned config) = W/L/D
    record; tiebreaker = total Stableford points.
    Bracket seeding = total Stableford points across all pool matches.

    D-MP-09 (config-gated): when the season's PINNED config carries
    pool_rank_rule == "dmp09" (ratified 2026-07-16/17, mailbox #215/#217),
    ranking switches to the register rule — every player counts exactly 3
    matches (first-3-by-date; a forced 4th counts only for its opponent),
    rank = match points of 3 (win 1, tie ½, loss 0) → aggregate H2H →
    pool Stableford. Seasons pinned to an older version keep the legacy
    wins → W−L → Stableford sort (past events frozen, Principle 4).
    """
    rule = "legacy"
    try:
        _ac = sct_get_active_config("match_play", season, chapter, db_path=db_path)
        if _ac and (_ac.get("config") or {}).get("pool_rank_rule") == "dmp09":
            rule = "dmp09"
    except Exception:
        rule = "legacy"

    if rule == "dmp09":
        from email_parser.match_play import dmp09_pool_standings
        with _connect(db_path) as conn:
            pools = [dict(p) for p in conn.execute(
                "SELECT id, pool_name FROM cmp_pools WHERE season=? AND chapter=? "
                "ORDER BY pool_name", (season, chapter)).fetchall()]
            members_by_pool = {}
            wd_by_pool = {}   # pool_id -> {name: reason-or-None} for withdrawn
            for pool in pools:
                rows_m = conn.execute(
                    "SELECT customer_name, COALESCE(withdrawn, 0) AS withdrawn, "
                    "withdrawn_reason FROM cmp_pool_members WHERE pool_id=?",
                    (pool["id"],)).fetchall()
                members_by_pool[pool["id"]] = [r["customer_name"] for r in rows_m]
                wd_by_pool[pool["id"]] = {r["customer_name"]: r["withdrawn_reason"]
                                          for r in rows_m if r["withdrawn"]}
        standings = []
        for pool in pools:
            ranked = dmp09_pool_standings(
                members_by_pool[pool["id"]],
                cmp_get_matches(pool["id"], db_path=db_path),
                advance_per_pool=advance_per_pool)
            for r in ranked:
                standings.append({
                    "pool_id": pool["id"], "pool_name": pool["pool_name"],
                    "player_name": r["player_name"], "rank": r["rank"],
                    "wins": r["wins"], "losses": r["losses"], "draws": r["draws"],
                    "stableford_pts": r["stableford"],
                    "match_points": r["points"], "counted": r["counted"],
                    "played": r["played"], "dropped_4th": r["dropped_4th"],
                    "advances": r["advances"],
                    "withdrawn": r["player_name"] in wd_by_pool[pool["id"]],
                    "withdrawn_reason": wd_by_pool[pool["id"]].get(r["player_name"]),
                })
        return _cmp_apply_wd_sort(standings)

    with _connect(db_path) as conn:
        pools = conn.execute(
            "SELECT id, pool_name FROM cmp_pools WHERE season = ? AND chapter = ? ORDER BY pool_name",
            (season, chapter),
        ).fetchall()
        standings = []
        for pool in pools:
            pid = pool["id"]
            members = conn.execute(
                "SELECT customer_name FROM cmp_pool_members WHERE pool_id = ?", (pid,)
            ).fetchall()
            wd_names = {r["customer_name"]: r["withdrawn_reason"]
                        for r in conn.execute(
                "SELECT customer_name, withdrawn_reason FROM cmp_pool_members "
                "WHERE pool_id = ? AND COALESCE(withdrawn, 0) = 1", (pid,)
            ).fetchall()}
            matches = conn.execute(
                "SELECT * FROM cmp_matches WHERE pool_id = ? AND played_at IS NOT NULL",
                (pid,),
            ).fetchall()

            stats = {m["customer_name"]: {"wins": 0, "losses": 0, "draws": 0, "pts": 0.0}
                     for m in members}

            for match in matches:
                p1, p2 = match["player1_name"], match["player2_name"]
                winner = match["winner_name"]
                margin = match["margin"] or ""
                s1 = match["player1_stableford"]
                s2 = match["player2_stableford"]

                for name in (p1, p2):
                    if name not in stats:
                        stats[name] = {"wins": 0, "losses": 0, "draws": 0, "pts": 0.0}

                # Accumulate Stableford points independently
                stats[p1]["pts"] += s1 or 0
                stats[p2]["pts"] += s2 or 0

                # W/L/D from match play result
                halved = margin.strip().lower() in ("halved", "all square", "as")
                if halved or winner is None:
                    if winner is None and s1 is None and s2 is None:
                        pass  # not yet played
                    else:
                        stats[p1]["draws"] += 1
                        stats[p2]["draws"] += 1
                elif winner == p1:
                    stats[p1]["wins"] += 1
                    stats[p2]["losses"] += 1
                elif winner == p2:
                    stats[p2]["wins"] += 1
                    stats[p1]["losses"] += 1

            pool_rows = sorted(
                stats.items(),
                key=lambda x: (-x[1]["wins"], -(x[1]["wins"] - x[1]["losses"]), -x[1]["pts"]),
            )
            for rank, (name, s) in enumerate(pool_rows, 1):
                standings.append({
                    "pool_id": pid,
                    "pool_name": pool["pool_name"],
                    "player_name": name,
                    "rank": rank,
                    "wins": s["wins"],
                    "losses": s["losses"],
                    "draws": s["draws"],
                    "stableford_pts": round(s["pts"], 1),
                    "advances": rank <= advance_per_pool,
                    "withdrawn": name in wd_names,
                    "withdrawn_reason": wd_names.get(name),
                })
        return _cmp_apply_wd_sort(standings)


def cmp_get_bracket(season: str, chapter: str, db_path=None) -> list[dict]:
    with _connect(db_path) as conn:
        # Join the linked event so the bracket carries a member-safe course +
        # event name (the /api/events list is view-only+; members can't fetch
        # it to resolve event_id → course themselves). Kerry 2026-07-19.
        rows = conn.execute(
            """SELECT b.*, e.item_name AS event_name, e.course AS event_course,
                      e.event_date AS event_date
               FROM cmp_bracket b
               LEFT JOIN events e ON e.id = b.event_id
               WHERE b.season = ? AND b.chapter = ?
               ORDER BY b.round, b.slot""",
            (season, chapter),
        ).fetchall()
        out = [dict(r) for r in rows]
        # Par row feed for the expanded knockout scorecards (Kerry
        # 2026-07-21) — same per-event map the pool matches carry.
        # Self-healing event link (Kerry's Austin catch, same day): when
        # the manager never linked an event to a bracket match, the
        # hardened GG detail still knows the round's event CODE
        # ("a9.18") — resolve it to the Tracker event so par + the
        # course·date header work without manual linking. Read-time
        # only; the row's stored event_id is untouched.
        _pc: dict = {}
        for b in out:
            ev_id = b.get("event_id")
            if not ev_id and b.get("gg_match_detail"):
                try:
                    _det = json.loads(b["gg_match_detail"]) \
                        if isinstance(b["gg_match_detail"], str) \
                        else (b["gg_match_detail"] or {})
                    _code = (_det.get("gg_event") or "").strip()
                except Exception:
                    _code = ""
                if _code:
                    _ev = conn.execute(
                        "SELECT id, item_name, course, event_date FROM events "
                        "WHERE item_name LIKE ? COLLATE NOCASE "
                        "ORDER BY event_date DESC LIMIT 1",
                        (_code + " %",)).fetchone()
                    if _ev:
                        ev_id = _ev["id"]
                        if not b.get("event_name"):
                            b["event_name"] = _ev["item_name"]
                        if not b.get("event_course"):
                            b["event_course"] = _ev["course"]
                        if not b.get("event_date"):
                            b["event_date"] = _ev["event_date"]
            b["hole_pars"] = _cmp_hole_pars_for_event(conn, ev_id, _pc)
        return out


def cmp_standings_diff_dmp09(db_path=None, advance_per_pool: int = 2) -> dict:
    """READ-ONLY (#217 step 1). Recompute every chapter/season's pool
    standings under the ratified D-MP-09 rule (first-3-by-date counting,
    match points-of-3 with ½-ties, aggregate H2H) and DIFF against the
    CURRENT live standings (wins → W−L → Stableford, all matches) that
    were used to seed the knockouts. Changes nothing.

    Kerry's expectation is CLEAN — no advancer or seed-order change. A
    row 'moves' only matters if it flips advancement (top-2) or the
    winner/runner-up order (which sets the P1 seed tier). Anything that
    moves is a documentation decision; the live bracket stands.

    Returns per (season, chapter): per-pool old vs new order, whether
    advancers or the winner/runner-up pair changed, the full row detail,
    and the seeded-bracket occupants for cross-check. Top-level
    `verdict` is 'clean' iff no advancer/winner-runnerup change anywhere.
    """
    from email_parser.match_play import dmp09_pool_standings

    out = {"verdict": "clean", "chapters": [], "moves": []}
    with _connect(db_path) as conn:
        pairs = conn.execute(
            "SELECT DISTINCT season, chapter FROM cmp_pools ORDER BY season, chapter"
        ).fetchall()

    for pr in pairs:
        season, chapter = pr["season"], pr["chapter"]
        old = cmp_get_standings(season, chapter, db_path=db_path,
                                advance_per_pool=advance_per_pool)
        old_by_pool: dict = {}
        for r in old:
            old_by_pool.setdefault(r["pool_name"], []).append(r)

        bracket = cmp_get_bracket(season, chapter, db_path=db_path)
        seeded = sorted(
            [{"seed": b.get("player_seed"), "name": b.get("player_name"),
              "wildcard": b.get("is_wildcard"), "round": b.get("round"),
              "slot": b.get("slot")}
             for b in bracket if b.get("player_name")
             and b.get("player_seed") is not None],
            key=lambda x: x["seed"])

        ch = {"season": season, "chapter": chapter, "pools": [],
              "seeded_bracket": seeded}
        with _connect(db_path) as conn:
            pools = [dict(p) for p in conn.execute(
                "SELECT id, pool_name FROM cmp_pools WHERE season=? AND chapter=? "
                "ORDER BY pool_name", (season, chapter)).fetchall()]
            members_by_pool = {}
            for pool in pools:
                members_by_pool[pool["id"]] = [
                    r["customer_name"] for r in conn.execute(
                        "SELECT customer_name FROM cmp_pool_members WHERE pool_id=?",
                        (pool["id"],)).fetchall()]
        for pool in pools:
            members = members_by_pool[pool["id"]]
            matches = cmp_get_matches(pool["id"], db_path=db_path)
            new = dmp09_pool_standings(members, matches,
                                       advance_per_pool=advance_per_pool)
            old_rows = old_by_pool.get(pool["pool_name"], [])
            old_order = [r["player_name"] for r in
                         sorted(old_rows, key=lambda r: r["rank"])]
            new_order = [r["player_name"] for r in new]
            old_adv = {r["player_name"] for r in old_rows if r["advances"]}
            new_adv = {r["player_name"] for r in new if r["advances"]}
            old_top2 = old_order[:2]
            new_top2 = new_order[:2]
            advancers_changed = old_adv != new_adv
            winner_runnerup_swapped = old_top2 != new_top2

            old_rank = {r["player_name"]: r["rank"] for r in old_rows}
            rows = []
            for r in new:
                nm = r["player_name"]
                rows.append({
                    "player": nm,
                    "old_rank": old_rank.get(nm),
                    "new_rank": r["rank"],
                    "moved": old_rank.get(nm) != r["rank"],
                    "points_of_3": r["points"],
                    "record": f'{r["wins"]}-{r["losses"]}-{r["draws"]}',
                    "stableford": r["stableford"],
                    "played": r["played"], "counted": r["counted"],
                    "dropped_4th": r["dropped_4th"],
                    "advances_new": r["advances"],
                    "advances_old": nm in old_adv,
                })
            pool_out = {
                "pool": pool["pool_name"],
                "old_order": old_order, "new_order": new_order,
                "advancers_changed": advancers_changed,
                "winner_runnerup_swapped": winner_runnerup_swapped,
                "has_4match_player": any(r["dropped_4th"] for r in new),
                "rows": rows,
            }
            ch["pools"].append(pool_out)
            if advancers_changed or winner_runnerup_swapped:
                out["verdict"] = "review"
                out["moves"].append({
                    "season": season, "chapter": chapter,
                    "pool": pool["pool_name"],
                    "advancers_changed": advancers_changed,
                    "winner_runnerup_swapped": winner_runnerup_swapped,
                    "old_order": old_order, "new_order": new_order,
                })
        out["chapters"].append(ch)
    return out


def cmp_save_bracket_slot(season: str, chapter: str, round_: str, slot: int,
                           player_name: str | None = None,
                           player_stableford: float | None = None,
                           opponent_name: str | None = None,
                           opponent_stableford: float | None = None,
                           winner_name: str | None = None,
                           margin: str | None = None,
                           event_id: int | None = None,
                           db_path=None) -> dict:
    with _connect(db_path) as conn:
        conn.execute(
            """INSERT INTO cmp_bracket
               (season, chapter, round, slot,
                player_name, player_stableford,
                opponent_name, opponent_stableford,
                winner_name, margin, event_id)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(season, chapter, round, slot)
               DO UPDATE SET player_name         = excluded.player_name,
                             player_stableford   = excluded.player_stableford,
                             opponent_name       = excluded.opponent_name,
                             opponent_stableford = excluded.opponent_stableford,
                             winner_name         = excluded.winner_name,
                             margin              = excluded.margin,
                             event_id            = excluded.event_id,
                             -- seed/WC chips belong to the occupant: keep
                             -- them on a result re-save, clear them when a
                             -- different player lands in the slot (IS is
                             -- SQLite's NULL-safe equality)
                             player_seed = CASE WHEN excluded.player_name IS player_name
                                                THEN player_seed ELSE NULL END,
                             is_wildcard = CASE WHEN excluded.player_name IS player_name
                                                THEN is_wildcard ELSE NULL END""",
            (season, chapter, round_, slot,
             player_name, player_stableford,
             opponent_name, opponent_stableford,
             winner_name, margin, event_id),
        )
        # Principle 6: resolve ids AT WRITE TIME, every save. The upsert
        # above keeps stale ids when a different player lands in a slot,
        # and nothing else wrote winner_id at all — the boot backfill only
        # runs at deploy time, so the LSC CITY MATCH PLAY seat stayed
        # 'to be decided' after Kerry recorded the Austin final
        # (2026-08-01: "didn't populate the Lone Star Cup position with
        # the champion"). Unresolvable names store NULL, never a guess.
        ids = {}
        for id_col, val in (("player_id", player_name),
                            ("opponent_id", opponent_name),
                            ("winner_id", winner_name)):
            cid = None
            if val:
                try:
                    cid = _lookup_customer_id(conn, val, None)
                except Exception:
                    cid = None
            ids[id_col] = cid
        conn.execute(
            "UPDATE cmp_bracket SET player_id = ?, opponent_id = ?, "
            "winner_id = ? WHERE season = ? AND chapter = ? AND round = ? "
            "AND slot = ?",
            (ids["player_id"], ids["opponent_id"], ids["winner_id"],
             season, chapter, round_, slot))
        conn.commit()
        row = conn.execute(
            "SELECT * FROM cmp_bracket WHERE season = ? AND chapter = ? AND round = ? AND slot = ?",
            (season, chapter, round_, slot),
        ).fetchone()
        return dict(row) if row else {}


def cmp_clear_bracket(season: str, chapter: str, db_path=None) -> int:
    """Delete all bracket slots for a given season + chapter. Returns rows deleted."""
    with _connect(db_path) as conn:
        cur = conn.execute(
            "DELETE FROM cmp_bracket WHERE season = ? AND chapter = ?",
            (season, chapter),
        )
        conn.commit()
        return cur.rowcount


# ---------------------------------------------------------------------------
# Season-Contest Config Templates (Game Creator engine, v2.34.0)
# ---------------------------------------------------------------------------
# Versioned, admin-editable config per the payout_templates pattern. The
# structure/payout RULES for a contest live in config_json (never in code);
# email_parser/match_play.py is the pure engine that evaluates them. A
# season+chapter gets pinned to a version via
# season_contest_config_snapshots on its first structural action, so
# template edits never rewrite a season in flight (Guiding Principle 4).

MATCH_PLAY_TEMPLATE_NAME = "City Match Play"


def _seed_match_play_template(conn: sqlite3.Connection) -> None:
    """Boot seed (idempotent): City Match Play v1 from the ratified matrix."""
    from email_parser.match_play import SEED_MATCH_PLAY_CONFIG

    row = conn.execute(
        "SELECT id, current_version_id FROM season_contest_templates "
        "WHERE kind = 'match_play' AND archived = 0 ORDER BY id LIMIT 1"
    ).fetchone()
    if row and row["current_version_id"]:
        return
    if row:
        template_id = row["id"]
    else:
        cur = conn.execute(
            "INSERT INTO season_contest_templates (name, kind, notes, created_by) "
            "VALUES (?, 'match_play', ?, 'boot-seed')",
            (MATCH_PLAY_TEMPLATE_NAME,
             "Structure + payouts for the City Match Play season contest."),
        )
        template_id = cur.lastrowid
    next_no = (conn.execute(
        "SELECT COALESCE(MAX(version_no), 0) + 1 FROM season_contest_versions "
        "WHERE template_id = ?", (template_id,)
    ).fetchone()[0])
    cur = conn.execute(
        "INSERT INTO season_contest_versions "
        "(template_id, version_no, config_json, saved_by, notes) "
        "VALUES (?, ?, ?, 'boot-seed', ?)",
        (template_id, next_no, json.dumps(SEED_MATCH_PLAY_CONFIG),
         "Seeded from Prizes-Match Play Matrix.xlsx (July 6 final)"),
    )
    conn.execute(
        "UPDATE season_contest_templates SET current_version_id = ? WHERE id = ?",
        (cur.lastrowid, template_id),
    )
    conn.commit()
    logger.info("Seeded '%s' config template v%d", MATCH_PLAY_TEMPLATE_NAME, next_no)


def sct_get_active_config(kind: str, season: str | None = None,
                          chapter: str | None = None, db_path=None) -> dict | None:
    """Resolve the config a season runs under: snapshot first, else current.

    Returns {template_id, template_name, version_id, version_no, config,
    snapshotted, snapped_at} or None if no template exists.
    """
    with _connect(db_path) as conn:
        t = conn.execute(
            "SELECT * FROM season_contest_templates "
            "WHERE kind = ? AND archived = 0 ORDER BY id LIMIT 1", (kind,)
        ).fetchone()
        if not t:
            return None
        snap = None
        if season and chapter:
            snap = conn.execute(
                "SELECT * FROM season_contest_config_snapshots "
                "WHERE season = ? AND chapter = ? AND template_id = ?",
                (season, chapter, t["id"]),
            ).fetchone()
        version_id = snap["version_id"] if snap else t["current_version_id"]
        if not version_id:
            return None
        v = conn.execute(
            "SELECT * FROM season_contest_versions WHERE id = ?", (version_id,)
        ).fetchone()
        if not v:
            return None
        return {
            "template_id": t["id"],
            "template_name": t["name"],
            "version_id": v["id"],
            "version_no": v["version_no"],
            "config": json.loads(v["config_json"]),
            "snapshotted": bool(snap),
            "snapped_at": snap["snapped_at"] if snap else None,
        }


def sct_list_versions(kind: str, db_path=None) -> list[dict]:
    """Version history (meta only — fetch config via sct_get_version)."""
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT v.id, v.version_no, v.saved_at, v.saved_by, v.notes,
                      (v.id = t.current_version_id) AS is_current
               FROM season_contest_versions v
               JOIN season_contest_templates t ON t.id = v.template_id
               WHERE t.kind = ? AND t.archived = 0
               ORDER BY v.version_no DESC""",
            (kind,),
        ).fetchall()
        return [dict(r) for r in rows]


def sct_get_version(version_id: int, db_path=None) -> dict | None:
    with _connect(db_path) as conn:
        v = conn.execute(
            "SELECT * FROM season_contest_versions WHERE id = ?", (version_id,)
        ).fetchone()
        if not v:
            return None
        out = dict(v)
        out["config"] = json.loads(out.pop("config_json"))
        return out


def sct_save_version(kind: str, config: dict, saved_by: str | None = None,
                     notes: str | None = None, db_path=None) -> dict:
    """Append a new config version and make it current.

    Validates match_play configs by evaluating every N in the configured
    range — a config that can't produce a structure or whose ladder doesn't
    sum to the adjusted pot is rejected (raises ValueError).
    """
    if kind == "match_play":
        from email_parser.match_play import structure_for_n
        n_min = int(config.get("n_min", 4))
        n_max = int(config.get("n_max", 32))
        for n in range(n_min, n_max + 1):
            s = structure_for_n(config, n)  # raises on missing N
            if sum(s["ladder_amounts_cents"]) != s["adjusted_pot_cents"]:
                raise ValueError(
                    f"N={n}: ladder sums to "
                    f"{sum(s['ladder_amounts_cents']) / 100:.2f}, expected "
                    f"adjusted pot {s['adjusted_pot_cents'] / 100:.2f}"
                )
            if not s["ladder_pcts"] and not config.get(
                    "amount_overrides", {}).get(str(n)):
                raise ValueError(f"N={n}: no ladder band or amount override")
            if len(s["ladder_amounts_cents"]) < 2:
                raise ValueError(f"N={n}: ladder must pay at least 2 places")
    with _connect(db_path) as conn:
        t = conn.execute(
            "SELECT id FROM season_contest_templates "
            "WHERE kind = ? AND archived = 0 ORDER BY id LIMIT 1", (kind,)
        ).fetchone()
        if not t:
            raise ValueError(f"No template of kind '{kind}'")
        next_no = conn.execute(
            "SELECT COALESCE(MAX(version_no), 0) + 1 FROM season_contest_versions "
            "WHERE template_id = ?", (t["id"],)
        ).fetchone()[0]
        cur = conn.execute(
            "INSERT INTO season_contest_versions "
            "(template_id, version_no, config_json, saved_by, notes) "
            "VALUES (?, ?, ?, ?, ?)",
            (t["id"], next_no, json.dumps(config), saved_by, notes),
        )
        conn.execute(
            "UPDATE season_contest_templates SET current_version_id = ? WHERE id = ?",
            (cur.lastrowid, t["id"]),
        )
        conn.commit()
        return {"version_id": cur.lastrowid, "version_no": next_no}


def sct_ensure_snapshot(kind: str, season: str, chapter: str,
                        by: str | None = None, db_path=None) -> dict | None:
    """Pin (season, chapter) to the template's CURRENT version if not pinned.

    Called by structural actions (auto-assign pools, seed bracket) so the
    season's rules freeze at first use. No-op if already pinned.
    """
    with _connect(db_path) as conn:
        t = conn.execute(
            "SELECT id, current_version_id FROM season_contest_templates "
            "WHERE kind = ? AND archived = 0 ORDER BY id LIMIT 1", (kind,)
        ).fetchone()
        if not t or not t["current_version_id"]:
            return None
        conn.execute(
            """INSERT INTO season_contest_config_snapshots
               (season, chapter, template_id, version_id, snapped_by)
               VALUES (?, ?, ?, ?, ?)
               ON CONFLICT(season, chapter, template_id) DO NOTHING""",
            (season, chapter, t["id"], t["current_version_id"], by),
        )
        conn.commit()
        snap = conn.execute(
            "SELECT * FROM season_contest_config_snapshots "
            "WHERE season = ? AND chapter = ? AND template_id = ?",
            (season, chapter, t["id"]),
        ).fetchone()
        return dict(snap) if snap else None


def sct_pin_snapshot(kind: str, season: str, chapter: str,
                     version_id: int | None = None, by: str | None = None,
                     db_path=None) -> dict:
    """Admin re-pin: point a season/chapter at a specific (or current) version."""
    with _connect(db_path) as conn:
        t = conn.execute(
            "SELECT id, current_version_id FROM season_contest_templates "
            "WHERE kind = ? AND archived = 0 ORDER BY id LIMIT 1", (kind,)
        ).fetchone()
        if not t:
            raise ValueError(f"No template of kind '{kind}'")
        vid = version_id or t["current_version_id"]
        v = conn.execute(
            "SELECT id FROM season_contest_versions WHERE id = ? AND template_id = ?",
            (vid, t["id"]),
        ).fetchone()
        if not v:
            raise ValueError(f"Version {vid} does not belong to this template")
        conn.execute(
            """INSERT INTO season_contest_config_snapshots
               (season, chapter, template_id, version_id, snapped_by)
               VALUES (?, ?, ?, ?, ?)
               ON CONFLICT(season, chapter, template_id)
               DO UPDATE SET version_id = excluded.version_id,
                             snapped_at = datetime('now'),
                             snapped_by = excluded.snapped_by""",
            (season, chapter, t["id"], vid, by),
        )
        conn.commit()
        snap = conn.execute(
            "SELECT * FROM season_contest_config_snapshots "
            "WHERE season = ? AND chapter = ? AND template_id = ?",
            (season, chapter, t["id"]),
        ).fetchone()
        return dict(snap)


def cmp_repin_2026_to_dmp_register(by: str | None = None, db_path=None) -> dict:
    """RE-PIN (#223, Kerry-approved 2026-07-17). Author a new match_play
    config version carrying the ratified D-MP-01→09 register as rules-as-data,
    then pin every 2026 season/chapter that has pools to it.

    The new version overlays the register flags onto the current base config
    (ladders/structure unchanged — sct_save_version re-validates every N):
      - pool_rank_rule = 'dmp09'       (D-MP-09; honored live by cmp_get_standings)
      - pool_assignment_mode = 'random' (D-MP-03 default)
      - seed_placement = 'p1_p4'       (D-MP-04 P1–P4; seeding-code adoption tracked)
      - consolation {min_n, primary, fallback} (D-MP-08)
      - tie_policy stays 'split_combined_places' (the D-MP-08 fallback)
      - seeding_knockout4 stays 'cross_pool' (the unchanged 4-player exception)

    Idempotent-safe: re-running authors another version and re-pins to it;
    the pin is a pointer, snapshots update in place. Returns the new
    version id/no and the list of pinned (season, chapter). Only pins 2026.
    """
    base = sct_get_active_config("match_play", db_path=db_path)
    if not base:
        raise ValueError("No match_play template/config found")
    cfg = dict(base["config"])  # shallow copy of the current base
    cfg["pool_rank_rule"] = "dmp09"
    cfg.setdefault("pool_assignment_mode", "random")
    cfg["pool_assignment_mode"] = "random"
    cfg["seed_placement"] = "p1_p4"
    cfg["seeding_knockout4"] = cfg.get("seeding_knockout4", "cross_pool")
    cfg["tie_policy"] = cfg.get("tie_policy", "split_combined_places")
    cfg["consolation"] = {
        "min_field_n": 6,          # no consolation at N=4–5
        "primary": "match",         # SF losers play to decide 3rd vs 4th/none
        "fallback": "split_combined_places",  # split place money if uncoordinated
    }
    cfg["dmp_register"] = "D-MP-01..09 (2026-07-16/17)"

    saved = sct_save_version(
        "match_play", cfg, saved_by=by or "tracker-claude (#223 re-pin)",
        notes="D-MP-01..09 register: D-MP-09 pool counting/rank (live), "
              "D-MP-03 random default, D-MP-04 P1–P4 seed placement, "
              "D-MP-08 consolation+fallback. Re-pin approved by Kerry #223.",
        db_path=db_path)
    vid = saved["version_id"]

    with _connect(db_path) as conn:
        pairs = [dict(r) for r in conn.execute(
            "SELECT DISTINCT season, chapter FROM cmp_pools WHERE season = '2026' "
            "ORDER BY chapter").fetchall()]
    pinned = []
    for pr in pairs:
        snap = sct_pin_snapshot("match_play", pr["season"], pr["chapter"],
                                version_id=vid, by=by or "tracker-claude",
                                db_path=db_path)
        pinned.append({"season": pr["season"], "chapter": pr["chapter"],
                       "version_id": snap["version_id"],
                       "snapped_at": snap.get("snapped_at")})
    return {"version_id": vid, "version_no": saved["version_no"],
            "pinned": pinned, "config_flags": {
                "pool_rank_rule": cfg["pool_rank_rule"],
                "pool_assignment_mode": cfg["pool_assignment_mode"],
                "seed_placement": cfg["seed_placement"],
                "seeding_knockout4": cfg["seeding_knockout4"],
                "consolation": cfg["consolation"],
                "tie_policy": cfg["tie_policy"]}}


def cmp_encode_uniform_allowance(value: float = 0.75, by: str | None = None,
                                 apply: bool = False, db_path=None) -> dict:
    """Encode the FUTURE uniform match-play handicap allowance as config
    data (Kerry-ratified 2026-07-20: 'Stored as a setting is our standard
    for everything. I want ultimate control to turn the dials').

    Authors a new match_play config version carrying
    `handicap_allowance = {basis: off_lowest, value: <v>, adjustable:
    true}` plus the historical GG-era per-chapter facts for the record
    (SA 75% / Austin 100% — the reconcilers keep using those for
    GG-originated events; past frozen). Does NOT re-pin 2026 — its
    snapshots stay on their pinned version; seasons created after this
    snapshot the new current version. Default DRY-RUN."""
    base = sct_get_active_config("match_play", db_path=db_path)
    if not base:
        return {"error": "No match_play template/config found"}
    if not (0 < float(value) <= 1):
        return {"error": f"allowance must be in (0, 1]: {value}"}
    cfg = dict(base["config"])
    cfg["handicap_allowance"] = {
        "basis": "off_lowest",       # lower plays scratch (D-MP-10)
        "value": float(value),       # ONE dial for ALL chapters
        "adjustable": True,
        "historical_gg_by_chapter": {"San Antonio": 0.75, "Austin": 1.0},
        "ratified": "Kerry 2026-07-20 (design 2026-07-17, D-MP-10)",
    }
    out = {"apply": apply, "base_version_no": base["version_no"],
           "handicap_allowance": cfg["handicap_allowance"]}
    if not apply:
        out["note"] = "dry-run — pass apply to author the config version"
        return out
    saved = sct_save_version(
        "match_play", cfg,
        saved_by=by or "tracker-claude (allowance encode)",
        notes="D-MP-10 uniform allowance dial: one adjustable off-lowest "
              "allowance for all chapters (default 75%). Kerry-ratified "
              "2026-07-20. 2026 snapshots NOT re-pinned (past frozen).",
        db_path=db_path)
    out.update({"version_id": saved["version_id"],
                "version_no": saved["version_no"], "pinned": "unchanged"})
    return out


# ---------------------------------------------------------------------------
# City Match Play — config-driven operations (auto-assign, seeding, payouts)
# ---------------------------------------------------------------------------

def cmp_enrolled_entrants(season: str, chapter: str, db_path=None) -> list[dict]:
    """Deduped City Match Play entrants for a chapter/season.

    Dedup by customer_id first (Principle 6), then by canonical-name
    fallback for legacy rows without one. Names resolve to the canonical
    customers.customer_name so pool members match standings rows.
    """
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT sc.id, sc.customer_name, sc.customer_id,
                      c.first_name || ' ' || c.last_name AS canonical_name
               FROM season_contests sc
               LEFT JOIN customers c ON c.customer_id = sc.customer_id
               WHERE sc.contest_type = 'City Match Play'
                 AND sc.season = ?
                 AND (sc.chapter IS NULL OR sc.chapter = '' OR sc.chapter = ?)
               ORDER BY sc.enrolled_at""",
            (season, chapter),
        ).fetchall()
    seen_ids, seen_names, out = set(), set(), []
    for r in rows:
        name = r["canonical_name"] or r["customer_name"]
        if not name:
            continue
        if r["customer_id"]:
            # customer_id is the identity — two DIFFERENT ids that share a
            # name are two real entrants and must both count (Principle 6).
            if r["customer_id"] in seen_ids:
                continue
            seen_ids.add(r["customer_id"])
            seen_names.add(name.lower())
        else:
            # Legacy id-less row: name is all we have to dedup on.
            if name.lower() in seen_names:
                continue
            seen_names.add(name.lower())
        out.append({"customer_name": name, "customer_id": r["customer_id"],
                    "enrollment_id": r["id"]})
    return out


def cmp_auto_assign_pools(season: str, chapter: str, created_by: str | None = None,
                          force: bool = False, db_path=None) -> dict:
    """Create pools per the versioned matrix and randomly assign entrants.

    Pool count and balanced sizes come from the active config for N
    enrolled. Refuses to wipe pools that already have recorded match
    results unless force=True. Pins the season's config snapshot.
    """
    import random

    active = sct_get_active_config("match_play", season, chapter, db_path=db_path)
    if not active:
        raise ValueError("No Match Play config template found")
    from email_parser.match_play import pool_sizes, structure_for_n

    entrants = cmp_enrolled_entrants(season, chapter, db_path=db_path)
    n = len(entrants)
    structure = structure_for_n(active["config"], n)  # raises if N out of range

    with _connect(db_path) as conn:
        played = conn.execute(
            """SELECT COUNT(*) FROM cmp_matches m
               JOIN cmp_pools p ON p.id = m.pool_id
               WHERE p.season = ? AND p.chapter = ? AND m.played_at IS NOT NULL""",
            (season, chapter),
        ).fetchone()[0]
        if played and not force:
            raise ValueError(
                f"{played} pool match result(s) already recorded for "
                f"{chapter} {season} — auto-assign would destroy them. "
                "Rearrange manually instead."
            )
        old = conn.execute(
            "SELECT id FROM cmp_pools WHERE season = ? AND chapter = ?",
            (season, chapter),
        ).fetchall()
        for p in old:
            conn.execute("DELETE FROM cmp_matches WHERE pool_id = ?", (p["id"],))
            conn.execute("DELETE FROM cmp_pool_members WHERE pool_id = ?", (p["id"],))
            conn.execute("DELETE FROM cmp_pools WHERE id = ?", (p["id"],))

        shuffled = list(entrants)
        random.shuffle(shuffled)
        sizes = pool_sizes(n, structure["pools"])
        pools_out, idx = [], 0
        for i, size in enumerate(sizes):
            pool_name = f"Pool {chr(65 + i)}"
            cur = conn.execute(
                "INSERT INTO cmp_pools (season, chapter, pool_name) VALUES (?, ?, ?)",
                (season, chapter, pool_name),
            )
            pool_id = cur.lastrowid
            members = shuffled[idx: idx + size]
            idx += size
            for m in members:
                conn.execute(
                    "INSERT INTO cmp_pool_members (pool_id, customer_name, customer_id) "
                    "VALUES (?, ?, ?)",
                    (pool_id, m["customer_name"], m["customer_id"]),
                )
            pools_out.append({"pool_name": pool_name, "size": size,
                              "members": [m["customer_name"] for m in members]})
        conn.commit()

    sct_ensure_snapshot("match_play", season, chapter, by=created_by, db_path=db_path)
    return {"n": n, "structure": structure, "pools": pools_out}


def _cmp_seed_metric(row: dict) -> tuple:
    """Seeding order: most Stableford points across pool matches (ratified),
    tiebreak wins, then name for determinism."""
    return (-(row.get("stableford_pts") or 0), -(row.get("wins") or 0),
            row.get("player_name") or "")


def cmp_seed_knockout(season: str, chapter: str, created_by: str | None = None,
                      force: bool = False, db_path=None) -> dict:
    """Server-side knockout seeding per the versioned config.

    Advancers = top advance_per_pool per pool (pool rank). Wildcards = best
    remaining by the seeding metric, cross-pool. Global seeds by the same
    metric; standard single-elim placement; first-round byes resolve
    automatically (12-bracket → top 4 seeds skip round 1). Refuses to
    overwrite a bracket that already has results unless force=True.
    """
    active = sct_get_active_config("match_play", season, chapter, db_path=db_path)
    if not active:
        raise ValueError("No Match Play config template found")
    from email_parser.match_play import (cross_pool_semi_order, seed_bracket,
                                         structure_for_n)

    entrants = cmp_enrolled_entrants(season, chapter, db_path=db_path)
    n = len(entrants)
    structure = structure_for_n(active["config"], n)

    standings = cmp_get_standings(season, chapter, db_path=db_path)
    if not standings:
        raise ValueError("No pool standings yet — assign pools and record matches first.")

    warnings = []
    adv = [r for r in standings if r["rank"] <= structure["advance_per_pool"]]
    rest = [r for r in standings if r["rank"] > structure["advance_per_pool"]]
    wc_count = structure["wildcards"]
    wildcards = sorted(rest, key=_cmp_seed_metric)[:wc_count]
    wc_names = {w["player_name"] for w in wildcards}
    field = adv + wildcards
    if len(field) < structure["knockout"]:
        warnings.append(
            f"Only {len(field)} qualifiers for a {structure['knockout']}-player "
            "bracket — extra byes will be created."
        )
    played_any = any((r.get("wins") or r.get("losses") or r.get("draws"))
                     for r in standings)
    if not played_any:
        warnings.append("No pool matches recorded yet — seeding is arbitrary.")

    # 4-player knockout from two pools = CROSS-POOL semis (Kerry
    # 2026-07-14): winner of one pool vs the 2nd-place finisher of the
    # other. Stableford does NOT seed this bracket — it only breaks
    # record ties in pool finishes (already applied in pool rank).
    seeding_mode = "stableford"
    seeded = None
    if (structure["knockout"] == 4 and wc_count == 0
            and active["config"].get("seeding_knockout4", "cross_pool")
            == "cross_pool"):
        adv_by_pool: dict = {}
        for r in adv:
            adv_by_pool.setdefault(r["pool_name"], []).append(r)
        pools_adv = [sorted(rows, key=lambda r: r["rank"])
                     for _, rows in sorted(adv_by_pool.items())]
        if len(pools_adv) == 2 and all(len(p) >= 2 for p in pools_adv):
            seeded = cross_pool_semi_order(pools_adv[0], pools_adv[1])
            seeding_mode = "cross_pool"
        else:
            warnings.append(
                "Cross-pool semis need two pools with two advancers each "
                "— fell back to Stableford seeding.")
    if seeded is None:
        seeded = sorted(field, key=_cmp_seed_metric)
    if len(field) < 2:
        raise ValueError("Not enough qualifiers to seed a knockout — need at least 2.")
    entrant_rows = [
        {"player_name": r["player_name"],
         "stableford": r.get("stableford_pts") or 0,
         "is_wildcard": 1 if r["player_name"] in wc_names else 0}
        for r in seeded
    ]
    plan = seed_bracket(entrant_rows, structure["knockout"])
    if plan["bye_placements"] and len(plan["rounds"]) < 2:
        # 2-player template with a bye = only one qualifier reached the
        # bracket; there is no next round to place the bye into.
        raise ValueError("Not enough qualifiers to seed a knockout — need at least 2.")

    # name → customer_id from pool membership (Principle 6)
    with _connect(db_path) as conn:
        existing = conn.execute(
            "SELECT COUNT(*) FROM cmp_bracket "
            "WHERE season = ? AND chapter = ? AND winner_name IS NOT NULL",
            (season, chapter),
        ).fetchone()[0]
        if existing and not force:
            raise ValueError(
                f"The bracket already has {existing} recorded result(s) — "
                "re-seeding would destroy them."
            )
        id_map = {r["customer_name"]: r["customer_id"] for r in conn.execute(
            """SELECT pm.customer_name, pm.customer_id FROM cmp_pool_members pm
               JOIN cmp_pools p ON p.id = pm.pool_id
               WHERE p.season = ? AND p.chapter = ?""",
            (season, chapter),
        ).fetchall()}

        conn.execute("DELETE FROM cmp_bracket WHERE season = ? AND chapter = ?",
                     (season, chapter))
        seed_no = {e["player_name"]: i + 1 for i, e in enumerate(entrant_rows)}

        def _insert(round_, slot, player):
            conn.execute(
                """INSERT INTO cmp_bracket
                   (season, chapter, round, slot, player_name,
                    player_stableford, player_id, player_seed, is_wildcard)
                   VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)""",
                (season, chapter, round_, slot, player["player_name"],
                 player["stableford"], id_map.get(player["player_name"]),
                 seed_no[player["player_name"]], player["is_wildcard"]),
            )

        rounds = plan["rounds"]
        for entry in plan["first_round"]:
            _insert(rounds[0], entry["slot"], entry["player"])
        for entry in plan["bye_placements"]:
            _insert(rounds[1], entry["slot"], entry["player"])
        conn.commit()

    sct_ensure_snapshot("match_play", season, chapter, by=created_by, db_path=db_path)
    return {
        "n": n,
        "structure": structure,
        "rounds": plan["rounds"],
        "seeding_mode": seeding_mode,
        "seeds": [{"seed": i + 1, **e} for i, e in enumerate(entrant_rows)],
        "byes": [e["player"]["player_name"] for e in plan["bye_placements"]],
        "warnings": warnings,
    }


def cmp_get_payout_sheet(season: str, chapter: str, db_path=None) -> dict:
    """The money view: pot, pool-winner bonuses, ladder places, tie splits.

    Every dollar figure comes from the versioned config via the engine —
    nothing hard-coded. Bonus winners are pool standings leaders (marked
    provisional until the bracket is seeded); ladder places fill in from
    bracket results (champion, runner-up, semifinal losers split combined
    places per tie_policy).
    """
    from email_parser.match_play import split_cents, structure_for_n

    active = sct_get_active_config("match_play", season, chapter, db_path=db_path)
    if not active:
        return {"error": "No Match Play config template found"}
    entrants = cmp_enrolled_entrants(season, chapter, db_path=db_path)
    n = len(entrants)
    try:
        structure = structure_for_n(active["config"], n)
    except ValueError as e:
        return {"error": str(e), "n": n,
                "config_version": active["version_no"],
                "snapshotted": active["snapshotted"]}

    standings = cmp_get_standings(season, chapter, db_path=db_path)
    bracket = cmp_get_bracket(season, chapter, db_path=db_path)
    bracket_seeded = bool(bracket)

    # ── Pool winner bonuses ──
    by_pool: dict = {}
    for r in standings:
        by_pool.setdefault(r["pool_name"], []).append(r)
    bonus_rows = []
    for pool_name in sorted(by_pool):
        rows = by_pool[pool_name]
        leader = min(rows, key=lambda r: r["rank"])
        has_results = any((r["wins"] or r["losses"] or r["draws"]) for r in rows)
        bonus_rows.append({
            "pool_name": pool_name,
            "player_name": leader["player_name"] if has_results else None,
            "amount": structure["pool_winner_bonus_each"],
            "status": "final" if (has_results and bracket_seeded) else "projected",
        })

    # ── Ladder places from bracket results ──
    def match_players(round_key):
        """[(player_a, player_b, winner), …] per match of a bracket round."""
        rows = [b for b in bracket if b["round"] == round_key]
        slots = {b["slot"]: b for b in rows}
        out = []
        for mi in range(0, (max(slots) // 2 + 1) if slots else 0):
            a = slots.get(mi * 2)
            b = slots.get(mi * 2 + 1)
            names = [x["player_name"] for x in (a, b) if x and x["player_name"]]
            winner = next((x["winner_name"] for x in (a, b)
                           if x and x["winner_name"]), None)
            if names:
                out.append((names, winner))
        return out

    finals = match_players("final")
    champion = runner_up = None
    if finals:
        names, winner = finals[0]
        if winner:
            champion = winner
            runner_up = next((x for x in names if x != winner), None)
    sf_losers = []
    for names, winner in match_players("sf"):
        if winner:
            sf_losers.extend(x for x in names if x != winner)

    amounts = structure["ladder_amounts_cents"]
    ladder_rows = []
    if amounts:
        ladder_rows.append({"place_label": "1st", "player_name": champion,
                            "amount": amounts[0] / 100.0,
                            "status": "final" if champion else "tbd"})
    if len(amounts) >= 2:
        ladder_rows.append({"place_label": "2nd", "player_name": runner_up,
                            "amount": amounts[1] / 100.0,
                            "status": "final" if runner_up else "tbd"})
    # ── D-MP-08 (ratified 2026-07-16, config v2): the two SF losers' 3rd/4th
    # is decided by a CONSOLATION MATCH (primary) at N≥6; if it can't be
    # coordinated (no recorded result), FALLBACK to splitting the combined
    # place money. N=4–5 has only 2 ladder places, so this block never runs
    # there ("nothing at N=4–5" is automatic). The consolation is stored as a
    # single bracket row (round='consolation', player+opponent+winner).
    conso_row = next((b for b in bracket if b["round"] == "consolation"), None)
    conso_winner = conso_row["winner_name"] if conso_row else None
    conso_loser = None
    if conso_row:
        for x in (conso_row.get("player_name"), conso_row.get("opponent_name")):
            if x and x != conso_winner:
                conso_loser = x
    if len(amounts) > 2:
        losers = sorted(sf_losers)[:2]
        if conso_winner:
            # Consolation played: winner takes 3rd outright; on a 4-place
            # ladder the loser takes 4th, on a 3-place ladder the loser gets
            # nothing.
            ladder_rows.append({"place_label": "3rd", "player_name": conso_winner,
                                "amount": amounts[2] / 100.0, "status": "final",
                                "via": "consolation"})
            if len(amounts) >= 4:
                ladder_rows.append({"place_label": "4th",
                                    "player_name": conso_loser,
                                    "amount": amounts[3] / 100.0,
                                    "status": "final" if conso_loser else "tbd",
                                    "via": "consolation"})
        else:
            # FALLBACK — split the combined place money between the two SF
            # losers (3-place: 3rd split 10/10 · 4-place: 3rd+4th split
            # 12.5/12.5). Split by the expected two so a lone recorded loser
            # never shows the full combined amount.
            combined = sum(amounts[2:4])
            label = "3rd" if len(amounts) == 3 else "3rd–4th (T)"
            shares = split_cents(combined, 2)
            for i, cents in enumerate(shares):
                name = losers[i] if i < len(losers) else None
                ladder_rows.append({"place_label": label, "player_name": name,
                                    "amount": cents / 100.0,
                                    "status": "final" if name else "tbd",
                                    "via": "fallback_split"})
    # Any configured places beyond 4th still render (TBD) so the sheet
    # always sums to the pot even under a nonstandard admin config.
    for idx in range(4, len(amounts)):
        ladder_rows.append({"place_label": f"{idx + 1}th", "player_name": None,
                            "amount": amounts[idx] / 100.0, "status": "tbd"})

    warnings = []
    with _connect(db_path) as conn:
        chapterless = conn.execute(
            """SELECT COUNT(*) FROM season_contests
               WHERE contest_type = 'City Match Play' AND season = ?
                 AND (chapter IS NULL OR chapter = '')""",
            (season,),
        ).fetchone()[0]
    if chapterless:
        warnings.append(
            f"{chapterless} enrollment(s) have no chapter and are counted in "
            "every chapter's field — set their chapter on the Enrollment tab."
        )
    pool_member_count = sum(len(v) for v in by_pool.values())
    if by_pool and pool_member_count != n:
        warnings.append(
            f"{n} enrolled but {pool_member_count} in pools — pot is based "
            "on enrollment."
        )
    # D-MP-08 consolation state for the UI: applies at N≥6 (a 3rd place
    # exists), both SF losers known once the semis are decided.
    has_consolation = n >= int(active["config"].get(
        "consolation", {}).get("min_field_n", 6)) and len(amounts) > 2
    return {
        "n": n,
        "structure": structure,
        "config_version": active["version_no"],
        "snapshotted": active["snapshotted"],
        "bonus_rows": bonus_rows,
        "ladder_rows": ladder_rows,
        "bracket_seeded": bracket_seeded,
        "consolation": {
            "applies": has_consolation,
            "sf_losers": sorted(sf_losers)[:2],
            "winner": conso_winner,
            "recorded": conso_row is not None and conso_winner is not None,
            "places": len(amounts),   # 3 → 3rd vs nothing · 4 → 3rd vs 4th
        },
        "warnings": warnings,
    }


def cmp_record_consolation(season: str, chapter: str,
                           loser_a: str, loser_b: str,
                           winner_name: str | None = None,
                           margin: str | None = None,
                           by: str | None = None, db_path=None) -> dict:
    """D-MP-08: record (or clear) the 3rd-place consolation match between the
    two semifinal losers. Stored as ONE cmp_bracket row (round='consolation',
    slot 0: player_name=loser_a, opponent_name=loser_b, winner_name). Passing
    winner_name=None clears the result → the payout sheet reverts to the
    fallback split. winner must be one of the two losers. customer_ids are
    resolved from pool membership (Principle 6)."""
    a, b = (loser_a or "").strip(), (loser_b or "").strip()
    if not a or not b or a == b:
        raise ValueError("consolation needs two distinct semifinal losers")
    w = (winner_name or "").strip() or None
    if w is not None and w not in (a, b):
        raise ValueError("consolation winner must be one of the two losers")
    with _connect(db_path) as conn:
        idmap = {r["customer_name"]: r["customer_id"] for r in conn.execute(
            """SELECT pm.customer_name, pm.customer_id FROM cmp_pool_members pm
               JOIN cmp_pools p ON p.id = pm.pool_id
               WHERE p.season = ? AND p.chapter = ?""",
            (season, chapter)).fetchall()}
        conn.execute(
            """INSERT INTO cmp_bracket
                 (season, chapter, round, slot, player_name, player_id,
                  opponent_name, opponent_id, winner_name, winner_id, margin)
               VALUES (?, ?, 'consolation', 0, ?, ?, ?, ?, ?, ?, ?)
               ON CONFLICT(season, chapter, round, slot)
               DO UPDATE SET player_name=excluded.player_name,
                             player_id=excluded.player_id,
                             opponent_name=excluded.opponent_name,
                             opponent_id=excluded.opponent_id,
                             winner_name=excluded.winner_name,
                             winner_id=excluded.winner_id,
                             margin=excluded.margin""",
            (season, chapter, a, idmap.get(a), b, idmap.get(b),
             w, idmap.get(w) if w else None, margin))
        conn.commit()
    return {"season": season, "chapter": chapter, "loser_a": a, "loser_b": b,
            "winner": w, "cleared": w is None}


# ---------------------------------------------------------------------------
# App Settings — persistent key/value store (survives Railway redeploys)
# ---------------------------------------------------------------------------

def get_app_setting(key: str, db_path: str | Path | None = None) -> str | None:
    """Return a single app setting value, or None if not set."""
    with _connect(db_path) as conn:
        row = conn.execute("SELECT value FROM app_settings WHERE key = ?", (key,)).fetchone()
    return row["value"] if row else None


def set_app_setting(key: str, value: str, db_path: str | Path | None = None) -> None:
    """Upsert a single app setting."""
    with _connect(db_path) as conn:
        conn.execute(
            "INSERT INTO app_settings (key, value, updated_at) VALUES (?, ?, datetime('now')) "
            "ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = datetime('now')",
            (key, value),
        )
        conn.commit()


