# TGF Payouts
# ---------------------------------------------------------------------------

def _repair_tgf_payout_shells(conn: sqlite3.Connection) -> None:
    """Merge shell customers minted by the pre-v2.49.0
    _resolve_customer_for_payout comma-split bug (GG "LAST, First Suffix"
    names → first="Victor Jr"/last="Arias" shells, one per recording
    pass). For every acquisition_source='tgf_payout' customer with no
    items, no emails, and no handicap links, re-resolve the name through
    the scoring spine; if it lands on a DIFFERENT customer, repoint
    tgf_payouts rows there and delete the shell. Idempotent — clean
    databases fall straight through."""
    shells = conn.execute(
        """SELECT c.customer_id,
                  TRIM(COALESCE(c.first_name,'') || ' ' || COALESCE(c.last_name,'')) AS nm
             FROM customers c
            WHERE c.acquisition_source = 'tgf_payout'
              AND NOT EXISTS (SELECT 1 FROM items i WHERE i.customer_id = c.customer_id)
              AND NOT EXISTS (SELECT 1 FROM customer_emails ce WHERE ce.customer_id = c.customer_id)
              AND NOT EXISTS (SELECT 1 FROM handicap_player_links hl WHERE hl.customer_id = c.customer_id)
        """).fetchall()
    if not shells:
        return
    merged = 0
    for s in shells:
        nm = (s["nm"] or "").strip()
        if not nm:
            continue
        # Reconstruct the GG form the recorder saw ("Victor Jr Arias" came
        # from "ARIAS, Victor Jr") and let the scoring spine resolve it;
        # also try the name as-is.
        target = _resolve_scoring_player(conn, nm)
        if target is None:
            parts = nm.split()
            if len(parts) >= 2:
                target = _resolve_scoring_player(
                    conn, f"{parts[-1].upper()}, {' '.join(parts[:-1])}")
        if target is None or target == s["customer_id"]:
            continue
        conn.execute("UPDATE tgf_payouts SET customer_id = ? WHERE customer_id = ?",
                     (target, s["customer_id"]))
        conn.execute("DELETE FROM customer_aliases WHERE customer_id = ?",
                     (s["customer_id"],))
        conn.execute("DELETE FROM customers WHERE customer_id = ?",
                     (s["customer_id"],))
        merged += 1
        logger.info("Merged tgf_payout shell %d ('%s') into customer %d",
                    s["customer_id"], nm, target)
    if merged:
        conn.commit()
        logger.info("Payout shell repair: merged %d shell customers", merged)


def _resolve_customer_for_payout(conn: sqlite3.Connection, name: str) -> int:
    """Return customer_id for a payout entry, creating a customer if needed.

    Handles both "First Last" and "LAST, First" formats (the latter is common
    in tournament leaderboard screenshots).

    Uses the same resolution cascade as email parsing (_lookup_customer_id):
    exact name, alias, etc.  If the raw name doesn't match, tries the reversed
    "LAST, First" → "First Last" interpretation.  If no customer matches,
    creates one from the normalized name with acquisition_source='tgf_payout'.

    Raises ValueError if the name is empty or cannot be parsed into first+last.
    """
    if not name or not name.strip():
        raise ValueError("Cannot resolve payout customer: name is empty")

    clean_name = name.strip()

    # GG-format resolution FIRST (v2.49.0): payout names come from Golf
    # Genius results tables as "ARIAS, Victor Jr" — the scoring spine
    # (_resolve_scoring_player: curated handicap_player_links map + full
    # name-candidate expansion incl. suffixes) already resolves exactly
    # these strings. The old comma-split alone turned "ARIAS, Victor Jr"
    # into first="Victor Jr"/last="Arias", missed the real customer
    # (first="Victor", suffix="Jr"), and minted a fresh shell customer on
    # EVERY recording pass (the Arias duplicate-shell bug, 2026-07-08).
    cid = _resolve_scoring_player(conn, clean_name)
    if cid is not None:
        return cid

    # Detect and normalize "LAST, First" format
    if "," in clean_name:
        parts = [p.strip() for p in clean_name.split(",", 1)]
        if len(parts) == 2 and parts[0] and parts[1]:
            # "CAMPOS, Roland" → first="Roland", last="Campos"
            normalized_first = parts[1].title()
            normalized_last = parts[0].title()
            normalized_name = f"{normalized_first} {normalized_last}"

            # Try normalized name first (most likely to match existing customer)
            cid = _lookup_customer_id(conn, normalized_name, None)
            if cid is not None:
                return cid

            # Also try the raw format in case it was stored that way
            cid = _lookup_customer_id(conn, clean_name, None)
            if cid is not None:
                return cid

            # Last guard before creating: an identical first+last already
            # created by a previous pass (the lookup cascade can miss its
            # own mis-split shells — never mint the same shell twice)
            row = conn.execute(
                """SELECT customer_id FROM customers
                   WHERE LOWER(first_name) = LOWER(?)
                     AND LOWER(last_name) = LOWER(?) LIMIT 1""",
                (normalized_first, normalized_last)).fetchone()
            if row:
                return row["customer_id"]

            # Create customer using the properly-ordered name
            cur = conn.execute(
                """INSERT INTO customers
                       (first_name, last_name, account_status, acquisition_source)
                   VALUES (?, ?, 'active', 'tgf_payout')""",
                (normalized_first, normalized_last),
            )
            new_cid = cur.lastrowid
            logger.info("Created customer %d for payout entry '%s' (normalized: %s)",
                        new_cid, clean_name, normalized_name)
            return new_cid

    # Standard "First Last" format
    cid = _lookup_customer_id(conn, clean_name, None)
    if cid is not None:
        return cid

    row = conn.execute(
        """SELECT customer_id FROM customers
           WHERE LOWER(TRIM(COALESCE(first_name,'') || ' ' || COALESCE(last_name,'')))
                 = LOWER(?) LIMIT 1""", (clean_name,)).fetchone()
    if row:
        return row["customer_id"]

    parts = clean_name.split()
    if len(parts) >= 2:
        first = parts[0]
        last = " ".join(parts[1:])
    else:
        first = clean_name
        last = "(Unknown)"
    cur = conn.execute(
        """INSERT INTO customers
               (first_name, last_name, account_status, acquisition_source)
           VALUES (?, ?, 'active', 'tgf_payout')""",
        (first, last),
    )
    new_cid = cur.lastrowid
    logger.info("Created customer %d for payout entry '%s'", new_cid, clean_name)
    return new_cid


def _seed_customer_payment_methods(conn: sqlite3.Connection) -> None:
    """Boot seed (idempotent): non-Venmo payment methods Kerry named
    (2026-07-07). Only sets payment_method when it's empty — an admin
    edit always wins. Handles stay NULL until supplied (the Payouts tab
    shows 'add handle' until then); Zelle uses the member's known
    phone/email at pay time, no deep link exists."""
    wanted = [
        ("Don", "Sharitz", "paypal"),
        ("Brian", "Thompson", "cashapp"),
        ("Gus", "Vasquez", "zelle"),
        ("Michelle", "DelCarmen", "zelle"),
        ("Michelle", "Del Carmen", "zelle"),   # name-spacing variant
    ]
    for first, last, method in wanted:
        rows = conn.execute(
            "SELECT customer_id, payment_method FROM customers "
            "WHERE LOWER(first_name) = LOWER(?) AND LOWER(REPLACE(last_name, ' ', '')) = LOWER(REPLACE(?, ' ', ''))",
            (first, last)).fetchall()
        if len(rows) != 1:
            if len(rows) > 1:
                logger.info("Payment-method seed: '%s %s' ambiguous (%d) — skipping",
                            first, last, len(rows))
            continue
        if rows[0]["payment_method"]:
            continue
        conn.execute("UPDATE customers SET payment_method = ? WHERE customer_id = ?",
                     (method, rows[0]["customer_id"]))
        logger.info("Payment-method seed: %s %s -> %s", first, last, method)
    conn.commit()


def get_tgf_data(db_path=None):
    """Return all customers with payouts and events with payouts.

    Returns {customers: [...], events: [...], winnings: {customer_id: {...}}}.
    """
    with _connect(db_path) as conn:
        # Customers who have received payouts
        customers = [dict(r) for r in conn.execute(
            """SELECT DISTINCT c.customer_id as id,
                      TRIM(c.first_name || ' ' || c.last_name || COALESCE(' ' || NULLIF(TRIM(c.suffix), ''), '')) as name,
                      c.venmo_username, c.payment_method, c.payment_handle,
                      c.chapter
               FROM customers c
               JOIN tgf_payouts p ON p.customer_id = c.customer_id
               ORDER BY c.last_name, c.first_name"""
        ).fetchall()]

        events = []
        for ev in conn.execute("SELECT * FROM tgf_events ORDER BY event_date DESC").fetchall():
            ev_dict = dict(ev)
            payouts = []
            for p in conn.execute(
                """SELECT p.*,
                          TRIM(c.first_name || ' ' || c.last_name || COALESCE(' ' || NULLIF(TRIM(c.suffix), ''), '')) as customer_name,
                          t.source as txn_source,
                          COALESCE(t.status, 'active') as txn_status
                   FROM tgf_payouts p
                   JOIN customers c ON c.customer_id = p.customer_id
                   LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
                   WHERE p.event_id = ?
                   ORDER BY p.amount DESC""",
                (ev["id"],),
            ).fetchall():
                pd = dict(p)
                # Derive payment status
                if pd.get("acct_transaction_id") is None:
                    pd["payment_status"] = "unwired"  # pre-Step 3 legacy
                elif pd.get("txn_source") == "pending":
                    pd["payment_status"] = "pending"
                elif pd.get("txn_source") == "venmo":
                    pd["payment_status"] = "paid"
                else:
                    pd["payment_status"] = "paid"  # any other ledger link counts as paid
                payouts.append(pd)
            ev_dict["payouts"] = payouts
            events.append(ev_dict)

        # Compute all-time winnings per customer who has received at least one payout
        winnings = {}
        for row in conn.execute(
            """SELECT c.customer_id as id,
                      TRIM(c.first_name || ' ' || c.last_name || COALESCE(' ' || NULLIF(TRIM(c.suffix), ''), '')) as name,
                      c.venmo_username, c.payment_method, c.payment_handle,
                      c.chapter,
                      COALESCE(SUM(p.amount), 0) as total_winnings,
                      COUNT(DISTINCT p.event_id) as events_played
               FROM customers c
               JOIN tgf_payouts p ON p.customer_id = c.customer_id
               GROUP BY c.customer_id
               ORDER BY total_winnings DESC"""
        ).fetchall():
            winnings[row["id"]] = dict(row)

        # Total events PLAYED per golfer (Kerry 2026-07-28: show overall
        # participation next to the paying-events average). Counted from
        # registrations: distinct real golf events (event_type='event',
        # not cancelled) whose date has passed, where the golfer holds a
        # live registration (active or rsvp_only — credited/refunded/
        # transferred rows mean they withdrew).
        played = {r["cid"]: r["n"] for r in conn.execute(
            """SELECT i.customer_id AS cid, COUNT(DISTINCT i.event_id) AS n
               FROM items i
               JOIN events e ON e.id = i.event_id
               WHERE i.customer_id IS NOT NULL
                 AND COALESCE(i.archived, 0) = 0
                 AND COALESCE(i.transaction_status, 'active') IN ('active', 'rsvp_only')
                 AND COALESCE(e.event_type, 'event') = 'event'
                 AND COALESCE(e.status, 'active') = 'active'
                 AND e.event_date IS NOT NULL AND e.event_date <= ?
               GROUP BY i.customer_id""",
            (today_central_str(),)).fetchall()}
        for w in winnings.values():
            # A golfer can hold payouts for more events than registrations
            # cover (pre-tracker history) — never report played < paying.
            w["events_entered"] = max(played.get(w["id"], 0),
                                      w["events_played"] or 0)

        # Overpaid winnings needing a REQUEST back (v2.141.0) — rendered as
        # its own section on the Unpaid work queue.
        try:
            _ensure_tgf_overpayments(conn)
            overpayments = [dict(r) for r in conn.execute(
                """SELECT o.*, e.code AS event_code, e.name AS event_name,
                          e.event_date,
                          TRIM(c.first_name || ' ' || c.last_name) AS customer_name,
                          c.venmo_username
                   FROM tgf_overpayments o
                   LEFT JOIN tgf_events e ON e.id = o.event_id
                   LEFT JOIN customers c ON c.customer_id = o.customer_id
                   WHERE o.status = 'open'
                   ORDER BY o.created_at DESC""").fetchall()]
        except Exception:
            logger.exception("overpayments fetch failed")
            overpayments = []

        return {"customers": customers, "events": events, "winnings": winnings,
                "overpayments": overpayments}


def add_tgf_event(data: dict, db_path=None) -> dict:
    """Add a new TGF event with payouts.

    data: {code, name, event_date, course, chapter, total_purse, winners_count, payouts: [{golferName, category, amount, description}]}
    """
    with _connect(db_path) as conn:
        # Check for duplicate
        existing = conn.execute("SELECT id FROM tgf_events WHERE code = ?", (data["code"],)).fetchone()
        if existing:
            return {"error": f"Event {data['code']} already exists", "event_id": existing["id"]}

        conn.execute(
            """INSERT INTO tgf_events (code, name, event_date, course, chapter, total_purse, winners_count, payouts_count)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
            (data["code"], data["name"], data["event_date"], data.get("course", ""),
             data.get("chapter", ""), data.get("total_purse", 0),
             data.get("winners_count", 0), len(data.get("payouts", []))),
        )
        event_id = conn.execute("SELECT last_insert_rowid()").fetchone()[0]

        new_payout_ids: list[int] = []
        for p in data.get("payouts", []):
            customer_id = _resolve_customer_for_payout(conn, p["golferName"])
            cur = conn.execute(
                """INSERT INTO tgf_payouts (event_id, customer_id, category, amount, description)
                   VALUES (?, ?, ?, ?, ?)""",
                (event_id, customer_id, p["category"], p["amount"], p.get("description", "")),
            )
            new_payout_ids.append(cur.lastrowid)

        # Wire new payouts to the ledger + match existing Venmo payments
        matched = 0
        if new_payout_ids:
            placeholders = ",".join("?" * len(new_payout_ids))
            new_rows = conn.execute(
                f"""SELECT p.id, p.event_id, p.customer_id, p.amount, p.category, p.description,
                           e.event_date, e.name as event_name
                    FROM tgf_payouts p
                    JOIN tgf_events e ON e.id = p.event_id
                    WHERE p.id IN ({placeholders})""",
                new_payout_ids,
            ).fetchall()
            matched = _reconcile_payouts_with_venmo(conn, new_rows)

        conn.commit()
        return {
            "event_id": event_id,
            "payouts_added": len(data.get("payouts", [])),
            "matched": matched,
        }


def _repair_tgf_event_bare_codes(conn: sqlite3.Connection) -> None:
    """Boot repair (idempotent): tgf_events rows created by early v2.38.0
    with a bare code ("s9.15") get the full event name as code, matching
    the convention every consumer keys on. Skips when another row already
    owns the full-name code."""
    for r in conn.execute(
            "SELECT id, code, name FROM tgf_events "
            "WHERE name != code AND code NOT LIKE '% %'").fetchall():
        if not re.fullmatch(r"[sa]\d+(\.\d+)?", (r["code"] or "").strip(), re.I):
            continue
        clash = conn.execute(
            "SELECT 1 FROM tgf_events WHERE LOWER(code) = ? AND id != ?",
            ((r["name"] or "").strip().lower(), r["id"])).fetchone()
        if clash or not (r["name"] or "").strip():
            continue
        conn.execute("UPDATE tgf_events SET code = ? WHERE id = ?",
                     (r["name"].strip(), r["id"]))
        logger.info("tgf_events code repair: '%s' -> '%s'", r["code"], r["name"])
    conn.commit()


def _load_games_matrix(db_path=None) -> tuple[dict, dict]:
    """The LIVE side-games prize matrix (9h, 18h): app_settings copy that
    the Matrix UI edits, falling back to the repo seed (fresh DBs)."""
    m9 = get_app_setting("games_matrix_9", db_path=db_path)
    m18 = get_app_setting("games_matrix_18", db_path=db_path)
    if m9 and m18:
        return json.loads(m9), json.loads(m18)
    root = Path(__file__).resolve().parent.parent
    content = (root / "static" / "js" / "games-matrix.js").read_text()
    s9 = re.search(r"window\.GAMES_MATRIX_9\s*=\s*(\{.*?\});", content, re.DOTALL)
    s18 = re.search(r"window\.GAMES_MATRIX_18\s*=\s*(\{.*?\});", content, re.DOTALL)
    return json.loads(s9.group(1)), json.loads(s18.group(1))


def _matrix_num(v) -> float:
    if v in (None, "", "NO_GAME", "NO_EVENT"):
        return 0.0
    try:
        return float(v)
    except (TypeError, ValueError):
        return 0.0


def _event_player_counts(conn, event_name: str) -> dict:
    """Server-side mirror of the Games tab's computeGameStats: parent
    items only; credited/refunded/transferred out; rsvp_overrides
    'not_playing' out; wd rows counted per un-credited bundle; rsvp_only
    counts toward total only. (Synthetic RSVP-only rows that exist only
    in Golf Genius — no purchase — are not counted here; they are rare
    on past events and the Games-tab UI remains the correction path.)"""
    names = [event_name]
    names += [r["alias_name"] for r in conn.execute(
        "SELECT alias_name FROM event_aliases WHERE canonical_event_name = ? COLLATE NOCASE",
        (event_name,)).fetchall() if r["alias_name"]]
    ph = ",".join("?" for _ in names)
    rows = [dict(r) for r in conn.execute(
        f"SELECT id, parent_item_id, side_games, wd_credits, "
        f"       COALESCE(transaction_status,'active') AS ts "
        f"FROM items WHERE LOWER(item_name) IN ({ph})",
        [n.lower() for n in names]).fetchall()]
    try:
        overrides = {r["item_id"] for r in conn.execute(
            "SELECT item_id FROM rsvp_overrides WHERE event_name = ? COLLATE NOCASE "
            "AND status = 'not_playing'", (event_name,)).fetchall()}
    except sqlite3.OperationalError:
        overrides = set()
    kids = {}
    for r in rows:
        if r["parent_item_id"]:
            kids.setdefault(str(r["parent_item_id"]), []).append(r)
    total = net = gross = 0
    parents = [r for r in rows if not r["parent_item_id"]]
    not_playing = 0
    for r in parents:
        if r["id"] in overrides or r["ts"] in ("credited", "refunded", "transferred"):
            not_playing += 1
            continue
        t = _classify_side_games_type(r["side_games"])
        has_net = t in ("NET", "BOTH")
        has_gross = t in ("GROSS", "BOTH")
        for c in kids.get(str(r["id"]), []):
            ct = _classify_side_games_type(c["side_games"])
            has_net = has_net or ct in ("NET", "BOTH")
            has_gross = has_gross or ct in ("GROSS", "BOTH")
        if r["ts"] == "wd":
            try:
                wd = json.loads(r["wd_credits"] or "{}")
            except (TypeError, ValueError):
                wd = {}
            if "included_games" in wd:
                not_playing += 1
            if "net_games" not in wd and has_net:
                net += 1
            if "gross_games" not in wd and has_gross:
                gross += 1
            continue
        if r["ts"] == "rsvp_only":
            continue
        if has_net:
            net += 1
        if has_gross:
            gross += 1
    total = len(parents) - not_playing
    return {"players": total, "net": net, "gross": gross}


def _rows_from_place_ladder(ranking: list, amounts: list, category: str,
                            label: str) -> list[dict]:
    """Payout rows from a ranked flight + place-money array, golf tie
    rule (tied players split the combined money of the places they
    jointly occupy), exact cents."""
    from email_parser.match_play import split_cents
    cents = [round(_matrix_num(a) * 100) for a in amounts]
    by_pos: dict = {}
    for r in ranking or []:
        by_pos.setdefault(r["position"], []).append(r)
    rows = []
    for pos in sorted(by_pos):
        grp = by_pos[pos]
        pool = sum(cents[pos - 1: pos - 1 + len(grp)])
        if pool <= 0:
            continue
        shares = split_cents(pool, len(grp))
        suffix = {1: "1st", 2: "2nd", 3: "3rd"}.get(pos, f"{pos}th")
        for r, c in zip(grp, shares):
            if c > 0:
                rows.append({"golferName": r["player"], "category": category,
                             "amount": c / 100.0,
                             "description": f"{label} {suffix}"
                                            + (" (T)" if len(grp) > 1 else "")})
    return rows


def rainout_audit(db_path=None) -> dict:
    """Find UNLABELED shut-down events (Kerry 2026-07-20: 'We had other
    rain outs. They need to be labeled as such.').

    Every past event with its shutdown signals: status/badge, registration
    count, credited/WD/refunded count + ratio, and recorded payout rows.
    `candidates` = ACTIVE-status events whose credited ratio ≥ 50%
    (deliberately wider than the 75% payout backstop so Kerry reviews the
    gray zone) — he confirms which were true washouts, then each gets its
    badge via scoring-rainout-label."""
    from email_parser.timezone_utils import today_central_str
    out_events, candidates = [], []
    with _connect(db_path) as conn:
        for ev in conn.execute(
                """SELECT id, item_name, event_date,
                          COALESCE(status,'active') AS status, status_badge
                     FROM events
                    WHERE event_date IS NOT NULL AND event_date <= ?
                    ORDER BY event_date""",
                (today_central_str(),)).fetchall():
            r = conn.execute(
                """SELECT COUNT(*) AS total,
                          SUM(CASE WHEN LOWER(COALESCE(transaction_status,''))
                                   IN ('wd','credited','refunded')
                                   THEN 1 ELSE 0 END) AS credited
                     FROM items WHERE item_name = ? COLLATE NOCASE""",
                (ev["item_name"],)).fetchone()
            total, credited = r["total"] or 0, r["credited"] or 0
            full = ev["item_name"].strip()
            m = _GG_EVENT_CODE_COMPOUND_RE.match(full)
            bare = m.group(1).lower() if m else full.lower()
            prow = conn.execute(
                """SELECT COUNT(*) AS n FROM tgf_payouts p
                    JOIN tgf_events te ON te.id = p.event_id
                   WHERE LOWER(te.code) IN (?, ?)""",
                (full.lower(), bare)).fetchone()
            row = {"event": full, "date": ev["event_date"],
                   "status": ev["status"], "badge": ev["status_badge"],
                   "registrations": total, "credited": credited,
                   "credited_ratio": round(credited / total, 2) if total else 0,
                   "payout_rows": prow["n"] or 0}
            out_events.append(row)
            if ev["status"] == "active" and total >= 4 and \
                    credited >= 0.5 * total:
                candidates.append(row)
    return {"events_checked": len(out_events), "candidates": candidates,
            "already_labeled": [e for e in out_events
                                if e["status"] != "active"],
            "all": out_events}


def label_event_rainout(event_name: str, badge: str = "RAINED OUT",
                        apply: bool = False, db_path=None) -> dict:
    """Stamp a shut-down event with its cancelled status + badge (the
    authoritative everything-is-shut-down signal the payout/HIO guards
    read). Kerry-directed per event; dry-run default."""
    with _connect(db_path) as conn:
        ev = conn.execute(
            "SELECT id, item_name, COALESCE(status,'active') AS status, "
            "status_badge FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
    if not ev:
        return {"error": f"event not found: {event_name}"}
    out = {"event": ev["item_name"], "current_status": ev["status"],
           "current_badge": ev["status_badge"], "badge": badge,
           "apply": apply}
    if badge.strip().lower() in ("clear", "none"):
        # Un-badge a mislabeled event (Kerry 2026-07-20: on 4/21 only the
        # Austin event was a rain out — s9.6's cancellation was something
        # else). Status is kept; only the badge is removed, so the
        # status-based payout/HIO guards stay in force.
        if apply:
            with _connect(db_path) as conn:
                conn.execute(
                    "UPDATE events SET status_badge = NULL WHERE id = ?",
                    (ev["id"],))
                conn.commit()
            out["applied"] = True
            out["badge"] = None
        else:
            out["note"] = "dry-run — pass apply to clear the badge"
        return out
    if ev["status"] != "active" and ev["status_badge"]:
        out["note"] = "already labeled"
        return out
    if apply:
        # active → cancel + badge; already cancelled but badge-less
        # (the a9.6/s9.6/s9.11 class) → re-stamp keeping the status.
        status = ev["status"] if ev["status"] != "active" else "cancelled"
        ok = set_event_status(ev["id"], status,
                              reason=f"{badge} — labeled via rain-out audit",
                              badge=badge, db_path=db_path)
        out["applied"] = bool(ok)
    else:
        out["note"] = "dry-run — pass apply to stamp"
    return out


def get_hio_pot(db_path=None) -> dict:
    """Running Hole-In-One pot (Kerry 2026-07-20: 'I need a running
    Hole-In-One pot amount. Can you add up from all events?').

    HIO is the one game pot that ACCRUES across events instead of paying
    out per event: each past event contributes its GAMES-matrix holeInOne
    amount (by that event's player count and 9/18 matrix), and the pot
    only drains when a hole-in-one is actually hit (a recorded 'hio'
    payout). Shut-down events (rain-outs — badge or credited-registration
    backstop) contributed nothing: their fees were credited back.

    Carry-in: app_settings 'hio_pot_carry_in' (a DIAL — ratified $1,822,
    2026-07-20; 'hio_pot_carry_in_note' carries provenance). Each event
    row carries `running` = carry-in + contributions through that event.

    Scheduled (future) events are INCLUDED as soon as they have
    registrations (Kerry 2026-07-20: 'The event itself should be included
    just like the event's pot is included in that event's payouts') —
    the HIO dollars are collected at registration, and the contribution
    self-corrects as the field grows because the pot recomputes live."""
    m9, m18 = _load_games_matrix(db_path=db_path)
    try:
        carry_in = float(get_app_setting("hio_pot_carry_in", db_path=db_path)
                         or 0)
    except (TypeError, ValueError):
        carry_in = 0.0
    carry_note = get_app_setting("hio_pot_carry_in_note", db_path=db_path)
    events_out, total = [], 0.0
    with _connect(db_path) as conn:
        rows = [dict(r) for r in conn.execute(
            """SELECT id, item_name, event_date,
                      COALESCE(status,'active') AS status
                 FROM events
                WHERE event_date IS NOT NULL
                ORDER BY event_date""").fetchall()]
        # 27-hole days contribute $3/player — $1 per 9 holes played
        # (Kerry 2026-07-20: "Hill country matches would be $3 / player
        # because we played 27"). Which events are 27-hole lives in a
        # dial, not code.
        pats_27h = [p.strip().upper() for p in
                    (get_app_setting("hio_27h_event_patterns",
                                     db_path=db_path)
                     or "HILL COUNTRY MATCHES").split(",") if p.strip()]
        # 36-hole championships contribute $4/player — two 18-hole
        # COMPETITION days ($1/nine/player law, ratified #276 item 7;
        # sizing instruction #279). Friday practice contributes $0, and
        # the field is ALL registered players, not just bundle buyers.
        pats_36h = [p.strip().upper() for p in
                    (get_app_setting("hio_36h_event_patterns",
                                     db_path=db_path)
                     or "2026 TGF CHAMPIONSHIP").split(",") if p.strip()]
        # Field-size overrides for days where the tracker's registration
        # count lags the true field (Kerry: 2026 Matches was 32 players,
        # tracker holds 29 registrations). Dial format:
        # "NAME PATTERN=COUNT,NAME PATTERN=COUNT".
        overrides = {}
        for part in (get_app_setting("hio_player_count_overrides",
                                     db_path=db_path) or "").split(","):
            pat, _, num = part.partition("=")
            if pat.strip() and num.strip().isdigit():
                overrides[pat.strip().upper()] = int(num.strip())
        # Future events join the pot only when NEXT IN LINE (Kerry
        # 2026-07-20: "you can't count those until the prior event is
        # completed") — everything dated through today counts; among
        # later dates only the earliest upcoming date counts, and the
        # ones behind it wait their turn.
        from email_parser.timezone_utils import today_central_str
        _today = today_central_str()
        _future = sorted({ev["event_date"] for ev in rows
                          if ev["status"] == "active"
                          and ev["event_date"] > _today})
        _next_date = _future[0] if _future else None
        for ev in rows:
            if ev["status"] != "active" or \
                    _event_looks_rained_out(conn, ev["item_name"]):
                continue
            if ev["event_date"] > _today and ev["event_date"] != _next_date:
                continue
            counts = _event_player_counts(conn, ev["item_name"])
            # True field = the larger of registrations and distinct
            # players on the event's banked scorecards (Kerry 2026-07-20,
            # Hill Country Matches: 3 golfers were staged as individuals
            # so registrations undercount; "if you look at portal results
            # you'll find 32 unique golfers"). Imports self-correct this.
            banked = conn.execute(
                """SELECT COUNT(DISTINCT player_name) AS n
                     FROM scoring_rounds WHERE event_id = ?""",
                (ev["id"],)).fetchone()["n"] or 0
            name_u = ev["item_name"].upper()
            players = next((n for pat, n in overrides.items()
                            if pat in name_u),
                           max(counts["players"] or 0, banked))
            if any(p in name_u for p in pats_36h):
                hio = float(players or 0) * 4.0
            elif any(p in name_u for p in pats_27h):
                hio = float(players or 0) * 3.0
            else:
                holes = _event_holes_type(ev["item_name"], None)
                matrix = m9 if holes == 9 else m18
                g = matrix.get(str(players)) or {}
                hio = _matrix_num(g.get("holeInOne"))
            if hio > 0:
                total += hio
                events_out.append({"event": ev["item_name"],
                                   "date": ev["event_date"],
                                   "players": players,
                                   "hio": round(hio, 2),
                                   "running": round(carry_in + total, 2)})
        paid = conn.execute(
            "SELECT COALESCE(SUM(amount), 0) AS s FROM tgf_payouts "
            "WHERE category = 'hio'").fetchone()["s"] or 0
    return {"carry_in": round(carry_in, 2), "carry_in_note": carry_note,
            "events": events_out, "events_counted": len(events_out),
            "total_contributed": round(total, 2),
            "paid_out": round(float(paid), 2),
            "pot": round(carry_in + total - float(paid), 2)}


def _event_looks_rained_out(conn, event_name: str) -> dict | None:
    """No payouts for a shut-down event (Kerry 2026-07-20, s9.18 Cedar
    Creek: 'It was a RAIN OUT. We have a badge on it. That means
    everything is shut down.').

    AUTHORITATIVE check: events.status != 'active' — the cancel flow
    (set_event_status) stamps status cancelled/postponed with a badge like
    'RAINED OUT'. Backstop for anything cancelled before the status field
    existed: registrations overwhelmingly (>=75%) credited/WD'd. Returns
    a reason dict when shut down, else None."""
    ev = conn.execute(
        """SELECT status, status_badge FROM events
            WHERE item_name = ? COLLATE NOCASE""", (event_name,)).fetchone()
    if ev and (ev["status"] or "active") != "active":
        return {"badge": ev["status_badge"] or ev["status"],
                "source": "event_status"}
    row = conn.execute(
        """SELECT COUNT(*) AS total,
                  SUM(CASE WHEN LOWER(COALESCE(transaction_status,''))
                           IN ('wd','credited','refunded') THEN 1 ELSE 0 END)
                      AS credited
             FROM items
            WHERE item_name = ? COLLATE NOCASE""",
        (event_name,)).fetchone()
    total, credited = row["total"] or 0, row["credited"] or 0
    if total >= 4 and credited >= 0.75 * total:
        return {"credited": credited, "total": total,
                "source": "credited_registrations"}
    return None


def clear_event_auto_payouts(event_name: str, include_manual: bool = False,
                             db_path=None) -> dict:
    """Remove an event's auto-recorded payout rows (description 'auto:…')
    and their PENDING ledger entries — never a matched real Venmo
    transaction. Built for wrongly auto-recorded events (the s9.18
    rain-out). include_manual=True ALSO removes manual/screenshot-imported
    rows (Kerry-directed only — e.g. a rained-out event whose sheet was
    imported before the wash was recorded), and the sweep covers EVERY
    tgf_events row matching the event code (duplicate code rows exist for
    some events)."""
    with _connect(db_path) as conn:
        ev = conn.execute(
            "SELECT item_name FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        full = ev["item_name"].strip()
        m = _GG_EVENT_CODE_COMPOUND_RE.match(full)
        bare = m.group(1).lower() if m else full.lower()
        # Whitespace-collapse normalization: duplicate tgf_events rows carry
        # code variants like "s9. 18 CEDAR CREEK" (memo-style space after the
        # period) that TRIM/LIKE prefixing can't reach. Normalize both sides
        # by stripping ALL whitespace, then match on the bare code as a
        # prefix (next char must be non-digit so s9.1 never swallows s9.18).
        # NO course-name-only fallback: same-course DIFFERENT events (s18.1
        # CEDAR CREEK vs s9.18 Cedar Creek) share the name token, and a
        # name-based match once swept 36 legitimate paid rows from two other
        # events (2026-07-20). The event CODE is the only safe key.
        def _norm(s):
            return re.sub(r"\s+", "", (s or "").lower())
        full_n, bare_n = _norm(full), _norm(bare)
        trows = []
        for t in conn.execute("SELECT id, code FROM tgf_events").fetchall():
            cn = _norm(t["code"])
            if cn == full_n or cn == bare_n:
                trows.append(t)
            elif cn.startswith(bare_n) and not cn[len(bare_n):][:1].isdigit():
                trows.append(t)
        if not trows:
            return {"event": full, "removed": 0,
                    "note": "no tgf_events row — nothing recorded"}
        removed = pending_deleted = kept_matched = 0
        desc_filter = "" if include_manual else "AND description LIKE 'auto:%'"
        for trow in trows:
            for r in conn.execute(
                    f"SELECT id, acct_transaction_id FROM tgf_payouts "
                    f"WHERE event_id = ? {desc_filter}",
                    (trow["id"],)).fetchall():
                if r["acct_transaction_id"]:
                    txn = conn.execute(
                        "SELECT id, source FROM acct_transactions WHERE id = ?",
                        (r["acct_transaction_id"],)).fetchone()
                    if txn and txn["source"] == "pending":
                        conn.execute(
                            "DELETE FROM acct_transactions WHERE id = ?",
                            (txn["id"],))
                        pending_deleted += 1
                    elif txn:
                        kept_matched += 1
                conn.execute("DELETE FROM tgf_payouts WHERE id = ?", (r["id"],))
                removed += 1
        # Kerry-directed full clears also drop the now-empty tgf_events
        # shell row: the Payouts sidebar shows tgf_events.total_purse (a
        # stored column from screenshot import), NOT the payout-row sum —
        # the Cedar Creek "$229" was a shell row with ZERO payout rows
        # that every row-only sweep necessarily reported as "removed: 0".
        shells_deleted = []
        if include_manual:
            for trow in trows:
                left = conn.execute(
                    "SELECT COUNT(*) AS n FROM tgf_payouts WHERE event_id = ?",
                    (trow["id"],)).fetchone()["n"]
                if left == 0:
                    purse = conn.execute(
                        "SELECT total_purse FROM tgf_events WHERE id = ?",
                        (trow["id"],)).fetchone()["total_purse"]
                    conn.execute("DELETE FROM tgf_events WHERE id = ?",
                                 (trow["id"],))
                    shells_deleted.append(
                        {"code": trow["code"], "total_purse": purse})
        conn.commit()
    return {"event": full, "tgf_event_rows": len(trows),
            "tgf_event_codes": [t["code"] for t in trows],
            "include_manual": include_manual, "removed": removed,
            "pending_ledger_deleted": pending_deleted,
            "matched_venmo_kept": kept_matched,
            "empty_event_rows_deleted": shells_deleted}


def restore_tgf_payouts_from_ledger(event_code: str, apply: bool = False,
                                    db_path=None) -> dict:
    """Re-create deleted tgf_payouts rows from their surviving ledger
    mirrors (repair for the 2026-07-20 clear-auto over-match that swept
    36 paid rows from s18.1 / s18.3). Bulk-confirm placeholder ledger
    rows carry the full original row: source_ref 'payout-<original id>',
    description 'Payout: <category> — <event> (...)', customer_id and
    amount. tgf_payouts.id is AUTOINCREMENT so the original ids are
    still free; rows already present are skipped (idempotent). Rows that
    were linked to REAL grouped Venmo receipts have no per-row mirror —
    they're reported as a remaining gap for Kerry, not guessed at."""
    with _connect(db_path) as conn:
        trow = conn.execute(
            "SELECT id, code FROM tgf_events WHERE TRIM(code) = ? "
            "COLLATE NOCASE", (event_code.strip(),)).fetchone()
        if not trow:
            return {"error": f"tgf_events code not found: {event_code}"}
        mirrors = conn.execute(
            "SELECT id, source_ref, description, customer, customer_id, "
            "amount, date FROM acct_transactions "
            "WHERE LOWER(TRIM(event_name)) = ? AND category = 'prize_payout' "
            "AND source_ref LIKE 'payout-%' "
            "AND COALESCE(status,'active') = 'active'",
            (trow["code"].strip().lower(),)).fetchall()
        restored, already, skipped = [], 0, []
        for r in mirrors:
            try:
                pid = int(r["source_ref"].split("-", 1)[1])
            except (IndexError, ValueError):
                skipped.append(r["source_ref"])
                continue
            if conn.execute("SELECT 1 FROM tgf_payouts WHERE id = ?",
                            (pid,)).fetchone():
                already += 1
                continue
            m = re.match(r"Payout:\s*(\S+)", r["description"] or "")
            cat = m.group(1) if m else "unknown"
            if apply:
                conn.execute(
                    "INSERT INTO tgf_payouts (id, event_id, customer_id, "
                    "category, amount, description, acct_transaction_id, "
                    "paid_at) VALUES (?,?,?,?,?,?,?,?)",
                    (pid, trow["id"], r["customer_id"], cat,
                     abs(r["amount"]),
                     "restored 2026-07-20: rebuilt from ledger mirror "
                     f"acct#{r['id']} after clear-auto over-match",
                     r["id"], r["date"]))
            restored.append({"payout_id": pid, "name": r["customer"],
                             "category": cat, "amount": abs(r["amount"])})
        if apply:
            conn.commit()
    return {"tgf_event": trow["code"], "apply": apply,
            "mirrors_found": len(mirrors), "restored": restored,
            "already_present": already, "unparsable": skipped}


def restore_tgf_payouts_explicit(rows: list, apply: bool = False,
                                 db_path=None) -> dict:
    """Second-stage repair for the 2026-07-20 clear-auto over-match: the 8
    deleted rows with NO surviving ledger mirror, reconstructed from GG's
    round boards (skins/ind-net/ctp purse tables + team roster) and
    Kerry-directed ('Of course rebuild what you screwed up'). Each row is
    re-inserted under its ORIGINAL id and marked paid exactly the way the
    app's bulk Mark Paid does — a source='venmo' '(bulk-confirmed paid)'
    ledger mirror dated to the event — because these players were in fact
    paid back in Feb/Mar. Idempotent: existing payout ids are skipped.

    rows: [{id, event_code, customer_id, customer_name, category,
            amount, date}, ...]"""
    out = {"apply": apply, "restored": [], "skipped": []}
    with _connect(db_path) as conn:
        for r in rows:
            trow = conn.execute(
                "SELECT id, code FROM tgf_events WHERE TRIM(code) = ? "
                "COLLATE NOCASE", (r["event_code"].strip(),)).fetchone()
            if not trow:
                out["skipped"].append({**r, "why": "tgf_events code not found"})
                continue
            if conn.execute("SELECT 1 FROM tgf_payouts WHERE id = ?",
                            (r["id"],)).fetchone():
                out["skipped"].append({**r, "why": "payout id already present"})
                continue
            if apply:
                cur = conn.execute(
                    """INSERT INTO acct_transactions
                           (date, description, total_amount, type, source,
                            source_ref, customer, customer_id, order_id,
                            entry_type, category, amount, account, status,
                            event_name)
                       VALUES (?, ?, ?, 'expense', 'venmo', ?, ?, ?, ?,
                               'expense', 'prize_payout', ?, 'Venmo',
                               'active', ?)""",
                    (r["date"],
                     f"Payout: {r['category']} — {trow['code']} "
                     f"(bulk-confirmed paid)",
                     round(float(r["amount"]), 2), f"payout-{r['id']}",
                     r.get("customer_name", ""), r["customer_id"],
                     f"PAYOUT-{r['id']}",
                     -round(float(r["amount"]), 2), trow["code"]))
                conn.execute(
                    """INSERT INTO tgf_payouts
                           (id, event_id, customer_id, category, amount,
                            description, acct_transaction_id, paid_at)
                       VALUES (?,?,?,?,?,?,?,?)""",
                    (r["id"], trow["id"], r["customer_id"], r["category"],
                     round(float(r["amount"]), 2),
                     "restored 2026-07-20: rebuilt from GG round boards "
                     "after clear-auto over-match (no ledger mirror "
                     "survived)", cur.lastrowid, r["date"]))
            out["restored"].append({"payout_id": r["id"],
                                    "name": r.get("customer_name"),
                                    "category": r["category"],
                                    "amount": r["amount"]})
        if apply:
            conn.commit()
    return out


def assemble_event_game_payouts(event_name: str, db_path=None) -> dict:
    """Server-side assembly of every DETERMINED winner for one event into
    payout rows — the single source of truth behind both the Games tab's
    Record Payouts button and the bulk populate (bridge command). Uses
    the LIVE prize matrix for amounts; skips (with a note) anything not
    yet determined. Returns {rows, notes, counts, holes}."""
    from email_parser.match_play import split_cents
    m9, m18 = _load_games_matrix(db_path=db_path)
    with _connect(db_path) as conn:
        ev = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        ev = dict(ev)
        rained = _event_looks_rained_out(conn, ev["item_name"])
        if rained:
            why = (f"event marked {rained['badge']}"
                   if rained.get("source") == "event_status" else
                   f"{rained['credited']} of {rained['total']} registrations "
                   f"credited/WD")
            return {"error": f"event shut down ({why}) — no winners, game "
                             f"payouts not assembled",
                    "rained_out": True}
        counts = _event_player_counts(conn, ev["item_name"])
    holes = _event_holes_type(ev["item_name"], ev.get("format"))
    matrix = m9 if holes == 9 else m18
    g_event = matrix.get(str(counts["players"])) or {}
    g_net = matrix.get(str(counts["net"])) or {}
    g_gross = matrix.get(str(counts["gross"])) or {}
    rows: list = []
    notes: list = []

    def _money_split(total: float, winners: list, category: str, desc: str):
        cents = split_cents(round(total * 100), len(winners))
        for w, c in zip(winners, cents):
            if c > 0:
                rows.append({"golferName": w, "category": category,
                             "amount": c / 100.0, "description": desc})

    # ── GG-recorded: Team Net (per-member split), CTP / Longest Putt ──
    gg = get_gg_game_results(ev["item_name"], db_path=db_path)
    gg_rows = gg.get("results") or []
    team_amts = [a for a in (_matrix_num(g_event.get("team1st")),
                             _matrix_num(g_event.get("team2nd"))) if a > 0]
    teams = [r for r in gg_rows if r["game"] == "team_net"]
    if team_amts and g_event.get("teamTotal") not in (None, "NO_EVENT"):
        if not teams:
            notes.append("Team Net: no GG-recorded winner yet — skipped")
        # Tied teams (GG "T1"/"T1") split the combined place money — with a
        # single team place, two T1 teams each take half of team1st (s9.17
        # Silverhorn: $108 → $54/team, matching GG's recorded purses).
        team_pos_groups: dict = {}
        for idx, t in enumerate(teams):
            pm = re.search(r"(\d+)", str(t.get("position") or ""))
            team_pos_groups.setdefault(
                int(pm.group(1)) if pm else idx + 1, []).append(t)
        place_cents = [round(a * 100) for a in team_amts]

        # Blind-draw partners ARE paid their team share (Kerry 2026-07-13,
        # verified vs GG's Player Purse Summary on s9.17 Silverhorn: GG
        # splits $54 across all 4 slots incl. Bl[HAMILTON, Doug] → $13.50
        # each). Unwrap the GG 'Bl[LAST, First]' wrapper (keeping the blind
        # flag for the dedup tie-break below) and strip the portal
        # decoration a cross-chapter team string leaves on its last member
        # ("SHARITZ, Don TGF Austin," / "... TGF Austin, Guest").
        def _member(nm):
            nm = re.sub(r"\s+TGF\s+.*$", "", nm).strip().rstrip(",")
            bm = re.match(r"^Bl\[(.+)\]$", nm)
            return ({"name": bm.group(1).strip(), "blind": True} if bm
                    else {"name": nm, "blind": False})

        paid_teams: list = []
        for pos in sorted(team_pos_groups):
            grp = team_pos_groups[pos]
            # GG-posted purse wins over the matrix split (Kerry 2026-08-02:
            # "we need to allow me to adjust GAMES money" — he tunes the
            # place purses directly on the GG board, e.g. rounding the SA
            # championship's team places to $170/$86 so member shares land
            # on clean quarters). The board's Purse column is captured per
            # team on every re-walk, so his GG edits flow through here and
            # the hourly auto re-record reproduces them. Matrix place money
            # stays the fallback for boards with no purse posted.
            gg_pool = round(sum((t.get("purse") or 0) for t in grp) * 100)
            pool = gg_pool if gg_pool > 0 else \
                sum(place_cents[pos - 1: pos - 1 + len(grp)])
            if pool <= 0:
                continue
            suffix = {1: "1st", 2: "2nd", 3: "3rd"}.get(pos, f"{pos}th")
            grp_members = [[_member(mname.strip())
                            for mname in t["player_name"].split("+")
                            if mname.strip()] for t in grp]
            # TIED teams sharing a duplicate player (real slot on one,
            # blind on the other) stop being separate pots (Kerry ruling
            # 2026-07-20): the COMBINED pool splits evenly among ALL
            # unique players across the tied teams — two tied foursomes
            # with one shared player → pool ÷ 7, everyone equal.
            if len(grp) > 1:
                seen_keys: set = set()
                uniq: list = []
                slots = 0
                for members in grp_members:
                    for m in members:
                        slots += 1
                        k = _cmp_person_key(m["name"])
                        if k not in seen_keys:
                            seen_keys.add(k)
                            if not m["blind"]:
                                m = dict(m)
                            uniq.append(m)
                        elif not m["blind"]:
                            for u in uniq:
                                if _cmp_person_key(u["name"]) == k:
                                    u["blind"] = False
                if uniq and len(uniq) < slots:
                    paid_teams.append({
                        "cents": pool, "members": uniq,
                        "desc": f"{g_event.get('teamType') or 'Team Net'} "
                                f"{suffix} (T) (split among "
                                f"{len(uniq)} unique players)"})
                    continue
            team_shares = split_cents(pool, len(grp))
            for t, members, tc in zip(grp, grp_members, team_shares):
                if not members or tc <= 0:
                    continue
                paid_teams.append({
                    "cents": tc, "members": members,
                    "desc": f"{g_event.get('teamType') or 'Team Net'} "
                            f"{suffix}{' (T)' if len(grp) > 1 else ''} "
                            f"(team split)"})
        # Cross-PLACE duplicate (Kerry ruling 2026-07-20): a player on two
        # DIFFERENTLY-placed paid teams (1st and 2nd) receives only the
        # HIGHER per-player share; the lower team's pot then splits among
        # its REMAINING members (the pot amount itself doesn't shrink).
        # Same-place ties were already pooled above.
        deduping = True
        while deduping:
            deduping = False
            seen: dict = {}
            for ti, team in enumerate(paid_teams):
                for m in team["members"]:
                    k = _cmp_person_key(m["name"])
                    if k in seen and seen[k] != ti:
                        oti = seen[k]

                        def _share(t):
                            return t["cents"] // max(1, len(t["members"]))

                        if _share(paid_teams[ti]) != _share(paid_teams[oti]):
                            drop = ti if _share(paid_teams[ti]) < \
                                _share(paid_teams[oti]) else oti
                        else:
                            other = next(x for x in paid_teams[oti]["members"]
                                         if _cmp_person_key(x["name"]) == k)
                            drop = ti if m["blind"] and not other["blind"] \
                                else (oti if other["blind"] and not m["blind"]
                                      else ti)
                        paid_teams[drop]["members"] = [
                            x for x in paid_teams[drop]["members"]
                            if _cmp_person_key(x["name"]) != k]
                        deduping = True
                        break
                    seen[k] = ti
                if deduping:
                    break
        for team in paid_teams:
            if team["members"]:
                _money_split(team["cents"] / 100.0,
                             [m["name"] for m in team["members"]],
                             "team_net", team["desc"])
    proxies = ([r for r in gg_rows if r["game"] == "ctp"]
               + [r for r in gg_rows if r["game"] == "longest_putt"])
    ctp_vals = [v for v in (
        _matrix_num(g_event.get("ctp1")), _matrix_num(g_event.get("ctp2")),
        _matrix_num(g_event.get("ctp3")), _matrix_num(g_event.get("ctp4")),
    ) if v > 0]
    if ctp_vals and not proxies:
        notes.append("CTP: no GG-recorded winners yet — skipped")
    for i, p in enumerate(proxies):
        amt = ctp_vals[min(i, len(ctp_vals) - 1)] if ctp_vals else 0
        # Same GG-money rule as Team Net: a purse posted on the CTP /
        # Longest Putt board is Kerry's adjusted number — prefer it.
        if (p.get("purse") or 0) > 0:
            amt = p["purse"]
        if amt > 0:
            label = "Longest Putt" if p["game"] == "longest_putt" else "CTP"
            rows.append({"golferName": p["player_name"],
                         "category": "longest_putt" if p["game"] == "longest_putt" else "ctp",
                         "amount": amt,
                         "description": f"{label} {p.get('game_label') or ''}".strip()})

    # ── MVP (computed): City here; TGF combined pot once per day ──
    linked: list = []
    det = determine_tgf_mvp(ev["item_name"], db_path=db_path)
    if not det.get("error"):
        per_event = det.get("per_event") or []
        linked = [e for e in per_event
                  if e["event_name"].lower() != ev["item_name"].lower()]
        tgf_val = _matrix_num(g_net.get("tgfMVP")) or _matrix_num(g_net.get("mvp"))
        my = next((e for e in per_event
                   if e["event_name"].lower() == ev["item_name"].lower()), None)
        city_val = _matrix_num(g_net.get("cityMVP")) + (0 if linked else tgf_val)
        if holes == 18:
            # 18-hole day type (Kerry-ratified 2026-07-31, mirrors the Games
            # tab): the m18 matrix row encodes the SINGLE-event day — mvp =
            # min($8xN, $100) with the capped-away excess folded into
            # Individual Net. With a linked same-day 18-hole event there is
            # no cap: the full $8xN splits $4/buyer City + $4/buyer TGF
            # ("exactly like 9s. It's just a bigger $/player"). Matrix
            # cityMVP/tgfMVP columns win where they exist.
            half18 = 4.0 * (counts["net"] or 0)
            city_half = _matrix_num(g_net.get("cityMVP")) or half18
            tgf_val = _matrix_num(g_net.get("tgfMVP")) or half18
            if linked:
                city_val = city_half
            else:
                city_val = (_matrix_num(g_net.get("mvp"))
                            or min(city_half + tgf_val, 100.0))
        cm = my and my.get("city_mvp")
        if cm and cm.get("status") == "determined" and cm.get("winners") and city_val > 0:
            _money_split(city_val, [w["player"] for w in cm["winners"]],
                         "mvp", "City MVP" + (" (split)" if cm.get("split") else ""))
        elif city_val > 0:
            notes.append("City MVP: not determined yet — skipped")
        t = det.get("tgf_mvp") or {}
        if linked:
            if t.get("status") == "determined" and t.get("winners"):
                # Exactly ONE event of the day owns the combined pot —
                # the winner's own event (v2.41.2; both linked events
                # previously assembled the same row, so a same-pass
                # force-refresh of both recorded it twice). Deterministic
                # on every side: min() settles a cross-event tie split.
                owner = min((w.get("event_name") or ev["item_name"])
                            for w in t["winners"])
                if owner.lower() != ev["item_name"].lower():
                    notes.append(f"TGF MVP: recorded under {owner} "
                                 "(winner's event) — not here")
                else:
                    combined = tgf_val
                    mtx = m9 if holes == 9 else m18
                    for le in linked:
                        nb = le.get("net_buyers") or 0
                        le_row = mtx.get(str(nb)) or {}
                        if holes == 9:
                            combined += (_matrix_num(le_row.get("tgfMVP"))
                                         or _matrix_num(le_row.get("mvp")))
                        else:
                            # 18h linked event's TGF half: matrix column if
                            # present, else the derived $4/buyer (the m18
                            # mvp column is the CAPPED single-day value —
                            # never a valid TGF contribution).
                            combined += (_matrix_num(le_row.get("tgfMVP"))
                                         or 4.0 * nb)
                    if combined > 0:
                        _money_split(combined, [w["player"] for w in t["winners"]],
                                     "tgf_mvp", "TGF MVP (combined same-day pot)"
                                     + (" (split)" if t.get("split") else ""))
                        notes.append("TGF MVP recorded here (winner's event) — "
                                     "the linked event skips it")
            elif t.get("status") == "awaiting_results":
                notes.append("TGF MVP: awaiting linked-event results — skipped")
            elif t.get("status") == "single_event_day":
                # Kerry ruling 2026-07-20 (a9.18 + the rained-out s9.18):
                # when the linked chapter's event washed out, there's no
                # cross-chapter TGF MVP HONOR — but THIS event's players
                # still funded its TGF MVP contribution, and money follows
                # collection: the day's sole determined City MVP takes this
                # event's own tgfMVP pot. (GG left it unallocated — the
                # source of the a9.18 $26 shortfall.)
                if cm and cm.get("status") == "determined" and \
                        cm.get("winners") and tgf_val > 0:
                    _money_split(tgf_val, [w["player"] for w in cm["winners"]],
                                 "tgf_mvp", "TGF MVP pot (single-event day)"
                                 + (" (split)" if cm.get("split") else ""))
                    notes.append("TGF MVP pot paid to the sole City MVP "
                                 "(linked event produced no MVP)")

    # ── Individual Net (per-flight ladders, tie splits) ──
    net_flights = int(_matrix_num(g_net.get("netFlights")) or 1)
    if _matrix_num(g_net.get("individualNet")) > 0 and counts["net"] >= 2:
        d = determine_event_game_results(ev["item_name"], "individual_net",
                                         flights=net_flights, db_path=db_path)
        if d.get("status") == "determined":
            if holes == 18:
                # Multi-event 18-hole day (Kerry-ratified 2026-07-31, mirrors
                # the Games tab): the m18 ladder encodes the single-event pot
                # (26xN minus the CAPPED MVP), but on a linked day the full
                # $8xN goes to MVP money — the capped-away residual leaves
                # Individual Net, places scaled proportionally so every
                # matrix ratio holds.
                _scale = 1.0
                if linked:
                    _full_mvp = 8.0 * (counts["net"] or 0)
                    _capped = _matrix_num(g_net.get("mvp"))
                    _stored = _matrix_num(g_net.get("individualNet"))
                    _residual = _full_mvp - _capped
                    if _residual > 0 and _stored > 0:
                        _scale = (_stored - _residual) / _stored

                def _scale_amt(v):
                    n = _matrix_num(v)
                    return round(n * _scale, 2) if n > 0 else v

                flight_amounts = [
                    [_scale_amt(g_net.get("netLow1st")), _scale_amt(g_net.get("netLow2nd")), _scale_amt(g_net.get("netLow3rd")), _scale_amt(g_net.get("netLow4th"))],
                    [_scale_amt(g_net.get("netHigh1st")), _scale_amt(g_net.get("netHigh2nd")), _scale_amt(g_net.get("netHigh3rd")), _scale_amt(g_net.get("netHigh4th"))],
                    [_scale_amt(g_net.get("netMid1st")), _scale_amt(g_net.get("netMid2nd")), _scale_amt(g_net.get("netMid3rd")), _scale_amt(g_net.get("netMid4th"))],
                    [_scale_amt(g_net.get("net4th1st")), _scale_amt(g_net.get("net4th2nd")), _scale_amt(g_net.get("net4th3rd")), _scale_amt(g_net.get("net4th4th"))],
                ]
            else:
                flight_amounts = [
                    [g_net.get("netLow1st"), g_net.get("netLow2nd"), g_net.get("netLow3rd")],
                    [g_net.get("netHigh1st"), g_net.get("netHigh2nd"), g_net.get("netHigh3rd")],
                ]
            for i, fl in enumerate(d.get("flights") or []):
                rows.extend(_rows_from_place_ladder(
                    fl.get("ranking") or [], flight_amounts[i] if i < len(flight_amounts) else [],
                    "individual_net", f"Ind Net {fl['flight']}"))
        else:
            notes.append(f"Individual Net: {d.get('status', 'unknown')} — skipped")

    # ── Skins (gross; ½-net rule pending below 8 gross buyers on 9h) ──
    skins_total = _matrix_num(g_gross.get("skinsTotal"))
    if skins_total > 0:
        if holes == 9 and counts["gross"] < 8:
            notes.append("Skins ½ Net: rule pending — record manually")
        else:
            skins_flights = int(_matrix_num(g_gross.get("skinsFlights")) or 1)
            d = determine_event_game_results(ev["item_name"], "skins",
                                             flights=skins_flights, db_path=db_path)
            if d.get("status") == "determined":
                n_fl = len(d.get("flights") or []) or 1
                flight_pot_cents = round(skins_total * 100 / n_fl)
                for fl in d.get("flights") or []:
                    if not fl.get("skin_count"):
                        continue
                    # exact-division cents: apportion the flight pot by skin
                    # counts with largest remainder so the flight sums to the
                    # pot exactly (no per-row rounding drift)
                    holders = sorted((fl.get("per_player") or {}).items(),
                                     key=lambda kv: (-kv[1], kv[0]))
                    total_sk = fl["skin_count"]
                    floors = [(nm, cnt, flight_pot_cents * cnt // total_sk,
                               (flight_pot_cents * cnt) % total_sk)
                              for nm, cnt in holders]
                    short = flight_pot_cents - sum(f[2] for f in floors)
                    order = sorted(range(len(floors)),
                                   key=lambda i: (-floors[i][3], i))
                    bump = set(order[:short])
                    for i, (nm, cnt, cents, _) in enumerate(floors):
                        # holes ride the description so member surfaces can
                        # say WHICH skins (Kerry 2026-08-03)
                        _won = [str(s["hole"]) for s in (fl.get("skins") or [])
                                if s.get("player") == nm]
                        _ht = f" holes {', '.join(_won)}" if _won else ""
                        rows.append({"golferName": nm, "category": "skins",
                                     "amount": (cents + (1 if i in bump else 0)) / 100.0,
                                     "description": f"Skins {fl['flight']} ×{cnt}{_ht}"})
            else:
                notes.append(f"Skins: {d.get('status', 'unknown')} — skipped")

    # ── Individual Gross (per flight) ──
    if _matrix_num(g_gross.get("individualGross")) > 0:
        g_flights = max(1, int(_matrix_num(g_gross.get("grossFlights")) or 1))
        d = determine_event_game_results(ev["item_name"], "individual_gross",
                                         flights=g_flights, db_path=db_path)
        if d.get("status") == "determined":
            # Flight-pot LEVER (Kerry 2026-07-22 — INTERIM, final rule
            # pending his ratification): app_setting
            # 'gross_flight_pot_mode' = 'buyins' (default; each flight's
            # pot is its own players' buy-ins — GG's model, right for
            # handicap-BAND flights with uneven headcounts: $8 × 4/5/7 =
            # $32/$40/$56 on s18.8's 16-buyer $128 pot) or 'even'
            # (straight split: total ÷ flights, for cuts meant to pay
            # flights equally). Editable via scoring-setting-set; the
            # matrix ladder's proportions split places within a flight
            # either way. Exact cents (largest remainder).
            _mode = (get_app_setting("gross_flight_pot_mode",
                                     db_path=db_path) or "buyins").strip().lower()
            # Per-EVENT override (v2.188.13, first piece of Kerry's FLIGHTS
            # mechanism): 'gross_flight_pot_mode_overrides' is a JSON dial
            # {event_name_lower: mode}. Needed because the global dial
            # can't represent one event paid differently — the hourly
            # auto-sync force-re-records recent events, so a temporary
            # global flip gets clobbered on the next sync (the 2026-08-01
            # championships were paid EVEN in GG while the default stays
            # buyins).
            try:
                _ovr = json.loads(get_app_setting(
                    "gross_flight_pot_mode_overrides", db_path=db_path) or "{}")
            except (TypeError, ValueError):
                _ovr = {}
            _mode = (_ovr.get(ev["item_name"].strip().lower())
                     or _mode).strip().lower()
            gross_total_cents = round(
                _matrix_num(g_gross.get("individualGross")) * 100)
            fls = d.get("flights") or []
            weights = [1 if _mode == "even" else int(fl.get("players") or 0)
                       for fl in fls]
            n_scored = sum(weights) or 1
            ladder = [a for a in (_matrix_num(g_gross.get("grossLow1st")),
                                  _matrix_num(g_gross.get("grossLow2nd")))
                      if a > 0]
            lsum = sum(ladder) or 1
            floors = [(fl,
                       gross_total_cents * w // n_scored,
                       (gross_total_cents * w) % n_scored)
                      for fl, w in zip(fls, weights)]
            short = gross_total_cents - sum(f[1] for f in floors)
            order = sorted(range(len(floors)), key=lambda i: (-floors[i][2], i))
            bump = set(order[:short])
            for i, (fl, cents, _r) in enumerate(floors):
                pot = (cents + (1 if i in bump else 0)) / 100.0
                if pot <= 0:
                    continue
                amts = ([round(pot * a / lsum, 2) for a in ladder] or [pot])
                drift = round(pot - sum(amts), 2)
                if abs(drift) >= 0.01:
                    amts[0] = round(amts[0] + drift, 2)
                rows.extend(_rows_from_place_ladder(
                    fl.get("ranking") or [], amts,
                    "individual_gross", f"Ind Gross {fl['flight']}"))
        else:
            notes.append(f"Ind. Gross: {d.get('status', 'unknown')} — skipped")

    notes.append("Hole-in-One is an accruing cross-event pot — never auto-recorded")
    return {"event_name": ev["item_name"], "holes": holes, "counts": counts,
            "rows": rows, "notes": notes,
            "total": round(sum(r["amount"] for r in rows), 2)}


def record_all_event_game_payouts(db_path=None, time_budget: float = 42.0,
                                  force: bool = False,
                                  recent_force_days: int = 0,
                                  force_events: list | None = None) -> dict:
    """Bulk populate: assemble + record payouts for every PAST event.

    Skips events that already have payout rows (auto rows are only
    replaced when force=True; events with MANUAL/screenshot-imported
    rows are always skipped — never mix). Time-budgeted like the
    portal walks; call repeatedly until events_left == 0.

    force_events: item_names whose auto rows re-record regardless of
    recent_force_days — the games import reports events whose GG winner
    set changed (a late-entered CTP), and those must flow through to the
    Payouts tab even when the event is older than the recent window.
    """
    from time import monotonic
    from email_parser.timezone_utils import today_central_str
    started = monotonic()
    from datetime import date, timedelta
    with _connect(db_path) as conn:
        events = [dict(r) for r in conn.execute(
            "SELECT item_name, event_date FROM events WHERE event_date IS NOT NULL "
            "AND event_date <= ? ORDER BY event_date DESC",
            (today_central_str(),)).fetchall()]
    recent_cutoff = None
    if recent_force_days:
        recent_cutoff = (date.fromisoformat(today_central_str())
                         - timedelta(days=recent_force_days)).isoformat()
    force_set = {str(n).strip().lower() for n in (force_events or [])}
    out = {"recorded": [], "skipped": [], "events_left": 0}
    for i, ev in enumerate(events):
        if monotonic() - started > time_budget:
            out["events_left"] = len(events) - i
            break
        name = ev["item_name"]
        with _connect(db_path) as conn:
            m = _GG_EVENT_CODE_COMPOUND_RE.match(name.strip())
            bare = m.group(1).lower() if m else name.strip().lower()
            trow = conn.execute(
                "SELECT id FROM tgf_events WHERE LOWER(code) IN (?, ?)",
                (name.strip().lower(), bare)).fetchone()
            if trow:
                kinds = conn.execute(
                    "SELECT SUM(CASE WHEN description LIKE 'auto:%' THEN 1 ELSE 0 END) a, "
                    "       SUM(CASE WHEN description LIKE 'auto:%' THEN 0 ELSE 1 END) m "
                    "FROM tgf_payouts WHERE event_id = ?", (trow["id"],)).fetchone()
                ev_force = force or name.strip().lower() in force_set \
                    or (recent_cutoff is not None
                        and (ev.get("event_date") or "") >= recent_cutoff)
                if (kinds["m"] or 0) > 0:
                    out["skipped"].append({"event": name, "reason": "manual payouts exist"})
                    continue
                if (kinds["a"] or 0) > 0 and not ev_force:
                    out["skipped"].append({"event": name, "reason": "already auto-recorded"})
                    continue
        asm = assemble_event_game_payouts(name, db_path=db_path)
        if asm.get("error") or not asm.get("rows"):
            out["skipped"].append({"event": name,
                                   "reason": asm.get("error") or "nothing determined"})
            continue
        res = record_event_game_payouts(name, asm["rows"], force=True,
                                        db_path=db_path)
        if res.get("error"):
            out["skipped"].append({"event": name, "reason": res["error"]})
        else:
            out["recorded"].append({"event": name, "payouts": res["payouts_added"],
                                    "total": asm["total"],
                                    "notes": [n for n in asm["notes"]
                                              if "never auto-recorded" not in n]})
    return out


def repair_teamnet_blind_draw_shares(event_name: str, dry_run: bool = True,
                                     db_path=None) -> dict:
    """Surgically correct a Team Net winning group where a blind-draw
    partner was wrongly EXCLUDED from the recorded split (the pre-v2.78.4
    bug — the real members were over-paid and the blind-draw got $0).

    Kerry (2026-07-13) scoped this to a PARTIAL repair: only the UNPAID
    rows of the affected group may change; teammates already paid at the
    old amount must be left exactly as-is (a full re-record would delete
    and re-create their paid rows). So this never touches a paid row.

    Uses the corrected assembler (assemble_event_game_payouts, which now
    includes blind-draw members) as the source of truth for the team_net
    winners and their uniform per-player share. For each winner, resolved
    by customer_id:
      - If ANY of their team_net rows for this event is PAID (linked to a
        non-pending acct_transaction) -> SKIP the player untouched.
      - Else bring their PENDING team_net rows to exactly one row at the
        correct share: adjust the amount of the existing pending row (and
        its mirror pending acct_transaction) in lockstep, delete any
        extra pending team_net rows, or INSERT a fresh pending row +
        mirror if the player has none (the excluded blind-draw case).

    The net change across the group is $0 (money over-distributed to the
    real members moves to the blind-draw member). dry_run=True returns the
    plan without writing. Returns {event, share, changes[], skipped_paid[],
    net_delta, applied}.
    """
    with _connect(db_path) as conn:
        ev = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        ev = dict(ev)
        full = ev["item_name"].strip()
        m = _GG_EVENT_CODE_COMPOUND_RE.match(full)
        bare = m.group(1).lower() if m else full.lower()
        trow = conn.execute(
            "SELECT id, name, event_date FROM tgf_events "
            "WHERE LOWER(code) = ? OR LOWER(code) = ?",
            (full.lower(), bare)).fetchone()
        if not trow:
            return {"error": f"no tgf_events row for {full}"}
        tgf_event_id = trow["id"]
        tgf_event_name = trow["name"]
        tgf_event_date = trow["event_date"]

        asm = assemble_event_game_payouts(event_name, db_path=db_path)
        if asm.get("error"):
            return asm
        team_rows = [r for r in asm.get("rows", [])
                     if r.get("category") == "team_net"]
        if not team_rows:
            return {"error": "no team_net winners in assembled payouts"}

        # Correct uniform share + winner customer_ids. Resolve names to
        # cids WITHOUT creating shells: map from the event's own recorded
        # winners first (every team_net winner has some recorded row —
        # even the excluded blind-draw has a skins/other row), then fall
        # back to the lookup cascade.
        recorded_all = [dict(r) for r in conn.execute(
            """SELECT p.id, p.customer_id, p.category, p.amount,
                      p.description, p.acct_transaction_id,
                      c.first_name, c.last_name,
                      t.source AS txn_source, t.id AS txn_id
               FROM tgf_payouts p
               LEFT JOIN customers c ON c.customer_id = p.customer_id
               LEFT JOIN acct_transactions t ON t.id = p.acct_transaction_id
               WHERE p.event_id = ?""", (tgf_event_id,)).fetchall()]
        name_to_cid = {}
        for r in recorded_all:
            if r["customer_id"] and r["last_name"]:
                key = f"{r['last_name']}, {r['first_name']}".strip().lower()
                name_to_cid.setdefault(key, r["customer_id"])

        def _cid_for(gname: str):
            # Recorded-row map first (already-resolved cids for this
            # event), then the curated scoring resolver (same non-creating
            # spine assemble/record use — handles "MORENO, Robert" vs the
            # customer's "Roberto Moreno"), then the lookup cascade. None
            # of these create a shell customer on a miss.
            cid = name_to_cid.get((gname or "").strip().lower())
            if cid:
                return cid
            cid = _resolve_scoring_player(conn, gname)
            if cid:
                return cid
            return _lookup_customer_id(conn, gname, None)

        share = round(float(team_rows[0]["amount"]), 2)
        team_desc = None
        winners = {}  # cid -> correct total team_net (uniform, but sum safe)
        for r in team_rows:
            cid = _cid_for(r["golferName"])
            if not cid:
                return {"error": f"could not resolve team_net winner "
                                 f"{r['golferName']!r} to a customer"}
            winners[cid] = round(winners.get(cid, 0) + float(r["amount"]), 2)
            team_desc = team_desc or ("auto: " + (r.get("description") or ""))

        # Current recorded team_net rows per winner
        cur_team = {}
        for r in recorded_all:
            if r["category"] != "team_net":
                continue
            cur_team.setdefault(r["customer_id"], []).append(r)

        changes = []
        skipped_paid = []
        net_delta = 0.0
        for cid, target in winners.items():
            rows = cur_team.get(cid, [])
            paid = [r for r in rows
                    if r["txn_source"] and r["txn_source"] != "pending"]
            if paid:
                skipped_paid.append({
                    "customer_id": cid,
                    "name": f"{paid[0]['first_name']} {paid[0]['last_name']}",
                    "recorded": round(sum(float(r["amount"]) for r in rows), 2),
                    "reason": "already paid — left untouched",
                })
                continue
            cur_sum = round(sum(float(r["amount"]) for r in rows), 2)
            if rows and cur_sum == target and len(rows) == 1:
                continue  # already correct
            nm = None
            if rows:
                nm = f"{rows[0]['first_name']} {rows[0]['last_name']}"
            else:
                crow = conn.execute(
                    "SELECT first_name, last_name FROM customers WHERE customer_id = ?",
                    (cid,)).fetchone()
                nm = f"{crow['first_name']} {crow['last_name']}" if crow else str(cid)
            changes.append({
                "customer_id": cid, "name": nm,
                "from": cur_sum, "to": target,
                "delta": round(target - cur_sum, 2),
                "existing_rows": len(rows),
            })
            net_delta = round(net_delta + (target - cur_sum), 2)

        plan = {
            "event": tgf_event_name,
            "share": share,
            "changes": changes,
            "skipped_paid": skipped_paid,
            "net_delta": net_delta,
            "applied": False,
        }
        if dry_run or not changes:
            return plan

        # ---- apply (single transaction) ----
        for ch in changes:
            cid = ch["customer_id"]
            rows = cur_team.get(cid, [])
            pend = [r for r in rows]  # all are pending here (paid skipped)
            target = ch["to"]
            if pend:
                keep = pend[0]
                conn.execute("UPDATE tgf_payouts SET amount = ? WHERE id = ?",
                             (target, keep["id"]))
                if keep["txn_id"]:
                    conn.execute(
                        "UPDATE acct_transactions SET total_amount = ?, amount = ? "
                        "WHERE id = ? AND source = 'pending'",
                        (target, -target, keep["txn_id"]))
                # remove any extra team_net rows for this player
                for extra in pend[1:]:
                    if extra["txn_id"]:
                        conn.execute(
                            "DELETE FROM acct_transactions WHERE id = ? AND source = 'pending'",
                            (extra["txn_id"],))
                    conn.execute("DELETE FROM tgf_payouts WHERE id = ?", (extra["id"],))
            else:
                # excluded blind-draw member — insert a fresh pending row
                cur = conn.execute(
                    """INSERT INTO tgf_payouts (event_id, customer_id, category,
                                                amount, description)
                       VALUES (?, ?, 'team_net', ?, ?)""",
                    (tgf_event_id, cid, target, team_desc or "auto: TEAM Net (team split)"))
                pid = cur.lastrowid
                cur2 = conn.execute(
                    """INSERT INTO acct_transactions
                           (date, description, total_amount, type, source, source_ref,
                            customer, order_id, entry_type, category, amount, account,
                            status, event_name)
                       VALUES (?, ?, ?, 'expense', 'pending', ?, ?, ?, 'expense',
                               'prize_payout', ?, 'Venmo', 'active', ?)""",
                    (tgf_event_date,
                     f"Payout: team_net — {tgf_event_name}",
                     target, f"payout-{pid}",
                     "", f"PAYOUT-{pid}", -target, tgf_event_name))
                conn.execute("UPDATE tgf_payouts SET acct_transaction_id = ? WHERE id = ?",
                             (cur2.lastrowid, pid))
                conn.execute(
                    """UPDATE acct_transactions SET customer = (
                           SELECT first_name || ' ' || last_name
                           FROM customers WHERE customer_id = ?
                       ) WHERE id = ?""", (cid, cur2.lastrowid))

        # recompute event aggregates
        stats = conn.execute(
            """SELECT COUNT(*) AS cnt, COALESCE(SUM(amount), 0) AS total,
                      COUNT(DISTINCT customer_id) AS winners
               FROM tgf_payouts WHERE event_id = ?""", (tgf_event_id,)).fetchone()
        conn.execute(
            "UPDATE tgf_events SET total_purse = ?, winners_count = ?, "
            "payouts_count = ? WHERE id = ?",
            (stats["total"], stats["winners"], stats["cnt"], tgf_event_id))
        conn.commit()
        plan["applied"] = True
        plan["event_total_purse"] = round(float(stats["total"]), 2)
        return plan


def record_event_game_payouts(event_name: str, payouts: list,
                              force: bool = False, db_path=None) -> dict:
    """Record the Games-tab winners as PAYOUTS-tab rows (v2.38.0).

    payouts: [{golferName, category, amount, description}] assembled by
    the Games tab from the determined winners (computed + GG-recorded;
    team payouts arrive pre-split per member so every row ties to a
    customer — Kerry: payouts tying to Customers is non-negotiable).

    Finds or creates the tgf_events row for the tracker event (matched
    by event code). Rows are stamped description 'auto: …'; re-recording
    requires force=True, which first removes the previous auto rows —
    deleting their PENDING ledger entries but never a matched real Venmo
    transaction. Inserting delegates to import_tgf_payouts so the
    customer resolution + Venmo reconciliation + aggregates all reuse
    the proven path.
    """
    if not payouts:
        return {"error": "No payouts provided"}
    with _connect(db_path) as conn:
        ev = conn.execute(
            "SELECT * FROM events WHERE item_name = ? COLLATE NOCASE",
            (event_name,)).fetchone()
        if not ev:
            return {"error": f"event not found: {event_name}"}
        ev = dict(ev)
        # tgf_events.code convention = the FULL event name ("s9.15 The
        # Quarry") — the TGF sidebar displays code and the Events-page
        # PAYOUTS tab matches code === item_name. Bare code prefix kept
        # as a lookup fallback for legacy/manual rows.
        full = ev["item_name"].strip()
        m = _GG_EVENT_CODE_COMPOUND_RE.match(full)
        bare = m.group(1).lower() if m else full.lower()

        trow = conn.execute(
            "SELECT id, code FROM tgf_events WHERE LOWER(code) = ? OR LOWER(code) = ?",
            (full.lower(), bare)).fetchone()
        if trow:
            tgf_event_id = trow["id"]
            if trow["code"].strip().lower() == bare != full.lower():
                conn.execute("UPDATE tgf_events SET code = ?, name = ? WHERE id = ?",
                             (full, full, tgf_event_id))
                conn.commit()
        else:
            cur = conn.execute(
                """INSERT INTO tgf_events (code, name, event_date, course, chapter)
                   VALUES (?, ?, ?, ?, ?)""",
                (full, full, ev.get("event_date") or "",
                 ev.get("course"), ev.get("chapter")))
            tgf_event_id = cur.lastrowid

        manual = conn.execute(
            "SELECT COUNT(*) FROM tgf_payouts WHERE event_id = ? "
            "AND description NOT LIKE 'auto:%'", (tgf_event_id,)).fetchone()[0]
        if manual:
            return {"error": f"{manual} manually recorded payout(s) exist for "
                             "this event — auto-recording would double-count. "
                             "Manage them on the TGF Payouts page instead."}
        existing_auto = conn.execute(
            "SELECT id, acct_transaction_id FROM tgf_payouts "
            "WHERE event_id = ? AND description LIKE 'auto:%'",
            (tgf_event_id,)).fetchall()
        if existing_auto and not force:
            return {"error": f"{len(existing_auto)} auto-recorded payout(s) "
                             "already exist for this event — re-recording "
                             "replaces them.",
                    "needs_force": True}
        removed = 0
        preserved: list = []
        for r in existing_auto:
            txn = None
            if r["acct_transaction_id"]:
                txn = conn.execute(
                    "SELECT id, source, COALESCE(status,'active') AS st "
                    "FROM acct_transactions WHERE id = ?",
                    (r["acct_transaction_id"],)).fetchone()
            if txn and txn["source"] != "pending" and txn["st"] == "active":
                # PAID — a real payment backs this row. A force re-record
                # must never un-pay money that actually moved (Kerry
                # 2026-08-02: Chuck Fehlis' cleared payout "came back"
                # after the hourly auto-sync re-recorded the event — the
                # old delete-everything dance relied on the receipt
                # re-matching afterwards, and an ambiguous amount can
                # silently fail that re-match). Keep the row; its
                # assembled twin is consumed below instead of re-inserted.
                pr = conn.execute(
                    "SELECT customer_id, category, amount FROM tgf_payouts "
                    "WHERE id = ?", (r["id"],)).fetchone()
                if pr:
                    preserved.append(dict(pr))
                continue
            if txn and txn["source"] == "pending":
                conn.execute("DELETE FROM acct_transactions WHERE id = ?",
                             (txn["id"],))
            conn.execute("DELETE FROM tgf_payouts WHERE id = ?", (r["id"],))
            removed += 1
        conn.commit()

        # Assembled rows already covered by a preserved PAID row are not
        # re-inserted — matched one-for-one on (customer, category, exact
        # amount) so legitimate duplicate amounts still record. A paid row
        # whose assembled amount has since CHANGED stays alongside the new
        # pending row for admin reconciliation (money that moved is never
        # deleted; the difference is visible on the Payouts tab).
        if preserved:
            pool = list(preserved)
            remaining = []
            for p in payouts:
                nm = (p.get("golferName") or "").strip()
                # SAME resolver import_tgf_payouts uses on insert — the
                # generic name lookup can't read GG's "VASQUEZ, Gus"
                # format, so consumption missed 26 of 33 preserved rows on
                # the first live run and re-inserted them as duplicates.
                cid = _resolve_customer_for_payout(conn, nm) if nm else None
                hit = None
                if cid:
                    hit = next((i for i, q in enumerate(pool)
                                if q["customer_id"] == cid
                                and q["category"] == p.get("category")
                                and abs((q["amount"] or 0)
                                        - (p.get("amount") or 0)) < 0.005),
                               None)
                if hit is None:
                    remaining.append(p)
                else:
                    pool.pop(hit)
            payouts = remaining
            if not payouts:
                return {"event_id": tgf_event_id, "payouts_added": 0,
                        "matched": 0, "pending": 0, "replaced": removed,
                        "preserved_paid": len(preserved),
                        "tgf_event_code": full}

    stamped = [{**p, "description": "auto: " + (p.get("description") or "")}
               for p in payouts]
    result = import_tgf_payouts(tgf_event_id, stamped, db_path=db_path)
    if isinstance(result, dict) and not result.get("error"):
        result["replaced"] = removed
        result["preserved_paid"] = len(preserved)
        result["tgf_event_code"] = full
        # Consume any Venmo payment emails that arrived BEFORE the payouts
        # were recorded (Kerry sometimes pays from GG's numbers first) —
        # the fresh pending groups can match them immediately.
        try:
            vm = auto_match_venmo_payouts_to_tgf(db_path=db_path)
            if vm.get("matched"):
                result["venmo_matched"] = vm["matched"]
        except Exception:
            logger.warning("post-record venmo payout match failed", exc_info=True)
    return result


def import_tgf_payouts(event_id: int, payouts: list, db_path=None) -> dict:
    """Add payouts to an existing TGF event.

    payouts: [{golferName, category, amount, description}]
      (golferName field retained for backward-compatible API; resolves to customer_id internally)

    Each new payout gets a corresponding acct_transactions entry
    (category='prize_payout'). If a matching Venmo payment already exists
    (exact amount + same customer + within 7 days of event), the payout is
    linked to it. Otherwise a pending expense entry is created.

    Returns {payouts_added, matched, pending, event_id} or {error}.
    """
    if not payouts:
        return {"error": "No payouts provided"}
    with _connect(db_path) as conn:
        ev = conn.execute("SELECT id, name, event_date FROM tgf_events WHERE id = ?", (event_id,)).fetchone()
        if not ev:
            return {"error": f"Event {event_id} not found"}

        added = 0
        new_payout_ids: list[int] = []
        for p in payouts:
            customer_id = _resolve_customer_for_payout(conn, p["golferName"])
            cur = conn.execute(
                """INSERT INTO tgf_payouts (event_id, customer_id, category, amount, description)
                   VALUES (?, ?, ?, ?, ?)""",
                (event_id, customer_id, p["category"], p["amount"], p.get("description", "")),
            )
            new_payout_ids.append(cur.lastrowid)
            added += 1

        # Reconcile new payouts with existing Venmo prize_payouts + create pending entries
        matched = 0
        if new_payout_ids:
            placeholders = ",".join("?" * len(new_payout_ids))
            new_rows = conn.execute(
                f"""SELECT p.id, p.event_id, p.customer_id, p.amount, p.category, p.description,
                           e.event_date, e.name as event_name
                    FROM tgf_payouts p
                    JOIN tgf_events e ON e.id = p.event_id
                    WHERE p.id IN ({placeholders})""",
                new_payout_ids,
            ).fetchall()
            matched = _reconcile_payouts_with_venmo(conn, new_rows)

        # Update event aggregates
        stats = conn.execute(
            """SELECT COUNT(*) as cnt, COALESCE(SUM(amount), 0) as total,
                      COUNT(DISTINCT customer_id) as winners
               FROM tgf_payouts WHERE event_id = ?""",
            (event_id,),
        ).fetchone()
        conn.execute(
            "UPDATE tgf_events SET total_purse = ?, winners_count = ?, payouts_count = ? WHERE id = ?",
            (stats["total"], stats["winners"], stats["cnt"], event_id),
        )
        conn.commit()
        return {
            "event_id": event_id,
            "payouts_added": added,
            "matched": matched,
            "pending": added - matched,
            "total_purse": stats["total"],
        }


def update_tgf_event(event_id: int, data: dict, db_path=None) -> dict:
    """Update event metadata (not payouts)."""
    with _connect(db_path) as conn:
        fields = []
        values = []
        for key in ("name", "event_date", "course", "chapter", "total_purse", "winners_count"):
            if key in data:
                fields.append(f"{key} = ?")
                values.append(data[key])
        if not fields:
            return {"error": "No fields to update"}
        values.append(event_id)
        conn.execute(f"UPDATE tgf_events SET {', '.join(fields)} WHERE id = ?", values)
        conn.commit()
        return {"updated": True}


def delete_tgf_event(event_id: int, db_path=None) -> dict:
    """Delete event and its payouts."""
    with _connect(db_path) as conn:
        conn.execute("DELETE FROM tgf_payouts WHERE event_id = ?", (event_id,))
        conn.execute("DELETE FROM tgf_events WHERE id = ?", (event_id,))
        conn.commit()
        return {"deleted": True}


def add_tgf_golfer(data: dict, db_path=None) -> dict:
    """Add or update a customer's golfer-related info (venmo_username, chapter).

    Backward-compatible name — the API still accepts {name, venmo_username?, chapter?}
    but now operates on the customers table instead of a separate tgf_golfers table.
    """
    with _connect(db_path) as conn:
        customer_id = _resolve_customer_for_payout(conn, data["name"])
        updates = []
        vals = []
        if "venmo_username" in data:
            updates.append("venmo_username = ?")
            vals.append(data["venmo_username"] or None)
        if "chapter" in data:
            updates.append("chapter = ?")
            vals.append(data["chapter"] or None)
        if updates:
            vals.append(customer_id)
            conn.execute(
                f"UPDATE customers SET {', '.join(updates)} WHERE customer_id = ?",
                vals,
            )
        conn.commit()
        return {"customer_id": customer_id, "updated": True}


def import_tgf_golfers(golfers: list[dict], db_path=None) -> dict:
    """Bulk import/update golfer-related fields on customers.

    Each dict: {name, venmo_username?, chapter?}. Resolves each name to a
    customer record (creating one if necessary) and updates its venmo/chapter.
    """
    added = 0
    updated = 0
    with _connect(db_path) as conn:
        for g in golfers:
            name = g.get("name", "").strip()
            if not name:
                continue
            existing_cid = _lookup_customer_id(conn, name, None)
            customer_id = _resolve_customer_for_payout(conn, name)
            if existing_cid is None:
                added += 1  # New customer was created
            else:
                updates = []
                vals = []
                for key in ("venmo_username", "chapter"):
                    if g.get(key):
                        updates.append(f"{key} = ?")
                        vals.append(g[key])
                if updates:
                    vals.append(customer_id)
                    conn.execute(
                        f"UPDATE customers SET {', '.join(updates)} WHERE customer_id = ?",
                        vals,
                    )
                    updated += 1
        conn.commit()
    return {"added": added, "updated": updated}


def get_customer_winnings(customer_name: str, db_path=None, customer_id: int | None = None) -> dict:
    """Look up payout/winnings history for a customer by customer_id.

    ``customer_id``, when the caller already has it (the Customers page has
    it resolved on every card), is used directly instead of re-deriving it
    from ``customer_name`` via the unqualified name-match step of the lookup
    cascade — two different real customers sharing a first+last name would
    otherwise both resolve to whichever one the cascade finds first, showing
    one member the other's payout history under their own name.

    Returns {golfer_name, total_winnings, payouts: [{event_name, event_date, category, amount, description}]}.
    The field name 'golfer_name' is retained for backward-compatible API response shape.
    """
    with _connect(db_path) as conn:
        if customer_id:
            row = conn.execute(
                "SELECT customer_id FROM customers WHERE customer_id = ?", (customer_id,)
            ).fetchone()
            customer_id = row["customer_id"] if row else None
        if not customer_id:
            customer_id = _lookup_customer_id(conn, customer_name, None)
        if customer_id is None:
            return {"golfer_name": None, "total_winnings": 0, "payouts": []}

        cust = conn.execute(
            "SELECT first_name, last_name, suffix FROM customers WHERE customer_id = ?",
            (customer_id,),
        ).fetchone()
        # Include the suffix so Victor Arias Jr and Victor Arias III are
        # distinguishable on every payout surface (Kerry, 2026-07-08)
        display_name = (" ".join(x for x in (cust["first_name"], cust["last_name"],
                                             (cust["suffix"] or "").strip()) if x)
                        if cust else customer_name)

        payouts = [dict(r) for r in conn.execute(
            """SELECT p.amount, p.category,
                      LTRIM(REPLACE(p.description, 'auto: ', ''), ' ') as description,
                      e.name as event_name, e.event_date, e.course
               FROM tgf_payouts p
               JOIN tgf_events e ON e.id = p.event_id
               WHERE p.customer_id = ?
               ORDER BY e.event_date DESC, p.amount DESC""",
            (customer_id,),
        ).fetchall()]

        total = sum(p["amount"] for p in payouts)

        return {
            "golfer_name": display_name,
            "total_winnings": round(total, 2),
            "payouts": payouts,
        }


# ═══════════════════════════════════════════════════════════════
#  COO CHAT SESSION PERSISTENCE
# ═══════════════════════════════════════════════════════════════

def get_chat_sessions(limit: int = 20, db_path=None) -> list[dict]:
    """Return recent chat sessions (newest first)."""
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT s.*, COUNT(m.id) AS message_count
               FROM coo_chat_sessions s
               LEFT JOIN coo_chat_messages m ON m.session_id = s.id
               GROUP BY s.id ORDER BY s.updated_at DESC LIMIT ?""",
            (limit,),
        ).fetchall()
        return [dict(r) for r in rows]


def get_chat_session(session_id: int, db_path=None) -> dict | None:
    """Return a single session with all its messages."""
    with _connect(db_path) as conn:
        sess = conn.execute("SELECT * FROM coo_chat_sessions WHERE id = ?", (session_id,)).fetchone()
        if not sess:
            return None
        msgs = conn.execute(
            "SELECT * FROM coo_chat_messages WHERE session_id = ? ORDER BY created_at ASC",
            (session_id,),
        ).fetchall()
        result = dict(sess)
        result["messages"] = [dict(m) for m in msgs]
        return result


def create_chat_session(title: str = "New Chat", db_path=None) -> dict:
    """Create a new chat session and return it."""
    with _connect(db_path) as conn:
        cur = conn.execute(
            "INSERT INTO coo_chat_sessions (title) VALUES (?)", (title,)
        )
        conn.commit()
        sess = conn.execute("SELECT * FROM coo_chat_sessions WHERE id = ?", (cur.lastrowid,)).fetchone()
        result = dict(sess)
        result["messages"] = []
        return result


def add_chat_message(session_id: int, role: str, content: str, routed_to: str | None = None, db_path=None) -> dict:
    """Append a message to a chat session."""
    with _connect(db_path) as conn:
        cur = conn.execute(
            "INSERT INTO coo_chat_messages (session_id, role, content, routed_to) VALUES (?, ?, ?, ?)",
            (session_id, role, content, routed_to),
        )
        conn.execute(
            "UPDATE coo_chat_sessions SET updated_at = datetime('now') WHERE id = ?",
            (session_id,),
        )
        conn.commit()
        msg = conn.execute("SELECT * FROM coo_chat_messages WHERE id = ?", (cur.lastrowid,)).fetchone()
        return dict(msg)


def update_chat_session_title(session_id: int, title: str, db_path=None) -> dict:
    """Rename a chat session."""
    with _connect(db_path) as conn:
        conn.execute("UPDATE coo_chat_sessions SET title = ? WHERE id = ?", (title, session_id))
        conn.commit()
        sess = conn.execute("SELECT * FROM coo_chat_sessions WHERE id = ?", (session_id,)).fetchone()
        return dict(sess)


def update_chat_session_summary(session_id: int, summary: str, db_path=None) -> dict:
    """Update the running summary of a chat session."""
    with _connect(db_path) as conn:
        conn.execute("UPDATE coo_chat_sessions SET summary = ? WHERE id = ?", (summary, session_id))
        conn.commit()
        sess = conn.execute("SELECT * FROM coo_chat_sessions WHERE id = ?", (session_id,)).fetchone()
        return dict(sess)


def get_chat_master_context(exclude_session_id: int | None = None, db_path=None) -> str:
    """Build a master context string from all past session summaries.
    This gives the AI a 'table of contents' of all prior conversations,
    so it can maintain context across sessions."""
    with _connect(db_path) as conn:
        rows = conn.execute(
            """SELECT id, title, summary, updated_at,
                      (SELECT COUNT(*) FROM coo_chat_messages WHERE session_id = s.id) AS msg_count
               FROM coo_chat_sessions s
               WHERE summary != '' AND summary IS NOT NULL
               ORDER BY updated_at DESC LIMIT 50""",
        ).fetchall()
    if not rows:
        return ""

    lines = ["MASTER CONVERSATION LOG — Table of Contents"]
    lines.append("You have persistent memory of all past conversations with Kerry:")
    lines.append("")
    for r in rows:
        if exclude_session_id and r["id"] == exclude_session_id:
            continue
        date = r["updated_at"] or "unknown"
        lines.append(f"[Session #{r['id']}] {date} — \"{r['title']}\" ({r['msg_count']} messages)")
        if r["summary"]:
            lines.append(f"  Summary: {r['summary']}")
        lines.append("")
    lines.append("Reference these naturally when relevant. If Kerry asks about something discussed before, recall it.")
    return "\n".join(lines)


def delete_chat_session(session_id: int, db_path=None) -> dict:
    """Delete a chat session and all its messages."""
    with _connect(db_path) as conn:
        conn.execute("DELETE FROM coo_chat_messages WHERE session_id = ?", (session_id,))
        conn.execute("DELETE FROM coo_chat_sessions WHERE id = ?", (session_id,))
        conn.commit()
    return {"deleted": session_id}


# ── Batch Categorization Preview & Promotion ─────────────────────────────────

def get_expense_batch_preview(limit: int = 20, offset: int = 0,
                              db_path: str | Path | None = None) -> dict:
    """Return a unified batch of ALL uncategorized transactions with AI suggestions.

    Merges two pools (both sorted by date desc, interleaved):
    - Pool A: expense_transactions WHERE review_status='pending'
      → item_type='expense', on approve: promote to acct_transactions
    - Pool B: acct_transactions with no categorized splits (type != transfer)
      → item_type='acct', on approve: update existing split category

    Each item includes:
    - suggestion: {category_name, entity_name, confidence, source}
    - is_duplicate: True if a matching acct_transaction already covers this
    """
    with _connect(db_path) as conn:
        # --- Count both pools ---
        exp_total = conn.execute(
            "SELECT COUNT(*) as c FROM expense_transactions WHERE review_status = 'pending'"
        ).fetchone()["c"]

        acct_uncategorized_total = conn.execute(
            """SELECT COUNT(*) as c FROM acct_transactions t
               WHERE t.type != 'transfer'
                 AND t.id NOT IN (
                     SELECT s.transaction_id FROM acct_splits s WHERE s.category_id IS NOT NULL
                 )"""
        ).fetchone()["c"]

        total = exp_total + acct_uncategorized_total

        # --- Fetch ALL unprocessed items (both pools, sorted by date) ---
        exp_rows = conn.execute(
            """SELECT id, transaction_date as date, merchant as description,
                      amount as total_amount, source_type as source,
                      transaction_type as type, account_last4, account_name,
                      event_name, notes, 'expense' as item_type
               FROM expense_transactions
               WHERE review_status = 'pending'"""
        ).fetchall()

        acct_rows = conn.execute(
            """SELECT t.id, t.date, t.description, t.total_amount, t.source,
                      t.type, NULL as account_last4, a.name as account_name,
                      t.event_name, t.notes, 'acct' as item_type
               FROM acct_transactions t
               LEFT JOIN acct_accounts a ON a.id = t.account_id
               WHERE t.type != 'transfer'
                 AND t.id NOT IN (
                     SELECT s.transaction_id FROM acct_splits s WHERE s.category_id IS NOT NULL
                 )"""
        ).fetchall()

        # Merge and sort by date descending
        all_rows = sorted(
            [dict(r) for r in exp_rows] + [dict(r) for r in acct_rows],
            key=lambda r: (r.get("date") or ""),
            reverse=True,
        )
        page_rows = all_rows[offset: offset + limit]

        suggestion_data = get_expense_suggestions(conn)

        # Fingerprints of existing acct_transactions for duplicate detection
        # (only used to flag expense items — acct items are already in the ledger)
        acct_fps = set()
        for r in conn.execute(
            "SELECT date, total_amount, source FROM acct_transactions WHERE COALESCE(status,'active') != 'reversed'"
        ).fetchall():
            acct_fps.add((r["date"] or "", round(float(r["total_amount"] or 0), 2),
                         (r["source"] or "").lower()))

        # Run AI suggestions on the page's descriptions in one batch
        descriptions = [r.get("description") or "" for r in page_rows]
        types        = [r.get("type") or "expense" for r in page_rows]
        ai_suggestions = auto_categorize_transactions(descriptions, types, db_path)

        items = []
        for r, ai_sug in zip(page_rows, ai_suggestions):
            item_type = r.get("item_type", "expense")
            merchant  = r.get("description") or ""
            src       = r.get("source") or ""

            # Prefer AI suggestion; fall back to merchant-based lookup for expense items
            if ai_sug and ai_sug.get("confidence") not in (None, "none", "skip"):
                sug_cat  = ai_sug.get("category_name") or ""
                sug_ent  = ai_sug.get("entity_name") or ""
                sug_conf = ai_sug.get("confidence") or "none"
                sug_src  = ai_sug.get("source") or ""
            else:
                fallback = suggest_for_merchant(merchant, suggestion_data) or {}
                sug_cat  = fallback.get("category") or ""
                sug_ent  = fallback.get("entity") or ""
                sug_conf = fallback.get("confidence") or "none"
                sug_src  = fallback.get("source") or ""

            # Duplicate flag only relevant for expense items
            is_duplicate = False
            if item_type == "expense":
                fp = (r.get("date") or "",
                      round(float(r.get("total_amount") or 0), 2),
                      src.lower())
                is_duplicate = fp in acct_fps

            items.append({
                "id":               r["id"],
                "item_type":        item_type,
                "date":             r.get("date"),
                "merchant":         merchant,
                "amount":           r.get("total_amount"),
                "source_type":      src,
                "transaction_type": r.get("type") or "expense",
                "account_last4":    r.get("account_last4"),
                "account_name":     r.get("account_name"),
                "event_name":       r.get("event_name"),
                "notes":            r.get("notes"),
                "suggestion": {
                    "category_name": sug_cat,
                    "entity_name":   sug_ent,
                    "confidence":    sug_conf,
                    "source":        sug_src,
                },
                "is_duplicate": is_duplicate,
            })

    categories = get_acct_categories(db_path=db_path)
    entities   = get_all_acct_entities(db_path=db_path)

    return {
        "items":      items,
        "total":      total,
        "exp_total":  exp_total,
        "acct_total": acct_uncategorized_total,
        "limit":      limit,
        "offset":     offset,
        "categories": categories,
        "entities":   entities,
    }


def promote_expense_to_ledger(expense_id: int, category_name: str | None,
                               entity_name: str | None, account_id: int | None = None,
                               event_name: str | None = None, notes: str | None = None,
                               db_path: str | Path | None = None) -> dict:
    """Promote an approved expense_transaction into acct_transactions.

    Creates a proper ledger entry + split, links the two tables via
    expense_transactions.acct_transaction_id, and learns a keyword rule
    if a confident category assignment was made.
    """
    with _connect(db_path) as conn:
        exp = conn.execute(
            "SELECT * FROM expense_transactions WHERE id = ?", (expense_id,)
        ).fetchone()
        if not exp:
            return {"error": f"expense_transaction {expense_id} not found"}
        exp = dict(exp)

        # If already promoted, return the linked acct_transaction
        if exp.get("acct_transaction_id"):
            return {"skipped": True, "acct_transaction_id": exp["acct_transaction_id"]}

        # Resolve category FK
        category_id = None
        if category_name:
            cat_row = conn.execute(
                "SELECT id FROM acct_categories WHERE LOWER(name) = LOWER(?) LIMIT 1",
                (category_name,),
            ).fetchone()
            if cat_row:
                category_id = cat_row["id"]

        # Resolve entity FK
        entity_id = None
        if entity_name:
            ent_row = conn.execute(
                "SELECT id FROM acct_entities WHERE LOWER(short_name) = LOWER(?) OR LOWER(name) = LOWER(?) LIMIT 1",
                (entity_name, entity_name),
            ).fetchone()
            if ent_row:
                entity_id = ent_row["id"]

        # Resolve event FK for split
        event_id = None
        lookup_event = event_name or exp.get("event_name")
        if lookup_event:
            ev_row = conn.execute(
                "SELECT id FROM events WHERE LOWER(item_name) = LOWER(?) LIMIT 1",
                (lookup_event,),
            ).fetchone()
            if ev_row:
                event_id = ev_row["id"]

        # Use default checking account if none provided
        if not account_id:
            acc_row = conn.execute(
                "SELECT id FROM acct_accounts WHERE account_type = 'checking' AND is_active = 1 LIMIT 1"
            ).fetchone()
            if acc_row:
                account_id = acc_row["id"]

        # Map raw transaction_type to the CHECK-allowed type values
        # ('income', 'expense', 'transfer'). Same map as in
        # _sync_expense_ledger_entry — kept in sync.
        _raw_txn_type = exp.get("transaction_type") or "expense"
        _type_map = {"received": "income", "payout": "expense",
                     "expense": "expense", "transfer": "transfer"}
        txn_type = _type_map.get(_raw_txn_type, "expense")
        amount = float(exp.get("amount") or 0)
        merchant = exp.get("merchant") or "(unknown)"
        txn_date = exp.get("transaction_date") or today_central_str()
        source = exp.get("source_type") or "manual"
        source_ref = f"exp-promoted-{expense_id}"
        final_notes = notes or exp.get("notes")

        cur = conn.execute(
            """INSERT INTO acct_transactions
               (date, description, total_amount, amount, type, entry_type,
                account_id, source, source_ref, notes, event_name)
               VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)""",
            (txn_date, merchant, amount, amount, txn_type, txn_type,
             account_id, source, source_ref, final_notes, lookup_event),
        )
        txn_id = cur.lastrowid

        conn.execute(
            """INSERT INTO acct_splits
               (transaction_id, entity_id, category_id, amount, event_id)
               VALUES (?, ?, ?, ?, ?)""",
            (txn_id, entity_id, category_id, amount, event_id),
        )

        # Mark expense as promoted
        conn.execute(
            """UPDATE expense_transactions
               SET review_status = 'approved', acct_transaction_id = ?,
                   reviewed_at = datetime('now')
               WHERE id = ?""",
            (txn_id, expense_id),
        )

        # Learn a keyword rule for future auto-categorization
        if category_id and merchant:
            existing_rule = conn.execute(
                "SELECT id FROM acct_keyword_rules WHERE LOWER(keyword) = LOWER(?) AND category_id = ? LIMIT 1",
                (merchant, category_id),
            ).fetchone()
            if not existing_rule:
                try:
                    conn.execute(
                        """INSERT INTO acct_keyword_rules (keyword, match_type, category_id, entity_id, is_active)
                           VALUES (?, 'contains', ?, ?, 1)""",
                        (merchant, category_id, entity_id),
                    )
                except sqlite3.IntegrityError:
                    pass

        conn.commit()

    return {"promoted": True, "acct_transaction_id": txn_id, "expense_id": expense_id}


def _approve_acct_item(txn_id: int, category_name: str | None,
                        entity_name: str | None, event_name: str | None = None,
                        db_path: str | Path | None = None) -> None:
    """Apply a category + entity to an existing acct_transaction's split."""
    with _connect(db_path) as conn:
        category_id = None
        if category_name:
            row = conn.execute(
                "SELECT id FROM acct_categories WHERE LOWER(name) = LOWER(?) LIMIT 1",
                (category_name,),
            ).fetchone()
            if row:
                category_id = row["id"]

        entity_id = None
        if entity_name:
            row = conn.execute(
                "SELECT id FROM acct_entities WHERE LOWER(short_name) = LOWER(?) OR LOWER(name) = LOWER(?) LIMIT 1",
                (entity_name, entity_name),
            ).fetchone()
            if row:
                entity_id = row["id"]

        event_id = None
        if event_name:
            row = conn.execute(
                "SELECT id FROM events WHERE LOWER(item_name) = LOWER(?) LIMIT 1",
                (event_name,),
            ).fetchone()
            if row:
                event_id = row["id"]

        split = conn.execute(
            "SELECT id FROM acct_splits WHERE transaction_id = ? LIMIT 1", (txn_id,)
        ).fetchone()

        if split:
            conn.execute(
                """UPDATE acct_splits SET category_id = ?, entity_id = ?,
                   event_id = COALESCE(?, event_id) WHERE id = ?""",
                (category_id, entity_id, event_id, split["id"]),
            )
        else:
            # No split yet — create one
            txn = conn.execute(
                "SELECT total_amount FROM acct_transactions WHERE id = ?", (txn_id,)
            ).fetchone()
            if txn:
                conn.execute(
                    """INSERT INTO acct_splits (transaction_id, entity_id, category_id, amount, event_id)
                       VALUES (?, ?, ?, ?, ?)""",
                    (txn_id, entity_id, category_id, txn["total_amount"], event_id),
                )
        conn.commit()


def batch_approve_expenses(items: list[dict],
                           db_path: str | Path | None = None) -> dict:
    """Approve a mixed batch of expense_transactions and acct_transactions.

    Each item: {id, item_type, category_name, entity_name, account_id?, event_name?, notes?}
    - item_type='expense' → promote via promote_expense_to_ledger
    - item_type='acct'    → update existing split via _approve_acct_item

    Returns {approved, skipped, errors}.
    """
    approved, skipped, errors = 0, 0, []
    for item in items:
        item_id   = item.get("id")
        item_type = item.get("item_type", "expense")
        if not item_id:
            continue
        if item.get("skip"):
            skipped += 1
            continue
        try:
            if item_type == "acct":
                _approve_acct_item(
                    txn_id=item_id,
                    category_name=item.get("category_name"),
                    entity_name=item.get("entity_name"),
                    event_name=item.get("event_name"),
                    db_path=db_path,
                )
                approved += 1
            else:
                result = promote_expense_to_ledger(
                    expense_id=item_id,
                    category_name=item.get("category_name"),
                    entity_name=item.get("entity_name"),
                    account_id=item.get("account_id"),
                    event_name=item.get("event_name"),
                    notes=item.get("notes"),
                    db_path=db_path,
                )
                if result.get("skipped"):
                    skipped += 1
                else:
                    approved += 1
        except Exception as e:
            errors.append({"id": item_id, "error": str(e)})
    return {"approved": approved, "skipped": skipped, "errors": errors}


# ─────────────────────────────────────────────────────────────────────────────
# Pairings
# ─────────────────────────────────────────────────────────────────────────────

def _nine_side(event: dict) -> str:
    """Which nine the 9-hole leg plays: 'Front' (default) or 'Back'."""
    side = str(event.get("nine_side") or "Front").strip().title()
    return "Back" if side == "Back" else "Front"


def _pairing_time_slots(event: dict, holes: str) -> list[str]:
    """Compute ordered slot labels for a given holes type (9 or 18).

    For tee-time events returns formatted clock strings ("8:00 AM", …).
    For shotgun events returns hole identifiers ("1A", "1B", "2A", …).
    """
    combo = (event.get("format") or "").strip() == "9/18 Combo"
    if combo and holes == "18":
        start_type = event.get("start_type_18") or "Tee Times"
        start_time = event.get("start_time_18")
        count = event.get("tee_time_count_18") or 0
    else:
        start_type = event.get("start_type") or "Tee Times"
        start_time = event.get("start_time")
        count = event.get("tee_time_count") or 0

    interval = event.get("tee_time_interval") or 10
    count = int(count)
    interval = int(interval)

    if count == 0:
        return []

    if start_type == "Shotgun":
        # The 9-hole leg can play the BACK nine (events.nine_side = 'Back',
        # Kerry 2026-07-21): hole labels start at 10. 18-hole legs use all
        # 18 holes, so the side setting doesn't apply there.
        base_hole = 1
        if holes == "9" and _nine_side(event) == "Back":
            base_hole = 10
        return [f"{(i // 2) + base_hole}{'A' if i % 2 == 0 else 'B'}"
                for i in range(count)]

    if not start_time:
        return [f"Group {i + 1}" for i in range(count)]

    try:
        base = datetime.strptime(start_time, "%H:%M")
    except ValueError:
        return [f"Group {i + 1}" for i in range(count)]

    slots = []
    for i in range(count):
        t = base + timedelta(minutes=i * interval)
        label = t.strftime("%I:%M %p").lstrip("0") or "12:00 AM"
        slots.append(label)
    return slots


def _ensure_pairing_tables(conn: sqlite3.Connection) -> None:
    """Create pairing tables if they don't exist (handles live DB migration)."""
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS event_pairings (
            id             INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id       INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
            holes          TEXT NOT NULL CHECK(holes IN ('9', '18')),
            group_num      INTEGER NOT NULL,
            slot_label     TEXT NOT NULL,
            player_name    TEXT NOT NULL,
            cart_pos       INTEGER NOT NULL CHECK(cart_pos BETWEEN 1 AND 5),
            tee_choice     TEXT,
            handicap_index REAL,
            created_at     TEXT DEFAULT (datetime('now')),
            UNIQUE(event_id, holes, group_num, cart_pos)
        )
        """
    )
    # FIVESOMES (Kerry 2026-07-31): cart_pos used to be capped at 4 by a
    # CHECK constraint, so a manually added 5th player could not be SAVED
    # at all. SQLite can't alter a CHECK in place, so rebuild the table
    # once on a live DB. Idempotent — the marker is the old constraint
    # text itself.
    try:
        _ep = conn.execute(
            "SELECT sql FROM sqlite_master WHERE type='table' "
            "AND name='event_pairings'").fetchone()
        if _ep and "BETWEEN 1 AND 4" in (_ep["sql"] or ""):
            conn.execute("ALTER TABLE event_pairings RENAME TO _event_pairings_o")
            conn.execute(
                """
                CREATE TABLE event_pairings (
                    id             INTEGER PRIMARY KEY AUTOINCREMENT,
                    event_id       INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
                    holes          TEXT NOT NULL CHECK(holes IN ('9', '18')),
                    group_num      INTEGER NOT NULL,
                    slot_label     TEXT NOT NULL,
                    player_name    TEXT NOT NULL,
                    cart_pos       INTEGER NOT NULL CHECK(cart_pos BETWEEN 1 AND 5),
                    tee_choice     TEXT,
                    handicap_index REAL,
                    created_at     TEXT DEFAULT (datetime('now')),
                    UNIQUE(event_id, holes, group_num, cart_pos)
                )
                """
            )
            conn.execute(
                """INSERT INTO event_pairings
                       (id, event_id, holes, group_num, slot_label,
                        player_name, cart_pos, tee_choice, handicap_index,
                        created_at)
                   SELECT id, event_id, holes, group_num, slot_label,
                          player_name, cart_pos, tee_choice, handicap_index,
                          created_at
                   FROM _event_pairings_o""")
            conn.execute("DROP TABLE _event_pairings_o")
            logger.info("event_pairings: cart_pos ceiling raised 4 -> 5 "
                        "(fivesome support)")
    except Exception:
        logger.exception("Non-fatal: event_pairings cart_pos migration failed")
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_event_pairings_event ON event_pairings(event_id)"
    )
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS pairing_history (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            player_a    TEXT NOT NULL,
            player_b    TEXT NOT NULL,
            event_id    INTEGER NOT NULL REFERENCES events(id),
            event_date  TEXT NOT NULL,
            created_at  TEXT DEFAULT (datetime('now')),
            UNIQUE(player_a, player_b, event_id)
        )
        """
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_pairing_history_ab ON pairing_history(player_a, player_b)"
    )
    conn.execute(
        "CREATE INDEX IF NOT EXISTS idx_pairing_history_date ON pairing_history(event_date)"
    )
    # Ratified customer_id amendment (pairings.md, Kerry "GO" 2026-07-12),
    # applied additively: pair customer ids, the rode-with flag (tee-sheet
    # sequence 1&2 / 3&4 ride together — Kerry's cart ruling), and the
    # row's source ('app' saves vs 'gg_teesheet' ingest).
    for col, decl in (("customer_a_id", "INTEGER"), ("customer_b_id", "INTEGER"),
                      ("rode", "INTEGER DEFAULT 0"),
                      ("source", "TEXT DEFAULT 'app'")):
        try:
            conn.execute(f"ALTER TABLE pairing_history ADD COLUMN {col} {decl}")
        except sqlite3.OperationalError:
            pass  # already added
    # Manager-suppressed partner requests (Kerry 2026-07-21): a row here
    # means the generator ignores that requester's partner_request for
    # this event. The request stays visible in the PAIRINGS requests
    # list, badged SUPPRESSED, until the row is removed (restore).
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS pairing_request_suppressions (
            id                    INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id              INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
            requester_name        TEXT NOT NULL,
            requester_customer_id INTEGER REFERENCES customers(customer_id),
            created_at            TEXT DEFAULT (datetime('now')),
            UNIQUE(event_id, requester_name)
        )
        """
    )
    # Manager APPROVAL of an outranked request (Kerry 2026-07-31).
    # First-come is the default (rule 11), but the manager is the
    # override (rule 5) — an approved request is honored even though the
    # partner was claimed earlier, by JOINING that group rather than
    # displacing anyone. A foursome is still the hard ceiling.
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS pairing_request_approvals (
            id                    INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id              INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
            requester_name        TEXT NOT NULL,
            requester_customer_id INTEGER REFERENCES customers(customer_id),
            approved_by           TEXT,
            created_at            TEXT DEFAULT (datetime('now')),
            UNIQUE(event_id, requester_name)
        )
        """
    )
    # Manager-fixed request matches (Kerry 2026-07-21): when the signup
    # text doesn't resolve to a rostered player ('Dave' vs 'David
    # Decareaux'), the manager binds the request to the intended player.
    # The generator substitutes this exact roster name for the raw text.
    conn.execute(
        """
        CREATE TABLE IF NOT EXISTS pairing_request_matches (
            id                    INTEGER PRIMARY KEY AUTOINCREMENT,
            event_id              INTEGER NOT NULL REFERENCES events(id) ON DELETE CASCADE,
            requester_name        TEXT NOT NULL,
            requester_customer_id INTEGER REFERENCES customers(customer_id),
            partner_name          TEXT NOT NULL,
            partner_customer_id   INTEGER REFERENCES customers(customer_id),
            created_at            TEXT DEFAULT (datetime('now')),
            UNIQUE(event_id, requester_name)
        )
        """
    )
    conn.commit()


def get_event_pairings(event_id: int, db_path=None) -> dict:
    """Return saved pairings for an event keyed by holes ('9' / '18').

    Each value is a list of groups:
        [{"group_num": int, "slot_label": str, "players": [...]}, ...]
    Players: {"name", "cart_pos", "tee_choice", "handicap_index"}
    """
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        rows = conn.execute(
            """
            SELECT holes, group_num, slot_label, player_name,
                   cart_pos, tee_choice, handicap_index
            FROM event_pairings
            WHERE event_id = ?
            ORDER BY holes, group_num, cart_pos
            """,
            (event_id,),
        ).fetchall()

    result: dict = {}
    for r in rows:
        h = r["holes"]
        if h not in result:
            result[h] = []
        grp_list = result[h]
        # Find or create the group entry
        grp = next((g for g in grp_list if g["group_num"] == r["group_num"]), None)
        if grp is None:
            grp = {"group_num": r["group_num"], "slot_label": r["slot_label"], "players": []}
            grp_list.append(grp)
        grp["players"].append({
            "name": r["player_name"],
            "cart_pos": r["cart_pos"],
            "tee_choice": r["tee_choice"],
            "handicap_index": r["handicap_index"],
        })
    return result


def get_event_print_pack(event_id: int, db_path=None) -> dict | None:
    """Assemble the data for the Starter Sheet + Cart Signs printables (B5).

    Reads the event row + saved pairings (get_event_pairings) and shapes them
    into an ordered group list, each group carrying its tee-time/hole slot,
    players, and cart split (Kerry's ruling: seats 1&2 = Cart A, 3&4 = Cart B).
    Read-only; returns None if the event has no id. handicap_index is the value
    the pairings carry (9-hole index the generator stored) — labeled "Idx" on
    the sheet, NOT presented as a playing handicap."""
    with _connect(db_path) as conn:
        ev = conn.execute("SELECT * FROM events WHERE id = ?", (event_id,)).fetchone()
        if not ev:
            return None
        ev = dict(ev)
    pairings = get_event_pairings(event_id, db_path=db_path)

    def _carts(players: list) -> list:
        ps = sorted(players, key=lambda p: p.get("cart_pos") or 0)
        carts = []
        for lo, hi, label in ((1, 2, "A"), (3, 4, "B")):
            occ = [p for p in ps if (p.get("cart_pos") or 0) in (lo, hi)]
            if occ:
                carts.append({"label": label, "players": occ})
        return carts

    groups = []
    for holes in ("9", "18"):
        for g in (pairings.get(holes) or []):
            players = sorted(g.get("players") or [],
                             key=lambda p: p.get("cart_pos") or 0)
            groups.append({
                "holes": holes,
                "group_num": g.get("group_num"),
                "slot_label": g.get("slot_label") or f"Group {g.get('group_num')}",
                "players": players,
                "carts": _carts(players),
            })
    return {
        "event": {
            "id": event_id,
            "item_name": ev.get("item_name"),
            "event_date": ev.get("event_date"),
            "course": ev.get("course"),
            "chapter": ev.get("chapter"),
            "format": ev.get("format"),
            "start_type": ev.get("start_type"),
        },
        "groups": groups,
        "group_count": len(groups),
    }


def save_event_pairings(event_id: int, groups_by_holes: dict, db_path=None) -> None:
    """Persist pairings for an event and rebuild pairing_history rows.

    groups_by_holes: {"9": [...], "18": [...]}
    Each group: {"group_num", "slot_label", "players": [{"name", "cart_pos",
                  "tee_choice", "handicap_index"}]}
    """
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        # Load event date for history
        ev_row = conn.execute(
            "SELECT event_date FROM events WHERE id = ?", (event_id,)
        ).fetchone()
        event_date = ev_row["event_date"] if ev_row else datetime.now().strftime("%Y-%m-%d")

        # Replace existing pairings for this event
        conn.execute("DELETE FROM event_pairings WHERE event_id = ?", (event_id,))
        conn.execute("DELETE FROM pairing_history WHERE event_id = ?", (event_id,))

        for holes, groups in groups_by_holes.items():
            for grp in groups:
                group_num = grp["group_num"]
                slot_label = grp["slot_label"]
                for p in grp["players"]:
                    conn.execute(
                        """
                        INSERT OR REPLACE INTO event_pairings
                            (event_id, holes, group_num, slot_label, player_name,
                             cart_pos, tee_choice, handicap_index)
                        VALUES (?, ?, ?, ?, ?, ?, ?, ?)
                        """,
                        (
                            event_id, holes, group_num, slot_label,
                            p["name"], p["cart_pos"],
                            p.get("tee_choice"), p.get("handicap_index"),
                        ),
                    )

                # Record every pair in history — rode pairs by cart_pos
                # (1&2 / 3&4, Kerry's ruling), customer ids by exact
                # canonical-name match (best effort; NULL when unknown)
                ordered = sorted(grp["players"], key=lambda p: p["cart_pos"])
                player_names = [p["name"] for p in ordered]
                rode_pairs = set()
                for lo, hi in ((0, 1), (2, 3)):
                    if hi < len(player_names):
                        rode_pairs.add(frozenset((player_names[lo], player_names[hi])))
                def _cid_for_name(nm):
                    row = conn.execute(
                        """SELECT customer_id FROM customers
                           WHERE TRIM(COALESCE(first_name,'') || ' ' ||
                                 COALESCE(last_name,'')) = ? COLLATE NOCASE""",
                        (nm,)).fetchone()
                    return row["customer_id"] if row else None
                for i in range(len(player_names)):
                    for j in range(i + 1, len(player_names)):
                        a = min(player_names[i], player_names[j])
                        b = max(player_names[i], player_names[j])
                        conn.execute(
                            """
                            INSERT OR IGNORE INTO pairing_history
                                (player_a, player_b, event_id, event_date,
                                 customer_a_id, customer_b_id, rode, source)
                            VALUES (?, ?, ?, ?, ?, ?, ?, 'app')
                            """,
                            (a, b, event_id, event_date,
                             _cid_for_name(a), _cid_for_name(b),
                             1 if frozenset((a, b)) in rode_pairs else 0),
                        )

        conn.commit()


def delete_event_pairings(event_id: int, db_path=None) -> None:
    """Remove saved pairings (and their history) for an event."""
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        conn.execute("DELETE FROM event_pairings WHERE event_id = ?", (event_id,))
        conn.execute("DELETE FROM pairing_history WHERE event_id = ?", (event_id,))
        conn.commit()


_SHOTGUN_LABEL_RE = re.compile(r"^(\d{1,2})([AB])$")


def switch_event_pairings_side(event_id: int, db_path=None) -> dict:
    """Flip the event's 9-hole side (Front ↔ Back) and shift any SAVED
    9-hole shotgun slot labels with it (1A ↔ 10A, 3B ↔ 12B, …) so the
    PAIRINGS tab and printables stay consistent without a regenerate
    (Kerry 2026-07-21: back-9 nights at The Quarry). Non-shotgun events
    just flip the setting — tee-time labels carry no hole number.
    """
    with _connect(db_path) as conn:
        ev = conn.execute("SELECT * FROM events WHERE id = ?",
                          (event_id,)).fetchone()
        if not ev:
            raise ValueError(f"Event {event_id} not found")
        ev = dict(ev)
        new_side = "Front" if _nine_side(ev) == "Back" else "Back"
        conn.execute("UPDATE events SET nine_side = ? WHERE id = ?",
                     (new_side, event_id))

        relabeled = 0
        if (ev.get("start_type") or "") == "Shotgun":
            _ensure_pairing_tables(conn)
            shift = 9 if new_side == "Back" else -9
            rows = conn.execute(
                "SELECT id, slot_label FROM event_pairings "
                "WHERE event_id = ? AND holes = '9'", (event_id,)).fetchall()
            for r in rows:
                m = _SHOTGUN_LABEL_RE.match((r["slot_label"] or "").strip())
                if not m:
                    continue
                hole = int(m.group(1)) + shift
                if not 1 <= hole <= 18:
                    continue  # label already on the target side — leave it
                conn.execute(
                    "UPDATE event_pairings SET slot_label = ? WHERE id = ?",
                    (f"{hole}{m.group(2)}", r["id"]))
                relabeled += 1
        conn.commit()
        return {"nine_side": new_side, "relabeled": relabeled}


def _request_time_key(item: dict):
    """Chronological key for signup-order request priority (Kerry
    2026-07-21): business order date first, then ingest timestamp, then
    row id (autoincrement ≈ arrival order) as the tiebreak. Missing
    values sort LAST so a dated signup always outranks an undated one."""
    return ((item.get("order_date") or "9999-99-99"),
            (item.get("created_at") or "9999"),
            item.get("id") or float("inf"))


HOST_GROUP_MAX = 4


def _host_of_map(rows: list[dict], all_names: list[str],
                 roster_ids: dict | None = None) -> dict:
    """{guest key -> host key} — who paid for whose spot (Kerry 2026-07-30).

    Two rules hang off this:
      * a bought-for player is ASSUMED to want to play with their host —
        no request text needed;
      * "A member can bring as many guests as they want and play with up
        to 3", so a host plus three guests is a legitimate FOURSOME, not
        three competing pair requests where the last two lose.

    Detected two ways, because the note alone proved unreliable in the
    field (Kerry 2026-07-31: Villa and Kypuros were still OUTRANKED
    against Daniel South, who had paid for all three):
      (a) the "Purchased by <buyer>" note — an explicit statement, so it
          wins where present, and it is the ONLY signal when the host
          bought the spot on a separate order;
      (b) SAME order_id — the structural fact the note is only a
          rendering of. A multi-spot order has exactly one payer;
          everybody else on it had their spot bought. This survives
          re-assignment, note edits, and a buyer name that no longer
          matches the roster spelling.

    `rows` must carry customer / notes / order_id / customer_email.
    """
    host_of: dict = {}

    # (a) explicit note
    for r in rows:
        m = re.match(r"\s*Purchased by\s+(.+?)\s*$", (r.get("notes") or ""),
                     re.I)
        if not m:
            continue
        host = _find_partner_name(m.group(1), all_names, r.get("customer"),
                                  roster_ids=roster_ids)
        if host:
            host_of[_pair_key_name(r.get("customer"))] = _pair_key_name(host)

    # (b) same order = same payer. Buyer picked by the same rule the
    # Transactions order-group header uses (`pickBuyerRow` in
    # dashboard.js): only the buyer's row keeps customer_email, and the
    # extras carry the Purchased-by note. customer_email is read here as
    # a BUYER MARKER only, never as a contact address, so the
    # identity-drift rule about items.* doesn't bite.
    def _is_extra(row):
        return bool(re.match(r"\s*Purchased by\s", (row.get("notes") or ""),
                             re.I))

    by_order: dict = {}
    for r in rows:
        oid = str(r.get("order_id") or "").strip()
        if oid and not oid.lower().startswith("manual"):
            by_order.setdefault(oid, []).append(r)
    for orows in by_order.values():
        if len(orows) < 2:
            continue
        buyer = (next((x for x in orows
                       if (x.get("customer_email") or "").strip()
                       and not _is_extra(x)), None)
                 or next((x for x in orows if not _is_extra(x)), None)
                 or orows[0])
        bk = _pair_key_name(buyer.get("customer"))
        for x in orows:
            xk = _pair_key_name(x.get("customer"))
            if xk and bk and xk != bk:
                host_of.setdefault(xk, bk)

    # Collapse chains (a guest of a guest) to the ultimate host, and drop
    # any cycle rather than looping — two people can't have bought each
    # other's spot, so a cycle means the data is wrong, not two hosts.
    def _ultimate(k):
        seen_h, cur = {k}, host_of.get(k)
        while cur is not None and cur in host_of:
            if cur in seen_h:
                return None
            seen_h.add(cur)
            cur = host_of[cur]
        return cur

    return {k: h for k, h in ((k, _ultimate(k)) for k in list(host_of))
            if h and h != k}


def _host_units(host_of: dict, players: list[str],
                max_size: int = HOST_GROUP_MAX) -> list[list[str]]:
    """Host-and-guests foursomes, as unsplittable units of roster NAMES.

    The generator must build the same groups the requests panel promises
    — a panel that badges Villa and Kypuros CONFIRMED with their host
    while the generator still splits them off is worse than no badge.
    Restricted to `players` (one holes bucket), capped at `max_size`,
    guests in roster order so the cap is deterministic.
    """
    by_key = {_pair_key_name(n): n for n in players if n}
    units: list[list[str]] = []
    hosts = [h for h in dict.fromkeys(host_of.values()) if h in by_key]
    for h in hosts:
        guests = [g for g in host_of if host_of[g] == h and g in by_key]
        if not guests:
            continue
        unit = [by_key[h]] + [by_key[g] for g in guests]
        if len(unit) >= 2:
            units.append(unit[:max_size])
    return units


def get_event_partner_requests(event_id: int, db_path=None) -> dict:
    """Who requested whom on this event's roster (Kerry 2026-07-21).

    One entry per rostered player carrying a partner_request: the raw
    request text, the rostered player it resolved to (same matching rule
    the generator uses — _find_partner_name), and whether the manager
    SUPPRESSED it. Suppressed requests stay in the list (visibility) but
    the generator ignores them on the next run. Unmatched text is shown
    too (matched=false) so the manager can see intent the generator
    can't act on.
    """
    INACTIVE = ("credited", "refunded", "transferred", "wd")
    ph = ",".join("?" * len(INACTIVE))
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        # A very old events table may predate the column; a missing
        # switch just means no fivesomes, which is the default anyway.
        try:
            _evr = conn.execute(
                "SELECT allow_fivesomes FROM events WHERE id = ?",
                (event_id,)).fetchone()
            group_max = 5 if (_evr and int(_evr["allow_fivesomes"] or 0)) else 4
        except sqlite3.OperationalError:
            group_max = 4
        group_word = "fivesome" if group_max == 5 else "foursome"
        rows = conn.execute(
            f"""
            SELECT DISTINCT i.customer, i.customer_id, i.holes,
                            i.partner_request, i.id, i.order_date,
                            i.created_at, i.notes, i.order_id,
                            i.customer_email, i.user_status,
                            c.current_player_status
            FROM events e
            LEFT JOIN event_aliases ea ON ea.canonical_event_name = e.item_name
            JOIN items i ON (
                i.item_name = e.item_name COLLATE NOCASE
                OR i.item_name = ea.alias_name COLLATE NOCASE
                OR i.event_id = e.id
            )
            LEFT JOIN customers c ON c.customer_id = i.customer_id
            WHERE e.id = ?
              AND COALESCE(i.transaction_status, 'active') NOT IN ({ph})
              AND i.parent_item_id IS NULL
            ORDER BY i.customer COLLATE NOCASE
            """,
            (event_id, *INACTIVE),
        ).fetchall()
        suppressed = {_pair_key_name(r["requester_name"]) for r in conn.execute(
            "SELECT requester_name FROM pairing_request_suppressions "
            "WHERE event_id = ?", (event_id,)).fetchall()}
        manual_matches = {_pair_key_name(r["requester_name"]): r["partner_name"]
                          for r in conn.execute(
            "SELECT requester_name, partner_name FROM pairing_request_matches "
            "WHERE event_id = ?", (event_id,)).fetchall()}
        approvals = {_pair_key_name(r["requester_name"]) for r in conn.execute(
            "SELECT requester_name FROM pairing_request_approvals "
            "WHERE event_id = ?", (event_id,)).fetchall()}

    # Earliest signup row per player, in signup order — the SAME
    # ordering + dedup the generator uses, so this list's priority
    # simulation matches what Generate will actually do.
    rows = sorted((dict(r) for r in rows), key=_request_time_key)
    seen: set = set()
    roster: list[dict] = []
    for r in rows:
        k = _pair_key_name(r.get("customer") or "")
        if not k or k in seen:
            continue
        seen.add(k)
        roster.append(r)

    all_names = [r["customer"] for r in roster]
    # The roster rows already carry the authoritative identity key, so
    # partner matching resolves id-to-id instead of string-to-string
    # (guiding principle 6 / Kerry 2026-07-30).
    roster_ids = {r["customer"]: r["customer_id"] for r in roster
                  if r.get("customer_id")}

    host_names = {_pair_key_name(r["customer"]): r["customer"] for r in roster}
    host_of = _host_of_map(roster, all_names, roster_ids=roster_ids)

    # GUEST LATITUDE (Kerry 2026-07-31). "It's a system to give all guests
    # the ability to feel the group out and play with who they want, but
    # require the members to branch out, beyond a single player request."
    # So the first-come lock (rule 11) binds MEMBERS. A guest's request is
    # honored even when their partner was claimed earlier — the guest joins
    # that group instead of losing to it. A foursome is still the ceiling,
    # and a manager can still suppress any request.
    #
    # Membership is decided by the ROSTER, never by the order label: a "1st
    # Timer" can be either (Kerry 2026-07-30, Villa/Kypuros), so
    # `_ls_is_member` lets customers.current_player_status rule and treats
    # items.user_status as a fallback that can only rule someone OUT.
    is_member_of = {
        _pair_key_name(r["customer"]): bool(_ls_is_member(
            r.get("current_player_status"), r.get("user_status")))
        for r in roster}

    def _host_group(key):
        """The host-and-guests set `key` belongs to, or None."""
        h = host_of.get(key, key if key in host_of.values() else None)
        if h is None:
            return None
        members = {h} | {g for g, hh in host_of.items() if hh == h}
        return members if len(members) > 1 else None

    requests = []
    # Who is grouped with whom, as UNITS rather than pairs. A pair-only
    # model can't express "join the group that already exists", which is
    # what both a host-and-guests foursome and a manager APPROVAL of an
    # outranked request need (Kerry 2026-07-30 / 2026-07-31).
    units: list[set] = []
    unit_of: dict = {}              # player key -> index into `units`

    def _unit(k):
        i = unit_of.get(k)
        return units[i] if i is not None else None

    def _join(a, b, cap=None) -> bool:
        """Put a and b in one unit. False if that would exceed `cap`."""
        cap = cap or group_max
        ia, ib = unit_of.get(a), unit_of.get(b)
        if ia is not None and ia == ib:
            return True
        if ia is None and ib is None:
            units.append({a, b})
            unit_of[a] = unit_of[b] = len(units) - 1
            return True
        if ia is None or ib is None:
            base = ib if ia is None else ia
            newcomer = a if ia is None else b
            if len(units[base]) + 1 > cap:
                return False
            units[base].add(newcomer)
            unit_of[newcomer] = base
            return True
        if len(units[ia]) + len(units[ib]) > cap:
            return False
        units[ia] |= units[ib]
        for m in list(units[ib]):
            unit_of[m] = ia
        units[ib] = set()
        return True

    # Implied guest->host requests, inserted at the guest's signup position
    # so priority still runs in signup order.
    for r in roster:
        rk = _pair_key_name(r["customer"])
        if rk in host_of and not (r["partner_request"] or "").strip():
            r["partner_request"] = host_names.get(host_of[rk], "")
            r["_implied_host_request"] = True

    # MANAGER-ADDED requests (Kerry 2026-07-30: "I also need the ability to
    # add a Playing Partner Request in the requests drop down"). A manual
    # match on a player who wrote no request text IS the request — someone
    # asked at the course, or by text. It enters the list at that player's
    # signup position, so it takes its honest place in the priority order
    # rather than jumping the queue for being entered late.
    for r in roster:
        added = manual_matches.get(_pair_key_name(r["customer"]))
        if added and not (r["partner_request"] or "").strip():
            r["partner_request"] = added
            r["_added_by_manager"] = True

    for r in roster:
        req_text = (r["partner_request"] or "").strip()
        if not req_text:
            continue
        # Manager's manual match wins over the automatic text match —
        # but only while the bound player is still on the roster.
        manual_name = manual_matches.get(_pair_key_name(r["customer"]))
        partner = None
        if manual_name:
            partner = next((n for n in all_names
                            if _pair_key_name(n) == _pair_key_name(manual_name)),
                           None)
        is_manual = bool(partner)
        if not partner:
            partner = _find_partner_name(req_text, all_names, r["customer"],
                                         roster_ids=roster_ids)
        # Multi-name texts ("Dan Other or Ed Fifth"): people request
        # more than one, but only ONE partner is honored (rule 1). The
        # auto-match takes the first hit; candidates>1 flags the row so
        # the manager can link the intended one — extras get honored by
        # manual moves after Generate (Kerry 2026-07-21).
        req_l = req_text.lower()
        candidates = [n for n in all_names
                      if n.lower() != (r["customer"] or "").lower()
                      and (n.lower() in req_l or req_l in n.lower())]
        entry = {
            "requester": r["customer"],
            "requester_customer_id": r["customer_id"],
            "holes": r["holes"],
            "order_date": r.get("order_date"),
            "request_text": req_text,
            "partner": partner,
            "matched": bool(partner),
            "manual": is_manual,
            "multi": len(candidates) > 1,
            "candidates": candidates if len(candidates) > 1 else [],
            "suppressed": _pair_key_name(r["customer"]) in suppressed,
            "locked_out": False,
            "locked_reason": None,
            # "active" (first claim) | "confirmed" (already grouped — a
            # reciprocal request or a same-host group) | "approved"
            # (manager overrode the first-come lock) | "outranked".
            "status": "active",
            "implied": bool(r.get("_implied_host_request")),
            "added": bool(r.get("_added_by_manager")),
            "host_group": False,
            "approved": _pair_key_name(r["customer"]) in approvals,
            "requester_is_member": is_member_of.get(
                _pair_key_name(r["customer"]), True),
        }
        # First-come lock simulation (rule 11 + Kerry 2026-07-21):
        # once a player is claimed in EITHER direction, later requests
        # touching them lose. Suppressed requests never claim anyone.
        if entry["matched"] and not entry["suppressed"]:
            rk, pk = _pair_key_name(r["customer"]), _pair_key_name(partner)

            # RECIPROCAL / already together — "Chuck Fehlis -> Gus Vasquez"
            # after "Gus Vasquez -> Chuck Fehlis" is the SAME pairing
            # restated, not a loser (Kerry 2026-07-30). Badge it CONFIRMED;
            # outranking it reads as though the request were being denied.
            if unit_of.get(rk) is not None and unit_of.get(rk) == unit_of.get(pk):
                entry["status"] = "confirmed"
                entry["locked_reason"] = (
                    f"Already paired with {partner} by an earlier request — "
                    f"this confirms it.")
                requests.append(entry)
                continue

            # SAME HOST GROUP — a host and up to three guests they paid for
            # all play together. These are not competing requests.
            grp = _host_group(rk)
            same_host = bool(grp and pk in grp)
            # A guest's request is honored on top of an existing claim;
            # a member's is not (Kerry 2026-07-31 — members branch out).
            guest_ok = not entry["requester_is_member"]
            was_claimed = rk in unit_of or pk in unit_of

            # MANAGER APPROVAL (Kerry 2026-07-31, rule 5 "admin and manager
            # can always override"). An approved request beats the
            # first-come lock by JOINING the partner's group rather than
            # displacing whoever claimed them — nobody has to lose for the
            # override to be honored, up to the foursome ceiling.
            if same_host or entry["approved"] or guest_ok:
                if _join(rk, pk):
                    size = len(_unit(rk) or ())
                    if not was_claimed and not same_host:
                        # Nothing to override — this is an ordinary
                        # first-come win, so it reads like every other one.
                        entry["status"] = "active"
                    elif same_host:
                        entry["host_group"] = True
                        # The FIRST claim on the host isn't confirming
                        # anything — it's the ordinary first-come win, same
                        # as any other opening request, so it gets no badge
                        # (Kerry 2026-07-31: "Not sure why Jacob Williams
                        # has the CONFIRMED badge"). CONFIRMED is for a
                        # request that would otherwise have READ as a loser.
                        entry["status"] = "active" if size == 2 else "confirmed"
                        entry["locked_reason"] = (
                            f"Playing with {partner}, who paid for their spot."
                            if entry["implied"] or host_of.get(rk) == pk else
                            f"Same host group as {partner}.")
                    elif entry["approved"]:
                        entry["status"] = "approved"
                        entry["locked_reason"] = (
                            f"Approved by a manager — grouped with {partner} "
                            f"even though an earlier request claimed them.")
                    else:
                        entry["status"] = "guest"
                        entry["locked_reason"] = (
                            f"Guest request — guests may join a group that is "
                            f"already claimed. {partner} was claimed by an "
                            f"earlier request; members would be outranked "
                            f"here and are expected to branch out.")
                else:
                    entry["locked_out"] = True
                    entry["status"] = "outranked"
                    entry["locked_reason"] = (
                        f"{partner}'s group is already a {group_word} — "
                        f"honoring this would make {group_max + 1}. Suppress "
                        f"a request in that group to make room, or add them "
                        f"by hand after Generate.")
                requests.append(entry)
                continue

            taken = [n for n, key in ((r["customer"], rk), (partner, pk))
                     if key in unit_of]
            if taken:
                entry["locked_out"] = True
                entry["status"] = "outranked"
                entry["locked_reason"] = (
                    " & ".join(taken) + " already locked by an earlier "
                    "request. Members are held to first-come and expected "
                    "to branch out — approve this request to group them "
                    "anyway, or suppress the earlier one.")
            else:
                _join(rk, pk)
        requests.append(entry)
    return {"event_id": event_id, "requests": requests}


def set_partner_request_match(event_id: int, requester_name: str,
                              partner_name: str | None,
                              db_path=None) -> dict:
    """Manually bind a player's partner request to a rostered player
    (Kerry 2026-07-21 — 'Dave Decareaux' vs roster 'David Decareaux').
    partner_name must be on the event roster; None/empty clears the
    manual match. Returns the refreshed request list."""
    requester_name = (requester_name or "").strip()
    if not requester_name:
        raise ValueError("requester_name required")
    partner_name = (partner_name or "").strip()
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        if not partner_name:
            conn.execute(
                "DELETE FROM pairing_request_matches "
                "WHERE event_id = ? AND requester_name = ? COLLATE NOCASE",
                (event_id, requester_name))
        else:
            roster = {_pair_key_name(r["name"]): r
                      for r in _event_roster_players(conn, event_id)}
            partner = roster.get(_pair_key_name(partner_name))
            if not partner:
                raise ValueError(f"'{partner_name}' is not on this "
                                 "event's roster")
            if _pair_key_name(partner["name"]) == _pair_key_name(requester_name):
                raise ValueError("A player can't be matched to themselves")
            requester = roster.get(_pair_key_name(requester_name))
            # Adding a request for someone who isn't playing would create a
            # row the generator can never act on (Kerry 2026-07-30 — the
            # Add-a-request control writes through here).
            if not requester:
                raise ValueError(f"'{requester_name}' is not on this "
                                 "event's roster")
            conn.execute(
                "INSERT OR REPLACE INTO pairing_request_matches "
                "(event_id, requester_name, requester_customer_id, "
                " partner_name, partner_customer_id) VALUES (?, ?, ?, ?, ?)",
                (event_id, requester_name,
                 requester.get("customer_id") if requester else None,
                 partner["name"], partner.get("customer_id")))
        conn.commit()
    return get_event_partner_requests(event_id, db_path=db_path)


def set_partner_request_suppression(event_id: int, requester_name: str,
                                    suppressed: bool, db_path=None) -> dict:
    """Suppress (or restore) one player's partner request for one event.
    Suppression is per REQUESTER row — if two players requested each
    other, each direction is its own toggle."""
    requester_name = (requester_name or "").strip()
    if not requester_name:
        raise ValueError("requester_name required")
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        if suppressed:
            cid_row = conn.execute(
                "SELECT customer_id FROM items WHERE customer = ? "
                "COLLATE NOCASE AND customer_id IS NOT NULL LIMIT 1",
                (requester_name,)).fetchone()
            conn.execute(
                "INSERT OR IGNORE INTO pairing_request_suppressions "
                "(event_id, requester_name, requester_customer_id) "
                "VALUES (?, ?, ?)",
                (event_id, requester_name,
                 cid_row["customer_id"] if cid_row else None))
        else:
            conn.execute(
                "DELETE FROM pairing_request_suppressions "
                "WHERE event_id = ? AND requester_name = ? COLLATE NOCASE",
                (event_id, requester_name))
        conn.commit()
    return get_event_partner_requests(event_id, db_path=db_path)


def set_partner_request_approval(event_id: int, requester_name: str,
                                 approved: bool, approved_by: str | None = None,
                                 db_path=None) -> dict:
    """Approve (or revoke) an OUTRANKED partner request (Kerry 2026-07-31).

    First-come is the default (rule 11); the manager is the override
    (rule 5). An approved request is honored by JOINING the group that
    already claimed the partner rather than displacing anyone — so
    nobody loses a pairing for the override to take effect. A foursome
    is still the hard ceiling: if the partner's group is already four,
    the request stays outranked and says why.

    Approval is stored per REQUESTER for one event, so it survives a
    re-generate and a page reload, and it is reversible.
    """
    requester_name = (requester_name or "").strip()
    if not requester_name:
        raise ValueError("requester_name required")
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        if approved:
            roster = {_pair_key_name(r["name"]): r
                      for r in _event_roster_players(conn, event_id)}
            who = roster.get(_pair_key_name(requester_name))
            if not who:
                raise ValueError(f"'{requester_name}' is not on this "
                                 "event's roster")
            conn.execute(
                "INSERT OR IGNORE INTO pairing_request_approvals "
                "(event_id, requester_name, requester_customer_id, approved_by) "
                "VALUES (?, ?, ?, ?)",
                (event_id, who["name"], who.get("customer_id"), approved_by))
        else:
            conn.execute(
                "DELETE FROM pairing_request_approvals "
                "WHERE event_id = ? AND requester_name = ? COLLATE NOCASE",
                (event_id, requester_name))
        conn.commit()
    return get_event_partner_requests(event_id, db_path=db_path)


def _build_bound_units(players: list[str], partner_map: dict,
                       host_units: list[list[str]],
                       is_privileged, resolve,
                       max_size: int = HOST_GROUP_MAX) -> list[list[str]]:
    """Every honored partner request, as unsplittable units of names.

    This is the GENERATOR's copy of the simulation the requests panel
    runs, and it must walk requests in the SAME signup order with the
    SAME join semantics — otherwise the panel promises pairings the tee
    sheet doesn't deliver. It did exactly that (Kerry 2026-07-31, "Nor is
    it honoring requests"): the generator built privileged units FIRST,
    so an approved "Larry Anthis → Michael Murphy" claimed Larry before
    the earlier "Richard Palacios → Larry Anthis" ever ran, and Palacios
    lost a request the panel showed as active. Walking in signup order
    lets Palacios claim Larry first and the approval JOIN that unit —
    which is what "approve" was defined to mean.

    `partner_map` must already be in signup order (the generator sorts
    the roster by `_request_time_key` before building it).
    `is_privileged(name)` marks a requester whose request beats the
    first-come lock: a guest, or a manager-approved request.
    `resolve(req_text, requester)` returns the rostered partner or None.
    """
    units = [list(dict.fromkeys(u)) for u in (host_units or [])]
    idx: dict = {}
    for i, u in enumerate(units):
        for n in u:
            idx[n] = i

    def _join(a, b) -> bool:
        ia, ib = idx.get(a), idx.get(b)
        if ia is not None and ia == ib:
            return True
        if ia is None and ib is None:
            units.append([a, b])
            idx[a] = idx[b] = len(units) - 1
            return True
        if ia is None or ib is None:
            base = ib if ia is None else ia
            newcomer = a if ia is None else b
            if len(units[base]) >= max_size:
                return False
            units[base].append(newcomer)
            idx[newcomer] = base
            return True
        if len(units[ia]) + len(units[ib]) > max_size:
            return False
        units[ia].extend(units[ib])
        for n in units[ib]:
            idx[n] = ia
        units[ib] = []
        return True

    for requester, req_text in partner_map.items():
        if requester not in players or not (req_text or "").strip():
            continue
        partner = resolve(req_text, requester)
        if not partner or partner not in players:
            continue
        both_free = requester not in idx and partner not in idx
        if both_free or is_privileged(requester):
            _join(requester, partner)
    return [u for u in units if len(u) >= 2]


def _merge_name_units(seed_units: list[list[str]],
                      pairs: list[tuple[str, str]],
                      max_size: int = HOST_GROUP_MAX) -> list[list[str]]:
    """Fold extra bound PAIRS into existing units, up to `max_size`.

    Used by the generator to combine host-and-guests foursomes with
    manager-APPROVED requests: an approved request joins the group that
    already claimed its partner instead of losing to it, which is the
    same thing the requests panel shows. A pair that would push a group
    past `max_size` is dropped here — the panel reports it as still
    outranked, so the two agree.
    """
    unitl = [list(dict.fromkeys(u)) for u in seed_units]
    idx: dict = {}
    for i, u in enumerate(unitl):
        for n in u:
            idx[n] = i
    for a, b in pairs:
        if not a or not b or a == b:
            continue
        ia, ib = idx.get(a), idx.get(b)
        if ia is not None and ia == ib:
            continue
        if ia is None and ib is None:
            unitl.append([a, b])
            idx[a] = idx[b] = len(unitl) - 1
        elif ia is None or ib is None:
            base = ib if ia is None else ia
            newcomer = a if ia is None else b
            if len(unitl[base]) >= max_size:
                continue
            unitl[base].append(newcomer)
            idx[newcomer] = base
        else:
            if len(unitl[ia]) + len(unitl[ib]) > max_size:
                continue
            unitl[ia].extend(unitl[ib])
            for n in unitl[ib]:
                idx[n] = ia
            unitl[ib] = []
    return [u for u in unitl if len(u) >= 2]


def _pair_key_name(name: str) -> str:
    """Normalized form used for pair-count keys: collapsed whitespace,
    lowercase. History rows come from several writers (app saves, GG
    ingest, roster names) — an exact-string key silently drops history
    on any case/spacing drift, which reads as 'generator ignores who
    I've played with'."""
    return " ".join((name or "").split()).lower()


def get_pairing_history_counts(year: int | None = None, db_path=None) -> dict:
    """Return a dict mapping (player_a, player_b) → count for the given calendar year.

    Keys are normalized via _pair_key_name (lowercase, collapsed spaces),
    alphabetical order. If year is None uses the current year.
    """
    if year is None:
        year = datetime.now().year
    year_start = f"{year}-01-01"
    year_end = f"{year}-12-31"

    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        rows = conn.execute(
            """
            SELECT player_a, player_b, COUNT(*) as cnt
            FROM pairing_history
            WHERE event_date BETWEEN ? AND ?
            GROUP BY player_a, player_b
            """,
            (year_start, year_end),
        ).fetchall()

    counts: dict = {}
    for r in rows:
        a, b = _pair_key_name(r["player_a"]), _pair_key_name(r["player_b"])
        key = (min(a, b), max(a, b))
        counts[key] = counts.get(key, 0) + r["cnt"]
    return counts


# ── GG tee-sheet pairings ingest (Kerry 2026-07-14, overnight directive:
#    "run a pairings grab from GG tonight for all 2026 events … stored
#    primarily for Generate Pairings to randomize based off history").
#    Tee sheets are Kerry's ruled PRIMARY source (pairings.md); cart
#    ruling: tee-sheet sequence positions 1&2 and 3&4 rode together.

_GG_PAIRING_PORTALS = {
    "sa": "https://tgf-sa.golfgenius.com",
    "austin": "https://tgf-austin.golfgenius.com",
}
_TEESHEET_PAGE_CACHE: dict = {}
_TEESHEET_WIDGET_CACHE: dict = {}
_EVENT_CODE_RE = re.compile(r"\b([a-z]{1,4}\d+\.\d+)\b", re.I)


def _gg_teesheet_widget(portal: str) -> str:
    """Resolve a portal key ('sa'/'austin') or explicit URL to its tee-sheet
    WIDGET url: portal menu → 'TEE SHEETS' page → iframe widget src."""
    import html as _html
    from golf_genius_sync import fetch_public_page, parse_page_structure
    if portal.startswith("http"):
        page_url = portal
    else:
        base = _GG_PAIRING_PORTALS[portal.lower()]
        page_url = _TEESHEET_PAGE_CACHE.get(portal)
        if not page_url:
            root = fetch_public_page(base, xhr=False)
            struct = parse_page_structure(root["html"], root.get("final_url", base))
            for lk in struct.get("links", []):
                if (lk.get("text") or "").strip().upper() == "TEE SHEETS":
                    page_url = lk["href"]
                    break
            if not page_url:
                raise RuntimeError(f"no TEE SHEETS link on {base}")
            _TEESHEET_PAGE_CACHE[portal] = page_url
    if page_url in _TEESHEET_WIDGET_CACHE:
        return _TEESHEET_WIDGET_CACHE[page_url]
    page = fetch_public_page(page_url, xhr=False)
    m = re.search(r"<iframe[^>]+src=[\"']([^\"']*/widgets/[a-z_0-9]+[^\"']*)[\"']",
                  page["html"], re.I)
    if not m:
        raise RuntimeError(f"no widget iframe on {page_url}")
    widget = _html.unescape(m.group(1))
    if widget.startswith("/"):
        from urllib.parse import urlparse
        pu = urlparse(page["final_url"] if page.get("final_url") else page_url)
        widget = f"{pu.scheme}://{pu.netloc}{widget}"
    _TEESHEET_WIDGET_CACHE[page_url] = widget
    return widget


def gg_pairings_rounds(portal: str) -> dict:
    """List the tee-sheet widget's rounds: [(round_id, label), …]."""
    from golf_genius_sync import fetch_public_page
    widget = _gg_teesheet_widget(portal)
    page = fetch_public_page(widget, xhr=False)
    sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>',
                    page["html"], re.S)
    options = re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                         sel.group(1) if sel else "", re.S)
    return {"widget": widget,
            "rounds": [{"round_id": rid, "label": re.sub(r"\s+", " ", lbl).strip()}
                       for rid, lbl in options]}


# The tee-sheet widget's OWN round selector. `gg_pairings_rounds` above
# looks for `<select name="round">` with plain numeric values — that is
# the tournament_results widget's shape, not this one. The tee-sheet
# widget uses `widget_round_panel_selector` and puts a whole widget URL in
# each option value, with the round id as a query param. It is the only
# listing that includes UPCOMING rounds, which is exactly what the
# per-event pull needs: the sheet exists in GG before the event is played.
_TEESHEET_SELECT_RE = re.compile(
    r"<select[^>]*\bwidget_round_panel_selector\b[^>]*>(.*?)</select>",
    re.S | re.I)
_TEESHEET_OPTION_RE = re.compile(
    r"<optgroup[^>]*label=[\"']([^\"']*)[\"']|"
    r"<option[^>]*value=[\"']([^\"']*)[\"'][^>]*>(.*?)</option>", re.S | re.I)


def gg_teesheet_rounds(portal: str) -> dict:
    """Every round the chapter's tee-sheet widget lists, PLAYED and
    UPCOMING, as [{round_id, label, upcoming}]. Labels are GG's own and
    are truncated by GG at ~50 chars ('… (Sat, Au…') — match on the event
    code / name words, never on the tail of the label."""
    import html as _html
    from golf_genius_sync import fetch_public_page
    widget = _gg_teesheet_widget(portal)
    page = fetch_public_page(widget, xhr=False)
    sel = _TEESHEET_SELECT_RE.search(page["html"] or "")
    rounds: list = []
    group_label = ""
    for m in _TEESHEET_OPTION_RE.finditer(sel.group(1) if sel else ""):
        if m.group(1) is not None:
            group_label = _html.unescape(m.group(1)).strip()
            continue
        value = _html.unescape(m.group(2) or "")
        rid = re.search(r"round_id=(\d+)", value)
        if not rid:
            continue
        label = re.sub(r"<[^>]+>", " ", m.group(3) or "")
        label = re.sub(r"\s+", " ", _html.unescape(label)).strip()
        rounds.append({"round_id": rid.group(1), "label": label,
                       "upcoming": "upcoming" in group_label.lower()})
    return {"widget": widget, "rounds": rounds}


def _score_teesheet_round_label(label: str, item_name: str, course: str,
                                event_date: str | None) -> int:
    """How well a GG round label identifies one Tracker event. Event code
    is decisive when both sides carry one; otherwise this leans on name +
    course words, because our names often carry no code at all ('TGF
    AUSTIN CHAMPIONSHIP' vs GG's 'a18.4 AUSTIN CHAMPIONSHIP | Falconhead')
    and GG truncates the date off the end of long labels."""
    lbl = (label or "").lower()
    ours = _GG_EVENT_CODE_RE.match((item_name or "").strip())
    theirs = _EVENT_CODE_RE.search(lbl)
    if ours and theirs:
        if ours.group(1).lower() == theirs.group(1).lower():
            return 1000
        return -100        # both coded and they disagree — not this event
    stop = {"tgf", "the", "golf", "club", "course", "round", "league"}
    lbl_words = set(re.findall(r"[a-z]{3,}", lbl)) - stop
    ours_words = (set(re.findall(r"[a-z]{3,}", (item_name or "").lower()))
                  | set(re.findall(r"[a-z]{3,}", (course or "").lower()))) - stop
    score = 10 * len(lbl_words & ours_words)
    # A date that survived GG's truncation is worth a lot.
    if event_date:
        md = re.search(
            r"\(?\w{3},?\s+(january|february|march|april|may|june|july|"
            r"august|september|october|november|december)\.?\s+(\d{1,2})", lbl)
        if md:
            months = {m.lower(): i + 1 for i, m in enumerate(
                ["January", "February", "March", "April", "May", "June",
                 "July", "August", "September", "October", "November",
                 "December"])}
            try:
                _y, _m, _d = str(event_date).split("-")
                if (months[md.group(1)] == int(_m)
                        and int(md.group(2)) == int(_d)):
                    score += 40
                else:
                    score -= 40
            except Exception:
                pass
    return score


def gg_teesheet_round_options(event_id: int,
                              db_path: str | Path = DB_PATH) -> dict:
    """Rank this event's chapter tee-sheet rounds by how well each matches
    it, best first, for the PAIRINGS tab's 'pull from GG' button. `best`
    is set only when one round wins clearly, so the manager is asked to
    pick rather than handed a wrong sheet."""
    with _connect(db_path) as conn:
        ev = conn.execute(
            "SELECT id, item_name, course, chapter, event_date FROM events "
            "WHERE id = ?", (int(event_id),)).fetchone()
    if not ev:
        return {"error": f"no event {event_id}"}
    chapter = (ev["chapter"] or "").strip().lower()
    portal = "austin" if chapter.startswith("austin") else "sa"
    listing = gg_teesheet_rounds(portal)
    scored = []
    for r in listing["rounds"]:
        scored.append({**r, "score": _score_teesheet_round_label(
            r["label"], ev["item_name"], ev["course"], ev["event_date"])})
    scored.sort(key=lambda r: (-r["score"], r["label"]))
    best = None
    if scored and scored[0]["score"] >= 20 and (
            len(scored) == 1 or scored[0]["score"] > scored[1]["score"]):
        best = scored[0]["round_id"]
    return {"event": {"id": ev["id"], "name": ev["item_name"],
                      "date": ev["event_date"], "course": ev["course"]},
            "portal": portal, "widget": listing["widget"],
            "best_round_id": best, "rounds": scored}


def import_gg_pairings_for_event(event_id: int, round_id: str | None = None,
                                 holes: str | None = None,
                                 apply: bool = True,
                                 db_path: str | Path = DB_PATH) -> dict:
    """Pull ONE event's pairings straight off Golf Genius (Kerry
    2026-07-31: "TGF AUSTIN CHAMPIONSHIP already has pairings on GG,
    because Robert didn't use our generator").

    Same machinery as the nightly history grab, aimed at a single event
    and usable BEFORE the event is played — the tee-sheet widget's round
    selector lists upcoming rounds too. `round_id` omitted means auto-match
    on the event's name/code/course/date. Replaces this event's pairings
    for the chosen leg; reports which GG names did not land on a
    registered player and which registered players the sheet omits, so
    the manager can see what to fix before printing."""
    opts = gg_teesheet_round_options(event_id, db_path=db_path)
    if opts.get("error"):
        return opts
    rid = str(round_id or "").strip() or opts.get("best_round_id")
    if not rid:
        return {**opts, "error": "could not tell which GG round is this "
                                 "event — pick one"}
    label = next((r["label"] for r in opts["rounds"]
                  if r["round_id"] == str(rid)), "")
    res = import_gg_teesheet_round(opts["portal"], str(rid), apply=apply,
                                   label=label, event_override=str(event_id),
                                   holes=holes, db_path=db_path)
    res["portal"] = opts["portal"]
    res["matched_label"] = label
    res["auto_matched"] = not round_id
    # Roster reconciliation — the manager's real question is "did everyone
    # land?", and that is a customer_id question, not a name question.
    try:
        _INACTIVE = ("credited", "refunded", "transferred", "wd")
        _ph = ",".join("?" * len(_INACTIVE))
        with _connect(db_path) as conn:
            reg = conn.execute(
                f"""SELECT DISTINCT i.customer, i.customer_id
                    FROM events e
                    LEFT JOIN event_aliases ea
                           ON ea.canonical_event_name = e.item_name
                    JOIN items i ON (
                        i.item_name = e.item_name COLLATE NOCASE
                        OR i.item_name = ea.alias_name COLLATE NOCASE
                        OR i.event_id = e.id)
                    WHERE e.id = ?
                      AND COALESCE(i.transaction_status,'active') NOT IN ({_ph})
                      AND i.parent_item_id IS NULL""",
                (int(event_id), *_INACTIVE)).fetchall()
            placed = {(r["player_name"] or "").strip().lower()
                      for r in conn.execute(
                          "SELECT player_name FROM event_pairings "
                          "WHERE event_id = ?", (int(event_id),)).fetchall()}
            missing = []
            for r in reg:
                canon = (r["customer"] or "").strip()
                if r["customer_id"]:
                    c = conn.execute(
                        """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                                  COALESCE(last_name,'')) AS nm
                           FROM customers WHERE customer_id = ?""",
                        (r["customer_id"],)).fetchone()
                    canon = ((c["nm"] or "").strip() if c else "") or canon
                if canon and canon.lower() not in placed:
                    missing.append(canon)
            res["registered_not_on_sheet"] = sorted(set(missing))
    except Exception as e:
        res["roster_check_error"] = str(e)
    return res


def _split_teesheet_names(cell: str) -> list:
    """Split a tee-sheet players cell ('MELCHOR, Eduardo MOORE, Dion
    STRAITON, Robert') into ordered names: break before each token that
    starts the next 'Surname,' unit."""
    parts = re.split(r"\s+(?=\S+,)", (cell or "").strip())
    return [p.strip() for p in parts if "," in p and len(p.strip()) > 4]


_TT_TABLE_RE = re.compile(
    r"<table[^>]*by_tee_times_table[^>]*>(.*?)</table>", re.S | re.I)
_TT_ROW_RE = re.compile(r"<tr\b([^>]*)>(.*?)</tr>", re.S | re.I)
_TT_CELL_RE = re.compile(r"<t[dh]\b[^>]*>(.*?)</t[dh]>", re.S | re.I)
# A portrait div's player name is the text before its first nested tag
# (the tee abbreviation span / division-and-flight div).
_TT_PORTRAIT_RE = re.compile(
    r"<div[^>]*\bplayers_portrait\b[^>]*>(.*?)(?:<span|<div|</div>)",
    re.S | re.I)
_TT_TIME_RE = re.compile(r"^\d{1,2}:\d{2}\s*(AM|PM)?$", re.I)


def _tt_text(fragment: str) -> str:
    import html as _html
    return re.sub(r"\s+", " ",
                  _html.unescape(re.sub(r"<[^>]+>", " ", fragment or ""))).strip()


def _parse_teesheet_groups_html(html_text: str) -> list:
    """Structural parse of the 'By Tee Times' table — one entry per
    `players_portrait` div, in GG's seat order.

    This is the primary path because the flattened-text parse below has
    to guess where one name ends and the next begins, and gets it wrong
    for any player GG does NOT print as 'SURNAME, First' (guests and
    1st timers often show as plain 'Matt Larson'). Dropping one name
    silently shifts every later seat, which corrupts the cart pairs.
    Rows marked `visible-xs` are GG's single-column mobile duplicates.
    """
    groups: list = []
    for tbl in _TT_TABLE_RE.findall(html_text or ""):
        for attrs, body in _TT_ROW_RE.findall(tbl):
            if "visible-xs" in attrs:
                continue
            cells = _TT_CELL_RE.findall(body)
            plain = [_tt_text(c) for c in cells]
            i = 0
            while i < len(cells):
                if not _TT_TIME_RE.match(plain[i]):
                    i += 1
                    continue
                j, hole, names = i + 1, None, None
                while j < len(cells) and j <= i + 2:
                    if "players_portrait" in cells[j]:
                        names = [n for n in
                                 (_tt_text(p) for p in
                                  _TT_PORTRAIT_RE.findall(cells[j])) if n]
                        break
                    if re.match(r"^\d{1,2}[AB]?$", plain[j], re.I):
                        hole = plain[j]
                        j += 1
                        continue
                    break
                if names:
                    groups.append({"slot": plain[i], "hole": hole,
                                   "players": names})
                    i = j + 1
                else:
                    i += 1
    # Shotgun sheets repeat one time across every group — the hole is the
    # slot that means anything there.
    if groups and len({g["slot"] for g in groups}) == 1:
        for g in groups:
            if g.get("hole"):
                g["slot"] = f"Hole {g['hole']}"
    return [{"slot": g["slot"], "players": g["players"]} for g in groups]


def _parse_teesheet_groups(html_text: str) -> dict:
    """Parse a GG next_round tee-sheet widget into ordered player groups.

    The 'By Tee Times' table lays groups out as (time, [hole,] players)
    triplets — sometimes two groups per row, and each group repeated in a
    single-column variant, so groups dedupe by (time, players). The
    alphabetical 'By Individual' table is skipped structurally (its
    names sit outside the time-cell window). Returns a debug dump of the
    raw tables so unexpected layouts can be diagnosed over the bridge."""
    from golf_genius_sync import parse_page_structure
    struct = parse_page_structure(html_text, "")
    tables = struct.get("tables", [])
    _time_re = re.compile(r"^\d{1,2}:\d{2}\s*(AM|PM)?$", re.I)

    structural = _parse_teesheet_groups_html(html_text)
    if structural:
        return {"groups": structural, "n_tables": len(tables),
                "parser": "html", "debug_tables": []}

    groups: list = []
    seen: set = set()
    for t in tables:
        rows = t if isinstance(t, list) else (t.get("rows") or [])
        for row in rows:
            cells = [re.sub(r"\s+", " ", (c or "")).strip() for c in row]
            i = 0
            while i < len(cells):
                if not _time_re.match(cells[i]):
                    i += 1
                    continue
                # Names live right after the time (optionally one pure-digit
                # hole cell between). Cells with ' + ' are the alphabetical
                # By-Individual table's 'Other Players' column — never a
                # group (18-hole layouts put it inside this window).
                names: list = []
                j = i + 1
                while j < len(cells) and j <= i + 2:
                    c = cells[j]
                    if " + " in c:
                        break
                    nm = _split_teesheet_names(c)
                    if len(nm) >= 2:
                        names = nm
                        break
                    # hole cells: '1', '10', shotgun '1A'/'1B' — anything
                    # else (tee labels like '2 - White') ends the window
                    if not re.match(r"^\d{1,2}[AB]?$", c, re.I):
                        break
                    j += 1
                if names:
                    key = (cells[i], tuple(names))
                    if key not in seen:
                        seen.add(key)
                        groups.append({"slot": cells[i], "players": names})
                i = j + 1
    debug = []
    for t in tables[:6]:
        rows = t if isinstance(t, list) else (t.get("rows") or [])
        debug.append({"n_rows": len(rows), "first_rows": rows[:6]})
    return {"groups": groups, "n_tables": len(tables), "debug_tables": debug}


def _match_event_for_round_label(conn, label: str, portal: str):
    """Tracker events row for a tee-sheet round label — event code first
    (s9.17 / a9.18 / s18.8 …), else the label's date + portal chapter."""
    m = _EVENT_CODE_RE.search(label)
    if m:
        rows = conn.execute(
            "SELECT id, item_name, event_date FROM events "
            "WHERE item_name LIKE ? COLLATE NOCASE "
            "ORDER BY event_date DESC",
            (m.group(1) + " %",)).fetchall()
        if len(rows) == 1:
            return rows[0]
        if rows:
            # Duplicate-code events exist (e.g. 'a18.2 CRYSTAL FALLS' vs
            # 'a18.2 AUSTIN KICKOFF | ShadowGlen') — disambiguate by word
            # overlap between the round label and each item_name.
            lbl_words = set(re.findall(r"[a-z]{3,}", label.lower()))
            def _overlap(r):
                nm_words = set(re.findall(r"[a-z]{3,}", r["item_name"].lower()))
                return len(lbl_words & nm_words)
            return max(rows, key=_overlap)
    md = re.search(
        r"\(?\w{3},?\s+(January|February|March|April|May|June|July|August|"
        r"September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|"
        r"Sep|Oct|Nov|Dec)\.?\s+(\d{1,2})", label)
    if md:
        months = {m[:3].lower(): i + 1 for i, m in enumerate(
            ["January", "February", "March", "April", "May", "June", "July",
             "August", "September", "October", "November", "December"])}
        iso = f"2026-{months[md.group(1)[:3].lower()]:02d}-{int(md.group(2)):02d}"
        chapter = {"sa": "San Antonio", "austin": "Austin"}.get(portal.lower())
        q = ("SELECT id, item_name, event_date FROM events WHERE event_date = ?"
             + (" AND chapter = ?" if chapter else ""))
        rows = conn.execute(q, (iso, chapter) if chapter else (iso,)).fetchall()
        if len(rows) == 1:
            return rows[0]
    return None


def import_gg_teesheet_round(portal: str, round_id: str, apply: bool = False,
                             label: str | None = None,
                             event_override: str | None = None,
                             holes: str | None = None,
                             db_path: str | Path = DB_PATH) -> dict:
    """Parse one FINAL tee-sheet round (Kerry's route: SCHEDULE calendar →
    per-round Tee Sheet page; the next_round widget serves the historical
    sheet when given round_id=). apply=True writes pairing_history for
    the matched event (REPLACES that event's rows — the tee sheet is the
    ruled source of truth). Players resolve through the scoring cascade;
    rode pairs = tee-sheet sequence 1&2 / 3&4 (Kerry ruling)."""
    from golf_genius_sync import fetch_public_page
    widget = _gg_teesheet_widget(portal)
    joiner = "&" if "?" in widget else "?"
    page = fetch_public_page(f"{widget}{joiner}round_id={round_id}", xhr=False)
    parsed = _parse_teesheet_groups(page["html"])
    label = label or ""
    out = {"portal": portal, "round_id": round_id, "label": label,
           "n_groups": len(parsed["groups"]), "groups": parsed["groups"],
           "n_tables": parsed["n_tables"], "applied": False}
    if not parsed["groups"]:
        out["debug_tables"] = parsed["debug_tables"]
        return out
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        ev = None
        if event_override:
            if str(event_override).isdigit():
                ev = conn.execute(
                    "SELECT id, item_name, event_date FROM events WHERE id = ?",
                    (int(event_override),)).fetchone()
            else:
                ev = conn.execute(
                    "SELECT id, item_name, event_date FROM events "
                    "WHERE item_name LIKE ? COLLATE NOCASE "
                    "ORDER BY event_date DESC LIMIT 1",
                    (f"%{event_override}%",)).fetchone()
        if not ev:
            ev = _match_event_for_round_label(conn, label, portal)
        if not ev:
            out["error"] = f"no Tracker event matched label {label!r}"
            out["debug_tables"] = parsed["debug_tables"][:2]
            return out
        out["event"] = {"id": ev["id"], "name": ev["item_name"],
                        "date": ev["event_date"]}
        resolved_groups = []
        unresolved = []
        for g in parsed["groups"]:
            names = []
            for raw in g["players"]:
                cid = None
                try:
                    cid = _resolve_scoring_player(conn, raw)
                except Exception:
                    cid = None
                canonical = None
                if cid:
                    c = conn.execute(
                        """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                                   COALESCE(last_name,'')) AS nm
                           FROM customers WHERE customer_id = ?""",
                        (cid,)).fetchone()
                    canonical = (c["nm"] or "").strip() or None
                if not canonical:
                    canonical = _normalize_player_name(raw)
                    unresolved.append(raw)
                names.append({"name": canonical, "cid": cid})
            resolved_groups.append({"slot": g["slot"], "players": names})
        out["unresolved_names"] = unresolved
        if apply:
            conn.execute("DELETE FROM pairing_history WHERE event_id = ?",
                         (ev["id"],))
            n_pairs = 0
            for g in resolved_groups:
                ps = g["players"]
                rode_pairs = set()
                for lo, hi in ((0, 1), (2, 3)):
                    if hi < len(ps):
                        rode_pairs.add(frozenset((ps[lo]["name"], ps[hi]["name"])))
                for i in range(len(ps)):
                    for j in range(i + 1, len(ps)):
                        a, b = sorted((ps[i], ps[j]), key=lambda p: p["name"])
                        conn.execute(
                            """INSERT OR IGNORE INTO pairing_history
                               (player_a, player_b, event_id, event_date,
                                customer_a_id, customer_b_id, rode, source)
                               VALUES (?, ?, ?, ?, ?, ?, ?, 'gg_teesheet')""",
                            (a["name"], b["name"], ev["id"], ev["event_date"],
                             a["cid"], b["cid"],
                             1 if frozenset((a["name"], b["name"])) in rode_pairs else 0))
                        n_pairs += 1
            out["event_pairings_rows"] = _write_event_pairings_from_groups(
                conn, ev["id"], resolved_groups, holes=holes)
            conn.commit()
            out["applied"] = True
            out["pairs_written"] = n_pairs
        out.pop("groups", None)
        out["group_sizes"] = [len(g["players"]) for g in resolved_groups]
    return out


def import_gg_teesheets_all(portal: str, apply: bool = False,
                            budget_seconds: int = 200,
                            db_path: str | Path = DB_PATH) -> dict:
    """Walk every played round through the FINAL tee-sheet importer.
    Round ids + labels come from the tournament_results widget's selector
    (the tee-sheet widget itself has none); time-budgeted, and apply
    replaces per event so repeats are safe."""
    import time as _time
    t0 = _time.time()
    listing = gg_teamnet_rounds(portal)
    results = []
    done = skipped = 0
    for r in listing["rounds"]:
        if _time.time() - t0 > budget_seconds:
            break
        try:
            res = import_gg_teesheet_round(portal, r["round_id"], apply=apply,
                                           label=r["label"], db_path=db_path)
        except Exception as e:
            res = {"round_id": r["round_id"], "label": r["label"], "error": str(e)}
        slim = {k: res.get(k) for k in
                ("round_id", "label", "n_groups", "event", "applied",
                 "pairs_written", "error", "unresolved_names")
                if res.get(k) is not None}
        results.append(slim)
        if res.get("applied") or (not apply and res.get("n_groups")):
            done += 1
        else:
            skipped += 1
    return {"portal": portal, "widget": listing["widget"],
            "rounds_total": len(listing["rounds"]),
            "rounds_processed": len(results), "ok": done, "skipped": skipped,
            "rounds_left": len(listing["rounds"]) - len(results),
            "results": results}


# ── GG TEAM/CART Net board pairings ingest (same overnight directive).
#    The public TEE SHEETS page turned out to be a next_round widget
#    (upcoming event only, no archive) and the tee-sheet history page is
#    login-gated — but every PLAYED round's tournament_results widget
#    lists a "TEAM Net $" (SA: foursomes) or "CART Net $" (Austin: cart
#    pairs) board whose rows are the actual playing groups in seat order.
#    Blind-draw fills render as Bl[Name] — on the card but not physically
#    in the group, so they become empty seats (kept for cart alignment,
#    excluded from pairs).

_GG_LEAGUE_IDS = {"sa": "514047", "austin": "514705"}
_TEAM_BOARD_RE = re.compile(r"\b(?:TEAM|CART)\s+Net\b", re.I)
_BLIND_SEAT_RE = re.compile(r"^[A-Za-z]{1,3}\[(.+)\]$")
# Trailing affiliation list after the LAST member: one entry per player,
# e.g. " TGF San Antonio, Former, TGF Houston, TGF Austin" or
# " TGF San Antonio, Guest" (sometimes with a dangling comma). A lone
# guest's tail can START with Guest/Former — no TGF token at all.
_TEAM_TAIL_RE = re.compile(
    r"\s+(?:TGF\s[A-Za-z .]+?|Guest|Former)"
    r"(?:\s*,\s*(?:TGF\s[A-Za-z .]+?|Guest|Former))*\s*,?\s*$")


def _gg_results_widget(portal: str) -> str:
    """The portal's tournament_results widget (has the full round selector,
    unlike the TEE SHEETS page's next_round widget)."""
    key = portal.lower()
    base = _GG_PAIRING_PORTALS[key]
    return (f"{base}/leagues/{_GG_LEAGUE_IDS[key]}"
            "/widgets/tournament_results?shared=false")


def gg_teamnet_rounds(portal: str) -> dict:
    """Rounds listed by the tournament_results widget's selector."""
    from golf_genius_sync import fetch_public_page
    widget = _gg_results_widget(portal)
    page = fetch_public_page(widget, xhr=False)
    sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>',
                    page["html"], re.S)
    options = re.findall(r'<option[^>]*value="(\d+)"[^>]*>(.*?)</option>',
                         sel.group(1) if sel else "", re.S)
    return {"widget": widget,
            "rounds": [{"round_id": rid, "label": re.sub(r"\s+", " ", lbl).strip()}
                       for rid, lbl in options]}


def _parse_teamnet_groups(tables: list) -> list:
    """Foursome/cart cells like 'SOUTH, Daniel + MORENO, Robert + WADE,
    Mary + Bl[HAMILTON, Doug] TGF San Antonio' → seat lists in board
    order. Blind fills (Xx[Name]) become None seats so the 1&2 / 3&4
    cart split stays aligned with the board's sequence."""
    groups = []
    for t in tables:
        rows = t if isinstance(t, list) else (t.get("rows") or [])
        for row in rows:
            for cell in row:
                c = re.sub(r"\s+", " ", (cell or "")).strip()
                if " + " not in c or c.lower().startswith("total purse"):
                    continue
                c = _TEAM_TAIL_RE.sub("", c).strip()
                seats: list = []
                ok = True
                for part in (p.strip() for p in c.split(" + ")):
                    bm = _BLIND_SEAT_RE.match(part)
                    if bm:
                        seats.append(None)
                    elif "," in part and 4 < len(part) < 60:
                        seats.append(part)
                    else:
                        ok = False
                        break
                if ok and any(seats):
                    groups.append(seats)
                break  # one group cell per row
    return groups


def import_gg_teamnet_round(portal: str, round_id: str, apply: bool = False,
                            label: str | None = None,
                            event_override: str | None = None,
                            db_path: str | Path = DB_PATH) -> dict:
    """Parse one round's TEAM/CART Net board into playing groups;
    apply=True REPLACES the matched event's pairing_history rows
    (source 'gg_teamnet'). Rode pairs come from board seat order
    (1&2 / 3&4 — Kerry's cart-sequence ruling; for Austin's 2-seat
    CART rows the pair rode by definition)."""
    from golf_genius_sync import fetch_public_page, parse_page_structure
    widget = _gg_results_widget(portal)
    joiner = "&" if "?" in widget else "?"
    page = fetch_public_page(f"{widget}{joiner}round={round_id}", xhr=False)
    if not label:
        sel = re.search(r'<select[^>]*name="round"[^>]*>(.*?)</select>',
                        page["html"], re.S)
        if sel:
            cur = re.search(r'<option[^>]*value="' + re.escape(str(round_id)) +
                            r'"[^>]*>(.*?)</option>', sel.group(1), re.S)
            if cur:
                label = re.sub(r"\s+", " ", cur.group(1)).strip()
    label = label or ""
    struct = parse_page_structure(page["html"], page.get("final_url") or widget)
    board = None
    for lk in struct.get("links", []):
        if (_TEAM_BOARD_RE.search(lk.get("text") or "")
                and "/v2tournaments/" in (lk.get("href") or "")):
            board = lk
            break
    out = {"portal": portal, "round_id": round_id, "label": label,
           "applied": False}
    if not board:
        out["error"] = "no TEAM/CART Net board on this round"
        return out
    out["board"] = (board.get("text") or "").strip()
    bpage = fetch_public_page(board["href"], xhr=False)
    btables = parse_page_structure(bpage["html"], board["href"]).get("tables", [])
    seat_groups = _parse_teamnet_groups(btables)
    out["n_groups"] = len(seat_groups)
    out["group_sizes"] = [sum(1 for s in g if s) for g in seat_groups]
    out["blind_seats"] = sum(1 for g in seat_groups for s in g if s is None)
    if not seat_groups:
        out["error"] = "board parsed 0 groups"
        out["debug_tables"] = btables[:2]
        return out
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        # Manual override for rounds whose selector label is truncated
        # past recognition (GG cuts option text mid-date on the coded-less
        # preseason rounds): accept an events.id or an item_name fragment.
        ev = None
        if event_override:
            if str(event_override).isdigit():
                ev = conn.execute(
                    "SELECT id, item_name, event_date FROM events WHERE id = ?",
                    (int(event_override),)).fetchone()
            else:
                ev = conn.execute(
                    "SELECT id, item_name, event_date FROM events "
                    "WHERE item_name LIKE ? COLLATE NOCASE "
                    "ORDER BY event_date DESC LIMIT 1",
                    (f"%{event_override}%",)).fetchone()
        if not ev:
            ev = _match_event_for_round_label(conn, label, portal)
        if not ev:
            out["error"] = f"no Tracker event matched label {label!r}"
            return out
        out["event"] = {"id": ev["id"], "name": ev["item_name"],
                        "date": ev["event_date"]}
        resolved = []
        unresolved = []
        for seats in seat_groups:
            rs = []
            for raw in seats:
                if raw is None:
                    rs.append(None)
                    continue
                cid = None
                try:
                    cid = _resolve_scoring_player(conn, raw)
                except Exception:
                    cid = None
                canonical = None
                if cid:
                    c = conn.execute(
                        """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                                   COALESCE(last_name,'')) AS nm
                           FROM customers WHERE customer_id = ?""",
                        (cid,)).fetchone()
                    canonical = (c["nm"] or "").strip() or None
                if not canonical:
                    canonical = _normalize_player_name(raw)
                    unresolved.append(raw)
                rs.append({"name": canonical, "cid": cid})
            resolved.append(rs)
        out["unresolved_names"] = unresolved
        if apply:
            conn.execute("DELETE FROM pairing_history WHERE event_id = ?",
                         (ev["id"],))
            n_pairs = 0
            for rs in resolved:
                real = [(idx, p) for idx, p in enumerate(rs) if p]
                for x in range(len(real)):
                    for y in range(x + 1, len(real)):
                        (ia, pa), (ib, pb) = real[x], real[y]
                        a, b = sorted((pa, pb), key=lambda p: p["name"])
                        conn.execute(
                            """INSERT OR IGNORE INTO pairing_history
                               (player_a, player_b, event_id, event_date,
                                customer_a_id, customer_b_id, rode, source)
                               VALUES (?, ?, ?, ?, ?, ?, ?, 'gg_teamnet')""",
                            (a["name"], b["name"], ev["id"], ev["event_date"],
                             a["cid"], b["cid"],
                             1 if ia // 2 == ib // 2 else 0))
                        n_pairs += 1
            out["event_pairings_rows"] = _write_event_pairings_from_groups(
                conn, ev["id"],
                [{"slot": None, "players": rs} for rs in resolved])
            conn.commit()
            out["applied"] = True
            out["pairs_written"] = n_pairs
    return out


def debug_pairing_history(query: str, db_path: str | Path = DB_PATH) -> dict:
    """Read-only inspection for the pairings pipeline: rows by event id
    (numeric query) or by player-name fragment, plus 2026 totals by
    source — so 'the generator ignored my history' is diagnosable over
    the bridge without a redeploy."""
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        out: dict = {"query": query}
        srcs = conn.execute(
            "SELECT COALESCE(source,'app') AS s, COUNT(*) AS n "
            "FROM pairing_history WHERE event_date >= '2026-01-01' "
            "GROUP BY COALESCE(source,'app')").fetchall()
        out["rows_2026_by_source"] = {r["s"]: r["n"] for r in srcs}
        if str(query).strip().isdigit():
            rows = conn.execute(
                "SELECT * FROM pairing_history WHERE event_id = ? ORDER BY id",
                (int(query),)).fetchall()
        else:
            frag = f"%{query.strip()}%"
            rows = conn.execute(
                "SELECT * FROM pairing_history "
                "WHERE (player_a LIKE ? OR player_b LIKE ?) "
                "AND event_date >= '2026-01-01' ORDER BY event_date, id",
                (frag, frag)).fetchall()
        out["n_rows"] = len(rows)
        out["rows"] = [
            {k: r[k] for k in ("player_a", "player_b", "event_id",
                               "event_date", "rode", "source",
                               "customer_a_id", "customer_b_id")}
            for r in rows[:80]]
        return out


def debug_generate_pairings(event_id: int,
                            db_path: str | Path = DB_PATH) -> dict:
    """Run the pairing generator server-side with NO seeds and report the
    repeat-score arithmetic it saw — isolates 'the generator ignores
    history' from 'the UI passed locked seeds'."""
    counts = get_pairing_history_counts(db_path=db_path)
    res = generate_event_pairings(int(event_id), db_path=db_path)
    out: dict = {"event_id": int(event_id), "n_pair_keys": len(counts)}
    for holes in ("9", "18"):
        if holes not in res:
            continue
        groups = []
        for g in res[holes]:
            names = [p["name"] for p in g.get("players", []) if p.get("name")]
            pairs = {f"{a} + {b}": _pair_count(counts, a, b)
                     for i, a in enumerate(names) for b in names[i + 1:]}
            groups.append({"slot": g.get("slot_label"), "players": names,
                           "repeat_pairs": {k: v for k, v in pairs.items()
                                            if v > 0},
                           "group_score": sum(pairs.values())})
        out[f"groups_{holes}"] = groups
        out[f"total_score_{holes}"] = sum(g["group_score"] for g in groups)
        roster = [n for g in out[f"groups_{holes}"] for n in g["players"]]
        out[f"roster_pairs_{holes}"] = {
            f"{a} + {b}": c for i, a in enumerate(roster)
            for b in roster[i + 1:]
            if (c := _pair_count(counts, a, b)) > 0}
    return out


def analyze_pairing_staging(db_path: str | Path = DB_PATH) -> dict:
    """Read-only side-quest data (Kerry 2026-07-14): every 9-hole event's
    ACTUAL groups in staging order (group_num follows the final tee
    sheet's sequence — tee-time order, or hole order on shotguns) with
    pace proxies per group: size, average CURRENT handicap index
    (as-of-event index not reconstructed — proxy only), and age-band
    mix from registrations (<50 / 50-64 / 65+)."""
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        hcp_rows = conn.execute(
            """
            SELECT l.customer_name, p.handicap_index
            FROM (
                SELECT player_name, AVG(differential) as handicap_index
                FROM (
                    SELECT player_name, differential,
                           ROW_NUMBER() OVER (
                               PARTITION BY player_name
                               ORDER BY round_date DESC, id DESC) as rn
                    FROM handicap_rounds
                    WHERE differential IS NOT NULL
                      AND round_date >= date('now', '-12 months')
                )
                WHERE rn <= 20
                GROUP BY player_name
            ) p
            JOIN handicap_player_links l ON l.player_name = p.player_name
            WHERE l.customer_name IS NOT NULL
            """).fetchall()
        hcp = {(r["customer_name"] or "").lower(): r["handicap_index"]
               for r in hcp_rows}
        evs = conn.execute(
            """SELECT DISTINCT e.id, e.item_name, e.event_date, e.chapter
               FROM events e JOIN event_pairings ep ON ep.event_id = e.id
               WHERE e.item_name LIKE 's9.%' OR e.item_name LIKE 'a9.%'
               ORDER BY e.event_date""").fetchall()
        out = []
        for ev in evs:
            rows = conn.execute(
                """SELECT group_num, slot_label, player_name
                   FROM event_pairings WHERE event_id = ?
                   ORDER BY group_num, cart_pos""", (ev["id"],)).fetchall()
            band_map = {r["customer"]: r["tee_choice"] for r in conn.execute(
                """SELECT DISTINCT customer, tee_choice FROM items
                   WHERE event_id = ? AND tee_choice IS NOT NULL
                   AND parent_item_id IS NULL""", (ev["id"],))}
            groups: dict = {}
            for r in rows:
                groups.setdefault(r["group_num"],
                                  {"slot": r["slot_label"], "players": []})[
                    "players"].append(r["player_name"])
            glist = []
            for gn in sorted(groups):
                g = groups[gn]
                idxs = [hcp.get((p or "").lower()) for p in g["players"]]
                idxs = [x for x in idxs if x is not None]
                bands = [band_map.get(p) for p in g["players"]]
                glist.append({
                    "n": gn, "slot": g["slot"], "size": len(g["players"]),
                    "avg_index": round(sum(idxs) / len(idxs), 1) if idxs else None,
                    "bands": [b for b in bands if b]})
            out.append({"event": ev["item_name"], "date": ev["event_date"],
                        "chapter": ev["chapter"], "groups": glist})
        return {"n_events": len(out), "events": out,
                "note": "avg_index uses CURRENT index (proxy); bands from "
                        "registrations; group order = final tee sheet order"}


def list_pace_ratings(db_path: str | Path = DB_PATH) -> dict:
    """Read-only: every customer with a stored pace_rating (1 slowest →
    3 fastest, Kerry-ratified scale). Players with no row here read as
    the default 2 system-wide. Bridge: scoring-pairings:pace|"""
    conn = get_connection(db_path)
    try:
        rows = conn.execute(
            """SELECT customer_id,
                      TRIM(first_name || ' ' || last_name) AS name,
                      chapter, pace_rating, pace_rating_source
               FROM customers
               WHERE pace_rating IS NOT NULL
               ORDER BY pace_rating DESC, last_name, first_name"""
        ).fetchall()
    except sqlite3.OperationalError as e:
        return {"error": f"pace_rating column missing: {e}"}
    finally:
        conn.close()
    out = [dict(r) for r in rows]
    return {
        "scale": "1=slowest, 3=fastest; unlisted players default to 2",
        "n_rated": len(out),
        "ratings": out,
    }


def set_customer_pace_rating(customer_id: int, rating: int,
                             db_path: str | Path = DB_PATH) -> dict:
    """Manager one-tap pace edit (task #23). Writes an EXPLICIT 1/2/3
    with source='manager' — never NULL: the boot seed is
    fill-only-if-NULL, so a cleared seeded player would get the seed
    value back on the next deploy. An explicit 2 is a real ruling
    ("this player is average pace"), same as Kerry's seed corrections.
    """
    if rating not in (1, 2, 3):
        raise ValueError("rating must be 1, 2, or 3")
    with _connect(db_path) as conn:
        cur = conn.execute(
            """UPDATE customers
               SET pace_rating = ?, pace_rating_source = 'manager'
               WHERE customer_id = ?""",
            (rating, int(customer_id)))
        if cur.rowcount == 0:
            raise ValueError(f"customer {customer_id} not found")
        conn.commit()
    return {"customer_id": int(customer_id), "pace_rating": rating,
            "pace_rating_source": "manager"}


def analyze_player_staging(db_path: str | Path = DB_PATH) -> dict:
    """Per-player staging positions across 9-hole events (Kerry's
    pace-ranking side quest). For each event's MAIN wave, each player's
    normalized position 0..1 by tee-sheet group order. Buckets:
      sa_shotgun    — SA main waves (hole-train: LATER position = front
                      of train = staged as FASTER)
      aus_shotgun   — Austin shotgun events (ShadowGlen pattern: all
                      main-wave slots share one time) — Robert's read
      aus_times     — Austin sequential tee times (availability-
                      constrained; EARLIER = staged as faster, weak)
    Pre-4PM tee times are the early-play option, counted separately
    (preference, not pace)."""
    tre = re.compile(r"(\d{1,2}):(\d{2})\s*(AM|PM)", re.I)

    def slot_minutes(s):
        m = tre.search(s or "")
        if not m:
            return None
        h, mi = int(m.group(1)) % 12, int(m.group(2))
        if m.group(3).upper() == "PM":
            h += 12
        return h * 60 + mi

    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        evs = conn.execute(
            """SELECT DISTINCT e.id, e.item_name, e.chapter
               FROM events e JOIN event_pairings ep ON ep.event_id = e.id
               WHERE e.item_name LIKE 's9.%' OR e.item_name LIKE 'a9.%'
               ORDER BY e.event_date""").fetchall()
        players: dict = {}
        n_events = {"sa_shotgun": 0, "aus_shotgun": 0, "aus_times": 0}
        for ev in evs:
            rows = conn.execute(
                """SELECT group_num, slot_label, player_name
                   FROM event_pairings WHERE event_id = ?
                   ORDER BY group_num, cart_pos""", (ev["id"],)).fetchall()
            groups: dict = {}
            for r in rows:
                groups.setdefault(r["group_num"],
                                  {"slot": r["slot_label"],
                                   "players": []})["players"].append(
                    r["player_name"])
            main, early = [], []
            for gn in sorted(groups):
                g = groups[gn]
                t = slot_minutes(g["slot"])
                (early if (t is not None and t < 16 * 60) else main).append(g)
            if len(main) < 2:
                continue
            times = [slot_minutes(g["slot"]) for g in main]
            is_shotgun = (None in times) or len(set(times)) == 1
            if (ev["chapter"] or "") == "San Antonio":
                bucket = "sa_shotgun"  # SA main waves are the shotgun train
            else:
                bucket = "aus_shotgun" if is_shotgun else "aus_times"
            n_events[bucket] += 1
            for i, g in enumerate(main):
                pos = round(i / (len(main) - 1), 2)
                for p in g["players"]:
                    players.setdefault(p, {"sa_shotgun": [], "aus_shotgun": [],
                                           "aus_times": [], "early_waves": 0})[
                        bucket].append(pos)
            for g in early:
                for p in g["players"]:
                    players.setdefault(p, {"sa_shotgun": [], "aus_shotgun": [],
                                           "aus_times": [],
                                           "early_waves": 0})["early_waves"] += 1
        return {"n_events": n_events, "players": players,
                "note": "positions 0=first group on sheet, 1=last; "
                        "sa/aus_shotgun: later = front of hole train"}


def clear_gg_teamnet_pairings(event_id: int,
                              db_path: str | Path = DB_PATH) -> dict:
    """Remove ONLY the GG-ingested pairing rows for one event (undo for a
    mis-matched apply). App-saved rows and event_pairings are untouched."""
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        cur = conn.execute(
            "DELETE FROM pairing_history WHERE event_id = ? "
            "AND source = 'gg_teamnet'", (int(event_id),))
        conn.commit()
        return {"event_id": int(event_id), "rows_deleted": cur.rowcount}


def _write_event_pairings_from_groups(conn: sqlite3.Connection,
                                      event_id: int, groups: list,
                                      holes: str | None = None) -> int:
    """Mirror ingested ACTUAL groups into event_pairings so the EVENTS
    page PAIRINGS tab shows played pairings on past events (Kerry
    2026-07-14). groups: [{'slot': str|None, 'players': [seat|None,…]}]
    where a seat is {'name': …} — None seats (blind fills) keep cart
    alignment but aren't written. holes inferred from event format /
    code; combo events' 18-hole groups may label as '9' (cosmetic).
    Pass `holes` explicitly to target one leg of a combo event — the
    delete is then scoped to that leg so the other one survives."""
    if holes not in ("9", "18"):
        ev = conn.execute(
            "SELECT format, item_name FROM events WHERE id = ?",
            (int(event_id),)).fetchone()
        fmt = (ev["format"] or "") if ev else ""
        nm = (ev["item_name"] or "") if ev else ""
        holes = "18" if ("18" in fmt and "9/18" not in fmt) or \
            re.match(r"^[a-z]18\b", nm, re.I) or "MATCHES" in nm.upper() else "9"
        conn.execute("DELETE FROM event_pairings WHERE event_id = ?",
                     (int(event_id),))
    else:
        conn.execute("DELETE FROM event_pairings WHERE event_id = ? "
                     "AND holes = ?", (int(event_id), holes))
    n = 0
    for gi, g in enumerate(groups, start=1):
        seats = g["players"]
        slot = g.get("slot") or f"Group {gi}"
        # Fivesomes are legal since Kerry's 2026-07-31 ruling, and GG
        # sheets carry them — the old [:4] silently dropped the 5th.
        for idx, p in enumerate(seats[:5]):
            if not p:
                continue
            conn.execute(
                """INSERT OR REPLACE INTO event_pairings
                   (event_id, holes, group_num, slot_label, player_name,
                    cart_pos)
                   VALUES (?, ?, ?, ?, ?, ?)""",
                (int(event_id), holes, gi, slot, p["name"], idx + 1))
            n += 1
    return n


def import_manual_pairing_groups(event_id: int, groups: list,
                                 apply: bool = False,
                                 source: str = "tee_sheet",
                                 db_path: str | Path = DB_PATH) -> dict:
    """Write pairing_history for one event from explicitly supplied groups
    (lists of names in tee-sheet seat order) — the path for OneDrive
    starter sheets / tee sheets, Kerry's ruled PRIMARY pairing source.
    Same semantics as the GG ingest: apply REPLACES the event's rows;
    rode pairs by seat sequence 1&2 / 3&4."""
    out: dict = {"event_id": event_id, "n_groups": len(groups),
                 "source": source, "applied": False}
    with _connect(db_path) as conn:
        _ensure_pairing_tables(conn)
        ev = conn.execute(
            "SELECT id, item_name, event_date FROM events WHERE id = ?",
            (int(event_id),)).fetchone()
        if not ev:
            out["error"] = f"no event {event_id}"
            return out
        out["event"] = {"id": ev["id"], "name": ev["item_name"],
                        "date": ev["event_date"]}
        resolved = []
        unresolved = []
        for seats in groups:
            rs = []
            for raw in seats:
                if not raw:
                    rs.append(None)
                    continue
                # "!Name" = literal: store normalized as-is, NO customer
                # resolution — for guests the fuzzy cascade could
                # mis-attach to a member (seen live: guest 'Cleary, Paul'
                # resolved to a member).
                if isinstance(raw, str) and raw.startswith("!"):
                    rs.append({"name": _normalize_player_name(raw[1:]),
                               "cid": None})
                    continue
                cid = None
                try:
                    cid = _resolve_scoring_player(conn, raw)
                except Exception:
                    cid = None
                canonical = None
                if cid:
                    c = conn.execute(
                        """SELECT TRIM(COALESCE(first_name,'') || ' ' ||
                                   COALESCE(last_name,'')) AS nm
                           FROM customers WHERE customer_id = ?""",
                        (cid,)).fetchone()
                    canonical = (c["nm"] or "").strip() or None
                if not canonical:
                    canonical = _normalize_player_name(raw)
                    unresolved.append(raw)
                rs.append({"name": canonical, "cid": cid})
            resolved.append(rs)
        out["unresolved_names"] = unresolved
        out["resolved_groups"] = [
            [p["name"] if p else None for p in rs] for rs in resolved]
        if apply:
            conn.execute("DELETE FROM pairing_history WHERE event_id = ?",
                         (ev["id"],))
            n_pairs = 0
            for rs in resolved:
                real = [(idx, p) for idx, p in enumerate(rs) if p]
                for x in range(len(real)):
                    for y in range(x + 1, len(real)):
                        (ia, pa), (ib, pb) = real[x], real[y]
                        a, b = sorted((pa, pb), key=lambda p: p["name"])
                        conn.execute(
                            """INSERT OR IGNORE INTO pairing_history
                               (player_a, player_b, event_id, event_date,
                                customer_a_id, customer_b_id, rode, source)
                               VALUES (?, ?, ?, ?, ?, ?, ?, ?)""",
                            (a["name"], b["name"], ev["id"], ev["event_date"],
                             a["cid"], b["cid"],
                             1 if ia // 2 == ib // 2 else 0, source))
                        n_pairs += 1
            out["event_pairings_rows"] = _write_event_pairings_from_groups(
                conn, ev["id"],
                [{"slot": None, "players": rs} for rs in resolved])
            conn.commit()
            out["applied"] = True
            out["pairs_written"] = n_pairs
    return out


def import_gg_teamnet_all(portal: str, apply: bool = False,
                          budget_seconds: int = 200,
                          db_path: str | Path = DB_PATH) -> dict:
    """Walk every round on the portal's tournament_results widget through
    the TEAM/CART Net pairings importer (time-budgeted; re-run to
    continue — apply replaces per event, so repeats are safe)."""
    import time as _time
    t0 = _time.time()
    listing = gg_teamnet_rounds(portal)
    results = []
    done = skipped = 0
    for r in listing["rounds"]:
        if _time.time() - t0 > budget_seconds:
            break
        try:
            res = import_gg_teamnet_round(portal, r["round_id"], apply=apply,
                                          label=r["label"], db_path=db_path)
        except Exception as e:
            res = {"round_id": r["round_id"], "label": r["label"],
                   "error": str(e)}
        slim = {k: res.get(k) for k in
                ("round_id", "label", "board", "n_groups", "group_sizes",
                 "blind_seats", "event", "applied", "pairs_written",
                 "error", "unresolved_names")
                if res.get(k) is not None}
        results.append(slim)
        if res.get("applied") or (not apply and res.get("n_groups")):
            done += 1
        else:
            skipped += 1
    return {"portal": portal, "widget": listing["widget"],
            "rounds_total": len(listing["rounds"]),
            "rounds_processed": len(results), "ok": done, "skipped": skipped,
            "rounds_left": len(listing["rounds"]) - len(results),
            "results": results}


def _pair_count(pair_counts: dict, a: str, b: str) -> int:
    """Look up play count for two players (normalized, alphabetical key)."""
    a, b = _pair_key_name(a), _pair_key_name(b)
    key = (min(a, b), max(a, b))
    return pair_counts.get(key, 0)


def _pair_cost(pair_counts: dict, a: str, b: str) -> int:
    """Optimizer cost for putting two players together. Kerry's rule 3 is
    MAXIMIZE NEW PAIRINGS — a once-played pair and a thrice-played pair
    are equally 'not new', so ANY repeat dominates repeat depth: primary
    term = is-repeat (weight 1000), tiebreak = play count (prefer
    re-pairing the 1s over the 3s when repeats are forced)."""
    c = _pair_count(pair_counts, a, b)
    return 0 if c == 0 else 1000 + c


def _group_score(players: list[str], pair_counts: dict) -> int:
    """Optimizer cost of a group: new-pair objective via _pair_cost —
    the number of repeat-pairs dominates; play counts break ties."""
    total = 0
    for i in range(len(players)):
        for j in range(i + 1, len(players)):
            total += _pair_cost(pair_counts, players[i], players[j])
    return total


# Name → customer_id index for partner-request matching, cached per
# process. Built from the customer_id PROFILES (canonical names + every
# alias row that carries a customer_id) rather than from name strings —
# Kerry 2026-07-30: "why not just reference actual aliases in customer_id
# profiles?" Guiding principle 6: two names are the same person because
# they resolve to the same customer_id, never because the strings look
# alike. Cached because this is consulted inside grouping loops and
# profiles change rarely.
_PARTNER_IDENTITY_CACHE: dict = {"at": 0.0, "map": {}}
_PARTNER_IDENTITY_TTL = 300.0


def _partner_name_key(name: str | None) -> str:
    """Whitespace/case-normalized name, the key used by the identity map."""
    return " ".join((name or "").split()).strip().lower()


def _partner_identity_map(db_path=None) -> dict:
    """{normalized name -> customer_id}, covering canonical + alias names.

    A name is ambiguous when two different customers answer to it (two
    real "Chris Martin"s). Those keys are dropped rather than pointed at
    an arbitrary winner — the same refuse-to-guess stance
    `_lookup_customer_id` takes on duplicate names.
    """
    import time as _time
    now = _time.time()
    if (now - _PARTNER_IDENTITY_CACHE["at"]) < _PARTNER_IDENTITY_TTL and \
            _PARTNER_IDENTITY_CACHE["map"]:
        return _PARTNER_IDENTITY_CACHE["map"]
    claims: dict = {}

    def _claim(name, cid):
        k = _partner_name_key(name)
        if not k or not cid:
            return
        claims.setdefault(k, set()).add(int(cid))

    try:
        with _connect(db_path) as conn:
            for r in conn.execute(
                    """SELECT customer_id, first_name, last_name, company_name
                       FROM customers
                       WHERE COALESCE(account_status,'active') != 'banned'"""
            ).fetchall():
                _claim(f"{r['first_name'] or ''} {r['last_name'] or ''}",
                       r["customer_id"])
                _claim(r["company_name"], r["customer_id"])
            # Alias rows: the alias VALUE and the profile name it was
            # captured under both point at the same customer_id.
            for r in conn.execute(
                    """SELECT customer_id, customer_name, alias_value
                       FROM customer_aliases
                       WHERE alias_type = 'name'
                         AND customer_id IS NOT NULL""").fetchall():
                _claim(r["alias_value"], r["customer_id"])
                _claim(r["customer_name"], r["customer_id"])
    except Exception:
        return _PARTNER_IDENTITY_CACHE["map"] or {}
    out = {k: next(iter(v)) for k, v in claims.items() if len(v) == 1}
    _PARTNER_IDENTITY_CACHE.update({"at": now, "map": out})
    return out


def _find_partner_name(request_text: str, all_names: list[str], requester: str,
                       db_path=None, roster_ids: dict | None = None
                       ) -> str | None:
    """Resolve a partner_request string to a rostered player name.

    A ladder, safest rung first. EVERY rung requires a UNIQUE match — an
    ambiguous one returns None so the manager sees "no roster match — fix"
    and picks from the dropdown, rather than the generator silently pairing
    the wrong two people.

    1. Exact full name (case/space-insensitive).
    2. **customer_id identity** — resolve the request text to a customer_id
       through the profile's canonical name and its `customer_aliases`
       rows, then find the roster player carrying that same id. "Dan South"
       and "Daniel South" match because they are the same PERSON, not
       because the strings resemble each other (Kerry 2026-07-30; guiding
       principle 6). `roster_ids` (name -> customer_id, straight off the
       roster rows) is authoritative for the roster side when the caller
       has it; otherwise roster names are resolved through the same map.
    3. Nickname-robust person key: surname + first initial. Covers the
       Matt/Matthew, Rob/Robert, Chris/Christopher class for people who
       have no alias on file yet.
    4. Substring, the original behaviour — now also uniqueness-checked, so
       a bare "Dan" against two Dans no longer resolves to whichever sorted
       first.
    """
    if not request_text:
        return None
    req = _partner_name_key(request_text)
    if not req:
        return None
    others = [n for n in all_names if (n or "").strip().lower() != (requester or "").strip().lower()]

    def _uniq(matches):
        uniq = list(dict.fromkeys(matches))
        return uniq[0] if len(uniq) == 1 else None

    # 1. exact
    hit = _uniq([n for n in others if _partner_name_key(n) == req])
    if hit:
        return hit

    # 2. same customer_id = same person
    ident = _partner_identity_map(db_path)
    req_cid = ident.get(req)
    if req_cid:
        by_key = {_partner_name_key(k): v
                  for k, v in (roster_ids or {}).items() if v}

        def _cid(n):
            return by_key.get(_partner_name_key(n)) or ident.get(_partner_name_key(n))

        hit = _uniq([n for n in others if _cid(n) == req_cid])
        if hit:
            return hit

    # 3. nickname-robust person key (surname + first initial)
    try:
        req_key = _cmp_person_key(request_text)
        if req_key[0] and req_key[1]:
            hit = _uniq([n for n in others if _cmp_person_key(n) == req_key])
            if hit:
                return hit
    except Exception:
        pass

    # 4. substring (legacy). The two directions mean different things and
    #    must not be treated alike:
    #
    #    a) a roster name appears INSIDE the request — "Dan Other or Ed
    #       Fifth". Several hits is EXPECTED here: people name more than one
    #       partner. Rule 1 honors only one, so take the first and let the
    #       caller flag candidates>1 for the manager (Kerry 2026-07-21).
    contained = [n for n in others if (n or "").lower() in req]
    if contained:
        # Honor the order the REQUESTER wrote, not roster order: "Ed Fifth
        # or Dan Other" means Ed first. Roster order would silently invert
        # a stated preference.
        contained.sort(key=lambda n: req.index((n or "").lower()))
        return contained[0]
    #    b) the request is a FRAGMENT of a roster name — a bare "Dan"
    #       against two Dans. Several hits is genuine ambiguity, so match
    #       nothing and let the manager pick rather than guess a pairing.
    return _uniq([n for n in others if req in (n or "").lower()])


_CMP_ROUND_LABELS = {"r16": "Round of 16", "qf": "Quarterfinal",
                     "sf": "Semifinal", "final": "Final"}


# ── Pace staging rules (task #23) — rules-as-data (principle 2) ─────────
# Kerry, 2026-07-14: group pace = aggregate of member ratings (1 slowest →
# 3 fastest, NULL reads as 2); staging ONLY — pace never dictates who
# plays with whom. Shotgun hole-trains put fast groups at the FRONT of
# the train (higher hole numbers = later sheet slots); sequential tee
# times put fast groups FIRST. Override any key via the
# 'pairing_staging_rules' app_settings JSON.
PAIRING_STAGING_DEFAULTS = {
    "enabled": True,
    "shotgun": "fast_front",    # fast → higher holes (later sheet slots)
    "tee_times": "fast_first",  # fast → earliest tee times
    "aggregate": "avg",         # group pace = average member rating
    "default_rating": 2,        # NULL pace_rating reads as 2 (Kerry)
    # Kerry 2026-07-21 (The Quarry, clarified same day): short groups
    # (threesomes/twosomes) beat pace. Tee times: they take the
    # EARLIEST times. Shotgun: they take the furthest-out loaded
    # hole's A slot, then its B slot, then the A slot one hole back
    # (4A → 4B → 3A). Pace orders within each size class.
    "smalls_lead": True,
    # Kerry 2026-07-28: when two groups TIE on pace average, the one
    # with the LOWER TOTAL handicap index goes first (better players
    # play faster than their pace rating implies). Set to "none" to
    # fall back to pure pace + size ordering.
    "pace_tie_break": "low_total_hcp",
}


def _stage_shotgun_smalls_lead(groups: list, slots: list,
                               pace_fn, hcp_fn=lambda g: 0.0) -> list:
    """Order settled groups over the filled shotgun slots per Kerry's
    2026-07-21 rulings. TRUE play order front-to-back is (hole DESC,
    A before B) — on a shared hole the A group tees off AHEAD of the
    B group, so 12A leads 12B (Kerry's 12A/12B catch: sheet-index
    order gets same-hole pairs backwards). Short groups take the
    front of the train (furthest hole's A, then its B, then the A one
    hole back), fastest/smallest first; foursomes fill the remaining
    slots in the same front-to-back order FASTEST FIRST — higher
    average pace goes first, slowest ends up at the back (lowest
    hole's B). Slots without hole labels (tee-count 0 → 'Group N')
    fall back to later-slot-equals-further-forward."""
    n = len(groups)
    filled = [slots[i] if i < len(slots) else f"Group {i + 1}"
              for i in range(n)]

    def slot_rank(i: int):
        m = _SHOTGUN_LABEL_RE.match((filled[i] or "").strip())
        if m:
            return (-int(m.group(1)), 0 if m.group(2) == "A" else 1)
        return (-i, 0)

    # Pace ties break to the LOWER total handicap (Kerry 2026-07-28):
    # among equal-pace groups the better foursome tees off first.
    smalls = sorted((g for g in groups if len(g) < 4),
                    key=lambda g: (-pace_fn(g), len(g), hcp_fn(g)))
    fours = sorted((g for g in groups if len(g) >= 4),
                   key=lambda g: (-pace_fn(g), hcp_fn(g)))
    pref = sorted(range(n), key=slot_rank)
    out: list = [None] * n
    for g, i in zip(smalls + fours, pref):
        out[i] = g
    return out


def get_pairing_staging_rules(db_path=None) -> dict:
    """The staging ordering rule, editable data over code defaults."""
    rules = dict(PAIRING_STAGING_DEFAULTS)
    try:
        raw = get_app_setting("pairing_staging_rules", db_path=db_path)
        if raw:
            override = json.loads(raw)
            if isinstance(override, dict):
                rules.update(override)
    except Exception:
        logger.exception("pairing_staging_rules unreadable — using defaults")
    return rules


def _event_roster_players(conn, event_id: int) -> list[dict]:
    """Active registrants for an event: name + customer_id (rule 6).
    Same events → aliases → items join the generator uses."""
    INACTIVE = ("credited", "refunded", "transferred", "wd")
    ph = ",".join("?" * len(INACTIVE))
    rows = conn.execute(
        f"""
        SELECT DISTINCT i.customer AS name, i.customer_id
        FROM events e
        LEFT JOIN event_aliases ea ON ea.canonical_event_name = e.item_name
        JOIN items i ON (
            i.item_name = e.item_name COLLATE NOCASE
            OR i.item_name = ea.alias_name COLLATE NOCASE
            OR i.event_id = e.id
        )
        WHERE e.id = ?
          AND COALESCE(i.transaction_status, 'active') NOT IN ({ph})
          AND i.parent_item_id IS NULL
        """,
        (event_id, *INACTIVE),
    ).fetchall()
    return [dict(r) for r in rows if r["name"]]


def detect_match_play_pairings(event_id: int, db_path=None) -> dict:
    """Rule 8 as AMENDED (Kerry 2026-07-14, 'Match Play is king'): find the
    potential Match Play matches the season state implies between players
    on this event's roster. The Generate Pairings flow shows each one to
    the manager for a confirm/decline BEFORE generating; confirmed matches
    become the generator's first constraint (same foursome, opposite carts).

    Phase rule: a seeded knockout (any cmp_bracket rows for the season +
    chapter) means pool play is over — only pending bracket matchups count.
    Otherwise every pool-mate pair without a PLAYED cmp_matches row (no
    played_at) is a potential match; a scheduled-but-unplayed row and a
    never-created row both imply "these two still need to play".

    Roster membership is checked by customer_id first (rule 6), normalized
    name as fallback (cmp_* rows written before the id columns existed).
    """
    with _connect(db_path) as conn:
        ev = conn.execute(
            "SELECT id, item_name, event_date, chapter FROM events WHERE id = ?",
            (event_id,),
        ).fetchone()
        if not ev:
            raise ValueError(f"Event {event_id} not found")
        ev = dict(ev)
        chapter = (ev.get("chapter") or "").strip()
        season = (ev.get("event_date") or "")[:4]
        if not season:
            from email_parser.timezone_utils import now_central
            season = str(now_central().year)

        out: dict = {"event_id": event_id, "event_name": ev.get("item_name"),
                     "season": season, "chapter": chapter,
                     "phase": None, "matches": [], "notes": []}
        if not chapter:
            out["notes"].append("Event has no chapter — cannot scope Match Play state.")
            return out

        roster = _event_roster_players(conn, event_id)
        roster_ids = {r["customer_id"] for r in roster if r.get("customer_id")}
        roster_names = {_pair_key_name(r["name"]): r["name"] for r in roster}

        def on_roster(name, cid):
            if cid and cid in roster_ids:
                return True
            return _pair_key_name(name or "") in roster_names

        def display(name):
            """Prefer the roster's casing of the name so the generator can
            match the pair against its player list exactly."""
            return roster_names.get(_pair_key_name(name or ""), name)

        bracket = conn.execute(
            "SELECT * FROM cmp_bracket WHERE season = ? AND chapter = ? "
            "ORDER BY round, slot",
            (season, chapter),
        ).fetchall()

        if bracket:
            # ── Knockout phase: pending matchups = slot pairs (2i, 2i+1)
            # with both players placed and no winner recorded.
            out["phase"] = "knockout"
            by_round: dict[str, dict[int, dict]] = {}
            for b in bracket:
                by_round.setdefault(b["round"], {})[b["slot"]] = dict(b)
            for rnd in ("r16", "qf", "sf", "final"):
                slots = by_round.get(rnd)
                if not slots:
                    continue
                for lo in sorted(slots):
                    if lo % 2:
                        continue
                    s1, s2 = slots.get(lo), slots.get(lo + 1)
                    if not s1 or not s2:
                        continue
                    p1, p2 = s1.get("player_name"), s2.get("player_name")
                    if not p1 or not p2:
                        continue
                    if s1.get("winner_name") or s2.get("winner_name"):
                        continue
                    both = (on_roster(p1, s1.get("player_id"))
                            and on_roster(p2, s2.get("player_id")))
                    if not both:
                        continue
                    out["matches"].append({
                        "stage": "knockout",
                        "label": _CMP_ROUND_LABELS.get(rnd, rnd),
                        "player1": display(p1), "player2": display(p2),
                        "player1_id": s1.get("player_id"),
                        "player2_id": s2.get("player_id"),
                    })
        else:
            # ── Pool phase: pool-mate pairs with no PLAYED match yet.
            out["phase"] = "pool"
            pools = conn.execute(
                "SELECT id, pool_name FROM cmp_pools WHERE season = ? AND chapter = ? "
                "ORDER BY pool_name",
                (season, chapter),
            ).fetchall()
            if not pools:
                out["phase"] = None
                return out
            for pool in pools:
                members = conn.execute(
                    "SELECT customer_name, customer_id FROM cmp_pool_members "
                    "WHERE pool_id = ? ORDER BY customer_name",
                    (pool["id"],),
                ).fetchall()
                here = [m for m in members
                        if on_roster(m["customer_name"], m["customer_id"])]
                if len(here) < 2:
                    continue
                played = set()
                for m in conn.execute(
                    "SELECT player1_name, player2_name FROM cmp_matches "
                    "WHERE pool_id = ? AND played_at IS NOT NULL",
                    (pool["id"],),
                ).fetchall():
                    played.add(frozenset((_pair_key_name(m["player1_name"]),
                                          _pair_key_name(m["player2_name"]))))
                for i in range(len(here)):
                    for j in range(i + 1, len(here)):
                        a, b = here[i], here[j]
                        key = frozenset((_pair_key_name(a["customer_name"]),
                                         _pair_key_name(b["customer_name"])))
                        if key in played:
                            continue
                        out["matches"].append({
                            "stage": "pool",
                            "label": pool["pool_name"],
                            "player1": display(a["customer_name"]),
                            "player2": display(b["customer_name"]),
                            "player1_id": a["customer_id"],
                            "player2_id": b["customer_id"],
                        })
        return out


def generate_event_pairings(
    event_id: int,
    mode: str = "random",
    protect_partner_requests: bool = True,
    seeds: list | None = None,
    mp_pairs: list | None = None,
    race_key: str | None = None,
    db_path=None,
) -> dict:
    """Generate pairings for an event and return (but do NOT save) the result.

    mode: 'random' | 'abcd' | 'standings'
        'standings' orders by the chapter's points race with the LEADERS
        GOING OFF LAST (PGA order), honoring partner requests first — see
        _standings_groups. race_key overrides the chapter's default race.
    protect_partner_requests: honor partner_request field
    seeds: list of pre-assigned player locks:
        [{"holes": "9"|"18", "slot_index": int (0-based), "players": [{"name", "cart_pos"}]}]
    mp_pairs: manager-CONFIRMED Match Play matches, [[name1, name2], ...]
        (rule 8 amendment, Kerry 2026-07-14: "Match Play is king").
        Opponents land in the same foursome in OPPOSITE carts (seats 1/2
        vs 3/4) — the first constraint, above partner requests. A partner
        request is still honored where it fits around a match (attached
        to the match's foursome), never at the match's expense.

    Returns:
        {
            "9":  [{"group_num", "slot_label", "players": [...]}],
            "18": [...],
            "slots_9":  [str, ...],
            "slots_18": [str, ...],
            "mp_notes": [str, ...],   # only when mp_pairs were passed
        }
    Players carry "mp_opponent" when their confirmed opponent is in the
    same group (the PAIRINGS tab's visual denotation).
    """
    import random as _random

    seeds = seeds or []
    mp_pairs = mp_pairs or []
    with _connect(db_path) as conn:
        # ── Load event ────────────────────────────────────────────────
        ev = conn.execute(
            "SELECT * FROM events WHERE id = ?", (event_id,)
        ).fetchone()
        if not ev:
            raise ValueError(f"Event {event_id} not found")
        ev = dict(ev)
        ev_chapter = ev.get("chapter")

        fmt = (ev.get("format") or "").strip()
        is_combo = fmt == "9/18 Combo"

        # ── Active players for this event ─────────────────────────────
        # Start from events → aliases → items (mirrors get_all_events join order)
        INACTIVE = ("credited", "refunded", "transferred", "wd")
        ph = ",".join("?" * len(INACTIVE))
        items = conn.execute(
            f"""
            SELECT DISTINCT i.customer, i.holes, i.tee_choice,
                            i.partner_request, i.id, i.order_date,
                            i.created_at, i.notes, i.order_id,
                            i.customer_email, i.customer_id,
                            i.user_status, c.current_player_status
            FROM events e
            LEFT JOIN event_aliases ea ON ea.canonical_event_name = e.item_name
            JOIN items i ON (
                i.item_name = e.item_name COLLATE NOCASE
                OR i.item_name = ea.alias_name COLLATE NOCASE
                OR i.event_id = e.id
            )
            LEFT JOIN customers c ON c.customer_id = i.customer_id
            WHERE e.id = ?
              AND COALESCE(i.transaction_status, 'active') NOT IN ({ph})
              AND i.parent_item_id IS NULL
            ORDER BY i.customer COLLATE NOCASE
            """,
            (event_id, *INACTIVE),
        ).fetchall()
        items = [dict(r) for r in items]

        # ── Signup-order priority (Kerry 2026-07-21) ──────────────────
        # Requests are honored FIRST-COME: sort the roster by when each
        # player's signup landed (order_date, then ingest time, then row
        # id) and keep the earliest row per player. Every downstream
        # consumer of partner_map iterates in this insertion order, so
        # the earliest request wins any 3/4-person cross-request — once
        # a player is claimed (either direction), later requests
        # touching them are dropped.
        items.sort(key=_request_time_key)
        _seen_players: set = set()
        _deduped: list = []
        for it in items:
            k = _pair_key_name(it.get("customer") or "")
            if not k or k in _seen_players:
                continue
            _seen_players.add(k)
            _deduped.append(it)
        items = _deduped

        # ── Manager request overrides (Kerry 2026-07-21) ──────────────
        # Manual matches first: substitute the bound roster name for
        # signup text that didn't auto-resolve ('Dave' vs 'David
        # Decareaux'). Then suppressions: blank the request entirely —
        # it stays listed on the PAIRINGS tab badged SUPPRESSED.
        _ensure_pairing_tables(conn)
        _matches = {_pair_key_name(r["requester_name"]): r["partner_name"]
                    for r in conn.execute(
            "SELECT requester_name, partner_name FROM pairing_request_matches "
            "WHERE event_id = ?", (event_id,)).fetchall()}
        _suppressed = {_pair_key_name(r["requester_name"]) for r in conn.execute(
            "SELECT requester_name FROM pairing_request_suppressions "
            "WHERE event_id = ?", (event_id,)).fetchall()}
        # Manager-approved requests (Kerry 2026-07-31): these beat the
        # first-come lock by joining the partner's group, so they must be
        # bound into units before ordinary pairing runs.
        _approved = {_pair_key_name(r["requester_name"]) for r in conn.execute(
            "SELECT requester_name FROM pairing_request_approvals "
            "WHERE event_id = ?", (event_id,)).fetchall()}
        for it in items:
            k = _pair_key_name(it.get("customer") or "")
            if k in _matches and (it.get("partner_request") or "").strip():
                it["partner_request"] = _matches[k]
            if k in _suppressed:
                it["partner_request"] = None

        # ── Handicap index map ────────────────────────────────────────
        hcp_rows = conn.execute(
            """
            SELECT l.customer_name, p.handicap_index
            FROM (
                SELECT player_name,
                       AVG(differential) as handicap_index
                FROM (
                    SELECT player_name, differential,
                           ROW_NUMBER() OVER (
                               PARTITION BY player_name
                               ORDER BY round_date DESC, id DESC
                           ) as rn
                    FROM handicap_rounds
                    WHERE differential IS NOT NULL
                      AND round_date >= date('now', '-12 months')
                )
                WHERE rn <= 20
                GROUP BY player_name
            ) p
            JOIN handicap_player_links l ON l.player_name = p.player_name
            WHERE l.customer_name IS NOT NULL
            """
        ).fetchall()
        hcp_map = {r["customer_name"].lower(): r["handicap_index"] for r in hcp_rows}

        # ── Pace map for STAGING (task #23) ───────────────────────────
        # Keyed by the roster's own name via customer_id (rule 6 — also
        # suffix-proof: 'Victor Arias III' finds the unsuffixed customer
        # row). Unrated players read as the configured default (2).
        pace_rows = conn.execute(
            f"""
            SELECT DISTINCT i.customer AS name, c.pace_rating
            FROM events e
            LEFT JOIN event_aliases ea ON ea.canonical_event_name = e.item_name
            JOIN items i ON (
                i.item_name = e.item_name COLLATE NOCASE
                OR i.item_name = ea.alias_name COLLATE NOCASE
                OR i.event_id = e.id
            )
            JOIN customers c ON c.customer_id = i.customer_id
            WHERE e.id = ?
              AND COALESCE(i.transaction_status, 'active') NOT IN ({ph})
              AND i.parent_item_id IS NULL
              AND c.pace_rating IS NOT NULL
            """,
            (event_id, *INACTIVE),
        ).fetchall()
        pace_map = {_pair_key_name(r["name"]): r["pace_rating"]
                    for r in pace_rows if r["name"]}

    staging_rules = get_pairing_staging_rules(db_path=db_path)

    # FIVESOMES (Kerry 2026-07-31). Off by default: a fivesome only ever
    # happens because a manager asked for one. The event-level switch
    # builds the whole sheet out of fivesomes, with FOURSOMES as the
    # short groups — "the same relational rules that 3somes play in a
    # 4some setup". A manager can still drop a 5th into any single group
    # by hand without turning this on.
    max_group = 5 if int(ev.get("allow_fivesomes") or 0 or 0) else 4

    # ── Normalise holes per player ────────────────────────────────────
    def player_holes(item):
        h = (item.get("holes") or "").strip()
        if h in ("9", "18"):
            return h
        return "18" if fmt in ("18 Holes", "27 Holes") else "9"

    # ── Separate players by holes ─────────────────────────────────────
    nines = [i for i in items if player_holes(i) == "9"]
    eighteens = [i for i in items if player_holes(i) == "18"]
    if not is_combo:
        if fmt in ("18 Holes", "27 Holes"):
            eighteens, nines = items, []
        else:
            nines, eighteens = items, []

    # ── Pairing history for current year ─────────────────────────────
    pair_counts = get_pairing_history_counts(db_path=db_path)

    # ── Confirmed Match Play pairs: roster + holes validation ────────
    # (rule 8 amendment — opponents must share a holes bucket to share
    # a foursome; anything that can't be constrained is reported, never
    # silently dropped)
    mp_notes: list[str] = []
    _roster_norm = {_pair_key_name(i["customer"]): i["customer"]
                    for i in items if i.get("customer")}
    _holes_norm = {_pair_key_name(i["customer"]): player_holes(i)
                   for i in items if i.get("customer")}
    valid_mp_pairs: list[tuple[str, str]] = []
    for pr in mp_pairs:
        if not (isinstance(pr, (list, tuple)) and len(pr) == 2):
            continue
        ak, bk = _pair_key_name(str(pr[0])), _pair_key_name(str(pr[1]))
        if ak == bk:
            continue
        if ak not in _roster_norm or bk not in _roster_norm:
            mp_notes.append(f"{pr[0]} vs {pr[1]}: not both on the event "
                            "roster — match constraint dropped.")
            continue
        if _holes_norm.get(ak) != _holes_norm.get(bk):
            mp_notes.append(f"{_roster_norm[ak]} vs {_roster_norm[bk]}: "
                            "registered for different hole counts — cannot "
                            "share a foursome.")
            continue
        valid_mp_pairs.append((_roster_norm[ak], _roster_norm[bk]))
    if valid_mp_pairs and mode == "abcd":
        mp_notes.append("Match Play constraints apply to Random mode only — "
                        "ABCD groups were built without them.")
        valid_mp_pairs = []

    # ── Generate slots ────────────────────────────────────────────────
    slots_9 = _pairing_time_slots(ev, "9")
    slots_18 = _pairing_time_slots(ev, "18")

    # ── Seed map: holes → {slot_index: {cart_pos: name}} ─────────────
    seed_map: dict[str, dict[int, dict[int, str]]] = {"9": {}, "18": {}}
    seeded_players: dict[str, set] = {"9": set(), "18": set()}
    for s in seeds:
        h = s.get("holes", "9")
        si = s.get("slot_index", 0)
        if si not in seed_map[h]:
            seed_map[h][si] = {}
        for sp in s.get("players", []):
            seed_map[h][si][sp["cart_pos"]] = sp["name"]
            seeded_players[h].add(sp["name"])

    result: dict = {}
    # {normalized name | customer_id -> season points} for the chosen race,
    # so the PAIRINGS tab can show the number the order was built from
    # (Kerry 2026-07-31). Empty unless standings mode ran.
    standings_points: dict = {}
    standings_enrolled: dict = {}

    for holes, player_items, slots in [("9", nines, slots_9), ("18", eighteens, slots_18)]:
        if not player_items and not seed_map[holes]:
            continue

        all_names = [p["customer"] for p in player_items if p.get("customer")]
        # Build quick lookup dicts
        tee_map = {p["customer"]: p.get("tee_choice") for p in player_items if p.get("customer")}
        partner_map = {p["customer"]: p.get("partner_request") for p in player_items if p.get("customer")}

        # Players available for free assignment (not seeded)
        free_players = [n for n in all_names if n not in seeded_players[holes]]

        # ── Host-and-guests units (Kerry 2026-07-30) ──────────────────
        # The requests panel promises a host and the guests they paid for
        # play together; the generator has to actually build that group,
        # or the badge is a lie. Below Match Play (rule 8: "Match Play is
        # king"), above ordinary partner pairs. Computed off the same
        # `_host_of_map` the panel uses so the two can never disagree.
        _host_ids = {p["customer"]: p.get("customer_id")
                     for p in player_items
                     if p.get("customer") and p.get("customer_id")}
        host_of_all = _host_of_map(player_items, all_names,
                                   roster_ids=_host_ids)
        bound_units = _host_units(host_of_all, free_players, max_group)

        # Every honored request, walked in SIGNUP ORDER — the same
        # simulation the requests panel runs. Two kinds of request beat
        # the first-come lock and JOIN a group instead of losing to it:
        #   * GUEST requests (Kerry 2026-07-31) — "give all guests the
        #     ability to feel the group out and play with who they want,
        #     but require the members to branch out";
        #   * MANAGER-APPROVED requests (rule 5 override).
        # Building those FIRST (as this did) let a late approved request
        # claim a player out from under an EARLIER ordinary request the
        # panel still showed as active — Palacios lost Anthis to the
        # approved Anthis→Murphy (Kerry 2026-07-31, "Nor is it honoring
        # requests"). Signup order fixes it: Palacios claims Anthis, and
        # the approval joins that unit, which is what approve means.
        _is_member = {p["customer"]: bool(_ls_is_member(
                          p.get("current_player_status"), p.get("user_status")))
                      for p in player_items if p.get("customer")}

        def _privileged(nm):
            return (_pair_key_name(nm) in _approved
                    or not _is_member.get(nm, True))

        if protect_partner_requests:
            bound_units = _build_bound_units(
                free_players, partner_map, bound_units, _privileged,
                lambda txt, who: _find_partner_name(txt, free_players, who),
                max_group)

        # ── Determine groups to fill ──────────────────────────────────
        n_free = len(free_players)
        # Seeded slots may be partially or fully locked
        n_slots = len(slots) if slots else max(
            1,
            -(-len(all_names) // 4)  # ceil(n/4)
        )

        # Count how many positions are pre-filled per seed slot
        seed_space_used = {si: len(v) for si, v in seed_map[holes].items()}
        # Positions still open in seeded slots
        seed_space_open = {si: 4 - len(v) for si, v in seed_map[holes].items() if len(v) < 4}

        # ── Match Play units (rule 8 amendment: the FIRST constraint) ──
        # Confirmed opponents form an unsplittable unit; overlapping
        # matches (pool play: one player can owe several pool-mates a
        # match) merge into one unit up to a foursome. A seed lock on
        # either player wins (rule 5: manager override) — the match is
        # reported, not auto-constrained.
        mp_units: list[list[str]] = []
        mp_opponents: set[frozenset] = set()
        for a, b in valid_mp_pairs:
            if a not in free_players or b not in free_players:
                if a in seeded_players[holes] or b in seeded_players[holes]:
                    mp_notes.append(f"{a} vs {b}: a player is locked in a "
                                    "seed — match left to the manager's "
                                    "placement (override wins).")
                continue
            ua = next((u for u in mp_units if a in u), None)
            ub = next((u for u in mp_units if b in u), None)
            if ua is not None and ub is not None:
                if ua is ub:
                    pass  # already together
                elif len(ua) + len(ub) <= 4:
                    ua.extend(ub)
                    mp_units.remove(ub)
                else:
                    mp_notes.append(f"{a} vs {b}: overlapping matches don't "
                                    "fit one foursome — this match was NOT "
                                    "constrained.")
                    continue
            elif ua is not None:
                if len(ua) >= 4:
                    mp_notes.append(f"{a} vs {b}: {a}'s match group is full "
                                    "— this match was NOT constrained.")
                    continue
                ua.append(b)
            elif ub is not None:
                if len(ub) >= 4:
                    mp_notes.append(f"{a} vs {b}: {b}'s match group is full "
                                    "— this match was NOT constrained.")
                    continue
                ub.append(a)
            else:
                mp_units.append([a, b])
            mp_opponents.add(frozenset((_pair_key_name(a), _pair_key_name(b))))
        mp_names = {n for u in mp_units for n in u}

        # Partner-request adjacency pairs (for cart seating) — built from
        # the same pairing rule _partner_locked_names uses.
        partner_adj: set[frozenset] = set()
        if protect_partner_requests:
            _pa_used: set = set()
            for requester, req_text in partner_map.items():
                if requester in _pa_used:
                    continue
                partner = _find_partner_name(req_text, all_names, requester)
                if partner and partner not in _pa_used:
                    partner_adj.add(frozenset((_pair_key_name(requester),
                                               _pair_key_name(partner))))
                    _pa_used.update((requester, partner))

        # Honor partner requests around a match where possible (never at
        # the match's expense): when exactly one of the two is inside a
        # match unit with room, the other joins that foursome.
        if protect_partner_requests and mp_units:
            for requester, req_text in partner_map.items():
                partner = _find_partner_name(req_text, free_players, requester)
                if not partner:
                    continue
                in_r = next((u for u in mp_units if requester in u), None)
                in_p = next((u for u in mp_units if partner in u), None)
                if (in_r is None) == (in_p is None):
                    if in_r is not None and in_p is not None and in_r is not in_p:
                        mp_notes.append(f"{requester} + {partner}: partner "
                                        "request dropped — both have Match "
                                        "Play matches in different groups.")
                    continue
                unit, joiner = (in_r, partner) if in_r is not None else (in_p, requester)
                if joiner in mp_names:
                    continue
                if len(unit) < 4:
                    unit.append(joiner)
                    mp_names.add(joiner)
                else:
                    mp_notes.append(f"{requester} + {partner}: partner "
                                    "request dropped — the Match Play "
                                    "foursome is full.")

        locked_names = _partner_locked_names(
            [n for n in free_players if n not in mp_names],
            partner_map, protect_partner_requests,
            host_units=bound_units if protect_partner_requests else None)
        locked_names |= mp_names

        if mode == "abcd":
            groups_players = _abcd_groups(free_players, hcp_map, max_group)
        elif mode == "standings":
            _rank_map, _race_used, _rnotes, _meta = _standings_rank_map(
                ev_chapter, race_key, event_name=ev.get("item_name"),
                db_path=db_path, _with_meta=True)   # refreshes if stale
            standings_points = _meta["points"]
            standings_enrolled = _meta["enrolled"]
            mp_notes.extend(_rnotes)
            if _rank_map:
                groups_players, _snotes = _standings_groups(
                    free_players, _rank_map, partner_map,
                    protect_partner_requests,
                    host_units=bound_units if protect_partner_requests else None,
                    id_map={p["customer"]: p.get("customer_id")
                            for p in player_items if p.get("customer")},
                    hcp_map=hcp_map, max_group=max_group)
                mp_notes.extend(_snotes)
            else:
                # No usable standings — say so and fall back rather than
                # silently producing an order that looks intentional.
                groups_players = _abcd_groups(free_players, hcp_map, max_group)
                mp_notes.append("Standings unavailable — used ABCD instead.")
        else:
            # Best-of-K restarts + swap hill-climb. The greedy alone has a
            # structural attractor: it fills groups in order, so the most-
            # played players get avoided until the end and pool together in
            # the LAST group (Kerry's live s9.18 case — his max-repeat trio
            # recurred across runs). Random restarts don't escape it;
            # pairwise swaps between groups do.
            best_groups: list | None = None
            best_score: int | None = None
            for _ in range(30):
                cand = _random_groups(
                    free_players, partner_map, pair_counts,
                    protect_partner_requests, fixed_units=mp_units,
                    host_units=bound_units if protect_partner_requests else None,
                    max_group=max_group
                )
                cand = _swap_improve(cand, pair_counts, locked_names)
                score = sum(_group_score(g, pair_counts) for g in cand)
                if best_score is None or score < best_score:
                    best_groups, best_score = cand, score
                if best_score == 0:
                    break
            groups_players = best_groups or []

        # Seat order within a settled group (foursomes already decided —
        # this only decides who RIDES with whom): every group runs the
        # exact seater. Priority when they conflict (Kerry 2026-07-21):
        # MP opponents in OPPOSITE carts (seats 1/2 vs 3/4) > partner-
        # request pairs in the SAME cart (requests supersede tees) >
        # same-tee players share a cart. The old sort-by-tee ordering
        # for unconstrained groups could split a tee pair across carts
        # when a third tee was present — the seater can't.
        def _seat(names: list[str]) -> list[str]:
            return _arrange_group_seats(names, mp_opponents,
                                        partner_adj, tee_map)

        is_shotgun = (ev.get("start_type" if holes == "9" else "start_type_18") == "Shotgun")

        # ── STAGING (task #23): order settled groups by aggregate pace.
        # HARD RULE: pace never dictates composition — the groups above
        # are final; this step only decides WHERE each group is staged.
        # Shotgun: fast groups to the FRONT of the hole train (higher
        # hole numbers = later sheet slots), so slowest-first here.
        # Tee times: fastest-first. Size breaks pace ties (a smaller
        # group plays faster), which also preserves the old shotgun
        # behavior of threesomes at the train's front. Seeded groups
        # stay where the manager placed them (rule 5).
        default_r = staging_rules.get("default_rating", 2)

        def _group_pace(names: list[str]) -> float:
            vals = [pace_map.get(_pair_key_name(n), default_r)
                    for n in names if n]
            return (sum(vals) / len(vals)) if vals else float(default_r)

        # Pace-tie tiebreak (Kerry 2026-07-28): equal-pace groups order by
        # LOWER TOTAL handicap index first — the better foursome goes out
        # ahead. A player with no stored index counts 20.0 so an unknown
        # never jumps a known-good group to the front.
        _tie_break = staging_rules.get("pace_tie_break", "low_total_hcp")

        def _group_hcp(names: list[str]) -> float:
            if _tie_break != "low_total_hcp":
                return 0.0
            return sum(
                (hcp_map.get((n or "").lower()) if
                 hcp_map.get((n or "").lower()) is not None else 20.0)
                for n in names if n)

        # STANDINGS MODE OWNS THE ORDER — RULED (Kerry 2026-07-31: "the
        # pace rule kind of becomes obsolete when we do pairings by
        # standings"). Pace staging decides WHERE a settled group is
        # staged, but in standings mode the staging order IS the
        # deliverable. Re-sorting by pace silently threw the whole thing
        # away: the SA Championship sheet said "leaders go off LAST" and
        # then came out in perfect descending pace order (2.5, 2.5, 2, 2,
        # 2, 2, 1.75, 1.25), with the unranked players stranded in the
        # middle instead of the front. Pace ratings are still COMPUTED and
        # shown per group as a manager read-out — they just don't move
        # anybody.
        _standings_order = (mode == "standings" and groups_players)
        staging_applied = bool(staging_rules.get("enabled", True)
                               and groups_players
                               and not _standings_order)
        if _standings_order and staging_rules.get("enabled", True):
            mp_notes.append(
                "Pace staging does not apply in STANDINGS mode — the "
                "standings set the tee sheet. Group pace is still shown "
                "for reference; use Random or ABCD to stage by pace.")
        if staging_applied:
            smalls_lead = staging_rules.get("smalls_lead", True)
            if is_shotgun and smalls_lead:
                # Short groups lead the hole train: furthest-out loaded
                # hole's A slot, then its B slot, then the A slot one
                # hole back (Kerry 2026-07-21 clarification). Foursomes
                # fill the rest slowest-first.
                groups_players = _stage_shotgun_smalls_lead(
                    groups_players, slots, _group_pace, _group_hcp)
            elif smalls_lead:
                # Tee times: short groups take the EARLIEST times
                # (Kerry 2026-07-21 clarification); fastest first
                # within each size class, smaller first on pace ties,
                # then lower total handicap (Kerry 2026-07-28).
                groups_players.sort(
                    key=lambda g: (len(g) >= 4, -_group_pace(g), len(g),
                                   _group_hcp(g)))
            else:
                groups_players.sort(key=lambda g: (-_group_pace(g), len(g)),
                                    reverse=bool(is_shotgun))

        # ── Build final group list with slot labels ───────────────────

        # Start with seeded groups (already filled positions)
        seeded_groups: dict[int, list] = {}
        for si, pos_map in seed_map[holes].items():
            seeded_groups[si] = [
                {"name": pos_map[cp], "cart_pos": cp,
                 "tee_choice": tee_map.get(pos_map[cp]),
                 "handicap_index": hcp_map.get((pos_map[cp] or "").lower())}
                for cp in sorted(pos_map)
            ]

        # Assign free groups to remaining slots
        all_groups: list[dict] = []
        group_num = 1
        free_group_idx = 0

        for si in range(n_slots):
            if si in seeded_groups:
                existing = seeded_groups[si]
                # Fill remaining spots from free groups
                if free_group_idx < len(groups_players):
                    needed = max_group - len(existing)
                    fill_players = groups_players[free_group_idx][:needed]
                    if len(fill_players) == needed:
                        free_group_idx += 1
                    else:
                        free_group_idx += 1
                    next_cart = max((p["cart_pos"] for p in existing), default=0) + 1
                    for fname in fill_players:
                        existing.append({
                            "name": fname,
                            "cart_pos": next_cart,
                            "tee_choice": tee_map.get(fname),
                            "handicap_index": hcp_map.get((fname or "").lower()),
                        })
                        next_cart += 1
                all_groups.append({
                    "slot_label": slots[si] if si < len(slots) else f"Group {si+1}",
                    "players": existing,
                })
            else:
                if free_group_idx < len(groups_players):
                    gp = _seat(groups_players[free_group_idx])
                    free_group_idx += 1
                    players_out = []
                    for cp, name in enumerate(gp, start=1):
                        players_out.append({
                            "name": name,
                            "cart_pos": cp,
                            "tee_choice": tee_map.get(name),
                            "handicap_index": hcp_map.get((name or "").lower()),
                        })
                    all_groups.append({
                        "slot_label": slots[si] if si < len(slots) else f"Group {si+1}",
                        "players": players_out,
                    })
                else:
                    # Empty slot (more slots than groups)
                    all_groups.append({
                        "slot_label": slots[si] if si < len(slots) else f"Group {si+1}",
                        "players": [],
                    })

        # Handle overflow: free groups beyond available slots
        while free_group_idx < len(groups_players):
            gp = _seat(groups_players[free_group_idx])
            free_group_idx += 1
            players_out = []
            for cp, name in enumerate(gp, start=1):
                players_out.append({
                    "name": name,
                    "cart_pos": cp,
                    "tee_choice": tee_map.get(name),
                    "handicap_index": hcp_map.get((name or "").lower()),
                })
            label = slots[len(all_groups)] if len(all_groups) < len(slots) else f"Group {len(all_groups)+1}"
            all_groups.append({"slot_label": label, "players": players_out})

        # Remove empty groups
        all_groups = [g for g in all_groups if g["players"]]

        # For shotgun WITHOUT pace staging: push threesomes to last slots
        # (the legacy ordering — staging subsumes it: at equal pace the
        # size tiebreak already sends smaller groups to the train front).
        if is_shotgun and slots and not staging_applied and not _standings_order:
            foursomes = [g for g in all_groups if len(g["players"]) >= 4]
            smalls = [g for g in all_groups if len(g["players"]) < 4]
            ordered = foursomes + smalls
            for i, g in enumerate(ordered):
                g["slot_label"] = slots[i] if i < len(slots) else f"Group {i+1}"
        else:
            ordered = all_groups

        # Group pace readout for the PAIRINGS tab (manager sanity check)
        for g in ordered:
            names = [p["name"] for p in g["players"] if p.get("name")]
            g["group_pace"] = round(_group_pace(names), 2) if names else None

        # Assign final group_num
        for i, g in enumerate(ordered):
            g["group_num"] = i + 1

        # Visual denotation feed: tag each player whose confirmed Match
        # Play opponent landed in the same group (rule 8's PAIRINGS-tab
        # requirement) — includes seeded groups the manager built.
        if mp_opponents:
            for g in ordered:
                norms = {_pair_key_name(p["name"]): p["name"]
                         for p in g["players"] if p.get("name")}
                for p in g["players"]:
                    pk = _pair_key_name(p.get("name") or "")
                    opps = [norms[next(iter(pair - {pk}))]
                            for pair in mp_opponents
                            if pk in pair and next(iter(pair - {pk})) in norms]
                    if opps:
                        p["mp_opponent"] = " & ".join(opps)

        result[holes] = ordered

    result["slots_9"] = slots_9
    result["slots_18"] = slots_18
    if mp_pairs or mp_notes:
        result["mp_notes"] = mp_notes
    if standings_points or standings_enrolled:
        # BOTH keyings go over the wire. Sending name keys ONLY was a
        # straight guiding-principle-6 violation and it bit exactly where
        # you'd expect: GG spells people its own way ("MORENO, Robert" for
        # our Roberto Moreno, "MURPHY, Mike" for our Michael Murphy), so
        # the name key never matched the roster name and the pairing card
        # showed a dash — even though customer_id had resolved perfectly
        # and the Contests board was showing their points all along
        # (Kerry 2026-07-31). JSON object keys are strings, so ids arrive
        # as "1234"; the UI reads the id first and falls back to the name.
        result["standings_points"] = {str(k): v for k, v in standings_points.items()}
        result["standings_enrolled"] = {str(k): v for k, v in standings_enrolled.items()}
    return result


def _make_group_sizes(n: int, max_size: int = 4) -> list[int]:
    """Return group sizes summing to n with max `max_size` per group and no
    onesomes.

    Kerry 2026-07-21: never more than three 3-somes within a grouping
    (9-hole or 18-hole bucket). The splits below guarantee it — the
    worst case is n ≡ 1 (mod 4), which resolves to [4, …, 3, 3, 3];
    every other remainder needs two or fewer short groups.

    FIVESOMES (Kerry 2026-07-31): when the event allows them, `max_size`
    is 5 and the sheet is built of fivesomes with FOURSOMES as the short
    groups — "following the same relational rules that 3somes play in a
    4some setup", i.e. the remainder is absorbed by at most three groups
    one player short, never by a group of two. A field too small to
    tile that way falls back to the ordinary 4-based sheet rather than
    inventing a shape (you can't make fivesomes out of eleven players
    without a threesome, and a threesome is a 4-based idea).
    """
    if n <= 0:
        return []
    if max_size >= 5:
        if n <= 5:
            return _make_group_sizes(n, 4) if n <= 4 else [5]
        q, r = divmod(n, 5)
        if r == 0:
            return [5] * q
        # Absorb the remainder by trading `take` fivesomes for `take + 1`
        # foursomes: 5·take + r = 4·(take + 1)  ⇒  take = 4 − r. That is
        # the fewest fivesomes given up, so the sheet stays as close to
        # all-fives as the field allows (n=21 → one fivesome and four
        # foursomes, which is Kerry's "at most 1 or 2 fivesomes" case
        # falling out of the arithmetic rather than being special-cased).
        take = 4 - r
        if q - take >= 0:
            sizes = [5] * (q - take) + [4] * (take + 1)
            if sum(sizes) == n and all(s >= 2 for s in sizes):
                return sizes
        return _make_group_sizes(n, 4)     # too small to tile as fivesomes
    if n <= 4:
        return [n]
    q, r = divmod(n, 4)
    if r == 0:
        return [4] * q
    elif r == 1:
        if q == 1:  # n == 5
            return [2, 3]
        return [4] * (q - 2) + [3, 3, 3]  # e.g. 9→[3,3,3], 13→[4,3,3,3]
    elif r == 2:
        return [4] * (q - 1) + [3, 3]     # e.g. 6→[3,3], 10→[4,3,3]
    else:  # r == 3
        return [4] * q + [3]              # e.g. 7→[4,3], 11→[4,4,3]


def _arrange_group_seats(names: list[str], mp_opponents: set,
                         partner_adj: set, tee_map: dict) -> list[str]:
    """Seat order for a settled group — foursomes are already decided;
    this only decides who RIDES with whom. Carts are seats 1&2 and 3&4
    (Kerry's cart-pair ruling).

    Hard-to-soft priority (weighted, best permutation wins — Kerry
    2026-07-21: requests supersede, then similar tees share a cart):
    - Match Play opponents ride in OPPOSITE carts (weight 1000). This is
      distinct from partner locking, which keeps a pair TOGETHER.
    - Partner-request pairs share a cart (weight 100).
    - Same-tee cart-mates (weight 1) — tee compare is case/whitespace-
      insensitive so label drift can't split a tee pair.

    Groups are ≤ 4 players (24 permutations), so brute force is exact.
    """
    from itertools import permutations

    def _cart(idx: int) -> int:
        return 0 if idx < 2 else 1

    def _tee(name: str) -> str:
        return str(tee_map.get(name) or "").strip().lower()

    keys = {n: _pair_key_name(n) for n in names}
    best, best_cost = list(names), None
    for perm in permutations(names):
        cost = 0
        for i in range(len(perm)):
            for j in range(i + 1, len(perm)):
                pair = frozenset((keys[perm[i]], keys[perm[j]]))
                same_cart = _cart(i) == _cart(j)
                if pair in mp_opponents and same_cart:
                    cost += 1000
                if pair in partner_adj and not same_cart:
                    cost += 100
        for i, j in ((0, 1), (2, 3)):
            if j < len(perm):
                ta, tb = _tee(perm[i]), _tee(perm[j])
                if ta and tb and ta != tb:
                    cost += 1
        if best_cost is None or cost < best_cost:
            best, best_cost = list(perm), cost
        if best_cost == 0:
            break
    return best


def _partner_locked_names(players: list[str], partner_map: dict,
                          protect_partner_requests: bool,
                          host_units: list[list[str]] | None = None) -> set:
    """Names bound by a partner request (same unit-building rule as
    _random_groups) — the swap improver must never split these.
    Host-and-guests foursomes lock the same way."""
    locked: set = set()
    if not protect_partner_requests:
        return locked
    for hu in (host_units or []):
        unit = [n for n in hu if n in players and n not in locked]
        if len(unit) >= 2:
            locked.update(unit)
    for requester, req_text in partner_map.items():
        if requester not in players or requester in locked:
            continue
        partner = _find_partner_name(req_text, players, requester)
        if partner and partner not in locked:
            locked.add(requester)
            locked.add(partner)
    return locked


def _swap_improve(groups: list[list[str]], pair_counts: dict,
                  locked: set, max_rounds: int = 40) -> list[list[str]]:
    """Pairwise-swap hill climb: exchange two unlocked players between
    groups whenever it lowers the repeat score. Group sizes (and partner
    units) are preserved; converges quickly at league sizes."""
    improved = True
    rounds = 0
    while improved and rounds < max_rounds:
        improved = False
        rounds += 1
        for gi in range(len(groups)):
            for gj in range(gi + 1, len(groups)):
                for i, a in enumerate(groups[gi]):
                    if a in locked:
                        continue
                    for j, b in enumerate(groups[gj]):
                        if b in locked:
                            continue
                        base = (_group_score(groups[gi], pair_counts)
                                + _group_score(groups[gj], pair_counts))
                        groups[gi][i], groups[gj][j] = b, a
                        new = (_group_score(groups[gi], pair_counts)
                               + _group_score(groups[gj], pair_counts))
                        if new < base:
                            improved = True
                            a = groups[gi][i]
                        else:
                            groups[gi][i], groups[gj][j] = a, b
    return groups


def _random_groups(
    players: list[str],
    partner_map: dict,
    pair_counts: dict,
    protect_partner_requests: bool,
    fixed_units: list[list[str]] | None = None,
    host_units: list[list[str]] | None = None,
    max_group: int = 4,
) -> list[list[str]]:
    """Form groups using weighted random (history-aware) assignment.

    fixed_units: pre-built unsplittable units placed FIRST — the Match
    Play foursomes (rule 8 amendment). Members are consumed before
    partner-request pairing, so a request can never pull a player out
    of a match group ("Match Play is king"). A partner PAIR never packs
    into a Match Play group either: MP opponents take one seat in EACH
    cart, so the two leftover seats of that foursome are split across
    carts — a pair placed there could not ride together. Keeping pairs
    out lets both constraints be satisfied instead of sacrificing the
    request at seat time.

    host_units: host-and-guests foursomes (Kerry 2026-07-30 — "a member
    can bring as many guests as they want and play with up to 3").
    Placed AFTER match units (a match still wins any member) but BEFORE
    ordinary partner pairs, because the guests' requests are all aimed
    at the one host and pairing them off two-at-a-time is exactly what
    made them outrank each other. They are ordinary multi-person units,
    not match units — the mp/pair cart exclusion does not apply.
    """
    import random as _random

    used: set = set()
    units: list[list[str]] = []
    mp_unit_names: set = set()

    for fu in (fixed_units or []):
        unit = [n for n in fu if n in players and n not in used]
        if unit:
            units.append(unit)
            used.update(unit)
            mp_unit_names.update(unit)

    for hu in (host_units or []):
        unit = [n for n in hu if n in players and n not in used]
        if len(unit) >= 2:
            units.append(unit)
            used.update(unit)

    # Build partner pairs first
    if protect_partner_requests:
        for requester, req_text in partner_map.items():
            if requester not in players or requester in used:
                continue
            partner = _find_partner_name(req_text, players, requester)
            if partner and partner not in used:
                units.append([requester, partner])
                used.add(requester)
                used.add(partner)

    # Remaining singles — shuffle for randomness
    singles = [p for p in players if p not in used]
    _random.shuffle(singles)
    for s in singles:
        units.append([s])

    # Determine target group sizes to avoid onesomes
    target_sizes = _make_group_sizes(len(players), max_group)
    groups: list[list[str]] = []
    remaining = list(units)

    def _unit_kind(unit: list[str]) -> str:
        if any(n in mp_unit_names for n in unit):
            return "mp"
        return "pair" if len(unit) >= 2 else "single"

    for target in target_sizes:
        group: list[str] = []
        kinds: set = set()
        while len(group) < target and remaining:
            needed = target - len(group)

            def _ok(u):
                # mp + pair in one foursome is cart-infeasible (docstring)
                k = _unit_kind(u)
                return not ((k == "pair" and "mp" in kinds)
                            or (k == "mp" and "pair" in kinds))

            fittable = [u for u in remaining if len(u) <= needed and _ok(u)]
            if not fittable:
                fittable = [u for u in remaining if _ok(u)] or remaining
            best_idx = 0
            best_score = float("inf")
            for idx, unit in enumerate(fittable):
                score = sum(
                    _pair_cost(pair_counts, g, u)
                    for g in group
                    for u in unit
                )
                if score < best_score:
                    best_score = score
                    best_idx = idx
            chosen = fittable[best_idx]
            remaining.remove(chosen)
            group.extend(chosen)
            kinds.add(_unit_kind(chosen))
        if group:
            groups.append(group)

    # Absorb any leftover units (e.g. oversized partner pair) into the last group
    for leftover in remaining:
        if groups:
            groups[-1].extend(leftover)
        else:
            groups.append(leftover)

    return groups


FELLOWSHIP_CUP_RACE_KEY = "fellowship_cup"


def _default_pairing_race(chapter: str | None,
                          event_name: str | None = None) -> str | None:
    """The race an event's pairings order by unless told otherwise.

    A chapter event defaults to that chapter's own City NET race. Matching
    on chapter alone would be wrong: players_cup_gross is also tagged
    "San Antonio", so the NET check is what stops an SA field being paired
    off the GROSS Players Cup.

    ONLY THE TGF CHAMPIONSHIP defaults to THE FELLOWSHIP CUP (Kerry
    2026-07-30) — the combined reset standings both City NET races convert
    into. A TGF-chapter event that is NOT the championship gets no default
    at all rather than a guess; the manager picks from the pulldown.

    Note the city championships ("TGF SAN ANTONIO CHAMPIONSHIP") carry a
    CHAPTER, so the chapter rule catches them first and they correctly stay
    on their own City NET race — the name containing both "TGF" and
    "CHAMPIONSHIP" never reaches the Fellowship Cup branch.
    """
    ch = (chapter or "").strip().lower()
    for k, cfg in _GG_POINTS_RACES.items():
        if (cfg.get("contest_type") or "").upper().startswith("NET") and \
                (cfg.get("chapter") or "").strip().lower() == ch and ch:
            return k
    if ch in ("tgf", "national", "tgf-wide") and \
            "champ" in (event_name or "").lower():
        return FELLOWSHIP_CUP_RACE_KEY
    return None


def pairing_race_options(chapter: str | None = None,
                         event_name: str | None = None) -> list:
    """Season-contest standings a manager can order pairings by.

    Every configured race plus THE FELLOWSHIP CUP, with the chapter's
    default flagged. Offered as a CHOICE rather than inferred, because the
    right race is not always the chapter's own — the TGF Championship uses
    the Fellowship Cup.
    """
    default = _default_pairing_race(chapter, event_name)
    out = []
    for k, cfg in _GG_POINTS_RACES.items():
        out.append({
            "race_key": k,
            "label": cfg.get("label") or k,
            "chapter": cfg.get("chapter"),
            "contest_type": cfg.get("contest_type"),
            "is_default": k == default,
        })
    out.append({
        "race_key": FELLOWSHIP_CUP_RACE_KEY,
        "label": "THE FELLOWSHIP CUP",
        "chapter": "TGF",
        "contest_type": "NET (combined reset)",
        "is_default": default == FELLOWSHIP_CUP_RACE_KEY,
    })
    # Default first, then chapter races, then the rest.
    out.sort(key=lambda r: (not r["is_default"], r["label"] or ""))
    return out


# Standings older than this are re-pulled from GG when pairings are being
# generated (Kerry 2026-07-30). Point-of-use refresh rather than a
# session-start or event-driven one: pairings lock when an event tees off,
# so the ONLY moment the numbers must be current is the moment you press
# Generate — including day 2 of a two-day event, where the second day's
# order comes off standings updated by day 1. Short enough that yesterday's
# snapshot never survives; long enough that hitting Generate repeatedly to
# reshuffle reuses one fetch instead of hammering GG.
_STANDINGS_PAIRING_MAX_AGE_HOURS = 0.25


def _parse_gg_rank(value) -> int | None:
    """'T8' → 8, '8' → 8, 8 → 8; None/blank/junk → None.

    Golf Genius marks TIES with a leading 'T' ("T8" = tied for 8th).
    Feeding that straight to int() raised ValueError and took the whole
    Generate down with 'invalid literal for int() with base 10: T8'
    (Kerry 2026-07-31). Ties are real and common, so the parser keeps the
    shared position rather than inventing an order — the tiebreak is
    applied later, where the handicap is known.
    """
    if value is None:
        return None
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        try:
            return int(value)
        except (ValueError, TypeError):
            return None
    m = re.search(r"\d+", str(value))
    return int(m.group()) if m else None


def _standings_rank_map(chapter: str | None, race_key: str | None = None,
                        max_age_hours: float = _STANDINGS_PAIRING_MAX_AGE_HOURS,
                        event_name: str | None = None,
                        db_path=None,
                        _with_meta: bool = False) -> tuple:
    """{lowercase player name: finishing position} for a chapter's points race.

    Position 1 is the LEADER. Returns (rank_map, race_key_used, notes).

    Refreshes from GG when the snapshot is older than `max_age_hours`. If GG
    is unreachable the underlying call falls back to the stale snapshot — and
    that fact is surfaced in the notes rather than swallowed, because pairing
    a field off yesterday's standings while believing they are current is
    exactly the failure this refresh exists to prevent.
    """
    notes = []
    key = race_key or _default_pairing_race(chapter, event_name)
    if not key:
        notes.append(f"No points race found for chapter '{chapter}' — "
                     f"pairings fell back to random order.")
        return (({}, None, notes, {"points": {}, "enrolled": {}})
                if _with_meta else ({}, None, notes))
    try:
        if key == FELLOWSHIP_CUP_RACE_KEY:
            # TGF-wide combined reset standings — the TGF Championship is
            # paired off this rather than either chapter's City NET race
            # (Kerry 2026-07-30).
            data = get_fellowship_cup_projection(db_path=db_path)
        else:
            data = get_points_race_standings(
                key, auto_refresh_hours=max_age_hours, db_path=db_path)
    except Exception as e:
        notes.append(f"Could not read the {key} standings ({e}) — "
                     f"pairings fell back to random order.")
        return (({}, key, notes, {"points": {}, "enrolled": {}})
                if _with_meta else ({}, key, notes))
    # KEYED BY customer_id FIRST (guiding principle 6). Standings rows come
    # from the GG portal, where names are "LAST, First" — a plain lowercased
    # name key matched ZERO of the 32 SA Championship players (Kerry
    # 2026-07-31), so every one of them was treated as unranked and the
    # field came out in random order. The snapshot rows already carry
    # customer_id, and so does the roster; the name keys below are only a
    # fallback for a standings row that never resolved to a profile.
    rank_map: dict = {}
    # Points and buy-in status ride alongside the positions, keyed the
    # same way, so the PAIRINGS tab can show WHY a player is where they
    # are and whether they are actually IN the race (Kerry 2026-07-31:
    # "add a column for those points" / colour-code who's in and who's
    # not, the same way Player Rankings does).
    points_map: dict = {}
    enrolled_map: dict = {}
    for i, r in enumerate(data.get("standings") or []):
        pos = _parse_gg_rank(r.get("position") or r.get("rank")) or (i + 1)
        pts = r.get("total_points")
        enr = bool(r.get("enrolled"))
        cid = r.get("customer_id")
        if cid:
            rank_map.setdefault(int(cid), pos)
            enrolled_map.setdefault(int(cid), enr)
            if pts is not None:
                points_map.setdefault(int(cid), pts)
        raw = r.get("player_name") or ""
        # Both the raw portal spelling and the "First Last" candidates it
        # implies, so a roster row with no customer_id can still match.
        for nm in [raw, *_gg_name_candidates(raw)]:
            k = _pair_key_name(nm)
            if k:
                rank_map.setdefault(k, pos)
                enrolled_map.setdefault(k, enr)
                if pts is not None:
                    points_map.setdefault(k, pts)
    if not rank_map:
        notes.append(f"The {key} standings are empty — pairings fell back "
                     f"to random order.")
    # Say how current the numbers actually are. A silent stale-fallback is
    # the one outcome that would let a manager pair off yesterday's order
    # believing it was today's.
    if data.get("gg_error"):
        notes.append(
            f"WARNING: Golf Genius could not be reached ({data['gg_error']}) "
            f"— these standings are the last saved snapshot"
            + (f" from {data.get('fetched_at')}" if data.get("fetched_at") else "")
            + ". Check them before saving these pairings.")
    elif data.get("fetched_at"):
        notes.append(f"Standings as of {data['fetched_at']}.")
    if _with_meta:
        return rank_map, key, notes, {"points": points_map,
                                      "enrolled": enrolled_map}
    return rank_map, key, notes


def _standings_groups(players: list[str], rank_map: dict, partner_map: dict,
                      protect_partner_requests: bool,
                      host_units: list[list[str]] | None = None,
                      id_map: dict | None = None,
                      hcp_map: dict | None = None,
                      max_group: int = 4
                      ) -> tuple[list, list]:
    """Group by points-race standing with the LEADERS GOING OFF LAST (PGA
    order), while still honoring partner requests.

    Kerry 2026-07-30: "I want the leaders paired last just like in the PGA.
    However, I still want to honor Player Requests for this one. Order
    should just pick up after their requests are accounted for."

    So requests are resolved FIRST into units, then units are ordered by
    their BEST-ranked member. A unit takes the position of its strongest
    player, which is what keeps a leader in the last group even when their
    requested partner is unranked — ordering by the weaker member would
    quietly drag the leader to an early tee time.

    Unranked players (no standing: guests, first timers, non-enrolled) go
    off EARLIEST, since "leaders last" makes the front of the field the
    place for everyone outside the race.
    """
    notes = []
    if not players:
        return [], notes

    # 1. Units — a partner request binds two players into one unit.
    #    A host-and-guests foursome is built FIRST so the guests aren't
    #    paired off two-at-a-time (Kerry 2026-07-30); the unit then takes
    #    the host's standing position, same as any other unit.
    placed, units = set(), []
    if protect_partner_requests:
        for hu in (host_units or []):
            unit = [n for n in hu if n in players and n not in placed]
            if len(unit) >= 2:
                units.append(unit)
                placed.update(unit)
        for requester, req_text in partner_map.items():
            if requester not in players or requester in placed:
                continue
            partner = _find_partner_name(req_text, players, requester)
            if partner and partner not in placed:
                units.append([requester, partner])
                placed.add(requester)
                placed.add(partner)
    units.extend([p] for p in players if p not in placed)

    # 2. Order units by their BEST rank; leaders last, unranked first.
    UNRANKED = 10 ** 6
    ids = {_pair_key_name(k): v for k, v in (id_map or {}).items() if v}

    def player_rank(n):
        """customer_id first, name only as a fallback (principle 6)."""
        cid = ids.get(_pair_key_name(n))
        if cid is not None:
            pos = rank_map.get(int(cid))
            if pos is not None:
                return pos
        return rank_map.get(_pair_key_name(n), UNRANKED)

    # TIES (Kerry 2026-07-31). GG shares a position between tied players
    # ("T8"), so the standing alone can't order them. Tiebreak: LOWER
    # HANDICAP is treated as the better position, then alphabetical by
    # LAST name. Unknown handicaps sort last within a tie rather than
    # jumping ahead of a known-good one.
    _h = {(k or "").lower(): v for k, v in (hcp_map or {}).items()}

    def _hcp(n):
        v = _h.get((n or "").lower())
        return float(v) if v is not None else 99.0

    def _surname(n):
        parts = (n or "").strip().split()
        return (parts[-1].lower() if parts else "", (n or "").lower())

    def player_key(n):
        return (player_rank(n), _hcp(n), _surname(n))

    def best_rank(unit):
        return min((player_rank(n) for n in unit), default=UNRANKED)

    # LEADER FIRST in unit order, because the sheet is FILLED FROM THE
    # BACK below. A unit takes the FULL key of its strongest member, so a
    # tie inside the standings is broken the same way for a pair as for a
    # single.
    units.sort(key=lambda u: min((player_key(n) for n in u),
                                 default=(UNRANKED, 99.0, ("", ""))))

    # 3. Fill from the LAST group backwards. "Leaders go off last" is the
    #    rule, so the leader's unit is placed first, into the final group
    #    — that makes leaders-last exact instead of merely likely.
    #
    #    Filling forwards (as this did) made two failures possible on the
    #    SA Championship's 32-player field, which divides evenly into 8
    #    foursomes: a cursor that advanced whenever a unit didn't fit
    #    permanently skipped groups that still had room, so tail units
    #    "matched no slot" and were dumped into the smallest group (Wade
    #    Fieber and Will Peterson, Kerry 2026-07-31); and backfilling
    #    those holes then pulled the LEADER forward off the last tee
    #    time. Filling backwards puts every hole at the FRONT of the
    #    sheet, among the unranked players, where slop costs nothing.
    #
    #    Short groups still sit earliest (sizes ascending), so the
    #    leaders finish in a full foursome as they would on tour.
    n = len(players)
    sizes = sorted(_make_group_sizes(n, max_group))
    groups = [[] for _ in sizes]
    gi = len(sizes) - 1
    for unit in units:
        while gi >= 0 and len(groups[gi]) >= sizes[gi]:
            gi -= 1
        target = next((i for i in range(gi, -1, -1)
                       if len(groups[i]) + len(unit) <= sizes[i]), None)
        if target is None:
            # Genuinely nowhere left — put them in the emptiest group
            # rather than losing the player, and say so.
            target = min(range(len(groups)), key=lambda i: len(groups[i]))
            notes.append(f"{' + '.join(unit)}: no slot matched the standings "
                         f"order — placed in the smallest available group.")
        groups[target].extend(unit)
    groups = [g for g in groups if g]

    unranked = [p for p in players if player_rank(p) >= UNRANKED]
    ranked = len(players) - len(unranked)
    notes.append(f"Ordered by points-race standing — leaders go off LAST. "
                 f"{ranked} of {len(players)} players are in the standings; "
                 f"the rest tee off earliest.")
    # A total miss means the standings and the roster aren't being matched
    # at all, not that nobody is enrolled — the SA Championship shipped a
    # 0-of-32 "ordered by standings" that was really random order (Kerry
    # 2026-07-31). Say so loudly, and name names when it's partial so the
    # mismatch is diagnosable instead of a silent shrug.
    if ranked == 0 and players:
        notes.append("WARNING: NONE of the field matched the standings, so "
                     "this is not a standings order at all — every player "
                     "was treated as unranked. Check that the race is the "
                     "right one and that these players are enrolled in it.")
    elif unranked:
        shown = ", ".join(sorted(unranked)[:6])
        more = f" +{len(unranked) - 6} more" if len(unranked) > 6 else ""
        notes.append(f"Not in the standings (teeing off earliest): "
                     f"{shown}{more}.")
    return groups, notes


def _abcd_groups(players: list[str], hcp_map: dict,
                 max_group: int = 4) -> list[list[str]]:
    """Form ABCD groups: one A/B/C/D tier player per group, sorted by handicap."""
    if not players:
        return []

    # Sort by handicap index ascending (lower = better = A)
    with_hcp = sorted(
        [(p, hcp_map.get(p.lower())) for p in players if hcp_map.get(p.lower()) is not None],
        key=lambda x: x[1],
    )
    without_hcp = [(p, None) for p in players if hcp_map.get(p.lower()) is None]
    sorted_players = [p for p, _ in with_hcp] + [p for p, _ in without_hcp]

    n = len(sorted_players)
    if n == 0:
        return []

    group_sizes = _make_group_sizes(n, max_group)
    num_groups = len(group_sizes)

    if num_groups == 0:
        return []

    # Distribute round-robin: player i goes to group (i % num_groups)
    # Result: each group gets one player from each tier (A/B/C/D), last tier may be short
    groups: list[list[str]] = [[] for _ in range(num_groups)]
    for i, player in enumerate(sorted_players):
        groups[i % num_groups].append(player)

    return groups


# ============================================================================
# Duplicate Detective
# ----------------------------------------------------------------------------
# Detection layer for the /admin/duplicate-detective admin tool. Identifies
# acct_transactions rows that represent the same financial event recorded by
# multiple writers (Venmo CSV import, Venmo email parser via exp-promoted-N,
# in-app refund/credit-payout operations). Returns a candidate list that the
# UI surfaces; merging and reversing live in separate functions added in
# later commits.
#
# See docs/claude/duplicate-detective.md for the full specification.
# ============================================================================

import hashlib as _dd_hashlib
import re as _dd_re


_DUP_PROMOTED_PREFIXES = ("exp-promoted-",)
_DUP_INAPP_PREFIXES = ("credit-payout-", "refund-flat-", "wd-credit-payout-")
_DUP_GODADDY_PREFIXES = ("godaddy-order-",)


def _dd_normalize_name(value) -> str:
    """Lowercase, strip punctuation/digits, collapse whitespace. Returns ''
    when there is nothing usable to match on."""
    if not value:
        return ""
    s = str(value).lower()
    s = _dd_re.sub(r"[^a-z\s]+", " ", s)
    s = _dd_re.sub(r"\s+", " ", s).strip()
    return s


def _dd_names_overlap(a, b) -> bool:
    """True when two free-form name/description fields likely refer to the
    same person. Match rules (any one wins):
      1. Either normalized string is a substring of the other (after both
         are reduced to at least 3 chars).
      2. They share at least 2 word tokens of length >= 3.
      3. The last token of one appears as a token in the other AND that
         token is at least 4 chars (catches "Todd McConahy" vs
         "McConahy: $93.06" style descriptions).
    """
    na, nb = _dd_normalize_name(a), _dd_normalize_name(b)
    if not na or not nb:
        return False
    if len(na) >= 3 and len(nb) >= 3 and (na in nb or nb in na):
        return True
    ta = [t for t in na.split() if len(t) >= 3]
    tb = [t for t in nb.split() if len(t) >= 3]
    shared = set(ta) & set(tb)
    if len(shared) >= 2:
        return True
    if ta and tb:
        if len(ta[-1]) >= 4 and ta[-1] in tb:
            return True
        if len(tb[-1]) >= 4 and tb[-1] in ta:
            return True
    return False


def _dd_source_ref_starts_with(source_ref, prefixes) -> bool:
    if not source_ref:
        return False
    return any(source_ref.startswith(p) for p in prefixes)


def _dd_is_venmo_csv(row) -> bool:
    """Venmo CSV import: source starts with 'venmo' AND source_ref is not the
    exp-promoted pattern (which is the email parser, not the CSV)."""
    source = (row["source"] or "").lower()
    if not source.startswith("venmo"):
        return False
    sref = row["source_ref"] or ""
    if _dd_source_ref_starts_with(sref, _DUP_PROMOTED_PREFIXES):
        return False
    return True


def _dd_classify_pattern(row_a, row_b):
    """Return (pattern_letter, base_confidence, customer_match_kind) or
    (None, 0.0, None) if the pair does not match any pattern.

    customer_match_kind is 'id' for customer_id match, 'name' for normalized
    name match, '' for amount/date-only (Pattern D).
    """
    sref_a = row_a["source_ref"] or ""
    sref_b = row_b["source_ref"] or ""

    a_promoted = _dd_source_ref_starts_with(sref_a, _DUP_PROMOTED_PREFIXES)
    b_promoted = _dd_source_ref_starts_with(sref_b, _DUP_PROMOTED_PREFIXES)
    a_inapp = _dd_source_ref_starts_with(sref_a, _DUP_INAPP_PREFIXES)
    b_inapp = _dd_source_ref_starts_with(sref_b, _DUP_INAPP_PREFIXES)
    a_venmo = _dd_is_venmo_csv(row_a)
    b_venmo = _dd_is_venmo_csv(row_b)

    cust_a = row_a["customer_id"] if "customer_id" in row_a.keys() else None
    cust_b = row_b["customer_id"] if "customer_id" in row_b.keys() else None
    same_cid = cust_a is not None and cust_b is not None and cust_a == cust_b

    name_a = row_a["customer"] or row_a["description"]
    name_b = row_b["customer"] or row_b["description"]
    same_name = _dd_names_overlap(name_a, name_b)

    def _customer_match_kind():
        if same_cid:
            return "id"
        if same_name:
            return "name"
        return None

    # Pattern A — Venmo CSV vs exp-promoted (email parser → expense)
    if (a_venmo and b_promoted) or (b_venmo and a_promoted):
        kind = _customer_match_kind()
        if kind:
            return "A", 0.95 if kind == "id" else 0.85, kind

    # Pattern B — in-app refund/credit/wd-credit vs exp-promoted
    if (a_inapp and b_promoted) or (b_inapp and a_promoted):
        kind = _customer_match_kind()
        if kind:
            return "B", 0.95 if kind == "id" else 0.85, kind

    # Pattern C — in-app refund/credit vs Venmo CSV
    if (a_inapp and b_venmo) or (b_inapp and a_venmo):
        kind = _customer_match_kind()
        if kind:
            return "C", 0.95 if kind == "id" else 0.85, kind

    # Pattern D — manual fallback: same customer_id, different source_ref,
    # not already covered above
    if same_cid and sref_a != sref_b:
        return "D", 0.65, "id"

    return None, 0.0, None


def _dd_select_survivor(row_a, row_b):
    """Survivor selection rule (highest priority kept). Returns (survivor_row,
    merged_row, rationale_str). Tie-breaks by older id."""
    def priority(row):
        sref = row["source_ref"] or ""
        source = (row["source"] or "").lower()
        # 1. Venmo CSV bank truth (highest)
        if source.startswith("venmo") and not _dd_source_ref_starts_with(
            sref, _DUP_PROMOTED_PREFIXES
        ):
            return 1
        # 2. GoDaddy order detail
        if _dd_source_ref_starts_with(sref, _DUP_GODADDY_PREFIXES):
            return 2
        # 3. In-app operation (has user context)
        if _dd_source_ref_starts_with(sref, _DUP_INAPP_PREFIXES):
            return 3
        # 4. Email parser exp-promoted (least specific)
        if _dd_source_ref_starts_with(sref, _DUP_PROMOTED_PREFIXES):
            return 4
        return 5  # everything else — lowest preference

    pa, pb = priority(row_a), priority(row_b)
    labels = {
        1: "Venmo CSV (bank truth)",
        2: "GoDaddy order detail",
        3: "in-app operation",
        4: "email parser exp-promoted",
        5: "other source",
    }
    if pa < pb:
        return row_a, row_b, f"keep {labels[pa]} over {labels[pb]}"
    if pb < pa:
        return row_b, row_a, f"keep {labels[pb]} over {labels[pa]}"
    # Equal priority — keep the older id (stable, deterministic)
    if row_a["id"] <= row_b["id"]:
        return row_a, row_b, f"equal priority ({labels[pa]}); kept older id"
    return row_b, row_a, f"equal priority ({labels[pa]}); kept older id"


def _dd_candidate_id(id_a: int, id_b: int) -> str:
    """Deterministic candidate id = sha1 of sorted id pair."""
    lo, hi = sorted((int(id_a), int(id_b)))
    return _dd_hashlib.sha1(f"{lo}:{hi}".encode("utf-8")).hexdigest()[:16]


def _dd_date_delta_days(date_a: str, date_b: str) -> int | None:
    """Absolute day delta between two ISO date strings. None on parse error."""
    from datetime import datetime
    fmts = ("%Y-%m-%d", "%Y-%m-%dT%H:%M:%S", "%Y-%m-%d %H:%M:%S")
    def _parse(s):
        if not s:
            return None
        s = str(s)[:19]
        for f in fmts:
            try:
                return datetime.strptime(s, f)
            except ValueError:
                continue
        try:
            return datetime.strptime(s[:10], "%Y-%m-%d")
        except ValueError:
            return None
    da, db = _parse(date_a), _parse(date_b)
    if not da or not db:
        return None
    return abs((da - db).days)


def _dd_check_fk_warnings(conn, survivor_id: int, merged_id: int) -> list[str]:
    """Return a list of human-readable FK warning strings for a candidate
    pair. Empty list means the merge is safe to auto-process.

    HARD ERROR: survivor and merged both have reconciliation_matches to
    DIFFERENT bank_deposits — auto-merge must refuse.
    """
    warnings = []
    s_match = conn.execute(
        "SELECT bank_deposit_id FROM reconciliation_matches "
        "WHERE acct_transaction_id = ?",
        (survivor_id,),
    ).fetchone()
    m_match = conn.execute(
        "SELECT bank_deposit_id FROM reconciliation_matches "
        "WHERE acct_transaction_id = ?",
        (merged_id,),
    ).fetchone()
    if s_match and m_match and s_match[0] != m_match[0]:
        warnings.append(
            f"HARD ERROR: survivor txn {survivor_id} is matched to bank "
            f"deposit {s_match[0]} and merged txn {merged_id} is matched "
            f"to bank deposit {m_match[0]} — manual review required"
        )
    return warnings


def find_duplicate_candidates(
    db_path=None,
    *,
    min_confidence: float = 0.0,
    pattern_filter=None,
    include_dismissed: bool = False,
) -> list[dict]:
    """Scan acct_transactions for probable duplicate pairs.

    Returns a deterministic list of candidate dicts (ordered by descending
    confidence, then ascending pair id) ready for the Duplicate Detective UI.
    See docs/claude/duplicate-detective.md for full pattern + scoring rules.
    """
    out: list[dict] = []
    seen_pairs: set[tuple[int, int]] = set()

    with _connect(db_path) as conn:
        dismissed: set[tuple[int, int]] = set()
        if not include_dismissed:
            for r in conn.execute(
                "SELECT txn_a_id, txn_b_id FROM duplicate_dismissed_pairs"
            ).fetchall():
                lo, hi = sorted((int(r["txn_a_id"]), int(r["txn_b_id"])))
                dismissed.add((lo, hi))

        # Narrow with SQL: active rows, expense or income only (skip transfers).
        rows = conn.execute(
            """
            SELECT id, date, description, total_amount, type, amount,
                   entry_type, customer, customer_id, event_name, category,
                   account_id, source, source_ref, account,
                   COALESCE(status, 'active') AS status
            FROM acct_transactions
            WHERE COALESCE(status, 'active') = 'active'
              AND COALESCE(entry_type, type) IN ('income', 'expense')
            ORDER BY id
            """
        ).fetchall()

        # Bucket by entry_type + rounded amount so we only compare candidates
        # that can possibly be a pair.
        from collections import defaultdict
        buckets = defaultdict(list)
        for r in rows:
            et = (r["entry_type"] or r["type"] or "").lower()
            amt = r["amount"] if r["amount"] is not None else r["total_amount"]
            if amt is None or et not in ("income", "expense"):
                continue
            # Round to nearest cent so within-0.01 pairs share a bucket
            key = (et, round(float(amt), 2))
            buckets[key].append(r)
            # Also place into ±$0.01 neighbor buckets to absorb precision drift
            buckets[(et, round(float(amt) + 0.01, 2))].append(r)
            buckets[(et, round(float(amt) - 0.01, 2))].append(r)

        # Deduplicate bucket contents (the ±0.01 trick can list the same row
        # multiple times)
        unique_buckets = {}
        for key, lst in buckets.items():
            seen_ids = set()
            uniq = []
            for r in lst:
                if r["id"] in seen_ids:
                    continue
                seen_ids.add(r["id"])
                uniq.append(r)
            unique_buckets[key] = uniq

        for bucket in unique_buckets.values():
            if len(bucket) < 2:
                continue
            for i in range(len(bucket)):
                for j in range(i + 1, len(bucket)):
                    a, b = bucket[i], bucket[j]
                    if a["id"] == b["id"]:
                        continue
                    # Amount within $0.01
                    amt_a = a["amount"] if a["amount"] is not None else a["total_amount"]
                    amt_b = b["amount"] if b["amount"] is not None else b["total_amount"]
                    if amt_a is None or amt_b is None:
                        continue
                    amt_delta = abs(float(amt_a) - float(amt_b))
                    if amt_delta > 0.01 + 1e-9:
                        continue
                    # Dates within 7 days
                    day_delta = _dd_date_delta_days(a["date"], b["date"])
                    if day_delta is None or day_delta > 7:
                        continue
                    # Pair already seen via the ±0.01 trick?
                    lo, hi = sorted((int(a["id"]), int(b["id"])))
                    if (lo, hi) in seen_pairs:
                        continue
                    seen_pairs.add((lo, hi))
                    # Dismissed?
                    if (lo, hi) in dismissed:
                        continue
                    pattern, conf, match_kind = _dd_classify_pattern(a, b)
                    if not pattern:
                        continue

                    # Scoring adjustments
                    if day_delta > 3:
                        conf -= 0.10
                    if amt_delta > 0.001:
                        conf -= 0.10

                    survivor, merged, surv_rationale = _dd_select_survivor(a, b)
                    fk_warnings = _dd_check_fk_warnings(
                        conn, survivor["id"], merged["id"]
                    )
                    if fk_warnings:
                        conf -= 0.20
                    conf = max(0.0, min(1.0, round(conf, 4)))

                    if conf < min_confidence:
                        continue
                    if pattern_filter and pattern not in pattern_filter:
                        continue

                    # variance_impact: the merged row's signed effect on the
                    # ledger that will be removed. Positive number = book
                    # balance drops by this much when merged.
                    merged_amt = (
                        merged["amount"]
                        if merged["amount"] is not None
                        else merged["total_amount"]
                    )
                    merged_type = (merged["entry_type"] or merged["type"] or "").lower()
                    variance = float(merged_amt or 0)
                    if merged_type == "income":
                        variance = -variance

                    rationale_bits = [
                        f"Pattern {pattern}",
                        f"customer match: {match_kind}",
                        f"date delta {day_delta}d",
                        f"amount delta ${amt_delta:.2f}",
                        surv_rationale,
                    ]

                    out.append({
                        "candidate_id": _dd_candidate_id(a["id"], b["id"]),
                        "txn_a": dict(a),
                        "txn_b": dict(b),
                        "pattern": pattern,
                        "confidence": conf,
                        "suggested_survivor_id": survivor["id"],
                        "suggested_merged_id": merged["id"],
                        "rationale": "; ".join(rationale_bits),
                        "fk_warnings": fk_warnings,
                        "variance_impact": round(variance, 2),
                        "match_kind": match_kind,
                        "date_delta_days": day_delta,
                        "amount_delta": round(amt_delta, 4),
                    })

    # Deterministic ordering: by confidence desc, then by sorted pair id asc
    out.sort(
        key=lambda c: (
            -c["confidence"],
            min(c["suggested_survivor_id"], c["suggested_merged_id"]),
            max(c["suggested_survivor_id"], c["suggested_merged_id"]),
        )
    )
    return out


def get_duplicate_detective_mode(db_path=None) -> str:
    """Read the current mode from app_settings; default 'dry_run_only'."""
    with _connect(db_path) as conn:
        row = conn.execute(
            "SELECT value FROM app_settings WHERE key = 'duplicate_detective_mode'"
        ).fetchone()
    if not row:
        return "dry_run_only"
    val = (row["value"] or "").strip()
    if val not in ("dry_run_only", "auto_high_confidence", "review_each"):
        return "dry_run_only"
    return val


def set_duplicate_detective_mode(mode: str, db_path=None) -> str:
    """Persist the mode flag. Returns the value actually written."""
    if mode not in ("dry_run_only", "auto_high_confidence", "review_each"):
        raise ValueError(f"Invalid duplicate_detective_mode: {mode!r}")
    with _connect(db_path) as conn:
        conn.execute(
            "INSERT INTO app_settings (key, value, updated_at) "
            "VALUES ('duplicate_detective_mode', ?, datetime('now')) "
            "ON CONFLICT(key) DO UPDATE SET "
            "  value = excluded.value, updated_at = excluded.updated_at",
            (mode,),
        )
        conn.commit()
    return mode


def dismiss_duplicate_pair(
    txn_a_id: int, txn_b_id: int, reason: str = "", db_path=None
) -> bool:
    """Record a pair as dismissed so it is skipped on subsequent scans.
    Returns True if a new row was inserted, False if the pair was already
    dismissed."""
    lo, hi = sorted((int(txn_a_id), int(txn_b_id)))
    with _connect(db_path) as conn:
        try:
            conn.execute(
                "INSERT INTO duplicate_dismissed_pairs "
                "(txn_a_id, txn_b_id, reason) VALUES (?, ?, ?)",
                (lo, hi, reason or None),
            )
            conn.commit()
            return True
        except sqlite3.IntegrityError:
            return False


class DuplicateMergeError(Exception):
    """Raised when a duplicate-detective merge cannot proceed safely. The
    caller should surface the message to the operator; nothing has been
    written to the DB."""


def merge_duplicate_pair(
    surviving_txn_id: int,
    merged_txn_id: int,
    *,
    confidence: float | None = None,
    reason: str = "",
    merged_by: str = "kerry",
    allow_fk_hard_error: bool = False,
    db_path=None,
) -> dict:
    """Execute a duplicate merge inside a single transaction.

    Steps (all-or-nothing — any failure rolls back):
      1. Validate both rows exist and are 'active'.
      2. Check FK warnings; HARD ERROR refuses unless allow_fk_hard_error=True.
      3. INSERT audit row capturing survivor + merged ids, reason, confidence.
      4. Re-point reconciliation_matches.acct_transaction_id to survivor;
         on UNIQUE(bank_deposit_id, acct_transaction_id) conflict, DELETE
         the merged-side row and record the deletion in audit.notes.
      5. Re-point acct_allocations.acct_transaction_id to survivor.
      6. Re-point expense_transactions.acct_transaction_id to survivor.
      7. UPDATE acct_transactions SET status='merged', merged_into_id=survivor
         on the merged row.

    Re-running with the same pair is a no-op (returns the existing audit
    row) — the merged row will already have status='merged'.

    Returns a dict describing what changed:
      {
        "audit_id": int,
        "surviving_txn_id": int,
        "merged_txn_id": int,
        "fk_repointed": {"recon": int, "allocations": int, "expense_txns": int},
        "recon_match_deleted": list[int],
        "noop": bool,
      }
    """
    if int(surviving_txn_id) == int(merged_txn_id):
        raise DuplicateMergeError(
            f"surviving and merged txn ids are identical ({surviving_txn_id})"
        )

    with _connect(db_path) as conn:
        cur = conn.cursor()

        survivor = cur.execute(
            "SELECT id, COALESCE(status, 'active') AS status FROM acct_transactions "
            "WHERE id = ?",
            (int(surviving_txn_id),),
        ).fetchone()
        merged = cur.execute(
            "SELECT id, COALESCE(status, 'active') AS status, merged_into_id "
            "FROM acct_transactions WHERE id = ?",
            (int(merged_txn_id),),
        ).fetchone()
        if not survivor:
            raise DuplicateMergeError(
                f"surviving_txn_id {surviving_txn_id} does not exist"
            )
        if not merged:
            raise DuplicateMergeError(
                f"merged_txn_id {merged_txn_id} does not exist"
            )

        # Idempotency: if merged row is already 'merged' and points at the
        # same survivor, return the existing audit row unchanged.
        if merged["status"] == "merged" and merged["merged_into_id"] == survivor["id"]:
            existing = cur.execute(
                "SELECT id FROM duplicate_merge_audit "
                "WHERE merged_txn_id = ? AND surviving_txn_id = ? "
                "AND reversed_at IS NULL ORDER BY id DESC LIMIT 1",
                (int(merged_txn_id), int(surviving_txn_id)),
            ).fetchone()
            return {
                "audit_id": existing["id"] if existing else None,
                "surviving_txn_id": int(surviving_txn_id),
                "merged_txn_id": int(merged_txn_id),
                "fk_repointed": {"recon": 0, "allocations": 0, "expense_txns": 0},
                "recon_match_deleted": [],
                "noop": True,
            }

        if survivor["status"] != "active":
            raise DuplicateMergeError(
                f"surviving txn {survivor['id']} is not active "
                f"(status={survivor['status']!r})"
            )
        if merged["status"] != "active":
            raise DuplicateMergeError(
                f"merged txn {merged['id']} is not active "
                f"(status={merged['status']!r})"
            )

        # FK warning check — HARD ERROR blocks unless caller opts in
        fk_warnings = _dd_check_fk_warnings(conn, survivor["id"], merged["id"])
        if fk_warnings and not allow_fk_hard_error:
            raise DuplicateMergeError(
                "FK warning blocks auto-merge — pass allow_fk_hard_error=True "
                "to override: " + " | ".join(fk_warnings)
            )

        notes_extras: list[str] = []
        if fk_warnings:
            notes_extras.append("HARD ERROR override: " + " | ".join(fk_warnings))

        try:
            cur.execute("BEGIN")

            cur.execute(
                "INSERT INTO duplicate_merge_audit "
                "(surviving_txn_id, merged_txn_id, merge_reason, "
                " confidence_score, merged_by, notes) "
                "VALUES (?, ?, ?, ?, ?, ?)",
                (
                    int(surviving_txn_id),
                    int(merged_txn_id),
                    reason or None,
                    confidence,
                    merged_by,
                    None,  # filled in at COMMIT after we know what changed
                ),
            )
            audit_id = cur.lastrowid

            recon_deleted: list[int] = []
            recon_repointed = 0
            # Re-point reconciliation_matches; handle UNIQUE conflict by
            # deleting the merged-side match row and logging the bank_deposit_id.
            merged_matches = cur.execute(
                "SELECT id, bank_deposit_id FROM reconciliation_matches "
                "WHERE acct_transaction_id = ?",
                (int(merged_txn_id),),
            ).fetchall()
            for m in merged_matches:
                dup = cur.execute(
                    "SELECT id FROM reconciliation_matches "
                    "WHERE bank_deposit_id = ? AND acct_transaction_id = ?",
                    (m["bank_deposit_id"], int(surviving_txn_id)),
                ).fetchone()
                if dup:
                    cur.execute(
                        "DELETE FROM reconciliation_matches WHERE id = ?",
                        (m["id"],),
                    )
                    recon_deleted.append(m["bank_deposit_id"])
                    notes_extras.append(
                        f"deleted duplicate reconciliation_match id={m['id']} "
                        f"(survivor already matched bank_deposit {m['bank_deposit_id']})"
                    )
                else:
                    cur.execute(
                        "UPDATE reconciliation_matches SET acct_transaction_id = ? "
                        "WHERE id = ?",
                        (int(surviving_txn_id), m["id"]),
                    )
                    recon_repointed += 1

            alloc_repointed = cur.execute(
                "UPDATE acct_allocations SET acct_transaction_id = ? "
                "WHERE acct_transaction_id = ?",
                (int(surviving_txn_id), int(merged_txn_id)),
            ).rowcount or 0

            exp_repointed = cur.execute(
                "UPDATE expense_transactions SET acct_transaction_id = ? "
                "WHERE acct_transaction_id = ?",
                (int(surviving_txn_id), int(merged_txn_id)),
            ).rowcount or 0

            cur.execute(
                "UPDATE acct_transactions "
                "SET status = 'merged', merged_into_id = ?, "
                "    updated_at = datetime('now') "
                "WHERE id = ?",
                (int(surviving_txn_id), int(merged_txn_id)),
            )

            # Patch the audit row's notes now that we know the full picture.
            if notes_extras:
                cur.execute(
                    "UPDATE duplicate_merge_audit SET notes = ? WHERE id = ?",
                    (" ; ".join(notes_extras), audit_id),
                )

            conn.commit()
        except Exception as e:
            try:
                conn.rollback()
            except Exception:
                pass
            raise DuplicateMergeError(f"merge failed; rolled back: {e}") from e

        return {
            "audit_id": audit_id,
            "surviving_txn_id": int(surviving_txn_id),
            "merged_txn_id": int(merged_txn_id),
            "fk_repointed": {
                "recon": recon_repointed,
                "allocations": alloc_repointed,
                "expense_txns": exp_repointed,
            },
            "recon_match_deleted": recon_deleted,
            "noop": False,
        }


def reverse_duplicate_merge(
    audit_id: int, *, reversed_by: str = "kerry", db_path=None
) -> dict:
    """Undo a prior merge.

    Restores the merged row to status='active' and clears merged_into_id;
    stamps reversed_at on the audit row. FK re-points performed during the
    original merge are NOT automatically restored — there's no record of
    which rows previously pointed at the merged txn. The audit row's notes
    field records this caveat so the operator can re-point allocations or
    reconciliation matches manually if needed.

    Idempotent: re-reversing an already-reversed audit row raises
    DuplicateMergeError so the caller can flag the click as a no-op.
    """
    with _connect(db_path) as conn:
        cur = conn.cursor()
        audit = cur.execute(
            "SELECT id, surviving_txn_id, merged_txn_id, reversible, "
            "reversed_at, notes FROM duplicate_merge_audit WHERE id = ?",
            (int(audit_id),),
        ).fetchone()
        if not audit:
            raise DuplicateMergeError(f"audit id {audit_id} does not exist")
        if audit["reversed_at"]:
            raise DuplicateMergeError(
                f"audit id {audit_id} was already reversed at {audit['reversed_at']}"
            )
        if not audit["reversible"]:
            raise DuplicateMergeError(
                f"audit id {audit_id} is marked non-reversible"
            )

        merged_id = audit["merged_txn_id"]
        merged_row = cur.execute(
            "SELECT COALESCE(status, 'active') AS status, merged_into_id "
            "FROM acct_transactions WHERE id = ?",
            (merged_id,),
        ).fetchone()
        if not merged_row:
            raise DuplicateMergeError(
                f"merged_txn_id {merged_id} no longer exists — cannot reverse"
            )

        try:
            cur.execute("BEGIN")
            cur.execute(
                "UPDATE acct_transactions "
                "SET status = 'active', merged_into_id = NULL, "
                "    updated_at = datetime('now') "
                "WHERE id = ?",
                (merged_id,),
            )
            extra_note = (
                f"reversed at {datetime.now().isoformat(timespec='seconds')} "
                f"by {reversed_by}; FK re-points (allocations / "
                f"reconciliation_matches / expense_transactions) were NOT "
                f"automatically restored — re-point manually if needed"
            )
            new_notes = (audit["notes"] + " ; " if audit["notes"] else "") + extra_note
            cur.execute(
                "UPDATE duplicate_merge_audit "
                "SET reversed_at = CURRENT_TIMESTAMP, notes = ? "
                "WHERE id = ?",
                (new_notes, int(audit_id)),
            )
            conn.commit()
        except Exception as e:
            try:
                conn.rollback()
            except Exception:
                pass
            raise DuplicateMergeError(f"reverse failed; rolled back: {e}") from e

        return {
            "audit_id": int(audit_id),
            "merged_txn_id": merged_id,
            "surviving_txn_id": audit["surviving_txn_id"],
            "fk_repoint_restored": False,
            "manual_cleanup_required": True,
        }


def get_duplicate_merge_audit(db_path=None, *, limit: int = 500) -> list[dict]:
    """Return audit rows (newest first), with the survivor + merged
    descriptions joined in for the audit UI."""
    with _connect(db_path) as conn:
        rows = conn.execute(
            f"""
            SELECT a.id, a.surviving_txn_id, a.merged_txn_id,
                   a.merge_reason, a.confidence_score,
                   a.merged_at, a.merged_by, a.notes,
                   a.reversible, a.reversed_at,
                   s.description AS surviving_description,
                   s.source_ref  AS surviving_source_ref,
                   COALESCE(s.amount, s.total_amount) AS surviving_amount,
                   m.description AS merged_description,
                   m.source_ref  AS merged_source_ref,
                   COALESCE(m.amount, m.total_amount) AS merged_amount,
                   COALESCE(m.status, 'active') AS merged_status
            FROM duplicate_merge_audit a
            LEFT JOIN acct_transactions s ON s.id = a.surviving_txn_id
            LEFT JOIN acct_transactions m ON m.id = a.merged_txn_id
            ORDER BY a.merged_at DESC, a.id DESC
            LIMIT {int(limit)}
            """
        ).fetchall()
        return [dict(r) for r in rows]
